const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 5":["מִצְוַת עֲשֵׂה לְקַדֵּשׁ כֹּהֵן הָעוֹבֵד יָדָיו וְרַגְלָיו וְאַחַר כָּךְ יַעֲבֹד שֶׁנֶּאֱמַר (שמות ל יט) \"וְרָחֲצוּ אַהֲרֹן וּבָנָיו מִמֶּנּוּ אֶת יְדֵיהֶם וְאֶת רַגְלֵיהֶם\". וְכֹהֵן שֶׁעָבַד וְלֹא קִדֵּשׁ יָדָיו וְרַגְלָיו שַׁחֲרִית חַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (שמות ל כ) \"יִרְחֲצוּ מַיִם וְלֹא יָמֻתוּ\". וַעֲבוֹדָתוֹ פְּסוּלָה בֵּין כֹּהֵן גָּדוֹל בֵּין כֹּהֵן הֶדְיוֹט:","וּמִנַּיִן שֶׁעֲבוֹדָתוֹ פְּסוּלָה שֶׁנֶּאֱמַר (שמות כח מג) \"חֻקַּת עוֹלָם לוֹ וּלְזַרְעוֹ\". וּבְבִגְדֵי כְּהֻנָּה הוּא אוֹמֵר חֻקַּת עוֹלָם. מָה מְחֻסַּר בְּגָדִים מְחַלֵּל עֲבוֹדָה כְּמוֹ שֶׁבֵּאַרְנוּ. אַף מִי שֶׁלֹּא רָחַץ יָדָיו וְרַגְלָיו מְחַלֵּל עֲבוֹדָה:","אֵין הַכֹּהֵן צָרִיךְ לְקַדֵּשׁ בֵּין כָּל עֲבוֹדָה וַעֲבוֹדָה. אֶלָּא פַּעַם אַחַת מְקַדֵּשׁ בַּבֹּקֶר וְעוֹבֵד וְהוֹלֵךְ כָּל הַיּוֹם כֻּלּוֹ וְכָל הַלַּיְלָה. וְהוּא שֶׁלֹּא יֵצֵא מִן הַמִּקְדָּשׁ וְלֹא יִישַׁן וְלֹא יָטִיל מַיִם וְלֹא יַסִּיחַ דַּעְתּוֹ. וְאִם עָשָׂה אֶחָד מֵאַרְבַּעְתָּן צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ:","יָצָא מִן הַמִּקְדָּשׁ וְחָזַר וְעָבַד וְלֹא קִדֵּשׁ אִם לֹא הִסִּיחַ דַּעְתּוֹ עֲבוֹדָתוֹ כְּשֵׁרָה. וְזֶה הַכְּלָל הָיָה בַּמִּקְדָּשׁ אֵין אָדָם נִכְנָס לָעֲזָרָה לַעֲבוֹדָה אַף עַל פִּי שֶׁהוּא טָהוֹר עַד שֶׁהוּא טוֹבֵל:","וְכָל הַמֵּסִיךְ אֶת רַגְלָיו טָעוּן טְבִילָה. וְכָל הַמֵּטִיל מַיִם טָעוּן קִדּוּשׁ יָדַיִם וְרַגְלַיִם. יָצָא חוּץ לְחוֹמַת הָעֲזָרָה אִם לִשְׁהוֹת בַּחוּץ יָצָא כְּשֶׁחוֹזֵר טָעוּן טְבִילָה וְאִם לַחְזֹר מִיָּד יָצָא] כְּשֶׁחוֹזֵר טָעוּן קִדּוּשׁ יָדַיִם וְרַגְלַיִם בִּלְבַד. וְאִם לֹא טָבַל וְלֹא קִדֵּשׁ וְעָבַד הוֹאִיל וְלֹא הִסִּיחַ דַּעְתּוֹ וְלֹא הִסִּיךְ רַגְלָיו וְלֹא הֵטִיל מַיִם עֲבוֹדָתוֹ כְּשֵׁרָה. הוֹצִיא יָדָיו חוּץ לְחוֹמַת הָעֲזָרָה אֵינוֹ צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ:","נִטְמְאוּ יָדָיו מַטְבִּילָן וְהֵן טְהוֹרוֹת. וְאֵינוֹ צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ. נִטְמָא גּוּפוֹ בַּאֲכִילַת אֳכָלִין טְמֵאִין אוֹ שְׁתִיַּת מַשְׁקִין טְמֵאִין וְטָבַל אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ הַעֲרֵב שֶׁמֶשׁ חוֹזֵר וּמְקַדֵּשׁ אַחַר טְבִילָה. שֶׁכָּל טוֹבֵל מְקַדֵּשׁ יָדָיו וְרַגְלָיו וְאַחַר כָּךְ עוֹבֵד. וְאִם לֹא קִדֵּשׁ הוֹאִיל וְלֹא הִסִּיחַ דַּעְתּוֹ לֹא חִלֵּל:","כֹּהֵן גָּדוֹל שֶׁלֹּא טָבַל וְלֹא קִדֵּשׁ יָדָיו וְרַגְלָיו בֵּין בְּגָדִים לִבְגָדִים וּבֵין עֲבוֹדָה לַעֲבוֹדָה בְּיוֹם הַכִּפּוּרִים וְעָבַד עֲבוֹדָתוֹ כְּשֵׁרָה. הוֹאִיל וְאוֹתָן הַטְּבִילוֹת וְהַקִּדּוּשִׁין אֵינָן שָׁוִים בְּאַהֲרֹן וּבָנָיו וְנֶאֱמַר (שמות ל יט) \"וְרָחֲצוּ אַהֲרֹן וּבָנָיו מִמֶּנּוּ\" דָּבָר הַשָּׁוֶה בְּכָל הַכֹּהֲנִים מְעַכֵּב שֶׁהוּא קִדּוּשׁ רִאשׁוֹן:","קִדֵּשׁ יָדָיו הַיּוֹם צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ לְמָחָר אַף עַל פִּי שֶׁלֹּא יָשַׁן כָּל הַלַּיְלָה. שֶׁהַיָּדַיִם נִפְסָלוֹת בְּלִינָה. קִדֵּשׁ בַּלַּיְלָה וְהִקְטִיר הַחֲלָבִים כָּל הַלַּיְלָה צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ בַּיּוֹם לַעֲבוֹדַת הַיּוֹם:","קִדֵּשׁ יָדָיו וְרַגְלָיו לִתְרוּמַת הַדֶּשֶׁן אַף עַל פִּי שֶׁהוּא מְקַדֵּשׁ קֹדֶם שֶׁתַּעֲלֶה הַשֶּׁמֶשׁ אֵינוֹ צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ אַחַר שֶׁהֵאִיר הַיּוֹם שֶׁהֲרֵי בִּתְחִלַּת עֲבוֹדָה קִדֵּשׁ:","מִצְוָה לְקַדֵּשׁ מִמֵּי הַכִּיּוֹר וְאִם קִדֵּשׁ מֵאֶחָד מִכְּלֵי הַשָּׁרֵת הֲרֵי זֶה כָּשֵׁר. אֲבָל כְּלֵי הַחל אֵינָם מְקַדְּשִׁין. קִדֵּשׁ בִּכְלִי שָׁרֵת בַּחוּץ אוֹ בִּכְלִי חֹל בִּפְנִים וְעָבַד עֲבוֹדָתוֹ פְּסוּלָה. וְאֵין מְקַדְּשִׁין בְּתוֹךְ הַכִּיּוֹר אוֹ בְּתוֹךְ כְּלֵי הַשָּׁרֵת אֶלָּא מֵהֶן שֶׁנֶּאֱמַר (שמות ל יט) \"וְרָחֲצוּ אַהֲרֹן וּבָנָיו מִמֶּנּוּ\" וְלֹא בְּתוֹכוֹ. וְאִם קִדֵּשׁ בְּתוֹכוֹ וְעָבַד לֹא חִלֵּל:","הִטְבִּיל יָדָיו וְרַגְלָיו בְּמֵי מִקְוֶה אֲפִלּוּ בְּמַעְיָן אֵין זֶה קִדּוּשׁ כְּלָל עַד שֶׁיִּרְחַץ בִּכְלִי. וּבְכָל כְּלֵי הַקֹּדֶשׁ מְקַדְּשִׁין בֵּין שֶׁיֵּשׁ בָּהֶן רְבִיעִית בֵּין שֶׁאֵין בָּהֶן רְבִיעִית:","כָּל הַמֵּימוֹת כְּשֵׁרִים לְקִדּוּשׁ בֵּין מַיִם חַיִּים בֵּין מֵי מִקְוֶה. וּבִלְבַד שֶׁלֹּא יִשְׁתַּנֶּה מַרְאֵיהֶן. אֶלָּא יִהְיוּ כַּמַּיִם הַכְּשֵׁרִים לִטְבִילָה. טִיט הַנָּרוֹק שֶׁהַפָּרָה שׁוֹחָה וְשׁוֹתָה מִמֶּנּוּ מַשְׁלִים לְמֵי כִּיּוֹר. זֶה הַכְּלָל כָּל הַמַּשְׁלִים לְמֵי מִקְוֶה מַשְׁלִים לְמֵי כִּיּוֹר:","כַּמָּה מַיִם צְרִיכִין לִהְיוֹת בַּכִּיּוֹר אֵין פָּחוֹת מִכְּדֵי לְקַדֵּשׁ מִמֶּנּוּ אַרְבָּעָה כֹּהֲנִים שֶׁנֶּאֱמַר (שמות ל יט) \"אַהֲרֹן וּבָנָיו\" וְהָיוּ אֶלְעָזָר וְאִיתָמָר וּפִינְחָס עִמָּהֶם הֲרֵי אַרְבָּעָה:","מֵי כִּיּוֹר נִפְסָלִין בְּלִינָה כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵיצַד הָיוּ עוֹשִׂין. מְשַׁקְּעִים אוֹתוֹ בְּמֵי מִקְוֶה אוֹ בְּמַעְיָן וּלְמָחָר מַעֲלִין אוֹתוֹ אוֹ מְמַלְּאִין אוֹתוֹ בְּכָל יוֹם בַּבֹּקֶר:","הַיָּם שֶׁעָשָׂה שְׁלֹמֹה כְּמִקְוֶה הָיָה. מִפְּנֵי שֶׁאַמָּה שֶׁל מַיִם הָיְתָה עוֹבֶרֶת בְּתוֹכוֹ מֵעֵין עֵיטָם. לְפִיכָךְ לֹא הָיוּ מֵימָיו נִפְסָלִין בְּלִינָה כְּמֵי הַכִּיּוֹר וּמִמֶּנּוּ הָיוּ מְמַלְּאִין הַכִּיּוֹר:","כֵּיצַד מִצְוַת קִדּוּשׁ. מַנִּיחַ יָדוֹ הַיְמָנִית עַל גַּבֵּי רַגְלוֹ הַיְמָנִית וְיָדוֹ הַשְּׂמָאלִית עַל גַּבֵּי רַגְלוֹ הַשְּׂמָאלִית וְשׁוֹחֶה וּמְקַדֵּשׁ. וְכָל הַחוֹצֵץ בִּטְבִילָה חוֹצֵץ בְּקִדּוּשׁ יָדַיִם. וְאֵינוֹ מְקַדֵּשׁ כְּשֶׁהוּא יוֹשֵׁב מִפְּנֵי שֶׁהוּא כַּעֲבוֹדָה. וְאֵין עֲבוֹדָה אֶלָּא מְעֻמָּד שֶׁנֶּאֱמַר (דברים יח ה) \"לַעֲמֹד לְשָׁרֵת\":","וְכָל הָעוֹבֵד וְהוּא יוֹשֵׁב חִלֵּל וַעֲבוֹדָתוֹ פְּסוּלָה וְאֵינוֹ לוֹקֶה. מִפְּנֵי שֶׁאַזְהָרָה שֶׁלּוֹ מִכְּלָל עֲשֵׂה הִיא. וְכֵן כָּל הָעוֹסֵק בַּעֲבוֹדָה מֵעֲבוֹדַת הַמִּקְדָּשׁ צָרִיךְ שֶׁיִּהְיֶה עוֹמֵד עַל הָרִצְפָּה. וְאִם הָיָה דָּבָר חוֹצֵץ בֵּינוֹ וּבֵין הַקַּרְקַע כְּגוֹן שֶׁעָמַד עַל גַּבֵּי כֵּלִים אוֹ בְּהֵמָה אוֹ עַל רַגְלֵי חֲבֵרוֹ פָּסַל. וְכֵן אִם הָיָה דָּבָר חוֹצֵץ בֵּין יָדוֹ וּבֵין הַכְּלִי שֶׁעוֹבֵד בּוֹ פָּסַל:","וְאֵין עֲבוֹדָה אֶלָּא בְּיָמִין. וְאִם עָבַד בִּשְׂמֹאל פְּסוּלָה וְאֵינוֹ לוֹקֶה. רַגְלוֹ אַחַת עַל הַכֶּלִי וְרַגְלוֹ אַחַת עַל הָרִצְפָּה [רַגְלוֹ אַחַת עַל הָאֶבֶן וְרַגְלוֹ אַחַת עַל הָרִצְפָּה] רוֹאִין כּל שֶׁאִלּוּ יִנָּטֵל הַכְּלִי אוֹ הָאֶבֶן יָכוֹל לַעֲמֹד עַל רַגְלוֹ אַחַת עֲבוֹדָתוֹ כְּשֵׁרָה. וְאִם לָאו עֲבוֹדָתוֹ פְּסוּלָה. קִבֵּל בְּיָמִין וּשְׂמֹאל מְסַיַּעְתּוֹ עֲבוֹדָתוֹ כְּשֵׁרָה. שֶׁהַמְסַיֵּעַ אֵין מַשְׁגִּיחִין עָלָיו:","נִתְנַדְּדָה אֶבֶן מֵאַבְנֵי הָעֲזָרָה לֹא יַעֲמֹד עָלֶיהָ בִּשְׁעַת עֲבוֹדָה עַד שֶׁתְּחֻבַּר בָּאָרֶץ. וְאִם עָבַד עֲבוֹדָתוֹ כְּשֵׁרָה הוֹאִיל וּבִמְקוֹמָהּ עוֹמֶדֶת:"],"Mishneh Torah, Agents and Partners 7":["הַנּוֹתֵן מָעוֹת לַחֲבֵרוֹ סְתָם לְהִתְעַסֵּק בָּהֶן אוֹ שֶׁהִתְנוּ בְּפֵרוּשׁ שֶׁיִּהְיֶה הַשָּׂכָר וְהַהֶפְסֵד בֵּינֵיהֶם בְּשָׁוֶה וְנֶאֱבַד הַמָּמוֹן יֵשׁ מִי שֶׁהוֹרָה שֶׁיְּשַׁלֵּם הַמִּתְעַסֵּק שְׁלִישׁ כְּמוֹ שֶׁבֵּאַרְנוּ אִם אָבַד מִקְצָת הַמָּמוֹן. וְיֵרָאֶה לִי שֶׁהוּא מְשַׁלֵּם מֶחֱצָה שֶׁהוּא בְּתוֹרַת מִלְוֶה וְזֶה שֶׁאָמְרוּ חֲכָמִים מְשַׁלֵּם שְׁלִישׁ בַּהֶפְסֵד בְּשֶׁלֹּא הִגִּיעַ הַהֶפְסֵד לִטֹּל בַּעַל הַמָּעוֹת פָּחוֹת מֵחֲצִי מָמוֹנוֹ. כֵּיצַד. רְאוּבֵן שֶׁנָּתַן לְשִׁמְעוֹן מֵאָה וְעֶשְׂרִים דִּינָר וְנָשָׂא וְנָתַן וּפָחַת תִּשְׁעִים הֲרֵי שִׁמְעוֹן מְשַׁלֵּם שְׁלֹשִׁים וְנִמְצָא רְאוּבֵן נוֹטֵל שִׁשִּׁים. אֲבָל פָּחַת שִׁמְעוֹן מֵאָה וַחֲמִשָּׁה אֵין אוֹמְרִים יַפְסִיד שִׁמְעוֹן חֲמִשָּׁה וּשְׁלֹשִׁים שֶׁאִם אַתָּה אוֹמֵר כֵּן נִמְצָא רְאוּבֵן נוֹטֵל חֲמִשִּׁים וּלְעוֹלָם לֹא יִטּל רְאוּבֵן פָּחוֹת מִשִּׁשִּׁים. לְפִיכָךְ שְׁטַר עֵסֶק הַיּוֹצֵא עַל הַיְתוֹמִים שֶׁהָיָה אֲבִיהֶן מִתְעַסֵּק בּוֹ נִשְׁבָּע בַּעַל הַשְּׁטָר וְגוֹבֶה מֶחֱצָה שֶׁהוּא בְּתוֹרַת מִלְוֶה אַף עַל פִּי שֶׁלְּעוֹלָם טוֹעֲנִין לַיּוֹרֵשׁ. הִנֵּה לָמַדְתָּ שֶׁאֵינוֹ נוֹטֵל לְעוֹלָם פָּחוֹת מִמֶּחֱצָה. וְלָמָּה אֲנִי אוֹמֵר שֶׁאֵין פּוֹחֲתִין לוֹ כָּאן כְּנֶגֶד שְׂכָרוֹ שֶׁנִּתְעַסֵּק בְּפִקָּדוֹן. שֶׁהֲרֵי אָבַד כָּל הַחֵצִי שֶׁל פִּקָּדוֹן וְלֹא נִשְׁאַר כָּאן פִּקָּדוֹן כְּלָל שֶׁנֹּאמַר אִם לֹא יִטּל שְׂכָרוֹ יֵרָאֶה כְּרִבִּית שֶׁהֲרֵי חֲצִי הַמִּלְוֶה בִּלְבַד נוֹטֵל. וְכֵן אִם הִתְנוּ שֶׁיִּטּל הַמִּתְעַסֵּק רְבִיעַ הַשָּׂכָר וְאָבַד הַמָּמוֹן כֻּלּוֹ מְשַׁלֵּם הָרְבִיעַ כֻּלּוֹ שֶׁהוּא בְּתוֹרַת מִלְוֶה אֲבָל אִם נִשְׁאַר מִן הַמָּמוֹן מְעַט כְּדֵי שֶׁאִם תוֹסִיף עַל אוֹתוֹ הַמְעַט שְׁתוּת הַהֶפְסֵד שֶׁפְּחָתוֹ יָבוֹא הַכּל רְבִיעַ הַמָּמוֹן אוֹ יֶתֶר הֲרֵי זֶה מְשַׁלֵּם שְׁתוּת בִּלְבַד מִן הַטַּעַם שֶׁכְּבָר בֵּאַרְנוּ:","הַמִּתְעַסֵּק שֶׁהִפְסִיד וְחָזַר וְטָרַח עַד שֶׁהִרְוִיחַ אֵינוֹ יָכוֹל לוֹמַר לְבַעַל הַמָּעוֹת בּוֹא וְנַחְשֹׁב הַהֶפְסֵד שֶׁהִפְסַדְנוּ תְּחִלָּה וְתַפְסִיד שְׁנֵי שְׁלִישִׁים וְנַחְשֹׁב הָרֶוַח שֶׁהִרְוַחְנוּ בָּאַחֲרוֹנָה וְתִטּל שְׁלִישׁ אֶלָּא מְחַשֵּׁב בָּאַחֲרוֹנָה בִּלְבַד עַל הָרֶוַח אוֹ עַל הַהֶפְסֵד וְאֵין לוֹ אֶלָּא בַּרֶוַח שֶׁהוֹסִיף עַל הַקֶּרֶן:","נָתַן לוֹ מָאתַיִם יְרִיעוֹת בְּמָאתַיִם דִּינָרִים בְּעֵסֶק וּכְתָבָן שְׁנֵי שְׁטָרוֹת מֵאָה בְּכָל שְׁטָר מְחַשֵּׁב לוֹ עַל כָּל שְׁטָר בִּפְנֵי עַצְמוֹ וּבַעַל הַמָּעוֹת הוּא שֶׁהִפְסִיד עַל עַצְמוֹ. נָתַן לוֹ מֵאָה יְרִיעוֹת בְּמֵאָה דִּינָרִים וְחָזַר וְנָתַן לוֹ בָּעֵסֶק אַחֵר מֵאָה חָבִיּוֹת שֶׁל יַיִן בְּמֵאָה דִּינָרִין וְכָתַב לוֹ שְׁטַר עֵסֶק בְּמָאתַיִם דִּינָרִין אֵינוֹ מְחַשֵּׁב לוֹ אֶלָּא בִּשְׁטָר אֶחָד, הוּא שֶׁהִפְסִיד עַל עַצְמוֹ. כֵּיצַד. שֶׁאִם מָכַר הַמֵּאָה יְרִיעוֹת בְּמֵאָה וּשְׁלֹשִׁים וְהַמֵּאָה הֶחָבִיּוֹת בְּשִׁבְעִים בַּעַל הַמָּעוֹת נוֹטֵל הַכּל מִפְּנֵי שֶׁעָשָׂה שְׁטָר אֶחָד הֲרֵי הַכּל מָאתַיִם וְלֹא הִרְוִיחַ כְּלוּם. אֲבָל אִלּוּ הִנִּיחָם שְׁנֵי עֲסָקִים כְּשֶׁהָיוּ הָיָה מַרְוִיחַ הַמִּתְעַסֵּק בְּחֶלְקוֹ בַּבְּגָדִים עֶשְׂרִים וּמַפְסִיד בְּחֶלְקוֹ בָּחָבִיּוֹת עֲשָׂרָה וְהָיָה נוֹטֵל עֲשָׂרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין הַמִּתְעַסֵּק יָכוֹל לַחֲלֹק הַמָּעוֹת שֶׁל עֵסֶק אוֹ סְחוֹרָה וְלוֹמַר אֶטּל אֶת הַחֵצִי שֶׁבְּתוֹרַת מִלְוֶה לְעַצְמִי וְאֶשָּׂא וְאֶתֵּן בּוֹ וְאַנִּיחַ הַחֵצִי שֶׁבְּתוֹרַת פִּקָּדוֹן בְּבֵית דִּין. שֶׁלֹּא נָתַן לוֹ מָמוֹן זֶה אֶלָּא לְהִתְעַסֵּק בְּכֻלּוֹ. וְאִם חָלַק וְעָשָׂה זֶה אֲפִלּוּ בְּבֵית דִּין הַגָּדוֹל לֹא עָשָׂה כְּלוּם אֶלָּא הַשָּׂכָר אוֹ הַהֶפְסֵד בֵּינֵיהֶן עַל אוֹתָן הַדְּרָכִים שֶׁבֵּאַרְנוּ:","הַמִּתְעַסֵּק שֶׁנָּתַן מַתָּנָה לַאֲחֵרִים מִן הַמִּטַּלְטְלִין שֶׁל עֵסֶק אוֹ מִמְּעוֹת הָעֵסֶק וְהֵבִיא בַּעַל הַמָּעוֹת רְאָיָה בְּרוּרָה שֶׁאֵלּוּ הַמְּטַלְטְלִין אוֹ הַמָּעוֹת מִשֶּׁל עֵסֶק הֵן מוֹצִיאִין אוֹתָן מִיָּדוֹ. וַאֲפִלּוּ שִׁנָּה הַמְקַבֵּל אוֹתָם וּמְכָרָם וּנְתָנָם מַתָּנָה לַאֲחֵרִים אוֹ הִפְסִיד חַיָּב לְשַׁלֵּם. וְהַכּל בִּרְאָיָה בְּרוּרָה. כְּבָר בֵּאַרְנוּ שֶׁהַמִּתְעַסֵּק שֶׁמֵּת נִשְׁבָּע בַּעַל הַמָּעוֹת וְגוֹבֶה מֶחֱצָה. וְאִם יֵשׁ שָׁם עֵדִים שֶׁהַמִּטַּלְטְלִין אֵלּוּ מִן הַמָּעוֹת שֶׁל עֵסֶק הֵם נוֹטֵל אוֹתָם בַּעַל הַמָּעוֹת בְּלֹא שְׁבוּעָה. וְאֵין בַּעַל חוֹב וְלֹא אִשָּׁה נוֹטְלִים מֵהֶם כְּלוּם אֶלָּא אִם כֵּן הָיָה בָּהֶם רֶוַח הֲרֵי חֵלֶק הָרֶוַח שֶׁל מֵת שֶׁל יוֹרְשָׁיו וְיִטּל בְּאוֹתוֹ חֵלֶק בַּעַל חוֹב וְהָאִשָּׁה:","הַנּוֹתֵן מָעוֹת לַחֲבֵרוֹ לִקַּח בָּהֶם פֵּרוֹת לְמַחֲצִית שָׂכָר וְלֹא לָקַח אֵין לוֹ עָלָיו אֶלָּא תַּרְעֹמֶת. וְאִם נוֹדַע בִּרְאָיָה בְּרוּרָה שֶׁלָּקַח וּמָכַר הֲרֵי זֶה מוֹצִיא מִמֶּנּוּ הַשָּׂכָר בְּעַל כָּרְחוֹ:","נָתַן לוֹ מָעוֹת לִקַּח בָּהֶן פֵּרוֹת לְמַחֲצִית שָׂכָר לוֹקֵחַ בָּהֶן מִכָּל מִין שֶׁיִּרְצֶה. וְלֹא יִקַּח לֹא כְּסוּת וְלֹא עֵצִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הַמּוֹשִׁיב אֶת חֲבֵרוֹ בַּחֲנוּת לְמַחֲצִית שָׂכָר אִם הָיָה אֻמָּן לֹא יַעֲסֹק בְּאֻמָּנוּתוֹ לְפִי שֶׁאֵין עֵינָיו עַל הַחֲנוּת בְּשָׁעָה שֶׁעוֹסֵק בְּאֻמָּנוּתוֹ. וְאִם הָיָה שֻׁתָּף עִמּוֹ בֶּחָצֵר מֻתָּר. וְלֹא יִהְיֶה לוֹקֵחַ וּמוֹכֵר דְּבָרִים אֲחֵרִים וְאִם לָקַח וּמָכַר הַשָּׂכָר לָאֶמְצַע:"],"Mishneh Torah, Blessings 10":["בְרָכוֹת אֲחֵרוֹת וּדְבָרים אֲחֵרִים הַרְבֵּה שֶׁאֵין בָּהֶן פְּתִיחָה וְלֹא חֲתִימָה תִּקְּנוּ חֲכָמִים דֶּרֶךְ שֶׁבַח וְהוֹדָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא. כְּמוֹ בִּרְכוֹת הַתְּפִלָּה שֶׁכְּבָר כְּתַבְנוּם. וְאֵלּוּ הֵן. הַבּוֹנֶה בַּיִת חָדָשׁ וְהַקּוֹנֶה כֵּלִים חֳדָשִׁים בֵּין יֵשׁ לוֹ כַּיּוֹצֵא בָּהֶן בֵּין אֵין לוֹ מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהֶחֱיָנוּ וְקִיְּמָנוּ וְהִגִּיעָנוּ לַזְּמַן הַזֶּה:","וְכֵן הָרוֹאֶה אֶת חֲבֵרוֹ לְאַחַר שְׁלֹשִׁים יוֹם מְבָרֵךְ שֶׁהֶחֱיָנוּ. וְאִם רָאָהוּ לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ מְחַיֵּה הַמֵּתִים. הָרוֹאֶה פְּרִי הַמִּתְחַדֵּשׁ מִשָּׁנָה לְשָׁנָה בִּתְחִלַּת רְאִיָּתוֹ מְבָרֵךְ שֶׁהֶחֱיָנוּ:","שָׁמַע שְׁמוּעָה טוֹבָה מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַטּוֹב וְהַמֵּטִיב. שָׁמַע שְׁמוּעָה רָעָה מְבָרֵךְ בָּרוּךְ דַּיַּן הָאֱמֶת. וְחַיָּב אָדָם לְבָרֵךְ עַל הָרָעָה בְּטוּב נֶפֶשׁ כְּדֶרֶךְ שֶׁמְּבָרֵךְ עַל הַטּוֹבָה בְּשִׂמְחָה שֶׁנֶּאֱמַר (דברים ו ה) ״וְאָהַבְתָּ אֵת יְיָ׳‎ אֱלֹהֶיךָ״ וְגוֹ׳‎ (דברים ו ה) ״וּבְכָל מְאֹדֶךָ״. וּבִכְלַל אַהֲבָה הַיְתֵרָה שֶׁנִּצְטַוֵּינוּ בָּהּ שֶׁאֲפִלּוּ בְּעֵת שֶׁיָּצֵר לוֹ יוֹדֶה וִישַׁבֵּחַ בְּשִׂמְחָה:","הִגִּיעָה אֵלָיו טוֹבָה אוֹ שֶׁשָּׁמַע שְׁמוּעָה טוֹבָה אַף עַל פִּי שֶׁהַדְּבָרִים מַרְאִין שֶׁטּוֹבָה זוֹ תִּגְרֹם לוֹ רָעָה מְבָרֵךְ הַטּוֹב וְהַמֵּטִיב. וְכֵן אִם נָגְעָה אֵלָיו רָעָה אוֹ שָׁמַע שְׁמוּעָה רָעָה אַף עַל פִּי שֶׁהַדְּבָרִים מַרְאִים שֶׁרָעָה זוֹ גּוֹרֶמֶת לוֹ טוֹבָה מְבָרֵךְ דַּיַּן הָאֱמֶת. שֶׁאֵין מְבָרְכִין עַל הֶעָתִיד לִהְיוֹת אֶלָּא עַל מַה שֶּׁאֵרַע עַתָּה:","יָרְדוּ גְּשָׁמִים רַבִּים. אִם יֵשׁ לוֹ שָׂדֶה מְבָרֵךְ שֶׁהֶחֱיָנוּ. וְאִם הָיְתָה שֶׁלּוֹ וְשֶׁל אֲחֵרִים מְבָרֵךְ הַטּוֹב וְהַמֵּטִיב. וְאִם אֵין לוֹ שָׂדֶה מְבָרֵךְ מוֹדִים אֲנַחְנוּ לָךְ יְיָ׳‎ אֱלֹהֵינוּ עַל כָּל טִפָּה וְטִפָּה שֶׁהוֹרַדְתָּ לָנוּ וְאִלּוּ פִינוּ מָלֵא כוּ׳‎ עַד הֵן הֵם יוֹדוּ וִישַׁבְּחוּ וִיבָרְכוּ אֶת שִׁמְךָ מַלְכֵּנוּ בָּרוּךְ אַתָּה יְיָ׳‎ אֵל רֹב הַהוֹדָאוֹת וְהַתִּשְׁבָּחוֹת:","מֵאֵימָתַי מְבָרְכִין עַל הַגְּשָׁמִים מִשֶּׁיִּרְבֶּה הַמַּיִם עַל הָאָרֶץ וְיַעֲלוּ אֲבַעְבּוּעוֹת מִן הַמָּטָר עַל פְּנֵי הַמַּיִם וְיֵלְכוּ הָאֲבַעְבּוּעוֹת זֶה לִקְרַאת זֶה:","אָמְרוּ לוֹ מֵת אָבִיו וִירָשָׁהוּ. אִם יֵשׁ עִמּוֹ אַחִין מְבָרֵךְ בַּתְּחִלָּה דַּיַּן הָאֱמֶת וְאַחַר כָּךְ הַטּוֹב וְהַמֵּטִיב. וְאִם אֵין עִמּוֹ אַחִים מְבָרֵךְ שֶׁהֶחֱיָנוּ. קְצָרוֹ שֶׁל דָּבָר כָּל דְּבַר טוֹבָה שֶׁהִיא לוֹ וְלַאֲחֵרִים מְבָרֵךְ הַטּוֹב וְהַמֵּטִיב. וְטוֹבָה שֶׁהִיא לוֹ לְבַדּוֹ מְבָרֵךְ שֶׁהֶחֱיָנוּ:","אַרְבָּעָה צְרִיכִין לְהוֹדוֹת. חוֹלֶה שֶׁנִּתְרַפֵּא. וְחָבוּשׁ שֶׁיָּצָא מִבֵּית הָאֲסוּרִים. וְיוֹרְדֵי הַיָּם כְּשֶׁעָלוּ. וְהוֹלְכֵי דְּרָכִים כְּשֶׁיַּגִּיעוּ לַיִּשּׁוּב. וּצְרִיכִין לְהוֹדוֹת בִּפְנֵי עֲשָׂרָה וּשְׁנַיִם מֵהֶם חֲכָמִים שֶׁנֶּאֱמַר (תהילים קז לב) ״וִירֹמְמוּהוּ בִּקְהַל עָם וּבְמוֹשַׁב זְקֵנִים יְהַלְלוּהוּ״. וְכֵיצַד מוֹדֶה וְכֵיצַד מְבָרֵךְ. עוֹמֵד בֵּינֵיהֶן וּמְבָרֵךְ. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַגּוֹמֵל לְחַיָּבִים טוֹבוֹת שֶׁגְּמָלַנִי כָּל טוֹב. וְכָל הַשּׁוֹמְעִין אוֹמְרִים שֶׁגְּמָלְךָ טוֹב הוּא יִגְמָלְךָ סֶלָה:","הָרוֹאֶה מָקוֹם שֶׁנַּעֲשׂוּ נִסִּים לְיִשְׂרָאֵל כְּגוֹן יַם סוּף וּמַעְבְּרוֹת הַיַּרְדֵּן אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה נִסִּים לַאֲבוֹתֵינוּ בַּמָּקוֹם הַזֶּה. וְכֵן כָּל מָקוֹם שֶׁנַּעֲשׂוּ בּוֹ נִסִּים לָרַבִּים. אֲבָל מָקוֹם שֶׁנַּעֲשָׂה בּוֹ נֵס לַיָּחִיד אוֹתוֹ הַיָּחִיד וּבְנוֹ וּבֶן בְּנוֹ מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה לִי נֵס בַּמָּקוֹם הַזֶּה אוֹ שֶׁעָשָׂה נֵס לַאֲבוֹתַי בַּמָּקוֹם הַזֶּה. הָרוֹאֶה גֹּב אֲרָיוֹת וְכִבְשַׁן הָאֵשׁ שֶׁהֻשְׁלַךְ בּוֹ חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה נֵס לַצַּדִּיקִים בַּמָּקוֹם הַזֶּה. הָרוֹאֶה מָקוֹם שֶׁעוֹבְדִין בּוֹ עַכּוּ״ם מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁנָּתַן אֶרֶךְ אַפַּיִם לְעוֹבְרֵי רְצוֹנוֹ. מָקוֹם שֶׁנֶּעֶקְרָה מִמֶּנּוּ עַכּוּ״ם אִם בְּאֶרֶץ יִשְׂרָאֵל הוּא מְבָרֵךְ שֶׁעָקַר עַכּוּ״ם מֵאַרְצֵנוּ. וְאִם בְּחוּץ לָאָרֶץ הוּא מְבָרֵךְ שֶׁעָקַר עַכּוּ״ם מִמָּקוֹם הַזֶּה. וְאוֹמֵר בִּשְׁתֵּיהֶן כְּשֵׁם שֶׁעָקַרְתָּ מִמָּקוֹם זֶה כָּךְ תַּעֲקֹר מִכָּל מְקוֹמוֹת וְתָשִׁיב לֵב עוֹבְדֵיהֶם לְעָבְדְךָ:","הָרוֹאֶה בָּתֵּי יִשְׂרָאֵל בְּיִשּׁוּבָן מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם מַצִּיב גְּבוּל אַלְמָנָה. בְּחֻרְבָּנָן אוֹמֵר בָּרוּךְ דַּיַּן הָאֱמֶת. הָרוֹאֶה קִבְרֵי יִשְׂרָאֵל מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר יָצַר אֶתְכֶם בַּדִּין וְדָן אֶתְכֶם בַּדִּין וְכִלְכֵּל אֶתְכֶם בְּדִין וְהֵמִית אֶתְכֶם בַּדִּין וְהוּא עָתִיד לְהָקִים אֶתְכֶם בַּדִּין לְחַיֵּי הָעוֹלָם הַבָּא בָּרוּךְ אַתָּה יְיָ׳‎ מְחַיֵּה הַמֵּתִים:","הָרוֹאֶה שֵׁשׁ מֵאוֹת אֶלֶף אָדָם כְּאֶחָד. אִם עַכּוּ״ם הֵם אוֹמֵר (ירמיה נ יב) ״בּוֹשָׁה אִמְּכֶם מְאֹד חָפְרָה יוֹלַדְתְּכֶם הִנֵּה אַחֲרִית גּוֹיִם מִדְבָּר צִיָּה וַעֲרָבָה״. וְאִם יִשְׂרָאֵל הֵם וּבְאֶרֶץ יִשְׂרָאֵל אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם חֲכַם הָרָזִים. הָרוֹאֶה מֵחַכְמֵי אֻמּוֹת הָעוֹלָם אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם. חַכְמֵי יִשְׂרָאֵל מְבָרֵךְ שֶׁנָּתַן מֵחָכְמָתוֹ לִירֵאָיו. מַלְכֵי יִשְׂרָאֵל אוֹמֵר שֶׁנָּתַן מִכְּבוֹדוֹ וּמִגְּבוּרָתוֹ לִירֵאָיו. מַלְכֵי אֻמּוֹת הָעוֹלָם מְבָרֵךְ שֶׁנָּתַן מִכְּבוֹדוֹ לְבָשָׂר וָדָם:","הָרוֹאֶה אֶת הַכּוּשִׁי וְאֶת הַמְשֻׁנִּין בְּצוּרַת פְּנֵיהֶן אוֹ בְּאֵיבְרֵיהֶם מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם מְשַׁנֶּה אֶת הַבְּרִיּוֹת. הָרוֹאֶה סוּמָא אוֹ קִטֵּעַ וּמֻכֶּה שְׁחִין וּבוֹהֲקָנִין וְכַיּוֹצֵא בָּהֶן מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם דַּיַּן הָאֱמֶת. וְאִם נוֹלְדוּ כֵּן מִמְּעֵי אִמָּן מְבָרֵךְ מְשַׁנֶּה אֶת הַבְּרִיּוֹת. הָרוֹאֶה אֶת הַפִּיל וְאֶת הַקּוֹף וְאֶת הַקִּיפוֹף אוֹמֵר בָּרוּךְ מְשַׁנֶּה אֶת הַבְּרִיּוֹת:","הָרוֹאֶה בְּרִיּוֹת נָאוֹת וּמְתֻקָּנוֹת בְּיוֹתֵר וְאִילָנוֹת טוֹבוֹת מְבָרֵךְ שֶׁכָּכָה לוֹ בְּעוֹלָמוֹ. הַיּוֹצֵא לַשָּׂדוֹת אוֹ לַגִּנּוֹת בְּיוֹמֵי נִיסָן וְרָאָה אִילָנוֹת פּוֹרְחוֹת וְנִצָּנִים עוֹלִים מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁלֹּא חִסַּר בְּעוֹלָמוֹ כְּלוּם וּבָרָא בּוֹ בְּרִיּוֹת טוֹבוֹת וְאִילָנוֹת טוֹבוֹת וְנָאוֹת כְּדֵי לֵהָנוֹת בָּהֶן בְּנֵי אָדָם:","עַל הָרוּחוֹת שֶׁנָּשְׁבוּ בְּזַעַף וְעַל הַבְּרָקִים וְעַל הָרְעָמִים וְעַל קוֹל הַהֲבָרָה שֶׁתִּשָּׁמַע בָּאָרֶץ כְּמוֹ רֵיחַיִם גְּדוֹלִים וְעַל הָאוּר שֶׁבַּאֲוִיר שֶׁיֵּרָאוּ כְּאִלּוּ הֵם כּוֹכָבִים נוֹפְלִים וְרָצִים מִמָּקוֹם לְמָקוֹם אוֹ כְּמוֹ כּוֹכָבִים שֶׁיֵּשׁ לָהֶם זָנָב עַל כָּל אֶחָד מֵאֵלּוּ מְבָרֵךְ בָּרוּךְ שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם. וְאִם רָצָה מְבָרֵךְ עוֹשֶׂה בְּרֵאשִׁית:","עַל הֶהָרִים וְעַל הַגְּבָעוֹת עַל הַיַּמִּים וְעַל הַמִּדְבָּרוֹת וְעַל הַנְּהָרוֹת אִם רָאָה אַחַת מֵהֶן מִשְּׁלֹשִׁים יוֹם לִשְׁלֹשִׁים יוֹם מְבָרֵךְ עוֹשֶׂה בְּרֵאשִׁית. הָרוֹאֶה אֶת הַיָּם הַגָּדוֹל מִשְּׁלֹשִׁים יוֹם לִשְׁלֹשִׁים יוֹם אוֹ יוֹתֵר מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל:","הָרוֹאֶה קֶשֶׁת בֶּעָנָן מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם זוֹכֵר הַבְּרִית וְנֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ. הָרוֹאֶה לְבָנָה בְּחִדּוּשָׁהּ מְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בְּמַאֲמָרוֹ בָּרָא שְׁחָקִים וּבְרוּחַ פִּיו כָּל צְבָאָם חֹק וּזְמַן נָתַן לָהֶם שֶׁלֹּא יְשַׁנּוּ אֶת תַּפְקִידָם שָׂשִׂים וּשְׂמֵחִים לַעֲשׂוֹת רְצוֹן קוֹנֵיהֶם פּוֹעֲלֵי אֱמֶת וּפְעֻלָּתָם צֶדֶק וְלַלְּבָנָה אָמַר שֶׁתִּתְחַדֵּשׁ עֲטָרָה תִּפְאֶרֶת לַעֲמוּסֵי בָטֶן שֶׁהֵם עֲתִידִין לְהִתְחַדֵּשׁ כְּמוֹתָהּ וּלְפָאֵר לְיוֹצְרָם עַל כְּבוֹד מַלְכוּתוֹ וְעַל כָּל מַה שֶּׁבָּרָא בָּרוּךְ אַתָּה יְיָ׳‎ מְחַדֵּשׁ הֶחֳדָשִׁים:","וְצָרִיךְ לְבָרֵךְ בְּרָכָה זוֹ מְעֻמָּד. שֶׁכָּל הַמְבָרֵךְ עַל הַחֹדֶשׁ בִּזְמַנּוֹ כְּאִלּוּ הִקְבִּיל פְּנֵי הַשְּׁכִינָה. אִם לֹא בֵּרֵךְ עָלֶיהָ בַּלַּיִל הָרִאשׁוֹן מְבָרֵךְ עָלֶיהָ עַד שִׁשָּׁה עָשָׂר יוֹם בַּחֹדֶשׁ עַד שֶׁתִּמָּלֵא פְּגִימָתָהּ:","הָרוֹאֶה אֶת הַחַמָּה בְּיוֹם תְּקוּפַת נִיסָן שֶׁל תְּחִלַּת הַמַּחֲזוֹר שֶׁל שְׁמוֹנֶה וְעֶשְׂרִים שָׁנָה שֶׁהַתְּקוּפָה בִּתְחִלַּת לֵיל רְבִיעִי כְּשֶׁרוֹאֶה אוֹתָהּ בְּיוֹם רְבִיעִי בַּבֹּקֶר מְבָרֵךְ בָּרוּךְ עוֹשֶׂה בְּרֵאשִׁית. וְכֵן כְּשֶׁתַּחֲזֹר הַלְּבָנָה לִתְחִלַּת מַזַּל טָלֶה בִּתְחִלַּת הַחֹדֶשׁ וְלֹא תִּהְיֶה נוֹטָה לֹא לְצָפוֹן וְלֹא לְדָרוֹם. וְכֵן כְּשֶׁיַּחֲזֹר כָּל כּוֹכָב וְכוֹכָב מֵחֲמֵשֶׁת הַכּוֹכָבִים הַנִּשְׁאָרִים לִתְחִלַּת מַזַּל טָלֶה וְלֹא יִהְיֶה נוֹטֶה לֹא לְצָפוֹן וְלֹא לְדָרוֹם. וְכֵן בְּכָל עֵת שֶׁיִּרְאֶה מַזַּל טָלֶה עוֹלֶה מִקְּצֵה הַמִּזְרָח עַל כָּל אֶחָד מֵאֵלּוּ מְבָרֵךְ עוֹשֶׂה בְּרֵאשִׁית:","הָרוֹאֶה בָּתֵּי עַכּוּ״ם בְּיִשּׁוּבָן אוֹמֵר (משלי טו כה) ״בֵּית גֵּאִים יִסַּח יְיָ׳‎״. בְּחֻרְבָּנָן אוֹמֵר (תהילים צד א) ״אֵל נְקָמוֹת יְיָ׳‎ אֵל נְקָמוֹת הוֹפִיעַ״. רָאָה קִבְרֵי עַכּוּ״ם אוֹמֵר (ירמיה נ יב) ״בּוֹשָׁה אִמְּכֶם מְאֹד״ וְגוֹ׳‎:","הַנִּכְנָס לַמֶּרְחָץ אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁתַּכְנִיסֵנִי לְשָׁלוֹם וְתוֹצִיאֵנִי לְשָׁלוֹם וְתַצִּילֵנִי מִזֶּה וּמִכַּיּוֹצֵא בָּזֶה לֶעָתִיד לָבוֹא. וּכְשֶׁיֵּצֵא מִן הַמֶּרְחָץ אוֹמֵר מוֹדֶה אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁהִצַּלְתַּנִי מִן הָאוּר וְכוּ׳‎:","הַנִּכְנָס לְהַקִּיז דָּם אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁיְּהֵא עֵסֶק זֶה לִי לִרְפוּאָה כִּי רוֹפֵא חִנָּם אָתָּה. וּכְשֶׁיֵּצֵא אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ רוֹפֵא חוֹלִים:","הַהוֹלֵךְ לָמֹד גָּרְנוֹ אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁתִּשְׁלַח בְּרָכָה בְּמַעֲשֵׂה יָדַי. הִתְחִיל לָמֹד אוֹמֵר בָּרוּךְ הַשּׁוֹלֵחַ בְּרָכָה בִּכְרִי זֶה. מָדַד וְאַחַר כָּךְ בִּקֵּשׁ רַחֲמִים הֲרֵי זוֹ תְּפִלַּת שָׁוְא. וְכָל הַצּוֹעֵק לְשֶׁעָבַר הֲרֵי זוֹ תְּפִלַּת שָׁוְא:","הַנִּכְנָס לְבֵית הַמִּדְרָשׁ אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁלֹּא אֶכָּשֵׁל בִּדְבַר הֲלָכָה שֶׁלֹּא אֹמַר עַל טָהוֹר טָמֵא וְעַל טָמֵא טָהוֹר וְלֹא עַל מֻתָּר אָסוּר וְלֹא עַל אָסוּר מֻתָּר וְלֹא אֶכָּשֵׁל בִּדְבַר הֲלָכָה וְיִשְׂמְחוּ בִּי חֲבֵרַי וְאַל יִכָּשְׁלוּ חֲבֵרַי וְאֶשְׂמַח בָּהֶם:","וּבִיצִיאָתוֹ מִבֵּית הַמִּדְרָשׁ אוֹמֵר מוֹדֶה אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁשַּׂמְתָּ חֶלְקִי מִיּוֹשְׁבֵי בֵּית הַמִּדְרָשׁ וְלֹא שַׂמְתָּ חֶלְקִי מִיּוֹשְׁבֵי קְרָנוֹת שֶׁאֲנִי מַשְׁכִּים וְהֵם מַשְׁכִּימִים אֲנִי מַשְׁכִּים לְדִבְרֵי תּוֹרָה וְהֵם מַשְׁכִּימִים לִדְבָרִים בְּטֵלִים אֲנִי עָמֵל וְהֵם עֲמֵלִין אֲנִי עָמֵל לְדִבְרֵי תּוֹרָה וּמְקַבֵּל שָׂכָר וְהֵם עֲמֵלִין וְאֵין מְקַבְּלִין שָׂכָר אֲנִי רָץ וְהֵם רָצִים אֲנִי רָץ לְחַיֵּי הָעוֹלָם הַבָּא וְהֵם רָצִים לִבְאֵר שַׁחַת:","הַנִּכְנָס לִכְרַךְ אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁתַּכְנִיסֵנִי לִכְרַךְ זֶה לְשָׁלוֹם. וְאִם נִכְנַס בְּשָׁלוֹם אוֹמֵר מוֹדֶה אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁהִכְנַסְתַּנִי לְשָׁלוֹם. וּכְשֶׁיְּבַקֵּשׁ לָצֵאת אוֹמֵר יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁתּוֹצִיאֵנִי מִכְּרַךְ זֶה לְשָׁלוֹם. וְאִם יָצָא בְּשָׁלוֹם אוֹמֵר מוֹדֶה אֲנִי לְפָנֶיךָ יְיָ׳‎ אֱלֹהַי שֶׁהוֹצֵאתַנִי מִכְּרַךְ זֶה לְשָׁלוֹם וּכְשֵׁם שֶׁהוֹצֵאתַנִי לְשָׁלוֹם כָּךְ תּוֹלִיכֵנִי לְשָׁלוֹם וְתַצְעִידֵנִי לְשָׁלוֹם וְתִסְמְכֵנִי לְשָׁלוֹם וְתַצִּילֵנִי מִכַּף אוֹיֵב וְאוֹרֵב בַּדֶּרֶךְ:","כְּלָלוֹ שֶׁל דָּבָר לְעוֹלָם יִצְעַק אָדָם עַל הֶעָתִיד לָבוֹא וִיבַקֵּשׁ רַחֲמִים וְיִתֵּן הוֹדָיָה עַל מַה שֶּׁעָבַר וְיוֹדֶה וִישַׁבֵּחַ כְּפִי כֹּחוֹ. וְכָל הַמַּרְבֶּה לְהוֹדוֹת אֶת יְיָ׳‎ וּלְשַׁבְּחוֹ תָּמִיד הֲרֵי זֶה מְשֻׁבָּח:"],"Mishneh Torah, Borrowing and Deposit 3":["הַשׁוֹאֵל אֶת הַפָּרָה מֵחֲבֵרוֹ וּשְׁלָחָהּ לוֹ הַמַּשְׁאִיל בְּיַד בְּנוֹ אוֹ בְּיַד שְׁלוּחוֹ אוֹ בְּיַד עַבְדּוֹ. אֲפִלּוּ שְׁלָחָהּ לוֹ בְּיַד בְּנוֹ אוֹ בְּיַד עַבְדּוֹ אוֹ בְּיַד שְׁלוּחוֹ שֶׁל שׁוֹאֵל וּמֵתָה קֹדֶם שֶׁתִּכָּנֵס לִרְשׁוּת הַשּׁוֹאֵל הֲרֵי זֶה פָּטוּר. וְאִם אָמַר לוֹ הַשּׁוֹאֵל שַׁלְּחָהּ לִי בְּיַד בְּנִי בְּיַד עַבְדִּי בְּיַד שְׁלוּחִי אוֹ בְּיַד עַבְדְּךָ הָעִבְרִי אוֹ בְּיַד שְׁלוּחֲךָ. אוֹ שֶׁאָמַר לוֹ הַמַּשְׁאִיל הֲרֵינִי מְשַׁלְּחָהּ בְּיַד בִּנְךָ בְּיַד עַבְדְּךָ בְּיַד שְׁלוּחֲךָ בְּיַד בְּנִי בְּיַד עַבְדִּי הָעִבְרִי בְּיַד שְׁלוּחִי. וְאָמַר לוֹ הַשּׁוֹאֵל שְׁלַח וּשְׁלָחָהּ וּמֵתָה בַּדֶּרֶךְ הֲרֵי זֶה חַיָּב. שְׁלָחָהּ לוֹ הַמַּשְׁאִיל בְּיַד עַבְדּוֹ הַכְּנַעֲנִי אַף עַל פִּי שֶׁאָמַר לוֹ הַשּׁוֹאֵל שְׁלַח וּמֵתָה פָּטוּר מִפְּנֵי שֶׁיָּדוֹ כְּיַד רַבּוֹ וַעֲדַיִן לֹא יָצְאָה מֵרְשׁוּת הַמַּשְׁאִיל:","אָמַר לוֹ הַשּׁוֹאֵל הַכִּישָׁהּ בְּמַקֵּל וְהִיא תָּבוֹא מֵאֵלֶיהָ וְעָשָׂה הַמַּשְׁאִיל כָּךְ אֵין הַשּׁוֹאֵל חַיָּב בָּהּ עַד שֶׁתִּכָּנֵס לִרְשׁוּתוֹ. אֲבָל מֵתָה בַּדֶּרֶךְ פָּטוּר. וְכֵן בְּשָׁעָה שֶׁמַּחְזִירָהּ הַשּׁוֹאֵל לַבְּעָלִים אִם שְׁלָחָהּ בְּיַד אַחֵר וּמֵתָה קֹדֶם שֶׁתַּגִּיעַ לִרְשׁוּת הַמַּשְׁאִיל הֲרֵי זֶה חַיָּב שֶׁעֲדַיִן הִיא בְּאַחֲרָיוּת הַשּׁוֹאֵל. וְאִם שְׁלָחָהּ מִדַּעַת הַמַּשְׁאִיל עַל יְדֵי אַחֵר וּמֵתָה פָּטוּר. שְׁלָחָהּ בְּיַד עַבְדּוֹ הַכְּנַעֲנִי אַף עַל פִּי שֶׁאָמַר לוֹ הַמַּשְׁאִיל שְׁלַח אִם מֵתָה בַּדֶּרֶךְ חַיָּב שֶׁיַּד הָעֶבֶד כְּיַד רַבּוֹ וַעֲדַיִן לֹא יָצָאת מִיַּד הַשּׁוֹאֵל. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהֶחְזִירָהּ בְּתוֹךְ יְמֵי שְׁאִילָתָהּ. אֲבָל אִם הֶחֱזִירָהּ אַחַר יְמֵי שְׁאִילָתָהּ הֲרֵי זֶה פָּטוּר אִם מֵתָה בַּדֶּרֶךְ שֶׁאַחַר יְמֵי שְׁאֵלָתָהּ יָצָאתָ מִדִּין שְׁאֵלָה וַהֲרֵי הוּא כְּשׁוֹמֵר שָׂכָר. לְפִיכָךְ אִם נִשְׁבֵּית אוֹ מֵתָה אַחֲרֵי יְמֵי שְׁאִילָתָהּ פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשּׁוֹאֵל פָּרָה מֵחֲבֵרוֹ. שְׁאָלָהּ חֲצִי הַיּוֹם וּשְׂכָרָהּ חֲצִי הַיּוֹם. שְׁאָלָהּ הַיּוֹם וּשְׂכָרָהּ לְמָחָר. שָׁאַל אַחַת וְשָׂכַר אַחַת וּמֵתָה אַחַת מֵהֶן. הַמַּשְׁאִיל אוֹמֵר שְׁאוּלָה מֵתָה בַּיּוֹם שֶׁהָיְתָה שְׁאוּלָה מֵתָה בַּשָּׁעָה שֶׁהָיְתָה שְׁאוּלָה מֵתָה וְהַשּׁוֹמֵר אוֹמֵר אֵינִי יוֹדֵעַ. אוֹ שֶׁאָמַר הַשּׁוֹאֵל שְׂכוּרָה מֵתָה בַּיּוֹם שֶׁהָיְתָה שְׂכוּרָה מֵתָה בַּשָּׁעָה שֶׁהָיְתָה שְׂכוּרָה מֵתָה. וְהַמַּשְׁאִיל אוֹמֵר אֵינִי יוֹדֵעַ אוֹ שֶׁאָמַר זֶה אֵינִי יוֹדֵעַ וְזֶה אוֹמֵר אֵינִי יוֹדֵעַ. הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. לֹא הָיְתָה שָׁם רְאָיָה יִשָּׁבַע הַשּׂוֹכֵר עַל הַשְּׂכוּרָה שֶׁמֵּתָה אוֹ שֶׁאֵינוֹ יוֹדֵעַ וְיִפָּטֵר. זֶה אוֹמֵר שְׁאוּלָה וְזֶה אוֹמֵר שְׂכוּרָה יִשָּׁבַע הַשּׁוֹמֵר עַל הַשְּׂכוּרָה שֶׁמֵּתָה כְּדַרְכָּהּ כְּמוֹ שֶׁטָּעַן וִיגַלְגֵּל עָלָיו שֶׁהַשְּׂכוּרָה הִיא שֶׁמֵּתָה:","הִשְׁאִילוֹ שְׁתֵּי פָּרוֹת חֲצִי הַיּוֹם בִּשְׁאֵלָה וַחֲצִי הַיּוֹם בִּשְׂכִירוּת. הַמַּשְׁאִיל אוֹמֵר בִּזְמַן הַשְּׁאֵלָה מֵתָה וְהַלָּה אוֹמֵר אַחַת מֵתָה בִּזְמַן הַשְּׁאֵלָה וְהָאַחֶרֶת אֵינִי יוֹדֵעַ. מִתּוֹךְ שֶׁאֵינוֹ יָכוֹל לִשָּׁבַע יְשַׁלֵּם הַשְּׁתַּיִם. וְכֵן אִם מָסַר לוֹ שָׁלֹשׁ פָּרוֹת שְׁתַּיִם שְׁאוּלוֹת וְאַחַת שְׂכוּרָה. הַמַּשְׁאִיל אוֹמֵר שְׁתַּיִם הַשְּׁאוּלוֹת הֵן שֶׁמֵּתוּ וְהַשּׁוֹאֵל אוֹמֵר אַחַת הַשְּׁאוּלָה מֵתָה וַדַּאי אֲבָל הַשְּׁנִיָּה שֶׁמֵּתָה אֵינִי יוֹדֵעַ אִם הַשְּׁאוּלָה הָאַחֶרֶת אוֹ הַשְּׂכוּרָה. מִתּוֹךְ שֶׁאֵינוֹ יָכוֹל לִשָּׁבַע שֶׁהֲרֵי אוֹמֵר אֵינִי יוֹדֵעַ יְשַׁלֵּם הַשְּׁתַּיִם. וּבְהִלְכוֹת טוֹעֵן וְנִטְעָן יִתְבָּאֵר דִּין זֶה וְכַיּוֹצֵא בּוֹ מִכָּל הַטּוֹעֲנִין שֶׁאֵינָן יְכוֹלִים לְהִשָּׁבַע וְכֵיצַד מְשַׁלְּמִין וּמֵאֵי זֶה טַעַם הֵם מְשַׁלְּמִים:"],"Mishneh Torah, Creditor and Debtor 12":["אֵין נִפְרָעִין מִן הַיּוֹרְשִׁין אֶלָּא אִם כֵּן הָיוּ גְּדוֹלִים. אֲבָל יוֹרְשִׁין קְטַנִּים אֵין נִפְרָעִין מֵהֶן שְׁטַר חוֹב:","וַאֲפִלּוּ הָיָה בּוֹ כָּל תְּנַאי שֶׁבָּעוֹלָם לֹא יִפָּרַע בּוֹ הַמַּלְוֶה כְּלוּם עַד שֶׁיַּגְדִּילוּ הַיְתוֹמִים שֶׁמָּא יֵשׁ לָהֶן רְאָיָה שֶׁשּׁוֹבְרִין בָּהּ אֶת הַשְּׁטָר:","הָיְתָה הַמִּלְוֶה רִבִּית שֶׁל עַכּוּ\"ם שֶׁהֲרֵי הָרִבִּית אוֹכֶלֶת בְּנִכְסֵיהֶן מַעֲמִידִין לָהֶם אַפּוֹטְרוֹפּוֹס וְנִזְקָקִין לְנִכְסֵיהֶן וּמוֹכְרִין וּפוֹרְעִין הַחוֹב. וְכֵן אִשָּׁה שֶׁתָּבְעָה כְּתֻבָּתָהּ בֵּין אַלְמָנָה בֵּין גְּרוּשָׁה מַעֲמִידִים לָהֶם אַפּוֹטְרוֹפּוֹס וְנִזְקָקִין מִשּׁוּם חֵן הָאִשָּׁה כְּדֵי שֶׁיִּהְיֶה לָהּ כְּלוּם שֶׁתִּנָּשֵׂא בּוֹ הָאִשָּׁה לְאַחֵר. לְפִיכָךְ אִם קָפְצָה הָאִשָּׁה וְנִשֵּׂאת וְאַחַר כָּךְ בָּאת לִתְבֹּעַ כְּתֻבָּתָהּ מִנִּכְסֵי יְתוֹמִים אֵין נִזְקָקִין לָהּ עַד שֶׁיִּגְדְּלוּ הַיְתוֹמִים שֶׁהֲרֵי אֵין לָהּ מְזוֹנוֹת וַהֲרֵי נִשֵּׂאת:","הוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁאִם הָיוּ הַנְּכָסִים כְּנֶגֶד הַכְּתֻבָּה בִּלְבַד אוֹ פְּחוּתִים מִמֶּנָּה אֵין נִזְקָקִין לָהּ שֶׁהֲרֵי אֵין כָּאן זְכוּת לַיְתוֹמִים שֶׁלֹּא אָמְרוּ נִזְקָקִין לְנִכְסֵי יְתוֹמִים לְהִפָּרַע מֵהֶן הַכְּתוּבָה אֶלָּא כְּדֵי שֶׁלֹּא יִפְחֲתוּ הַנְּכָסִים מֵחֲמַת הַמְּזוֹנוֹת וְזֹאת הוֹאִיל וְהִיא נוֹטֶלֶת הַכּל מַה זְּכוּת יֵשׁ לַיְתוֹמִים הַקְּטַנִּים בְּדָבָר זֶה עַד שֶׁנִּזְקָקִין לָהֶן. וְלֹא חָשׁוּ לְחֵן הָאִשָּׁה:","צִוָּה הַמּוֹרִישָׁן וְאָמַר תְּנוּ מָנֶה לִפְלוֹנִי נִזְקָקִין אַחַר שֶׁמַּעֲמִידִין לָהֶן אַפּוֹטְרוֹפּוֹס לִטְעֹן טַעֲנָתָם. אָמַר תְּנוּ מָנֶה זֶה לִפְלוֹנִי אוֹ שָׂדֶה זוֹ לִפְלוֹנִי נוֹתְנִין וְאֵין צְרִיכִים לְהַעֲמִיד לָהֶן אַפּוֹטְרוֹפּוֹס:","נִמְצֵאת קַרְקַע שֶׁאֵינָהּ שֶׁלָּהֶן אֶלָּא טָעַן הַטּוֹעֵן שֶׁהִיא גֵּזֶל בְּיַד מוֹרִישָׁיו נִזְקָקִין לָהֶן וּמַעֲמִידִים לָהֶן אַפּוֹטְרוֹפּוֹס לִטְעֹן וְלָדוּן. אִם נִמְצֵאת גְּזוּלָה מַחְזִירִים אוֹתָהּ לִבְעָלֶיהָ. וְכֵן קָטָן שֶׁתָּקַף בַּעֲבָדָיו וְיָרַד לְתוֹךְ שְׂדֵה חֲבֵרוֹ וּכְבָשָׁהּ אֵין אוֹמְרִין נַמְתִּין לוֹ עַד שֶׁיַּגְדִּיל אֶלָּא מוֹצִיאִין אוֹתָהּ מִיָּדוֹ וְלִכְשֶׁיַּגְדִּיל אִם יֵשׁ לוֹ עֵדִים יָבִיא עֵדָיו:","קַרְקַע שֶׁהָיְתָה בְּחֶזְקַת קְטַנִּים וּבָא אַחֵר וְטָעַן שֶׁהִיא לְקוּחָה מִמּוֹרִישָׁן וְיֵשׁ לוֹ עֵדִים שֶׁהֶחְזִיק בָּהּ וַאֲכָלָהּ שְׁנֵי חֲזָקָה בְּחַיֵּי אֲבִיהֶן אֵין מוֹצִיאִין אוֹתָהּ מִיָּדָן עַד שֶׁיַּגְדִּילוּ שֶׁאֵין מְקַבְּלִין עֵדִים שֶׁלֹּא בִּפְנֵי בַּעַל דִּין וְהַקָּטָן כְּאִלּוּ אֵינוֹ עוֹמֵד כָּאן הוּא חָשׁוּב. אֲבָל אִם הוֹצִיא שְׁטָר שֶׁהִיא לְקוּחָה בְּיָדוֹ הֲרֵי זֶה מְקַיֵּם אֶת הַשְּׁטָר וּמוֹצִיאִין אוֹתָהּ מִיָּדָן אַחַר שֶׁמַּעֲמִידִים לָהֶם אַפּוֹטְרוֹפּוֹס:","כְּשֶׁנִּזְקָקִין בֵּית דִּין לְנִכְסֵי יְתוֹמִים לִמְכֹּר שָׁמִין אֶת הַקַּרְקַע וְאַחַר כָּךְ מַכְרִיזִין עָלֶיהָ שְׁלֹשִׁים יוֹם רְצוּפִין אוֹ שִׁשִּׁים יוֹם שֵׁנִי וַחֲמִישִׁי. וּמַכְרִיזִים בַּבֹּקֶר וּבָעֶרֶב בִּשְׁעַת הַכְנָסַת פּוֹעֲלִים וּבִשְׁעַת הוֹצָאַת פּוֹעֲלִין וְכָל מִי שֶׁרוֹצֶה לִקְנוֹת יוֹלִיךְ הַפּוֹעֲלִין לְבַקֵּר לוֹ. וּבְשָׁעָה שֶׁמַּכְרִיזִין מְסַיְּמִים אֶת הַשָּׂדֶה בִּמְצָרֶיהָ וּמוֹדִיעִין כַּמָּה יָפָה וּבְכַמָּה הוּא שׁוּמָה וּמִפְּנֵי מָה רוֹצִים לְמָכְרָהּ אִם לְהַגְבּוֹת לְבַעַל חוֹב אוֹ לִכְתֻבַּת אִשָּׁה לְפִי שֶׁיֵּשׁ מִי שֶׁרוֹצֶה לִתֵּן לְבַעַל חוֹב וְיֵשׁ מִי שֶׁרוֹצֶה לְהַגְבּוֹת לְאִשָּׁה:","וּכְשֶׁכּוֹתְבִין הָאַדְרַכְתָּא עַל נִכְסֵי יְתוֹמִים בֵּין גְּדוֹלִים בֵּין קְטַנִּים כּוֹתְבִין בָּהּ וְהִכַּרְנוּ שֶׁהַנְּכָסִים הָאֵלּוּ הֵן שֶׁל פְּלוֹנִי הַמֵּת. וְאִם לֹא כָּתְבוּ כָּךְ הֲרֵי אַדְרַכְתָּא זוֹ פְּסוּלָה וְאֵין אוֹכְלִין בָּהּ פֵּרוֹת אֲפִלּוּ לְאַחַר שֶׁשָּׁלְמוּ הַהַכְרָזוֹת:","בֵּית דִּין שֶׁמָּכְרוּ שֶׁלֹּא בְּהַכְרָזָה נַעֲשׂוּ כְּמִי שֶׁטָּעוּ בִּדְבַר מִשְׁנָה וְחוֹזְרִים וּמוֹכְרִין בְּהַכְרָזָה. וּבֵית דִּין שֶׁמָּכְרוּ הָאַחֲרָיוּת עַל הַיְתוֹמִים:","וּבֵית דִּין שֶׁהִכְרִיזוּ כָּרָאוּי וּבָדְקוּ יָפֶה יָפֶה וְדִקְדְּקוּ בַּשּׁוּמָא אַף עַל פִּי שֶׁטָּעוּ וּמָכְרוּ שְׁוֵה מָנֶה בְּמָאתַיִם אוֹ מָאתַיִם בְּמָנֶה הֲרֵי מִכְרָן קַיָּם. אֲבָל אִם לֹא בָּדְקוּ בַּשּׁוּמָא וְלֹא כָּתְבוּ אִגֶּרֶת בִּקֹּרֶת שֶׁהִיא דִּקְדּוּק הַשּׁוּמָא וְהַהַכְרָזָה וְטָעוּ וְהוֹתִירוּ שְׁתוּת אוֹ פָּחֲתוּ שְׁתוּת מִכְרָן בָּטֵל. פָּחוֹת מִשְּׁתוּת מִכְרָן קַיָּם. וְכֵן אִם מָכְרוּ קַרְקַע בְּעֵת שֶׁאֵינָן צְרִיכִין לְהַכְרִיז עָלֶיהָ וְטָעוּ שְׁתוּת אוֹ הוֹתִירוּ שְׁתוּת מִכְרָן בָּטֵל אַף עַל פִּי שֶׁהִכְרִיזוּ. פָּחוֹת מִשְּׁתוּת מִכְרָן קַיָּם אַף עַל פִּי שֶׁלֹּא הִכְרִיזוּ שֶׁאֵינָן צְרִיכִין הַכְרָזָה בְּאוֹתוֹ הָעֵת. אֵיזֶהוּ הָעֵת שֶׁאֵינָן צְרִיכִין הַכְרָזָה בְּעֵת שֶׁיִּמְכְּרוּ קַרְקַע לִקְבוּרָה אוֹ לִמְזוֹן הָאִשָּׁה וְהַבָּנוֹת אוֹ לִתֵּן מְנַת הַמֶּלֶךְ אֵין צְרִיכִין הַכְרָזָה לְפִי שֶׁהַדָּבָר נָחוּץ. וְכֵן בֵּית דִּין שֶׁמָּכְרוּ דְּבָרִים שֶׁאֵינָן טְעוּנִין הַכְרָזָה וְטָעוּ בִּשְׁתוּת מִכְרָן בָּטֵל. פָּחוֹת מִשְּׁתוּת מִכְרָן קַיָּם. וְאֵלּוּ הֵן הַדְּבָרִים שֶׁאֵין מַכְרִיזִין עֲלֵיהֶם הָעֲבָדִים וְהַשְּׁטָרוֹת וְהַמִּטַּלְטְלִין. הָעֲבָדִים שֶׁמָּא יִשְׁמְעוּ וְיִבְרְחוּ. וְהַשְּׁטָרוֹת וְהַמִּטַּלְטְלִין שֶׁמָּא יִגָּנְבוּ. לְפִיכָךְ שָׁמִין אוֹתָן בְּבֵית דִּין וּמוֹכְרִין אוֹתָן מִיָּד. וְאִם הַשּׁוּק קָרוֹב לַמְּדִינָה מוֹלִיכִין אוֹתָן לַשּׁוּק:"],"Mishneh Torah, Creditor and Debtor 23":["שִׁטְרֵי חוֹב הַמֻּקְדָּמִים פְּסוּלִין שֶׁהֲרֵי טוֹרֵף בָּהֶן לָקוֹחוֹת שֶׁלֹּא כַּדִּין וּלְפִיכָךְ קָנְסוּ אוֹתוֹ חֲכָמִים וְלֹא יִגְבֶּה בִּשְׁטָר מֻקְדָּם אֶלָּא מִבְּנֵי חוֹרִין גְּזֵרָה שֶׁמָּא יִטְרֹף בּוֹ מִזְּמַן רִאשׁוֹן שֶׁהִקְדִּימוֹ:","שִׁטְרֵי חוֹב הַמְאֻחָרִין כְּשֵׁרִין שֶׁהֲרֵי הוּרַע כֹּחוֹ שֶׁל בַּעַל הַשְּׁטָר שֶׁאֵינוֹ טוֹרֵף אֶלָּא מִזְּמַן הַשְּׁטָר. וְאַף עַל פִּי שֶׁלֹּא כָּתְבוּ בּוֹ שֶׁהוּא מְאֻחָר הֲרֵי זֶה כָּשֵׁר:","שְׁטָר שֶׁכְּתָבוּהוּ בַּיּוֹם וְנֶחְתַּם בַּלַּיְלָה הַסָּמוּךְ לוֹ פָּסוּל מִפְּנֵי שֶׁהוּא מֻקְדָּם. וְאִם הָיוּ עֲסוּקִים בָּעִנְיָן עַד שֶׁנִּכְנַס הַלַּיְלָה וַחֲתָמוּהוּ אַף עַל פִּי שֶׁקָּנוּ מִמֶּנּוּ בַּלַּיְלָה כָּשֵׁר:","שְׁטָר שֶׁזְּמַנּוֹ כָּתוּב בְּשַׁבָּת אוֹ בַּעֲשָׂרָה בְּתִשְׁרֵי שְׁטָר מְאֻחָר הוּא וְכָשֵׁר. וְאֵין חוֹשְׁשִׁין שֶׁמָּא מֻקְדָּם הוּא וּבְאֶחָד בְּשַׁבָּת אוֹ בְּי\"א בְּתִשְׁרֵי נִכְתַּב אֶלָּא מַעֲמִידִין הַשְּׁטָר עַל חֶזְקָתוֹ שֶׁהַדָּבָר יָדוּעַ הוּא שֶׁאֵין כּוֹתְבִין בְּשַׁבָּת וּלְפִיכָךְ אִחֲרוּהוּ:","כּוֹתְבִין שְׁטָר לַלּוֶֹה אַף עַל פִּי שֶׁאֵין הַמַּלְוֶה עִמּוֹ וְאֵין כּוֹתְבִין לַמַּלְוֶה עַד שֶׁיִּהְיֶה לוֶֹה עִמּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁטָר שֶׁיֵּשׁ בּוֹ קִנְיָן שֶׁהֲרֵי מִשָּׁעָה שֶׁקָּנוּ מִיָּדוֹ נִשְׁתַּעְבְּדוּ נְכָסָיו. אֲבָל שְׁטָר שֶׁאֵין בּוֹ קִנְיָן אֵין כּוֹתְבִין אֲפִלּוּ לַלּוֶֹה עַד שֶׁיִּהְיֶה מַלְוֶה עִמּוֹ וְיִתֵּן הַשְּׁטָר בְּיַד הַמַּלְוֶה בְּפָנֵינוּ שֶׁמָּא יִכְתֹּב עַתָּה לִלְווֹת מִמֶּנּוּ בְּנִיסָן וְלֹא יִלְוֶה מִמֶּנּוּ עַד תִּשְׁרֵי וְנִמְצָא הַמַּלְוֶה טוֹרֵף בִּשְׁטָר זֶה מִנִּיסָן שֶׁלֹּא כַּדִּין שֶׁלֹּא הִגִּיעַ לְיָדוֹ עַד תִּשְׁרֵי:","עֵדִים שֶׁקָּנוּ מִיַּד הַלּוֶֹה אוֹ הַמּוֹכֵר וְכַיּוֹצֵא בָּהֶן וְנִתְאַחֲרָה כְּתִיבַת הַשְּׁטָר זְמַן מְרֻבֶּה אִם יָדְעוּ יוֹם שֶׁקָּנוּ מִמֶּנּוּ בּוֹ כּוֹתְבִין בַּשְּׁטָר זְמַן הַקִּנְיָן וְאַף עַל פִּי שֶׁאֵינוֹ זְמַן חֲתִימָתָן. וְאֵין צְרִיכִין לוֹמַר וְנִתְאַחֲרָה כְּתִיבַת יָדֵינוּ עַד יוֹם פְּלוֹנִי. וְאִם לֹא יָדְעוּ יוֹם שֶׁקָּנוּ בּוֹ כּוֹתְבִין זְמַנּוֹ שֶׁל שְׁטָר מִשְּׁעַת כְּתִיבָה. וְכֵן מִי שֶׁנִּמְסְרָה לָהֶן הָעֵדוּת בִּמְדִינָה אַחַת וְכָתְבוּ הָעֵדִים בִּמְדִינָה אַחֶרֶת אֵין מַזְכִּירִין בַּשְּׁטָר מָקוֹם שֶׁנִּמְסְרָה בּוֹ הָעֵדוּת אֶלָּא מָקוֹם שֶׁכָּתְבוּ בּוֹ חֲתִימַת יָדָן:","שִׁטְרֵי מִקָּח וּמִמְכָּר שֶׁלֹּא נִכְתְּבוּ בִּזְמַנָּן אֲפִלּוּ הַמְאֻחָרִין פְּסוּלִין שֶׁהֲרֵי אֶפְשָׁר לִטְרֹף בָּהֶן שֶׁלֹּא כַּדִּין. כֵּיצַד. כְּגוֹן שֶׁחָזַר הַמּוֹכֵר וְקָנָה הַשָּׂדֶה מִיַּד הַלּוֹקֵחַ קֹדֶם שֶׁיַּגִּיעַ זְמַן הַשְּׁטָר הַמְאֻחָר וְיוֹצִיא הַלָּה הַשְּׁטָר הַמְאֻחָר וְיֹאמַר חָזַרְתִּי וּלְקַחְתִּיהָ פַּעַם שְׁנִיָּה מִמְּךָ וְנִמְצָא טוֹרֵף שֶׁלֹּא כַּדִּין. וְלָמָּה לֹא נָחוּשׁ כֵּן לִשְׁטַר חוֹב הַמְאֻחָר שֶׁמָּא יִפְרָעֶנּוּ קֹדֶם שֶׁיַּגִּיעַ זְמַנּוֹ וְיִכְתֹּב שׁוֹבֵר וְיַחְזֹר וְיוֹצִיא הַשְּׁטָר הַמְאֻחָר וְיִטְרֹף בּוֹ שֶׁלֹּא כַּדִּין. לְפִי שֶׁכָּל הַכּוֹתֵב שְׁטָר מְאֻחָר תַּקָּנָתוֹ שֶׁיִּכְתֹּב הַשּׁוֹבֵר סְתָם שֶׁכָּל זְמַן שֶׁיֵּצֵא הַשְּׁטָר יִשְׁבֹּר אוֹתוֹ זֶה הַשּׁוֹבֵר. וְאִם לֹא עָשָׂה כֵן וְכָתַב הַשּׁוֹבֵר בִּזְמַן הַפֵּרָעוֹן הוּא הִפְסִיד עַל עַצְמוֹ:","מִי שֶׁמָּכַר שָׂדֵהוּ בְּאֹנֶס וּמָסַר מוֹדָעָא. אוֹ שֶׁקָּדַם וּמָכַר אוֹ נָתַן לְאַחֵר קֹדֶם שֶׁיִּמְכֹּר לְאַנָּס. הֲרֵי הַמָּעוֹת שֶׁל אַנָּס אֵצֶל הַמּוֹכֵר כְּמִלְוֶה עַל פֶּה וְאֵינוֹ טוֹרֵף בִּשְׁטַר מֶכֶר שֶׁבְּיָדוֹ כְּלוּם מִפְּנֵי שֶׁאֵין דִּין שְׁטָר זֶה שֶׁיִּכְתֹּב וְלֹא נִכְתַּב אֶלָּא מִפְּנֵי הָאֹנֶס. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֶפְשָׁר לַטּוֹרֵף שֶׁיִּטְרֹף בְּלֹא שְׁטָר אֶלָּא בְּעֵדוּת עַל פֶּה. כֵּיצַד. כְּגוֹן שֶׁיֵּשׁ לוֹ עֵדוּת שֶׁזּוֹ גְּזוּלָה מֵאָבִיו הֲרֵי יֵשׁ לוֹ לְהוֹצִיא בְּעֵדִים אֵלּוּ וְאֵין כָּאן שְׁטָר. וְכֵן אִם הֵעִידוּ לוֹ שֶׁנִּגְמַר הַדִּין לְאָבִיו לִטְרֹף מִנִּכְסֵי פְּלוֹנִי בְּכָךְ וְכָךְ מִזְּמַן פְּלוֹנִי וּמֵת אָבִיו וַעֲדַיִן לֹא טָרַף הֲרֵי הַבֵּן טוֹרֵף בְּעֵדוּת זוֹ:","לְפִיכָךְ אֵין כּוֹתְבִין שְׁנֵי שִׁטְרוֹת מֶכֶר עַל שָׂדֶה אַחַת שֶׁמָּא יַעֲשֶׂה הַלּוֹקֵחַ קְנוּנְיָא עִם בַּעַל חוֹב וְיִטְרֹף שֶׁלֹּא כַּדִּין. כֵּיצַד. יָבוֹא זֶה וְיִטְרֹף שָׂדֶה זוֹ בְּעֵדוּת שֶׁהֵעִידוּ לוֹ מֵחֲמַת אָבִיו וְיַחְזֹר הַלּוֹקֵחַ וְיִטְרֹף בִּשְׁטַר הַמֶּכֶר שֶׁבְּיָדוֹ מִן הַלָּקוֹחוֹת שֶׁלָּקְחוּ אַחֲרָיו וְיִקְרַע שְׁטַר הַמֶּכֶר שֶׁבְּיָדוֹ וְיַחְזֹר בִּקְנוּנְיָא וְיַעֲמֹד בַּשָּׂדֶה שֶׁנִּטְרְפָה מִמֶּנּוּ וְיָבוֹא הוּא שֶׁטְּרָפָהּ בְּעַצְמָהּ וְיִטְרֹף אוֹתָהּ פַּעַם אַחֶרֶת בְּעֵדוּת עֵדָיו וְיוֹצִיא הַלָּה שְׁטַר הַמֶּכֶר הַשֵּׁנִי וְיִטְרֹף בּוֹ לָקוֹחוֹת אֲחֵרִים שֶׁלֹּא כַּדִּין. אִם כֵּן מִי שֶׁנֶּאֱבַד לוֹ שְׁטַר הַמֶּכֶר וְעֵדָיו קַיָּמִין כֵּיצַד יַעֲשֶׂה. יִכְתְּבוּ שְׁטָר שֵׁנִי וְיֹאמְרוּ בּוֹ שְׁטָר זֶה אֵין גּוֹבִין בּוֹ לֹא מִנְּכָסִים מְשֻׁעְבָּדִים וְלֹא מִנְּכָסִים בְּנֵי חוֹרִין וְלֹא כְּתַבְנוּהוּ אֶלָּא לְהַעֲמִיד שָׂדֶה זוֹ בְּיַד פְּלוֹנִי הַלּוֹקֵחַ כְּדֵי שֶׁלֹּא יוֹצִיאָהּ מִיָּדוֹ הַמּוֹכֵר וְלֹא יוֹרְשָׁיו:","בְּשִׁטְרֵי הַחוֹבוֹת אֵינוֹ כֵן. אַף עַל פִּי שֶׁעֵדָיו קַיָּמִין וְקָנוּ מִיָּדוֹ וְחָזַר בִּשְׁעָתוֹ וְאָמַר שְׁטָר שֶׁכְּתַבְתֶּם לִי עַתָּה אָבַד אוֹ נִשְׂרַף אֵין כּוֹתְבִין לוֹ שְׁטָר שֵׁנִי שֶׁמָּא פְּרָעוֹ אוֹ מְחָלוֹ. וַאֲפִלּוּ הָיָה הַחוֹב לִזְמַן וְאֵינוֹ גּוֹבֶה בְּעֵדִים אֵלּוּ כְּלוּם אֶלָּא אִם הַלּוֶֹה אוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם שֶׁזֶּה הֻחְזַק כַּפְרָן בְּעֵדוּתָן כְּמוֹ שֶׁיִּתְבָּאֵר:","מִי שֶׁבָּלָה שְׁטַר חוֹבוֹ וַהֲרֵי הוּא הוֹלֵךְ לְהִמָּחֵק מַעֲמִיד עָלָיו עֵדִים וּבָא לְבֵית דִּין וְהֵם עוֹשִׂין לוֹ קִיּוּם. אֲבָל עֵדֵי הַשְּׁטָר עַצְמָן אֵין כּוֹתְבִין לוֹ שְׁטָר אַחֵר אַף עַל פִּי שֶׁנִּמְחַק בִּפְנֵיהֶם. אֲבָל בָּאִין לְבֵית דִּין וּבֵית דִּין עוֹשִׂין לוֹ קִיּוּם:","כֵּיצַד מְקַיְּמִין שְׁטָר זֶה. כּוֹתְבִין שְׁטָר אַחֵר וְאוֹמְרִים אָנוּ בֵּית דִּין פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי הוֹצִיא פְּלוֹנִי בֶּן פְּלוֹנִי שְׁטָר מָחוּק לְפָנֵינוּ וּזְמַנּוֹ בְּיוֹם פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי עֵדָיו. וְאִם כָּתְבוּ וְהֻזְקַקְנוּ לְעֵדוּתָן שֶׁל עֵדִים וְנִמְצֵאת מְכֻוֶּנֶת גּוֹבֶה בִּשְׁטָר זֶה שֶׁכָּתְבוּ לוֹ וְאֵין צָרִיךְ קִיּוּם אַחֵר. וְאִם לֹא כָּתְבוּ כֵן צָרִיךְ לְהָבִיא רְאָיָה עַל הָעֵדִים הָרִאשׁוֹנִים עַד שֶׁתִּתְקַיֵּם עֵדוּתָן:","שְׁטַר חוֹב שֶׁנִּתְקָרֵעַ כָּשֵׁר. נִמְחַק אוֹ נִתְטַשְׁטֵשׁ אִם רִשּׁוּמוֹ נִכָּר כָּשֵׁר. נִקְרָע קֶרַע בֵּית דִּין הֲרֵי זֶה פָּסוּל. אֵיזֶהוּ קֶרַע בֵּית דִּין שְׁתִי וָעֵרֶב:","מִי שֶׁפָּרַע מִקְצָת חוֹבוֹ אִם רָצָה מַחְלִיף וְכוֹתְבִין לוֹ בֵּית דִּין שְׁטָר אַחֵר בִּשְׁאָר הַחוֹב מִזְּמַן רִאשׁוֹן אֲבָל לֹא עֵדֵי הַשְּׁטָר. וְאִם רָצָה יִכְתֹּב שׁוֹבֵר:","הַבָּא לִפְרֹעַ חוֹבוֹ וְאָמַר הַמַּלְוֶה אָבַד לִי הַשְּׁטָר הֲרֵי זֶה יִכְתֹּב לוֹ שׁוֹבֵר וְיִפְרַע כָּל חוֹבוֹ. וְיֵשׁ לַלּוֶֹה לְהַחֲרִים סְתָם עַל מִי שֶׁכּוֹבֵשׁ שְׁטָרוֹ וְטוֹעֵן שֶׁאָבַד. וְאִם טָעַן הַלּוֶֹה טַעֲנַת וַדַּאי וְאָמַר הַשְּׁטָר אֶצְלוֹ וְעַתָּה הִנִּיחוֹ בְּכִיסוֹ הוֹרוּ רַבּוֹתַי שֶׁיִּשָּׁבַע הַמַּלְוֶה הֶסֵּת שֶׁאָבַד הַשְּׁטָר וְאַחַר כָּךְ יִפְרַע חוֹבוֹ וְיִכְתֹּב שׁוֹבֵר:","מִי שֶׁהוֹצִיא שְׁטַר חוֹב בְּמָנֶה וְאָמַר עֲשׂוּ לִי מִמֶּנּוּ שְׁנַיִם בַּחֲמִשִּׁים חֲמִשִּׁים אֵין עוֹשִׂין שֶׁזְּכוּת הוּא לַלּוֶֹה לִהְיוֹת הַכּל בִּשְׁטָר אֶחָד שֶׁאִם יִפְרָעֶנּוּ מִקְצָת נִמְצָא שְׁטָרוֹ פָּגוּם. וְכֵן אִם הוֹצִיא שְׁנֵי שְׁטָרוֹת בַּחֲמִשִּׁים חֲמִשִּׁים וְאָמַר עָשׂוּ לִי אוֹתָן בְּמֵאָה אֵין עוֹשִׂין לוֹ אֶלָּא עוֹשִׂין לוֹ קִיּוּם לְכָל אֶחָד וְאֶחָד שֶׁזְּכוּת הוּא לַלּוֶֹה לִהְיוֹת שְׁנַיִם שֶׁלֹּא יָכֹף אוֹתוֹ בַּדִּין בְּפַעַם אַחַת לִגְבּוֹת הַכּל:","הוֹצִיא שְׁטַר חוֹב בְּמֵאָה וְאָמַר קְרָעוּהוּ וְכִתְבוּ לִי שְׁטָר אַחֵר בַּחֲמִשִּׁים אֵין שׁוֹמְעִין לוֹ שֶׁמָּא פָּרְעוּ הַכּל וְכָתַב לוֹ שׁוֹבֵר עַל שְׁטָר שֶׁל מֵאָה וּכְשֶׁיַּחֲזֹר וְיוֹצִיא קִיּוּם זֶה עַל שְׁטַר חֲמִשִּׁים וְיוֹצִיא הַלּוֶֹה הַשּׁוֹבֵר יֹאמַר לוֹ זֶה שְׁטָר אַחֵר הוּא:"],"Mishneh Torah, Daily Offerings and Additional Offerings 1":["מִצְוַת עֲשֵׂה לְהַקְרִיב שְׁנֵי כְּבָשִׂים עוֹלוֹת בְּכָל יוֹם וְהֵם הַנִּקְרָאִים תְּמִידִין. אֶחָד בַּבֹּקֶר וְאֶחָד בֵּין הָעַרְבַּיִם שֶׁנֶּאֱמַר (במדבר כח ג) \"שְׁנַיִם לַיּוֹם עלָה תָמִיד\" וְגוֹ':","וְאֵימָתַי זְמַן שְׁחִיטָתָן. שֶׁל בֹּקֶר שׁוֹחֲטִין אוֹתוֹ קֹדֶם שֶׁתַּעֲלֶה הַחַמָּה מִשֶּׁיֵּאוֹר פְּנֵי כָּל מִזְרָח. ופַּעַם אַחַת דָּחֲקָה הַשָּׁעָה אֶת הַצִּבּוּר בְּבַיִת שֵׁנִי וְהִקְרִיבוּ תָּמִיד שֶׁל שַׁחַר בְּאַרְבַּע שָׁעוֹת בַּיּוֹם:","תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם שׁוֹחֲטִין אוֹתוֹ מִשֶּׁיַּאֲרִיךְ הַצֵּל וְיֵרָאֶה לַכּל שֶׁהֶאֱרִיךְ. וְהוּא מִשֵּׁשׁ וּמֶחֱצָה וָמַעְלָה עַד סוֹף הַיּוֹם. וְלֹא הָיוּ שׁוֹחֲטִין אוֹתוֹ בְּכָל יוֹם אֶלָּא בִּשְׁמוֹנֶה שָׁעוֹת וּמֶחֱצָה וְקָרֵב בְּתֵשַׁע וּמֶחֱצָה. וְלָמָּה מְאַחֲרִין אוֹתוֹ שְׁתֵּי שָׁעוֹת אַחַר תְּחִלַּת זְמַן שְׁחִיטָתוֹ. מִפְּנֵי הַקָּרְבָּנוֹת שֶׁל יְחִידִים אוֹ שֶׁל צִבּוּר. לְפִי שֶׁאָסוּר לְהַקְרִיב קָרְבָּן כְּלָל קֹדֶם תָּמִיד שֶׁל שַׁחַר. וְלֹא שׁוֹחֲטִין קָרְבָּן אַחַר תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם חוּץ מִקָּרְבַּן פֶּסַח לְבַדּוֹ. שֶׁאִי אֶפְשָׁר שֶׁיַּקְרִיבוּ כָּל יִשְׂרָאֵל פִּסְחֵיהֶן בִּשְׁתֵּי שָׁעוֹת:","אֵין שׁוֹחֲטִין אֶת הַפֶּסַח אֶלָּא אַחַר תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְכֵן מְחֻסְּרֵי כִּפּוּרִים מַקְרִיבִין כַּפָּרָתָן אַחַר תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם בְּיוֹם אַרְבָּעָה עָשָׂר כְּדֵי שֶׁיִּהְיוּ טְהוֹרִין לֶאֱכל פִּסְחֵיהֶן לָעֶרֶב:","עַרְבֵי פְּסָחִים בֵּין בְּחל בֵּין בְּשַׁבָּת הָיָה הַתָּמִיד נִשְׁחַט בְּשֶׁבַע וּמֶחֱצָה וְקָרֵב בִּשְׁמוֹנֶה וּמֶחֱצָה. כְּדֵי שֶׁיִּהְיֶה לָהֶם פְּנַאי לִשְׁחֹט פִּסְחֵיהֶם. וְאִם חָל עֶרֶב פֶּסַח לִהְיוֹת עֶרֶב שַׁבָּת הָיוּ שׁוֹחֲטִין אוֹתוֹ בְּשֵׁשׁ וּמֶחֱצָה בִּתְחִלַּת זְמַנּוֹ. וְקָרֵב בְּשֶׁבַע וּמֶחֱצָה כְּדֵי שֶׁיִּהְיֶה לָהֶם רֶוַח לִצְלוֹת קֹדֶם שֶׁיִּכָּנֵס שַׁבָּת:","אַף עַל פִּי שֶׁאֵין שׁוֹחֲטִין אַחַר תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. מַקְטִירִין כָּל דָּבָר הָרָאוּי לְהַקְטָרָה כָּל הַיּוֹם. וּמַקְטִירִין אֵיבְרֵי עוֹלוֹת וְהָאֵימוּרִין עַד חֲצִי הַלַּיְלָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת. וְאֵיבָרִין וְאֵימוּרִין שֶׁלֹּא נִתְאַכְּלוּ בֵּין מִן הַתָּמִיד בֵּין מִשְּׁאָר הַקָּרְבָּנוֹת מְהַפְּכִין בָּהֶן כָּל הַלַּיְלָה עַד הַבֹּקֶר שֶׁנֶּאֱמַר (ויקרא ו ב) \"כָּל הַלַּיְלָה עַד הַבֹּקֶר\":","אֵיבָרִים שֶׁל תָּמִיד דּוֹחִין אֶת הַטֻּמְאָה וְאֵין דּוֹחִין אֶת הַשַּׁבָּת. אֶלָּא בְּעֶרֶב שַׁבָּת בִּלְבַד מַקְטִירִין אֵיבְרֵי תָּמִיד שֶׁל עֶרֶב שַׁבָּת. שֶׁהַתָּמִיד תְּחִלָּתוֹ דּוֹחֶה שַׁבָּת וְסוֹפוֹ אֵינוֹ דּוֹחֶה. חֶלְבֵי שַׁבָּת קְרֵבִין בְּלֵילֵי יוֹם טוֹב אִם חָל יוֹם טוֹב לִהְיוֹת בְּמוֹצָאֵי שַׁבָּת. אֲבָל אֵין קְרֵבִין בְּלֵילֵי יוֹם הַכִּפּוּרִים שֶׁנֶּאֱמַר (במדבר כח י) \"עלַת שַׁבַּת בְּשַׁבַּתּוֹ\" וְלֹא עוֹלַת שַׁבָּת זוֹ בְּשַׁבָּת אַחֶרֶת. וְלֹא עוֹלַת חֹל בְּיוֹם טוֹב:","אַרְבָּעָה עָשָׂר שֶׁחָל לִהְיוֹת בְּשַׁבָּת. מַקְטִירִין חֶלְבֵי הַפְּסָחִים בְּלֵילֵי יוֹם טוֹב מִפְּנֵי שֶׁהֵם כְּחֶלְבֵי שַׁבָּת:","אֵין פּוֹחֲתִין מִשִּׁשָּׁה טְלָאִים הַמְבֻקָּרִין בְּלִשְׁכַּת הַטְּלָאִים שֶׁבַּמִּקְדָּשׁ. וְיִהְיוּ מוּכָנִים קֹדֶם יוֹם הַקְרָבָה בְּאַרְבָּעָה יָמִים. וְאַף עַל פִּי שֶׁהָיוּ מְבַקְּרִין אוֹתוֹ מִתְּחִלָּה לֹא הָיוּ שׁוֹחֲטִין אֶת הַתָּמִיד עַד שֶׁמְּבַקְּרִין אוֹתוֹ שְׁנִיָּה קֹדֶם שְׁחִיטָה לְאוֹר הָאֲבוּקוֹת. וּמַשְׁקִין אוֹתוֹ מַיִם בְּכוֹס שֶׁל זָהָב כְּדֵי שֶׁיִּהְיֶה נוֹחַ לְהֶפְשֵׁט:","כְּמַעֲשֵׂה תָּמִיד שֶׁל שַׁחַר כָּךְ מַעֲשֵׂה תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְהַכּל כְּמַעֲשֵׂה הָעוֹלָה שֶׁכָּתַבְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת. וְלֹא הָיוּ כּוֹפְתִין אֶת הַטָּלֶה שֶׁלֹּא יְחַקּוּ אֶת הַמִּינִין אֶלָּא אוֹחֲזִין יָדָיו וְרַגְלָיו בִּידֵיהֶן. וְכָךְ הָיְתָה עֲקֵדָתוֹ רֹאשׁוֹ לַדָּרוֹם וּפָנָיו לַמַּעֲרָב:","תָּמִיד שֶׁל שַׁחַר הָיָה נִשְׁחָט עַל קֶרֶן צְפוֹנִית מַעֲרָבִית שֶׁל בֵּית הַמִּטְבָּחַיִם עַל טַבַּעַת שְׁנִיָּה. וְשֶׁל בֵּין הָעַרְבַּיִם עַל קֶרֶן צְפוֹנִית מִזְרָחִית מִמֶּנָּה עַל טַבַּעַת שְׁנִיָּה כְּדֵי שֶׁיִּהְיֶה כְּנֶגֶד הַשֶּׁמֶשׁ. דִּבְרֵי קַבָּלָה הֵן שֶׁיִּהְיוּ נִשְׁחָטִין כְּנֶגֶד הַשֶּׁמֶשׁ:","טָעוּ אוֹ שָׁגְגוּ אֲפִלּוּ הֵזִידוּ וְלֹא הִקְרִיבוּ תָּמִיד שֶׁל שַׁחַר יַקְרִיבוּ תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנִּתְחַנֵּךְ הַמִּזְבֵּחַ. אֲבָל הָיָה מִזְבֵּחַ חָדָשׁ שֶׁעֲדַיִן לֹא קָרֵב עָלָיו כְּלוּם לֹא יַקְרִיבוּ עָלָיו תְּחִלָּה בֵּין הָעַרְבַּיִם. שֶׁאֵין מְחַנְּכִין מִזְבַּח הָעוֹלָה אֶלָּא בְּתָמִיד שֶׁל שַׁחַר:"],"Mishneh Torah, Damages to Property 11":["כַּמָּה הוּא הַכֹּפֶר. כְּמוֹ שְׁרָאוּ הַדַּיָּנִין שֶׁהוּא דְּמֵי הַנֶּהֱרָג הַכּל לְפִי שָׁוְיוֹ שֶׁל נֶהֱרָג שֶׁנֶּאֱמַר (שמות כא ל) \"וְנָתַן פִּדְיֹן נַפְשׁוֹ כְּכל אֲשֶׁר יוּשַׁת עָלָיו\". וְכֹפֶר הָעֲבָדִים בֵּין גְּדוֹלִים בֵּין קְטַנִּים בֵּין זְכָרִים בֵּין נְקֵבוֹת הוּא הַקְּנָס הַקָּצוּב בַּתּוֹרָה שְׁלֹשִׁים סֶלַע כֶּסֶף יָפֶה בֵּין שֶׁהָיָה הָעֶבֶד שָׁוֶה מֵאָה מָנֶה בֵּין שֶׁאֵינוֹ שָׁוֶה אֶלָּא דִּינָר. וְכָל הַמְעֻכָּב גֵּט שִׁחְרוּר אֵין לוֹ קְנָס הוֹאִיל וְאֵין לוֹ אָדוֹן שֶׁהֲרֵי יָצָא לְחֵרוּת:","לְמִי נוֹתְנִין הַכֹּפֶר. לְיוֹרְשֵׁי הַנֶּהֱרָג. וְאִם הֵמִית אִשָּׁה הַכֹּפֶר לְיוֹרְשֶׁיהָ מֵאָבִיהָ וְאֵינוֹ לַבַּעַל. הֵמִית מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין נוֹתֵן חֲצִי קְנָס לְרַבּוֹ וְהַחֵצִי הָאַחֵר רָאוּי לִתֵּן וְאֵין מִי יִקָּחֶנּוּ:","שׁוֹר שֶׁנָּגַח אִשָּׁה וְיָצְאוּ יְלָדֶיהָ אַף עַל פִּי שֶׁהוּא מוּעָד לִגַּח הַבְּעָלִים פְּטוּרִין מִדְּמֵי וְלָדוֹת. שֶׁלֹּא חִיְּבָה תּוֹרָה בִּדְמֵי וְלָדוֹת אֶלָּא לָאָדָם:","נָגַח שִׁפְחָה וְיָצְאוּ יְלָדֶיהָ מְשַׁלֵּם דְּמֵי וְלָדוֹת. שֶׁזֶּה כְּמִי שֶׁנָּגַח חֲמוֹר מְעֻבֶּרֶת. וְאִם הָיָה תָּם מְשַׁלֵּם חֲצִי דְּמֵי וְלָדוֹת מִגּוּפוֹ:","כֵּיצַד שָׁמִין אוֹתָהּ. אוֹמְדִין כַּמָּה הָיְתָה שִׁפְחָה זוֹ שָׁוָה כְּשֶׁהָיְתָה מְעֵבֶּרֶת וְכַמָּה הִיא שָׁוָה עַתָּה וְנוֹתֵן לִבְעָלֶיהָ הַפְּחָת אוֹ חֶצְיוֹ. וְאִם הֵמִית הַשִּׁפְחָה מְשַׁלֵּם הַכֹּפֶר הַקָּצוּב בַּתּוֹרָה בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:","שׁוֹר שֶׁנִּתְכַּוֵּן לִבְהֵמָה וְנָגַח אֶת הָאָדָם אַף עַל פִּי שֶׁאִם הֱמִיתוֹ פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ אִם חָבַל בּוֹ חַיָּב בְּנֵזֶק. וְאִם תָּם הוּא מְשַׁלֵּם חֲצִי נֵזֶק מִגּוּפוֹ. וְאִם מוּעָד נֵזֶק שָׁלֵם:","שׁוֹר תָּם שֶׁהֵמִית וְהִזִּיק דָּנִין אוֹתוֹ דִּינֵי נְפָשׁוֹת וְאֵין דָּנִין אוֹתוֹ דִּינֵי מָמוֹנוֹת. וּמוּעָד שֶׁהֵמִית וְהִזִּיק דָּנִין אוֹתוֹ דִּינֵי מָמוֹנוֹת וְחוֹזְרִין וְדָנִין אוֹתוֹ דִּינֵי נְפָשׁוֹת. קָדְמוּ וְדָנוּהוּ דִּינֵי נְפָשׁוֹת תְּחִלָּה חוֹזְרִין וְדָנִין אוֹתוֹ דִּינֵי מָמוֹנוֹת:","וּמֵהֵיכָן מִשְׁתַּלֵּם מִן הַשֶּׁבַח שֶׁהִשְׁבִּיחַ בִּרְדִיָּתוֹ אַחַר שֶׁנִּגְמַר דִּינוֹ. שֶׁכֵּיוָן שֶׁנִּגְמַר דִּינוֹ לִסְקִילָה אֵין לוֹ בְּעָלִים שֶׁיִּתְחַיְּבוּ בִּנְזָקָיו. דָּנוּהוּ דִּינֵי נְפָשׁוֹת וּבָרַח אֵין דָּנִין אוֹתוֹ דִּינֵי מָמוֹנוֹת:","שׁוֹר שֶׁהֵמִית אֶת הָאָדָם וְהִקְדִּישׁוֹ בְּעָלָיו אֵינוֹ קָדוֹשׁ. וְכֵן אִם הִפְקִירוֹ אֵינוֹ מֻפְקָר. מְכָרוֹ אֵינוֹ מָכוּר. הֶחֱזִירוֹ שׁוֹמֵר לִבְעָלָיו אֵינָהּ חֲזָרָה. שְׁחָטוֹ בְּשָׂרוֹ אָסוּר בַּהֲנָאָה. בַּמֶּה דְּבָרִים אֲמוּרִים אַחַר שֶׁנִּגְמַר דִּינוֹ לִסְקִילָה. אֲבָל עַד שֶׁלֹּא נִגְמָר דִּינוֹ לִסְקִילָה אִם הִקְדִּישׁוֹ מֻקְדָּשׁ וְאִם הִפְקִירוֹ הֲרֵי הוּא מֻפְקָר. מְכָרוֹ הֲרֵי זֶה מָכוּר. הֶחֱזִירוֹ שׁוֹמֵר לִבְעָלָיו הֲרֵי זֶה מֻחְזָר. וְאִם קָדַם וּשְׁחָטוֹ הֲרֵי זֶה מֻתָּר בַּאֲכִילָה:","שׁוֹר שֶׁלֹּא נִגְמַר דִּינוֹ שֶׁנִּתְעָרֵב בִּשְׁוָרִים אֲחֵרִים כֻּלָּן פְּטוּרִין לְפִי שֶׁאֵין גּוֹמְרִין דִּינוֹ שֶׁל שׁוֹר אֶלָּא בִּפְנֵי הַשּׁוֹר כְּדִין הָאָדָם. נִגְמַר דִּינוֹ וְאַחַר כָּךְ נִתְעָרֵב בַּאֲחֵרִים אֲפִלּוּ בְּאֶלֶף כֻּלָּן נִסְקָלִים וְנִקְבָּרִין וַאֲסוּרִין בַּהֲנָאָה כְּדִין בְּהֵמָה נִסְקֶלֶת:","פָּרָה מְעֻבֶּרֶת שֶׁהֵמִיתָה אֶת הָאָדָם וְכֵן כָּל בְּהֵמָה שֶׁנֶּעֶבְדָה בָּהּ עֲבֵרָה הֲרֵי עֵבָּרָהּ כָּמוֹהָ. הִיא וְעֵבָּרָהּ נָגְחָה הִיא וְעֻבָּרָהּ נִרְבְּעָה:","נָגְחָה וְהֵמִיתָה וְאַחַר כָּךְ נִתְעַבְּרָה. אִם עַד שֶׁלֹּא נִגְמַר דִּינָהּ נִתְעַבְּרָה וְיָלְדָה קֹדֶם גְּמַר דִּין וְלָדָהּ מֻתָּר וְאִם יָלְדָה אַחַר גְּמַר דִּין וְלָדָהּ אָסוּר שֶׁהָעֻבָּר יֶרֶךְ אִמּוֹ הוּא. וְאִם נִתְעָרֵב וָלָד זֶה בַּאֲחֵרִים כּוֹנְסִין אֶת כֻּלָּם בְּכִפָּה עַד שֶׁיָּמוּתוּ שָׁם:","שׁוֹר הַנִּסְקָל שֶׁהוּזַמּוּ עֵדָיו כָּל הַקּוֹדֵם בּוֹ זָכָה שֶׁהֲרֵי מִשֶּׁנִּגְמַר דִּינוֹ הִפְקִירוּהוּ בְּעָלָיו. וְאִם הֵעִידוּ שֶׁבְּעָלָיו רִבְּעָהוּ וְהֵזִים אֶת הָעֵדִים הֲרֵי הַשּׁוֹר לִבְעָלָיו וְהַקּוֹדֵם וּמְשָׁכוֹ לֹא זָכָה בּוֹ שֶׁכֵּיוָן שֶׁהַבַּעַל יוֹדֵעַ בְּעַצְמוֹ שֶׁלֹּא חָטָא וְשֶׁאֵלּוּ עֵדֵי שֶׁקֶר הֵם וַהֲרֵי הוּא מְיַחֵל לַהֲזִימָם לֹא הִפְקִיר:"],"Mishneh Torah, Defilement by Leprosy 1":["צָרַעַת עוֹר הַבָּשָׂר הוּא שֶׁיַּלְבִּין מָקוֹם מִן הָעוֹר וְתִהְיֶה הַלַּבְנוּנִית כִּקְרוּם בֵּיצָה וּמִקְּרוּם בֵּיצָה וּלְמַעְלָה. אֲבָל לַבְנוּנִית שֶׁהִיא דִּהָה מִקְּרוּם הַבֵּיצָה וּלְמַטָּה אֵינָהּ צָרַעַת אֶלָּא בֹּהַק הוּא:","וְאַרְבָּעָה מַרְאוֹת יֵשׁ בְּצָרַעַת עוֹר הַבָּשָׂר. וְאֵלּוּ הֵן. לֹבֶן עַז בְּיוֹתֵר שֶׁאֵין לְמַעְלָה מִמֶּנּוּ שֶׁהוּא נִרְאֶה בְּעוֹר הַבָּשָׂר כְּשֶׁלֶג הוּא הַנִּקְרָא בַּהֶרֶת. וְלֹבֶן שֶׁהוּא דִּהָה מִזֶּה מְעַט שֶׁנִּרְאֶה כְּצֶמֶר נָקִי שֶׁל כֶּבֶשׂ בֶּן יוֹמוֹ הוּא הַנִּקְרָא שְׂאֵת. וְלָבָן שֶׁדִּהָה מִן הַשְּׂאֵת מְעַט שֶׁנִּרְאֶה כְּסִיד הַהֵיכָל הוּא תּוֹלֶדֶת הַבַּהֶרֶת וְנִקְרֵאת סַפַּחַת. וְלֹבֶן שֶׁדִּהָה מִסִּיד הַהֵיכָל מְעַט וַהֲרֵי הוּא כִּקְרוּם בֵּיצָה הִיא תּוֹלֶדֶת הַשְּׂאֵת וְגַם זֶה נִקְרָא סַפַּחַת. הִנֵּה לָמַדְתָּ שֶׁהַמַּרְאֶה שֶׁהוּא כְּסִיד הַהֵיכָל הוּא סַפַּחַת הַבַּהֶרֶת. וְהַמַּרְאֶה שֶׁהוּא כִּקְרוּם בֵּיצָה הִיא סַפַּחַת הַשְּׂאֵת. שֶׁאֵין לְשׁוֹן סַפַּחַת אֶלָּא טְפֵלָה. מִכָּאן אָמְרוּ מַרְאוֹת נְגָעִים שְׁתַּיִם שֶׁהֵן אַרְבַּע בַּהֶרֶת וְסַפַּחְתָּהּ שְׂאֵת וְסַפַּחְתָּהּ:","אַרְבַּע מַרְאוֹת נְגָעִים אֵלּוּ כֻּלָּן מִצְטָרְפִין זֶה עִם זֶה בֵּין לְהָקֵל בֵּין לְהַחְמִיר. בֵּין בִּתְחִלַּת רְאִיַּת הַנֶּגַע בֵּין בְּסוֹף הַשִּׁבְעָה. בֵּין לְאַחַר שֶׁנִּפְטַר הַמְצֹרָע אוֹ נֶחְלַט. כֵּיצַד. אֶחָד נֶגַע שֶׁהָיָה כֻּלּוֹ לָבָן כַּשֶּׁלֶג אוֹ כְּסִיד הַהֵיכָל אוֹ כְּצֶמֶר נָקִי אוֹ כִּקְרוּם בֵּיצָה. וְאֶחָד נֶגַע שֶׁהָיָה מִקְצָת הַלֹּבֶן כְּמַרְאֵה הַבַּהֶרֶת וּמִקְצָתוֹ כְּמַרְאֵה הַשְּׂאֵת וּמִקְצָתוֹ כְּמַרְאֵה הַסַּפַּחַת. הַכּל כְּמַרְאֶה אֶחָד הוּא חָשׁוּב. אִם כֵּן לָמָּה מְנָאוּם חֲכָמִים וְאָמְרוּ מַרְאוֹת נְגָעִים שְׁתַּיִם שֶׁהֵן אַרְבַּע כְּדֵי לְהָבִין בְּמַרְאוֹת. שֶׁכָּל כֹּהֵן שֶׁאֵינוֹ מַכִּיר הַמַּרְאוֹת וּשְׁמוֹתֵיהֶן כְּשֶׁמְּלַמְּדִין אוֹתוֹ וּמוֹדִיעִין אוֹתוֹ לֹא יִרְאֶה הַנֶּגַע עַד שֶׁיָּבִין וְיַכִּיר וְיֹאמַר זוֹ הִיא הַבַּהֶרֶת וְזוֹ הִיא סַפַּחְתָּהּ זוֹ הִיא הַשְּׂאֵת וְזוֹ הִיא סַפַּחְתָּהּ:","הָיָה בְּמַרְאֵה הַלֹּבֶן מֵאַרְבַּע מַרְאוֹת אֵלּוּ מִקְצָת אַדְמוּמִיּוֹת מְעֹרָבוֹת בּוֹ. גַּם זֶה נֶגַע צָרַעַת הוּא שֶׁנֶּאֱמַר (ויקרא יג יט) \"אוֹ בַהֶרֶת לְבָנָה אֲדַמְדָּמֶת\". וְהוּא הַדִּין לִשְׂאֵת וּלְסַפַּחַת שֶׁל שְׂאֵת וּלְסַפַּחַת הַבַּהֶרֶת. וְהַמַּרְאֶה הַזֶּה שֶׁהוּא מְעֹרָב מִלַּבְנוּנִית וּמְעַט אֹדֶם הוּא הַנִּקְרָא פָּתוּךְ. וְכֵיצַד מַרְאֵה הַפָּתוּךְ בְּאַרְבַּע מַרְאוֹת אֵלּוּ. כְּאִלּוּ הֵן אַרְבַּע כּוֹסוֹת מְלֵאוֹת חָלָב וְנִתְעָרֵב בַּכּוֹס הָרִאשׁוֹנָה שְׁנֵי טִפֵּי דָּם וּבַשְּׁנִיָּה אַרְבָּעָה טִפִּין וּבַשְּׁלִישִׁית שְׁמוֹנֶה טִפִּין וּבָרְבִיעִית שִׁשָּׁה עָשָׂר טִפִּין. הַפָּתוּךְ שֶׁבַּבַּהֶרֶת הוּא הַמַּרְאֶה הָרְבִיעִי וְהַפָּתוּךְ שֶׁבַּשְּׂאֵת כְּמַרְאֵה כּוֹס שְׁלִישִׁית וְהַפָּתוּךְ שֶׁבְּסַפַּחַת הַבַּהֶרֶת כְּמַרְאֵה הַכּוֹס הַשְּׁנִיָּה וְהַפָּתוּךְ שֶׁבְּסַפַּחַת הַשְּׂאֵת כְּמַרְאֵה הַכּוֹס הָרִאשׁוֹנָה:","כָּל הַמַּרְאוֹת הָאֵלּוּ בֵּין הַלָּבָן בֵּין הַפָּתוּךְ מִצְטָרְפִין זֶה עִם זֶה וּכְמַרְאֶה אֶחָד הֵן חֲשׁוּבִין. וּבֵין שֶׁהָיָה הַנֶּגַע כֻּלּוֹ לָבָן אוֹ מִקְצָתוֹ לָבָן וּמִקְצָתוֹ אֲדַמְדַּם הַכּל כְּמַרְאֶה אֶחָד הוּא בֵּין לְהָקֵל בֵּין לְהַחְמִיר:","כָּל מַרְאֵה צָרַעַת עוֹר הַבָּשָׂר אֵינָהּ קְרוּיָה נֶגַע וְלֹא מְטַמְּאָה עַד שֶׁיִּהְיֶה מַרְאֵה הַנֶּגַע עָמֹק מֵעוֹר הַבָּשָׂר. לֹא עָמֹק בִּמְשִׁישָׁתוֹ אֶלָּא בְּמַרְאִית הָעַיִן כְּמַרְאֵה הַחַמָּה הַנִּרְאֵית לַעַיִן עֲמֻקָּה מִן הַצֵּל. אֲבָל אִם הָיָה מַרְאֵה הַלֹּבֶן אוֹ הַפָּתוּךְ בְּשָׁוֶה עִם שְׁאָר הָעוֹר אוֹ גָּבוֹהַּ מִן הָעוֹר אֵינוֹ נֶגַע אֶלָּא כְּמוֹ צֶמַח מִן הַצְּמָחִים הָעוֹלִים בַּגּוּף:","שִׁעוּר כָּל נִגְעֵי צָרַעַת בֵּין צָרַעַת אָדָם בֵּין צָרַעַת בְּגָדִים כִּגְרִיס הַקִּלְקִי שֶׁהוּא מְרֻבָּע. וְהוּא מָקוֹם מְרֻבָּע מֵעוֹר הַבָּשָׂר כְּדֵי צְמִיחַת שְׁלֹשִׁים וְשֵׁשׁ שְׂעָרוֹת שֵׁשׁ שְׂעָרוֹת אֹרֶךְ וְשֵׁשׁ שְׂעָרוֹת רֹחַב. וְכָל הַפָּחוּת מִזֶּה אֵינוֹ נֶגַע צָרַעַת:","נֶגַע שֶׁהָיָה רָחְבּוֹ כְּדֵי צְמִיחַת חָמֵשׁ שְׂעָרוֹת אֲפִלּוּ הָיָה אָרְכּוֹ אַמָּה הֲרֵי זֶה טָהוֹר וְאֵינוֹ נֶגַע צָרַעַת עַד שֶׁיִּהְיֶה בּוֹ רִבּוּעַ כִּגְרִיס. וְכָל הַשִּׁעוּרִין הֲלָכָה לְמשֶׁה מִסִּינַי:","כָּל מָקוֹם שֶׁנֶּאֱמַר (ויקרא יג יט) \"בַּהֶרֶת\" הוּא הַדִּין לִשְׁאָר אַרְבָּעָה מַרְאוֹת שֶׁל לֹבֶן אוֹ שֶׁל פָּתוּךְ וְהוּא שֶׁיִּהְיֶה הַנֶּגַע כִּגְרִיס אוֹ יֶתֶר וְיִהְיֶה עָמֹק מֵעוֹר הַבָּשָׂר וְזֶה הוּא שֶׁאָנוּ קוֹרִין אוֹתוֹ בַּהֶרֶת סְתָם. בַּהֶרֶת שֶׁהִיא עַזָּה כַּשֶּׁלֶג נִרְאֵית בְּאָדָם שֶׁהוּא לָבָן כֵּהָה. וּבַהֶרֶת שֶׁהִיא כֵּהָה נִרְאֵית בְּכוּשִׁי עַזָּה. לְפִיכָךְ אֵין מְשַׁעֲרִין הַכּל אֶלָּא בְּבֵינוֹנִי שֶׁאֵינוֹ לֹא לָבָן וְלֹא שָׁחוֹר:","שְׁלֹשָׁה סִימָנֵי טֻמְאָה הֵן בְּצָרַעַת עוֹר הַבָּשָׂר. שֵׂעָר לָבָן וְהַמִּחְיָה וְהַפִּשְׂיוֹן. וּשְׁלָשְׁתָּן מְפֹרָשִׁין בַּתּוֹרָה. כֵּיצַד. מִי שֶׁנּוֹלְדָה בּוֹ בַּהֶרֶת וּבָהּ שֵׂעָר לָבָן אוֹ מִחְיַת בָּשָׂר חַי כְּשֶׁיִּרְאֵהוּ הַכֹּהֵן יַחְלִיטוֹ וְיֹאמַר טָמֵא. לֹא הָיָה בָּהּ שֵׂעָר לָבָן וְלֹא מִחְיָה יִסָּגֵר שִׁבְעַת יָמִים וּבַשְּׁבִיעִי רוֹאֵהוּ אִם נוֹלַד בַּבַּהֶרֶת שֵׂעָר לָבָן אוֹ מִחְיָה אוֹ שֶׁפָּשְׂתָה וְהוֹסִיפָה הֲרֵי זֶה מֻחְלָט. לֹא נוֹלַד בָּהּ לֹא מִחְיָה וְלֹא שֵׂעָר לָבָן וְלֹא פָּשְׂתָה בָּעוֹר יַסְגִּיר שָׁבוּעַ שֵׁנִי. אִם נוֹלַד בָּהּ אֶחָד מִשְּׁלָשְׁתָּן מַחְלִיטוֹ וְאִם לָאו הֲרֵי זֶה טָהוֹר וְיִפְטְרֶנּוּ שֶׁאֵין בְּנִגְעֵי עוֹר הַבָּשָׂר הֶסְגֵּר יֶתֶר עַל שְׁנֵי שָׁבוּעוֹת. וְאִם לְאַחַר שֶׁפְּטָרוֹ וְטִהֵר פָּשָׂה הַנֶּגַע אוֹ נוֹלַד בּוֹ שֵׂעָר לָבָן אוֹ מִחְיָה הֲרֵי זֶה מֻחְלָט טֻמְאָה:","בַּהֶרֶת שֶׁהָיְתָה עַזָּה כַּשֶּׁלֶג וּלְאַחַר הַהֶסְגֵּר נַעֲשֵׂית כִּקְרוּם בֵּיצָה אוֹ שֶׁהָיְתָה בַּתְּחִלָּה כִּקְרוּם בֵּיצָה וְנַעֲשֵׂית כַּשָּׁלֶג הֲרֵי הִיא כְּמוֹת שֶׁהָיְתָה שֶׁאֵין עַזּוּת הַמַּרְאֶה סִימַן טֻמְאָה וְלֹא כְּהִיָּתוֹ סִימַן טָהֳרָה אֶלָּא אִם נִתְמַעֵט מֵאַרְבַּע מַרְאוֹת וְנַעֲשֵׂית כֵּהָה מִקְּרוּם בֵּיצָה שֶׁהֲרֵי נַעֲשֵׂית בֹּהַק וּלְפִיכָךְ טָהוֹר. אִם כֵּן מַהוּ זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא יג ו) \"וְהִנֵּה כֵּהָה הַנֶּגַע וְלֹא פָשָׂה הַנֶּגַע בָּעוֹר וְטִהֲרוֹ הַכֹּהֵן\". שֶׁאִם כֵּהָה מֵאַרְבַּע מַרְאוֹת טָהוֹר. וְכֵן אִם לֹא כֵּהָה וְלֹא פָּשָׂה וְלֹא נוֹלְדָה בּוֹ לֹא שֵׂעָר לָבָן וְלֹא מִחְיָה הֲרֵי זֶה טָהוֹר:"],"Mishneh Torah, Defilement by Leprosy 6":["אֵלוּ מְקוֹמוֹת בָּאָדָם שֶׁאֵין מִתְטַמְּאִין בְּבַהֶרֶת. תּוֹךְ הָעַיִן וְתוֹךְ הָאֹזֶן וְתוֹךְ הַחֹטֶם וְתוֹךְ הַפֶּה וְהַקְּמָטִים שֶׁבַּבֶּטֶן וְהַקְּמָטִים שֶׁבַּצַּוָאר וְתַחַת הַדָּד וּבֵית הַשֶּׁחִי וְכַף הָרֶגֶל וְהַצִּפֹּרֶן וְהָרֹאשׁ וְהַזָּקָן שֶׁיֵּשׁ בָּהֶן שֵׂעָר וְהַשְּׁחִין וְהַמִּכְוָה הַמּוֹרְדִין. כָּל אֵלּוּ הַמְּקוֹמוֹת אֵין מִתְטַמְּאִין בִּנְגָעִים וְאֵין מִצְטָרְפִין בִּנְגָעִים. וְלֹא הַנֶּגַע פּוֹשֶׂה לְתוֹכָן. וְאֵין מִתְטַמְּאִין מִשּׁוּם מִחְיָה. וְאֵין מְעַכְּבִין אֶת הַהוֹפֵךְ כֻּלּוֹ לָבָן שֶׁנֶּאֱמַר (ויקרא יג ב) \"בְעוֹר בְּשָׂרוֹ\". וְכָל אֵלּוּ אֵינוֹ עוֹר גָּלוּי אֶלָּא מֵהֶן שֶׁאֵינוֹ עוֹר וּמֵהֶן שֶׁהוּא עוֹר וְהוּא מְכֻסֶּה וְאֵינוֹ גָּלוּי. וְאֹדֶם הַשְּׂפָתַיִם נִדּוֹן כְּבֵית הַסְּתָרִים וְאֵינוֹ מִטַּמֵּא בִּנְגָעִים:","הָרֹאשׁ וְהַזָּקָן שֶׁנָּשַׁר כָּל שַׂעֲרָן וְהַשְּׁחִין וְהַמִּכְוָה שֶׁעָלוּ צָרֶבֶת מִטַּמְּאִין בְּבַהֶרֶת כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֵינָן מִצְטָרְפִין זֶה עִם זֶה וְאֵין נֶגַע עוֹר הַבָּשָׂר פּוֹשֶׂה לְתוֹכָם וְאֵינָן מִטַּמְּאִים מִשּׁוּם מִחְיָה אֲבָל מְעַכְּבִין אֶת הַהוֹפֵךְ כֻּלּוֹ לָבָן:","בַּהֶרֶת הַסְּמוּכָה לָרֹאשׁ אוֹ לָעַיִן אוֹ לָאֹזֶן וְכַיּוֹצֵא בָּהֶן אוֹ לַשְּׁחִין אוֹ לַמִּכְוָה טְהוֹרָה שֶׁנֶּאֱמַר (ויקרא יג ג) \"וְרָאָה הַכֹּהֵן אֶת הַנֶּגַע בְּעוֹר הַבָּשָׂר\" שֶׁיִּהְיֶה כָּל שֶׁחוּצָה לָנֶגַע בְּעוֹר הַבָּשָׂר וְרָאוּי לְפִשְׂיוֹן:","אֵלּוּ בֶּהָרוֹת טְהוֹרוֹת. עַכּוּ\"ם שֶׁהָיְתָה בּוֹ בַּהֶרֶת וְנִתְגַּיֵּר. הָיְתָה בְּעֻבָּר וְנוֹלַד. בְּקֶמֶט וְנִגְלָה. בָּרֹאשׁ וּבַזָּקָן כְּשֶׁהָיָה בָּהֶן שֵׂעָר וְנִקְרְחוּ וְנָשַׁר כָּל הַשֵּׂעָר וְנִתְגַּלְּתָה הַבַּהֶרֶת. הָיְתָה בַּשְּׁחִין וּבַמִּכְוָה כְּשֶׁהֵן מוֹרְדִין וְהֶעֱלוּ צָרֶבֶת הֲרֵי אֵלּוּ טְהוֹרוֹת. וְכֵן אִם הָיְתָה הַבַּהֶרֶת בָּרֹאשׁ אוֹ בַּזָּקָן קֹדֶם שֶׁיַּעֲלוּ שֵׂעָר מֵעוֹלָם וְהֶעֱלוּ שֵׂעָר וְהָלַךְ הַשֵּׂעָר. אוֹ שֶׁהָיְתָה הַבַּהֶרֶת בָּעוֹר וְנַעֲשָׂה מְקוֹמָהּ שְׁחִין אוֹ מִכְוָה וְחָיוּ וַהֲרֵי הֵן כְּעוֹר הַבָּשָׂר. אַף עַל פִּי שֶׁתְּחִלָּתָהּ וְסוֹפָהּ טְמֵאִין הוֹאִיל וְהָיְתָה טְהוֹרָה בֵּינְתַיִם הֲרֵי זוֹ טְהוֹרָה. נִשְׁתַּנּוּ מַרְאֵיהֶן בֵּין שֶׁהֵעֵזּוּ אוֹ שֶׁכָּהוּ יֵרָאֶה בַּתְּחִלָּה. כֵּיצַד. עַכּוּ\"ם שֶׁהָיְתָה בּוֹ בַּהֶרֶת כִּקְרוּם בֵּיצָה וּלְאַחַר שֶׁנִּתְגַּיֵּר נַעֲשֵׂית כַּשֶּׁלֶג. אוֹ שֶׁהָיְתָה כַּשֶּׁלֶג וּלְאַחַר שֶׁנִּתְגַּיֵּר נַעֲשֵׂית כִּקְרוּם בֵּיצָה. תֵּרָאֶה בַּתְּחִלָּה. וְכֵן בְּקָטָן שֶׁנּוֹלַד. וּבַקֶּמֶט שֶׁנִּגְלָה. וּבָרֹאשׁ וּבַזָּקָן שֶׁנִּקְרְחוּ. וּבַשְּׁחִין וּבַמִּכְוָה שֶׁחָיוּ. אִם נִשְׁתַּנָּה מַרְאֵה אוֹתָן הַבֶּהָרוֹת יֵרָאוּ בַּתְּחִלָּה וְאִם לָאו טְהוֹרוֹת:","כָּל סְפֵק נְגָעִים חוּץ מִשְּׁנֵי סְפֵקוֹת שֶׁמָּנִינוּ כְּבָר טָהוֹר עַד שֶׁלֹּא נִזְקַק לְטֻמְאָה. אֲבָל מִשֶּׁנִּזְקַק לְטֻמְאָה סְפֵקוֹ טָמֵא. כֵּיצַד. שְׁנַיִם שֶׁבָּאוּ אֵצֶל כֹּהֵן בָּזֶה בַּהֶרֶת כִּגְרִיס וּבָזֶה כְּסֶלַע וְהִסְגִּירָן וּבְסוֹף הַשָּׁבוּעַ הָיָה בָּזֶה כְּסֶלַע וּבָזֶה כְּסֶלַע וְאֵין יָדוּעַ בְּאֵיזֶה מֵהֶן פָּשְׂתָה. בֵּין בִּשְׁנֵי אֲנָשִׁים בֵּין בְּאִישׁ אֶחָד הֲרֵי זֶה טָהוֹר. שֶׁאַף עַל פִּי שֶׁוַּדַּאי פָּשָׂה הַנֶּגַע בָּזֶה הוֹאִיל וְאֵינוֹ יָדוּעַ אֵי זוֹ הִיא הַבַּהֶרֶת שֶׁפָּשְׂתָה הֲרֵי זֶה טָהוֹר עַד שֶׁיֵּדַע בְּאֵי זֶה נֶגַע טִמְּאוֹ:","מִשֶּׁנִּזְקַק לְטֻמְאָה סְפֵקוֹ טָמֵא. כֵּיצַד. שְׁנַיִם שֶׁבָּאוּ אֵצֶל כֹּהֵן בָּזֶה בַּהֶרֶת כִּגְרִיס וּבָזֶה כְּסֶלַע וְהִסְגִּירָם בְּסוֹף הַשָּׁבוּעַ וַהֲרֵי בָּזֶה כְּסֶלַע וְעוֹד וּבָזֶה כְּסֶלַע וְעוֹד שְׁנֵיהֶן טְמֵאִין. חָזְרוּ שְׁנֵיהֶן לִהְיוֹת כְּסֶלַע שֶׁהֲרֵי הָלַךְ הַפִּשְׂיוֹן מֵאֶחָד מֵהֶן הוֹאִיל וְאֵינוֹ יָדוּעַ אֵי זֶהוּ שְׁנֵיהֶן טְמֵאִים עַד שֶׁיַּחְזְרוּ שְׁנֵיהֶן לִהְיוֹת כִּגְרִיס. וְזֶהוּ שֶׁאָמְרוּ מִשֶּׁנִּזְקַק לְטֻמְאָה סְפֵקוֹ טָמֵא. וְכֵן מִי שֶׁהָיְתָה בּוֹ בַּהֶרֶת וּבָהּ שֵׂעָר לָבָן שֶׁקָּדַם אֶת הַבַּהֶרֶת וְשֵׂעָר לָבָן שֶׁהֲפָכַתּוּ הַבַּהֶרֶת. וְאֵינוֹ יָדוּעַ זֶה שֶׁקָּדַם מִזֶּה שֶׁנֶּהְפַּךְ. אִם מִתּוֹךְ הֶסְגֵּר נִסְתַּפֵּק לוֹ הֲרֵי זֶה טָהוֹר. וְאִם אַחַר הֶחְלֵט הֲרֵי זֶה טָמֵא. אַף עַל פִּי שֶׁהָלַךְ שֵׂעָר אֶחָד מֵהֶן וְאֵינוֹ יוֹדֵעַ אֵי זֶה הָלַךְ אִם הַשֵּׂעָר שֶׁהָיָה סִימַן טֻמְאָה אוֹ הַשֵּׂעָר הָאַחֵר:","מִי שֶׁבָּא אֵצֶל כֹּהֵן וְרָאָהוּ שֶׁצָּרִיךְ הֶסְגֵּר אוֹ שֶׁהוּא פָּטוּר וְעַד שֶׁלֹּא הִסְגִּירוֹ אוֹ פְּטָרוֹ נוֹלְדוּ לוֹ סִימָנֵי טֻמְאָה. הֲרֵי זֶה יַחְלִיט. וְכֵן אִם רָאָהוּ שֶׁיֵּשׁ בּוֹ סִימָנֵי טֻמְאָה וְקֹדֶם שֶׁיַּחְלִיטוֹ וְיֹאמַר לוֹ טָמֵא אַתָּה הָלְכוּ לָהֶן סִימָנֵי טֻמְאָה. אִם הָיָה בַּתְּחִלָּה אוֹ בְּסוֹף שָׁבוּעַ רִאשׁוֹן יַסְגִּירוֹ. וְאִם הָיָה בְּסוֹף שָׁבוּעַ שֵׁנִי אוֹ לְאַחַר הַפִּטּוּר יִפְטֹר אוֹתוֹ:"],"Mishneh Torah, Defilement by a Corpse 17":["זִיז שֶׁהוּא יוֹצֵא מִפֶּתַח הַבַּיִת וּפנָיו לְמַטָּה. וְהָיָה גָּבְהוֹ מֵעַל הָאָרֶץ שְׁנֵים עָשָׂר טֶפַח אוֹ פָּחוֹת מִכָּאן הֲרֵי זֶה מֵבִיא אֶת הַטֻּמְאָה בְּכָל שֶׁהוּא. וְדָבָר בָּרוּר הוּא שֶׁאֵינוֹ מֵבִיא אֶלָּא מִדִּבְרֵיהֶם. וְכֵן כָּל כַּיּוֹצֵא בַּהֲבָאַת הַטֻּמְאָה כָּזוֹ שֶׁאֵינָהּ בְּאֹהֶל טֶפַח הַבָּרִיא אֵינָהּ אֶלָּא מִדִּבְרֵיהֶם. הָיָה גָּבוֹהַּ יֶתֶר מִי\"ב טֶפַח אוֹ שֶׁהָיוּ פָּנָיו לְמַעְלָה. וְכֵן הָעֲטָרוֹת וְהַפִּתּוּחִים הַיּוֹצְאוֹת מִן הַבִּנְיָן אֵין מְבִיאִין אֶלָּא בְּפוֹתֵחַ טֶפַח. וְכֵן זִיז שֶׁעַל גַּבֵּי הַפֶּתַח הַיּוֹצֵא מִן הַמַּשְׁקוֹף וַאֲפִלּוּ הָיָה קָנֶה בְּצַד הַמַּשְׁקוֹף בְּרֹחַב הַפֶּתַח אֵינוֹ מֵבִיא אֶלָּא אִם כֵּן הָיָה בּוֹ פּוֹתֵחַ טֶפַח:","זִיז שֶׁהוּא סוֹבֵב אֶת כָּל הַבַּיִת וְאוֹכֵל בַּפֶּתַח טֶפַח מֵבִיא אֶת הַטֻּמְאָה. הָיָה אוֹכֵל בַּפֶּתַח פָּחוֹת מִטֶּפַח וְטֻמְאָה בַּבַּיִת כֵּלִים שֶׁתַּחְתָּיו טְמֵאִין. טֻמְאָה תַּחְתָּיו אֵינוֹ מֵבִיא אֶת הַטֻּמְאָה לַבַּיִת. וְכֵן בְּחָצֵר שֶׁהִיא מֻקֶּפֶת אַכְסַדְרָה:","חַלּוֹן הָעֲשׂוּיָה לְתַשְׁמִישׁ וְזִיז יוֹצֵא עַל גַּבֵּי הַחַלּוֹן אֲפִלּוּ הָיָה כְּרֹחַב אֲגוּדָל מֵבִיא אֶת הַטֻּמְאָה. וְהוּא שֶׁיִּהְיֶה גָּבוֹהַּ מֵעַל הַחַלּוֹן רוּם אֶצְבָּעַיִם אוֹ פָּחוֹת. הָיָה לְמַעְלָה מֵאֶצְבָּעַיִם אֵינוֹ מֵבִיא אֶת הַטֻּמְאָה אֶלָּא אִם כֵּן יֵשׁ בּוֹ רֹחַב טֶפַח. זִיז זֶה שֶׁעַל גַּבֵּי הַחַלּוֹן הָעֲשׂוּיָה לְמָאוֹר מֵבִיא אֶת הַטֻּמְאָה בְּכָל שֶׁהוּא וַאֲפִלּוּ גָּבוֹהַּ כָּל שֶׁהוּא. בִּנְיָן הַיּוֹצֵא לִפְנֵי הַחַלּוֹן שֶׁהַמַּשְׁקִיף נִסְמָךְ עָלָיו בְּשָׁעָה שֶׁמַּשְׁקִיף אֵינוֹ מֵבִיא אֶת הַטֻּמְאָה. הָיָה בּוֹ זִיז רוֹאִין אֶת הַבִּנְיָן כְּאִלּוּ אֵינוֹ וְהַזִּיז הָעֶלְיוֹן מֵבִיא אֶת הַטֻּמְאָה. וְכֵיצַד מְבִיאִין כָּל הַזִּיזִין הָאֵלּוּ טֻמְאָה. שֶׁאִם הָיְתָה טֻמְאָה תַּחַת אֶחָד מֵהֶן אוֹ בַּבַּיִת הַכּל טָמֵא בֵּין בַּבַּיִת בֵּין תַּחַת הַזִּיז:","שְׁנֵי זִיזִין זֶה עַל גַּב זֶה וְיֵשׁ בְּכָל אֶחָד מֵהֶן פּוֹתֵחַ טֶפַח וּבֵינֵיהֶם פּוֹתֵחַ טֶפַח וְטֻמְאָה תַּחַת הַתַּחְתּוֹן תַּחְתָּיו בִּלְבַד טָמֵא. הָיְתָה טֻמְאָה בֵּינֵיהֶן בֵּינֵיהֶם בִּלְבַד טָמֵא. הָיְתָה עַל גַּב הָעֶלְיוֹן כְּנֶגְדּוֹ עַד הָרָקִיעַ טָמֵא. הָיָה הָעֶלְיוֹן עוֹדֵף עַל הַתַּחְתּוֹן פּוֹתֵחַ טֶפַח וְטֻמְאָה תַּחַת הַתַּחְתּוֹן אוֹ בֵּינֵיהֶן תַּחְתֵּיהֶן וּבֵינֵיהֶן טָמֵא. הָיְתָה עַל גַּב הָעֶלְיוֹן כְּנֶגְדּוֹ וְעַד הָרָקִיעַ טָמֵא. הָיָה הָעֶלְיוֹן עוֹדֵף עַל הַתַּחְתּוֹן פָּחוֹת מִטֶּפַח וְטֻמְאָה תַּחְתֵּיהֶם תַּחְתֵּיהֶם וּבֵינֵיהֶן טָמֵא. הָיְתָה הַטֻּמְאָה בֵּינֵיהֶם אוֹ תַּחַת הַמּוֹתָר בֵּינֵיהֶן וְתַחַת הַמּוֹתָר טָמֵא אֲבָל תַּחַת הַתַּחְתּוֹן טָהוֹר. יֵשׁ בְּכָל אֶחָד מֵהֶן פּוֹתֵחַ טֶפַח וְאֵין בֵּינֵיהֶם פּוֹתֵחַ טֶפַח וְטֻמְאָה תַּחַת הַתַּחְתּוֹן תַּחְתָּיו בִּלְבַד טָמֵא. הָיְתָה בֵּינֵיהֶן אוֹ עַל גַּבֵּי הָעֶלְיוֹן כְּנֶגֶד הַטֻּמְאָה עַד לָרָקִיעַ טָמֵא. אֵין בָּהֶן פּוֹתֵחַ טֶפַח בֵּין שֶׁיֵּשׁ בֵּינֵיהֶם פּוֹתֵחַ טֶפַח וּבֵין שֶׁאֵין בֵּינֵיהֶם פּוֹתֵחַ טֶפַח. בֵּין שֶׁהָיְתָה הַטֻּמְאָה תַּחַת הַתַּחְתּוֹן אוֹ בֵּינֵיהֶן אוֹ עַל גַּב הָעֶלְיוֹן. טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת שֶׁהֲרֵי הִיא רְצוּצָה. וְכֵן שְׁתֵּי יְרִיעוֹת שֶׁהֵן גְּבוֹהוֹת מִן הָאָרֶץ פּוֹתֵחַ טֶפַח זוֹ עַל גַּבֵּי זוֹ. כֵּלִים אוֹ בְּגָדִים אוֹ לוּחוֹת שֶׁל עֵץ שֶׁהֵן מֻנָּחִין זֶה עַל גַּבֵּי זֶה וְטֻמְאָה רְצוּצָה בֵּינֵיהֶן אִם הָיְתָה הַטֻּמְאָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח הֲרֵי הַכְּלִי שֶׁעָלֶיהָ מִלְּמַעְלָה מַאֲהִיל עַל חֲלַל הַטֶּפַח וּמֵבִיא אֶת הַטֻּמְאָה לְכָל הַכֵּלִים שֶׁתַּחְתָּיו. הָיוּ טַבְלִיּוֹת שֶׁל שַׁיִשׁ אֲפִלּוּ גְּבוֹהוֹת מִן הָאָרֶץ אֶלֶף אַמָּה טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת מִפְּנֵי שֶׁהֵן כְּקַרְקַע:","לוּחוֹת שֶׁל עֵץ שֶׁהֵן נוֹגְעוֹת זֶה בָּזֶה בְּקַרְנוֹתֵיהֶן וְהֵן גְּבוֹהוֹת מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחַת אַחַת מֵהֶן כֵּלִים שֶׁתַּחַת הַשְּׁנִיָּה טְהוֹרִין לְפִי שֶׁאֵינָהּ נוֹגַעַת בַּחֲבֶרְתָּהּ בְּפוֹתֵחַ טֶפַח וְהַנּוֹגֵעַ בְּלוּחַ זוֹ הַשְּׁנִיָּה כְּנוֹגֵעַ בְּכֵלִים שֶׁנָּגְעוּ בְּאֹהֶל הַמֵּת. אֲבָל כָּל הַכֵּלִים שֶׁאָמַרְנוּ שֶׁמְּבִיאִין אֶת הַטֻּמְאָה וְאֵינָן חוֹצְצִין אִם הֶאֱהִיל הַכְּלִי עַל הַמֵּת כָּל כֵּלִים שֶׁעַל גַּבָּיו טְמֵאִים כְּמוֹ שֶׁבֵּאַרְנוּ. וְטֻמְאָתָן מִשּׁוּם כֵּלִים הַמַּאֲהִילִין עַל הַמֵּת וְאַף הַכֵּלִים שֶׁעַל גַּבָּיו שֶׁאֵינָן כְּנֶגֶד הַטֻּמְאָה טְמֵאִים מִשּׁוּם כֵּלִים שֶׁנָּגְעוּ בְּכֵלִים שֶׁהֶאֱהִילוּ עַל הַמֵּת:","חָבִית שֶׁהִיא יוֹשֶׁבֶת עַל שׁוּלֶיהָ בָּאֲוִיר וּכְזַיִת מִן הַמֵּת נָתוּן בְּתוֹכָהּ אוֹ תַּחְתֶּיהָ כְּנֶגֶד אֲוִירָהּ טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. וְהֶחָבִית טְמֵאָה שֶׁהֲרֵי הַטֻּמְאָה בּוֹקַעַת מִתַּחְתֶּיהָ וְנִטְמֵאת אֲוִירָהּ. הָיְתָה הַטֻּמְאָה תַּחַת עֳבִי דָּפְנָהּ טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת וְהֶחָבִית טְהוֹרָה. וְלָמָּה הֶחָבִית טְהוֹרָה שֶׁהֲרֵי אֵין הַטֻּמְאָה בּוֹקַעַת בַּאֲוִירָהּ אֶלָּא בְּדָפְנָהּ וְאֵין כְּלִי חֶרֶשׂ מִטָּמֵּא אֶלָּא מֵאֲוִירוֹ. הָיְתָה מִקְצָת הַטֻּמְאָה תַּחַת עֳבִי דָּפְנָהּ וּמִקְצָתָהּ תַּחַת אֲוִירָהּ טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. הָיָה בַּדְּפָנוֹת פּוֹתֵחַ טֶפַח כֻּלָּהּ טְמֵאָה וּכְנֶגֶד פִּיהָ טָהוֹר שֶׁהֲרֵי הַטֻּמְאָה פָּשְׁטָה בַּדְּפָנוֹת בִּלְבַד. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחָבִית טְהוֹרָה. אֲבָל אִם הָיְתָה טְמֵאָה אוֹ גְּבוֹהָה מִן הָאָרֶץ טֶפַח אוֹ מְכֻסָּה אוֹ כְּפוּיָה עַל פִּיהָ וְהָיְתָה טֻמְאָה תַּחְתֶּיהָ אוֹ בְּתוֹכָהּ אוֹ עַל גַּבָּהּ הַכּל טָמֵא וְכָל הַנּוֹגֵעַ בָּהּ כֻּלּוֹ טָמֵא. הָיְתָה מֻקֶּפֶת צָמִיד פָּתִיל וּנְתוּנָה עַל גַּבֵּי הַמֵּת הָאֳכָלִים וְהַמַּשְׁקִין שֶׁבְּתוֹכָהּ טְהוֹרִין וְהַכֵּלִים שֶׁעַל גַּבָּהּ טְמֵאִים. חָבִיּוֹת שֶׁהֵן יוֹשְׁבוֹת עַל שׁוּלֵיהֶן אוֹ מֻטּוֹת עַל צִדֵּיהֶם בָּאֲוִיר וְהֵן נוֹגְעוֹת זוֹ בָּזוֹ בְּפוֹתֵחַ טֶפַח וְטֻמְאָה תַּחַת אַחַת מֵהֶן טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת מִפְּנֵי שֶׁהִיא רְצוּצָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּטְהוֹרוֹת. אֲבָל אִם הָיוּ טְמֵאוֹת אוֹ גְּבוֹהוֹת מִן הָאָרֶץ פּוֹתֵחַ טֶפַח וְטֻמְאָה תַּחַת אַחַת מֵהֶן תַּחַת כֻּלָּן טָמֵא שֶׁהֲרֵי הַכּל אֹהֶל אֶחָד:"],"Mishneh Torah, Defilement by a Corpse 5":["כָּל הַמִּתְטַמְּאִין מֵחֲמַת הַמֵּת בֵּין אָדָם בֵּין כֵּלִים טְמֵאִים טֻמְאַת שִׁבְעָה. כֵּיצַד. אָדָם אוֹ כְּלִי שֶׁנָּגַע בִּדְבָרִים שֶׁמְּטַמְּאִין מִן הַמֵּת בְּמַגָּע. אוֹ שֶׁנִּטְמָא בְּאֹהֶל בְּאֶחָד מִדְּבָרִים שֶׁמְּטַמְּאִין בְּאֹהֶל. וְכֵן אָדָם שֶׁנָּשָׂא דְּבָרִים שֶׁמְּטַמְּאִין מִן הַמֵּת בְּמַשָּׂא. הַכּל טְמֵאִים טֻמְאַת שִׁבְעָה שֶׁנֶּאֱמַר (במדבר יט יד) \"כָּל הַבָּא אֶל הָאֹהֶל וְכָל אֲשֶׁר בָּאֹהֶל יִטְמָא שִׁבְעַת יָמִים\":","אָדָם שֶׁנִּטְמָא בְּמֵת וְכֵלִים שֶׁיִּגַּע בָּהֶן אָדָם זֶה טְמֵאִין טֻמְאַת שִׁבְעָה שֶׁנֶּאֱמַר (במדבר לא כד) \"וְכִבַּסְתֶּם בִּגְדֵיכֶם בַּיּוֹם הַשְּׁבִיעִי וּטְהַרְתֶּם\". אֲבָל אָדָם שֶׁנָּגַע בְּאָדָם שֶׁנִּטְמָא בְּמֵת. בֵּין שֶׁנָּגַע בּוֹ אַחַר שֶׁפֵּרַשׁ מִמְּטַמְּאָיו בֵּין שֶׁנָּגַע בּוֹ כְּשֶׁהוּא עֲדַיִן נוֹגֵעַ בְּמֵת. הֲרֵי זֶה הַשֵּׁנִי טָמֵא טֻמְאַת עֶרֶב שֶׁנֶּאֱמַר (במדבר יט כב) \"וְהַנֶּפֶשׁ הַנֹּגַעַת תִּטְמָא עַד הָעָרֶב\". זֶהוּ דִּין תּוֹרָה אֲבָל מִדִּבְרֵי סוֹפְרִים הַנּוֹגֵעַ בְּמֵת וְנָגַע בְּאָדָם אַחֵר וַעֲדַיִן הוּא מְחֻבָּר בַּמֵּת שְׁנֵיהֶן טְמֵאִין טֻמְאַת שִׁבְעָה וּכְאִלּוּ נָגַע זֶה הַשֵּׁנִי בַּמֵּת עַצְמוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים לְעִנְיַן תְּרוּמָה וְקָדָשִׁים. אֲבָל לְנָזִיר וּלְעוֹשֶׂה פֶּסַח בֵּין בִּשְׁעַת חִבּוּר בֵּין אַחַר שֶׁפֵּרַשׁ אֵינוֹ טָמֵא אֶלָּא טֻמְאַת עֶרֶב כְּדִין תּוֹרָה:","כֵּלִים שֶׁנִּטְמְאוּ בְּמֵת בֵּין בְּמַגָּע בֵּין בְּאֹהֶל הֲרֵי הֵן לַנּוֹגֵעַ בָּהֶן כְּנוֹגֵעַ בַּמֵּת עַצְמוֹ. מָה הַמֵּת מְטַמֵּא הַנּוֹגֵעַ בּוֹ בֵּין אָדָם בֵּין כֵּלִים טֻמְאַת שִׁבְעָה אַף כֵּלִים שֶׁנִּטְמְאוּ בַּמֵּת הֵם וְהַכֵּלִים אוֹ הָאָדָם שֶׁיִּגַּע בָּהֶן טְמֵאִין טֻמְאַת שִׁבְעָה. שֶׁנֶּאֱמַר (במדבר יט טז) \"בַּחֲלַל חֶרֶב אוֹ בְמֵת\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַחֶרֶב כְּמֵת וְהוּא הַדִּין לִשְׁאָר כֵּלִים. בֵּין כְּלֵי מַתָּכוֹת בֵּין כְּלֵי שֶׁטֶף וּבְגָדִים. הֲרֵי הוּא אוֹמֵר (במדבר לא יט) \"כּל הֹרֵג נֶפֶשׁ וְכל נֹגֵעַ בֶּחָלָל\" וְכִי תַּעֲלֶה עַל דַּעְתְּךָ שֶׁזֶּה יָרָה חֵץ וְהָרַג אוֹ זָרַק אֶבֶן וְהָרַג נִטְמָא שִׁבְעַת יָמִים. אֶלָּא הוֹרֵג נֶפֶשׁ בְּחֶרֶב וְכַיּוֹצֵא בָּהּ שֶׁנִּטְמָא בִּנְגִיעָתוֹ בַּכְּלִי שֶׁהָרַג בּוֹ שֶׁהֲרֵי נָגַע הַכְּלִי בְּמֵת. וּמִנַּיִן שֶׁאַף הַכֵּלִים הַנּוֹגְעִין בָּאָדָם שֶׁנָּגַע בְּכֵלִים שֶׁנִּטְמְאוּ בַּמֵּת שֶׁטְּמֵאִים טֻמְאַת שִׁבְעָה שֶׁהֲרֵי הוּא אוֹמֵר (במדבר לא כד) \"וְכִבַּסְתֶּם בִּגְדֵיכֶם בַּיּוֹם הַשְּׁבִיעִי וּטְהַרְתֶּם\". הָא לָמַדְתָּ שֶׁכָּל אָדָם הַטָּמֵא טֻמְאַת שִׁבְעָה מְטַמֵּא בְּגָדִים טֻמְאַת שִׁבְעָה:","נִמְצֵאתָ אוֹמֵר אָדָם שֶׁנָּגַע בְּמֵת וְאָדָם בְּאָדָם אַחֵר הָרִאשׁוֹן טָמֵא טֻמְאַת שִׁבְעָה וְהַשֵּׁנִי טֻמְאַת עֶרֶב. כֵּלִים הַנּוֹגְעִין בְּמֵת וְכֵלִים בְּכֵלִים שְׁנֵיהֶם טְמֵאִים טֻמְאַת שִׁבְעָה אֲבָל הַשְּׁלִישִׁי בֵּין אָדָם בֵּין כֵּלִים טָמֵא טֻמְאַת עֶרֶב. כֵּלִים הַנּוֹגְעִין בְּמֵת וְאָדָם בְּכֵלִים וְכֵלִים בְּאָדָם שְׁלָשְׁתָּן טְמֵאִין טֻמְאַת שִׁבְעָה וְהָרְבִיעִי בֵּין אָדָם בֵּין כֵּלִים טָמֵא טֻמְאַת עֶרֶב:","בַּמֶּה דְּבָרִים אֲמוּרִים לְעִנְיַן תְּרוּמָה וְקָדָשִׁים. אֲבָל לְחַיֵּב כָּרֵת עַל בִּיאַת מִקְדָּשׁ אוֹ עַל אֲכִילַת קָדָשִׁים אֵינוֹ חַיָּב אֶלָּא הַשְּׁנַיִם בִּלְבַד הָרִאשׁוֹן שֶׁנָּגַע בַּמֵּת וְהַשֵּׁנִי שֶׁנָּגַע בּוֹ כְּדִין תּוֹרָה שֶׁנֶּאֱמַר (במדבר יט כב) \"וְכל אֲשֶׁר יִגַּע בּוֹ הַטָּמֵא יִטְמָא\". אֲבָל הַנּוֹגֵעַ בְּכֵלִים שֶׁנָּגְעוּ בָּאָדָם אוֹ הַנּוֹגֵעַ בְּאָדָם שֶׁנָּגַע בַּכֵּלִים שֶׁנָּגְעוּ בַּמֵּת פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בִּיאַת מִקְדָּשׁ. שֶׁהַדְּבָרִים הָאֵלּוּ אַף עַל פִּי שֶׁהֵן דִּבְרֵי קַבָּלָה אֵינָן דִּין תּוֹרָה. שֶׁהֲרֵי לֹא נִתְפָּרְשׁוּ בַּתּוֹרָה. אֶלָּא זֶה שֶׁנִּטְמָא בְּמֵת שֶׁהוּא אָב וְהַשֵּׁנִי הַנּוֹגֵעַ בּוֹ שֶׁהוּא רִאשׁוֹן בֵּין אָדָם בֵּין כֵּלִים:","כְּלִי חֶרֶשׂ שֶׁנָּגַע בְּמֵת אוֹ שֶׁהָיָה עִמּוֹ בָּאֹהֶל טָמֵא. וְאֵינוֹ מְטַמֵּא [לֹא אָדָם] וְלֹא כְּלִי חֶרֶשׂ אַחֵר וְלֹא שְׁאָר כֵּלִים שֶׁאֵין כְּלִי חֶרֶשׂ נַעֲשֶׂה אַב הַטֻּמְאָה לְעוֹלָם לֹא בְּמֵת וְלֹא בִּשְׁאָר טֻמְאוֹת. וְזֶה דִּין תּוֹרָה אַף עַל פִּי שֶׁהוּא קַבָּלָה:","זֶה כְּלָל גָּדוֹל בַּטֻּמְאוֹת כָּל אַב הַטֻּמְאָה מְטַמֵּא אָדָם וּמְטַמֵּא בְּגָדִים וְכֵלִים בֵּין כְּלֵי מַתָּכוֹת בֵּין כְּלֵי שֶׁטֶף בֵּין כְּלֵי חֶרֶשׂ. וְכָל הַמְטַמֵּא אָדָם וְכֵלִים בִּנְגִיעָה הֲרֵי זֶה אַב הַטֻּמְאָה. וְכָל וְלַד הַטֻּמְאוֹת מְטַמֵּא אֳכָלִין וּמַשְׁקִין וְאֵינוֹ מְטַמֵּא לֹא אָדָם וְכֵלִים לֹא כְּלֵי חֶרֶשׂ וְלֹא שְׁאָר כֵּלִים וּבְגָדִים:","כָּל הַנּוֹגֵעַ בְּאָב הוּא הַנִּקְרָא רִאשׁוֹן. וְהַנּוֹגֵעַ בָּרִאשׁוֹן נִקְרָא שֵׁנִי. וְהַנּוֹגֵעַ בַּשֵּׁנִי נִקְרָא שְׁלִישִׁי. וְהַנּוֹגֵעַ בַּשְּׁלִישִׁי נִקְרָא רְבִיעִי. וְהָרִאשׁוֹן וְשֶׁלְּמַטָּה מִמֶּנּוּ כֻּלָּן נִקְרָאִין וְלַד הַטֻּמְאָה:","כָּל הַמִּתְטַמֵּא מֵחֲמַת הַמֵּת טֻמְאַת שִׁבְעָה בֵּין אָדָם בֵּין כֵּלִים הוּא הַנִּקְרָא טְמֵא מֵת. וְהוּא אָב מֵאֲבוֹת הַטֻּמְאוֹת לְעִנְיַן טֻמְאַת תְּרוּמָה וְטֻמְאַת קָדָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ. לִמְנוֹת מִמֶּנּוּ רִאשׁוֹן וְשֵׁנִי כְּדֵי לְטַמֵּא אָדָם וְכֵלִים בְּמַגָּע כִּשְׁאָר אֲבוֹת הַטֻּמְאוֹת. וְאֵינוֹ מְטַמֵּא בְּמַשָּׂא:","כָּל הַמִּתְטַמֵּא מֵחֲמַת הַמֵּת טֻמְאַת עֶרֶב הוּא וְלַד הַטֻּמְאָה וְהוּא הָרִאשׁוֹן לְטֻמְאָה. וְאֶפְשָׁר שֶׁיִּהְיֶה הָרְבִיעִי מִן הַמֵּת רִאשׁוֹן לְטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ לְעִנְיַן תְּרוּמָה וְקָדָשִׁים:","אָדָם אוֹ כֵּלִים שֶׁנִּטְמְאוּ בְּמַגַּע אֶרֶץ הָעַכּוּ\"ם וּבֵית הַפְּרָס אוֹ בְּמַשָּׂאָן אוֹ בְּמַגַּע דַּם תְּבוּסָה וְגוֹלֵל וְדוֹפֵק אוֹ בְּאָהֳלָן. וְכֵן אָדָם שֶׁנִּטְמָא בְּמַשָּׂא דַּם תְּבוּסָה הֲרֵי אֵלּוּ כֻּלָּן וְכָל כַּיּוֹצֵא בָּהֶן אֲבוֹת טֻמְאוֹת שֶׁל דִּבְרֵי סוֹפְרִים. וְכֵן בְּגָדִים הַמִּתְטַמְּאִין מֵחֲמַת אֵלּוּ טֻמְאַת שִׁבְעָה כֻּלָּן אֲבוֹת הַטֻּמְאוֹת שֶׁל דִּבְרֵי סוֹפְרִים:","הָאֹהֶל עַצְמוֹ הַמַּאֲהִיל עַל הַטֻּמְאָה אַף עַל פִּי שֶׁלֹּא נָגְעָה בּוֹ טֻמְאָה הֲרֵי הוּא טָמֵא טֻמְאַת שִׁבְעָה מִן הַתּוֹרָה וַהֲרֵי הוּא כִּבְגָדִים שֶׁנָּגְעוּ בְּמֵת שֶׁנֶּאֱמַר (במדבר יט יח) \"וְהִזָּה עַל הָאֹהֶל\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הָאֹהֶל בֶּגֶד אוֹ שַׂק אוֹ כְּלִי עֵץ אוֹ עוֹר אֶחָד עוֹר בְּהֵמָה וְחַיָּה בֵּין הַמֻּתָּרִין לַאֲכִילָה בֵּין הָאֲסוּרִין לַאֲכִילָה שֶׁנֶּאֱמַר (שמות מ יט) \"וַיִּפְרשֹׁ אֶת הָאֹהֶל עַל הַמִּשְׁכָּן\" אֵין קָרוּי אֹהֶל אֶלָּא אָרוּג וְעוֹר כַּמִּשְׁכָּן. אֲבָל אִם הָיָה הָאֹהֶל נְסָרִין שֶׁל עֵץ כְּגוֹן הַתִּקְרָה וְהַמַּחְצֶלֶת וְכַיּוֹצֵא בָּהֶן. אוֹ שֶׁהָיָה עֶצֶם אוֹ שֶׁל מַתָּכוֹת הֲרֵי זֶה טָהוֹר. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם הָיָה בִּנְיָן שֶׁהוּא טָהוֹר. וְכָל מָקוֹם שֶׁנֶּאֱמַר הַבַּיִת טָמֵא אֵינוֹ אֶלָּא אָדָם וְכֵלִים שֶׁבְּכָל הַבַּיִת. וְאֵין לְךָ יוֹצֵא מִן הָעֵץ שֶׁהוּא מִתְטַמֵּא טֻמְאַת אֹהָלִים אֶלָּא הַפִּשְׁתָּן בִּלְבַד:","בְּגָדִים הַנּוֹגְעִין בְּמֵת אַף עַל פִּי שֶׁהֵן כְּמֵת לְטַמֵּא אֲחֵרִים שֶׁנָּגְעוּ בּוֹ טֻמְאַת שִׁבְעָה אֵינָן כְּמֵת לְטַמֵּא בְּאֹהֶל וּבְמַשָּׂא. שֶׁהַמַּשָּׂא לַמֵּת עַצְמוֹ אֵינוֹ מְפֹרָשׁ כְּמוֹ שֶׁבֵּאַרְנוּ. וּבְטֻמְאַת אֹהֶל הוּא אוֹמֵר (במדבר יט יד) \"אָדָם כִּי יָמוּת בְּאֹהֶל\". לְפִיכָךְ הַנּוֹשֵׂא בְּגָדִים שֶׁנָּגְעוּ בְּמֵת וְלֹא נָגַע בָּהֶן וְכָל הַמַּאֲהִיל עֲלֵיהֶן אוֹ שֶׁהֶאֱהִילוּ עָלָיו אוֹ שֶׁהָיוּ עִמּוֹ בְּאֹהֶל הֲרֵי זֶה טָהוֹר. וְכֵן הָאָדָם שֶׁנִּטְמָא בְּמֵת וְהֶאֱהִיל עַל הַכֵּלִים הֲרֵי הֵן טְהוֹרִין שֶׁאֵין טְמֵא מֵת טָמֵא אֶלָּא בְּמַגָּע בִּלְבַד:","הַמֵּת אֵינוֹ מְטַמֵּא מִשְׁכָּב וּמוֹשָׁב מִתַּחְתָּיו וְלֹא מַדָּף מֵעַל גַּבָּיו אֶלָּא אֶחָד כְּלִי שֶׁיִּגַּע בַּמֵּת מִצִּדּוֹ אוֹ שֶׁהָיָה תַּחְתָּיו אוֹ עַל גַּבָּיו. כֵּיצַד. עֲשָׂרָה בְּגָדִים זֶה עַל גַּבֵּי זֶה וְהַמֵּת לְמַעְלָה וַעֲשָׂרָה בְּגָדִים אֲחֵרִים עַל גַּבּוֹ מִלְּמַעְלָה. בֶּגֶד הַנּוֹגֵעַ בּוֹ וְהַבֶּגֶד הַשֵּׁנִי שֶׁנָּגַע בַּבֶּגֶד שֶׁנָּגַע בּוֹ שְׁנֵיהֶן טְמֵאִים טֻמְאַת שִׁבְעָה וְהַשְּׁלִישִׁי טָמֵא טֻמְאַת עֶרֶב בֵּין שֶׁל מַעְלָה בֵּין שֶׁל מַטָּה. וְהָרְבִיעִי וּמִן הָרְבִיעִי וּלְמַטָּה וּמִן הָרְבִיעִי וּלְמַעְלָה כֻּלָּן טְהוֹרִין. מַה שֶּׁאֵין כֵּן בִּטְמֵאֵי מִשְׁכָּב וּמוֹשָׁב כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁכָּל הַבְּגָדִים אוֹ הַכֵּלִים שֶׁתַּחְתָּיו וְשֶׁל מַעְלָה מִמֶּנּוּ טְהוֹרִין בְּשֶׁלֹּא הָיְתָה שָׁם טֻמְאָה רְצוּצָה וְלֹא טֻמְאַת אֹהֶל. אוֹ שֶׁהָיָה מַבְדִּיל בֵּינוֹ וּבֵין הַכֵּלִים אֶבֶן כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:"],"Mishneh Torah, Defilement of Foods 16":["כָּל הָאֲגֻדּוֹת שֶׁבַּשְּׁוָקִים וְכָל הַקְּמָחִים וְכָל הַסְּלָתוֹת שֶׁבַּשְּׁוקִים בְּחֶזְקַת מֻכְשָׁרִין. הָאֲגֻדּוֹת מִפְּנֵי שֶׁדַּרְכָּן לְזַלֵּף הַמַּיִם עֲלֵיהֶן תָּמִיד וְהַקֶּמַח וְהַסּלֶת לוֹתְתִין אוֹתוֹ וְאַחַר כָּךְ טוֹחֲנִין אוֹתוֹ. וְכֵן חִטִּין שֶׁחוֹלְקִין אוֹתָן בְּרֵחַיִם אַחַת לִשְׁתַּיִם וְאַחַת לְשָׁלֹשׁ כְּדֵי לַעֲשׂוֹת מֵהֶן מַעֲשֵׂה קְדֵרָה כְּגוֹן הָרִיפוֹת וְכַיּוֹצֵא בָּהֶן הֲרֵי הֵן בְּחֶזְקַת מֻכְשָׁרִין בְּכָל מָקוֹם בֵּין שֶׁל שְׁוָקִין בֵּין שֶׁל בָּתִּים. מִפְּנֵי שֶׁלּוֹתְתִין אוֹתָן לְהָסִיר קְלִפָּתָן:","כָּל אֵלּוּ שֶׁהֵן בְּחֶזְקַת מֻכְשָׁרִין הֲרֵי הֵן בְּחֶזְקַת טֻמְאָה מִפְּנֵי שֶׁהַכּל מְמַשְׁמְשִׁין בָּהֶן וְהֵן מֻכְשָׁרִין. וְעַל כֻּלָּן נֶאֱמָן עַם הָאָרֶץ לוֹמַר לֹא הֻכְשְׁרוּ וְאֵין צָרִיךְ לוֹמַר שְׁאָר אֳכָלִין שֶׁאֵין לָהֶן חֲזָקָה שֶׁעַם הָאָרֶץ נֶאֱמָן לוֹמַר לֹא הֻכְשְׁרוּ:","כָּל הַדָּגִים בְּחֶזְקַת מֻכְשָׁרִין וְאֵין עַם הָאָרֶץ נֶאֱמָן עֲלֵיהֶן לוֹמַר לֹא הֻכְשְׁרוּ לְפִיכָךְ לְעוֹלָם הַדָּגִים בְּחֶזְקַת טֻמְאָה. הַדָּגִים בֵּין שֶׁצָּדָן בְּחֶרֶם בֵּין בְּכָפוּף בֵּין בִּמְצוּדָה אִם לֹא נִעֵר אֶת הַמְּצוּדָה עֲלֵיהֶן לֹא הֻכְשְׁרוּ. וְאִם נִעֵר הֻכְשְׁרוּ. וְאֵין עַם הָאָרֶץ נֶאֱמָן לוֹמַר לֹא נִעַרְתִּי אֶת הַמְּצוּדָה עֲלֵיהֶן וַהֲרֵי הֵן בְּחֶזְקַת טֻמְאָה עַד שֶׁיִּתְכַּוֵּן לְצוּדָן בְּטָהֳרָה:","כָּל הַצִּיר בְּחֶזְקַת מֻכְשָׁר וצִיר טָהוֹר שֶׁנָּפַל לְתוֹכוֹ מַיִם כָּל שֶׁהֵם הֲרֵי הַכּל מַשְׁקֶה וּמַכְשִׁיר וּמִתְטַמֵּא טֻמְאַת מַשְׁקִין לְפִיכָךְ חֶזְקָתוֹ טָמֵא. נָפַל לְתוֹכוֹ יַיִן דְּבַשׁ וְחָלָב הוֹלְכִין אַחַר הָרֹב. וְכֵן מֵי פֵּרוֹת שֶׁנִּתְעָרְבוּ בִּשְׁאָר הַמַּשְׁקִין הוֹלְכִין אַחַר הָרֹב. נִתְעָרְבוּ בְּמַיִם כָּל שֶׁהֵן הֲרֵי הַכּל מַשְׁקֶה וּמִתְטַמֵּא טֻמְאַת מַשְׁקִין וּמַכְשִׁיר. וְצִיר חֲגָבִים טְמֵאִים אֵינוֹ מַכְשִׁיר אֲבָל מִתְטַמֵּא טֻמְאַת מַשְׁקִין:","הַלּוֹקֵחַ צִיר מֵעַם הָאָרֶץ מַשִּׁיקוֹ בַּמַּיִם וְטָהוֹר שֶׁאִם הָיָה רֹב הַצִּיר מַיִם הֲרֵי הַמַּיִם מִטַהֲרִין בְּמִקְוֶה. וְאִם הָיָה רֻבּוֹ מֶלַח שֶׁל דָּגִים אֵינָהּ מְקַבֶּלֶת טֻמְאָה וְהַמַּיִם שֶׁבָּהּ בָּטְלוּ בְּמִעוּטָן. בַּמֶּה דְּבָרִים אֲמוּרִים לִטְבּל בָּהֶן פַּת. אֲבָל לִקְדֵרָה מָצָא מִין אֶת מִינוֹ וְנֵעוֹר וְנִמְצְאוּ רֹב הַמַּיִם טְמֵאִים. שֶׁהַמִּעוּט שֶׁהָיָה בַּצִּיר לֹא טָהוֹר בְּמִקְוֶה:","הַפֵּרוֹת בְּכָל מָקוֹם בְּחֶזְקַת טָהֳרָה אֲפִלּוּ הָיָה הַמּוֹכֵר עַכּוּ\"ם עַד שֶׁיֵּדַע שֶׁהֻכְשְׁרוּ אוֹ שֶׁיִּהְיוּ מִדְּבָרִים שֶׁחֶזְקָתָן מֻכְשָׁרִין:","הָאוֹג בְּכָל מָקוֹם בְּחֶזְקַת טֻמְאָה. וְכֵן כָּל הַקִּשּׁוּאִין וְהַדְּלוּעִין וְהַתְּלוּיוֹת בְּגֶמִי עַל פִּתְחֵי חֲנֻיּוֹת בְּחֶזְקַת מֻכְשָׁרִין וּטְמֵאִין:","כָּל הַכָּתוּב בַּתּוֹרָה וּבְדִבְרֵי קַבָּלָה מֵהִלְכוֹת הַטֻּמְאוֹת וְהַטָּהֳרוֹת אֵינוֹ אֶלָּא לְעִנְיַן מִקְדָּשׁ וְקָדָשָׁיו וּתְרוּמוֹת וּמַעֲשֵׂר שֵׁנִי בִּלְבַד. שֶׁהֲרֵי הִזְהִיר אֶת הַטְּמֵאִין מִלִּכָּנֵס לַמִּקְדָּשׁ אוֹ לֶאֱכל קֹדֶשׁ אוֹ תְּרוּמָה וּמַעֲשֵׂר בְּטֻמְאָה. אֲבָל הַחֻלִּין אֵין בָּהֶן אִסּוּר כְּלָל אֶלָּא מֻתָּר לֶאֱכל חֻלִּין טְמֵאִין וְלִשְׁתּוֹת מַשְׁקִין טְמֵאִים. הֲרֵי נֶאֱמַר בַּתּוֹרָה (ויקרא ז יט) \"וְהַבָּשָׂר אֲשֶׁר יִגַּע בְּכָל טָמֵא לֹא יֵאָכֵל\". מִכְּלָל שֶׁהַחֻלִּין מֻתָּרִין שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בִּבְשַׂר קָדָשִׁים. אִם כֵּן מִפְּנֵי מָה נֶאֱמַר הָרִאשׁוֹן שֶׁבְּחֻלִּין טָמֵא וְהַשֵּׁנִי פָּסוּל לֹא שֶׁיִּהְיֶה אָסוּר בַּאֲכִילָה אֶלָּא לִמְנוֹת מִמֶּנּוּ לִתְרוּמָה וּלְקֹדֶשׁ שֶׁאִם נָגַע שֵׁנִי שֶׁל חֻלִּין בִּתְרוּמָה פְּסָלָהּ וַעֲשָׂאָהּ שְׁלִישִׁי. וְכֵן אִם נָגַע בָּאֳכָלִין שֶׁל קֹדֶשׁ טִמְּאָן וַעֲשָׂאָן שְׁלִישִׁי כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן הָאוֹכֵל אֹכֶל שֵׁנִי שֶׁל חֻלִּין אִם נָגַע בִּתְרוּמָה פְּסָלָהּ:","כְּשֵׁם שֶׁמֻּתָּר לֶאֱכל חֻלִּין טְמֵאִים וְלִשְׁתּוֹתָן כָּךְ מֻתָּר לִגְרֹם טֻמְאָה לְחֻלִּין שֶׁבְּאֶרֶץ יִשְׂרָאֵל. וְיֵשׁ לוֹ לְטַמֵּא אֶת הַחֻלִּין הַמְתֻקָּנִין לְכַתְּחִלָּה. וְכֵן מֻתָּר לָאָדָם לִגַּע בְּכָל הַטֻּמְאוֹת וּלְהִתְטַמֵּא בָּהֶן. שֶׁהֲרֵי הִזְהִיר הַכָּתוּב אֶת בְּנֵי אַהֲרֹן וְאֶת הַנָּזִיר מֵהִתְטַמֵּא בְּמֵת מִכְּלָל שֶׁכָּל הָעָם מֻתָּרִין. וְשֶׁאַף כֹּהֲנִים וּנְזִירִים מֻתָּרִין לְהִתְטַמֵּא בִּשְׁאָר טֻמְאוֹת חוּץ מִטְּמֵא מֵת:","כָּל יִשְׂרָאֵל מֻזְהָרִין לִהְיוֹת טְהוֹרִים בְּכָל רֶגֶל מִפְּנֵי שֶׁהֵם נְכוֹנִים לִכָּנֵס בַּמִּקְדָּשׁ וְלֶאֱכל קָדָשִׁים. וְזֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא יא ח) \"וּבְנִבְלָתָם לֹא תִגָּעוּ\" בָּרֶגֶל בִּלְבַד וְאִם נִטְמָא אֵינוֹ לוֹקֶה אֲבָל בִּשְׁאָר יְמוֹת הַשָּׁנָה אֵינוֹ מֻזְהָר:","(דברים יב כב) \"הַטָּמֵא וְהַטָּהוֹר יַחְדָּו\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַטָּמֵא וְהַטָּהוֹר אוֹכְלִין בִּקְעָרָה אַחַת אֲבָל לֹא יֹאכַל הַבַּעַל עִם אִשְׁתּוֹ בַּקְּעָרָה כְּשֶׁתִּהְיֶה נִדָּה וְלֹא יִשְׁתֶּה עִמָּהּ וְלֹא תִּמְזֹג לוֹ אֶת הַכּוֹס כְּמוֹ שֶׁבֵּאַרְנוּ. וְלֹא יֹאכַל הַזָּב עִם הַזָּבָה מִפְּנֵי הֶרְגֵּל עֲבֵרָה שֶׁמָּא יִבְעל:","אַף עַל פִּי שֶׁמֻּתָּר לֶאֱכל אֳכָלִין טְמֵאִין וְלִשְׁתּוֹת מַשְׁקִין טְמֵאִים חֲסִידִים הָרִאשׁוֹנִים הָיוּ אוֹכְלִין חֻלִּין בְּטָהֳרָה וְנִזְהָרִין מִן הַטֻּמְאוֹת כֻּלָּן כָּל יְמֵיהֶם וְהֵן הַנִּקְרָאִים פְּרוּשִׁים וְדָבָר זֶה קְדֻשָּׁה יְתֵרָה הִיא וְדֶרֶךְ חֲסִידוּת שֶׁיִּהְיֶה נִבְדָּל אָדָם וּפוֹרֵשׁ מִשְּׁאָר הָעָם וְלֹא יִגַּע בָּהֶם וְלֹא יֹאכַל וְיִשְׁתֶּה עִמָּהֶם. שֶׁהַפְּרִישׁוּת מְבִיאָה לִידֵי טָהֳרַת הַגּוּף מִמַּעֲשִׂים הָרָעִים. וְטָהֳרַת הַגּוּף מְבִיאָה לִידֵי קְדֻשַּׁת הַנֶּפֶשׁ מִן הַדֵּעוֹת הָרָעוֹת. וּקְדֻשַּׁת הַנֶּפֶשׁ גּוֹרֶמֶת לְהִדָּמוֹת בַּשְּׁכִינָה. שֶׁנֶּאֱמַר (ויקרא יא מד, ויקרא כ, ו-ז) \"וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אֲנִי ה' מְקַדִּשְׁכֶם\": בְּרִיךְ רַחֲמָנָא דְּסַיְּעָן"],"Mishneh Torah, Diverse Species 3":["יֵשׁ מִינִין בַּזְּרָעִין שֶׁיִּהְיֶה הַמִּין הָאֶחָד נִפְרָד לְצוּרוֹת הַרְבֵּה מִפְּנֵי שִׁנּוּי מְקוֹמוֹת וְהָעֲבוֹדָה שֶׁעוֹבְדִין הָאָרֶץ עַד שֶׁיֵּרָאֶה כִּשְׁנֵי מִינִין וְאַף עַל פִּי שֶׁאֵין דּוֹמִין זֶה לָזֶה הוֹאִיל וְהֵן מִין אֶחָד אֵינָן כִּלְאַיִם זֶה בָּזֶה:","וְיֵשׁ בַּזְּרָעִים שְׁנֵי מִינִין שֶׁהֵן דּוֹמִין זֶה לָזֶה וְצוּרַת שְׁנֵיהֶן קְרוֹבָה לִהְיוֹת צוּרָה אַחַת וְאַף עַל פִּי כֵן הוֹאִיל וְהֵן שְׁנֵי מִינִין הֲרֵי אֵלּוּ אֲסוּרִים זֶה עִם זֶה:","כֵּיצַד. הַחֲזֶרֶת עִם חֲזֶרֶת גַּלִּים. וְהָעֵלְשִׁין עִם עֵלְשֵׁי שָׂדֶה. וְהַכְּרֵשִׁין עִם כְּרֵשֵׁי שָׂדֶה. הַכֻּסְבַּר עִם כֻּסְבַּר הָרִים. וְחַרְדָּל עִם חַרְדָּל מִצְרִי. וּדְלַעַת הַמִּצְרִית עִם דְּלַעַת הָרְמוּצָה אֵינָן כִּלְאַיִם זֶה בָּזֶה. וְכֵן הַחִטִּין עִם הַזּוּנִין. וְהַשְּׂעוֹרִים עִם שִׁבּלֶת שׁוּעָל. וְהַכֻּסְּמִין עִם הַשִּׁיפוֹן. וְהַפּוֹל עִם הַסַּפִּיר. וְהַפֻּרְקְדָּן עִם הַטֹּפַח. וּפוֹל לָבָן עִם הַשְּׁעוּעִים. וְהַקְּשׁוּת עִם הַמְּלָפְפוֹן. וְהַכְּרוּב עִם הַתְּרוֹבְתּוֹר. וְהַתְּרָדִין עִם הַלְּעוּנִין אֵינָן כִּלְאַיִם זֶה עִם זֶה. אֲבָל הַצְּנוֹן עִם הַנְּפוּסִין. וְהַחַרְדָּל עִם הַלַּפְסָן. וּדְלַעַת יְוָנִית עִם דְּלַעַת מִצְרִית אוֹ עִם דְּלַעַת הָרְמוּצָה אַף עַל פִּי שֶׁדּוֹמִים זֶה לָזֶה הֲרֵי אֵלּוּ כִּלְאַיִם זֶה בָּזֶה:","וְכֵן בְּאִילָן שֶׁיֵּשׁ שְׁנֵי מִינִין שֶׁדּוֹמִין זֶה לָזֶה בָּעָלִין אוֹ בַּפֵּרוֹת הוֹאִיל וְהֵן שְׁנֵי מִינִין הֲרֵי אֵלּוּ כִּלְאַיִם. כֵּיצַד. הַתַּפּוּחַ עִם הַחִזְרָד. וְהַפַּרְסְקִין עִם הַשְּׁקֵדִים. וְהַשֵּׁזָפִין עִם הָרִימִין אַף עַל פִּי שֶׁדּוֹמִין זֶה לָזֶה הֲרֵי הֵן כִּלְאַיִם זֶה בָּזֶה. אֲבָל הָאֲגַסִּים עִם הַקְרוּסְטְמָלִים וְהַפְּרִישִׁים עִם הָעֵזְרָדִין אֵינָן כִּלְאַיִם זֶה בָּזֶה:","וְכֵן אִם יֵשׁ שָׁם זְרָעִים וְאִילָנוֹת אֲחֵרוֹת אַף עַל פִּי שֶׁהֵן שְׁנֵי מִינִין בְּטִבְעָן הוֹאִיל וְעָלִין שֶׁל זֶה דּוֹמִין לְעָלִין שֶׁל זֶה אוֹ פְּרִי שֶׁל זֶה דּוֹמֶה לִפְרִי שֶׁל זֶה דִּמְיוֹן גָּדוֹל עַד שֶׁיֵּרָאוּ כִּשְׁנֵי גְּוָנִין מִמִּין אֶחָד לֹא חָשְׁשׁוּ לָהֶן לְכִלְאַיִם זֶה עִם זֶה שֶׁאֵין הוֹלְכִין בְּכִלְאַיִם אֶלָּא אַחַר מַרְאִית הָעַיִן:","כֵּיצַד. הַלֶּפֶת עִם הַצְּנוֹן אֵינָן כִּלְאַיִם זֶה בָּזֶה מִפְּנֵי שֶׁפִּרְיֵיהֶן שָׁוִין. וְהַלֶּפֶת עִם הַנְּפוּס אֵינָן כִּלְאַיִם זֶה בָּזֶה מִפְּנֵי שֶׁהֶעָלִין שֶׁלָּהֶן שָׁוִין. אֲבָל צְנוֹן עִם הַנְּפוּס אַף עַל פִּי שֶׁהֶעָלִין דּוֹמִין זֶה לָזֶה וְהַפְּרִי דּוֹמֶה לַפְּרִי הֲרֵי אֵלּוּ כִּלְאַיִם הוֹאִיל וְטַעַם פְּרִי זֶה רָחוֹק מִטַּעַם פְּרִי זֶה בְּיוֹתֵר. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ:","כַּמָּה מַרְחִיקִין בֵּין שְׁנֵי מִינֵי זְרָעִים שֶׁהֵן כִּלְאַיִם זֶה עִם זֶה. כְּדֵי שֶׁיִּהְיוּ נִרְאִים מֻבְדָּלִין זֶה מִזֶּה. אֲבָל אִם נִרְאִין שֶׁנִּזְרְעוּ בְּעִרְבּוּבְיָא הֲרֵי זֶה אָסוּר:","וְשִׁעוּרִין רַבִּים יֵשׁ בְּהַרְחָקָה הַזֹּאת הַכּל לְפִי גֹּדֶל הַשָּׂדֶה הַנִּזְרַעַת וּלְפִי רֹב הֶעָלִין וְשִׁלּוּחַ הַיּוֹנְקוֹת:","כֵּיצַד. שָׂדֵהוּ שֶׁהָיְתָה זְרוּעָה מִין תְּבוּאָה וּבִקֵּשׁ לִזְרֹעַ בְּצִדָּהּ מִין תְּבוּאָה אַחֶרֶת בְּשָׂדֶה אַחַת מַרְחִיק בֵּינֵיהֶן בֵּית רֹבַע וְהוּא כְּעֶשֶׂר אַמּוֹת וְחֹמֶשׁ אַמָּה עַל עֶשֶׂר אַמּוֹת וְחֹמֶשׁ אַמָּה מְרֻבָּע בֵּין מִן הָאֶמְצַע בֵּין מִן הַצַּד. וְאִם לֹא הָיָה בֵּינֵיהֶן כַּשִּׁעוּר הַזֶּה אָסוּר וְאֵינוֹ לוֹקֶה עַד שֶׁיִּהְיוּ קְרוֹבִין בְּתוֹךְ שִׁשָּׁה טְפָחִים:","הָיְתָה שָׂדֵהוּ זְרוּעָה יָרָק וּבִקֵּשׁ לִזְרֹעַ בְּצִדָּהּ שְׂדֵה יָרָק אַחֵר אֲפִלּוּ דְּלַעַת מַרְחִיק בֵּין שְׁתֵּי הַשָּׂדוֹת שִׁשָּׁה טְפָחִים עַל שִׁשָּׁה טְפָחִים מְרֻבָּע בֵּין מִן הַצַּד בֵּין מִן הָאֶמְצַע. וּפָחוֹת מִשִּׁעוּר זֶה אָסוּר וְאֵינוֹ לוֹקֶה עַד שֶׁיִּהְיוּ קְרוֹבִין בְּתוֹךְ טֶפַח:","הָיְתָה אַחַת מִשְּׁתֵּי הַשָּׂדוֹת זְרוּעָה תְּבוּאָה וְהַשְּׁנִיָּה שֶׁבְּצִדָּהּ יָרָק אוֹ דְּלַעַת מַרְחִיק בֵּינֵיהֶן בֵּית רֹבַע:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁצָּרִיךְ לְהַרְחָקָה בַּשִּׁעוּרִין הַלָּלוּ בֵּין שְׁתֵּי שָׂדוֹת. אֲבָל אִם הָיְתָה שָׂדֵהוּ זְרוּעָה יָרָק וְרָצָה לִזְרֹעַ בְּצִדָּהּ שׁוּרָה שֶׁל יָרָק מִמִּין אַחֵר דַּיּוֹ לַעֲשׂוֹת בֵּין הַשָּׂדֶה וּבֵין הַשּׁוּרָה תֶּלֶם אֶחָד אָרְכּוֹ שִׁשָּׁה טְפָחִים בִּלְבַד וְרָחְבּוֹ כְּעָמְקוֹ:","הָיְתָה שָׂדֵהוּ זְרוּעָה תְּבוּאָה וְרָצָה לִזְרֹעַ בְּתוֹכָהּ שׁוּרָה שֶׁל יָרָק אֲפִלּוּ שׁוּרָה שֶׁל דְּלוּעִין שֶׁעָלִין שֶׁלָּהֶן אֲרֻכִּים וּמִסְתַּבְּכִין מַרְחִיק בֵּינֵיהֶן שִׁשָּׁה טְפָחִים. וְאִם נִמְשְׁכוּ הֶעָלִים שֶׁל דְּלַעַת וְנִכְנְסוּ לַתְּבוּאָה וְנִסְתַּבְּכוּ בָּהּ יַעֲקֹר מִן הַתְּבוּאָה שֶׁלִּפְנֵי הַדְּלַעַת עַד שֶׁלֹּא יִתְעָרְבוּ הֶעָלִין. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם זָרַע שׁוּרָה מִמִּין זֶה וְשׁוּרָה מִמִּין אַחֵר שֶׁדַּיּוֹ לִהְיוֹת בֵּינֵיהֶן תֶּלֶם אֶחָד כְּמוֹ שֶׁיִּתְבָּאֵר:","הִרְחִיק בֵּין שְׁנֵי הַמִּינִין הַרְחָקָה הָרְאוּיָה לָהֶן וְהָיָה מִין זֶה נוֹטֶה עַל גַּבֵּי מִין זֶה בֵּין שֶׁנָּטְתָה תְּבוּאָה עַל הַתְּבוּאָה אוֹ יָרָק עַל גַּבֵּי יָרָק אוֹ יָרָק עַל הַתְּבוּאָה אוֹ תְּבוּאָה עַל הַיָּרָק הַכּל מֻתָּר. שֶׁהֲרֵי הִרְחִיק כַּשִּׁעוּר. חוּץ מִדְּלַעַת יְוָנִית שֶׁהִיא נִמְשֶׁכֶת הַרְבֵּה. לְפִיכָךְ אִם נָטְתָה יַעֲקֹר מִלְּפָנֶיהָ כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיָה בֵּין שְׁנֵי הַמִּינִים בּוֹר אוֹ נִיר אוֹ גַּפָּה אוֹ דֶּרֶךְ אוֹ גָּדֵר שֶׁהוּא גָּבוֹהַּ עֲשָׂרָה טְפָחִים אוֹ חָרִיץ שֶׁהוּא עָמֹק עֲשָׂרָה טְפָחִים וְרָחָב אַרְבָּעָה. אוֹ אִילָן שֶׁהוּא מֵסֵךְ עַל הָאָרֶץ. אוֹ סֶלַע שֶׁהוּא גָּבוֹהַּ עֲשָׂרָה טְפָחִים וְרָחָב אַרְבָּעָה. הֲרֵי זֶה מֻתָּר לִסְמֹךְ הַמִּין הָאֶחָד לְצַד אֶחָד מֵאֵלּוּ וְהַמִּין הָאַחֵר לַצַּד הַשֵּׁנִי הוֹאִיל וְאֶחָד מִכָּל אֵלּוּ מַבְדִּיל בֵּינֵיהֶן הֲרֵי הֵן נִרְאִים מֻבְדָּלִין זֶה מִזֶּה:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁצָּרִיךְ הַרְחָקָה אוֹ דָּבָר הַמַּבְדִּיל בְּשֶׁזָּרַע בְּתוֹךְ שָׂדֵהוּ. אֲבָל אִם הָיְתָה שָׂדֵהוּ זְרוּעָה חִטִּים מֻתָּר לַחֲבֵרוֹ לִזְרֹעַ בְּצִדָּהּ שְׂעוֹרִים שֶׁנֶּאֱמַר (ויקרא יט יט) \"שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם\". אֵין הָאִסּוּר אֶלָּא שֶׁיִּזְרַע שָׂדֵהוּ כִּלְאַיִם שֶׁלֹּא נֶאֱמַר הָאָרֶץ לֹא תִזְרַע כִּלְאָיִם. וְלֹא עוֹד אֶלָּא אֲפִלּוּ זָרַע בְּתוֹךְ שָׂדֵהוּ שְׂעוֹרִים סָמוּךְ לַחִטִּים וּמָשַׁךְ זֶרַע הַשְּׂעוֹרִים עַד שֶׁסְּמָכוֹ לִשְׂדֵה חֲבֵרוֹ שֶׁהִיא זְרוּעָה שְׂעוֹרִים הֲרֵי זֶה מֻתָּר. מִפְּנֵי שֶׁנִּרְאוּ הַשְּׂעוֹרִים שֶׁבְּתוֹךְ שָׂדֵהוּ שֶׁהֵן סוֹף שְׂדֵה חֲבֵרוֹ:","הָיְתָה שָׂדֵהוּ זְרוּעָה חִטִּים וּשְׂדֵה חֲבֵרוֹ בְּצִדָּהּ זְרוּעָה חִטִּים מֻתָּר לוֹ לִזְרֹעַ תֶּלֶם אֶחָד שֶׁל פִּשְׁתָּן בְּצַד חִטִּים שֶׁלּוֹ סָמוּךְ לִשְׂדֵה חֲבֵרוֹ. שֶׁהָרוֹאֶה יוֹדֵעַ שֶׁאֵין דֶּרֶךְ הָעָם לִזְרֹעַ תֶּלֶם אֶחָד שֶׁל פִּשְׁתָּן וְלֹא נִתְכַּוֵּן זֶה אֶלָּא לִבְדֹּק שָׂדֵהוּ אִם רְאוּיָה הִיא לִזְרֹעַ פִּשְׁתָּן אִם לֹא וְנִמְצָא כְּזוֹרֵעַ לְהַשְׁחָתָה. לְפִיכָךְ אָסוּר לִזְרֹעַ מִין אַחֵר בֵּין שְׁתֵּי שׁוּרוֹת אֵלּוּ שֶׁהֵן מִמִּין אֶחָד עַד שֶׁיַּרְחִיק בְּתוֹךְ שֶׁלּוֹ:","הָיְתָה שָׂדֵהוּ וּשְׂדֵה חֲבֵרוֹ שֶׁבְּצִדָּהּ זְרוּעִין שְׁנֵי מִינֵי תְּבוּאָה לֹא יִזְרַע בֵּינֵיהֶם חַרְדָּל וַחֲרִיעַ אֲפִלּוּ תֶּלֶם אֶחָד מִפְּנֵי שֶׁהָעָם זוֹרְעִים מֵאֵלּוּ תֶּלֶם אֶחָד. אֲבָל אִם הָיוּ שְׁתֵּי הַשָּׂדוֹת זְרוּעִין שְׁנֵי מִינֵי יְרָקוֹת מֻתָּר לִזְרֹעַ בֵּינֵיהֶן חַרְדָּל אוֹ חֲרִיעַ. שֶׁמֻּתָּר לְהַקִּיף חַרְדָּל אוֹ חֲרִיעַ לְכָל מִין חוּץ מִן הַתְּבוּאָה מִפְּנֵי שֶׁאֵינָן מַזִּיקִין אוֹתָהּ. וְכֵן אִם הָיְתָה זָוִית שֶׁל זֶרַע זֶה נוֹגַעַת בְּצֶלַע שֶׁל זֶרַע הָאַחֵר בְּתוֹךְ שָׂדֵהוּ הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁהֵן נִרְאִין מֻבְדָּלִין זֶה מִזֶּה. וְאֵין צָרִיךְ לוֹמַר אִם הָיְתָה זָוִית שֶׁל זֶרַע זֶה נוֹגַעַת בְּזָוִית שֶׁל זֶרַע הָאַחֵר מִפְּנֵי שֶׁהֵן נִרְאִין כְּסוֹף שָׂדֶה שֶׁנָּגַע בְּסוֹף שָׂדֶה שֶׁהוּא מֻתָּר בְּלֹא הַרְחָקָה וְלֹא הַבְדָּלָה כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Divorce 2":["זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (דברים כד א) \"וְכָתַב לָהּ סֵפֶר כְּרִיתֻת וְנָתַן בְּיָדָהּ\". אֶחָד הַכּוֹתֵב בְּיָדוֹ אוֹ שֶׁאָמַר לְאַחֵר לִכְתֹּב לוֹ. וְאֶחָד הַנּוֹתֵן בְּיָדוֹ אוֹ שֶׁאָמַר לְאַחֵר לִתֵּן לָהּ. לֹא נֶאֱמַר וְכָתַב אֶלָּא לְהוֹדִיעַ שֶׁאֵין מִתְגָּרֶשֶׁת אֶלָּא בִּכְתָב. וְנָתַן שֶׁלֹּא תִּקַּח מֵעַצְמָהּ:","אָמַר לִשְׁנַיִם כִּתְבוּ גֵּט וְחִתְמוּ וּתְנוּ לְאִשְׁתִּי הֲרֵי אֵלּוּ כּוֹתְבִין וְחוֹתְמִין וְנוֹתְנִין לָהּ וְהֵן הֵן שְׁלוּחָיו וְהֵן הֵן עֵדָיו. וְכֵן אִם אָמַר לַסּוֹפֵר כְּתֹב לִי גֵּט לְאִשְׁתִּי וְאָמַר לָעֵדִים לַחְתֹּם כּוֹתְבִים וְחוֹתְמִים וְנוֹתְנִין לוֹ וְהוּא מְגָרֵשׁ בּוֹ בְּכָל עֵת שֶׁיִּרְצֶה:","וְכוֹתְבִין גֵּט לָאִישׁ אַף עַל פִּי שֶׁאֵין אִשְׁתּוֹ עִמּוֹ. וְהוּא שֶׁיִּהְיוּ הָעֵדִים וְהַסּוֹפֵר שֶׁכָּתְבוּ וְחָתְמוּ בּוֹ מַכִּירִין וְיוֹדְעִים שֶׁזֶּה הוּא פְּלוֹנִי וְאִשְׁתּוֹ הִיא פְּלוֹנִית. וְאִם הָיוּ בְּאוֹתוֹ מָקוֹם שְׁנַיִם שֶׁשְּׁמוֹתֵיהֶם שָׁוִים וּשְׁמוֹת נְשׁוֹתֵיהֶם שָׁוִים אֵין מְגָרֵשׁ אֶחָד מֵהֶם אֶלָּא בְּמַעֲמַד חֲבֵרוֹ שֶׁמָּא יִכְתֹּב גֵּט וְיוֹלִיכוֹ לְאֵשֶׁת חֲבֵרוֹ וְיַאַסְרֶנָּה עָלָיו:","וּבִשְׁעַת הַסַּכָּנָה כּוֹתְבִין וְנוֹתְנִין אַף עַל פִּי שֶׁאֵין מַכִּירִים. וְהָאִשָּׁה נוֹתֶנֶת שְׂכַר הַסּוֹפֵר בְּכָל מָקוֹם:","וְצָרִיךְ שֶׁיֹּאמַר הַבַּעַל עַצְמוֹ לַסּוֹפֵר כְּתֹב וְלָעֵדִים חֲתֹמוּ. הֲרֵי שֶׁאָמְרוּ לוֹ בֵּית דִּין אוֹ שְׁנַיִם נִכְתֹּב גֵּט לְאִשְׁתְּךָ וְאָמַר לָהֶם כִּתְבוּ וְכָתְבוּ הֵן עַצְמָן וְחָתְמוּ בּוֹ הֲרֵי זֶה כָּשֵׁר. אֲבָל אִם אָמְרוּ הֵם לַסּוֹפֵר וְכָתַב וְלָעֵדִים וְחָתְמוּ אַף עַל פִּי שֶׁחָזְרוּ וּנְתָנוּהוּ לַבַּעַל וְחָזַר וְנָתַן גֵּט זֶה לְאִשְׁתּוֹ בִּפְנֵי עֵדִים הֲרֵי זֶה גֵּט בָּטֵל, שֶׁהֲרֵי כְּתָבוֹ מִי שֶׁלֹּא אָמַר לוֹ הַבַּעַל לְכָתְבוֹ:","אָמַר לִשְׁנַיִם אוֹ לִשְׁלֹשָׁה אִמְרוּ לַסּוֹפֵר וְיִכְתֹּב גֵּט לְאִשְׁתִּי וְאִמְרוּ לָעֵדִים וְיַחְתֹּמוּ וְאָמְרוּ לַסּוֹפֵר וְכָתַב וְלָעֵדִים וְחָתְמוּ, אוֹ שֶׁאָמַר לִשְׁנַיִם אִמְרוּ לַסּוֹפֵר וְיִכְתֹּב גֵּט לְאִשְׁתִּי וְאַתֶּם חֲתֹמוּ הֲרֵי זֶה גֵּט פָּסוּל. וּמִתְיַשְּׁבִין בְּדָבָר זֶה הַרְבֵּה מִפְּנֵי שֶׁהוּא קָרוֹב לִהְיוֹת גֵּט בָּטֵל:","וּמַה בֵּין פָּסוּל לְבָטֵל. שֶׁכָּל מָקוֹם שֶׁנֶּאֱמַר בְּחִבּוּר זֶה בְּגֵט שֶׁהוּא בָּטֵל הוּא בָּטֵל מִן הַתּוֹרָה. וּבְכָל מָקוֹם שֶׁנֶּאֱמַר פָּסוּל הוּא פָּסוּל מִדִּבְרֵי סוֹפְרִים:","הַבַּעַל שֶׁהֵבִיא גֵּט בְּיָדוֹ חָתוּם וְאָמַר תְּנוּ גֵּט זֶה לְאִשְׁתִּי הֲרֵי אֵלּוּ יִתְּנוּ לָהּ. אָמַר לַאֲחֵרִים לִכְתֹּב גֵּט וְלַחְתֹּם בּוֹ וְלִתְּנוֹ לְאִשְׁתּוֹ וְכָתְבוּ וְחָתְמוּ וְנָתְנוּ לָהּ וְנִמְצָא הַגֵּט בָּטֵל אוֹ פָּסוּל הֲרֵי אֵלּוּ כּוֹתְבִין גֵּט אַחֵר אֲפִלּוּ מֵאָה עַד שֶׁיַּגִּיעַ לְיָדָהּ גֵּט כָּשֵׁר:","אָמַר לָהֶם הַבַּעַל כִּתְבוּ וְחִתְמוּ וּתְנוּ לַשָּׁלִיחַ לְהוֹלִיךְ לָהּ וְכָתְבוּ וְחָתְמוּ וְנָתְנוּ לַשָּׁלִיחַ וְנִמְצָא הַגֵּט בָּטֵל אוֹ פָּסוּל אֵין כּוֹתְבִים אַחֵר עַד שֶׁיִּמָּלְכוּ בַּבַּעַל. שֶׁהֲרֵי לֹא עָשָׂה אוֹתָן שְׁלוּחִים לְגֵרוּשִׁין וְשֶׁמָּא לֹא רָצָה אֶלָּא שֶׁיִּכְתְּבוּ וְיִתְּנוּ לַשָּׁלִיחַ בִּלְבַד וְלֹא יִשָּׁאֵר לָהֶם בּוֹ מַעֲשֶׂה אַחֵר וַהֲרֵי כָּתְבוּ וְנָתְנוּ. לְפִיכָךְ לֹא יִכְתְּבוּ אַחֵר. וְאִם כָּתְבוּ גֵּט אַחֵר כָּשֵׁר וּנְתָנוּהוּ לַשָּׁלִיחַ (וְנָתְנוּ לָהּ) הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","הָאוֹמֵר לִשְׁנַיִם אוֹ לְיֶתֶר מִשְּׁנַיִם כִּתְבוּ גֵּט וּתְנוּ לְאִשְׁתִּי גַּרְשׁוּהָ שַׁלְּחוּהָ שִׁבְקוּהָ תַּרְכוּהָ כִּתְבוּ אִגֶּרֶת וּתְנוּ לָהּ הֲרֵי אֵלּוּ יִכְתְּבוּ גֵּט כָּשֵׁר וְיִתְּנוּ לָהּ. אָמַר לָהֶם פִּטְרוּהָ פַּרְנְסוּהָ עֲשׂוּ לָהּ כַּדָּת עֲשׂוּ לָהּ כַּנִּימוּס עֲשׂוּ לָהּ כָּרָאוּי לֹא אָמַר כְּלוּם. וְאִם כָּתְבוּ גֵּט וְנָתְנוּ לָהּ הֲרֵי זֶה גֵּט בָּטֵל:","אָמַר לָהֶם הוֹצִיאוּהָ עִזְבוּהָ הַתִּירוּהָ הַנִּיחוּהָ הוֹעִילוּהָ הֲרֵי זֶה סָפֵק אִם מַשְׁמָע מִלּוֹת אֵלּוּ גֵּרוּשִׁין אוֹ עִנְיָן אַחֵר. לְפִיכָךְ אֵין כּוֹתְבִין לָהּ. וְאִם כָּתְבוּ גֵּט וְנָתְנוּ לָהּ הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","הָאוֹמֵר כִּתְבוּ גֵּט לְאִשְׁתִּי הֲרֵי אֵלּוּ כּוֹתְבִין וְחוֹתְמִין וְנוֹתְנִין לַבַּעַל בְּיָדוֹ וְאֵין נוֹתְנִין לְאִשְׁתּוֹ עַד שֶׁיֹּאמַר לָהֶם לִתֵּן לָהּ. וְאִם נָתְנוּ לָהּ אֵינוֹ גֵּט. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבָרִיא אֲבָל בִּמְסֻכָּן וְהוּא אָדָם שֶׁקָּפַץ עָלָיו הַחלִי בִּמְהֵרָה וְהִכְבִּיד עָלָיו חָלְיוֹ מִיָּד וְהַיּוֹצֵא בְּקוֹלָר אֲפִלּוּ עַל עִסְקֵי מָמוֹן וְהַמְפָרֵשׁ בַּיָּם וְהַיּוֹצֵא בְּשַׁיָּרָא וְאָמַר כִּתְבוּ גֵּט לְאִשְׁתִּי הֲרֵי אֵלּוּ יִכְתְּבוּ וְיַחְתְּמוּ וְיִתְּנוּ לָהּ. שֶׁהַדָּבָר יָדוּעַ שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא לִכְתֹּב וְלִתֵּן לָהּ:","בָּרִיא שֶׁאָמַר כִּתְבוּ גֵּט לְאִשְׁתִּי וְכָתְבוּ וְחָתְמוּ וְנָתְנוּ לָהּ וְהָרַג עַצְמוֹ מִיָּד כְּגוֹן שֶׁהִשְׁלִיךְ עַצְמוֹ מִן הַגַּג אוֹ הִפִּיל עַצְמוֹ לַיָּם הֲרֵי זֶה גֵּט כָּשֵׁר. עָלָה לַגַּג וּדְחָפַתּוּ הָרוּחַ וְנָפַל וּמֵת אֵינוֹ גֵּט. סָפֵק הִפִּיל עַצְמוֹ סָפֵק דְּחָפַתּוּ הָרוּחַ הֲרֵי זֶה גֵּט עַד שֶׁיִּוָּדַע לְךָ בְּוַדַּאי שֶׁהָרוּחַ דְּחָפַתּוּ. וְכֵן מִי שֶׁהָיָה מֻשְׁלָךְ בַּבּוֹר וְאָמַר כָּל הַשּׁוֹמֵעַ קוֹלִי יִכְתֹּב גֵּט לְאִשְׁתִּי הֲרֵי אֵלּוּ יִכְתְּבוּ וְיִתְּנוּ לָהּ. וְהוּא שֶׁיָּדְעוּ אוֹתוֹ. וְאַף עַל פִּי שֶׁהֶעֱלוּהוּ וְלֹא הִכִּירוּהוּ הֲרֵי זֶה כָּשֵׁר. שֶׁזֶּה כִּשְׁעַת הַסַּכָּנָה הוּא שֶׁכּוֹתְבִים וְנוֹתְנִין אַף עַל פִּי שֶׁאֵין מַכִּירִין. וְכֵן מִי שֶׁנָּפְלוּ בּוֹ מַכּוֹת רָעוֹת שֶׁאִי אֶפְשָׁר שֶׁיִּחְיֶה מֵהֶן אֲפִלּוּ נִשְׁחֲטוּ בּוֹ רֹב סִימָנִין וְרָמַז וְאָמַר כִּתְבוּ גֵּט לְאִשְׁתִּי הֲרֵי אֵלּוּ יִכְתְּבוּ וְיִתְּנוּ שֶׁהֲרֵי עַתָּה חַי הוּא אַף עַל פִּי שֶׁסּוֹפוֹ לָמוּת:","מִי שֶׁהָיְתָה רוּחַ רָעָה מְבַעֶתֶת אוֹתוֹ וְאָמַר כְּשֶׁהִתְחִיל בּוֹ הַחלִי כִּתְבוּ גֵּט לְאִשְׁתִּי לֹא אָמַר כְּלוּם. מִפְּנֵי שֶׁאֵין דַּעְתּוֹ נְכוֹנָה וּמְיֻשֶּׁבֶת. וְכֵן שִׁכּוֹר שֶׁהִגִּיעַ לְשִׁכְרוּתוֹ שֶׁל לוֹט. וְאִם לֹא הִגִּיעַ הֲרֵי זֶה סָפֵק:","אָמַר כְּשֶׁהוּא בָּרִיא כִּתְבוּ וּתְנוּ גֵּט לְאִשְׁתִּי וְאַחַר כָּךְ נִבְעַת מַמְתִּינִין עַד שֶׁיַּבְרִיא וְכוֹתְבִין וְנוֹתְנִין לָהּ. וְאֵין צָרִיךְ לַחֲזֹר וּלְהִמָּלֵךְ בּוֹ אַחַר שֶׁהִבְרִיא. וְאִם כָּתְבוּ וְנָתְנוּ קֹדֶם שֶׁיִּבָּרֵא הֲרֵי זֶה פָּסוּל:","מִי שֶׁנִּשְׁתַּתֵּק וַהֲרֵי דַּעְתּוֹ נְכוֹנָה וְאָמְרוּ לוֹ נִכְתֹּב גֵּט לְאִשְׁתְּךָ וְהִרְכִּין בְּרֹאשׁוֹ בּוֹדְקִין אוֹתוֹ שָׁלֹשׁ פְּעָמִים בְּסֵרוּגִין אִם אָמַר לָהֶם עַל לָאו לָאו וְעַל הֵן הֵן הֲרֵי אֵלּוּ יִכְתְּבוּ וְיִתְּנוּ. וּצְרִיכִין לְבָדְקוֹ יָפֶה יָפֶה שֶׁמָּא נִטְרְפָה דַּעְתּוֹ. וְכֵן אִם כָּתַב בְּיָדוֹ כִּתְבוּ וּתְנוּ גֵּט לְאִשְׁתִּי הֲרֵי אֵלּוּ כּוֹתְבִין וְנוֹתְנִין לָהּ אִם הָיְתָה דַּעְתּוֹ מְיֻשֶּׁבֶת עָלָיו. שֶׁאֵין דִּין מִי שֶׁנִּשְׁתַּתֵּק כְּדִין הַחֵרֵשׁ:","מִי שֶׁנָּשָׂא כְּשֶׁהוּא פִּקֵּחַ וְנִתְחָרֵשׁ וְאֵין צָרִיךְ לוֹמַר נִשְׁתַּטָּה אֵינוֹ מוֹצִיא לְעוֹלָם עַד שֶׁיַּבְרִיא. וְאֵין סוֹמְכִין עַל רְמִיזַת הַחֵרֵשׁ וְלֹא עַל כְּתָבוֹ אַף עַל פִּי שֶׁדַּעְתּוֹ נְכוֹנָה וּמְיֻשֶּׁבֶת עָלָיו. אֲבָל אִם נָשָׂא אִשָּׁה כְּשֶׁהוּא חֵרֵשׁ מְגָרֵשׁ בִּרְמִיזָה שֶׁאֵין קִדּוּשָׁיו קִדּוּשִׁין מִן הַתּוֹרָה כְּמוֹ שֶׁבֵּאַרְנוּ. וּכְשֵׁם שֶׁכּוֹנֵס בִּרְמִיזָה כָּךְ מוֹצִיא בִּרְמִיזָה:","הַמְקַדֵּשׁ קְטַנָּה עַל יְדֵי אָבִיהָ וְגֵרְשָׁהּ כְּשֶׁהִיא קְטַנָּה אָבִיהָ מְקַבֵּל גִּטָּהּ וּמִשֶּׁיַגִּיעַ גֵּט לְיַד הָאָב נִתְגָּרְשָׁה. גֵּרְשָׁהּ כְּשֶׁהִיא נַעֲרָה אִם הִגִּיעַ הַגֵּט לְיָדָהּ אוֹ לְיַד אָבִיהָ נִתְגָּרְשָׁה. וְאֵין עוֹשָׂה נַעֲרָה הַמְאֹרָסָה שָׁלִיחַ לְקַבֵּל גִּטָּהּ מִיַּד בַּעְלָהּ בְּחַיֵּי אָבִיהָ. אֲבָל הָאָב עוֹשֶׂה שָׁלִיחַ לְקַבֵּל הַגֵּט לְבִתּוֹ הַמְאֹרָסָה בֵּין קְטַנָּה בֵּין נַעֲרָה:","קִדְּשָׁהּ אָבִיהָ כְּשֶׁהִיא קְטַנָּה וּמֵת. אִם מַבְחֶנֶת בֵּין גִּטָּהּ לְדָבָר אַחֵר הֲרֵי זוֹ מִתְגָּרֶשֶׁת מִשֶּׁיַגִּיעַ הַגֵּט לְיָדָהּ. וְאִם לָאו אֵינָהּ מִתְגָּרֶשֶׁת עַד שֶׁתַּבְחִין וְאִם גֵּרְשָׁהּ אֵינָהּ מְגֹרֶשֶׁת:","מִי שֶׁהַדִּין נוֹתֵן שֶׁכּוֹפִין אוֹתוֹ לְגָרֵשׁ אֶת אִשְׁתּוֹ וְלֹא רָצָה לְגָרֵשׁ. בֵּית דִּין שֶׁל יִשְׂרָאֵל בְּכָל מָקוֹם וּבְכָל זְמַן מַכִּין אוֹתוֹ עַד שֶׁיֹּאמַר רוֹצֶה אֲנִי וְיִכְתֹּב הַגֵּט וְהוּא גֵּט כָּשֵׁר. וְכֵן אִם הִכּוּהוּ עַכּוּ\"ם וְאָמְרוּ לוֹ עֲשֵׂה מַה שֶּׁיִּשְׂרָאֵל אוֹמְרִין לְךָ וְלָחֲצוּ אוֹתוֹ יִשְׂרָאֵל בְּיַד הָעַכּוּ\"ם עַד שֶׁיְּגָרֵשׁ הֲרֵי זֶה כָּשֵׁר. וְאִם הָעַכּוּ\"ם מֵעַצְמָן אֲנָסוּהוּ עַד שֶׁכָּתַב הוֹאִיל וְהַדִּין נוֹתֵן שֶׁיִּכְתֹּב הֲרֵי זֶה גֵּט פָּסוּל. וְלָמָּה לֹא בִּטֵּל גֵּט זֶה שֶׁהֲרֵי הוּא אָנוּס בֵּין בְּיַד עַכּוּ\"ם בֵּין בְּיַד יִשְׂרָאֵל. שֶׁאֵין אוֹמְרִין אָנוּס אֶלָּא לְמִי שֶׁנִּלְחַץ וְנִדְחַק לַעֲשׂוֹת דָּבָר שֶׁאֵינוֹ מְחֻיָּב בּוֹ מִן הַתּוֹרָה לַעֲשׂוֹתוֹ כְּגוֹן מִי שֶׁהֻכָּה עַד שֶׁמָּכַר אוֹ עַד שֶׁנָּתַן. אֲבָל מִי שֶׁתְּקָפוֹ יִצְרוֹ הָרַע לְבַטֵּל מִצְוָה אוֹ לַעֲשׂוֹת עֲבֵרָה וְהֻכָּה עַד שֶׁעָשָׂה דָּבָר שֶׁחַיָּב לַעֲשׂוֹתוֹ אוֹ עַד שֶׁנִּתְרַחֵק מִדָּבָר הָאָסוּר לַעֲשׂוֹתוֹ אֵין זֶה אָנוּס מִמֶּנּוּ אֶלָּא הוּא אָנַס עַצְמוֹ בְּדַעְתּוֹ הָרָעָה. לְפִיכָךְ זֶה שֶׁאֵינוֹ רוֹצֶה לְגָרֵשׁ מֵאַחַר שֶׁהוּא רוֹצֶה לִהְיוֹת מִיִּשְׂרָאֵל וְרוֹצֶה הוּא לַעֲשׂוֹת כָּל הַמִּצְוֹת וּלְהִתְרַחֵק מִן הָעֲבֵרוֹת וְיִצְרוֹ הוּא שֶׁתְּקָפוֹ וְכֵיוָן שֶׁהֻכָּה עַד שֶׁתָּשַׁשׁ יִצְרוֹ וְאָמַר רוֹצֶה אֲנִי כְּבָר גֵּרֵשׁ לִרְצוֹנוֹ. לֹא הָיָה הַדִּין נוֹתֵן שֶׁכּוֹפִין אוֹתוֹ לְגָרֵשׁ וְטָעוּ בֵּית דִּין שֶׁל יִשְׂרָאֵל אוֹ שֶׁהָיוּ הֶדְיוֹטוֹת וַאֲנָסוּהוּ עַד שֶׁגֵּרֵשׁ הֲרֵי זֶה גֵּט פָּסוּל הוֹאִיל וְיִשְׂרָאֵל אֲנָסוּהוּ יִגְמֹר וִיגָרֵשׁ. וְאִם הָעַכּוּ\"ם, אֲנָסוּהוּ לְגָרֵשׁ שֶׁלֹּא כַּדִּין אֵינוֹ גֵּט. אַף עַל פִּי שֶׁאָמַר בְּעַכּוּ\"ם רוֹצֶה אֲנִי וְאָמַר לְיִשְׂרָאֵל כִּתְבוּ וְחִתְמוּ הוֹאִיל וְאֵין הַדִּין מְחַיְּבוֹ לְהוֹצִיא וְהָעַכּוּ\"ם אֲנָסוּהוּ אֵינוֹ גֵּט:"],"Mishneh Torah, Eruvin 5":["אַנְּשֵׁי מָבוֹי שֶׁהָיָה בֵּינֵיהֶן שִׁתּוּף בְּמַאֲכָל אֶחָד לְעִנְיַן סְחוֹרָה כְּגוֹן שֶׁקָּנוּ יַיִן בְּשֻׁתָּפוּת אוֹ שֶׁמֶן אוֹ דְּבַשׁ וְכַיּוֹצֵא בָּהֶן אֵינָן צְרִיכִין שִׁתּוּף אַחֵר לְעִנְיַן שַׁבָּת אֶלָּא סוֹמְכִין עַל שִׁתּוּף שֶׁל סְחוֹרָה. וְהוּא שֶׁיִּהְיֶה הַמִּין שֶׁהֵן שֻׁתָּפִין בּוֹ מִין אֶחָד וּבִכְלִי אֶחָד. אֲבָל אִם הָיָה אֶחָד מֵהֶן שֻׁתָּף לָזֶה בְּיַיִן וּלְאַחֵר בְּשֶׁמֶן אוֹ שֶׁהָיָה הַכּל יַיִן וְהָיָה בִּשְׁנֵי כֵּלִים הֲרֵי אֵלּוּ צְרִיכִין שִׁתּוּף אַחֵר לְעִנְיַן שַׁבָּת:","אֶחָד מִבְּנֵי הַמָּבוֹי שֶׁבִּקֵּשׁ מֵחֲבֵרוֹ יַיִן אוֹ שֶׁמֶן קֹדֶם הַשַּׁבָּת וְלֹא נָתַן לוֹ בָּטַל הַשִּׁתּוּף. שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁאֵינָן כֻּלָּן כְּשֻׁתָּפִין שֶׁאֵין מַקְפִּידִין זֶה עַל זֶה. אֶחָד מִבְּנֵי הַמָּבוֹי שֶׁרָגִיל לְהִשְׁתַּתֵּף עִם בְּנֵי הַמָּבוֹי וְלֹא נִשְׁתַּתֵּף. בְּנֵי מָבוֹי נִכְנָסִין לְבֵיתוֹ וְנוֹטְלִין מִמֶּנּוּ שִׁתּוּף בְּעַל כָּרְחוֹ. וְאֶחָד מִבְּנֵי הַמָּבוֹי שֶׁאֵינוֹ רוֹצֶה לְהִשְׁתַּתֵּף כְּלָל עִם בְּנֵי הַמָּבוֹי כּוֹפִין אוֹתוֹ לְהִשְׁתַּתֵּף עִמָּהֶן:","אֶחָד מִבְּנֵי הַמָּבוֹי שֶׁהָיָה לוֹ אוֹצָר שֶׁל יַיִן אוֹ שֶׁמֶן וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה מְזַכֶּה מִמֶּנּוּ מְעַט לְכָל בְּנֵי הַמָּבוֹי לְהִשְׁתַּתֵּף בּוֹ וּמְעָרֵב בּוֹ עֲלֵיהֶם. וְאַף עַל פִּי שֶׁלֹּא הִפְרִישׁוֹ וְלֹא יִחֲדוֹ אֶלָּא הֲרֵי הוּא מְעֹרָב בָּאוֹצָר הֲרֵי זֶה שִׁתּוּף:","חָצֵר שֶׁיֵּשׁ לָהּ שְׁנֵי פְּתָחִים לִשְׁנֵי מְבוֹאוֹת אִם נִשְׁתַּתְּפָה עִם אֶחָד מֵהֶן בִּלְבַד נֶאֶסְרָה בַּמָּבוֹי הַשֵּׁנִי וְאֵינָהּ מוֹצִיאָה וּמַכְנִיסָה בּוֹ. לְפִיכָךְ אִם זִכָּה אֶחָד בְּשִׁתּוּף לְכָל בְּנֵי הַמָּבוֹי וְשִׁתֵּף עֲלֵיהֶן צָרִיךְ לְהוֹדִיעַ לְאַנְשֵׁי הֶחָצֵר זוֹ. שֶׁאֵינָן מִשְׁתַּתְּפִין אֶלָּא מִדַּעְתָּן שֶׁאֵינָהּ זְכוּת לָהֶן שֶׁמָּא בַּמָּבוֹי הַשֵּׁנִי רוֹצִים לְהִשְׁתַּתֵּף וְלֹא בָּזֶה:","אִשְׁתּוֹ שֶׁל אָדָם מְעָרֶבֶת לוֹ שֶׁלֹּא מִדַּעְתּוֹ וְהוּא שֶׁלֹּא יֶאֱסרוֹ עַל שְׁכֵנָיו. אֲבָל אִם אוֹסֵר אֵינָהּ מְעָרֶבֶת עָלָיו וְלֹא מִשְׁתַּתֶּפֶת עָלָיו אֶלָּא מִדַּעְתּוֹ. כֵּיצַד אוֹסֵר. כְּגוֹן שֶׁאָמַר אֵינִי מְעָרֵב עִמָּכֶם אוֹ אֵינִי מִשְׁתַּתֵּף עִמָּכֶם:","נִשְׁתַּתְּפוּ אַנְשֵׁי חָצֵר זוֹ עִם אֶחָד מִשְׁנִי הַמְּבוֹאוֹת אִם בְּמִין אֶחָד נִשְׁתַּתְּפוּ אֲפִלּוּ כָּלָה אוֹתוֹ הַמִּין הֲרֵי זֶה עוֹשֶׂה שִׁתּוּף אַחֵר וּמְזַכֶּה לָהֶן וְאֵינוֹ צָרִיךְ לְהוֹדִיעָם פַּעַם שְׁנִיָּה. וְאִם בִּשְׁנֵי מִינִין נִשְׁתַּתְּפוּ וְנִתְמַעֵט הָאֹכֶל מוֹסִיף וּמְזַכֶּה וְאֵינוֹ צָרִיךְ לְהוֹדִיעָן. וְאִם כָּלוּ מְזַכֶּה לָהֶם וְצָרִיךְ לְהוֹדִיעָם. נִתְוַסְּפוּ שְׁכֵנִים בֶּחָצֵר זוֹ מְזַכֶּה לָהֶם וְצָרִיךְ לְהוֹדִיעָם:","נִשְׁתַּתְּפָה חָצֵר זוֹ עִם בְּנֵי הַמָּבוֹי זֶה מִפֶּתַח זֶה וְעִם בְּנֵי הַמָּבוֹי הַשֵּׁנִי מִן הַפֶּתַח הָאַחֵר מֻתֶּרֶת עִם שְׁנֵיהֶן וְהֵן מֻתָּרִין עִמָּהּ וּשְׁנֵי הַמְּבוֹאוֹת אֲסוּרִין זֶה עִם זֶה. לֹא עֵרְבָה עִם אֶחָד מֵהֶם אוֹסֶרֶת עַל שְׁנֵיהֶן:","הָיְתָה חָצֵר זוֹ רְגִילָה בְּפֶתַח אֶחָד וְהַפֶּתַח הַשֵּׁנִי אֵינָהּ רְגִילָה. זֶה שֶׁרְגִילָה לְהִכָּנֵס וְלָצֵאת בּוֹ אוֹסֵר וְשֶׁאֵינָהּ רְגִילָה בּוֹ אֵינוֹ אוֹסֵר. עֵרְבָה עִם מָבוֹי שֶׁאֵינָהּ רְגִילָה בּוֹ הֻתַּר הַמָּבוֹי הָאַחֵר לְעַצְמוֹ וְאֵינוֹ צָרִיךְ לְעָרֵב עִמָּהּ:","עֵרְבוּ בְּנֵי הַמָּבוֹי שֶׁהִיא רְגִילָה בּוֹ לְעַצְמָן וְהִיא לֹא עֵרְבָה עִמּוֹ וְלֹא עִם בְּנֵי הַמָּבוֹי הָאַחֵר שֶׁאֵינָהּ רְגִילָה בּוֹ וְגַם לֹא עֵרְבוּ בְּנֵי הַמָּבוֹי שֶׁאֵינָהּ רְגִילָה בּוֹ. דּוֹחִין אוֹתָהּ אֵצֶל זֶה הַמָּבוֹי שֶׁאֵינָהּ רְגִילָה מִפְּנֵי שֶׁלֹּא עֵרֵב. הוֹאִיל וְהִיא לֹא עֵרְבָה וְהוּא לֹא עֵרֵב דּוֹחִין אוֹתָהּ אֶצְלוֹ כְּדֵי שֶׁלֹּא תֶּאֱסֹר עַל מָבוֹי זֶה שֶׁעֵרֵב לְעַצְמוֹ:","חָצֵר שֶׁיֵּשׁ לָהּ פֶּתַח לְמָבוֹי וּפֶתַח אַחֵר לְבִקְעָה אוֹ לְקַרְפָּף יֶתֶר מִבֵּית סָאתַיִם הוֹאִיל וְאָסוּר לְטַלְטֵל מֵחָצֵר לְאוֹתוֹ הַקַּרְפָּף אֵינוֹ סוֹמֵךְ אֶלָּא עַל פֶּתַח שֶׁל מָבוֹי לְפִיכָךְ אוֹסֵר עַל בְּנֵי הַמָּבוֹי עַד שֶׁיִּשְׁתַּתֵּף עִמָּהֶן. אֲבָל אִם הָיָה הַקַּרְפָּף בֵּית סָאתַיִם אוֹ פָּחוֹת אֵינוֹ אוֹסֵר עַל בְּנֵי הַמָּבוֹי שֶׁעַל הַפֶּתַח הַמְיֻחָד לוֹ סוֹמֵךְ הוֹאִיל וּמֻתָּר לְטַלְטֵל בְּכָל הַקַּרְפָּף:","אֶחָד מִבְּנֵי מָבוֹי שֶׁהָלַךְ לִשְׁבֹּת בְּמָבוֹי אַחֵר אֵינוֹ אוֹסֵר עֲלֵיהֶן. וְכֵן אֶחָד מִבְּנֵי מָבוֹי שֶׁבָּנָה מַצֵּבָה רְחָבָה אַרְבָּעָה טְפָחִים עַל פִּתְחוֹ אֵינוֹ אוֹסֵר עֲלֵיהֶן שֶׁהֲרֵי הִפְרִישׁ עַצְמוֹ מֵהֶן וְחָלַק רְשׁוּתוֹ:","אַנְשֵׁי מָבוֹי שֶׁנִּשְׁתַּתְּפוּ מִקְצָתָן וְשָׁכְחוּ מִקְצָתָן וְלֹא נִשְׁתַּתְּפוּ מְבַטְּלִין רְשׁוּתָן לְאֵלּוּ שֶׁנִּשְׁתַּתְּפוּ. וְדִינָם לְעִנְיַן בִּטּוּל רְשׁוּת כְּדִין אַנְשֵׁי חָצֵר שֶׁשָּׁכַח אֶחָד מֵהֶן אוֹ שְׁנַיִם וְלֹא עֵרְבוּ. וּכְבָר אָמַרְנוּ שֶׁכָּל אָדָם עִם אַנְשֵׁי בֵּיתוֹ הַסְּמוּכִים עַל שֻׁלְחָנוֹ כְּאִישׁ אֶחָד הֵן חֲשׁוּבִין בֵּין לְעֵרוּבֵי חֲצֵרוֹת בֵּין לְשִׁתּוּפֵי מְבוֹאוֹת:","מָבוֹי שֶׁעֵרְבוּ כָּל חֲצֵרוֹת שֶׁבּוֹ כָּל חָצֵר וְחָצֵר בִּפְנֵי עַצְמָהּ וְאַחַר כָּךְ נִשְׁתַּתְּפוּ כֻּלָּן בַּמָּבוֹי. שָׁכַח אֶחָד מִבְּנֵי הֶחָצֵר וְלֹא עֵרֵב עִם בְּנֵי חֲצֵרוֹ לֹא הִפְסִיד כְּלוּם. שֶׁהֲרֵי כֻּלָּם נִשְׁתַּתְּפוּ וְעַל הַשִּׁתּוּף סוֹמְכִין וְלֹא הִצְרִיכוּ לְעָרֵב בַּחֲצֵרוֹת עִם הַשִּׁתּוּף אֶלָּא שֶׁלֹּא לְשַׁכֵּחַ לַתִּינוֹקוֹת תּוֹרַת עֵרוּב וַהֲרֵי עֵרְבוּ בַּחֲצֵרוֹת. אֲבָל אִם שָׁכַח אֶחָד מִבְּנֵי הַמָּבוֹי וְלֹא נִשְׁתַּתֵּף אֲסוּרִים בַּמָּבוֹי וּמֻתָּרִין כָּל בְּנֵי חָצֵר לְטַלְטֵל בַּחֲצֵרָן שֶׁהַמָּבוֹי לַחֲצֵירוֹת כְּחָצֵר לַבָּתִּים:","נִשְׁתַּתְּפוּ בַּמָּבוֹי וְשָׁכְחוּ כֻּלָּן לְעָרֵב בָּחֲצֵרוֹת. אִם אֵין מַקְפִּידִין עַל פְּרוּסָתָן סוֹמְכִין עַל הַשִּׁתּוּף בַּשַּׁבָּת הָרִאשׁוֹנָה בִּלְבַד. וְאֵין מַתִּירִין לָהֶן דָּבָר זֶה אֶלָּא מִדֹּחַק:","מָבוֹי שֶׁלֹּא נִשְׁתַּתְּפוּ בּוֹ אִם עֵרְבוּ חֲצֵרוֹת עִם הַבָּתִּים אֵין מְטַלְטְלִין בּוֹ אֶלָּא בְּאַרְבַּע אַמּוֹת כְּכַרְמְלִית. מֵאַחַר שֶׁעֵרְבוּ חֲצֵרוֹת עִם הַבָּתִּים נַעֲשָׂה הַמָּבוֹי כְּאִלּוּ אֵינוֹ פָּתוּחַ לוֹ אֶלָּא בָּתִּים בִּלְבַד בְּלֹא חֲצֵרוֹת. וּלְפִיכָךְ אֵין מְטַלְטְלִין בְּכֻלָּן. וְאִם לֹא עֵרְבוּ אַנְשֵׁי הַחֲצֵרוֹת מְטַלְטְלִין בְּכֻלָּן כֵּלִים שֶׁשָּׁבְתוּ בְּתוֹכוֹ כְּחָצֵר שֶׁלֹּא עֵרְבוּ בָּהּ:","עוֹבֵד כּוֹכָבִים אוֹ צְדוֹקִי הַשָּׁרוּי בְּחָצֵר שֶׁבַּמָּבוֹי דִּינוֹ עִם בְּנֵי הַמָּבוֹי כְּדִינוֹ עִם בְּנֵי הֶחָצֵר שֶׁשּׂוֹכְרִים מִן הָעוֹבֵד כּוֹכָבִים אוֹ מֵאֶחָד מִבְּנֵי בֵּיתוֹ רְשׁוּתוֹ שֶׁבַּמָּבוֹי. אוֹ מְבַטֵּל לָהֶן הַצְּדוֹקִי. וְאִם הָיָה בַּמָּבוֹי עוֹבֵד כּוֹכָבִים וְיִשְׂרָאֵל אֶחָד אֵינוֹ צָרִיךְ שִׁתּוּף. וְדִין יִשְׂרָאֵל אֶחָד וְדִין רַבִּים שֶׁהֵן סוֹמְכִין עַל שֻׁלְחָן אֶחָד דִּין אֶחָד הוּא:","עוֹבֵד כּוֹכָבִים שֶׁהָיָה דָּר בַּמָּבוֹי אִם יֵשׁ לוֹ בַּחֲצֵרוֹ פֶּתַח אֶחָד לַבִּקְעָה אֵינוֹ אוֹסֵר עַל בְּנֵי הַמָּבוֹי. וַאֲפִלּוּ הָיָה פֶּתַח קָטָן אַרְבָּעָה עַל אַרְבָּעָה. וְאַף עַל פִּי שֶׁמּוֹצִיא גְּמַלִּים וּקְרוֹנוֹת דֶּרֶךְ הַפֶּתַח שֶׁבַּמָּבוֹי אֵינוֹ אוֹסֵר עֲלֵיהֶן שֶׁאֵין דַּעְתּוֹ אֶלָּא עַל פֶּתַח הַמְיֻחָד לוֹ שֶׁהוּא לַבִּקְעָה. וְכֵן אִם הָיָה פָּתוּחַ לְקַרְפָּף שֶׁהוּא יֶתֶר עַל בֵּית סָאתַיִם הֲרֵי זֶה כְּפָתוּחַ לַבִּקְעָה וְאֵינוֹ אוֹסֵר עֲלֵיהֶן. הָיָה בֵּית סָאתַיִם אוֹ פָּחוֹת אֵינוֹ סוֹמֵךְ עֲלֵיהֶן וְאוֹסֵר עֲלֵיהֶן עַד שֶׁיִּשְׂכְּרוּ מִמֶּנּוּ:","מָבוֹי שֶׁצִּדּוֹ אֶחָד עוֹבֵד כּוֹכָבִים וְצִדּוֹ אֶחָד יִשְׂרְאֵלִים וְהָיוּ חַלּוֹנוֹת פְּתוּחוֹת מֵחָצֵר לֶחָצֵר שֶׁל יִשְׂרָאֵל וְעֵרְבוּ כֻּלָּן דֶּרֶךְ חַלּוֹנוֹת. אַף עַל פִּי שֶׁנַּעֲשׂוּ כְּאַנְשֵׁי בַּיִת אֶחָד וּמֻתָּרִין לְהוֹצִיא וּלְהַכְנִיס דֶּרֶךְ חַלּוֹנוֹת הֲרֵי אֵלּוּ אֲסוּרִין לְהִשְׁתַּמֵּשׁ בַּמָּבוֹי דֶּרֶךְ פְּתָחִים עַד שֶׁיִּשְׂכְּרוּ מִן הָעוֹבֵד כּוֹכָבִים. שֶׁאֵין נַעֲשִׂים כְּיָחִיד בִּמְקוֹם עוֹבֵד כּוֹכָבִים:","כֵּיצַד מִשְׁתַּתְּפִין בַּמְּדִינָה. כָּל חָצֵר וְחָצֵר מְעָרֶבֶת לְעַצְמָהּ שֶׁלֹּא לְשַׁכֵּחַ הַתִּינוֹקוֹת. וְאַחַר כָּךְ מִשְׁתַּתְּפִין כָּל אַנְשֵׁי הַמְּדִינָה כְּדֶרֶךְ שֶׁמִּשְׁתַּתְּפִין בַּמָּבוֹי. וְאִם הָיְתָה הַמְּדִינָה קִנְיַן יָחִיד אֲפִלּוּ נַעֲשֵׂית שֶׁל רַבִּים מִשְׁתַּתְּפִין כֻּלָּן שִׁתּוּף אֶחָד וִיטַלְטְלוּ בְּכָל הַמְּדִינָה. וְכֵן אִם הָיְתָה שֶׁל רַבִּים וְיֵשׁ לָהּ פֶּתַח אֶחָד מִשְׁתַּתְּפִין כֻּלָּן שִׁתּוּף אֶחָד:","אֲבָל אִם הָיְתָה שֶׁל רַבִּים וְיֵשׁ לָהּ שְׁנֵי פְּתָחִים שֶׁהָעָם נִכְנָסִין בָּזֶה וְיוֹצְאִין בָּזֶה אֲפִלּוּ נַעֲשֵׂית שֶׁל יָחִיד אֵין מְעָרְבִין אֶת כֻּלָּהּ אֶלָּא מַנִּיחִין מִמֶּנָּה מָקוֹם אֶחָד אֲפִלּוּ בַּיִת אֶחָד בְּחָצֵר אַחַת וּמִשְׁתַּתְּפִין הַשְּׁאָר. וְיִהְיוּ אֵלּוּ הַמִּשְׁתַּתְּפִין כֻּלָּן מֻתָּרִין בְּכָל הַמְּדִינָה חוּץ מֵאוֹתוֹ מָקוֹם שֶׁשִּׁיְּרוּ. וְיִהְיוּ אוֹתָן הַנִּשְׁאָרִים מֻתָּרִין בִּמְקוֹמָן בַּשִּׁתּוּף שֶׁעוֹשִׂין לְעַצְמָן אִם הָיוּ הַנִּשְׁאָרִים רַבִּים. וַאֲסוּרִין לְטַלְטֵל בִּשְׁאָר כָּל הַמְּדִינָה:","וְדָבָר זֶה מִשּׁוּם הֶכֵּר הוּא כְּדֵי שֶׁיֵּדְעוּ שֶׁהָעֵרוּב הִתִּיר לָהֶן לְטַלְטֵל בִּמְדִינָה זוֹ שֶׁרַבִּים בּוֹקְעִין בָּהּ. שֶׁהֲרֵי הַמָּקוֹם שֶׁנִּשְׁאַר וְלֹא נִשְׁתַּתֵּף עִמָּהֶן אֵין מְטַלְטְלִין בּוֹ אֶלָּא אֵלּוּ לְעַצְמָן וְאֵלּוּ לְעַצְמָן:","מְדִינָה שֶׁל רַבִּים שֶׁיֵּשׁ לָהּ פֶּתַח אֶחָד וְסֻלָּם בְּמָקוֹם אֶחָד מְעָרְבִין אֶת כֻּלָּהּ וְאֵינָהּ צְרִיכָה שִׁיּוּר שֶׁאֵין הַסֻּלָּם שֶׁבַּחוֹמָה חָשׁוּב כְּפֶתַח. הַבָּתִּים שֶׁמַּנִּיחִין אוֹתוֹ שִׁיּוּר אַף עַל פִּי שֶׁאֵינָן פְּתוּחִין לָעִיר אֶלָּא אֲחוֹרֵיהֶן לָעִיר וּפְנֵיהֶם לַחוּץ עוֹשִׂין אוֹתוֹ שִׁיּוּר וּמְעָרְבִין אֶת הַשְּׁאָר:","הַמְזַכֶּה בְּשִׁתּוּף לִבְנֵי הַמְּדִינָה. אִם עֵרְבוּ כֻּלָּן עֵרוּב אֶחָד אֵינוֹ צָרִיךְ לְהוֹדִיעָן שֶׁזְּכוּת הוּא לָהֶן. וְדִין מִי שֶׁשָּׁכַח וְלֹא נִשְׁתַּתֵּף עִם בְּנֵי הַמְּדִינָה אוֹ מִי שֶׁהָלַךְ לִשְׁבֹּת בְּעִיר אַחֶרֶת אוֹ עוֹבֵד כּוֹכָבִים שֶׁהָיָה עִמָּהֶן בַּמְּדִינָה דִּין הַכּל כְּדִינָם בְּחָצֵר וּמָבוֹי:","מְדִינָה שֶׁנִּשְׁתַּתְּפוּ כָּל יוֹשְׁבֶיהָ חוּץ מִמָּבוֹי אֶחָד הֲרֵי זֶה אוֹסֵר עַל כֻּלָּן. וְאִם בָּנוּ מַצֵּבָה עַל פֶּתַח הַמָּבוֹי אֵינוֹ אוֹסֵר לְפִיכָךְ אֵין מְעָרְבִין מְדִינָה לַחֲצָאִין אֶלָּא אוֹ כֻּלָּהּ אוֹ מָבוֹי מָבוֹי. וּבוֹנֶה כָּל מָבוֹי וּמָבוֹי מַצֵּבָה עַל פִּתְחוֹ אִם רָצָה לַחֲלֹק רְשׁוּתוֹ מֵהֶן כְּדֵי שֶׁלֹּא יֶאֱסֹר עַל שְׁאָר הַמְּבוֹאוֹת:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 1":["עֶשְׂרִים וְאַרְבַּע מַתָּנוֹת נִתְּנוּ לַכֹּהֲנִים וְכֻלָּן מְפֹרָשִׁין בַּתּוֹרָה. וְעַל כֻּלָּן נִכְרְתָה בְּרִית לְאַהֲרֹן. וְכָל כֹּהֵן שֶׁאֵינוֹ מוֹדֶה בָּהֶן אֵין לוֹ חֵלֶק בַּכֹּהֲנִים וְאֵין נוֹתְנִין לוֹ מַתָּנָה מֵהֶן:","וְכָל הָאוֹכֵל מַתָּנָה שֶׁיֵּשׁ בָּהּ קְדֻשָּׁה מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לֶאֱכל כָּךְ וְכָךְ:","שְׁמוֹנֶה מַתָּנוֹת מֵהֶם אֵין אוֹכְלִים אוֹתָן הַכֹּהֲנִים אֶלָּא בַּמִּקְדָּשׁ לְפָנִים מֵחוֹמַת הָעֲזָרָה. וְחָמֵשׁ מַתָּנוֹת אֵין אוֹכְלִין אוֹתָן אֶלָּא בִּירוּשָׁלַיִם לְפָנִים מֵחוֹמַת הָעִיר. וְחָמֵשׁ מַתָּנוֹת אֵין זוֹכִין בָּהֶן מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד. וְחָמֵשׁ מַתָּנוֹת זוֹכִין בָּהֶן בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּמַתָּנָה אַחַת זוֹכִין בָּהּ מִן הַמִּקְדָּשׁ:","מַה הֵן הַשְּׁמוֹנֶה שֶׁאֵין נֶאֱכָלִין אֶלָּא בַּמִּקְדָּשׁ. בְּשַׂר הַחַטָּאת אֶחָד חַטַּאת הָעוֹף וְאֶחָד חַטַּאת הַבְּהֵמָה. וּבְשַׂר הָאָשָׁם בֵּין תָּלוּי בֵּין וַדַּאי. וְזִבְחֵי שַׁלְמֵי צִבּוּר. וּמוֹתָר הָעֹמֶר. וּשְׁיָרֵי מְנָחוֹת יִשְׂרָאֵל. וּשְׁתֵּי הַלֶּחֶם. וְלֶחֶם הַפָּנִים. וְלוֹג שֶׁמֶן שֶׁל מְצֹרָע. אֵלּוּ אֵינָן נֶאֱכָלִין אֶלָּא בַּמִּקְדָּשׁ:","וּמַה הֵן הֶחָמֵשׁ שֶׁאֵינָן נֶאֱכָלִין אֶלָּא בִּירוּשָׁלַיִם. חָזֶה וְשׁוֹק שֶׁל שְׁלָמִים. וְהַמּוּרָם מִן הַתּוֹדָה. וְהַמּוּרָם מֵאֵיל נָזִיר. וּבְכוֹר בְּהֵמָה טְהוֹרָה. וְהַבִּכּוּרִים. אֵלּוּ אֵינָן נֶאֱכָלִין אֶלָּא בִּירוּשָׁלַיִם:","וּמַה הֵן הֶחָמֵשׁ שֶׁבְּאֶרֶץ יִשְׂרָאֵל. הַתְּרוּמָה. וּתְרוּמַת מַעֲשֵׂר. וְהַחַלָּה. וּשְׁלָשְׁתָּן קֹדֶשׁ. וְרֵאשִׁית הַגֵּז. וּשְׂדֵה אֲחֻזָּה. וּשְׁנֵיהֶן חֻלִּין. אֵלּוּ אֵינָן זוֹכִין בָּהֶן מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל. וְאֵין אוֹכְלִין תְּרוּמוֹת וְחַלּוֹת שֶׁל אֶרֶץ יִשְׂרָאֵל אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל:","וּמַה הֵן הֶחָמֵשׁ שֶׁזּוֹכִין בָּהֶן הַכֹּהֲנִים בְּכָל מָקוֹם. הַמַּתָּנוֹת. וּפִדְיוֹן הַבֵּן. וּפֶטֶר חֲמוֹר. וְגֵזֶל הַגֵּר. וְהַחֲרָמִים. וַחֲמִשְּׁתָּן חֻלִּין לְכָל דָּבָר:","וְהַמַּתָּנָה שֶׁזּוֹכִין בָּהּ מִן הַמִּקְדָּשׁ הִיא עוֹרוֹת הָעוֹלוֹת. וְהוּא הַדִּין לִשְׁאָר עוֹרוֹת קָדְשֵׁי הַקָּדָשִׁים כֻּלָּן לַכֹּהֲנִים:","הַשְּׁמוֹנֶה מַתָּנוֹת שֶׁאֵינָן נֶאֱכָלִין אֶלָּא בַּמִּקְדָּשׁ כֻּלָּן קָדְשֵׁי קָדָשִׁים הֵן וְאֵינָן נֶאֱכָלִים אֶלָּא לְזִכְרֵי כְּהֻנָּה כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. וּבָהֶן נֶאֱמַר (ויקרא ו כב) \"כָּל זָכָר בַּכֹּהֲנִים יֹאכַל אֹתוֹ\" וְגוֹ':","הֶחָמֵשׁ שֶׁבִּירוּשָׁלַיִם הֵן קָדָשִׁים קַלִּים וְנֶאֱכָלִין לִזְכָרִים וְלִנְקֵבוֹת וּבָהֶן נֶאֱמַר (במדבר יח יא) \"לְךָ נְתַתִּים וּלְבָנֶיךָ וְלִבְנֹתֶיךָ אִתְּךָ לְחָק עוֹלָם\". וְאַף עַל פִּי כֵן אֵין נִתָּנִין אֶלָּא לְזִכְרֵי כְּהֻנָּה שֶׁהֲרֵי לְאַנְשֵׁי מִשְׁמָר הֵן. וְהַבְּכוֹר מַקְרִיבִין חֶלְבּוֹ וְדָמוֹ וְאֵין מַקְרִיבוֹ אֶלָּא אִישׁ. וְכֵן עוֹרוֹת קָדְשֵׁי הַקָּדָשִׁים. וּשְׂדֵה אֲחֻזָּה. וְהַחֲרָמִים. וְגֵזֶל הַגֵּר. אֵין זוֹכִין בָּהֶן אֶלָּא אַנְשֵׁי מִשְׁמָר כְּמוֹ שֶׁיִּתְבָּאֵר. וְכֵן פִּדְיוֹן הַבֵּן לְזִכְרֵי כְּהֻנָּה שֶׁכֵּן נֶאֱמַר בּוֹ (במדבר ג מח) \"וְנָתַתָּ הַכֶּסֶף לְאַהֲרֹן וּלְבָנָיו\". וּפֶטֶר חֲמוֹר לְזִכְרֵי כְּהֻנָּה. שֶׁדִּין הַבְּכוֹרוֹת כֻּלָּן שָׁוֶה לִזְכָרִים וְלֹא לִנְקֵבוֹת:","הִנֵּה לָמַדְתָּ שֶׁהַמַּתָּנוֹת שֶׁנִּתָּנִין לִנְקֵבוֹת כִּזְכָרִים חָמֵשׁ מַתָּנוֹת. תְּרוּמָה. וּתְרוּמַת מַעֲשֵׂר. וְחַלָּה. וּמַתְּנוֹת בְּהֵמָה. וְרֵאשִׁית הַגֵּז. וּמִנַּיִן אַתָּה אוֹמֵר שֶׁרֵאשִׁית הַגֵּז נִתֶּנֶת לַכֹּהֲנוֹת שֶׁנֶּאֱמַר (דברים יח ד) \"רֵאשִׁית דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וְרֵאשִׁית גֵּז צֹאנְךָ תִּתֶּן לּוֹ\". מָה רֵאשִׁית דָּגָן נִתֶּנֶת לִנְקֵבוֹת כִּזְכָרִים אַף רֵאשִׁית הַגֵּז:","מָנוּ חֲכָמִים מַתָּנוֹת אֵלּוּ עַל דֶּרֶךְ אַחֶרֶת וְאָמְרוּ עֶשְׂרִים וְאַרְבַּע מַתְּנוֹת כְּהֻנָּה נִתְּנוּ לְאַהֲרֹן וְאֵלּוּ הֵן. עֶשֶׂר בַּמִּקְדָּשׁ. אַרְבַּע בִּירוּשָׁלַיִם. וְעֶשֶׂר בַּגְּבוּלִין:","עֶשֶׂר בַּמִּקְדָּשׁ. חַטַּאת בְּהֵמָה. וְחַטַּאת הָעוֹף. אָשָׁם. וְאָשָׁם תָּלוּי. זִבְחֵי שַׁלְמֵי צִבּוּר. וְלֹג שֶׁמֶן שֶׁל מְצֹרָע. שְׁתֵּי הַלֶּחֶם. וְלֶחֶם הַפָּנִים. שְׁיָרֵי מְנָחוֹת. וּמוֹתַר הָעֹמֶר:","אַרְבַּע בִּירוּשָׁלַיִם. הַבְּכוֹר. וְהַבִּכּוּרִים. וּמוּרָם מִתּוֹדָה וְאֵיל נָזִיר. וְעוֹרוֹת קָדָשִׁים:","עֶשֶׂר בַּגְּבוּלִין. תְּרוּמָה. וּתְרוּמַת מַעֲשֵׂר. וְחַלָּה. וְרֵאשִׁית הַגֵּז. וְהַמַּתָּנוֹת. וּפִדְיוֹן הַבֵּן. וּפִדְיוֹן פֶּטֶר חֲמוֹר. שְׂדֵה חֲרָמִים. וּשְׂדֵה אֲחֻזָּה. וְגֵזֶל הַגֵּר. וּלְפִי חֶשְׁבּוֹן זֶה חַשֵּׁב כָּל הַמּוּרָם מִקָּדָשִׁים קַלִּים מַתָּנָה אַחַת. וְהֵן חָזֶה וְשׁוֹק הַמּוּרָם מִכָּל זֶבַח שְׁלָמִים עִם הַלֶּחֶם הַמּוּרָם עִמָּהֶם [אִם הָיָה תּוֹדָה. עִם הַזְּרוֹעַ הַמּוּרֶמֶת מֵאֵיל נָזִיר עִם הַלֶּחֶם הַמּוּרָם עִמָּהּ] עִם חָזֶה וְשׁוֹק. הוֹאִיל וּשְׁלָשְׁתָּן שְׁלָמִים הֵן חֲשֹׁב הַמּוּרָם מֵהֶם מַתָּנָה אַחַת:","כָּל הַמַּתָּנוֹת שֶׁהֵן תְּלוּיוֹת בַּקָּרְבָּנוֹת תִּתְבָּאֵר כָּל אַחַת וְאַחַת בִּמְקוֹמָהּ בְּהִלְכוֹת קָרְבָּנוֹת. וְכֵן גֵּזֶל הַגֵּר יִתְבָּאֵר בְּהִלְכוֹת גְּזֵלָה. וּכְבָר בֵּאַרְנוּ דִּין שְׂדֵה אֲחֻזָּה וְדִין הַחֲרָמִים בְּהִלְכוֹת עֶרְכִין. וְדִין תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר בְּהִלְכוֹת תְּרוּמוֹת. וּבַהֲלָכוֹת אֵלּוּ אֲבָאֵר מִשְׁפְּטֵי הַמַּתָּנוֹת שֶׁאֵין תְּלוּיִין בְּקָרְבָּנוֹת. וְהֵן: הַבִּכּוּרִים. וְהַחַלָּה. וְהַמַּתָּנוֹת. וְרֵאשִׁית הַגֵּז. וּפִדְיוֹן הַבֵּן. וּפֶטֶר חֲמוֹר:"],"Mishneh Torah, Firstlings 1":["מִצְוַת עֲשֵׂה לְהַפְרִישׁ כָּל פֶּטֶר רֶחֶם הַזְּכָרִים בֵּין בָּאָדָם בֵּין בִּבְהֵמָה טְהוֹרָה בֵּין מִמִּין הַחֲמוֹר. בֵּין שֶׁהָיוּ שְׁלֵמִים בֵּין שֶׁהָיוּ טְרֵפוֹת. שֶׁנֶּאֱמַר (שמות יג ב) \"קַדֵּשׁ לִי כָל בְּכוֹר פֶּטֶר כָּל רֶחֶם בִּבְנֵי יִשְׂרָאֵל בָּאָדָם וּבַבְּהֵמָה\". וְכֻלָּן לַכֹּהֲנִים:","בְּכוֹר אָדָם וּבְכוֹר חֲמוֹר נִפְדִּים וּפִדְיוֹנָם לַכֹּהֲנִים. וּבְכוֹר בְּהֵמָה טְהוֹרָה נִשְׁחָט בָּעֲזָרָה כִּשְׁאָר קָדָשִׁים קַלִּים. זוֹרְקִין דָּמוֹ וּמַקְטִיר אֵימוּרָיו כְּמוֹ שֶׁבֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת וּשְׁאָר הַבָּשָׂר נֶאֱכָל לַכֹּהֲנִים שֶׁנֶּאֱמַר (במדבר יח טו) \"אַךְ פָּדֹה תִפְדֶּה אֵת בְּכוֹר הָאָדָם וְאֵת בְּכוֹר הַבְּהֵמָה הַטְּמֵאָה תִּפְדֶּה\" (במדבר יח יז) \"אַךְ בְּכוֹר שׁוֹר\" (במדבר יח יז) \"לֹא תִפְדֶּה קֹדֶשׁ הֵם\" (במדבר יח יח) \"וּבְשָׂרָם יִהְיֶה לָּךְ\":","בְּכוֹר בְּהֵמָה טְהוֹרָה שֶׁהוּא בַּעַל מוּם בֵּין שֶׁנּוֹלַד בְּמוּמוֹ בֵּין שֶׁנָּפַל בּוֹ מוּם אַחַר שֶׁהָיָה תָמִים הֲרֵי הוּא לַכֹּהֵן אִם רָצָה אוֹכְלוֹ בְּכָל מָקוֹם אוֹ מוֹכְרוֹ אוֹ מַאֲכִילוֹ לְמִי שֶׁיִּרְצֶה אֲפִלּוּ לְנָכְרִי מִפְּנֵי שֶׁהוּא חֻלִּין. שֶׁנֶּאֱמַר (דברים טו כא) \"וְכִי יִהְיֶה בוֹ מוּם פִּסֵּחַ אוֹ עִוֵּר\" וְגוֹ' (דברים טו כב) \"הַטָּמֵא וְהַטָּהוֹר יַחְדָּו יֹאכֲלֶנּוּ כַּצְּבִי וְכָאַיָּל\" וַהֲרֵי הוּא נִכְסֵי כֹּהֵן:","מִצְוָה לְהַקְדִּישׁ בְּכוֹר בְּהֵמָה טְהוֹרָה וְיֹאמַר הֲרֵי זֶה קֹדֶשׁ שֶׁנֶּאֱמַר (דברים טו יט) \"תַּקְדִּישׁ לַה' אֱלֹהֶיךָ\" וְאִם לֹא הִקְדִּישׁוֹ הֲרֵי זֶה מִתְקַדֵּשׁ מֵאֵלָיו וּקְדֻשָּׁתוֹ מֵרֶחֶם הִיא:","מִצְוַת בְּכוֹר בְּהֵמָה טְהוֹרָה נוֹהֶגֶת בָּאָרֶץ וּבְחוּצָה לָאָרֶץ וְאֵין מְבִיאִין בְּכוֹרוֹת מִחוּצָה לָאָרֶץ לָאָרֶץ שֶׁנֶּאֱמַר (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\" (דברים יד כג) \"מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנֶךָ\". מִמָּקוֹם שֶׁאַתָּה מֵבִיא מַעֲשַׂר דָּגָן אַתָּה מֵבִיא בְּכוֹר בָּקָר וָצֹאן וּמִמָּקוֹם שֶׁאֵין אַתָּה מֵבִיא מַעֲשַׂר דָּגָן אִי אַתָּה מֵבִיא בְּכוֹר בָּקָר וָצֹאן אֶלָּא הֲרֵי הוּא כְּחֻלִּין וְיֵאָכֵל בְּמוּמוֹ. וְאִם הֵבִיא אֵין מְקַבְּלִין מִמֶּנּוּ וְלֹא יִקָּרֵב אֶלָּא יֵאָכֵל בְּמוּמוֹ:","מִצְוָה זוֹ נוֹהֶגֶת בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת כְּמוֹ מַעֲשַׂר דָּגָן. וְאֵינָהּ נוֹהֶגֶת בְּמֻקְדָּשִׁין כְּשֶׁהֵן בִּקְדֻשָּׁתָן קֹדֶם שֶׁיִּפָּדוּ בֵּין קָדְשֵׁי מִזְבֵּחַ בֵּין קָדְשֵׁי בֶּדֶק הַבַּיִת:","הַכּל חַיָּבִין בִּבְכוֹר בְּהֵמָה טְהוֹרָה כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים. וְאַף עַל פִּי שֶׁהַבְּכוֹר לַכֹּהֵן אִם נוֹלַד לוֹ בְּכוֹר מַקְרִיב דָּמוֹ וְאֵימוּרָיו כְּמוֹ שֶׁבֵּאַרְנוּ וְאוֹכֵל שְׁאָר הַבָּשָׂר בְּתוֹרַת בְּכוֹר. שֶׁנֶּאֱמַר (דברים טו יט) \"כָּל הַבְּכוֹר אֲשֶׁר יִוָּלֵד בִּבְקָרְךָ וּבְצֹאנְךָ\" וְגוֹ'. אֲבָל בְּכוֹר אָדָם וּבְכוֹר בְּהֵמָה טְמֵאָה כֹּהֲנִים וּלְוִיִּים פְּטוּרִין כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַתְּנוֹת כְּהֻנָּה:","הַבְּכוֹר נֶאֱכָל בְּתוֹךְ שְׁנָתוֹ בֵּין תָמִים בֵּין בַּעַל מוּם שֶׁנֶּאֱמַר (דברים טו כ) \"לִפְנֵי ה' אֱלֹהֶיךָ תֹּאכֲלֶנּוּ שָׁנָה בְּשָׁנָה\" (דברים טו כא) \"וְכִי יִהְיֶה בּוֹ מוּם\" (דברים טו כב) \"בִּשְׁעָרֶיךָ תֹּאכֲלֶנּוּ\". וּמֵאֵימָתַי מוֹנֶה לוֹ. אִם תָּם הוּא מוֹנֶה לוֹ מִיּוֹם שְׁמִינִי שֶׁהוּא רָאוּי לְהַקְרָבָה וְאִם נוֹלַד בַּעַל מוּם מוֹנֶה לוֹ מִיּוֹם שֶׁנּוֹלַד. וְהוּא שֶׁכָּלוּ לוֹ חֳדָשָׁיו שֶׁהֲרֵי נִרְאֶה לַאֲכִילָה בְּיוֹם לֵידָתוֹ. אֲבָל אִם לֹא יָדַע בְּוַדַּאי שֶׁכָּלוּ לוֹ חֳדָשָׁיו מוֹנֶה לוֹ מִיּוֹם שְׁמִינִי:","נוֹלַד לוֹ מוּם בְּתוֹךְ שְׁנָתוֹ רַשַּׁאי לְקַיְּמוֹ כָּל שְׁנֵים עָשָׂר חֹדֶשׁ. נוֹלַד לוֹ מוּם בְּסוֹף שְׁנָתוֹ מֻתָּר לְקַיְּמוֹ שְׁלֹשִׁים יוֹם מִיּוֹם שֶׁנָּפַל בּוֹ הַמּוּם וְאַף עַל פִּי שֶׁהוּא מִתְאַחֵר לְאַחַר שְׁנָתוֹ. כֵּיצַד. כְּגוֹן שֶׁנָּפַל בּוֹ מוּם בַּחֲמִשָּׁה עָשָׂר יוֹם לִפְנֵי גְּמַר שְׁנָתוֹ מַשְׁלִימִין לוֹ חֲמִשָּׁה עָשָׂר אַחַר שְׁנָתוֹ. נוֹלָד לוֹ מוּם אַחַר שְׁנָתוֹ אֵינוֹ רַשַּׁאי לְקַיְּמוֹ אֶלָּא עַד שְׁלֹשִׁים יוֹם וְיֵאָכֵל:","הַבְּכוֹר בַּזְּמַן הַזֶּה מַנִּיחוֹ עַד שֶׁיִּפּל בּוֹ מוּם וְיֵאָכֵל:","וְעַד שֶׁלֹּא נִרְאֶה לְהַרְאוֹתוֹ לְחָכָם רַשַּׁאי לְקַיְּמוֹ שְׁתַּיִם וְשָׁלֹשׁ שָׁנִים. וּמִשֶּׁנִּרְאֶה לְהַרְאוֹתוֹ לְחָכָם. אִם נוֹלַד בּוֹ מוּם בְּתוֹךְ שְׁנָתוֹ רַשַּׁאי לְקַיְּמוֹ כָּל שְׁנֵים עָשָׂר חֹדֶשׁ. נוֹלַד אַחַר שְׁנָתוֹ מְקַיְּמוֹ שְׁלֹשִׁים יוֹם:","שָׁנָה שֶׁל בְּכוֹר הִיא שְׁנַת לְבָנָה תְּמִימָה שְׁנֵים עָשָׂר חֹדֶשׁ מִיּוֹם לְיוֹם. וְאִם הָיְתָה שָׁנָה מְעֻבֶּרֶת נִתְעַבְּרָה לוֹ וּמוֹנֶה לוֹ שְׁלֹשָׁה עָשָׂר חֹדֶשׁ. נוֹלְדוּ לוֹ שְׁנֵי טְלָאִים אֶחָד בַּחֲמִשָּׁה עָשָׂר שֶׁל אֲדָר הָרִאשׁוֹן וְאֶחָד בְּרֹאשׁ חֹדֶשׁ אֲדָר שֵׁנִי. זֶה שֶׁנּוֹלַד בְּרֹאשׁ חֹדֶשׁ אֲדָר שֵׁנִי כֵּיוָן שֶׁהִגִּיעַ יוֹם רִאשׁוֹן בַּאֲדָר שֶׁל שָׁנָה הַבָּאָה עָלְתָה לוֹ שָׁנָה וְזֶה שֶׁנּוֹלַד בַּחֲצִי אֲדָר רִאשׁוֹן לֹא עָלְתָה לוֹ שָׁנָה עַד חֲצִי אֲדָר שֶׁל שָׁנָה הַבָּאָה הוֹאִיל וְנוֹלַד בְּחֹדֶשׁ הָעִבּוּר מוֹנִין אוֹתוֹ לוֹ:","עָבַר וְאִחֵר הַבְּכוֹר לְאַחַר שְׁנָתוֹ אַף עַל פִּי שֶׁהוּא עוֹבֵר בְּלֹא תַּעֲשֶׂה אִם הָיָה תָּם הֲרֵי זֶה לֹא נִפְסַל אֶלָּא מַקְרִיבוֹ וְאִם הָיָה בַּעַל מוּם שׁוֹחֲטוֹ בְּכָל מָקוֹם שֶׁנֶּאֱמַר (דברים יד כג) \"מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנֶךָ\" מַקִּישׁ בְּכוֹר לְמַעֲשֵׂר מַה מַּעֲשֵׂר אֵינוֹ נִפְסַל מִשָּׁנָה לַחֲבֶרְתָּהּ אַף בְּכוֹר אֵינוֹ נִפְסַל מִשָּׁנָה לַחֲבֶרְתָּהּ:","אֵין נוֹתְנִין אֶת הַבְּכוֹר לַכֹּהֵן כְּשֶׁיִּוָּלֵד שֶׁאֵין זוֹ גְּדֻלָּה לַכֹּהֵן. אֶלָּא יְטַפֵּל בּוֹ בְּעָלָיו עַד שֶׁיַּגְדִּיל מְעַט וְיִתְּנֶנּוּ לַכֹּהֵן. וְעַד כַּמָּה יִשְׂרָאֵל חַיָּבִין לְהִטָּפֵל בַּבְּכוֹר. בְּהֵמָה דַּקָּה שְׁלֹשִׁים יוֹם וּבְגַסָּה חֲמִשִּׁים יוֹם. וְאִם אָמַר לוֹ הַכֹּהֵן תְּנֵהוּ לִי בְּתוֹךְ זְמַן זֶה וַאֲנִי אֲטַפֵּל לְעַצְמִי אֵינוֹ רַשַּׁאי לִתְּנוֹ לוֹ שֶׁזֶּה כְּמוֹ מְסַיֵּעַ עַל מַתְּנוֹתָיו וּכְבָר בֵּאַרְנוּ בִּתְרוּמוֹת שֶׁהַכֹּהֲנִים הַמְסַיְּעִין בְּבֵית הַגֳּרָנוֹת וּבְבֵית הַמִּטְבָּחַיִם וּבְתוֹךְ הָרוֹעִים אֵין נוֹתְנִין לָהֶם מַתְּנוֹתֵיהֶן בִּשְׂכָרָן:","הָיָה הַבְּכוֹר בַּעַל מוּם וְאָמַר לוֹ בְּתוֹךְ זְמַן זֶה תְּנֵהוּ לִי שֶׁאֹכֲלֶנּוּ עַתָּה. אוֹ שֶׁהָיָה תָמִים וְאָמַר לוֹ תְּנֵהוּ לִי בְּתוֹךְ זְמַן זֶה שֶׁאַקְרִיבֶנּוּ עַתָּה הֲרֵי זֶה נוֹתְנוֹ לוֹ. וְיֵרָאֶה לִי שֶׁהַבְּכוֹר נוֹתֵן לְכָל כֹּהֵן שֶׁיִּרְצֶה:","כֹּהֵן שֶׁאָכַל כְּזַיִת מִבְּכוֹר תָּמִים חוּץ לִירוּשָׁלַיִם לוֹקֶה מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנֶךָ\". וְכֵן זָר שֶׁאָכַל כְּזַיִת מִבְּכוֹר בֵּין לִפְנֵי זְרִיקָה בֵּין לְאַחַר זְרִיקָה לוֹקֶה. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה אַף לְזָר שֶׁאָכַל בְּכוֹר בֵּין לִפְנֵי זְרִיקָה בֵּין לְאַחַר זְרִיקָה:","הַבְּכוֹר אֵין פּוֹדִין אוֹתוֹ שֶׁנֶּאֱמַר (במדבר יח יז) \"אַךְ בְּכוֹר שׁוֹר אוֹ בְכוֹר כֶּשֶׂב אוֹ בְכוֹר עֵז לֹא תִפְדֶּה\". וְכֵן אֵין מוֹכְרִין אוֹתוֹ כְּשֶׁהוּא תָּם שֶׁכֵּיוָן שֶׁהוּא עוֹמֵד לְקָרְבָּן אֵין לַכֹּהֵן בּוֹ זְכוּת כְּדֵי לְמָכְרוֹ. וּבַזְּמַן הַזֶּה שֶׁאֵין בַּיִת הוֹאִיל וְהוּא עוֹמֵד לַאֲכִילָה הֲרֵי הוּא מֻתָּר לְמָכְרוֹ וְאַף עַל פִּי שֶׁהוּא תָמִים בֵּין לְכֹהֵן בֵּין לְיִשְׂרָאֵל:","בְּכוֹר בַּעַל מוּם יֵשׁ לַכֹּהֵן לְמָכְרוֹ בְּכָל זְמַן בֵּין לִפְנֵי הַבַּיִת בֵּין שֶׁלֹּא לִפְנֵי הַבַּיִת. בֵּין חַי בֵּין שָׁחוּט. וּכְשֶׁהוּא מוֹכֵר בְּשַׂר בְּכוֹר בַּעַל מוּם מוֹכְרוֹ בַּבַּיִת אֲבָל לֹא בַּשּׁוּק כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מִזְבֵּחַ אֲבָל בְּשַׂר בְּכוֹר תָּמִים אֵינוֹ נִמְכָּר מִפְּנֵי שֶׁהוּא בְּשַׂר קֹדֶשׁ. וְכֹהֲנִים שֶׁנִּמְנוּ עִם הַבְּכוֹר מֻתָּרִין לִשְׁקל מָנָה כְּנֶגֶד מָנָה:","הַמַּפְשִׁיט בְּכוֹר בַּעַל מוּם הֲרֵי זֶה מֻתָּר לְהַפְשִׁיטוֹ בְּאֵי זֶה דֶּרֶךְ שֶׁיִּרְצֶה. אִם רָצָה לְהַרְגִּיל מַרְגִּיל. וְכֵן שְׁאָר פְּסוּלֵי הַמֻּקְדָּשִׁין אִם רָצָה לְהַפְשִׁיט מִן הָרֶגֶל מַפְשִׁיט:"],"Mishneh Torah, Forbidden Foods 13":["הַלוֹקֵחַ בַּיִת אוֹ שֶׁשָּׂכָר בַּיִת בַּחֲצֵרוֹ שֶׁל עַכּוּ\"ם וּמִלְּאָהוּ יַיִן אִם הָיָה הַיִּשְׂרְאֵלִי דָּר בְּאוֹתָהּ חָצֵר אַף עַל פִּי שֶׁהַפֶּתַח פָּתוּחַ הַיַּיִן מֻתָּר. מִפְּנֵי שֶׁהָעַכּוּ\"ם מְפַחֵד תָּמִיד וְאוֹמֵר עַתָּה יִכָּנֵס לְבֵיתוֹ פִּתְאֹם וְיִמְצָא אוֹתִי בְּתוֹךְ בֵּיתוֹ. וְאִם הָיָה דָּר בְּחָצֵר אַחֶרֶת לֹא יֵצֵא עַד שֶׁיִּסְגֹּר הַבַּיִת וְיִהְיֶה הַמַּפְתֵּחַ וְהַחוֹתָם בְּיָדוֹ. וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יְזַיֵּף הָעַכּוּ\"ם מַפְתֵּחַ הַבַּיִת:","יָצָא וְלֹא סָגַר הַפֶּתַח אוֹ שֶׁסָּגַר וְהִנִּיחַ הַמַּפְתֵּחַ בְּיַד עַכּוּ\"ם הֲרֵי הַיַּיִן אָסוּר בִּשְׁתִיָּה. שֶׁמָּא נִכְנַס הָעַכּוּ\"ם וְנִסֵּךְ. שֶׁהֲרֵי אֵין הַיִּשְׂרְאֵלִי שָׁם. וְאִם אָמַר לוֹ אֱחֹז לִי מַפְתֵּחַ זֶה עַד שֶׁאָבוֹא הַיַּיִן מֻתָּר שֶׁלֹּא מָסַר לוֹ שְׁמִירַת הַבַּיִת אֶלָּא שְׁמִירַת הַמַּפְתֵּחַ:","עַכּוּ\"ם שֶׁשָּׂכַר יִשְׂרָאֵל לִדְרֹךְ לוֹ יֵינוֹ בְּטָהֳרָה כְּדֵי שֶׁיִּהְיֶה מֻתָּר לְיִשְׂרָאֵל וְיִקָּחוּהוּ מִמֶּנּוּ וְהָיָה הַיַּיִן בְּבֵיתוֹ שֶׁל עַכּוּ\"ם. אִם הָיָה יִשִׂרָאֵל זֵה שֵׁשּׁוֹמֵר הַיַּיִן דָּר בְּאוֹתָהּ חָצֵר הַיַּיִן מֻתָּר. וְאַף עַל פִּי שֶׁהַפֶּתַח פָּתוּחַ וְהַשּׁוֹמֵר נִכְנָס וְיוֹצֵא. וְאִם הָיָה הַשּׁוֹמֵר דָּר בְּחָצֵר אַחֶרֶת הַיַּיִן אָסוּר. וְאַף עַל פִּי שֶׁהַמַּפְתֵּחַ וְהַחוֹתָם בְּיַד יִשְׂרָאֵל. שֶׁכֵּיוָן שֶׁהַיַּיִן שֶׁל עַכּוּ\"ם וּבִרְשׁוּתוֹ אֵינוֹ מְפַחֵד לְזַיֵּף וּלְהִכָּנֵס לַבַּיִת וְיֹאמַר וִיהִי מָה אִם יֵדְעוּ בּוֹ לֹא יִקְחוּ מִמֶּנִּי:","אֲפִלּוּ כָּתַב הָעַכּוּ\"ם לְיִשְׂרָאֵל שֶׁנִּתְקַבֵּל מִמֶּנּוּ הַמָּעוֹת לִמְכֹּר לוֹ בָּהֶן יַיִן הוֹאִיל וְאֵין הַיִּשְׂרְאֵלִי יָכוֹל לְהוֹצִיאוֹ מֵרְשׁוּת הָעַכּוּ\"ם עַד שֶׁיִּתֵּן לוֹ הַמָּעוֹת הֲרֵי הוּא שֶׁל עַכּוּ\"ם וְאָסוּר. אֶלָּא אִם הָיָה הַשּׁוֹמֵר דָּר שָׁם בֶּחָצֵר. וְאֵין הַשּׁוֹמֵר צָרִיךְ לִהְיוֹת יוֹשֵׁב וּמְשַׁמֵּר תָּמִיד אֶלָּא נִכְנָס וְיוֹצֵא כְּמוֹ שֶׁבֵּאַרְנוּ. בֵּין בִּרְשׁוּת בַּעַל הַיַּיִן בֵּין בִּרְשׁוּת עַכּוּ\"ם אַחֵר:","הָיָה יַיִן זֶה הַטָּהוֹר שֶׁל עַכּוּ\"ם מֻנָּח בִּרְשׁוּת הָרַבִּים אוֹ בְּבַיִת הַפָּתוּחַ לִרְשׁוּת הָרַבִּים וְיִשְׂרָאֵל הוֹלְכִים וְשָׁבִים מֻתָּר. שֶׁעֲדַיִן לֹא נִכְנַס בִּרְשׁוּת הָעַכּוּ\"ם:","וְאַשְׁפָּה וְחַלּוֹן וְדֶקֶל אַף עַל פִּי שֶׁאֵין בּוֹ פֵּרוֹת הֲרֵי אֵלּוּ כִּרְשׁוּת הָרַבִּים. וְחָבִית יַיִן שָׁם וְעַכּוּ\"ם הַנִּמְצָא שָׁם אֵינוֹ אוֹסְרָהּ. וּבַיִת הַפָּתוּחַ לְשָׁם הֲרֵי הוּא כְּפָתוּחַ לִרְשׁוּת הָרַבִּים:","חָצֵר הַחֲלוּקָה בִּמְסִיפִים וְעַכּוּ\"ם בְּצַד זֶה וְיִשְׂרָאֵל בְּצַד אַחֵר. וְכֵן שְׁנֵי גַּגִּין שֶׁהָיָה גַּג יִשְׂרָאֵל לְמַעְלָה וְגַג הָעַכּוּ\"ם לְמַטָּה. אוֹ שֶׁהָיוּ זֶה בְּצַד זֶה וְיֵשׁ בֵּינֵיהֶן מְסִיפִים. אַף עַל פִּי שֶׁיַּד הָעַכּוּ\"ם מַגַּעַת לְחֵלֶק יִשְׂרָאֵל אֵינוֹ חוֹשֵׁשׁ מִשּׁוּם יֵין נֶסֶךְ וְלֹא מִשּׁוּם טָהֳרוֹת:","מֻתָּר לְיִשְׂרָאֵל לְהַפְקִיד יֵינוֹ בִּכְלִי סָתוּם בְּיַד עַכּוּ\"ם וְהוּא שֶׁיִּהְיֶה לוֹ בּוֹ שְׁנֵי סִימָנִין. וְזֶה הוּא הַנִּקְרָא חוֹתָם בְּתוֹךְ חוֹתָם. כֵּיצַד. סָתַם הֶחָבִית בִּכְלִי שֶׁאֵינוֹ מְהֻדָּק כְּדֶרֶךְ שֶׁסּוֹתְמִין כָּל אָדָם וְטָח בְּטִיט הֲרֵי זֶה חוֹתָם אֶחָד. הָיָה כְּלִי מְהֻדָּק וְטָח עָלָיו מִלְּמַעְלָה הֲרֵי זֶה חוֹתָם בְּתוֹךְ חוֹתָם. וְכֵן אִם צָר פִּי הַנּוֹד הֲרֵי זֶה חוֹתָם אֶחָד. הָפַךְ פִּי הַנּוֹד לְתוֹכוֹ וְצָר עָלָיו הֲרֵי זֶה חוֹתָם בְּתוֹךְ חוֹתָם. וְכֵן כָּל שִׁנּוּי שֶׁמְּשַׁנֶּה מִדְּבָרִים שֶׁאֵין דֶּרֶךְ כָּל אָדָם הֲרֵי הֵן כְּחוֹתָם אֶחָד וְהַטִּיחָה אוֹ הַקְּשִׁירָה חוֹתָם שֵׁנִי:","וְאִם הִפְקִיד בְּיַד עַכּוּ\"ם בְּחוֹתָם אֶחָד הֲרֵי זֶה אָסוּר בִּשְׁתִיָּה וּמֻתָּר בַּהֲנָיָה וְהוּא שֶׁיְּיַחֵד לוֹ קֶרֶן זָוִית:","יַיִן מְבֻשָּׁל וְהַשֵּׁכָר אוֹ יַיִן שֶׁעֵרְבוֹ עִם דְּבָרִים אֲחֵרִים כְּגוֹן דְּבַשׁ וְשֶׁמֶן וְכֵן הַחֹמֶץ וְהַגְּבִינָה וְהֶחָלָב וְכָל שֶׁאִסּוּרוֹ מִדִּבְרֵי סוֹפְרִים שֶׁהִפְקִידוֹ בְּיַד עַכּוּ\"ם אֵינוֹ צָרִיךְ שְׁנֵי חוֹתָמוֹת אֶלָּא חוֹתָם אֶחָד בִּלְבַד דַּיּוֹ. אֲבָל הַיַּיִן וְהַבָּשָׂר וַחֲתִיכַת דָּג שֶׁאֵין בָּהּ סִימָן שֶׁהִפְקִידָן בְּיַד עַכּוּ\"ם צְרִיכִין שְׁנֵי חוֹתָמוֹת:","יֵרָאֶה לִי שֶׁכָּל מָקוֹם שֶׁאָמַרְנוּ בְּעִנְיָן זֶה בְּיַיִן שֶׁלָּנוּ שֶׁהוּא אָסוּר בִּשְׁתִיָּה וּמֻתָּר בַּהֲנָיָה מִפְּנֵי צַד נְגִיעָה שֶׁנָּגַע בּוֹ הָעַכּוּ\"ם כְּשֶׁהָיָה הָעַכּוּ\"ם עוֹבֵד עַכּוּ\"ם. אֲבָל אִם הָיָה אִסּוּרוֹ בִּגְלַל עַכּוּ\"ם שֶׁאֵינוֹ עוֹבֵד עַכּוּ\"ם כְּגוֹן יִשְׁמְעֵאלִי שֶׁנָּגַע בַּיַּיִן שֶׁלָּנוּ שֶׁלֹּא בְּכַוָּנָה אוֹ שֶׁטִּפַּח עַל פִּי הֶחָבִית הֲרֵי זֶה מֻתָּר בִּשְׁתִיָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֲבָל הַמַּפְקִיד יַיִן בְּיַד גֵּר תּוֹשָׁב אוֹ שֶׁשְּׁלָחוֹ עִמּוֹ וְהִפְלִיג אוֹ שֶׁהֵנִיחַ בֵּיתוֹ פָּתוּחַ בַּחֲצַר גֵּר תּוֹשָׁב הֲרֵי זֶה אָסוּר בִּשְׁתִיָּה. שֶׁכָּל חֲשָׁשׁ שֶׁל חִלּוּף וְזִיּוּף יֵרָאֶה לִי שֶׁכָּל הָעַכּוּ\"ם שָׁוִים בּוֹ הוֹאִיל וְנַעֲשָׂה הַיַּיִן בִּרְשׁוּתָן נֶאֱסַר בִּשְׁתִיָּה עַל כָּל פָּנִים:","יֵשׁ דְּבָרִים שֶׁאֵין בָּהֶם אִסּוּר נִסּוּךְ כְּלָל וְאָסְרוּ אוֹתָם חֲכָמִים כְּדֵי לְהַרְחִיק מִן הַנִּסּוּךְ. וְאֵלּוּ הֵן. לֹא יִמְזֹג הָעַכּוּ\"ם הַמַּיִם לְתוֹךְ הַיַּיִן שֶׁבְּיַד יִשְׂרָאֵל שֶׁמָּא יָבוֹא לִצֹּק הַיַּיִן לְתוֹךְ הַמַּיִם. וְלֹא יוֹלִיךְ הָעַכּוּ\"ם עֲנָבִים לַגַּת שֶׁמָּא יָבוֹא לִדְרֹךְ אוֹ לִגַּע. וְלֹא יְסַיֵּעַ לְיִשְׂרָאֵל בְּשָׁעָה שֶׁמֵּרִיק מִכְּלִי לִכְלִי שֶׁמָּא יַנִּיחַ הַכְּלִי בְּיַד הָעַכּוּ\"ם וְנִמְצָא הַיַּיִן בָּא מִכֹּחוֹ. וְאִם סִיֵּעַ אוֹ מָזַג הַמַּיִם אוֹ הֵבִיא עֲנָבִים מֻתָּר:","וְכֵן מֻתָּר שֶׁיָּרִיחַ הָעַכּוּ\"ם בְּחָבִית שֶׁל יַיִן שֶׁלָּנוּ. וּמֻתָּר לְיִשְׂרָאֵל לְהָרִיחַ בְּחָבִית שֶׁל יֵין נֶסֶךְ וְאֵין בָּזֶה שֵׁם אִסּוּר שֶׁאֵין הָרֵיחַ כְּלוּם לְפִי שֶׁאֵין בּוֹ מַמָּשׁ:","כְּבָר בֵּאַרְנוּ שֶׁכָּל דָּבָר שֶׁהוּא אָסוּר בַּהֲנָיָה אִם עָבַר וּמָכְרוּ דָּמָיו מֻתָּרִין חוּץ מֵעַכּוּ\"ם וּמְשַׁמְּשֶׁיהָ וְתִקְרֹבֶת שֶׁלָּהּ וְיַיִן שֶׁנִּתְנַסֵּךְ לָהּ. וְהֶחְמִירוּ חֲכָמִים בִּסְתַם יֵינָם לִהְיוֹת דָּמָיו אֲסוּרִין כִּדְמֵי יַיִן שֶׁנִּתְנַסֵּךְ לְעַכּוּ\"ם. לְפִיכָךְ עַכּוּ\"ם שֶׁשָּׂכַר אֶת יִשְׂרָאֵל לַעֲשׂוֹת עִמּוֹ בְּיַיִן שְׂכָרוֹ אָסוּר:","וְכֵן הַשּׂוֹכֵר אֶת הַחֲמוֹר לְהָבִיא עָלָיו יַיִן אוֹ שֶׁשָּׂכַר סְפִינָה לְהָבִיא בָּהּ יַיִן שְׂכָרָן אָסוּר. אִם מָעוֹת נָתְנוּ לוֹ יוֹלִיכֵן לְיָם הַמֶּלַח. וְאִם נָתְנוּ לוֹ בִּשְׂכָרוֹ כְּסוּת אוֹ כֵּלִים אוֹ פֵּרוֹת הֲרֵי זֶה יִשְׂרֹף אוֹתָן וְיִקְבֹּר הָאֵפֶר כְּדֵי שֶׁלֹּא לֵהָנוֹת בּוֹ:","שָׂכַר לָעַכּוּ\"ם חֲמוֹר לִרְכֹּב עָלָיו וְהִנִּיחַ עָלָיו לוֹגִין שֶׁל יַיִן שְׂכָרוֹ מֻתָּר. שְׂכָרוֹ לְשַׁבֵּר כַּדֵּי יֵין נֶסֶךְ שְׂכָרוֹ מֻתָּר וְתָבוֹא עָלָיו בְּרָכָה מִפְּנֵי שֶׁמְּמַעֵט בְּתִפְלָה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל וְאָמַר לוֹ הַעֲבֵר לִי מֵאָה חָבִיּוֹת שֶׁל שֵׁכָר בְּמֵאָה פְּרוּטוֹת וְנִמְצָא אַחַת מֵהֶן יַיִן שְׂכָרוֹ כֻּלּוֹ אָסוּר:","אָמַר לוֹ הַעֲבֵר לִי חָבִית בִּפְרוּטָה חָבִית בִּפְרוּטָה וְהֶעֱבִיר וְנִמְצָא בֵּינֵיהֶן חָבִיּוֹת שֶׁל יַיִן. שְׂכַר חָבִיּוֹת שֶׁל יַיִן אָסוּר וּשְׁאָר שְׂכָרוֹ מֻתָּר:","אֻמְּנֵי יִשְׂרָאֵל שֶׁשָּׁלַח לָהֶם עַכּוּ\"ם חָבִית שֶׁל יַיִן בִּשְׂכָרָן מֻתָּר שֶׁיֹּאמְרוּ לוֹ תֵּן לָנוּ אֶת דָּמֶיהָ. וְאִם מִשֶּׁנִּכְנְסָה לִרְשׁוּתָן אָסוּר:","יִשְׂרָאֵל שֶׁהָיָה נוֹשֶׁה בְּעַכּוּ\"ם מָנֶה. הָלַךְ הָעַכּוּ\"ם וּמָכַר עַבוֹדָה זָרָה וְיֵין נֶסֶךְ וְהֵבִיא לוֹ דְּמֵיהֶן הֲרֵי זֶה מֻתָּר. וְאִם אָמַר לוֹ קֹדֶם שֶׁיִּמְכֹּר הַמְתֵּן לִי עַד שֶׁאֶמְכֹּר עַבוֹדָה זָרָה אוֹ יֵין נֶסֶךְ שֶׁיֵּשׁ לִי וְאָבִיא לְךָ. אַף עַל פִּי שֶׁהוּא סְתַם יֵינוֹ. וּמָכַר וְהֵבִיא לוֹ הֲרֵי זֶה אָסוּר. מִפְּנֵי שֶׁהַיִּשְׂרְאֵלִי רוֹצֶה בְּקִיּוּמוֹ כְּדֵי שֶׁיִּפְרַע מִמֶּנּוּ חוֹבוֹ:","וְכֵן גֵּר וְעַכּוּ\"ם שֶׁהָיוּ שֻׁתָּפִין וּבָאוּ לַחֲלֹק. אֵין הַגֵּר יָכוֹל לוֹמַר לָעַכּוּ\"ם טֹל אַתָּה עַבוֹדָה זָרָה וַאֲנִי מָעוֹת. אַתָּה יַיִן וַאֲנִי פֵּרוֹת שֶׁהֲרֵי רוֹצֶה בְּקִיּוּמָן כְּדֵי שֶׁיִּטּל כְּנֶגְדָּן. אֲבָל גֵּר וְעַכּוּ\"ם שֶׁיָּרְשׁוּ אֶת אֲבִיהֶן עַכּוּ\"ם יָכוֹל לוֹמַר לוֹ טֹל אַתָּה עַבוֹדָה זָרָה וַאֲנִי מָעוֹת. אַתָּה יַיִן וַאֲנִי שֶׁמֶן. קַל הוּא שֶׁהֵקֵלּוּ בִּירֻשַּׁת הַגֵּר כְּדֵי שֶׁלֹּא יַחֲזֹר לְסוּרוֹ. וְאִם מִשֶּׁבָּאוּ לִרְשׁוּת הַגֵּר אָסוּר:","יִשְׂרָאֵל שֶׁמָּכַר יֵינוֹ לְעַכּוּ\"ם פָּסַק עַד שֶׁלֹּא מָדַד לוֹ דָּמָיו מֻתָּרִין. שֶׁמִּשֶּׁפָּסַק סָמְכָה דַּעְתּוֹ וּמִשֶּׁמָּשַׁךְ קָנָה וְיֵין נֶסֶךְ אֵינוֹ נַעֲשֶׂה עַד שֶׁיִּגַּע בּוֹ. נִמְצָא בִּשְׁעַת מְכִירָה הָיָה מֻתָּר. מָדַד לוֹ עַד שֶׁלֹּא פָּסַק הַדָּמִים דָּמָיו אֲסוּרִין. שֶׁהֲרֵי לֹא סָמְכָה דַּעְתּוֹ אַף עַל פִּי שֶׁמָּשַׁךְ וְנִמְצָא כְּשֶׁנָּגַע עֲדַיִן לֹא סָמְכָה דַּעְתּוֹ לִקַּח וְנֶאֱסַר הַיַּיִן בִּנְגִיעָתוֹ וַהֲרֵי זֶה כְּמוֹכֵר סְתַם יֵינָם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁמָּדַד הַיִּשְׂרְאֵלִי לְכֵלָיו. אֲבָל אִם מָדַד לִכְלִי הָעַכּוּ\"ם אוֹ לִכְלִי יִשְׂרָאֵל שֶׁבְּיַד הָעַכּוּ\"ם צָרִיךְ לִקַּח אֶת הַדָּמִים וְאַחַר כָּךְ יִמְדֹּד. וְאִם מָדַד וְלֹא לָקַח דָּמִים אַף עַל פִּי שֶׁפָּסַק דָּמָיו אֲסוּרִים שֶׁמִּשֶּׁיַגִּיעַ לַכְּלִי נֶאֱסַר כִּסְתָם יֵינָם:","הַנּוֹתֵן דִּינָר לְחֶנְוָנִי עַכּוּ\"ם וְאָמַר לְפוֹעֲלוֹ הָעַכּוּ\"ם לֵךְ וּשְׁתֵה וֶאֱכל מִן הַחֶנְוָנִי וַאֲנִי מְחַשֵּׁב לוֹ הֲרֵי זֶה חוֹשֵׁשׁ שֶׁמָּא יִשְׁתֶּה יַיִן. שֶׁזֶּה כְּמִי שֶׁקָּנָה לוֹ יֵין נֶסֶךְ וְהִשְׁקָהוּ. וּכְנֶגֶד זֶה בִּשְׁבִיעִית אָסוּר כְּגוֹן שֶׁנָּתַן דִּינָר לְחֶנְוָנִי יִשְׂרָאֵל עַם הָאָרֶץ וְאָמַר לְפוֹעֲלוֹ הַיִּשְׂרְאֵלִי לֵךְ וֶאֱכל וַאֲנִי מְחַשֵּׁב לוֹ. וְאִם אָכַל הַפּוֹעֵל דָּבָר שֶׁאֵינוֹ מְעֵשָּׂר אָסוּר:","אֲבָל אִם אָמַר לָהֶם אִכְלוּ וּשְׁתוּ בְּדִינָר זֶה. אוֹ שֶׁאָמַר לָהֶם אִכְלוּ וּשְׁתוּ עָלַי מִן הַחֶנְוָנִי וַאֲנִי פּוֹרֵעַ אַף עַל פִּי שֶׁנִּשְׁתַּעְבֵּד הוֹאִיל וְלֹא נִתְיַחֵד שִׁעְבּוּדוֹ הֲרֵי זֶה מֻתָּר וְאֵינוֹ חוֹשֵׁשׁ לֹא מִשּׁוּם יֵין נֶסֶךְ וְלֹא מִשּׁוּם שְׁבִיעִית וְלֹא מִשּׁוּם מַעֲשֵׂר:","מֶלֶךְ שֶׁהָיָה מְחַלֵּק יֵינוֹ לָעָם וְלוֹקֵחַ מֵהֶן דָּמָיו כְּפִי מַה שֶּׁיִּרְצֶה. אַל יֹאמַר אָדָם לְעַכּוּ\"ם הֵא לְךָ מָאתַיִם זוּז וְהִכָּנֵס תַּחְתַּי בְּאוֹצַר הַמֶּלֶךְ כְּדֵי שֶׁיִּקַּח עַכּוּ\"ם הַיַּיִן שֶׁכָּתְבוּ בְּשֵׁם יִשְׂרָאֵל וְיִתֵּן הָעַכּוּ\"ם הַדָּמִים לַמֶּלֶךְ. אֲבָל אוֹמֵר לוֹ הֵא לְךָ מָאתַיִם זוּז וּמַלְּטֵנִי מִן הָאוֹצָר:","עַכּוּ\"ם שֶׁנָּגַע בְּיֵינוֹ שֶׁל יִשְׂרָאֵל לְאָנְסוֹ מֻתָּר לִמְכֹּר אוֹתוֹ יַיִן לְאוֹתוֹ הָעַכּוּ\"ם שֶׁאֲסָרוֹ לְבַדּוֹ. שֶׁכֵּיוָן שֶׁנִּתְכַּוֵּן זֶה הָעַכּוּ\"ם לְהַזִּיקוֹ וְלֶאֱסֹר יֵינוֹ הֲרֵי זֶה כְּמוֹ שֶׁשְּׁבָרוֹ אוֹ שְׂרָפוֹ שֶׁחַיָּב לְשַׁלֵּם. וְנִמְצְאוּ הַדָּמִים שֶׁלּוֹקֵחַ מִמֶּנּוּ דְּמֵי הַהֶזֵּק וְלֹא דְּמֵי הַמְּכִירָה:"],"Mishneh Torah, Forbidden Foods 9":["בָּשָׂר בְּחָלָב אָסוּר לְבַשְּׁלוֹ וְאָסוּר לְאָכְלוֹ מִן הַתּוֹרָה. וְאָסוּר בַּהֲנָאָה. וְקוֹבְרִין אוֹתוֹ. וְאֶפְרוֹ אָסוּר כְּאֵפֶר כָּל הַנִּקְבָּרִין. וּמִי שֶׁיְּבַשֵּׁל מִשְּׁנֵיהֶם כְּזַיִת כְּאֶחָד לוֹקֶה שֶׁנֶּאֱמַר (שמות כג יט) (שמות לד כו) (דברים יד כא) \"לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ\". וְכֵן הָאוֹכֵל כְּזַיִת מִשְּׁנֵיהֶם מֵהַבָּשָׂר וְהֶחָלָב שֶׁנִּתְבַּשְּׁלוּ כְּאֶחָד לוֹקֶה וְאַף עַל פִּי שֶׁלֹּא בִּשֵּׁל:","לֹא שָׁתַק הַכָּתוּב מִלֶּאֱסֹר הָאֲכִילָה אֶלָּא מִפְּנֵי שֶׁאָסַר הַבִּשּׁוּל כְּלוֹמַר וַאֲפִלּוּ בִּשּׁוּלוֹ אָסוּר וְאֵין צָרִיךְ לוֹמַר אֲכִילָתוֹ. כְּמוֹ שֶׁשָּׁתַק מִלֶּאֱסֹר הַבַּת מֵאַחַר שֶׁאָסַר בַּת הַבַּת:","אֵין אָסוּר מִן הַתּוֹרָה אֶלָּא בְּשַׂר בְּהֵמָה טְהוֹרָה בַּחֲלֵב בְּהֵמָה טְהוֹרָה שֶׁנֶּאֱמַר (שמות כג יט) (שמות לד כו) (דברים יד כא) \"לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ\". וּגְדִי הוּא כּוֹלֵל וְלַד הַשּׁוֹר וְלַד הַשֶּׂה וְלַד הָעֵז עַד שֶׁיִּפְרֹט וְיֹאמַר גְּדִי עִזִּים וְלֹא נֶאֱמַר גְּדִי בַּחֲלֵב אִמּוֹ אֶלָּא שֶׁדִּבֵּר הַכָּתוּב בַּהוֹוֶה. אֲבָל בְּשַׂר בְּהֵמָה טְהוֹרָה (שֶׁבִּשְּׁלוֹ) בַּחֲלֵב בְּהֵמָה טְמֵאָה. אוֹ בְּשַׂר בְּהֵמָה טְמֵאָה (שֶׁבִּשְּׁלוֹ) בַּחֲלֵב בְּהֵמָה טְהוֹרָה מֻתָּר לְבַשֵּׁל וּמֻתֶּרֶת בַּהֲנָיָה וְאֵין חַיָּבִין עַל אֲכִילָתוֹ מִשּׁוּם בָּשָׂר בְּחָלָב:","וְכֵן בְּשַׂר חַיָּה וְעוֹף בֵּין בַּחֲלֵב חַיָּה בֵּין בַּחֲלֵב בְּהֵמָה אֵינוֹ אָסוּר בַּאֲכִילָה מִן הַתּוֹרָה לְפִיכָךְ מֻתָּר לְבַשְּׁלוֹ וּמֻתָּר בַּהֲנָיָה. וְאָסוּר בַּאֲכִילָה מִדִּבְרֵי סוֹפְרִים כְּדֵי שֶׁלֹּא יִפְשְׁעוּ הָעָם וְיָבוֹאוּ לִידֵי אִסּוּר בָּשָׂר בְּחָלָב שֶׁל תּוֹרָה וְיֹאכְלוּ בְּשַׂר בְּהֵמָה טְהוֹרָה בַּחֲלֵב בְּהֵמָה טְהוֹרָה. שֶׁהֲרֵי אֵין מַשְׁמַע הַכָּתוּב אֶלָּא גְּדִי בַּחֲלֵב אִמּוֹ מַמָּשׁ. לְפִיכָךְ אָסְרוּ כָּל בָּשָׂר בְּחָלָב:","דָּגִים וַחֲגָבִים מֻתָּר לְאָכְלָן בְּחָלָב. וְהַשּׁוֹחֵט עוֹף וְנִמְצָא בּוֹ בֵּיצִים גְּמוּרוֹת מֻתָּר לְאָכְלָן בְּחָלָב:","הַמְעֻשָּׁן וְהַמְבֻשָּׁל בְּחַמֵּי טְבֶרְיָא וְכַיּוֹצֵא בָּהֶן אֵין לוֹקִין עָלָיו. וְכֵן הַמְבַשֵּׁל בָּשָׂר בְּמֵי חָלָב אוֹ בַּחֲלֵב מֵתָה אוֹ בַּחֲלֵב זָכָר אוֹ שֶׁבִּשֵּׁל דָּם בְּחָלָב פָּטוּר וְאֵינוֹ לוֹקֶה עַל אֲכִילָתוֹ מִשּׁוּם בָּשָׂר בְּחָלָב. אֲבָל הַמְבַשֵּׁל בְּשַׂר מֵתָה אוֹ חֵלֶב וְכַיּוֹצֵא בָּהֶן בְּחָלָב לוֹקֶה עַל בִּשּׁוּלוֹ וְאֵינוֹ לוֹקֶה עַל אֲכִילָתוֹ מִשּׁוּם בָּשָׂר בְּחָלָב. שֶׁאֵין אִסּוּר בָּשָׂר בְּחָלָב חָל עַל אִסּוּר נְבֵלָה אוֹ אִסּוּר חֵלֶב. שֶׁאֵין כָּאן לֹא אִסּוּר כּוֹלֵל וְלֹא אִסּוּר מוֹסִיף וְלֹא אִסּוּר בַּת אַחַת:","הַמְבַשֵּׁל שָׁלִיל בְּחָלָב חַיָּב וְכֵן הָאוֹכְלוֹ. אֲבָל הַמְבַשֵּׁל שִׁלְיָא אוֹ עוֹר וְגִידִין וַעֲצָמוֹת וְעִקְּרֵי קַרְנַיִם וּטְלָפַיִם הָרַכִּים בְּחָלָב פָּטוּר. וְכֵן הָאוֹכְלָן פָּטוּר:","בָּשָׂר שֶׁנָּפַל לְתוֹךְ הֶחָלָב אוֹ חָלָב שֶׁנָּפַל לְתוֹךְ הַבָּשָׂר וְנִתְבַּשֵּׁל עִמּוֹ שִׁעוּרוֹ בְּנוֹתֵן טַעַם. כֵּיצַד. חֲתִיכָה שֶׁל בָּשָׂר שֶׁנָּפְלָה לִקְדֵרָה רוֹתַחַת שֶׁל חָלָב. טוֹעֵם הַנָּכְרִי אֶת הַקְּדֵרָה. אִם אָמַר שֶׁיֵּשׁ בָּהּ טַעַם בָּשָׂר אֲסוּרָה. וְאִם לָאו מֻתֶּרֶת. וְאוֹתָהּ חֲתִיכָה אֲסוּרָה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁקָּדַם וְהוֹצִיא אֶת הַחֲתִיכָה קֹדֶם שֶׁתִּפְלֹט חָלָב שֶׁבָּלְעָה. אֲבָל אִם לֹא סִלֵּק מְשַׁעֲרִים אוֹתָהּ בְּשִׁשִּׁים מִפְּנֵי שֶׁהֶחָלָב שֶׁנִּבְלָע בָּהּ וְנֶאֱסַר יָצָא וְנִתְעָרֵב עִם שְׁאָר הֶחָלָב:","נָפַל חָלָב לְתוֹךְ קְדֵרָה שֶׁל בָּשָׂר טוֹעֲמִין אֶת הַחֲתִיכָה שֶׁנָּפַל עָלֶיהָ חָלָב. אִם אֵין בָּהּ טַעַם חָלָב הַכּל מֻתָּר. וְאִם יֵשׁ בַּחֲתִיכָה טַעַם חָלָב אַף עַל פִּי שֶׁאִם תִּסָּחֵט הַחֲתִיכָה לֹא יִשָּׁאֵר בָּהּ טַעַם. הוֹאִיל וְיֵשׁ בָּהּ עַתָּה טַעַם חָלָב נֶאֶסְרָה אוֹתָהּ חֲתִיכָה. וּמְשַׁעֲרִין בְּכֻלָּהּ אִם הָיָה בְּכָל שֶׁיֵּשׁ בַּקְּדֵרָה מִן הַחֲתִיכוֹת וְהָיָּרָק וְהַמָּרָק וְהַתַּבְלִין כְּדֵי שֶׁתִּהְיֶה חֲתִיכָה זוֹ אֶחָד מִשִּׁשִּׁים מִן הַכּל הַחֲתִיכָה אֲסוּרָה וְהַשְּׁאָר מֻתָּר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא נִעֵר אֶת הַקְּדֵרָה בַּתְּחִלָּה כְּשֶׁנָּפַל הֶחָלָב אֶלָּא לְבַסּוֹף וְלֹא כִּסָּה. אֲבָל אִם נִעֵר מִתְּחִלָּה וְעַד סוֹף אוֹ שֶׁכִּסָּה מִשְּׁעַת נְפִילָה עַד סוֹף הֲרֵי זֶה בְּנוֹתֵן טַעַם. וְכֵן אִם נָפַל חָלָב לְתוֹךְ הַמָּרָק אוֹ לְכָל הַחֲתִיכוֹת וְלֹא נוֹדַע לְאֵי זֶה חֲתִיכָה נָפַל. נוֹעֵר אֶת הַקְּדֵרָה כֻּלָּהּ עַד שֶׁתָּשׁוּב וְיִתְעָרֵב הַכּל. אִם יֵשׁ בַּקְּדֵרָה כֻּלָּהּ טַעַם חָלָב אֲסוּרָה וְאִם לָאו מֻתֶּרֶת. אִם לֹא נִמְצָא נָכְרִי שֶׁיִּטְעֹם וְנִסְמֹךְ עָלָיו מְשַׁעֲרִים בְּשִׁשִּׁים בֵּין בָּשָׂר לְתוֹךְ חָלָב בֵּין חָלָב לְתוֹךְ בָּשָׂר אֶחָד מִשִּׁשִּׁים מֻתָּר פָּחוֹת מִשִּׁשִּׁים אָסוּר:","קְדֵרָה שֶׁבִּשֵּׁל בָּהּ בָּשָׂר לֹא יְבַשֵּׁל בָּהּ חָלָב. וְאִם בִּשֵּׁל בְּנוֹתֵן טַעַם:","הַכְּחַל אָסוּר מִדִּבְרֵי סוֹפְרִים. שֶׁאֵין בָּשָׂר שֶׁנִתְבַּשֵּׁל בַּחֲלֵב שְׁחוּטָה אָסוּר מִן הַתּוֹרָה כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ אִם קְרָעוֹ וּמֵרֵק הֶחָלָב שֶׁבּוֹ מֻתָּר לִצְלוֹתוֹ וּלְאָכְלוֹ. וְאִם קְרָעוֹ שְׁתִי וָעֵרֶב וְטָחוֹ בַּכֹּתֶל עַד שֶׁלֹּא נִשְׁאַר בּוֹ לַחְלוּחִית חָלָב מֻתָּר לְבַשְּׁלוֹ עִם הַבָּשָׂר. וּכְחַל שֶׁלֹּא קְרָעוֹ בֵּין שֶׁל קְטַנָּה שֶׁלֹּא הֵינִיקָה בֵּין שֶׁל גְּדוֹלָה אָסוּר לְבַשְּׁלוֹ. וְאִם עָבַר וּבִשְּׁלוֹ בִּפְנֵי עַצְמוֹ מֻתָּר לְאָכְלוֹ. וְאִם בִּשְּׁלוֹ עִם בָּשָׂר אַחֵר מְשַׁעֲרִין אוֹתוֹ בְּשִׁשִּׁים וּכְחַל מִן הַמִּנְיָן:","כֵּיצַד. אִם הָיָה הַכּל עִם הַכְּחַל כְּמוֹ שִׁשִּׁים בַּכְּחַל הַכְּחַל אָסוּר וְהַשְּׁאָר מֻתָּר. וְאִם הָיָה בְּפָחוֹת מִשִּׁשִּׁים הַכּל אָסוּר. בֵּין כָּךְ וּבֵין כָּךְ אִם נָפַל לִקְדֵרָה אַחֶרֶת אוֹסֵר אוֹתָהּ וּמְשַׁעֲרִין בּוֹ בְּשִׁשִּׁים כְּבָרִאשׁוֹנָה. שֶׁהַכְּחַל עַצְמוֹ שֶׁנִתְבַּשֵּׁל נַעֲשָׂה כַּחֲתִיכָה הָאֲסוּרָה וְאֵין מְשַׁעֲרִין בּוֹ אֶלָּא כְּמוֹת שֶׁהוּא בְּעֵת שֶׁנִתְבַּשֵּׁל לֹא כְּמוֹת שֶׁהָיָה בְּשָׁעָה שֶׁנָּפַל:","אֵין צוֹלִין אֶת הַכְּחַל שֶׁחֲתָכוֹ [לְמַעְלָה] מִן הַבָּשָׂר בְּשִׁפּוּד. וְאִם צָלָהוּ הַכּל מֻתָּר:","קֵבָה שֶׁבִּשְּׁלָהּ בֶּחָלָב שֶׁבָּהּ מֻתֶּרֶת שֶׁאֵינוֹ חָלָב אֶלָּא הֲרֵי הוּא כְּטִנֹּפֶת שֶׁהֲרֵי יִשְׁתַּנֶּה בַּמֵּעַיִם:","אָסוּר לְהַעֲמִיד הַגְּבִינָה בְּעוֹר הַקֵּבָה שֶׁל שְׁחוּטָה. וְאִם הֶעֱמִיד טוֹעֵם אֶת הַגְּבִינָה אִם יֵשׁ בָּהּ טַעַם בָּשָׂר אֲסוּרָה וְאִם לָאו מֻתֶּרֶת. מִפְּנֵי שֶׁהַמַּעֲמִיד דָּבָר הַמֻּתָּר הוּא. שֶׁקֵּיבַת שְׁחוּטָה הִיא. וְאֵין כָּאן אֶלָּא אִסּוּר בָּשָׂר בְּחָלָב שֶׁשִּׁעוּרוֹ בְּנוֹתֵן טַעַם. אֲבָל הַמַּעֲמִיד בְּעוֹר קֵיבַת נְבֵלָה וּטְרֵפָה וּבְהֵמָה טְמֵאָה הוֹאִיל וְהַמַּעֲמִיד דָּבָר הָאָסוּר בִּפְנֵי עַצְמוֹ נֶאֶסְרָה הַגְּבִינָה מִשּׁוּם נְבֵלָה לֹא מִשּׁוּם בָּשָׂר בְּחָלָב. וּמִפְּנֵי חֲשָׁשׁ זֶה אָסְרוּ גְּבִינַת עַכּוּ\"ם כְּמוֹ שֶׁבֵּאַרְנוּ:","הַבָּשָׂר לְבַדּוֹ מֻתָּר וְהֶחָלָב לְבַדּוֹ מֻתָּר וּבְהִתְעָרֵב שְׁנֵיהֶן עַל יְדֵי בִּשּׁוּל יֵאָסְרוּ שְׁנֵיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּתְבַּשְּׁלוּ שְׁנֵיהֶם בְּיַחַד אוֹ שֶׁנָּפַל חַם לְתוֹךְ חַם אוֹ צוֹנֵן לְתוֹךְ חַם. אֲבָל אִם נָפַל אֶחָד מִשְּׁנֵיהֶם וְהוּא חַם לְתוֹךְ הַשֵּׁנִי וְהוּא צוֹנֵן קוֹלֵף הַבָּשָׂר כֻּלּוֹ שֶׁנָּגַע בּוֹ הֶחָלָב וְאוֹכֵל הַשְּׁאָר. וְאִם נָפַל צוֹנֵן לְתוֹךְ צוֹנֵן מֵדִיחַ הַחֲתִיכָה וְאוֹכְלָהּ. לְפִיכָךְ מֻתָּר לִצְרֹר בָּשָׂר וּגְבִינָה בְּמִטְפַּחַת אַחַת וְהוּא שֶׁלֹּא יִגְּעוּ זֶה בָּזֶה. וְאִם נָגְעוּ מֵדִיחַ הַבָּשָׂר וּמֵדִיחַ הַגְּבִינָה וְאוֹכֵל:","מָלִיחַ שֶׁאֵינוֹ נֶאֱכָל מֵחֲמַת מִלְחוֹ הֲרֵי הוּא כְּרוֹתֵחַ. וְאִם נֶאֱכָל כְּמוֹת שֶׁהוּא כְּמוֹ הַכּוּתָח אֵינוֹ כְּרוֹתֵחַ:","עוֹף שָׁחוּט שֶׁנָּפַל לְחָלָב אוֹ לְכוּתָח שֶׁיֵּשׁ בּוֹ חָלָב. אִם חַי הוּא מְדִיחוֹ וּמֻתָּר. וְאִם צָלִי קוֹלְפוֹ. וְאִם הָיוּ בּוֹ פְּלָחִים פְּלָחִים אוֹ שֶׁהָיָה מְתֻבָּל בְּתַבְלִין וְנָפַל לְחָלָב אוֹ לְכוּתָח הֲרֵי זֶה אָסוּר:","אָסוּר לְהַעֲלוֹת הָעוֹף עִם הַגְּבִינָה עַל הַשֻּׁלְחָן שֶׁהוּא אוֹכֵל עָלָיו גְּזֵרָה מִשּׁוּם הֶרְגֵּל עֲבֵרָה שֶׁמָּא יֹאכַל זֶה עִם זֶה. אַף עַל פִּי שֶׁהָעוֹף בְּחָלָב אָסוּר מִדִּבְרֵי סוֹפְרִים:","שְׁנֵי אַכְסַנָּאִין שֶׁאֵינָם מַכִּירִין זֶה אֶת זֶה אוֹכְלִין עַל שֻׁלְחָן אֶחָד זֶה בְּשַׂר בְּהֵמָה וְזֶה גְּבִינָה מִפְּנֵי שֶׁאֵין זֶה גַּס לִבּוֹ בָּזֶה כְּדֵי שֶׁיֹּאכַל עִמּוֹ:","אֵין לָשִׁין הָעִסָּה בְּחָלָב וְאִם לָשׁ כָּל הַפַּת אֲסוּרָה מִפְּנֵי הֶרְגֵּל עֲבֵרָה. שֶׁמָּא יֹאכַל בָּהּ בָּשָׂר. וְאֵין טָשִׁין אֶת הַתַּנּוּר בְּאַלְיָה. וְאִם טָשׁ כָּל הַפַּת אֲסוּרָה עַד שֶׁיַּסִּיק אֶת הַתַּנּוּר שֶׁמָּא יֹאכַל בָּהּ חָלָב. וְאִם שִׁנָּה בְּצוּרַת הַפַּת עַד שֶׁתִּהְיֶה נִכֶּרֶת כְּדֵי שֶׁלֹּא יֹאכַל בָּהּ לֹא בָּשָׂר וְלֹא חָלָב הֲרֵי זֶה מֻתָּר:","פַּת שֶׁאֲפָאָהּ עִם הַצָּלִי וְדָגִים שֶׁצְּלָאָן עִם הַבָּשָׂר אָסוּר לְאָכְלָן בְּחָלָב. קְעָרָה שֶׁאָכְלוּ בָּהּ בָּשָׂר וּבִשְּׁלוּ בָּהּ דָּגִים אוֹתָן הַדָּגִים מֻתָּר לְאָכְלָן בְּכוּתָח:","סַכִּין שֶׁחָתַךְ בָּהּ בָּשָׂר צָלִי וְחָזַר וְחָתַךְ בָּהּ צְנוֹן וְכַיּוֹצֵא בּוֹ מִדְּבָרִים חֲרִיפִין אָסוּר לְאָכְלָן בְּכוּתָח. אֲבָל אִם חָתַךְ בָּהּ בָּשָׂר וְחָזַר וְחָתַךְ בָּהּ קִישׁוּת אוֹ אֲבַטִּיחַ גּוֹרֵד מְקוֹם הַחֲתָךְ וְאוֹכֵל הַשְּׁאָר בְּחָלָב:","אֵין מַנִּיחִין כַּד שֶׁל מֶלַח בְּצַד כַּד שֶׁל כְּמָךְ מִפְּנֵי שֶׁשּׁוֹאֵב מִמֶּנּוּ וְנִמְצָא מְבַשֵּׁל הַבָּשָׂר בְּמֶלַח זֶה שֶׁיֵּשׁ בּוֹ טַעַם הֶחָלָב. אֲבָל מַנִּיחַ כַּד הַחֹמֶץ בְּצַד כַּד הַכְּמָךְ שֶׁאֵין הַחֹמֶץ שׁוֹאֵב מִמֶּנּוּ:","מִי שֶׁאָכַל גְּבִינָה אוֹ חָלָב תְּחִלָּה מֻתָּר לֶאֱכל אַחֲרָיו בָּשָׂר מִיָּד. וְצָרִיךְ שֶׁיָּדִיחַ יָדָיו וִיקַנֵּחַ פִּיו בֵּין הַגְּבִינָה וּבֵין הַבָּשָׂר. וּבְמַה מְקַנֵּחַ פִּיו בְּפַת אוֹ בְּפֵרוֹת שֶׁלּוֹעֲסָן וּבוֹלְעָן אוֹ פּוֹלְטָן. וּבַכּל מְקַנְּחִין אֶת הַפֶּה חוּץ מִתְּמָרִים אוֹ קֶמַח אוֹ יְרָקוֹת שֶׁאֵין אֵלּוּ מְקַנְּחִין יָפֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּבְשַׂר בְּהֵמָה אוֹ חַיָּה. אֲבָל אִם אָכַל בְּשַׂר עוֹף אַחַר שֶׁאָכַל הַגְּבִינָה אוֹ הֶחָלָב אֵינוֹ צָרִיךְ לֹא קִנּוּחַ הַפֶּה וְלֹא נְטִילַת יָדַיִם:","מִי שֶׁאָכַל בָּשָׂר בַּתְּחִלָּה בֵּין בְּשַׂר בְּהֵמָה בֵּין בְּשַׂר עוֹף לֹא יֹאכַל אַחֲרָיו חָלָב עַד שֶׁיִּהְיֶה בֵּינֵיהֶן כְּדֵי שִׁעוּר סְעֻדָּה אַחֶרֶת וְהוּא כְּמוֹ שֵׁשׁ שָׁעוֹת מִפְּנֵי הַבָּשָׂר שֶׁל בֵּין הַשִּׁנַּיִם שֶׁאֵינוֹ סָר בְּקִנּוּחַ:"],"Mishneh Torah, Forbidden Intercourse 2":["אֵשֶׁת אָבִיו וְאֵשֶׁת בְּנוֹ וְאֵשֶׁת אָחִיו וְאֵשֶׁת אֲחִי אָבִיו אַרְבַּעְתָּן עֶרְוָה עָלָיו לְעוֹלָם. בֵּין מִן הָאֵרוּסִין בֵּין מִן הַנִּשּׂוּאִין. בֵּין שֶׁנִּתְגָּרְשׁוּ בֵּין שֶׁלֹּא נִתְגָּרְשׁוּ. בֵּין בְּחַיֵּי בַּעְלֵיהֶן בֵּין אַחַר מִיתַת בַּעְלֵיהֶן. חוּץ מֵאֵשֶׁת אָחִיו שֶׁלֹּא הִנִּיחַ בֵּן. וְאִם בָּא עַל אַחַת מֵהֶן בְּחַיֵּי בַּעְלָהּ חַיָּב שְׁתַּיִם. מִשּׁוּם שְׁאֵר בָּשָׂר וּמִשּׁוּם אֵשֶׁת אִישׁ. שֶׁהֲרֵי שְׁנֵיהֶן הָאִסּוּרִין בָּאִין כְּאֶחָד:","לְפִיכָךְ הַבָּא עַל אִמּוֹ שֶׁהִיא אֵשֶׁת אָבִיו חַיָּב שְׁתַּיִם. בֵּין בְּחַיֵּי אָבִיו בֵּין לְאַחַר מִיתַת אָבִיו. אַחַת מִשּׁוּם אִמּוֹ וְאַחַת מִשּׁוּם אֵשֶׁת אָבִיו. אֶחָד אָחִיו מֵאָבִיו אוֹ אָחִיו מֵאִמּוֹ. בֵּין מִנִּשּׂוּאִין בֵּין מִזְּנוּת. אִשְׁתּוֹ עֶרְוָה עָלָיו. אֲבָל אֵשֶׁת אֲחִי אָבִיו מִן הָאֵם הֲרֵי הִיא שְׁנִיָּה כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֶחָד אֲחוֹתוֹ מֵאָבִיו אוֹ מֵאִמּוֹ. בֵּין מִן הַנִּשּׂוּאִין בֵּין מִזְּנוּת. כְּגוֹן שֶׁזָּנְתָה אִמּוֹ אוֹ אָבִיו עִם אֲחֵרִים וְהָיְתָה לוֹ אָחוֹת מִזְּנוּת. הֲרֵי זוֹ עֶרְוָה עָלָיו שֶׁנֶּאֱמַר (ויקרא יח ט) \"מוֹלֶדֶת בַּיִת אוֹ מוֹלֶדֶת חוּץ\":","בַּת אֵשֶׁת אָבִיו שֶׁהִיא אֲחוֹתוֹ מֵאָבִיו הֲרֵי הִיא עֶרְוָה עָלָיו שֶׁנֶּאֱמַר (ויקרא יח יא) \"עֶרְוַת בַּת אֵשֶׁת אָבִיךָ מוֹלֶדֶת אָבִיךָ\". אֲבָל אִם נָשָׂא אָבִיו אִשָּׁה וְיֵשׁ לָהּ בַּת מֵאִישׁ אַחֵר אוֹתָהּ הַבַּת מֻתֶּרֶת לוֹ שֶׁאֵין זוֹ מוֹלֶדֶת אָבִיו. וַהֲלֹא מִשּׁוּם אֲחוֹתוֹ חַיָּב עָלֶיהָ וְלָמָּה נֶאֱמַר (ויקרא יח יא) \"בַּת אֵשֶׁת אָבִיךָ\" לְחַיֵּב עָלֶיהָ אַף מִשּׁוּם זֶה:","לְפִיכָךְ הַבָּא עַל אֲחוֹתוֹ שֶׁהִיא בַּת נְשׂוּאַת אָבִיו חַיָּב שְׁתַּיִם. אַחַת מִשּׁוּם (ויקרא יח ט) \"עֶרְוַת אֲחוֹתְךָ\" וְאַחַת מִשּׁוּם (ויקרא יח יא) \"עֶרְוַת בַּת אֵשֶׁת אָבִיךָ\". אֲבָל אִם אָנַס אָבִיו אִשָּׁה אוֹ פִּתָּה אוֹתָהּ וְהוֹלִיד מִמֶּנָּה בַּת וּבָא עָלֶיהָ אֵינוֹ חַיָּב אֶלָּא מִשּׁוּם אֲחוֹתוֹ בִּלְבַד. שֶׁאֵין בַּת הָאֲנוּסָה בַּת אֵשֶׁת אָבִיו:","אֲחוֹת אִמּוֹ בֵּין אֲחוֹתָהּ מֵאָבִיהָ בֵּין אֲחוֹתָהּ מֵאִמָּהּ בֵּין מִן הַנִּשּׂוּאִין בֵּין מִזְּנוּת הֲרֵי זוֹ עֶרְוָה עָלָיו מִשּׁוּם אֲחוֹת אֵם. וְכֵן אֲחוֹת הָאָב בֵּין מִן הָאֵם בֵּין מִן הָאָב בֵּין מִן הַנִּשּׂוּאִין בֵּין מִזְּנוּת הֲרֵי זוֹ עֶרְוָה עָלָיו מִשּׁוּם אֲחוֹת אָב:","הַבָּא עַל אִשָּׁה דֶּרֶךְ זְנוּת וְהוֹלִיד מִמֶּנָּה בַּת אוֹתָהּ הַבַּת עֶרְוָה עָלָיו מִשּׁוּם בִּתּוֹ. וְאַף עַל פִּי שֶׁלֹּא נֶאֱמַר בַּתּוֹרָה עֶרְוַת בִּתְּךָ לֹא תְּגַלֶּה מֵאַחַר שֶׁאָסַר בַּת הַבַּת שָׁתַק מִן הַבַּת וְאִסּוּרָהּ מִן הַתּוֹרָה. וְאֵינוֹ מִדִּבְרֵי סוֹפְרִים. לְפִיכָךְ הַבָּא עַל בִּתּוֹ מִנְּשׂוּאָתוֹ חַיָּב שְׁתַּיִם. מִשּׁוּם בִּתּוֹ וּמִשּׁוּם עֶרְוַת אִשָּׁה וּבִתָּהּ:","כֵּיוָן שֶׁקִּדֵּשׁ אָדָם אִשָּׁה נֶאֶסְרוּ עָלָיו מִקְּרוֹבוֹתֶיהָ שֵׁשׁ נָשִׁים. וְכָל אַחַת מֵהֶן עֶרְוָה עָלָיו לְעוֹלָם בֵּין כָּנַס בֵּין גֵּרֵשׁ בֵּין בְּחַיֵּי אִשְׁתּוֹ בֵּין לְאַחַר מוֹתָהּ. וְאֵלּוּ הֵן. אִמָּהּ וְאֵם אִמָּהּ וְאֵם אָבִיהָ וּבִתָּהּ וּבַת בִּתָּהּ וּבַת בְּנָהּ. וְאִם בָּא עַל אַחַת מֵהֶן בְּחַיֵּי אִשְׁתּוֹ שְׁנֵיהֶן נִשְׂרָפִין:","בָּא עֲלֵיהֶן לְאַחַר מִיתַת אִשְׁתּוֹ הֲרֵי אֵלּוּ בְּכָרֵת וְאֵין בָּהֶן מִיתַת בֵּית דִּין. שֶׁנֶּאֱמַר (ויקרא כ יד) \"בָּאֵשׁ יִשְׂרְפוּ אֹתוֹ וְאֶתְהֶן\". בִּזְמַן שֶּׁשְּׁתֵּיהֶן קַיָּמוֹת שֶׁהֵן אִשְׁתּוֹ וְזוֹ שֶׁבָּא עָלֶיהָ הֲרֵי הוּא וְהָעֶרְוָה נִשְׂרָפִין. וּבִזְמַן שֶׁאֵין שְׁתֵּיהֶן קַיָּמוֹת אֵין שָׁם שְׂרֵפָה:","וְכֵן אֲחוֹת אִשְׁתּוֹ עֶרְוָה עָלָיו עַד שֶׁתָּמוּת אִשְׁתּוֹ. בֵּין אֲחוֹתָהּ מֵאִמָּהּ בֵּין אֲחוֹתָהּ מֵאָבִיהָ בֵּין מִן הַנִּשּׂוּאִין בֵּין מִזְּנוּת הֲרֵי זוֹ עֶרְוָה עָלָיו:","עָבַר וְנָאַף עִם אַחַת מִשֶּׁבַע נָשִׁים אֵלּוּ בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה אַף עַל פִּי שֶׁהוּא וְהַנּוֹאֶפֶת בְּמִיתַת בֵּית דִּין אוֹ בְּכָרֵת לֹא נֶאֶסְרָה אִשְׁתּוֹ עָלָיו חוּץ מֵאֲחוֹת אֲרוּסָתוֹ שֶׁהִיא אוֹסֶרֶת אִשְׁתּוֹ עָלָיו כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גֵּרוּשִׁין:","הַבּוֹעֵל אִשָּׁה דֶּרֶךְ זְנוּת לֹא נֶאֶסְרוּ עָלָיו קְרוֹבוֹתֶיהָ שֶׁהֵן הַשֶּׁבַע נָשִׁים שֶׁאָמַרְנוּ. אֲבָל חֲכָמִים אָסְרוּ עַל מִי שֶׁנָּאַף עִם אִשָּׁה לִשָּׂא אַחַת מִן הַשֶּׁבַע נָשִׁים קְרוֹבוֹתֶיהָ כָּל זְמַן שֶׁהַזּוֹנָה קַיֶּמֶת. מִפְּנֵי שֶׁהַזּוֹנָה בָּאָה לִקְרוֹבוֹתֶיהָ לְבַקֵּר אוֹתָן וְהוּא מִתְיַחֵד עִמָּהּ וְלִבּוֹ גַּס בָּהּ וְיָבוֹא לִידֵי עֲבֵרָה שֶׁיִּבְעל הָעֶרְוָה. וְלֹא עוֹד אֶלָּא אֲפִלּוּ נִטְעַן עַל אִשָּׁה הֲרֵי זֶה לֹא יִשָּׂא אַחַת מִקְּרוֹבוֹתֶיהָ עַד שֶׁתָּמוּת זוֹ שֶׁנִּטְעַן עָלֶיהָ. וְאִם כָּנַס הַקְּרוֹבָה שֶׁזָּנָה עִם קְרוֹבוֹתֶיהָ לֹא יוֹצִיא:","מִי שֶׁנִּטְעַן עַל עֶרְוָה אוֹ שֶׁיָּצָא לוֹ שֵׁם רַע עִמָּהּ לֹא יָדוּר עִמָּהּ בְּמָבוֹי אֶחָד וְלֹא יֵרָאֶה בְּאוֹתָהּ שְׁכוּנָה. וּמַעֲשֶׂה שֶׁהָיוּ מְרַנְּנִין אַחֲרָיו עִם חֲמוֹתוֹ וְהִכּוּ אוֹתוֹ חֲכָמִים מַכַּת מַרְדּוּת מִפְּנֵי שֶׁעָבַר עַל פֶּתַח בֵּיתָהּ:","הַבָּא עַל אִשָּׁה וּבִתָּהּ דֶּרֶךְ זְנוּת אוֹ עַל אִשָּׁה וַאֲחוֹתָהּ וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה כְּמִי שֶׁבָּא עַל שְׁתֵּי נָשִׁים נָכְרִיּוֹת שֶׁאֵין נַעֲשׂוֹת עֶרְוָה זוֹ עִם זוֹ אֶלָּא בְּנִשּׂוּאִין לֹא בִּזְנוּת. וְכֵן אִם אָנַס אָבִיו אוֹ בְּנוֹ אוֹ אָחִיו אוֹ אֲחִי אָבִיו אִשָּׁה אוֹ פִּתָּה אוֹתָהּ הֲרֵי זוֹ מֻתֶּרֶת לוֹ וְיִשָּׂאֶנָּה שֶׁלֹּא נֶאֱמַר אֶלָּא אֵשֶׁת וְאֵין כָּאן אִישׁוּת:","אָבִיו אוֹ בְּנוֹ שֶׁנָּשָׂא אִשָּׁה הֲרֵי זֶה מֻתָּר לִשָּׂא בִּתָּהּ אוֹ אִמָּהּ כְּמוֹ שֶׁבֵּאַרְנוּ. וּמֻתָּר לְאָדָם לִשָּׂא אֵשֶׁת בֶּן אָחִיו. וְנוֹשֵׂא אָדָם אִשָּׁה וּבַת אֲחוֹתָהּ אוֹ בַּת אָחִיהָ כְּאַחַת. וּמִצְוַת חֲכָמִים שֶׁיִּשָּׂא אָדָם בַּת אֲחוֹתוֹ וְהוּא הַדִּין לְבַת אָחִיו שֶׁנֶּאֱמַר (ישעיה נח ז) \"וּמִבְּשָׂרְךָ לֹא תִתְעַלָּם\":"],"Mishneh Torah, Foreign Worship and Customs of the Nations 10":["אֵין כּוֹרְתִין בְּרִית לְשׁבְעָה עֲמָמִין כְּדֵי שֶׁנַּעֲשֶׂה עִמָּהֶן שָׁלוֹם וְנָנִיחַ אוֹתָם לַעֲבֹד עֲבוֹדָה זָרָה שֶׁנֶּאֱמַר (דברים ז ב) \"לֹא תִכְרֹת לָהֶם בְּרִית\" אֶלָּא יַחְזְרוּ מֵעֲבוֹדָתָם אוֹ יֵהָרְגוּ. וְאָסוּר לְרַחֵם עֲלֵיהֶם שֶׁנֶּאֱמַר (דברים ז ב) \"וְלֹא תְחָנֵּם\". לְפִיכָךְ אִם רָאָה מֵהֶם אוֹבֵד אוֹ טוֹבֵעַ בַּנָּהָר לֹא יַעֲלֶנּוּ. רָאָהוּ נָטוּי לָמוּת לֹא יַצִּילֶנּוּ. אֲבָל לְאַבְּדוֹ בְּיָדוֹ אוֹ לְדָחֳפוֹ לַבּוֹר וְכַיּוֹצֵא בָּזֶה אָסוּר מִפְּנֵי שֶׁאֵינוֹ עוֹשֶׂה עִמָּנוּ מִלְחָמָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשִׁבְעָה עֲמָמִין אֲבָל הַמּוֹסְרִים וְהָאֶפִּיקוֹרוֹסִין מִיִּשְׂרָאֵל הָיָה דִּין לְאַבְּדָן בְּיָד וּלְהוֹרִידָן עַד בְּאֵר שַׁחַת מִפְּנֵי שֶׁהָיוּ מְצֵרִים לְיִשְׂרָאֵל וּמְסִירִין אֶת הָעָם מֵאַחֲרֵי ה':","מִכָּאן אַתָּה לָמֵד שֶׁאָסוּר לְרַפְּאוֹת עַכּוּ\"ם אֲפִלּוּ בְּשָׂכָר. וְאִם הָיָה מִתְיָרֵא מֵהֶן אוֹ שֶׁהָיָה חוֹשֵׁשׁ מִשּׁוּם אֵיבָה מְרַפֵּא בְּשָׂכָר אֲבָל בְּחִנָּם אָסוּר. וְגֵר תּוֹשָׁב הוֹאִיל וְאַתָּה מְצֻוֶּה לְהַחֲיוֹתוֹ מְרַפְּאִים אוֹתוֹ בְּחִנָּם:","אֵין מוֹכְרִין לָהֶם בָּתִּים וְשָׂדוֹת בְּאֶרֶץ יִשְׂרָאֵל. וּבְסוּרְיָא מוֹכְרִין לָהֶם בָּתִּים אֲבָל לֹא שָׂדוֹת. וּמַשְׂכִּירִין לָהֶם בָּתִּים בְּאֶרֶץ יִשְׂרָאֵל וּבִלְבַד שֶׁלֹּא יַעֲשׂוּ שְׁכוּנָה וְאֵין שְׁכוּנָה פָּחוֹת מִשְּׁלֹשָׁה. וְאֵין מַשְׂכִּירִין לָהֶם שָׂדוֹת. וּבְסוּרְיָא מַשְׂכִּירִין לָהֶם שָׂדוֹת. וּמִפְּנֵי מָה הֶחְמִירוּ בְּשָׂדֶה, מִפְּנֵי שֶׁיֵּשׁ בָּהּ שְׁתַּיִם, מַפְקִיעָהּ מִן הַמַּעַשְׂרוֹת וְנוֹתֵן לָהֶם חֲנִיָּה בַּקַּרְקַע. וּמֻתָּר לִמְכֹּר לָהֶם בָּתִּים וְשָׂדוֹת בְּחוּצָה לָאָרֶץ מִפְּנֵי שֶׁאֵינָהּ אַרְצֵנוּ:","אַף בְּמָקוֹם שֶׁהִתִּירוּ לְהַשְׂכִּיר לֹא לְבֵית דִּירָה הִתִּירוּ מִפְּנֵי שֶׁהוּא מַכְנִיס לְתוֹכָהּ עֲבוֹדַת כּוֹכָבִים וְנֶאֱמַר (דברים ז כו) \"לֹא תָבִיא תוֹעֵבָה אֶל בֵּיתֶךָ\". אֲבָל מַשְׂכִּיר לָהֶן בָּתִּים לַעֲשׂוֹתָן אוֹצָר. וְאֵין מוֹכְרִין לָהֶן פֵּרוֹת וּתְבוּאָה וְכַיּוֹצֵא בָּהֶן בַּמְחֻבָּר לַקַּרְקַע. אֲבָל מוֹכֵר הוּא מִשֶּׁיָקֹץ אוֹ מוֹכֵר לוֹ עַל מְנָת לָקֹץ וְקוֹצֵץ. וּמִפְּנֵי מָה אֵין מוֹכְרִין לָהֶן שֶׁנֶּאֱמַר (דברים ז ב) \"וְלֹא תְחָנֵּם\" לֹא תִּתֵּן לָהֶם חֲנִיָּה בַּקַּרְקַע שֶׁאִם לֹא יִהְיֶה לָהֶם קַרְקַע יְשִׁיבָתָן יְשִׁיבַת עַרְאַי הִיא. וְכֵן אָסוּר לְסַפֵּר בְּשִׁבְחָן וַאֲפִלּוּ לוֹמַר כַּמָּה נָאֶה עוֹבֵד כּוֹכָבִים זֶה בְּצוּרָתוֹ. קַל וָחֹמֶר שֶׁיְּסַפֵּר בְּשֶׁבַח מַעֲשָׂיו אוֹ שֶׁיְּחַבֵּב דָּבָר מִדִּבְרֵיהֶם שֶׁנֶּאֱמַר וְלֹא תְחָנֵּם לֹא יִהְיֶה לָהֶם חֵן בְּעֵינֶיךָ, מִפְּנֵי שֶׁגּוֹרֵם לְהִדַּבֵּק עִמּוֹ וְלִלְמֹד מִמַּעֲשָׂיו הָרָעִים. וְאָסוּר לִתֵּן לָהֶם מַתְּנַת חִנָּם אֲבָל נוֹתֵן הוּא לְגֵר תּוֹשָׁב שֶׁנֶּאֱמַר (דברים יד כא) \"לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךָ תִּתְּנֶנָּה וַאֲכָלָהּ אוֹ מָכֹר לְנָכְרִי\", בִּמְכִירָה וְלֹא בִּנְתִינָה:","מְפַרְנְסִים עֲנִיֵּי עוֹבְדֵי כּוֹכָבִים עִם עֲנִיֵּי יִשְׂרָאֵל מִפְּנֵי דַּרְכֵי שָׁלוֹם. וְאֵין מְמַחִין בִּידֵי עֲנִיֵּי עוֹבְדֵי כּוֹכָבִים בְּלֶקֶט שִׁכְחָה וּפֵאָה מִפְּנֵי דַּרְכֵי שָׁלוֹם. וְשׁוֹאֲלִים בִּשְׁלוֹמָם וַאֲפִלּוּ בְּיוֹם חַגָּם מִפְּנֵי דַּרְכֵי שָׁלוֹם. וְאֵין כּוֹפְלִין לָהֶן שָׁלוֹם לְעוֹלָם. וְלֹא יִכָּנֵס לְבֵיתוֹ שֶׁל עוֹבֵד כּוֹכָבִים בְּיוֹם חַגּוֹ לָתֵת לוֹ שָׁלוֹם. מְצָאוֹ בַּשּׁוּק נוֹתֵן לוֹ שָׁלוֹם בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ:","אֵין כָּל הַדְּבָרִים הָאֵלּוּ אֲמוּרִים אֶלָּא בִּזְמַן שֶׁגָּלוּ יִשְׂרָאֵל לְבֵין הָעוֹבְדֵי כּוֹכָבִים אוֹ שֶׁיַּד עַכּוּ\"ם תַּקִּיפָה עַל יִשְׂרָאֵל אֲבָל בִּזְמַן שֶׁיַּד יִשְׂרָאֵל תַּקִּיפָה עֲלֵיהֶם אָסוּר לָנוּ לְהַנִּיחַ עוֹבְדֵי כּוֹכָבִים בֵּינֵינוּ. וַאֲפִלּוּ יוֹשֵׁב יְשִׁיבַת עַרְאַי אוֹ עוֹבֵר מִמָּקוֹם לְמָקוֹם בִּסְחוֹרָה לֹא יַעֲבֹר בְּאַרְצֵנוּ אֶלָּא עַד שֶׁיְּקַבֵּל עָלָיו שֶׁבַע מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ שֶׁנֶּאֱמַר (שמות כג לג) \"לֹא יֵשְׁבוּ בְּאַרְצְךָ\" אֲפִלּוּ לְפִי שָׁעָה. וְאִם קִבֵּל עָלָיו שֶׁבַע מִצְוֹת הֲרֵי זֶה גֵּר תּוֹשָׁב. וְאֵין מְקַבְּלִין גֵּר תּוֹשָׁב אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג אֲבָל שֶׁלֹּא בִּזְמַן הַיּוֹבֵל אֵין מְקַבְּלִין אֶלָּא גֵּר צֶדֶק בִּלְבַד:"],"Mishneh Torah, Foundations of the Torah 10":["כָּל נָבִיא שֶׁיַּעֲמֹד לָנוּ וְיֹאמַר שֶׁה' שְׁלָחוֹ אֵינוֹ צָרִיךְ לַעֲשׂוֹת אוֹת כְּאֶחָד מֵאוֹתוֹת משֶׁה רַבֵּנוּ אוֹ כְּאוֹתוֹת אֵלִיָּהוּ וֶאֱלִישָׁע שֶׁיֵּשׁ בָּהֶם שִׁנּוּי מִנְהָגוֹ שֶׁל עוֹלָם. אֶלָּא הָאוֹת שֶׁלּוֹ שֶׁיֹּאמַר דְּבָרִים הָעֲתִידִים לִהְיוֹת בָּעוֹלָם וְיֵאָמְנוּ דְּבָרָיו שֶׁנֶּאֱמַר (דברים יח כא) \"וְכִי תֹאמַר בִּלְבָבֶךָ אֵיכָה נֵדַע אֶת הַדָּבָר\" וְגוֹ'. לְפִיכָךְ כְּשֶׁיָּבוֹא אָדָם הָרָאוּי לִנְבוּאָה בְּמַלְאֲכוֹת הַשֵּׁם וְלֹא יָבוֹא לְהוֹסִיף וְלֹא לִגְרֹעַ אֶלָּא לַעֲבֹד אֶת ה' בְּמִצְוֹת הַתּוֹרָה אֵין אוֹמְרִין לוֹ קְרַע לָנוּ הַיָּם אוֹ הַחֲיֵה מֵת וְכַיּוֹצֵא בְּאֵלּוּ וְאַחַר כָּךְ נַאֲמִין בְּךָ. אֶלָּא אוֹמְרִים לוֹ אִם נָבִיא אַתָּה אֱמֹר דְּבָרִים הָעֲתִידִים לִהְיוֹת וְהוּא אוֹמֵר וְאָנוּ מְחַכִּים לִרְאוֹת הֲיָבוֹאוּ דְּבָרָיו אִם לֹא יָבוֹאוּ. וַאֲפִלּוּ נָפַל דָּבָר קָטָן בְּיָדוּעַ שֶׁהוּא נְבִיא שֶׁקֶר. וְאִם בָּאוּ דְּבָרָיו כֻּלָּן יִהְיֶה בְּעֵינֵינוּ נֶאֱמָן:","וּבוֹדְקִין אוֹתוֹ פְּעָמִים הַרְבֵּה. אִם נִמְצְאוּ דְּבָרָיו נֶאֱמָנִים כֻּלָּן הֲרֵי זֶה נְבִיא אֱמֶת. כְּמוֹ שֶׁנֶּאֱמַר בִּשְׁמוּאֵל (שמואל א ג כ) \"וַיֵּדַע כָּל יִשְׂרָאֵל מִדָּן וְעַד בְּאֵר שָׁבַע כִּי נֶאֱמָן שְׁמוּאֵל לְנָבִיא לַה'\":","וַהֲלֹא הַמְעוֹנְנִים וְהַקּוֹסְמִים אוֹמְרִים מַה שֶּׁעָתִיד לִהְיוֹת. וּמַה הֶפְרֵשׁ יֵשׁ בֵּין הַנָּבִיא וּבֵינָם. אֶלָּא שֶׁהַמְעוֹנְנִים וְהַקּוֹסְמִים וְכַיּוֹצֵא בָּהֶן מִקְצָת דִּבְרֵיהֶם מִתְקַיְּמִין וּמִקְצָתָן אֵין מִתְקַיְּמִין. כָּעִנְיָן שֶׁנֶּאֱמַר (ישעיה מז יג) \"יַעַמְדוּ נָא וְיוֹשִׁיעֻךְ הֹבְרֵי שָׁמַיִם הַחֹזִים בַּכּוֹכָבִים מוֹדִעִים לֶחֳדָשִׁים מֵאֲשֶׁר יָבֹאוּ עָלָיִךְ\". מֵאֲשֶׁר וְלֹא כָּל אֲשֶׁר. וְאֶפְשָׁר שֶׁלֹּא יִתְקַיֵּם מִדִּבְרֵיהֶם כְּלוּם אֶלָּא יִטְעוּ בַּכּל כָּעִנְיָן שֶׁנֶּאֱמַר (ישעיה מד כה) \"מֵפֵר אֹתוֹת בַּדִּים וְקֹסְמִים יְהוֹלֵל\". אֲבָל הַנָּבִיא כָּל דְּבָרָיו קַיָּמִין שֶׁנֶּאֱמַר (מלכים ב י י) \"כִּי לֹא יִפּל מִדְּבַר ה' אַרְצָה\". וְכֵן הוּא אוֹמֵר (ירמיה כג כח) \"הַנָּבִיא אֲשֶׁר אִתּוֹ חֲלוֹם יְסַפֵּר חֲלוֹם וַאֲשֶׁר דְּבָרִי אִתּוֹ יְדַבֵּר דִּבְרֵי אֱמֶת מַה לַּתֶּבֶן אֶת הַבָּר נְאֻם ה'\". כְּלוֹמַר שֶׁדִּבְרֵי הַקּוֹסְמִים וְהַחֲלוֹמוֹת כְּתֶבֶן שֶׁנִּתְעָרֵב בּוֹ מְעַט בַּר וּדְבַר ה' כְּבַר שֶׁאֵין בּוֹ תֶּבֶן כְּלָל. וּבַדָּבָר הַזֶּה הַכָּתוּב הִבְטִיחַ וְאָמַר שֶׁאוֹתָן הַדְּבָרִים שֶׁמּוֹדִיעִין הַמְעוֹנְנִים וְהַקּוֹסְמִים לָאֻמּוֹת וּמְכַזְּבִין הַנָּבִיא יוֹדִיעַ לָכֶם דִּבְרֵי אֱמֶת וְאֵין אַתֶּם צְרִיכִין לִמְעוֹנֵן וְקוֹסֵם וְכַיּוֹצֵא בּוֹ שֶׁנֶּאֱמַר (דברים יח י) \"לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ\" וְגוֹ' (דברים יח יד) \"כִּי הַגּוֹיִם הָאֵלֶּה\" וְגוֹ'. וְאָמַר (דברים יח טו) \"נָבִיא מִקִּרְבְּךָ מֵאַחֶיךָ\" וְגוֹ'. הָא לָמַדְתָּ שֶׁאֵין הַנָּבִיא עוֹמֵד לָנוּ אֶלָּא לְהוֹדִיעֵנוּ דְּבָרִים הָעֲתִידִים לִהְיוֹת בָּעוֹלָם מִשֹּׂבַע וְרָעָב מִלְחָמָה וְשָׁלוֹם וְכַיּוֹצֵא בָּהֶן. וַאֲפִלּוּ צָרְכֵי יָחִיד מוֹדִיעַ לוֹ. כְּשָׁאוּל שֶׁאָבְדָה לוֹ אֲבֵדָה וְהָלַךְ לַנָּבִיא לְהוֹדִיעוֹ מְקוֹמָהּ. וְכַיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים הוּא שֶׁיֹּאמַר הַנָּבִיא לֹא שֶׁיַּעֲשֶׂה דָּת אַחֶרֶת אוֹ יוֹסִיף מִצְוָה אוֹ יִגְרַע:","דִּבְרֵי הַפֻּרְעָנוּת שֶׁהַנָּבִיא אוֹמֵר כְּגוֹן שֶׁיֹּאמַר פְּלוֹנִי יָמוּת אוֹ שָׁנָה פְּלוֹנִית רָעָב אוֹ מִלְחָמָה וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ אִם לֹא עָמְדוּ דְּבָרָיו אֵין בָּזֶה הַכְחָשָׁה לִנְבוּאָתוֹ. וְאֵין אוֹמְרִים הִנֵּה דִּבֵּר וְלֹא בָּא. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וְנִחָם עַל הָרָעָה וְאֶפְשָׁר שֶׁעָשׂוּ תְּשׁוּבָה וְנִסְלַח לָהֶם כְּאַנְשֵׁי נִינְוֵה. אוֹ שֶׁתָּלָה לָהֶם כְּחִזְקִיָּה. אֲבָל אִם הִבְטִיחַ עַל טוֹבָה וְאָמַר שֶׁיִּהְיֶה כָּךְ וְכָךְ וְלֹא בָּאָה הַטּוֹבָה שֶׁאָמַר בְּיָדוּעַ שֶׁהוּא נְבִיא שֶׁקֶר. שֶׁכָּל דְּבַר טוֹבָה שֶׁיִּגְזֹר הָאֵל אֲפִלּוּ עַל תְּנַאי אֵינוֹ חוֹזֵר. וְלֹא מָצִינוּ שֶׁחָזַר בִּדְבַר טוֹבָה אֶלָּא בְּחֻרְבָּן רִאשׁוֹן כְּשֶׁהִבְטִיחַ לַצַּדִּיקִים שֶׁלֹּא יָמוּתוּ עִם הָרְשָׁעִים וְחָזַר בִּדְבָרָיו. וְזֶה מְפֹרָשׁ בְּמַסֶּכֶת שַׁבָּת. הָא לָמַדְתָּ שֶׁבְּדִבְרֵי הַטּוֹבָה בִּלְבַד יִבָּחֵן הַנָּבִיא. הוּא שֶׁיִּרְמְיָהוּ אָמַר בִּתְשׁוּבָתוֹ לַחֲנַנְיָה בֶּן עַזּוּר כְּשֶׁהָיָה יִרְמְיָה מִתְנַבֵּא לְרָעָה וַחֲנַנְיָה לְטוֹבָה. אָמַר לוֹ לַחֲנַנְיָה אִם לֹא יַעַמְדוּ דְּבָרַי אֵין בָּזֶה רְאָיָה שֶׁאֲנִי נְבִיא שֶׁקֶר אֲבָל אִם לֹא יַעַמְדוּ דְּבָרֶיךָ יִוָּדַע שֶׁאַתָּה נְבִיא שֶׁקֶר. שֶׁנֶּאֱמַר (ירמיה כח ז) \"אַךְ שְׁמַע נָא אֶת הַדָּבָר הַזֶּה\" וְגוֹ' הַנָּבִיא אֲשֶׁר יְדַבֵּר שָׁלוֹם בְּבֹא דְּבַר הַנָּבִיא יִוָּדַע הַנָּבִיא אֲשֶׁר שְׁלָחוֹ ה' בֶּאֱמֶת:","נָבִיא שֶׁהֵעִיד לוֹ נָבִיא אַחֵר שֶׁהוּא נָבִיא הֲרֵי הוּא בְּחֶזְקַת נָבִיא וְאֵין זֶה הַשֵּׁנִי צָרִיךְ חֲקִירָה. שֶׁהֲרֵי משֶׁה רַבֵּנוּ הֵעִיד לִיהוֹשֻׁעַ וְהֶאֱמִינוּ בּוֹ כָּל יִשְׂרָאֵל קֹדֶם שֶׁיַּעֲשֶׂה אוֹת. וְכֵן לְדוֹרוֹת. נָבִיא שֶׁנּוֹדְעָה נְבוּאָתוֹ וְהֶאֱמִינוּ בִּדְבָרָיו פַּעַם אַחַר פַּעַם אוֹ שֶׁהֵעִיד לוֹ נָבִיא וְהָיָה הוֹלֵךְ בְּדַרְכֵי הַנְּבוּאָה אָסוּר לַחְשֹׁב אַחֲרָיו וּלְהַרְהֵר בִּנְבוּאָתוֹ שֶׁמָּא אֵינָהּ אֱמֶת. וְאָסוּר לְנַסּוֹתוֹ יוֹתֵר מִדַּאי וְלֹא נִהְיֶה הוֹלְכִים וּמְנַסִּים לְעוֹלָם שֶׁנֶּאֱמַר (דברים ו טז) \"לֹא תְנַסּוּ אֶת ה' אֱלֹהֵיכֶם כַּאֲשֶׁר נִסִּיתֶם בַּמַּסָּה\" שֶׁאָמְרוּ (שמות יז ז) \"הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן\". אֶלָּא מֵאַחַר שֶׁנּוֹדַע שֶׁזֶּה נָבִיא יַאֲמִינוּ וְיֵדְעוּ כִּי ה' בְּקִרְבָּם וְלֹא יְהַרְהֲרוּ וְלֹא יַחְשְׁבוּ אַחֲרָיו. כָּעִנְיָן שֶׁנֶּאֱמַר (יחזקאל ב ה) \"וְיָדְעוּ כִּי נָבִיא הָיָה בְתוֹכָם\":"],"Mishneh Torah, Gifts to the Poor 1":["הַקּוֹצֵר אֶת שָׂדֵהוּ לֹא יִקְצֹר אֶת כָּל הַשָּׂדֶה כֻּלָּהּ אֶלָּא יַנִּיחַ מְעַט קָמָה לָעֲנִיִּים בְּסוֹף הַשָּׂדֶה שֶׁנֶּאֱמַר (ויקרא כג כב) \"לֹא תְכַלֶּה פְּאַת שָׂדְךָ בְּקֻצְרֶךָ\" אֶחָד הַקּוֹצֵר וְאֶחָד הַתּוֹלֵשׁ. וְזֶה שֶׁמַּנִּיחַ הוּא הַנִּקְרָא פֵּאָה:","וּכְשֵׁם שֶׁמַּנִּיחַ בַּשָּׂדֶה כָּךְ בָּאִילָנוֹת כְּשֶׁאוֹסֵף אֶת פֵּרוֹתֵיהֶן מַנִּיחַ מְעַט לָעֲנִיִּים. עָבַר וְקָצַר אֶת כָּל הַשָּׂדֶה אוֹ אָסַף כָּל פֵּרוֹת הָאִילָן לוֹקֵחַ מְעַט מִמַּה שֶּׁקָּצַר אוֹ מִמַּה שֶּׁאָסַף וְנוֹתְנוֹ לָעֲנִיִּים שֶׁנְּתִינָתוֹ מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (ויקרא כג כב) \"לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם\". וַאֲפִלּוּ טָחַן הַקָּמָה וְלָשׁוֹ וַאֲפָאוֹ פַּת הֲרֵי זֶה נוֹתֵן מִמֶּנּוּ פֵּאָה לָעֲנִיִּים:","אָבַד כָּל הַקָּצִיר שֶׁקָּצַר אוֹ נִשְׂרַף קֹדֶם שֶׁנָּתַן הַפֵּאָה הֲרֵי זֶה לוֹקֶה. שֶׁהֲרֵי עָבַר עַל מִצְוַת לֹא תַּעֲשֶׂה וְאֵינוֹ יָכוֹל לְקַיֵּם עֲשֵׂה שֶׁבָּהּ שֶׁנִּתָּק לוֹ:","וְכֵן בְּלֶקֶט כְּשֶׁקּוֹצֵר וּמְאַלֵּם לֹא יְלַקֵּט הַשִּׁבֳּלִים הַנּוֹפְלוֹת בִּשְׁעַת הַקָּצִיר אֶלָּא יַנִּיחֵם לָעֲנִיִּים שֶׁנֶּאֱמַר (ויקרא יט ט) (ויקרא כג כב) \"וְלֶקֶט קְצִירְךָ לֹא תְלַקֵּט\". עָבַר וּלְקָטָן אֲפִלּוּ טָחַן וְאָפָה נוֹתֵן לָעֲנִיִּים שֶׁנֶּאֱמַר (ויקרא כג כב) \"לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם\". אָבְדוּ אוֹ נִשְׂרְפוּ אַחַר שֶׁלְּקָטָן קֹדֶם שֶׁנָּתַן לָעֲנִיִּים לוֹקֶה:","וְכֵן בְּפֶרֶט שֶׁנִּפְרַט מִן הָעֲנָבִים בִּשְׁעַת הַבְּצִירָה וְכֵן בְּעוֹלֵלוֹת שֶׁנֶּאֱמַר (ויקרא יט י) \"וְכַרְמְךָ לֹא תְעוֹלֵל וּפֶרֶט כַּרְמְךָ לֹא תְלַקֵּט לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם\". וְכֵן הַמְעַמֵּר וְשָׁכַח אֲלֻמָּה אַחַת בַּשָּׂדֶה הֲרֵי זֶה לֹא יִקָּחֶנָּה שֶׁנֶּאֱמַר (דברים כד יט) \"וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה לֹא תָשׁוּב לְקַחְתּוֹ\". עָבַר וּלְקָטוֹ אֲפִלּוּ טְחָנוֹ וַאֲפָאוֹ הֲרֵי זֶה נוֹתְנוֹ לָעֲנִיִּים שֶׁנֶּאֱמַר (דברים כד יט) \"לַגֵּר לַיָּתוֹם וְלָאַלְמָנָה יִהְיֶה\" זוֹ מִצְוַת עֲשֵׂה הָא לָמַדְתָּ שֶׁכֻּלָּן מִצְוֹת לֹא תַּעֲשֶׂה הַנִּתָּק לַעֲשֵׂה הֵן וְאִם לֹא קִיֵּם עֲשֵׂה שֶׁבָּהֶן לוֹקֶה:","כְּשֵׁם שֶׁהַשִּׁכְחָה בָּעֳמָרִים כָּךְ הִיא בַּקָּמָה. אִם שָׁכַח מִקְצָת הַקָּמָה וְלֹא קְצָרָהּ הֲרֵי זוֹ לָעֲנִיִּים. וּכְשֵׁם שֶׁהַשִּׁכְחָה בַּתְּבוּאָה וְכַיּוֹצֵא בָּהּ כָּךְ יֵשׁ שִׁכְחָה לָאִילָנוֹת כֻּלָּן שֶׁנֶּאֱמַר (דברים כד כ) \"כִּי תַחְבֹּט זֵיתְךָ לֹא תְפַאֵר אַחֲרֶיךָ\" וְהוּא הַדִּין לִשְׁאָר הָאִילָנוֹת:","נִמְצֵאתָ לָמֵד שֶׁאַרְבַּע מַתָּנוֹת לָעֲנִיִּים בַּכֶּרֶם. הַפֶּרֶט וְהָעוֹלֵלוֹת וְהַפֵּאָה וְהַשִּׁכְחָה. וְשָׁלֹשׁ מַתָּנוֹת בַּתְּבוּאָה הַלֶּקֶט וְהַשִּׁכְחָה וְהַפֵּאָה. וּשְׁתַּיִם בָּאִילָנוֹת הַשִּׁכְחָה וְהַפֵּאָה:","כָּל מַתְּנוֹת עֲנִיִּים אֵלּוּ אֵין בָּהֶן טוֹבַת הֲנָיָה לַבְּעָלִים. אֶלָּא הָעֲנִיִּים בָּאִין וְנוֹטְלִין אוֹתָן עַל כָּרְחָן שֶׁל בְּעָלִים וַאֲפִלּוּ עָנִי שֶׁבְּיִשְׂרָאֵל מוֹצִיאִין אוֹתָן מִיָּדוֹ:","כָּל גֵּר הָאָמוּר בְּמַתְּנוֹת עֲנִיִּים אֵינוֹ אֶלָּא גֵּר צֶדֶק. שֶׁהֲרֵי הוּא אוֹמֵר בְּמַעֲשֵׂר שֵׁנִי (דברים יד כט) \"וּבָא הַלֵּוִי וְהַגֵּר\" מָה הַלֵּוִי בֶּן בְּרִית אַף הַגֵּר בֶּן בְּרִית. וְאַף עַל פִּי כֵן אֵין מוֹנְעִין עֲנִיֵּי עַכּוּ\"ם מִמַּתָּנוֹת אֵלּוּ. אֶלָּא בָּאִין בִּכְלַל עֲנִיֵּי יִשְׂרָאֵל וְנוֹטְלִין אוֹתָן מִפְּנֵי דַּרְכֵי שָׁלוֹם:","נֶאֱמַר בְּמַתְּנוֹת עֲנִיִּים (ויקרא יט י) (ויקרא כג כב) \"לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם\", כָּל זְמַן שֶׁהָעֲנִיִּים תּוֹבְעִין אוֹתָן. פָּסְקוּ הָעֲנִיִּים לְבַקֵּשׁ וּלְחַזֵּר עֲלֵיהֶם הֲרֵי הַנִּשְׁאָר מֵהֶן מֻתָּר לְכָל אָדָם. שֶׁאֵין גּוּפוֹ קָדוֹשׁ כִּתְרוּמוֹת. וְאֵינוֹ חַיָּב לִתֵּן לָהֶן דְּמֵיהֶן שֶׁלֹּא נֶאֱמַר בָּהֶן וְנָתַן לָעֲנִיִּים אֶלָּא תַּעֲזֹב אֹתָם. וְאֵינוֹ מְצֻוֶּה לַעֲזֹב אוֹתָן לַחַיָּה וְלָעוֹפוֹת אֶלָּא לָעֲנִיִּים וַהֲרֵי אֵין עֲנִיִּים:","מֵאֵימָתַי מֻתָּרִין כָּל אָדָם בְּלֶקֶט. מִשֶּׁיִּכָּנְסוּ הַמְלַקְּטִים שְׁנִיִּים וְיִלְקְטוּ אַחַר מְלַקְּטִים הָרִאשׁוֹנִים וְיֵצְאוּ. מֵאֵימָתַי מֻתָּרִין כָּל אָדָם בְּפֶרֶט וּבְעוֹלֵלוֹת מִשֶּׁהָלְכוּ הָעֲנִיִּים בַּכֶּרֶם וְיָבוֹאוּ. הַנִּשְׁאָר אַחֲרֵי כֵן מֻתָּר לְכָל אָדָם. מֵאֵימָתַי מֻתָּרִין כָּל אָדָם בְּשִׁכְחָה שֶׁל זֵיתִים. בְּאֶרֶץ יִשְׂרָאֵל אִם שָׁכַח אוֹתָהּ בְּרֹאשׁ הַזַּיִת הֲרֵי זֶה מֻתָּר בָּהּ מֵרֹאשׁ חֹדֶשׁ כִּסְלֵו שֶׁהוּא זְמַן רְבִיעָה שְׁנִיָּה בְּשָׁנָה אֲפִילָה. אֲבָל צִבּוּרֵי זֵיתִים שֶׁשְּׁכָחָן תַּחַת הָאִילָן הֲרֵי זֶה מֻתָּר בָּהֶן מִשֶּׁיִּפְסְקוּ הָעֲנִיִּים מִלְּחַזֵּר אַחֲרֶיהָ:","כָּל זְמַן שֶׁיֵּשׁ לֶעָנִי לִטּל שִׁכְחַת הַזֵּיתִים הַמֻּנָּחוֹת בָּאָרֶץ תַּחַת הָאִילָנוֹת נוֹטֵל. וְאַף עַל פִּי שֶׁכְּבָר הֻתַּר כָּל אָדָם בַּשִּׁכְחָה שֶׁבְּרֹאשׁ הָאִילָן. וְכָל זְמַן שֶׁיֵּשׁ לוֹ לִטּל שִׁכְחָה שֶׁבְּרֹאשׁ הָאִילָן נוֹטֵל. וְאַף עַל פִּי שֶׁעֲדַיִן אֵין לוֹ שִׁכְחָה תַּחְתָּיו:","מַתְּנוֹת עֲנִיִּים שֶׁבַּשָּׂדֶה שֶׁאֵין הָעֲנִיִּים מַקְפִּידִים עֲלֵיהֶן הֲרֵי הֵן שֶׁל בַּעַל הַשָּׂדֶה. וְאַף עַל פִּי שֶׁעֲדַיִן לֹא פָּסְקוּ הָעֲנִיִּים מִלַּחֲזֹר עַל מַתְּנוֹתֵיהֶם:","כָּל מַתְּנוֹת הָעֲנִיִּים הָאֵלּוּ אֵינָן נוֹהֲגוֹת מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל כִּתְרוּמוֹת וּמַעַשְׂרוֹת. הֲרֵי הַכָּתוּב אוֹמֵר (ויקרא יט ט) (ויקרא כג כב) \"וּבְקֻצְרְכֶם אֶת קְצִיר אַרְצְכֶם\" (דברים כד יט) \"כִּי תִקְצֹר קְצִירְךָ בְשָׂדֶךָ\". וּכְבָר נִתְפָּרֵשׁ בַּגְּמָרָא שֶׁהַפֵּאָה נוֹהֶגֶת בְּחוּצָה לָאָרֶץ מִדִּבְרֵיהֶם. וְיֵרָאֶה לִי שֶׁהוּא הַדִּין לִשְׁאָר מַתְּנוֹת עֲנִיִּים אֵלּוּ שֶׁכֻּלָּן נוֹהֲגוֹת בְּחוּצָה לָאָרֶץ מִדִּבְרֵיהֶם:","כַּמָּה הוּא שִׁעוּר הַפֵּאָה. מִן הַתּוֹרָה אֵין לָהּ שִׁעוּר אֲפִלּוּ הִנִּיחַ שִׁבּלֶת אַחַת יָצָא יְדֵי חוֹבָתוֹ. אֲבָל מִדִּבְרֵיהֶם אֵין פָּחוֹת מֵאֶחָד מִשִּׁשִּׁים בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּמוֹסִיף עַל הָאֶחָד מִשִּׁשִּׁים לְפִי גֹּדֶל הַשָּׂדֶה וּלְפִי רֹב הָעֲנִיִּים וּלְפִי בִּרְכַּת הַזֶּרַע. כֵּיצַד. שָׂדֶה שֶׁהִיא קְטַנָּה בְּיוֹתֵר שֶׁאִם הִנִּיחַ מִמֶּנָּה אֶחָד מִשִּׁשִּׁים אֵינוֹ מוֹעִיל לֶעָנִי הֲרֵי זֶה מוֹסִיף עַל הַשִּׁעוּר. וְכֵן אִם הָיוּ הָעֲנִיִּים מְרֻבִּין מוֹסִיף. וְאִם זָרַע מְעַט וְאָסַף הַרְבֵּה שֶׁהֲרֵי נִתְבָּרֵךְ מוֹסִיף לְפִי הַבְּרָכָה. וְכָל הַמּוֹסִיף עַל הַפֵּאָה מוֹסִיפִין לוֹ שָׂכָר. וְאֵין לְתוֹסֶפֶת זֹאת שִׁעוּר:"],"Mishneh Torah, Heave Offerings 11":["הַתְּרוּמָה נִתֶּנֶת לַאֲכִילָה וְלִשְׁתִיָּה וּלְסִיכָה שֶׁהַסִּיכָה הִיא כִּשְׁתִיָּה שֶׁנֶּאֱמַר (תהילים קט יח) \"וַתָּבֹא כַמַּיִם בְּקִרְבּוֹ וְכַשֶּׁמֶן בְּעַצְמוֹתָיו\". וְהַשְּׁתִיָּה בִּכְלַל אֲכִילָה. לֶאֱכל דָּבָר שֶׁדַּרְכּוֹ לֶאֱכל. וְלִשְׁתּוֹת דָּבָר שֶׁדַּרְכּוֹ לִשְׁתּוֹת. וְלָסוּךְ דָּבָר שֶׁדַּרְכּוֹ לָסוּךְ. לֹא יָסוּךְ יַיִן וְחֹמֶץ. אֲבָל סָךְ הוּא אֶת הַשֶּׁמֶן הַטָּהוֹר וּמַדְלִיק אֶת הַטָּמֵא וְזֶהוּ הַנִּקְרָא שֶׁמֶן שְׂרֵפָה בְּכָל מָקוֹם:","תְּמָרִים שֶׁל תְּרוּמָה מֻתָּר לְחָבְצָן וּלְקַבְּצָן כְּעִגּוּל הַדְּבֵלָה. וְאָסוּר לַעֲשׂוֹת מֵהֶם שֵׁכָר. וְכֵן אֵין עוֹשִׂין תְּמָרִים דְּבַשׁ וְלֹא תַּפּוּחִים יַיִן וְלֹא פֵּרוֹת הַסְּתָו חֹמֶץ. וְכֵן שְׁאָר כָּל הַפֵּרוֹת אֵין מְשַׁנִּין אוֹתָן מִבְּרִיָּתָן בִּתְרוּמָה חוּץ מִזֵּיתִים וַעֲנָבִים בִּלְבַד. עָבַר וְעָשָׂה הָאוֹכֵל מַשְׁקֶה הֲרֵי זֶה שׁוֹתֵהוּ. וְזָר שֶׁאָכַל דְּבַשׁ תְּמָרִים וְיֵין תַּפּוּחִים וְכַיּוֹצֵא בָּהֶן בִּשְׁגָגָה אֵינוֹ חַיָּב לְשַׁלֵּם. וְאִם אָכַל בְּמֵזִיד מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אֵין נוֹתְנִין דְּבֵלָה וּגְרוֹגָרוֹת לְתוֹךְ הַמֻּרְיָס מִפְּנֵי שֶׁהוּא מְאַבְּדָן. אֲבָל נוֹתְנִין אֶת הַיַּיִן לְתוֹךְ הַמֻּרְיָס. וְאֵין מְפַטְּמִין אֶת הַשֶּׁמֶן מִפְּנֵי שֶׁהוּא מוֹצִיאוֹ מִכְּלַל מַאֲכָלוֹת וְעוֹשֵׂהוּ שֶׁמֶן מִשְׁחָה. אֲבָל מְעָרְבִין יַיִן וּדְבַשׁ וּפִלְפְּלִין וְכַיּוֹצֵא בָּאֵלּוּ לְאָכְלָן:","אֵין מְבַשְּׁלִין יַיִן שֶׁל תְּרוּמָה מִפְּנֵי שֶׁהוּא מְמַעֲטוֹ. אֵין כּוֹבְשִׁין בְּצָלִים שֶׁל תְּרוּמָה בְּחֹמֶץ שֶׁל תְּרוּמָה מִפְּנֵי שֶׁמַּפְסִיד הַחֹמֶץ. אֵין מְעָרְבִין תְּבוּאָה בְּקִטְנִיּוֹת. וְכָל דָּבָר שֶׁיִּתְפָּרֵשׁ זֶה מִזֶּה כְּשֶׁכּוֹבְרִין אוֹתוֹ מְעָרְבִין. וּמִשֶּׁחָרְבָה יְהוּדָה הִתְחִילוּ לְעָרֵב תְּבוּאָה בִּתְבוּאָה וְקִטְנִית בְּקִטְנִית אֲבָל לֹא תְּבוּאָה בְּקִטְנִית:","כְּדֶרֶךְ שֶׁמְּרַקְּדִין אֶת הַקֶּמַח בְּחֻלִּין כָּךְ נוֹהֵג הַכֹּהֵן בִּתְרוּמָה. מְרַקֵּד לֶאֱכל וּמַשְׁלִיךְ אֶת הַמֻּרְסָן. הֲרֵי שֶׁרָצָה לַעֲשׂוֹת סלֶת מְנֻפֶּה בְּנָפָיוֹת הַרְבֵּה עַד שֶׁיּוֹצִיא קַב אוֹ קַבַּיִם מִן הַסְּאָה לֹא יַשְׁלִיךְ אֶת הַשְּׁאָר מִפְּנֵי שֶׁהוּא רָאוּי לַאֲכִילָה אֶלָּא יַנִּיחֵהוּ בְּמָקוֹם מֻצְנָע:","שֶׁמֶן שֶׁל תְּרוּמָה אֵין חוֹסְמִין בּוֹ תַּנּוּר וְכִירַיִם. וְאֵין סָכִין בּוֹ מִנְעָל וְסַנְדָּל. וְלֹא יָסוּךְ רַגְלוֹ וְהוּא בְּתוֹךְ מִנְעָל וְסַנְדָּל אֲבָל סָךְ אֶת רַגְלוֹ וְלוֹבֵשׁ הַמִּנְעָל אוֹ הַסַּנְדָּל וְסָךְ כָּל גּוּפוֹ וּמִתְעַגֵּל עַל גַּבֵּי קַטוֹבְלִיָּא חֲדָשָׁה וְאַף עַל פִּי שֶׁהֵן נִסּוֹכִין אֵינוֹ חוֹשֵׁשׁ. אֲבָל לֹא יִתֵּן שֶׁמֶן עַל גַּבֵּי טַבְלָא שֶׁל שַׁיִשׁ לְהִתְעַגֵּל עָלֶיהָ מִפְּנֵי שֶׁמְּאַבְּדוֹ:","כָּל הָאוֹכֵל תְּרוּמָה אֲפִלּוּ פֵּרוֹת צָרִיךְ נְטִילַת יָדַיִם אַף עַל פִּי שֶׁהָיוּ יָדָיו טְהוֹרוֹת כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. וְאֵינָהּ נֶאֱכֶלֶת עִם הַזָּר עַל הַשֻּׁלְחָן גְּזֵרָה שֶׁמָּא יֹאכַל מִמֶּנָּה. וּתְרוּמַת חוּצָה לָאָרֶץ נֶאֱכֶלֶת עִם הַזָּר עַל הַשֻּׁלְחָן וְאֵינָהּ צְרִיכָה נְטִילַת יָדַיִם כְּחֻלִּין. וְאֵין סָכִין תְּרוּמָה בְּיָדַיִם מְסֹאָבוֹת. נָפַל עַל בְּשָׂרוֹ מְשַׁפְשְׁפוֹ בְּיָדַיִם מְסֹאָבוֹת. אֲבָל סָכִין אֶת הַקָּטָן בְּשֶׁמֶן תְּרוּמָה בְּתוֹךְ שִׁבְעָה. שֶׁהַנּוֹלָד כָּל שִׁבְעָה אֵינוֹ חָשׁוּב עָרֵל:","סָךְ הוּא הַכֹּהֵן עַצְמוֹ בְּשֶׁמֶן שֶׁל תְּרוּמָה וּמֵבִיא בֶּן בִּתּוֹ יִשְׂרָאֵל וּמַעֲגִילוֹ עַל גַּבָּיו. וְאִם סָךְ עַצְמוֹ בְּשֶׁמֶן וְנִכְנָס לַמֶּרְחָץ מֻתָּר לְזָר לְמָשְׁחוֹ בַּמֶּרְחָץ אַף עַל פִּי שֶׁהוּא נִסּוֹךְ מִמֶּנּוּ:","כֹּהֶנֶת שֶׁחָפְפָה רֹאשָׁהּ בְּתִלְתָּן שֶׁל תְּרוּמָה אֵין הַיִּשְׂרְאֵלִית מֻתֶּרֶת לָחֹף אַחֲרֶיהָ. אֲבָל מְעַגֶּלֶת שְׂעָרָהּ בִּשְׂעָרָהּ. וּמִפְּנֵי מָה הֻתְּרוּ הַכֹּהֲנִים לָחֹף שְׂעָרָן בְּתִלְתָּן שֶׁל תְּרוּמָה מִפְּנֵי שֶׁאֵינוֹ רָאוּי לְמַאֲכַל אָדָם:","עֻקְצֵי תְּאֵנִים וּגְרוֹגָרוֹת וְהַכְּלִיסִים וְהֶחָרוּבִין וּמֵעֵי אֲבַטִּיחַ וּקְלִפֵּי אֲבַטִּיחַ וְאֶתְרוֹג וּמְלָפְפוֹן אַף עַל פִּי שֶׁאֵין בָּהֶן אֹכֶל וּקְנִיבַת יָרָק שֶׁמַּשְׁלִיכִין בַּעֲלֵי בָּתִּים הֲרֵי אֵלּוּ אֲסוּרִים לְזָרִים. אֲבָל קְנִיבַת יָרָק שֶׁמְּקַנְּבִים הַגַּנָּנִין מֻתֶּרֶת לְזָרִים. קְלִפֵּי פּוֹלִין וְשֻׁמְשְׁמִין אִם יֵשׁ בָּהֶן אֹכֶל אֲסוּרִין. אֵין בָּהֶן אֹכֶל מֻתָּרִין:","גַּרְעִינֵי אֶתְרוֹג מֻתָּרִים. גַּרְעִינֵי זֵיתִים וּתְמָרִים וְחָרוּבִין אַף עַל פִּי שֶׁלֹּא כְּנָסָן הַכֹּהֵן הֲרֵי אֵלּוּ אֲסוּרִין לְזָרִים. וּשְׁאָר הַגַּרְעִינִין בִּזְמַן שֶׁכְּנָסָן וְיֵשׁ בָּהֶן לַחְלוּחִית לִמְצֹץ אוֹתָן אֲסוּרִין לְזָר וְאִם הִשְׁלִיכָן מֻתָּרוֹת:","הַסֻּבִּין שֶׁל חִטִּים חֲדָשׁוֹת אֲסוּרִין מִפְּנֵי שֶׁהוּא רָאוּי לְמַאֲכַל אָדָם. וְשֶׁל יְשָׁנוֹת מֻתָּר. וְעַד מָתַי נִקְרְאוּ חֲדָשׁוֹת כָּל זְמַן שֶׁבְּנֵי אָדָם רְגִילִין לַחְבֹּט בֵּין הַגֳּרָנוֹת:","הַנְּצוֹלוֹת וְהָרַקְבָנִיּוֹת שֶׁל תְּרוּמָה אֲסוּרוֹת וְאִם הֶעֱלוּ אָבָק מֻתָּרוֹת. שְׁמָרִים שֶׁל תְּרוּמָה שֶׁנָּתַן עֲלֵיהֶם מַיִם הָרִאשׁוֹן וְהַשֵּׁנִי אָסוּר לְזָרִים וְהַשְּׁלִישִׁי מֻתָּר וְאִם לֹא נָתַן עֲלֵיהֶם מַיִם אֶלָּא מְסַנֵּן הַיַּיִן מֵעַל הַשְּׁמָרִים בִּלְבַד אַף הַשְּׁלִישִׁי אָסוּר לְזָרִים:","מְגוּרָה שֶׁפִּנָּה מִמֶּנָּה חִטֵּי תְּרוּמָה אֵין מְחַיְּבִין אוֹתוֹ לִהְיוֹת יוֹשֵׁב וּמְלַקֵּט אַחַת אַחַת וְאַחַר כָּךְ יִתֵּן לְתוֹכָהּ חֻלִּין אֶלָּא מְכַבֵּד כְּדַרְכּוֹ וְנוֹתֵן לְתוֹכָהּ חֻלִּין. וְכֵן חָבִית שֶׁל שֶׁמֶן תְּרוּמָה שֶׁנִּשְׁפְּכָה אֵין מְחַיְּבִין אוֹתוֹ לִהְיוֹת יוֹשֵׁב וּמְטַפֵּחַ אֶלָּא נוֹהֵג בָּהּ כְּדֶרֶךְ שֶׁנּוֹהֵג בְּחֻלִּין:","הַמְעָרֶה כַּד שֶׁל שֶׁמֶן תְּרוּמָה הֲרֵי זֶה מְעָרֶה עַד שֶׁיִּפְסֹק הָעַמּוּד וְיַתְחִיל הַשֶּׁמֶן לִנְטֹף מְעַט מְעַט וְכֵיוָן שֶׁנָּטְפוּ שָׁלֹשׁ טִפִּים זוֹ אַחַר זוֹ דַּיּוֹ. וּמֻתָּר לִתֵּן בְּכַד שֶׁמֶן חֻלִּין. הֲרֵי שֶׁלֹּא נָתַן אֶלָּא הִנִּיחַ הַכַּד עַד שֶׁנִּתְמַצֵּית אוֹתָהּ הַתַּמְצִית תְּרוּמָה:","מְמַלֵּא הַכֹּהֵן נֵר שֶׁמֶן שְׂרֵפָה וְנוֹתְנוֹ לְיִשְׂרָאֵל לַעֲלוֹת בּוֹ לַעֲלִיָּה וּלְהִכָּנֵס לַחֶדֶר לַעֲשׂוֹת צָרְכֵי הַכֹּהֵן אֲבָל לֹא צָרְכֵי יִשְׂרָאֵל. וְאִם הָיָה שֻׁתָּף עִמּוֹ מֻתָּר:","יִשְׂרָאֵל שֶׁהָיָה אוֹרֵחַ אֵצֶל כֹּהֵן וְהִדְלִיק לוֹ שֶׁמֶן שְׂרֵפָה וְעָמַד הַכֹּהֵן וְהָלַךְ לוֹ אֵינוֹ חַיָּב לְכַבּוֹתוֹ עַד שֶׁכָּבֶה מֵאֵלָיו וְטוֹבֵל הַיִּשְׂרָאֵל פְּתִילָה בְּנֵר הַכֹּהֵן וּמַדְלִיק לֵילֵךְ בָּהּ:","בְּקָרוֹ שֶׁל כֹּהֵן שֶׁהָיָה עוֹמֵד אֵצֶל בְּקָרוֹ שֶׁל יִשְׂרָאֵל. וְכֵלָיו שֶׁל כֹּהֵן שֶׁהָיָה נֶאֱרָג אֵצֶל כֵּלָיו שֶׁל יִשְׂרָאֵל. הֲרֵי זֶה מַדְלִיק עֲלֵיהֶן שֶׁמֶן שְׂרֵפָה שֶׁלֹּא בִּרְשׁוּת הַכֹּהֵן. וְכֵן מַדְלִיקִין שֶׁמֶן שְׂרֵפָה בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וּבַמְּבוֹאוֹת הָאֲפֵלִים שֶׁלֹּא בִּרְשׁוּת כֹּהֵן. וּמִי שֶׁאֵין לוֹ חֻלִּין לְהַדְלִיק נֵר חֲנֻכָּה מַדְלִיק שֶׁמֶן שְׂרֵפָה שֶׁלֹּא בִּרְשׁוּת הַכֹּהֵן. מַדְלִיקִין שֶׁמֶן שְׂרֵפָה עַל גַּבֵּי הַחֻלִּין בִּרְשׁוּת כֹּהֵן:","בַּת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן וְהִיא לְמוּדָה אֵצֶל אָבִיהָ מַדְלִיק בִּרְשׁוּתָהּ. מֻתָּר לְכֹהֵן לְהַדְלִיק שֶׁמֶן שְׂרֵפָה אֲפִלּוּ בְּבֵית הָאָבֵל אוֹ בְּבֵית הַמִּשְׁתֶּה שֶׁיֵּשׁ שָׁם עִרְבּוּב. וְאֵין חוֹשְׁשִׁין שֶׁמָּא יְסֻפְּקוּ מִמֶּנָּה בְּבֵית הַמִּשְׁתֶּה שֶׁמִּפְּנֵי נִקְיוֹן כְּלֵיהֶם אֵין נוֹגְעִין בּוֹ. וּבְבֵית הָאָבֵל מִפְּנֵי שֶׁאֵין לָהֶם פְּנַאי מִפְּנֵי הָאָבֵל:","הַזּוֹרֵעַ אֶת הַתְּרוּמָה בְּשׁוֹגֵג יְהַפֵּךְ בְּמֵזִיד יְקַיֵּם. הֵבִיאָה שְׁלִישׁ בֵּין בְּמֵזִיד בֵּין בְּשׁוֹגֵג יְקַיֵּם. וְאִם הָיָה פִּשְׁתָּן אֲפִלּוּ הֵבִיאָה שְׁלִישׁ וַאֲפִלּוּ בְּמֵזִיד יְהַפֵּךְ. קְנָס קָנְסוּ בּוֹ שֶׁלֹּא יִזְרַע וְיִתְכַּוֵּן לֵהָנוֹת בְּעֵצָיו:","גִּדּוּלֵי תְּרוּמָה הֲרֵי הֵן כְּחֻלִּין לְכָל דָּבָר אֶלָּא שֶׁאֲסוּרִים לְזָרִים. גָּזְרוּ חֲכָמִים עֲלֵיהֶן שֶׁיִּהְיוּ אֲסוּרִין לְזָרִים כִּתְרוּמָה מִשּׁוּם תְּרוּמָה טְמֵאָה שֶׁבְּיַד הַכֹּהֵן שֶׁלֹּא יַשְׁהֶנָּה אֶצְלוֹ כְּדֵי שֶׁיִּזְרָעֶנָּה וְתֵצֵא לְחֻלִּין וְנִמְצָא בָּא בָּהּ לִידֵי תַּקָּלָה. לְפִיכָךְ מֻתָּר לֶאֱכל הַגִּדּוּלִין בְּיָדַיִם טְמֵאוֹת וּמֻתָּר לִטְבוּל יוֹם כְּחֻלִּין:","גִּדּוּלֵי גִּדּוּלִין חֻלִּין לְכָל דָּבָר. וַאֲפִלּוּ דָּבָר שֶׁאֵין זַרְעוֹ כָּלֶה אִם רַבּוּ הַגִּדּוּלִין עַל הָעִקָּר בְּגִדּוּלֵי הַגִּדּוּלִין הֲרֵי הַגִּדּוּלִין הַשְּׁנִיִּים מַעֲלִין אֶת הָעִקָּר אַף עַל פִּי שֶׁאֵין זַרְעוֹ כָּלֶה וְיִהְיֶה הַכּל מֻתָּר לְזָרִים. וְכֵן תְּרוּמַת חוּצָה לָאָרֶץ וְהַמְדֻמָּע וְתוֹסֶפֶת תְּרוּמָה וְזֵרְעוֹנֵי גִּנָּה שֶׁאֵינָם נֶאֱכָלִים כְּגוֹן זֶרַע לֶפֶת וּצְנוֹן אַף עַל פִּי שֶׁאוֹתוֹ לֶפֶת וּצְנוֹן תְּרוּמָה גִּדּוּלֵיהֶן מֻתָּרִין וַהֲרֵי הֵן חֻלִּין לְכָל דָּבָר. וְכֵן הַזּוֹרֵעַ פִּשְׁתָּן שֶׁל תְּרוּמָה הַגִּדּוּלִין מֻתָּרִין לְזָרִים:","הַזּוֹרֵעַ תְּרוּמָה טְמֵאָה אַף עַל פִּי שֶׁהַגִּדּוּלִים טְהוֹרִין הֲרֵי הֵן אֲסוּרִין בַּאֲכִילָה. הוֹאִיל וְהַתְּרוּמָה שֶׁנִּזְרְעָה אֲסוּרָה בַּאֲכִילָה הָיְתָה כְּבָר נִדְּחוּ:","חָתַךְ אֶת הֶעָלִין שֶׁצָּמְחוּ וְיָצְאוּ עָלִין שְׁנִיִּין וַחֲתָכָן הֲרֵי אֹכֶל שֶׁיָּצָא אַחַר כָּךְ מֻתָּר בַּאֲכִילָה:","שְׁתִילֵי חֻלִּין שֶׁנִּטְמְאוּ וּזְרָעָן וַעֲשָׂאָן תְּרוּמָה הֲרֵי אֵלּוּ מֻתָּרִין. שֶׁהֲרֵי טָהֲרוּ בִּזְרִיעָה וְלֹא נִטְמְאוּ כְּשֶׁהֵן תְּרוּמָה כְּדֵי שֶׁיִּהְיוּ אֲסוּרִין:","שִׁבּלֶת שֶׁהָיְתָה בְּתוֹךְ הַכְּרִי וּמֵרַח הַכְּרִי כֻּלּוֹ הֲרֵי אוֹתָהּ הַשִּׁבּלֶת טֶבֶל. הוֹאִיל וְנִמְרְחָה בְּתוֹךְ הַכְּרִי. שְׁתָלָהּ וְאַחַר כָּךְ קָרָא עָלֶיהָ שֵׁם וַעֲשָׂאָהּ תְּרוּמָה הֲרֵי זוֹ סְפֵק תְּרוּמָה הוֹאִיל וּזְרָעָהּ. שֶׁמָּא פָּרַח הַטֶּבֶל מִמֶּנָּה וְנַעֲשֵׂית כְּפֵרוֹת שֶׁעֲדַיִן לֹא נִגְמְרוּ. אֲבָל אִם עֲשָׂאָהּ תְּרוּמָה קֹדֶם שֶׁיִּזְרָעֶנָּה הֲרֵי זוֹ תְּרוּמָה. לְפִיכָךְ אִם תָּלַשׁ מִמֶּנָּה וְאָכַל בְּמֵזִיד חַיָּב מִיתָה. בְּשׁוֹגֵג מְשַׁלֵּם אֶת הַחֹמֶשׁ. וְאִם גָּחַן וְאָכַל בְּפִיו מִן הָאָרֶץ בְּטֵלָה דַּעְתּוֹ אֵצֶל כָּל אָדָם. שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם בְּכָךְ. לְפִיכָךְ פָּטוּר מִן הַמִּיתָה וּמִן הַחֹמֶשׁ אִם הָיָה שׁוֹגֵג:","שָׂדֶה שֶׁל גִּדּוּלֵי תְּרוּמָה חַיֶּבֶת בְּלֶקֶט שִׁכְחָה וּפֵאָה וּבִתְרוּמָה וּמַעַשְׂרוֹת וּבְמַעֲשַׂר עָנִי. וַעֲנִיֵּי יִשְׂרָאֵל וַעֲנִיֵּי כֹּהֲנִים נוֹטְלִים מִמֶּנָּה מַתָּנוֹת אֵלּוּ. עֲנִיֵּי כֹּהֲנִים אוֹכְלִין אֶת שֶׁלָּהֶם וַעֲנִיֵּי יִשְׂרָאֵל מוֹכְרִין אֶת שֶׁלָּהֶם לַכֹּהֲנִים בִּדְמֵי תְּרוּמָה וְהַדָּמִים שֶׁל עֲנִיִּים. וְכֵן בֶּן לֵוִי מוֹכֵר הַמַּעֲשֵׂר שֶׁלּוֹ לַכֹּהֲנִים:","הַחוֹבֵט גִּדּוּלִין אֵלּוּ מְשֻׁבָּח. וְהַדָּשׁ בִּבְהֵמָה כֵּיצַד יַעֲשֶׂה. תּוֹלֶה כְּפִיפוֹת בְּצַוְּארֵי בְּהֵמָה וְנוֹתֵן לְתוֹכָן מֵאוֹתוֹ הַמִּין. נִמְצָא לֹא זוֹמֵם אֶת הַבְּהֵמָה וְלֹא מַאֲכִיל אֶת הַתְּרוּמָה:"],"Mishneh Torah, Heave Offerings 9":["הָאִשָׁה אוֹכֶלֶת בִּתְרוּמָה עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ אוֹ לְיַד שְׁלוּחָהּ שֶׁעָשְׂתָה לְקַבָּלָה. וְכָל שֶׁהִיא סְפֵק גְּרוּשָׁה הֲרֵי זוֹ לֹא תֹּאכַל. הָאִשָּׁה שֶׁעָשְׂתָה שָׁלִיחַ לְקַבֵּל לָהּ גִּטָּהּ אֲסוּרָה לֶאֱכל בִּתְרוּמָה מִיָּד. וְאִם אָמְרָה קַבֵּל לִי גִּטִּי בְּמָקוֹם פְּלוֹנִי אֵינָהּ אֲסוּרָה עַד שֶׁיַּגִּיעַ שָׁלִיחַ לְאוֹתוֹ מָקוֹם. שָׁלְחָה שָׁלִיחַ לְהָבִיא לָהּ גִּטָּהּ אוֹכֶלֶת בִּתְרוּמָה עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ. הָאוֹמֵר לְאִשְׁתּוֹ הֲרֵי זֶה גִּטֵּךְ שָׁעָה אַחַת קֹדֶם לְמִיתָתִי אֲסוּרָה לֶאֱכל בִּתְרוּמָה מִיָּד:","עִיר שֶׁהִקִּיפוּהָ כַּרְקוֹם וּסְפִינָה הַמִּטָּרֶפֶת בַּיָּם וְהַיּוֹצֵא לִדּוֹן הֲרֵי אֵלּוּ בְּחֶזְקַת קַיָּמִין. וְאֵין צָרִיךְ לוֹמַר מְפָרֵשׁ וְיוֹצֵא בְּשַׁיָּרָא. אֲבָל עִיר שֶׁכְּבָשׁוּהָ כַּרְקוֹם וּסְפִינָה שֶׁאָבְדָה בַּיָּם וְהַיּוֹצֵא לֵהָרֵג מִבָּתֵּי דִּינֵי עַכּוּ\"ם וּמִי שֶׁגְּרָרַתּוּ חַיָּה אוֹ נָפְלָה עָלָיו מַפּלֶת אוֹ שְׁטָפוֹ נָהָר נוֹתְנִין לוֹ חֻמְרֵי מֵתִים וְחֻמְרֵי חַיִּים. לְפִיכָךְ אִם הָיוּ נְשׁוֹתֵיהֶן בַּת כֹּהֵן לְיִשְׂרָאֵל אוֹ בַּת יִשְׂרָאֵל לְכֹהֵן הֲרֵי אֵלּוּ לֹא יֹאכְלוּ. אֲבָל מִי שֶׁנִּגְמַר דִּינוֹ בְּבֵית דִּין וְהִנִּיחוּהוּ בְּבֵית הַסְּקִילָה לֵהָרֵג הֲרֵי זֶה בְּחֶזְקַת מֵת וְלֹא תֹּאכַל אִשְׁתּוֹ:","הִנִּיחָה בַּעְלָהּ גּוֹסֵס בִּמְדִינָה אַחֶרֶת בֵּין שֶׁהָיְתָה כֹּהֶנֶת אֵשֶׁת יִשְׂרָאֵל אוֹ יִשְׂרְאֵלִית אֵשֶׁת כֹּהֵן לֹא תֹּאכַל שֶׁרֹב גּוֹסְסִין לְמִיתָה. אֶחָד אוֹמֵר מֵת וְאֶחָד אוֹמֵר לֹא מֵת הֲרֵי זוֹ לֹא תֹּאכַל:","אָמְרָה לָהּ צָרָתָהּ אוֹ אַחַת מֵהֶחָמֵשׁ נָשִׁים שֶׁאֵינָן נֶאֱמָנוֹת לְהָעִידָהּ שֶׁמֵּת בַּעְלָהּ הוֹאִיל וְאֵינָהּ נִשֵּׂאת עַל פִּיהֶן הֲרֵי זוֹ אוֹכֶלֶת בִּתְרוּמָה בְּחֶזְקַת שֶׁבַּעְלָהּ קַיָּם. עַד שֶׁיָּעִיד לָהּ מִי שֶׁהוּא נֶאֱמָן לְהַשִּׂיאָהּ עַל פִּיו:","הַמְשַׁחְרֵר אֶת עַבְדּוֹ מִשֶּׁיְּזַכֶּה לוֹ בְּגֵט שִׁחְרוּר פְּסָלוֹ מִלֶּאֱכל בִּתְרוּמָה. וְכָל עֶבֶד שֶׁיָּצָא לְחֵרוּת וַעֲדַיִן הוּא מְעֻכָּב גֵּט שִׁחְרוּר כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת עֲבָדִים אַף עַל פִּי כֵן הֲרֵי הוּא אָסוּר לֶאֱכל בִּתְרוּמָה:","הַכּוֹתֵב נְכָסָיו לְאַחֵר וְזִכָּה לוֹ עַל יְדֵי אַחֵר וְהָיוּ בָּהֶן עֲבָדִים וְשָׁתַק זֶה שֶׁנָּתְנוּ לוֹ וְאַחַר כָּךְ צָוַח הֲרֵי זֶה סָפֵק אִם זֶה שֶׁצָּוַח הוֹכִיחַ סוֹפוֹ עַל תְּחִלָּתוֹ וַעֲדַיִן לֹא יָצְאוּ מֵרְשׁוּת רִאשׁוֹן אוֹ זֶה שֶׁצָּוַח אַחַר שֶׁשָּׁתַק חָזַר בּוֹ. לְפִיכָךְ אֵין אוֹכְלִין בִּתְרוּמָה בֵּין שֶׁהָיָה רַבּוֹ שֵׁנִי יִשְׂרָאֵל וְהָרִאשׁוֹן כֹּהֵן בֵּין שֶׁהָיָה רַבּוֹ רִאשׁוֹן יִשְׂרָאֵל וְהַשֵּׁנִי כֹּהֵן:","יִשְׂרָאֵל שֶׁשָּׂכַר בְּהֵמָה מִכֹּהֵן מַאֲכִילָהּ תְּרוּמָה וְכֹהֵן שֶׁשָּׂכַר בֶּהֱמַת יִשְׂרָאֵל אַף עַל פִּי שֶׁהוּא חַיָּב בִּמְזוֹנוֹתֶיהָ לֹא יַאֲכִילֶנָּה תְּרוּמָה מִפְּנֵי שֶׁאֵינָהּ (ויקרא כב יא) \"קִנְיַן כַּסְפּוֹ\":","יִשְׂרָאֵל שֶׁשָּׁם פָּרָה מִכֹּהֵן לְפַטְּמָהּ וְלִהְיוֹת הַשֶּׁבַח בֵּינֵיהֶן לֹא יַאֲכִילֶנָּה בִּתְרוּמָה אַף עַל פִּי שֶׁיֵּשׁ לַכֹּהֵן חֵלֶק בְּשִׁבְחָהּ. אֲבָל כֹּהֵן שֶׁשָּׁם פָּרָה מִיִּשְׂרָאֵל לְפַטְּמָהּ אַף עַל פִּי שֶׁיֵּשׁ לְיִשְׂרָאֵל חֵלֶק בַּשֶּׁבַח הוֹאִיל וְגוּפָהּ לַכֹּהֵן שֶׁהֲרֵי שָׁמָהּ עַל עַצְמוֹ הֲרֵי זֶה מַאֲכִילָהּ תְּרוּמָה:","פָּרָתוֹ שֶׁל יִשְׂרָאֵל שֶׁיָּלְדָה בְּכוֹר מַאֲכִילוֹ תְּרוּמָה. שֶׁהַבְּכוֹר לַכֹּהֲנִים. וְאוֹצֵר אָדָם כַּרְשִׁינֵי תְּרוּמָה לְתוֹךְ שׁוֹבָכוֹ וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יָבוֹאוּ הַיּוֹנִים שֶׁלּוֹ וְיֹאכְלוּ אוֹתָן:","יֵרָאֶה לִי שֶׁאִם מָכַר הַכֹּהֵן פָּרָתוֹ לְיִשְׂרָאֵל וְלָקַח הַדָּמִים אַף עַל פִּי שֶׁעֲדַיִן לֹא מָשַׁךְ הַלּוֹקֵחַ הֲרֵי זֶה אָסוּר לְהַאֲכִילָהּ תְּרוּמָה שֶׁדִּין תּוֹרָה מָעוֹת קוֹנוֹת כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מִקָּח וּמִמְכָּר. וְאִם מָכַר יִשְׂרָאֵל לַכֹּהֵן אַף עַל פִּי שֶׁנָּתַן הַדָּמִים לֹא תֹּאכַל בִּתְרוּמָה עַד שֶׁיִּמְשֹׁךְ:"],"Mishneh Torah, Hiring 8":["אֶחָד הַשּׂוֹכֵר מֵחֲבֵרוֹ שָׂדֶה לְזָרְעָהּ אוֹ כֶּרֶם לֶאֱכל פֵּרוֹתָיו בְּדָמִים אוֹ שֶׁשָּׂכַר מִמֶּנּוּ בְּפֵרוֹת קְצוּבִים כְּגוֹן שֶׁשָּׂכַר מִמֶּנּוּ שָׂדֶה זוֹ בְּעֶשְׂרִים כּוֹר בְּשָׁנָה וְכֶרֶם זֶה בְּעֶשְׂרִים כַּדֵּי יַיִן בְּכָל שָׁנָה שְׁנֵיהֶן דִּין אֶחָד יֵשׁ לָהֶן. וְהַשּׂוֹכֵר בְּפֵרוֹת הוּא הַנִּקְרָא חוֹכֵר:","הַמְקַבֵּל שָׂדֶה אוֹ פַּרְדֵּס כְּדֵי לַעֲבֹד אוֹתוֹ וּלְהוֹצִיא עָלָיו יְצִיאוֹת וְיִתֵּן לְבַעַל הַקַּרְקַע שְׁלִישׁ הַתְּבוּאוֹת אוֹ רְבִיעַ אוֹ מַה שֶּׁיַּתְנוּ בֵּינֵיהֶן וְהוּא הַנִּקְרָא מְקַבֵּל. כָּל דָּבָר שֶׁהוּא לִסְיַג הָאָרֶץ בַּעַל הַקַּרְקַע חַיָּב בּוֹ וְכָל דָּבָר שֶׁהוּא שְׁמִירָה יְתֵרָה הַחוֹכֵר אוֹ הַמְקַבֵּל חַיָּב בּוֹ. הַקַּרְדֹּם שֶׁחוֹפְרִין בּוֹ הָאָרֶץ וְהַכֵּלִים שֶׁנּוֹשְׂאִין בָּהֶן הֶעָפָר וְהַדְּלִי וְהַכַּד וְכַיּוֹצֵא בָּהֶן שֶׁדּוֹלִין בָּהֶן הַמַּיִם עַל בַּעַל הַקַּרְקַע. וַחֲטִיטַת הַמְּקוֹמוֹת שֶׁמְּקַבְּצִין בָּהֶן הַמַּיִם עַל הַחוֹכֵר אוֹ עַל הַמְקַבֵּל:","הַשּׂוֹכֵר אוֹ הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ לְשָׁנִים מוּעָטוֹת לֹא יִזְרָעֶנָּה פִּשְׁתָּן. שְׂכָרָהּ אוֹ קִבְּלָהּ שֶׁבַע שָׁנִים זוֹרְעָהּ שָׁנָה רִאשׁוֹנָה פִּשְׁתָּן וְאֵין הַשְּׁבִיעִית מִן הַמִּנְיָן. שְׂכָרָהּ אוֹ קִבְּלָהּ שָׁבוּעַ אֶחָד שְׁבִיעִית מִן הַמִּנְיָן:","הַחוֹכֵר אוֹ הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ וְהִיא בֵּית הַשְּׁלָחִין אוֹ בֵּית הָאִילָן וְיָבְשָׁה מַעְיַן בֵּית הַשְּׁלָחִין וְלֹא פָּסַק הַנָּהָר הַגָּדוֹל אֶלָּא אֶפְשָׁר לְהָבִיא מִמֶּנּוּ בִּדְלִי. אוֹ שֶׁנִּקְצַץ הָאִילָן שֶׁל בֵּית הָאִילָנוֹת אֵינוֹ מְנַכֶּה לוֹ מֵחַכִּירוֹ. וְאִם מַכַּת מְדִינָה הִיא כְּגוֹן שֶׁיָּבַשׁ הַנָּהָר מְנַכֶּה לוֹ מֵחַכִּירוֹ. הָיָה עוֹמֵד בְּתוֹךְ הַשָּׂדֶה וְאָמַר לוֹ בֵּית הַשְּׁלָחִין הַזֶּה אֲנִי מַשְׂכִּיר לְךָ בֵּית הָאִילָן זֶה אֲנִי מַשְׂכִּיר יָבֵשׁ הַמַּעְיָן אוֹ נִקְצַץ הָאִילָן מְנַכֶּה מֵחַכִּירוֹ שֶׁהֲרֵי הוּא עוֹמֵד בְּתוֹכָהּ וְלֹא אָמַר לוֹ הַזֶּה אֶלָּא כְּמִי שֶּׁאוֹמֵר כְּמוֹת שֶׁהִיא עַתָּה אֲנִי מַשְׂכִּיר לְפִיכָךְ אִם לֹא הָיָה עוֹמֵד בְּתוֹכָהּ וְאָמַר לוֹ בֵּית הַשְּׁלָחִין אֲנִי מַשְׂכִּיר לְךָ אוֹ בֵּית הָאִילָן וְיָבֵשׁ הַמַּעְיָן אוֹ שֶׁנִּקְצַץ הָאִילָן אֵינוֹ מְנַכֶּה לוֹ מֵחַכִּירוֹ:","הַשּׂוֹכֵר אוֹ הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ וַאֲכָלָהּ חָגָב אוֹ נִשְׁתַּדְּפָה אִם אֵרַע דָּבָר זֶה לְרֹב הַשָּׂדוֹת שֶׁל אוֹתָהּ הָעִיר מְנַכֶּה לוֹ מֵחַכִּירוֹ הַכּל לְפִי הַהֶפְסֵד שֶׁאֵרְעוֹ וְאִם לֹא פָּשְׁטָה הַמַּכָּה בְּרֹב הַשָּׂדוֹת אֵינוֹ מְנַכֶּה לוֹ מֵחַכִּירוֹ אַף עַל פִּי שֶׁנִּשְׁתַּדְּפוּ כָּל הַשָּׂדוֹת שֶׁל בַּעַל הַקַּרְקַע. נִשְׁתַּדְּפוּ כָּל הַשָּׂדוֹת שֶׁל הַשּׂוֹכֵר אוֹ הַמְקַבֵּל אַף עַל פִּי שֶׁפָּשְׁטָה הַמַּכָּה בְּרֹב הַשָּׂדוֹת אֵינוֹ מְנַכֶּה לוֹ מֵחַכִּירוֹ שֶׁאֵין זֶה הַהֶפְסֵד תָּלוּי אֶלָּא בַּשּׂוֹכֵר שֶׁהֲרֵי כָּל שְׂדוֹתָיו נִשְׁתַּדְּפוּ. הִתְנָה עָלָיו בַּעַל הַקַּרְקַע שֶׁיִּזְרָעֶנָּה חִטִּים וּזְרָעָהּ שְׂעוֹרִים אוֹ שֶׁלֹּא זְרָעָהּ כְּלָל אוֹ שֶׁזְּרָעָהּ וְלֹא צָמְחָה אַף עַל פִּי שֶׁבָּא חָגָב אוֹ שִׁדָּפוֹן וְהֻכְּתָה רֹב הַמְּדִינָה אֵינוֹ מְנַכֶּה לוֹ מֵחַכִּירוֹ. וְעַד מָתַי חַיָּב לְהִטַּפֵּל וְלִזְרֹעַ פַּעַם אַחֶרֶת אִם לֹא צָמְחָה כָּל זְמַן שֶׁרָאוּי לִזְרִיעָה בְּאוֹתוֹ מָקוֹם:","הַשּׂוֹכֵר אוֹ הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ מָקוֹם שֶׁנָּהֲגוּ לִקְצֹר יִקְצֹר וְאֵינוֹ רַשַּׁאי לַעֲקֹר. לַעֲקֹר יַעֲקֹר וְאֵינוֹ רַשַּׁאי לִקְצֹר. וּשְׁנֵיהֶם מְעַכְּבִין זֶה עַל זֶה. וּמָקוֹם שֶׁנָּהֲגוּ לַחְרשׁ אַחֲרָיו יַחְרשׁ. מָקוֹם שֶׁנָּהֲגוּ לְהַשְׂכִּיר אִילָנוֹת עַל גַּב קַרְקַע מַשְׂכִּירִין וְאַף עַל פִּי שֶׁהִשְׂכִּיר לוֹ סְתָם בְּפָחוֹת מִן הַיָּדוּעַ. וּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לְהַשְׂכִּיר אִילָנוֹת אֵין לוֹ אִילָנוֹת אַף עַל פִּי שֶׁשָּׂכַר מִמֶּנּוּ בְּיֶתֶר עַל הַיָּדוּעַ. הַכּל כְּמִנְהַג הַמְּדִינָה:","הַחוֹכֵר שָׂדֶה מֵחֲבֵרוֹ בַּעֲשָׂרָה כּוֹר חִטִּים וְלָקְתָה נוֹתֵן לוֹ מִתּוֹכָהּ. הָיוּ חִטֶּיהָ יָפוֹת לֹא יֹאמַר לוֹ הֲרֵינִי לוֹקֵחַ לְךָ מִן הַשּׁוּק אֶלָּא נוֹתֵן לוֹ מִתּוֹכָהּ. חָכַר מִמֶּנּוּ כֶּרֶם בַּעֲשָׂרָה סַלֵּי עֲנָבִים וְהִקְרִיסוּ אַחַר שֶׁנִּבְצְרוּ וְכֵן עֳמָרִים שֶׁלָקוּ אַחַר שֶׁנִּקְצְרוּ נוֹתֵן לוֹ מִתּוֹכָן. חֲכָרוֹ בַּעֲשָׂרָה כַּדֵּי יַיִן וְהֶחְמִיץ חַיָּב לִתֵּן לוֹ יַיִן טוֹב. חֲכָרָהּ מִמֶּנּוּ בְּמֵאָה עֳמָרִים שֶׁל אַסְפַּסְתָּא וּזְרָעָהּ מִין אַחֵר וְאַחַר כָּךְ חֲרָשָׁהּ וּזְרָעָהּ אַסְפַּסְתָּא וְלָקְתָה אוֹ שֶׁזְּרָעָהּ בַּתְּחִלָּה אַסְפַּסְתָּא וַחֲרָשָׁהּ וְאַחַר כָּךְ זְרָעָהּ פַּעַם אַחֶרֶת וְלָקְתָה אֵינוֹ נוֹתֵן לוֹ מִתּוֹכָהּ אֶלָּא נוֹתֵן לוֹ אַסְפַּסְתָּא טוֹבָה שֶׁהֲרֵי שִׁנָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַחוֹכֵר שָׂדֶה מֵחֲבֵרוֹ וְלֹא רָצָה לְנַכֵּשׁ וְאָמַר לוֹ מַה הֶפְסֵד יֵשׁ לְךָ הֲרֵינִי נוֹתֵן לְךָ חַכִּירְךָ אֵין שׁוֹמְעִין לוֹ שֶׁהֲרֵי הוּא אוֹמֵר לוֹ לְמָחָר אַתָּה יוֹצֵא מִמֶּנָּה וְהִיא מַעֲלָה עֲשָׂבִים. וַאֲפִלּוּ אָמַר לוֹ בָּאַחֲרוֹנָה אֲנִי חוֹרֵשׁ אוֹתָהּ אֵין שׁוֹמְעִין לוֹ:","הַחוֹכֵר שָׂדֶה מֵחֲבֵרוֹ לְזָרְעָהּ שְׂעוֹרִים לֹא יִזְרָעֶנָּה חִטִּים מִפְּנֵי שֶׁהַחִטִּין מַכְחִישׁוֹת אֶת הַקַּרְקַע יֶתֶר מֵהַשְּׂעוֹרִים. שְׂכָרָהּ לְזָרְעָהּ חִטִּים יִזְרָעֶנָּה שְׂעוֹרִים. קִטְנִית לֹא יִזְרָעֶנָּה תְּבוּאָה. תְּבוּאָה יִזְרָעֶנָּה קִטְנִית. וּבְבָבֶל וְכַיּוֹצֵא בָּהּ לֹא יִזְרָעֶנָּה קִטְנִית מִפְּנֵי שֶׁהַקִּטְנִית שָׁם מַכְחֶשֶׁת אֶת הָאָרֶץ:","הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ לְשָׁנִים מוּעָטוֹת אֵין לַמְקַבֵּל כְּלוּם בְּקוֹרַת הַשִּׁקְמָה וְכַיּוֹצֵא בָּהּ וְלֹא בְּשֶׁבַח הָאִילָנוֹת שֶׁיָּצְאוּ מֵאֲלֵיהֶן בַּשָּׂדֶה. אֲבָל מְחַשְּׁבִין לוֹ מְקוֹם הָאִילָנוֹת כְּאִלּוּ הָיָה בָּהֶן אוֹתוֹ זֶרַע שֶׁזָּרַע בְּכָל הַשָּׂדֶה. וְהוּא שֶׁצָּמְחוּ הָאִילָנוֹת בְּמָקוֹם הָרָאוּי לִזְרִיעָה אֲבָל אִם יָצְאוּ בְּמָקוֹם שֶׁאֵינוֹ רָאוּי לִזְרִיעָה אֵין מְחַשְּׁבִין לוֹ כְּלוּם. וְאִם קִבְּלָהּ שֶׁבַע שָׁנִים אוֹ יֶתֶר יֵשׁ לוֹ בְּקוֹרַת הַשִּׁקְמָה וְכַיּוֹצֵא בָּהּ. הִגִּיעַ זְמַנּוֹ לְהִסְתַּלֵּק מִן הַשָּׂדֶה וְהָיוּ שָׁם זְרָעִים שֶׁעֲדַיִן לֹא הִגִּיעוּ לְהִמָּכֵר אוֹ שֶׁנִּגְמְרוּ וְלֹא הִגִּיעַ יוֹם הַשּׁוּק לְמָכְרָן שָׁמִין אוֹתָן וְנוֹטֵל מִבַּעַל הַקַּרְקַע. כְּשֵׁם שֶׁחוֹלְקִין הַמְקַבֵּל וּבַעַל הַקַּרְקַע בַּתְּבוּאָה כָּךְ חוֹלְקִין בַּתֶּבֶן וּבַקַּשׁ. כְּשֵׁם שֶׁחוֹלְקִין בַּיַּיִן כָּךְ חוֹלְקִין בַּזְּמוֹרוֹת. אֲבָל הַקָּנִים הַמַּעֲמִידִים תַּחַת הַגְּפָנִים אִם קָנוּ אוֹתָן בְּשֻׁתָּפוּת הֲרֵי אֵלּוּ חוֹלְקִין בָּהֶן וְאִם הֵן מִשֶּׁל אֶחָד מֵהֶן זֶה שֶׁקָּנָה אוֹתָן הֲרֵי הֵן שֶׁלּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ לִטַּע מְקַבֵּל עָלָיו בַּעַל הַשָּׂדֶה עֲשָׂרָה בּוֹרְאוֹת לִסְאָה. יֶתֶר עַל זֶה מְגַלְגְּלִין עָלָיו אֶת הַכּל:","הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ וְלֹא עָשְׂתָה אִם יֵשׁ בָּהּ כְּדֵי שֶׁתּוֹצִיא סָאתַיִם יֶתֶר עַל הַהוֹצָאָה חַיָּב הַמְקַבֵּל לִטָּפֵל בָּהּ. שֶׁכָּךְ כּוֹתֵב לְבַעַל הַקַּרְקַע אָנָּא אֵיקוּם וְאָנִיר וְאֶזְרַע וְאֶקְצֹר וְאֶעֱמֹר וְאָדוּשׁ וְאֶזְרֶה וְאַעֲמִיד כְּרִי לְפָנֶיךָ וְתִטּל אֶת חֶצְיוֹ אוֹ מַה שֶּׁיִּתְּנוּ וַאֲנִי אֶטּל הַשְּׁאָר בִּשְׂכַר עֲמָלִי וּבְמַה שֶּׁהוֹצֵאתִי:","הַמְקַבֵּל שָׂדֶה מֵחֲבֵרוֹ וְאַחַר שֶׁזָּכָה בָּהּ הוֹבִירָהּ שָׁמִין אוֹתָהּ כַּמָּה הִיא רְאוּיָה לַעֲשׂוֹת וְנוֹתֵן לוֹ חֶלְקוֹ שֶׁהָיָה מַגִּיעַ לוֹ. שֶׁכָּךְ כּוֹתֵב לְבַעַל הַקַּרְקַע אִם אוֹבִיר וְלֹא אַעֲבִיד אֲשַׁלֵּם בְּמֵיטָבָא. וְהוּא הַדִּין אִם הוֹבִיר מִקְצָתָהּ. וּמִפְּנֵי מָה נִתְחַיֵּב לְשַׁלֵּם מִפְּנֵי שֶׁלֹּא פָּסַק עַל עַצְמוֹ דָּבָר קָצוּב כְּדֵי שֶׁנֹּאמַר הֲרֵי הִיא כְּאַסְמַכְתָּא אֶלָּא הִתְנָה שֶׁיְּשַׁלֵּם בְּמֵיטָבָא וּלְפִיכָךְ גָּמַר וְשִׁעְבֵּד עַצְמוֹ. אֲבָל אִם אָמַר אִם אוֹבִיר וְלֹא אַעֲבִיד אֶתֵּן לְךָ מֵאָה דִּינָרִין הֲרֵי זוֹ אַסְמַכְתָּא וְאֵינוֹ חַיָּב לְשַׁלֵּם אֶלָּא נוֹתֵן כְּפִי מַה שֶּׁרְאוּיָה לַעֲשׂוֹת בִּלְבַד:","הַמְקַבֵּל שָׂדֶה לְזָרְעָהּ שֻׁמְשְׁמִין וּזְרָעָהּ חִטִּים וְעָשְׂתָה חִטִּים שֶׁשָּׁוִין כַּמָּה שֶׁהִיא רְאוּיָה לַעֲשׂוֹת מִן הַשֻּׁמְשְׁמִין אֵין לוֹ עָלָיו אֶלָּא תַּרְעֹמֶת. עָשְׂתָה פָּחוֹת מִמַּה שֶּׁהִיא רְאוּיָה לַעֲשׂוֹת מִן הַשֻּׁמְשְׁמִין מְשַׁלֵּם לוֹ הַמְקַבֵּל כְּפִי מַה שֶּׁהִיא רְאוּיָה לַעֲשׂוֹת מִן הַשֻּׁמְשְׁמִין. עָשְׂתָה חִטִּים יֶתֶר מִמַּה שֶּׁהִיא רְאוּיָה לַעֲשׂוֹת מִן הַשֻּׁמְשְׁמִין חוֹלְקִין לְפִי הַתְּנַאי שֶׁבֵּינֵיהֶן אַף עַל פִּי שֶׁמִּשְׂתַּכֵּר בַּעַל הַקַּרְקַע:"],"Mishneh Torah, Immersion Pools 2":["אֵלוּ חוֹצְצִין בָּאָדָם. לִפְלוּף שֶׁחוּץ לָעַיִן. וְגֶלֶד שֶׁחוּץ לַמַּכָּה. וְהַדָּם יָבֵשׁ שֶׁעַל גַּבֵּי הַמַּכָּה. וְהָרְטִיָּה שֶׁעָלֶיהָ. וְגִלְדֵי צוֹאָה שֶׁעַל בְּשָׂרוֹ. וּבָצֵק אוֹ טִיט שֶׁתַּחַת הַצִּפֹּרֶן. וְהַמִּלְמוּלִין שֶׁעַל הַגּוּף. וְטִיט הַיָּוֵן וְטִיט הַיּוֹצְרִים וְטִיט שֶׁל דְּרָכִים הַנִּמְצָא שָׁם תָּמִיד אֲפִלּוּ בִּימוֹת הַחַמָּה כָּל אֵלּוּ חוֹצְצִין. וּשְׁאָר כָּל הַטִּיט כְּשֶׁהוּא לַח אֵינוֹ חוֹצֵץ שֶׁהֲרֵי נִמְחָה בְּמַיִם וּכְשֶׁהוּא יָבֵשׁ חוֹצֵץ:","הַדְּבַשׁ. וְהַדְּיוֹ. וְהֶחָלָב. וְהַדָּם. וּשְׂרַף הַתּוּת. וְהַתְּאֵנָה. וְהַשִּׁקְמָה. וְהֶחָרוּב. יְבֵשִׁין חוֹצְצִין לַחִין אֵינָן חוֹצְצִין. וּשְׁאָר כָּל הַשְּׂרָפִין בֵּין לַחִין בֵּין יְבֵשִׁין חוֹצְצִין. וְדָם שֶׁנִּסְרַךְ בַּבָּשָׂר אֲפִלּוּ לַח חוֹצֵץ. הָאֵבֶר וְהַבָּשָׂר הַמְדֻלְדָּלִים חוֹצְצִין:","בֵּית הַסְּתָרִים בְּאִשָּׁה חוֹצֵץ עַד שֶׁתָּדִיחַ תְּחִלָּה. שֶׁהַזֵּעָה שָׁם תָּמִיד וְהֶאָבָק מִתְקַבֵּץ וְחוֹצֵץ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּנְשׂוּאָה. אֲבָל בִּפְנוּיָה הוֹאִיל וְאֵינָהּ מַקְפֶּדֶת אֵינוֹ חוֹצֵץ:","הָאֶגֶד שֶׁעַל גַּבֵּי הַמַּכָּה. וְהַקַּשְׂקַשִּׂין שֶׁעַל גַּבֵּי הַשֶּׁבֶר. וְהַשֵּׁירִים וְהַנְּזָמִים וְהַקַּטְלָיוֹת וְהַטַּבָּעוֹת. בִּזְמַן שֶׁהֵן חֲזָקִים וּדְבוּקִים בַּבָּשָׂר חוֹצְצִים. רָפִים אֵינָם חוֹצְצִין:","חוּטֵי צֶמֶר וְחוּטֵי פִּשְׁתָּן וְהָרְצוּעוֹת שֶׁקּוֹשְׁרוֹת הַנָּשִׁים בְּרָאשֵׁיהֶן לְנוֹי חוֹצְצִין מִפְּנֵי שֶׁמַּבְדִּילִין בֵּין הַגּוּף וּבֵין הַמַּיִם. אֲבָל חוּטֵי שֵׂעָר אֵין חוֹצְצִין מִפְּנֵי שֶׁהַמַּיִם בָּאִין בָּהֶן אַף עַל פִּי שֶׁאֵינָן רָפִין:","חוּטִין שֶׁבַּצַּוָּאר אֵינָן חוֹצְצִין אֲפִלּוּ שֶׁל פִּשְׁתָּן לְפִי שֶׁאֵין אִשָּׁה חוֹנֶקֶת עַצְמָהּ בָּהֶן. אֲבָל חֲבָקִים שֶׁבַּצַּוָּאר כְּגוֹן קַטְלָיוֹת וַעֲנָקִים חוֹצְצִין לְפִי שֶׁהָאִשָּׁה חוֹנֶקֶת עַצְמָהּ בָּהֶן כְּדֵי שֶׁתֵּרָאֶה בַּעֲלַת בָּשָׂר:","שֵׂעָר שֶׁעַל הַלֵּב שֶׁנִּתְקַשֵּׁר וְנַעֲשָׂה קִלְקִין. וְכֵן קִלְקֵי הַזָּקָן חוֹצְצִין:","חֵץ הַתָּחוּב בְּאָדָם בִּזְמַן שֶׁהוּא נִרְאֶה חוֹצֵץ. וּבַזְּמַן שֶׁאֵינוֹ נִרְאֶה טוֹבֵל וְאוֹכֵל בִּתְרוּמָתוֹ לָעֶרֶב אַף עַל פִּי שֶׁהוּא חֵץ טָמֵא. וְכֵן מִי שֶׁבָּלַע טַבַּעַת טָמֵא וְטָבַל הֲרֵי זֶה טָהוֹר. וְאִם הֱקִיאָהּ אַחַר שֶׁטָּבַל נִטְמָא בְּמַגָּעָהּ שֶׁכְּבָר בֵּאַרְנוּ שֶׁכָּל הַבְּלוּעִים בְּגוּף הַחַי לֹא מְטַמְּאִין וְלֹא מִתְטַמְּאִין. נִכְנְסוּ צְרוֹרוֹת וְקֵיסָמִין בְּסִדְקֵי רַגְלָיו מִלְּמַטָּה חוֹצְצִין:","אִסְפְּלָנִית מְלוּגְמָא וּרְטִיָּה שֶׁעַל בֵּית הַסְּתָרִים חוֹצְצִין. אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ שֶׁיִּכָּנְסוּ בָּהֶן הַמַּיִם צְרִיכִין שֶׁיִּהְיוּ רְאוּיִין וְלֹא יְהֵא בָּהֶן דָּבָר חוֹצֵץ כְּמוֹ שֶׁבֵּאַרְנוּ. הָיְתָה בּוֹ שְׂעָרָה אַחַת אוֹ שְׁתַּיִם חוּץ לַמַּכָּה וְרֹאשָׁהּ מֻדְבָּק לַמַּכָּה אוֹ שֶׁהָיוּ שְׁתֵּי שְׂעָרוֹת רֹאשָׁם מֻדְבָּק בְּטִיט אוֹ בְּצוֹאָה אוֹ שֶׁהָיוּ שְׁתֵּי שְׂעָרוֹת בְּרִיסֵי עֵינָיו מִלְּמַטָּה וּנְקָבָן וְהוֹצִיאָן בְּרִיסֵי עֵינָיו מִלְּמַעְלָה הֲרֵי אֵלּוּ חוֹצְצִין:","לֹא יִטְבּל אָדָם בֶּעָפָר שֶׁעַל רַגְלָיו וְאִם טָבַל אֵינוֹ חוֹצֵץ:","הָאוֹחֵז בְּאָדָם וּבְכֵלִים וְהִטְבִּילָן הֲרֵי הֵן בְּטֻמְאָתָן. וְאַף עַל פִּי שֶׁרִפָּה יָדָיו עַד שֶׁבָּאוּ בָּהֶן הַמַּיִם גְּזֵרָה שֶׁמָּא לֹא יַרְפֶּה. וְאִם הֵדִיחַ יָדָיו בַּמַּיִם עָלְתָה לָהֶן טְבִילָה:","הַמַּפְשֶׁלֶת בְּנָהּ לַאֲחוֹרָהּ וְטָבְלָה לֹא עָלְתָה לָהּ טְבִילָה שֶׁמָּא הָיָה טִיט בְּרַגְלֵי הַתִּינוֹק אוֹ בְּיָדָיו וְנִדְבַּק בְּאִמּוֹ בִּשְׁעַת טְבִילָה וְחָצַץ וְאַחַר שֶׁעָלְתָה נָפַל:","נִדָּה שֶׁנָּתְנָה שְׂעָרָהּ בְּפִיהָ אוֹ שֶׁקָּפְצָה יָדָהּ אוֹ שֶׁקָּרְצָה בְּשִׂפְתוֹתֶיהָ אוֹ שֶׁנִּמְצָא עֶצֶם בֵּין שִׁנֶּיהָ כְּאִלּוּ לֹא טָבְלָה. וְכֵן שְׁאָר כָּל הַטְּמֵאִים. נָתְנָה מָעוֹת בְּפִיהָ וְיָרְדָה וְטָבְלָה טָהֲרָה מִטֻּמְאַת הַנִּדָּה וַהֲרֵי הִיא טְמֵאָה עַל גַּב רֻקָּה וְנִמְצֵאת רִאשׁוֹן לְטֻמְאָה כְּמִי שֶׁנָּגַע בְּרֹק הַנִּדָּה. וְכֵן הַדִּין בְּזָב:","וְאֵלּוּ שֶׁאֵין חוֹצְצִין בְּאָדָם. קִלְקֵי הָרֹאשׁ וּבֵית הַשֶּׁחִי וּבֵית הַסְּתָרִים שֶׁבָּאִישׁ. וְלִפְלוּף שֶׁבָּעַיִן. וְגֶלֶד שֶׁהֶעֶלְתָה הַמַּכָּה. וְלִכְלוּכֵי צוֹאָה שֶׁעַל בְּשָׂרוֹ. וְצוֹאָה שֶׁתַּחַת הַצִּפֹּרֶן. וְצִפֹּרֶן הַמְדֻלְדֶּלֶת. וּכְשׁוּת הַקָּטָן וְהוּא הַשֵּׂעָר הַדַּק שֶׁעַל בְּשָׂרוֹ. כָּל אֵלּוּ אֵינָן חוֹצְצִין:","שְׁתֵּי שְׂעָרוֹת אוֹ יֶתֶר שֶׁהָיוּ קְשׁוּרִין כְּאַחַת קֶשֶׁר אֶחָד אֵינָן חוֹצְצִין מִפְּנֵי שֶׁהַמַּיִם בָּאִין בָּהֶן. וּשְׂעָרָה אַחַת שֶׁנִּקְשְׁרָה חוֹצֶצֶת וְהוּא שֶׁיִּהְיֶה מַקְפִּיד עָלֶיהָ. אֲבָל אִם אֵינוֹ מַקְפִּיד עָלֶיהָ עָלְתָה לוֹ טְבִילָה עַד שֶׁתִּהְיֶה רֹב שְׂעָרוֹ קָשׁוּר נִימָא נִימָא בִּפְנֵי עַצְמוֹ כָּזֶה הוֹרוּ הַגְּאוֹנִים. וְיֵרָאֶה לִי שֶׁשְּׂעָרוֹ שֶׁל אָדָם כְּגוּפוֹ הוּא חָשׁוּב לְעִנְיַן טְבִילָה וְאֵינוֹ כְּגוּף בִּפְנֵי עַצְמוֹ כְּדֵי שֶׁנֹּאמַר רֹב הַשֵּׂעָר אֶלָּא אַף עַל פִּי שֶׁכָּל שְׂעַר רֹאשׁוֹ קָשׁוּר נִימָא נִימָא אִם אֵינוֹ מַקְפִּיד עָלָיו עָלְתָה לוֹ טְבִילָה אֶלָּא אִם כֵּן נִצְטָרֵף לְחוֹצֵץ אַחֵר עַל גּוּפוֹ וְנִמְצָא הַכּל רֹב גּוּפוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֶחָד הַנִּדָּה וְאֶחָד שְׁאָר הַטְּמֵאִין שֶׁיֵּשׁ בְּרֹאשָׁן שֵׂעָר:","תַּקָּנַת עֶזְרָא הִיא שֶׁתִּהְיֶה אִשָּׁה חוֹפֶפֶת אֶת שְׂעָרָהּ וְאַחַר כָּךְ תִּטְבֹּל. וְאִם אֶפְשָׁר לָהּ לָחֹף בַּלַּיְלָה וְלִטְבּל מִיָּד תֵּכֶף לַחֲפִיפָה הֲרֵי זֶה מְשֻׁבָּח. וּבִשְׁעַת הַדְּחָק אוֹ מִפְּנֵי הַחלִי חוֹפֶפֶת אֲפִלּוּ בְּעֶרֶב שַׁבָּת וְטוֹבֶלֶת לְמוֹצָאֵי שַׁבָּת:","טָבְלָה וְעָלְתָה וְנִמְצָא עָלֶיהָ דָּבָר חוֹצֵץ אִם בְּאוֹתוֹ הַיּוֹם שֶׁחָפְפָה טָבְלָה אֵינָהּ צְרִיכָה לָחֹף פַּעַם שְׁנִיָּה אֶלָּא חוֹזֶרֶת וְטוֹבֶלֶת מִיָּד בִּלְבַד. וְאִם לָאו צְרִיכָה לָחֹף פַּעַם שְׁנִיָּה וְלִטְבֹּל:","לֹא תָּחֹף אִשָּׁה בְּנֶתֶר מִפְּנֵי שֶׁמְּקַטֵּף אֶת הַשֵּׂעָר. וְלֹא בְּאֹהֶל מִפְּנֵי שֶׁמַּסְרִיךְ אֶת הַשֵּׂעָר. אֶלָּא בְּחַמִּין וַאֲפִלּוּ בְּחַמֵּי חַמָּה מִפְּנֵי שֶׁהַחַמִּין מְיַשְּׁרִין אֶת הַשֵּׂעָר וּמְסַלְסְלִין אוֹתוֹ. אֲבָל הַצּוֹנְנִין מְקַלְקְלִין וּמְקַבְּצִין אֶת הַשֵּׂעָר וּמִתְקַשֵּׁר:","נִדָּה שֶׁנָּתְנָה תַּבְשִׁיל לִבְנָהּ וְטָבְלָה לֹא עָלְתָה לָהּ טְבִילָה מִפְּנֵי הַשַּׁמְנוּנִית שֶׁעַל יָדֶיהָ:","שָׂרְטָה בִּבְשָׂרָהּ וְהוֹצִיא דָּם וְטָבְלָה. בְּתוֹךְ שְׁלֹשָׁה יָמִים אֵין מְקוֹם הַשְּׂרִיטוֹת חוֹצֵץ לְאַחַר שְׁלֹשָׁה יָמִים חוֹצֵץ מִפְּנֵי שֶׁהַדָּם נִקְפֶּה שָׁם כְּגֶלֶד שֶׁעַל גַּבֵּי הַמַּכָּה. וְכֵן לִפְלוּף שֶׁבָּעַיִן אִם הָיָה יָבֵשׁ וְהוּא שֶׁהִתְחִיל לְהוֹרִיק חוֹצֵץ בְּנִדָּה:","כֹּחַל שֶׁבָּעַיִן אֵינוֹ חוֹצֵץ. שֶׁעַל גַּב הָעַיִן חוֹצֵץ. וְאִם הָיוּ עֵינֶיהָ פּוֹרְחוֹת אַף עַל גַּבֵּי הָעַיִן אֵינוֹ חוֹצֵץ:","פָּתְחָה עֵינֶיהָ בְּיוֹתֵר אוֹ עִצַּמְתָּן בְּיוֹתֵר לֹא עָלְתָה לָהּ טְבִילָה. בַּמֶּה דְּבָרִים אֲמוּרִים לְעִנְיַן טָהֳרוֹת. אֲבָל לְהַתִּירָהּ לְבַעֲלָהּ הֲרֵי זוֹ מֻתֶּרֶת. אַף עַל פִּי שֶׁנָּתְנָה תַּבְשִׁיל לִבְנָהּ אוֹ שֶׁהָיָה בָּהּ שֶׂרֶט יָשָׁן אוֹ שֶׁהָיָה עַל גַּב עֵינָהּ כֹּחַל. וּבֵין פָּתְחָה עֵינֶיהָ אוֹ עִצַּמְתָּן הֲרֵי זוֹ מֻתֶּרֶת לְבַעֲלָהּ שֶׁכָּל הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן אֵינָן חוֹצְצִין אֶלָּא מִדִּבְרֵיהֶן וּלְעִנְיַן טָהֳרוֹת גָּזְרוּ לְעִנְיַן בִּיאָה לֹא גָּזְרוּ. וְכָל הַחוֹצֵץ בְּנִדָּה לְטָהֳרוֹת חוֹצֵץ בִּשְׁאָר הַטְּמֵאִין לְעִנְיַן טָהֳרוֹת. וְחוֹצֵץ בְּגֵר בִּשְׁעַת טְבִילָה:","מִי שֶׁטָּבַל וְעָלָה וְנִמְצָא עָלָיו דָּבָר חוֹצֵץ אַף עַל פִּי שֶׁנִּתְעַסֵּק בְּאוֹתוֹ הַמִּין כָּל הַיּוֹם כֻּלּוֹ הֲרֵי הוּא בְּטֻמְאָתוֹ עַד שֶׁיֹּאמַר יוֹדֵעַ אֲנִי בְּוַדַּאי שֶׁלֹּא הָיָה זֶה עָלַי קֹדֶם הַטְּבִילָה הוֹאִיל וְהֻחְזַק טָמֵא הַעֲמֵד טָמֵא עַל טֻמְאָתוֹ עַד שֶׁתֵּדַע בְּוַדַּאי שֶׁטָּהַר:"],"Mishneh Torah, Inheritances 3":["אֵין הַבְּכוֹר נוֹטֵל פִּי שְׁנַיִם בִּנְכָסִים הָרְאוּיִין לָבוֹא לְאַחַר מִיתַת אָבִיו אֶלָּא בִּנְכָסִים הַמֻּחְזָקִין לְאָבִיו שֶׁבָּאוּ לִרְשׁוּתוֹ שֶׁנֶּאֱמַר (דברים כא יז) \"בְּכל אֲשֶׁר יִמָּצֵא לוֹ\". כֵּיצַד. אֶחָד מִמּוֹרִישֵׁי אָבִיו שֶׁמֵּת לְאַחַר מִיתַת אָבִיו הַבְּכוֹר וְהַפָּשׁוּט יוֹרְשִׁין כְּאֶחָד. וְכֵן אִם הָיְתָה לְאָבִיו מִלְוֶה אוֹ הָיְתָה לוֹ סְפִינָה בַּיָּם יוֹרְשִׁין כְּאֶחָד:","הִנִּיחַ לָהֶם פָּרָה מֻשְׂכֶּרֶת אוֹ מֻחְכֶּרֶת אוֹ שֶׁהָיְתָה רוֹעָה בָּאֲפָר וְיָלְדָה. הַבְּכוֹר נוֹטֵל בָּהּ וּבִוְלָדָהּ פִּי שְׁנַיִם:","שָׁחַט אֶחָד מִמַּכִּירֵי אָבִיו בְּהֵמָה וְאַחַר כָּךְ מֵת אָבִיו נוֹטֵל פִּי שְׁנַיִם בַּמַּתָּנוֹת שֶׁל אוֹתָהּ בְּהֵמָה:","אֵין הַבְּכוֹר נוֹטֵל פִּי שְׁנַיִם בַּשֶּׁבַח שֶׁשָּׁבְחוּ נְכָסִים לְאַחַר מִיתַת אָבִיו אֶלָּא מַעֲלֶה אוֹתוֹ הַשֶּׁבַח בְּדָמִים וְנוֹתֵן הַיֶּתֶר לַפָּשׁוּט. וְהוּא שֶׁיִּשְׁתַּנּוּ הַנְּכָסִים כְּגוֹן כַּרְמֶל שֶׁנַּעֲשׂוּ שִׁבֳּלִים וְכִפְנִיּוֹת שֶׁנַּעֲשׂוּ תְּמָרִים. אֲבָל שָׁבְחוּ מֵחֲמַת עַצְמָן וְלֹא נִשְׁתַּנּוּ כְּגוֹן אִילָן קָטָן שֶׁגָּדַל וְעָבָה וְאֶרֶץ שֶׁהֶעֶלְתָה שִׂרְטוֹן הֲרֵי זֶה נוֹטֵל בַּשֶּׁבַח פִּי שְׁנַיִם. וְאִם מֵחֲמַת הוֹצָאָה הִשְׁבִּיחַ אֵינוֹ נוֹטֵל:","אֵין הַבְּכוֹר נוֹטֵל פִּי שְׁנַיִם בְּמִלְוֶה אַף עַל פִּי שֶׁהוּא בִּשְׁטָר אַף עַל גַּב שֶׁגָּבוּ קַרְקַע בְּחוֹב אֲבִיהֶם. הָיָה לְאָב מִלְוֶה בְּיַד הַבְּכוֹר הֲרֵי זֶה סָפֵק אִם נוֹטֵל בָּהּ פִּי שְׁנַיִם הוֹאִיל וְיֶשְׁנָהּ תַּחַת יָדוֹ. אוֹ לֹא יִטּל הוֹאִיל וּמֵחֲמַת אָבִיו יִירָשֶׁנָּה וַעֲדַיִן לֹא בָּאָה לְיָדוֹ שֶׁל אָבִיו. לְפִיכָךְ יִטּל מִמֶּנָּה חֲצִי חֵלֶק בְּכוֹרָה:","בְּכוֹר שֶׁמָּכַר חֵלֶק בְּכוֹרָה קֹדֶם חֲלוּקָה מִמְכָּרוֹ קַיָּם מִפְּנֵי שֶׁיֵּשׁ לַבְּכוֹר חֵלֶק בְּכוֹרָה קֹדֶם חֲלוּקָה. לְפִיכָךְ אִם חָלַק עִם אֶחָיו קוֹדֵם בְּמִקְצָת נְכָסִים בֵּין בַּקַּרְקַע בֵּין בְּמִטַּלְטְלִין וְנָטַל חֵלֶק כְּפָשׁוּט וִתֵּר בְּכָל הַנְּכָסִים וְאֵינוֹ נוֹטֵל בִּשְׁאֵרָן אֶלָּא כְּפָשׁוּט. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא מִחָה. אֲבָל אִם מִחָה בְּאֶחָיו וְאָמַר בִּפְנֵי שְׁנַיִם עֲנָבִים אֵלּוּ שֶׁאֲנִי חוֹלֵק עִם אֶחָי בְּשָׁוֶה לֹא מִפְּנֵי שֶׁמָּחַלְתִּי בְּחֵלֶק בְּכוֹרָה הֲרֵי זֶה מְחָאָה וְלֹא וִתֵּר בִּשְׁאָר נְכָסִים. וַאֲפִלּוּ מִחָה בַּעֲנָבִים כְּשֶׁהֵן מְחֻבָּרִים וּבְצָרוּם וְחִלְּקוּם בְּשָׁוֶה לֹא וִתֵּר בִּשְׁאָר נְכָסִים. אֲבָל אִם דְּרָכוּם וְחָלַק עִמָּהֶן בְּשָׁוֶה בְּיַיִן וְלֹא מִחָה בָּהֶן מִשֶּׁנַּעֲשָׂה יַיִן וִתֵּר בִּשְׁאָר הַנְּכָסִים. הָא לְמָה זֶה דּוֹמֶה לְמִי שֶׁמִּחָה בַּעֲנָבִים וְחָלַק עִמָּהֶם בְּשָׁוֶה בַּזֵיתִים שֶׁהֲרֵי וִתֵּר בַּכּל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁיִּבֵּם אֵשֶׁת אָחִיו הוּא יוֹרֵשׁ כָּל נִכְסֵי אֶחָיו הַמֻּחְזָקִים. וְכָל הָרְאוּיִין לָבוֹא לְאַחַר מִכָּאן הֲרֵי הוּא בָּהֶן כְּכָל הָאַחִים שֶׁהֲרֵי בְּכוֹר קָרָא אוֹתוֹ הַכָּתוּב שֶׁנֶּאֱמַר (דברים כה ו) \"וְהָיָה הַבְּכוֹר אֲשֶׁר תֵּלֵד יָקוּם עַל שֵׁם אָחִיו הַמֵּת וְלֹא יִמָּחֶה שְׁמוֹ מִיִּשְׂרָאֵל\". וּכְשֵׁם שֶׁאֵינוֹ נוֹטֵל מִמֶּנּוּ בְּרָאוּי כִּבְמֻחְזָק כָּךְ אֵינוֹ נוֹטֵל בַּשֶּׁבַח שֶׁשָּׁבְחוּ נְכָסִים אַחֲרֵי מוֹת אָבִיו מִשְּׁעַת מִיתָה עַד שְׁעַת חֲלוּקָתוֹ עִם אֶחָיו בְּנִכְסֵי אָבִיו. וַאֲפִלּוּ הִשְׁבִּיחוּ נְכָסִים אַחַר שֶׁיִּבֵּם וְקֹדֶם שֶׁיַּחְלְקוּ הֲרֵי הוּא בַּשֶּׁבַח כְּאֶחָד מִן הָאַחִין. אַף עַל פִּי שֶׁנּוֹטֵל מִן הַנְּכָסִים אֵלּוּ שְׁנֵי חֲלָקִים חֶלְקוֹ וְחֵלֶק אָחִיו שֶׁיִּבֵּם אִשְׁתּוֹ הוֹאִיל וּמֵת הָאָב בְּחַיֵּי כֻּלָּן:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת שְׁכֵנִים שֶׁהַבְּכוֹר נוֹטֵל שְׁנֵי חֲלָקִים שֶׁלּוֹ כְּאֶחָד בְּמֵצַר אֶחָד. אֲבָל הַיָּבָם שֶׁחָלַק עִם אֶחָיו בְּנִכְסֵי אָבִיו נוֹטֵל חֶלְקוֹ וְחֵלֶק אָחִיו בְּגוֹרָל. וְאִם עָלָה גּוֹרָלוֹ בִּשְׁנֵי מְקוֹמוֹת נוֹטֵל בִּשְׁנֵי מְקוֹמוֹת:","שׁוֹמֶרֶת יָבָם שֶׁמֵּתָה אֲפִלּוּ עָשָׂה בָּהּ אֶחָד מִן הָאַחִים מַאֲמָר מִשְׁפַּחַת בֵּית אָבִיהָ יוֹרְשִׁין בְּנִכְסֵי מְלוֹג וַחֲצִי נִכְסֵי צֹאן בַּרְזֶל. וְיוֹרְשֵׁי הַבַּעַל יוֹרְשִׁין כְּתֻבָּתָהּ עִם חֲצִי נִכְסֵי צֹאן בַּרְזֶל. וְיוֹרְשֵׁי הַבַּעַל חַיָּבִין בִּקְבוּרָתָהּ הוֹאִיל וְהֵן יִירְשׁוּ כְּתֻבָּתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ:"],"Mishneh Torah, Kings and Wars 3":["בְּעֵת שֶׁיֵּשֵׁב הַמֶּלֶךְ עַל כִּסֵּא מַלְכוּתוֹ כּוֹתֵב לוֹ סֵפֶר תּוֹרָה לְעַצְמוֹ יֶתֶר עַל הַסֵּפֶר שֶׁהִנִּיחוּ לוֹ אֲבוֹתָיו. וּמַגִּיהוֹ מִסֵּפֶר הָעֲזָרָה עַל פִּי בֵּית דִּין שֶׁל שִׁבְעִים וְאֶחָד. אִם לֹא הִנִּיחוּ לוֹ אֲבוֹתָיו אוֹ שֶׁנֶּאֱבַד כּוֹתֵב שְׁנֵי סִפְרֵי תּוֹרָה. אֶחָד מַנִּיחוֹ בְּבֵית גְּנָזָיו שֶׁהוּא מְצֻוֶּה בּוֹ כְּכָל אֶחָד מִיִּשְׂרָאֵל. וְהַשֵּׁנִי לֹא יָזוּז מִלְּפָנָיו אֶלָּא בְּעֵת שֶׁיִּכָּנֵס לְבֵית הַכִּסֵּא. אוֹ לְבֵית הַמֶּרְחָץ. אוֹ לְמָקוֹם שֶׁאֵין רָאוּי לִקְרִיאָה. יוֹצֵא לַמִּלְחָמָה וְהוּא עִמּוֹ. נִכְנָס וְהוּא עִמּוֹ. יוֹשֵׁב בַּדִּין וְהוּא עִמּוֹ. מֵסֵב וְהוּא כְּנֶגְדּוֹ שֶׁנֶּאֱמַר (דברים יז יט) \"וְהָיְתָה עִמּוֹ וְקָרָא בוֹ כָּל יְמֵי חַיָּיו\":","לֹא יַרְבֶּה לוֹ נָשִׁים. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהוּא לוֹקֵחַ עַד שְׁמוֹנֶה עֶשְׂרֵה נָשִׁים בֵּין הַנָּשִׁים וּפִלַּגְשִׁים הַכּל שְׁמוֹנֶה עֶשְׂרֵה. וְאִם הוֹסִיף אַחַת וּבְעָלָהּ לוֹקֶה. וְיֵשׁ לוֹ לְגָרֵשׁ וְלִשָּׂא אַחֶרֶת תַּחַת זוֹ שֶׁגֵּרֵשׁ:","וְלֹא יַרְבֶּה לוֹ סוּסִים אֶלָּא כְּדֵי מֶרְכַּבְתּוֹ. אֲפִלּוּ סוּס אֶחָד פָּנוּי לִהְיוֹת רָץ לְפָנָיו כְּדֶרֶךְ שֶׁעוֹשִׂין שְׁאָר הַמְּלָכִים אָסוּר. וְאִם הוֹסִיף לוֹקֶה:","וְלֹא יַרְבֶּה לוֹ כֶּסֶף וְזָהָב לְהַנִּיחַ בִּגְנָזָיו וּלְהִתְגָּאוֹת בּוֹ אוֹ לְהִתְנָאוֹת בּוֹ. אֶלָּא כְּדֵי שֶׁיִּתֵּן לְחֵילוֹתָיו וְלַעֲבָדָיו וּלְשַׁמָּשָׁיו. וְכָל כֶּסֶף וְזָהָב שֶׁיַּרְבֶּה לְאוֹצַר בֵּית ה' וְלִהְיוֹת שָׁם מוּכָן לְצָרְכֵי הַצִּבּוּר וּלְמִלְחֲמוֹתָם הֲרֵי זֶה מִצְוָה לְהַרְבּוֹתוֹ. וְאֵין אָסוּר אֶלָּא לְהַרְבּוֹת לְעַצְמוֹ בְּבֵית גְּנָזָיו שֶׁנֶּאֱמַר (דברים יז יז) \"וְלֹא יַרְבֶּה לּוֹ\". וְאִם הִרְבָּה לוֹקֶה:","הַמֶּלֶךְ אָסוּר לִשְׁתּוֹת דֶּרֶךְ שִׁכְרוּת. שֶׁנֶּאֱמַר (משלי לא ד) \"אַל לַמְלָכִים שְׁתוֹ יָיִן\". אֶלָּא יִהְיֶה עוֹסֵק בַּתּוֹרָה וּבְצָרְכֵי יִשְׂרָאֵל בַּיּוֹם וּבַלַּיְלָה. שֶׁנֶּאֱמַר (דברים יז יט) \"וְהָיְתָה עִמּוֹ וְקָרָא בוֹ כָּל יְמֵי חַיָּיו\":","וְכֵן לֹא יִהְיֶה שָׁטוּף בְּנָשִׁים. אֲפִלּוּ לֹא הָיְתָה לוֹ אֶלָּא אַחַת לֹא יִהְיֶה מָצוּי אֶצְלָהּ תָּמִיד כִּשְׁאָר הַטִּפְּשִׁים. שֶׁנֶּאֱמַר (משלי לא ג) \"אַל תִּתֵּן לַנָּשִׁים חֵילֶךָ\". עַל הֲסָרַת לִבּוֹ הִקְפִּידָה תּוֹרָה שֶׁנֶּאֱמַר (דברים יז יז) \"וְלֹא יָסוּר לְבָבוֹ\". שֶׁלִּבּוֹ הוּא לֵב כָּל קְהַל יִשְׂרָאֵל לְפִיכָךְ דִּבְּקוֹ הַכָּתוּב בַּתּוֹרָה יֶתֶר מִשְּׁאָר הָעָם שֶׁנֶּאֱמַר (דברים יז יט) \"כָּל יְמֵי חַיָּיו\":","כְּבָר בֵּאַרְנוּ שֶׁמַּלְכֵי בֵּית דָּוִד דָּנִין אוֹתָן וּמְעִידִין עֲלֵיהֶן. אֲבָל מַלְכֵי יִשְׂרָאֵל גָּזְרוּ חֲכָמִים שֶׁלֹּא יָדוּן וְלֹא דָּנִין אוֹתוֹ. וְלֹא מֵעִיד וְלֹא מְעִידִין עָלָיו. מִפְּנֵי שֶׁלִּבָּן גַּס בָּהֶן וְיָבוֹא מִן הַדָּבָר תַּקָּלָה וְהֶפְסֵד עַל הַדָּת:","כָּל הַמּוֹרֵד בְּמֶלֶךְ יִשְׂרָאֵל יֵשׁ לַמֶּלֶךְ רְשׁוּת לְהָרְגוֹ. אֲפִלּוּ גָּזַר עַל אֶחָד מִשְּׁאָר הָעָם שֶׁיֵּלֵךְ לְמָקוֹם פְּלוֹנִי וְלֹא הָלַךְ אוֹ שֶׁלֹּא יָצָא מִבֵּיתוֹ וְיָצָא חַיָּב מִיתָה. וְאִם רָצָה לְהָרְגוֹ יֵהָרֵג. שֶׁנֶּאֱמַר (יהושע א יח) \"כָּל אִישׁ אֲשֶׁר יַמְרֶה אֶת פִּיךָ\". וְכֵן כָּל הַמְבַזֶּה אֶת הַמֶּלֶךְ אוֹ הַמְחָרְפוֹ יֵשׁ לַמֶּלֶךְ רְשׁוּת לְהָרְגוֹ. כְּשִׁמְעִי בֶּן גֵּרָא. וְאֵין לַמֶּלֶךְ רְשׁוּת לַהֲרֹג אֶלָּא בְּסַיִף בִּלְבַד. וְיֵשׁ לוֹ לֶאֱסֹר וּלְהַכּוֹת בְּשׁוֹטִין לִכְבוֹדוֹ. אֲבָל לֹא יַפְקִיר מָמוֹן וְאִם הִפְקִיר הֲרֵי זֶה גֵּזֶל:","הַמְבַטֵּל גְּזֵרַת הַמֶּלֶךְ בִּשְׁבִיל שֶׁנִּתְעַסֵּק בְּמִצְוֹת. אֲפִלּוּ בְּמִצְוָה קַלָּה הֲרֵי זֶה פָּטוּר. דִּבְרֵי הָרַב וְדִבְרֵי הָעֶבֶד דִּבְרֵי הָרַב קוֹדְמִין. וְאֵין צָרִיךְ לוֹמַר אִם גָּזַר הַמֶּלֶךְ לְבַטֵּל מִצְוָה שֶׁאֵין שׁוֹמְעִין לוֹ:","כָּל הַהוֹרֵג נְפָשׁוֹת שֶׁלֹּא בִּרְאָיָה בְּרוּרָה. אוֹ בְּלֹא הַתְרָאָה. אֲפִלּוּ בְּעֵד אֶחָד. אוֹ שׂוֹנֵא שֶׁהָרַג בִּשְׁגָגָה. יֵשׁ לַמֶּלֶךְ רְשׁוּת לְהָרְגוֹ וּלְתַקֵּן הָעוֹלָם כְּפִי מַה שֶּׁהַשָּׁעָה צְרִיכָה. וְהוֹרֵג רַבִּים בְּיוֹם אֶחָד וְתוֹלֶה וּמַנִּיחָן תְּלוּיִים יָמִים רַבִּים לְהָטִיל אֵימָה וּלְשַׁבֵּר יַד רִשְׁעֵי הָעוֹלָם:"],"Mishneh Torah, Leavened and Unleavened Bread 6":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לֶאֱכל מַצָּה בְּלֵיל חֲמִשָּׁה עָשָׂר שֶׁנֶּאֱמַר (שמות יב יח) \"בָּעֶרֶב תֹּאכְלוּ מַצֹּת\". בְּכָל מָקוֹם וּבְכָל זְמַן. וְלֹא תָּלָה אֲכִילָה זוֹ בְּקָרְבַּן הַפֶּסַח אֶלָּא זוֹ מִצְוָה בִּפְנֵי עַצְמָהּ וּמִצְוָתָהּ כָּל הַלַּיְלָה. אֲבָל בִּשְׁאָר הָרֶגֶל אֲכִילַת מַצָּה רְשׁוּת רָצָה אוֹכֵל מַצָּה רָצָה אוֹכֵל אֹרֶז אוֹ דֹּחַן אוֹ קְלָיוֹת אוֹ פֵּרוֹת. אֲבָל בְּלֵיל חֲמִשָּׁה עָשָׂר בִּלְבַד חוֹבָה. וּמִשֶּׁאָכַל כְּזַיִת יָצָא יְדֵי חוֹבָתוֹ:","בָּלַע מַצָּה יָצָא. בָּלַע מָרוֹר לֹא יָצָא. בָּלַע מַצָּה וּמָרוֹר כְּאֶחָד יְדֵי מַצָּה יָצָא יְדֵי מָרוֹר לֹא יָצָא. שֶׁהַמָּרוֹר כִּטְפֵלָה לַמַּצָּה. כְּרָכָן בְּסִיב וְכַיּוֹצֵא בּוֹ וּבְלָעָן אַף יְדֵי מַצָּה לֹא יָצָא:","אָכַל מַצָּה בְּלֹא כַּוָּנָה כְּגוֹן שֶׁאֲנָסוּהוּ עַכּוּ\"ם אוֹ לִסְטִים לֶאֱכֹל יָצָא יְדֵי חוֹבָתוֹ. אָכַל כְּזַיִת מַצָּה וְהוּא נִכְפֶּה בְּעֵת שְׁטוּתוֹ וְאַחַר כָּךְ נִתְרַפֵּא חַיָּב לֶאֱכל אַחַר שֶׁנִּתְרַפֵּא. לְפִי שֶׁאוֹתָהּ אֲכִילָה הָיְתָה בְּשָׁעָה שֶׁהָיָה פָּטוּר מִכָּל הַמִּצְוֹת:","אֵין אָדָם יוֹצֵא יְדֵי חוֹבַת אֲכִילַת מַצָּה אֶלָּא אִם כֵּן אֲכָלָהּ מֵאֶחָד מֵחֲמֵשֶׁת הַמִּינִין שֶׁנֶּאֱמַר (דברים טז ג) \"לֹא תֹאכַל עָלָיו חָמֵץ שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת\". דְּבָרִים הַבָּאִים לִידֵי חִמּוּץ אִם אֲכָלָן מַצָּה יָצָא בָּהֶן יְדֵי חוֹבָתוֹ אֲבָל שְׁאָר דְּבָרִים כְּגוֹן אֹרֶז וְדֹחַן וְקִטְנִיּוֹת אֵין יוֹצֵא בָּהֶן יְדֵי מַצָּה לְפִי שֶׁאֵין בָּהֶן חָמֵץ:","הָעוֹשֶׂה עִסָּה מִן הַחִטִּים וּמִן הָאֹרֶז אִם יֵשׁ בָּהּ טַעַם דָּגָן יוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ. עִסַּת הַכְּלָבִים בִּזְמַן שֶׁהָרוֹעִים אוֹכְלִין מִמֶּנָּה יוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ. אֵין הָרוֹעִים אוֹכְלִין מִמֶּנָּה אֵינוֹ יוֹצֵא בָּהּ שֶׁאֵין זוֹ מְשֻׁמֶּרֶת לְשֵׁם מַצָּה. מַצָּה שֶׁלָּשָׁהּ בְּמֵי פֵּרוֹת יוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ בְּפֶסַח. אֲבָל אֵין לָשִׁין אוֹתָהּ בְּיַיִן אוֹ בְּשֶׁמֶן אוֹ חָלָב מִשּׁוּם (דברים טז ג) \"לֶחֶם עֹנִי\" כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם לָשׁ וְאָכַל לֹא יָצָא יְדֵי חוֹבָתוֹ. אֵין יוֹצְאִין לֹא בְּפַת מֻרְסָן וְלֹא בְּפַת סֻבִּין. אֲבָל לָשׁ הוּא אֶת הַקֶּמַח בַּסֻּבִּין שֶׁלּוֹ וּבְמוּרְסָנוֹ וְעוֹשֵׂהוּ פַּת וְיוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ. וְכֵן פַּת סלֶת נְקִיָּה בְּיוֹתֵר הֲרֵי זוֹ מֻתֶּרֶת וְיוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ בְּפֶסַח וְאֵין אוֹמְרִין בָּהּ אֵין זֶה לֶחֶם עֹנִי:","אֶחָד מַצָּה שֶׁנֶּאֱפֵית בְּתַנּוּר אוֹ בְּאִלְפָּס. בֵּין שֶׁהִדְבִּיק הַבָּצֵק בַּאִלְפָּס וְאַחַר כָּךְ הִרְתִּיחַ בֵּין שֶׁהִרְתִּיחַ וְאַחַר כָּךְ הִדְבִּיק אֲפִלּוּ אֲפָאָהּ בַּקַּרְקַע הֲרֵי זֶה יוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ. וְכֵן אִם לֹא נַאֲפֵית אֲפִיָּה גְּמוּרָה יוֹצְאִין בָּהּ. וְהוּא שֶׁלֹּא יִהְיוּ חוּטִין שֶׁל בָּצֵק נִמְשָׁכִין מִמֶּנָּה בְּעֵת שֶׁפּוֹרְסָהּ. וְיוֹצְאִין בְּרָקִיק הַשָּׁרוּי וְהוּא שֶׁלֹּא נִמּוֹחַ. אֲבָל מַצָּה שֶׁבִּשְּׁלָהּ אֵינוֹ יוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ בַּאֲכִילָתָהּ שֶׁהֲרֵי אֵין בָּהּ טַעַם פַּת:","אֵין אָדָם יוֹצֵא יְדֵי חוֹבָתוֹ בַּאֲכִילַת מַצָּה שֶׁהִיא אֲסוּרָה לוֹ כְּגוֹן שֶׁאָכַל בּוֹ טֶבֶל אוֹ מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ אוֹ שֶׁגְּזָלָהּ. זֶה הַכְּלָל כָּל שֶׁמְּבָרְכִין עָלָיו בִּרְכַּת הַמָּזוֹן יוֹצֵא בּוֹ יְדֵי חוֹבָתוֹ וְכָל שֶׁאֵין מְבָרְכִין עָלָיו בִּרְכַּת הַמָּזוֹן אֵין יוֹצֵא בּוֹ יְדֵי חוֹבָתוֹ:","הַכֹּהֲנִים יוֹצְאִין בְּחַלָּה וּבִתְרוּמָה אַף עַל פִּי שֶׁהִיא מַצָּה שֶׁאֵינָהּ רְאוּיָה לְכָל אָדָם. וְכֵן יוֹצְאִין בְּמַצָּה שֶׁל מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם. אֲבָל אֵין יוֹצְאִין בְּמַצָּה שֶׁל בִּכּוּרִים אֲפִלּוּ בִּירוּשָׁלַיִם מִפְּנֵי שֶׁהַבִּכּוּרִים אֵין לָהֶם הֶתֵּר בְּכָל הַמּוֹשָׁבוֹת. וּמַעֲשֵׂר שֵׁנִי אֶפְשָׁר שֶׁיִּפָּדֶה וְיֵאָכֵל בְּכָל מָקוֹם. וְכָתוּב (שמות יב כ) \"בְּכל מוֹשְׁבֹתֵיכֶם תֹּאכְלוּ מַצּוֹת\" מַצָּה הָרְאוּיָה לְהֵאָכֵל בְּכָל הַמּוֹשָׁבוֹת הוּא שֶׁיּוֹצְאִין בָּהּ יְדֵי חוֹבָה:","חַלּוֹת תּוֹדָה וּרְקִיקֵי נָזִיר שֶׁעָשׂוּ אוֹתָן לְעַצְמָן אֵין יוֹצְאִין בָּהֶן שֶׁנֶּאֱמַר (שמות יב יז) \"וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת\" מַצָּה הַמִּשְׁתַּמֶּרֶת לְעִנְיַן מַצָּה בִּלְבַד הוּא שֶׁיּוֹצְאִין בָּהּ אֲבָל זוֹ מִשְׁתַּמֶּרֶת לְעִנְיַן הַזֶּבַח. וְאִם עֲשָׂאָן לִמְכֹּר בַּשּׁוּק הֲרֵי זֶה יוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ. שֶׁהָעוֹשֶׂה לִמְכֹּר בַּשּׁוּק דַּעְתּוֹ שֶׁאִם לֹא יִמָּכְרוּ יֹאכַל אוֹתָן וְנִמְצָא בִּשְׁעַת עֲשִׂיָּתָן שְׁמָרָן לְשֵׁם מַצָּה:","הַכּל חַיָּבִין בַּאֲכִילַת מַצָּה אֲפִלּוּ נָשִׁים וַעֲבָדִים. קָטָן שֶׁיָּכוֹל לֶאֱכל פַּת מְחַנְּכִין אוֹתוֹ בְּמִצְוֹת וּמַאֲכִילִין אוֹתוֹ כְּזַיִת מַצָּה. חוֹלֶה אוֹ זָקֵן שֶׁאֵינוֹ יָכוֹל לֶאֱכל שׁוֹרִין לוֹ רָקִיק בְּמַיִם וּמַאֲכִילִין אוֹתוֹ וְהוּא שֶׁלֹּא נִמּוֹחַ:","מִדִּבְרֵי סוֹפְרִים שֶׁאֵין מַפְטִירִין אַחַר מַצָּה כְּלוּם וַאֲפִלּוּ קְלָיוֹת וֶאֱגוֹזִים וְכַיּוֹצֵא בָּהֶן. אֶלָּא אַף עַל פִּי שֶׁאָכַל מַצָּה וְאָכַל אַחֲרֶיהָ מַאֲכָלוֹת אֲחֵרוֹת וּפֵרוֹת וְכַיּוֹצֵא בָּהֶן חוֹזֵר וְאוֹכֵל כְּזַיִת מַצָּה בָּאַחֲרוֹנָה וּפוֹסֵק:","אָסְרוּ חֲכָמִים לֶאֱכֹל מַצָּה בְּעֶרֶב הַפֶּסַח כְּדֵי שֶׁיִּהְיֶה הֶכֵּר לַאֲכִילָתָהּ בָּעֶרֶב. וּמִי שֶׁאָכַל מַצָּה בְּעֶרֶב הַפֶּסַח מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת עַד שֶׁתֵּצֵא נַפְשׁוֹ. וְכֵן אָסוּר לֶאֱכֹל עֶרֶב הַפֶּסַח מִקֹּדֶם הַמִּנְחָה כִּמְעַט. כְּדֵי שֶׁיִּכָּנֵס לַאֲכִילַת מַצָּה בְּתַאֲוָה. אֲבָל אוֹכֵל הוּא מְעַט פֵּרוֹת אוֹ יְרָקוֹת וְלֹא יְמַלֵּא כְּרֵסוֹ מֵהֶן. וַחֲכָמִים הָרִאשׁוֹנִים הָיוּ מַרְעִיבִין עַצְמָן עֶרֶב הַפֶּסַח כְּדֵי לֶאֱכֹל מַצָּה בְּתַאֲוָה וְיִהְיוּ מַצּוֹת חֲבִיבוֹת עָלָיו. אֲבָל בִּשְׁאָר עַרְבֵי שַׁבְּתוֹת אוֹ עַרְבֵי יָמִים טוֹבִים אוֹכֵל וְהוֹלֵךְ עַד שֶׁתֶּחְשַׁךְ:"],"Mishneh Torah, Marriage 1":["קֹדֶם מַתַּן תּוֹרָה הָיָה אָדָם פּוֹגֵעַ אִשָּׁה בַּשּׁוּק אִם רָצָה הוּא וְהִיא לִשָּׂא אוֹתָהּ מַכְנִיסָהּ לְתוֹךְ בֵּיתוֹ וּבוֹעֲלָהּ בֵּינוֹ לְבֵין עַצְמוֹ וְתִהְיֶה לוֹ לְאִשָּׁה. כֵּיוָן שֶׁנִּתְּנָה תּוֹרָה נִצְטַוּוּ יִשְׂרָאֵל שֶׁאִם יִרְצֶה הָאִישׁ לִשָּׂא אִשָּׁה יִקְנֶה אוֹתָהּ תְּחִלָּה בִּפְנֵי עֵדִים וְאַחַר כָּךְ תִּהְיֶה לוֹ לְאִשָּׁה שֶׁנֶּאֱמַר (דברים כב יג) \"כִּי יִקַּח אִישׁ אִשָּׁה וּבָא אֵלֶיהָ\":","וְלִקּוּחִין אֵלּוּ מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה הֵם. וּבְאֶחָד מִשְּׁלֹשָׁה דְּבָרִים אֵלּוּ הָאִשָּׁה נִקְנֵית. בְּכֶסֶף. אוֹ בִּשְׁטָר. אוֹ בְּבִיאָה. בְּבִיאָה וּבִשְׁטָר מֵהַתּוֹרָה. וּבְכֶסֶף מִדִּבְרֵי סוֹפְרִים. וְלִקּוּחִין אֵלּוּ הֵן הַנִּקְרָאִין קִדּוּשִׁין אוֹ אֵרוּסִין בְּכָל מָקוֹם. וְאִשָּׁה שֶׁנִּקְנֵית בְּאֶחָד מִשְּׁלֹשָׁה דְּבָרִים אֵלּוּ הִיא הַנִּקְרֵאת מְקֻדֶּשֶׁת אוֹ מְאֹרֶסֶת:","וְכֵיוָן שֶׁנִּקְנֵית הָאִשָּׁה וְנַעֲשֵׂית מְקֻדֶּשֶׁת אַף עַל פִּי שֶׁלֹּא נִבְעֲלָה וְלֹא נִכְנְסָה לְבֵית בַּעְלָהּ הֲרֵי הִיא אֵשֶׁת אִישׁ וְהַבָּא עָלֶיהָ חוּץ מִבַּעְלָהּ חַיָּב מִיתַת בֵּית דִּין. וְאִם רָצָה לְגָרֵשׁ צְרִיכָה גֵּט:","קֹדֶם מַתַּן תּוֹרָה הָיָה אָדָם פּוֹגֵעַ אִשָּׁה בַּשּׁוּק אִם רָצָה הוּא וְהִיא נוֹתֵן לָהּ שְׂכָרָהּ וּבוֹעֵל אוֹתָהּ עַל אֵם הַדֶּרֶךְ וְהוֹלֵךְ. וְזוֹ הִיא הַנִּקְרֵאת קְדֵשָׁה. מִשֶּׁנִּתְּנָה הַתּוֹרָה נֶאֶסְרָה הַקְּדֵשָׁה שֶׁנֶּאֱמַר (דברים כג יח) \"לֹא תִהְיֶה קְדֵשָׁה מִבְּנוֹת יִשְׂרָאֵל\". לְפִיכָךְ כָּל הַבּוֹעֵל אִשָּׁה לְשֵׁם זְנוּת בְּלֹא קִדּוּשִׁין לוֹקֶה מִן הַתּוֹרָה לְפִי שֶׁבָּעַל קְדֵשָׁה:","כָּל שֶׁאָסַר בִּיאָתוֹ בַּתּוֹרָה וְחַיָּב עַל בִּיאָתוֹ כָּרֵת וְהֵם הָאֲמוּרוֹת בְּפָרָשַׁת (ויקרא טז א) \"אַחֲרֵי מוֹת\" הֵן הַנִּקְרָאוֹת עֲרָיוֹת וְכָל אַחַת מֵהֶן נִקְרֵאת עֶרְוָה כְּגוֹן אֵם וְאָחוֹת וּבַת וְכַיּוֹצֵא בָּהֶן:","וְיֵשׁ נָשִׁים אֲחֵרוֹת שֶׁהֵן אֲסוּרוֹת מִפִּי הַקַּבָּלָה וְאִסּוּרָן מִדִּבְרֵי סוֹפְרִים וְהֵן הַנִּקְרָאוֹת שְׁנִיּוֹת מִפְּנֵי שֶׁהֵן שְׁנִיּוֹת לָעֲרָיוֹת וְכָל אַחַת מֵהֶן נִקְרֵאת שְׁנִיָּה. וְעֶשְׂרִים נָשִׁים הֵן וְאֵלּוּ הֵן. א) אֵם אִמּוֹ וְזוֹ אֵין לָהּ הֶפְסֵק אֶלָּא אֲפִלּוּ אֵם אֵם אֵם אִמּוֹ עַד מַעְלָה מַעְלָה אֲסוּרָה: ב) אֵם אֲבִי אִמּוֹ בִּלְבַד: ג) אֵם אָבִיו וְזוֹ אֵין לָהּ הֶפְסֵק אֶלָּא אֲפִלּוּ אֵם אֵם אֵם אָבִיו עַד לְמַעְלָה אֲסוּרָה: ד) אֵם אֲבִי אָבִיו בִּלְבַד: ה) אֵשֶׁת אֲבִי אָבִיו וְזוֹ אֵין לָהּ הֶפְסֵק אֲפִלּוּ אֵשֶׁת יַעֲקֹב אָבִינוּ אֲסוּרָה עַל אֶחָד מִמֶּנּוּ: ו) אֵשֶׁת אֲבִי אִמּוֹ בִּלְבַד: ז) אֵשֶׁת אֲחִי הָאָב מִן הָאֵם: ח) אֵשֶׁת אֲחִי הָאֵם בֵּין מִן הָאֵם בֵּין מִן הָאָב: ט) כַּלַּת בְּנוֹ וְזוֹ אֵין לָהּ הֶפְסֵק אֲפִלּוּ כַּלַּת בֶּן בֶּן בֶּן בְּנוֹ עַד סוֹף כָּל הָעוֹלָם אֲסוּרָה עַד שֶׁתִּהְיֶה אֵשֶׁת אֶחָד מִמֶּנּוּ שְׁנִיָּה עַל יַעֲקֹב אָבִינוּ: י) כַּלַּת בִּתּוֹ בִּלְבַד: יא) בַּת בַּת בְּנוֹ בִּלְבַד: יב) בַּת בֶּן בְּנוֹ בִּלְבַד: יג) בַּת בַּת בִּתּוֹ בִּלְבַד: יד) בַּת בֶּן בִּתּוֹ בִּלְבַד: טו) בַּת בֶּן בֶּן אִשְׁתּוֹ בִּלְבַד: טז) בַּת בַּת בַּת אִשְׁתּוֹ בִּלְבַד: יז) אֵם אֵם אֲבִי אִשִׁתּוֹ בִּלִבַד: יח) אֵם אַב אֵם אִשִׁתּוֹ בִּלִבַד: יט) אֵם אֵם אֵם אִשִׁתּוֹ בִּלִבַד: כ) אֵם אַב אֲבִי אִשִׁתּוֹ בִּלִבַד. נִמְצְאוּ הַשְּׁנִיּוֹת שֶׁאֵין לָהֶן הֶפְסֵק אַרְבַּע. אֵם הָאֵם עַד לְמַעְלָה. וְאֵם הָאָב עַד לְמַעְלָה. וְאֵשֶׁת אֲבִי הָאָב עַד לְמַעְלָה. וְאֵשֶׁת בֶּן בְּנוֹ עַד לְמַטָּה:","כָּל שֶׁאָסַר בִּיאָתוֹ בַּתּוֹרָה וְלֹא חִיֵּב עָלָיו כָּרֵת הֵן הַנִּקְרָאִים אִסּוּרֵי לָאוִין. וְעוֹד נִקְרָאִין אִסּוּרֵי קְדֻשָּׁה. וְתִשְׁעָה הֵן וְאֵלּוּ הֵן. אַלְמָנָה לְכֹהֵן גָּדוֹל. גְּרוּשָׁה אוֹ זוֹנָה אוֹ חֲלָלָה בֵּין לְכֹהֵן גָּדוֹל בֵּין לְכֹהֵן הֶדְיוֹט. וּמַמְזֶרֶת לְבֶן יִשְׂרָאֵל. וּבַת יִשְׂרָאֵל לְמַמְזֵר. וּבַת יִשְׂרָאֵל לְעַמּוֹנִי וּמוֹאָבִי. וּבַת יִשְׂרָאֵל לִפְצוּעַ דַּכָּא. וּכְרוּת שָׁפְכָה. וּגְרוּשָׁתוֹ אַחַר שֶׁנִּשֵּׂאת לְאַחֵר. וִיבָמָה שֶׁנִּשֵּׂאת לְזָר וַעֲדַיִן רְשׁוּת הַיָּבָם עָלֶיהָ. הַחֲלוּצָה הֲרֵי הִיא כִּגְרוּשָׁה וְהִיא אֲסוּרָה לְכֹהֵן מִדִּבְרֵי סוֹפְרִים. וְהַנְּתִינִים הֲרֵי הֵם כְּמַמְזֵרִים אֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת וְאִסּוּרָם מִדִּבְרֵי סוֹפְרִים. וּבְהִלְכוֹת אִסּוּרֵי בִּיאָה יִתְבָּאֵר לְךָ מַה הֵם הַנְּתִינִים:","וְיֵשׁ שֶׁאִסּוּר בִּיאָתָן בַּעֲשֵׂה וְאֵינוֹ מֵחַיָּבֵי לָאוִין וּשְׁלֹשָׁה הֵם. מִצְרִי וֶאֱדוֹמִי דּוֹר רִאשׁוֹן וְדוֹר שֵׁנִי אֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת. וּבְעוּלָה לְכֹהֵן גָּדוֹל. לְפִי שֶׁלֹּא נֶאֱמַר בְּאֵלּוּ לֹא יָבוֹא אוֹ לֹא יִקַּח אֶלָּא מִכְּלַל שֶׁנֶּאֱמַר (דברים כג ט) \"דּוֹר שְׁלִישִׁי יָבֹא לָהֶם בִּקְהַל ה'\" אַתָּה לָמֵד שֶׁדּוֹר רִאשׁוֹן וְשֵׁנִי לֹא יָבוֹא. וּמִכְּלַל שֶׁנֶּאֱמַר (ויקרא כא יג) \"וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח\" אַתָּה לָמֵד שֶׁאֵינָהּ בְּתוּלָה לֹא יִקַּח. וְלָאו הַבָּא מִכְּלַל עֲשֵׂה הֲרֵי הוּא כַּעֲשֵׂה:"],"Mishneh Torah, Marriage 20":["צִוּוּ חֲכָמִים שֶׁיִּתֵּן אָדָם מִנְּכָסָיו מְעַט לְבִתּוֹ כְּדֵי שֶׁתִּנָּשֵׂא בּוֹ וְזֶה הוּא הַנִּקְרָא פַּרְנָסָה. הַמַּשִּׂיא אֶת בִּתּוֹ סְתָם לֹא יִפְחֹת לָהּ מִכְּסוּת שֶׁפּוֹסְקִין לְאֵשֶׁת עָנִי שֶׁבְּיִשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הָאָב עָנִי אֲבָל אִם הָיָה עָשִׁיר הֲרֵי זֶה רָאוּי לִתֵּן לָהּ כְּפִי עָשְׁרוֹ:","פֵּירֵשׁ עַל הַבַּעַל שֶׁאֵין לָהּ כְּלוּם וְשֶׁיַּכְנִיסֶנָּה עֲרֻמָּה אֵין לָהּ כְּלוּם. וְלֹא יֹאמַר הַבַּעַל כְּשֶׁתָּבוֹא לְבֵיתִי אֲכַסֶּנָּה אֶלָּא מְכַסֶּנָּה וְהִיא בְּבֵית אָבִיהָ:","הָאָב שֶׁמֵּת וְהִנִּיחַ בַּת אוֹמְדִין דַּעְתּוֹ כַּמָּה הָיָה בְּלִבּוֹ לִתֵּן לָהּ לְפַרְנָסָה וְנוֹתְנִין לָהּ. וּמִנַּיִן יוֹדְעִין אֻמְדַּן דַּעְתּוֹ. מֵרֵעָיו וּמְיֻדָּעָיו וּמַשָּׂאוֹ וּמַתָּנוֹ וּכְבוֹדוֹ. וְכֵן אִם הִשִּׂיא בַּת בְּחַיָּיו אוֹמְדִין בָּהּ. וְאִם לֹא יָדְעוּ לוֹ בֵּית דִּין אֻמְדַּן דַּעַת נוֹתְנִין לָהּ מִנְּכָסָיו עִשּׂוּר לְפַרְנָסָתָהּ:","הִנִּיחַ בָּנוֹת רַבּוֹת כָּל שֶׁתָּבוֹא לְהִנָּשֵׂא נוֹתְנִין לָהּ עִשּׂוּר הַנְּכָסִים. וְשֶׁלְּאַחֲרֶיהָ עִשּׂוּר מַה שֶׁשִּׁיְּרָה רִאשׁוֹנָה. וְשֶׁל אַחֲרֶיהָ עִשּׂוּר מַה שֶׁשִּׁיְּרָה שְׁנִיָּה. וְאִם בָּאוּ כֻּלָּן לְהִנָּשֵׂא כְּאַחַת רִאשׁוֹנָה נוֹטֶלֶת עִשּׂוּר. וְהַשְּׁנִיָּה עִשּׂוּר מַה שֶּׁשִּׁיְּרָה רִאשׁוֹנָה. וְהַשְּׁלִישִׁית עִשּׂוּר מַה שֶּׁשִּׁיְּרָה שְׁנִיָּה וְכֵן אֲפִלּוּ הֵן עֶשֶׂר וְחוֹזְרוֹת וְחוֹלְקוֹת כָּל הָעִשּׂוּרִים בְּשָׁוֶה. וּשְׁאָר הַנְּכָסִים לַאַחִים:","עִשּׂוּר זֶה שֶׁהוּא לְפַרְנָסָה אֵינוֹ מִתְּנָאֵי כְּתֻבָּה לְפִיכָךְ אֲפִלּוּ לְפִי תַּקָּנַת חֲכָמִים (הָרִאשׁוֹנִים) וְאַחֲרוֹנִים אֵינָהּ נוֹטֶלֶת אֶלָּא מִן הַקַּרְקַע וְיֵשׁ לָהּ לִגְבּוֹת עִשּׂוּר זֶה מִשְּׂכִירוּת הַקַּרְקַע וְאִם רָצוּ הָאַחִין לִתֵּן לָהּ מָעוֹת כְּנֶגֶד עִשּׂוּר הַקַּרְקַע נוֹתְנִין:","הַבַּת בְּעִשּׂוּר זֶה כְּבַעֲלַת חוֹב שֶׁל אַחִין הִיא לְפִיכָךְ נוֹטֶלֶת אוֹתוֹ מִן הַבֵּינוֹנִית בְּלֹא שְׁבוּעָה. וְאִם מֵתוּ הָאַחִין נוֹטֶלֶת אוֹתוֹ מִן בְּנֵיהֶם מִזִּבּוּרִית וּבִשְׁבוּעָה שֶׁהֲרֵי הִיא נִפְרַעַת מִנִּכְסֵי יְתוֹמִים וְהַבָּא לִפָּרַע מִנִּכְסֵי יְתוֹמִים לֹא יִפָּרַע אֶלָּא מִזִּבּוּרִית וּבִשְׁבוּעָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת הַלְוָאָה:","וְהָאַחִים שֶׁמָּכְרוּ אוֹ מִשְׁכְּנוּ קַרְקַע אֲבִיהֶם הַבַּת טוֹרֶפֶת מִן הַלָּקוֹחוֹת פַּרְנָסָתָהּ כְּדֶרֶךְ שֶׁטּוֹרְפִים כָּל בַּעֲלֵי חוֹבוֹת מִן הַלָּקוֹחוֹת כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת הַלְוָאָה:","מִי שֶׁהִשִּׂיא בָּנוֹת גְּדוֹלוֹת וְנִשְׁאֲרוּ קְטַנּוֹת וּמֵת בְּלֹא בֵּן אֵין נוֹטְלִין פַּרְנָסָה לִקְטַנּוֹת וְאַחַר כָּךְ חוֹלְקוֹת הַנְּכָסִים אֶלָּא חוֹלְקוֹת כֻּלָּן בְּשָׁוֶה:","מִי שֶׁמֵּת וְהִנִּיחַ שְׁתֵּי בָּנוֹת וּבֵן וְקָדְמָה רִאשׁוֹנָה וְנָטְלָה עִשּׂוּר נְכָסִים וְלֹא הִסְפִּיקָה הַשְּׁנִיָּה לִגְבּוֹת עַד שֶׁמֵּת הַבֵּן וְנָפְלוּ כָּל הַנְּכָסִים לִשְׁתֵּיהֶן אֵין הַשְּׁנִיָּה נוֹטֶלֶת עִשּׂוּר אֶלָּא חוֹלְקוֹת בְּשָׁוֶה וְזָכְתָה הָרִאשׁוֹנָה בְּעִשּׂוּר שֶׁלָּהּ:","מִי שֶׁצִּוָּה בִּשְׁעַת מִיתָה אַל תְּפַרְנְסוּ בְּנוֹתַי מִנְּכָסַי שׁוֹמְעִים לוֹ שֶׁאֵין זֶה מִתְּנָאֵי כְּתֻבָּה:","מִי שֶׁמֵּת וְהִנִּיחַ אַלְמָנָה וּבַת כְּבָר בֵּאַרְנוּ שֶׁמְּזוֹנוֹת הָאַלְמָנָה קוֹדְמִין לִמְזוֹנוֹת הַבַּת. וְכֵן אִם נִשֵּׂאת הַבַּת אֵינָהּ נוֹטֶלֶת עִשּׂוּר נְכָסִים מִפְּנֵי מְזוֹנוֹת הָאַלְמָנָה. וַאֲפִלּוּ מֵתָה הַבַּת אַחַר שֶׁנִּשֵּׂאת אֵין הַבַּעַל יוֹרֵשׁ פַּרְנָסָה הָרְאוּיָה לְהִנָּתֵן לָהּ שֶׁהֲרֵי הַנְּכָסִים כֻּלָּן בְּחֶזְקַת הָאַלְמָנָה שֶׁתְּהֵא נִזּוֹנֶת מֵהֶן:","קְטַנָּה יְתוֹמָה שֶׁהִשִּׂיאָתָהּ אִמָּהּ אוֹ אַחֶיהָ לְדַעְתָּהּ וְנָתְנוּ לָהּ מֵאָה אוֹ חֲמִשִּׁים זוּז יְכוֹלָה הִיא מִשֶּׁתַּגְדִּיל לְהוֹצִיא מִיָּדָם פַּרְנָסָה הָרְאוּיָה לָהּ. אוֹ בְּאֻמְדַּן דַּעַת הָאָב אוֹ בְּעִשּׂוּר הַקַּרְקָעוֹת. וַאֲפִלּוּ לֹא הָיוּ הָאַחִין זָנִין אוֹתָהּ. וְאַף עַל פִּי שֶׁלֹּא מָחֲתָה בִּשְׁעַת נִשּׂוּאִין מִפְּנֵי שֶׁהַקְּטַנָּה אֵינָהּ בַּת מְחָאָה:","נִשֵּׂאת הַבַּת אַחַר שֶׁגָּדְלָה בֵּין נַעֲרָה בֵּין בּוֹגֶרֶת וְלֹא תָּבְעָה פַּרְנָסָתָהּ אִבְּדָה פַּרְנָסָתָהּ. וְאִם מִחֲתָה בְּעֵת נִשּׂוּאֶיהָ הֲרֵי זוֹ מוֹצִיאָה אֶת הָרָאוּי לָהּ כָּל זְמַן שֶׁתִּרְצֶה. בָּגְרָה וְעוֹדָהּ בְּבֵית אָבִיהָ בֵּין שֶׁבָּגְרָה אַחַר מוֹתוֹ בֵּין שֶׁהִנִּיחָהּ בּוֹגֶרֶת אִם פָּסְקוּ הָאַחִין מִלָּתֵת מְזוֹנוֹתֶיהָ שֶׁהֲרֵי אֵין לָהּ מְזוֹנוֹת כְּמוֹ שֶׁבֵּאַרְנוּ וְשָׁתְקָה וְלֹא תָּבְעָה פַּרְנָסָתָהּ אִבְּדָה פַּרְנָסָתָהּ. וְאִם מִחֲתָה לֹא אִבְּדָה פַּרְנָסָתָהּ. לֹא פָּסְקוּ הָאַחִים מְזוֹנוֹתֶיהָ וְזָנוּ אוֹתָהּ בְּבֶגֶר אַף עַל פִּי שֶׁלֹּא מִחֲתָה לֹא אִבְּדָה פַּרְנָסָתָהּ כָּל זְמַן שֶׁהֵן זָנִין אוֹתָהּ. שֶׁיֵּשׁ לָהּ לִטְעֹן מִפְּנֵי שֶׁהֵן זָנִין אוֹתָהּ אַף עַל פִּי שֶׁאֵינָן חַיָּבִין וְהִיא עֲדַיִן לֹא נִשֵּׂאת מִפְּנֵי זֶה לֹא תָּבְעָה פַּרְנָסָתָהּ:","מִי שֶׁצִּוָּה לָתֵת לְבִתּוֹ כָּךְ וְכָךְ מָעוֹת לְפַרְנָסָתָהּ לִקַּח בָּהֶן קַרְקַע בֵּין שֶׁהָיָה שְׁכִיב מֵרַע בֵּין שֶׁהָיָה בָּרִיא וּמֵת וַהֲרֵי הַמָּעוֹת בְּיַד הַשָּׁלִישׁ וְאָמְרָה הַבַּת תְּנוּ אוֹתָם לְבַעְלִי כָּל מַה שֶּׁיִּרְצֶה יַעֲשֶׂה בָּהֶן. אִם הָיְתָה גְּדוֹלָה וְנִשֵּׂאת הָרְשׁוּת בְּיָדָהּ. וְאִם עֲדַיִן מְאֹרֶסֶת הִיא יַעֲשֶׂה שָׁלִישׁ מַה שֶּׁהֻשְׁלַשׁ בְּיָדוֹ. וְאִם עֲדַיִן קְטַנָּה הִיא אֲפִלּוּ נִשֵּׂאת אֵין שׁוֹמְעִין לָהּ אֶלָּא יַעֲשֶׂה הַשָּׁלִישׁ כְּמוֹ שֶׁצִּוָּה הָאָב:"],"Mishneh Torah, Marriage 9":["הַמְ [קַ] דֵשׁ שְׁתֵּי נָשִׁים שֶׁאָסוּר לִשָּׂא שְׁתֵּיהֶן מִשּׁוּם עֶרְוָה כְּאַחַת אֵינָן מְקֻדָּשׁוֹת. כֵּיצַד. כְּגוֹן שֶׁקִּדֵּשׁ אִשָּׁה וּבִתָּהּ אוֹ שְׁתֵּי אֲחָיוֹת כְּאַחַת אֵין אַחַת מֵהֶן מְקֻדֶּשֶׁת:","קִדֵּשׁ נָשִׁים רַבּוֹת כְּאַחַת וְאָמַר הֲרֵי כֻּלְּכֶם מְקֻדָּשׁוֹת לִי וְהָיוּ בָּהֶן שְׁתֵּי אֲחָיוֹת אוֹ אִשָּׁה וּבִתָּהּ וְכַיּוֹצֵא בָּהֶן אֵין אַחַת מִכֻּלָּן מְקֻדֶּשֶׁת. וְאִם אָמַר לָהֶן הָרְאוּיָה מִכֶּם לִי לְבִיאָה מְקֻדֶּשֶׁת לִי הֲרֵי כֻּלָּן מְקֻדָּשׁוֹת לוֹ חוּץ מֵאֲחָיוֹת אוֹ אִשָּׁה וּבִתָּהּ וְכַיּוֹצֵא בָּהֶן. וְכֵן אִם אָמַר לָהֶן הֲרֵי כֻּלְּכֶם מְקֻדָּשׁוֹת לִי וְהָיְתָה בָּהֶן שִׁפְחָה אוֹ עַכּוּ\"ם אוֹ אִשָּׁה אַחַת עֶרְוָה כְּגוֹן אֵשֶׁת אִישׁ אוֹ בִּתּוֹ אוֹ אֲחוֹתוֹ וְכַיּוֹצֵא בָּהֶן אֵין אַחַת מִכֻּלָּם מְקֻדֶּשֶׁת. וְאִם אָמַר הָרְאוּיָה מִכֶּם לִי לְבִיאָה תִּהְיֶה מְקֻדֶּשֶׁת לִי הֲרֵי כֻּלָּן מְקֻדָּשׁוֹת לוֹ חוּץ מֵאוֹתָהּ אִשָּׁה שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ:","אָמַר לִשְׁתֵּי אֲחָיוֹת הֲרֵי אַחַת מִכֶּם מְקֻדֶּשֶׁת לִי בָּזֶה וְנָתַן לָהֶן פְּרוּטָה אוֹ שֶׁקִּבַּלְתָּהּ אַחַת עַל יַד חֲבֶרְתָּהּ. וְכֵן הָאוֹמֵר לָאָב אַחַת מִבְּנוֹתֶיךָ מְקֻדֶּשֶׁת לִי וְקִבֵּל הָאָב קִדּוּשֶׁיהָ כֻּלָּן צְרִיכוֹת גֵּט מִמֶּנּוּ. וְאָסוּר לוֹ לָבוֹא עַל אַחַת מֵהֶן מִפְּנֵי שֶׁהַקִּדּוּשִׁין תּוֹפְסִין בָּהֶן אַף עַל פִּי שֶׁאִי אֶפְשָׁר לָבוֹא עַל אַחַת מֵהֶן:","הָעוֹשֶׂה שָׁלִיחַ לְקַדֵּשׁ לוֹ אִשָּׁה פְּלוֹנִית וְהָלַךְ וְקִדְּשָׁהּ לוֹ וְקִדֵּשׁ הַמְשַׁלֵּחַ בְּעַצְמוֹ לְאִמָּהּ אוֹ לְבִתָּהּ אוֹ לַאֲחוֹתָהּ וְאֵין יָדוּעַ אֵי זוֹ מֵהֶן נִתְקַדְּשָׁה רִאשׁוֹנָה שְׁתֵּיהֶן צְרִיכוֹת גֵּט וַאֲסוּרוֹת עָלָיו. וְכֵן אִשָּׁה שֶׁעָשְׂתָה שָׁלִיחַ לְקַדְּשָׁהּ וְהָלַךְ וְקִדְּשָׁהּ וְהָלְכָה וְקִדְּשָׁה הִיא עַצְמָהּ לְאַחֵר וְאֵין יָדוּעַ אֵי זוֹ מֵהֶן קֹדֶם שְׁנֵיהֶן נוֹתְנִין לָהּ גֵּט. וְאִם רָצוּ אֶחָד נוֹתֵן גֵּט וְאֶחָד כּוֹנֵס:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּרְחוֹקִין אֲבָל (בִּקְרוֹבִים) אִם קִדְּשָׁהּ הַשָּׁלִיחַ לָאָב וְקִדְּשָׁה הִיא עַצְמָהּ לַבֵּן אוֹ לָאָח וְכַיּוֹצֵא בָּהֶן שְׁנֵיהֶם נוֹתְנִין גֵּט וְהִיא אֲסוּרָה לִשְׁנֵיהֶם:","הָאוֹמֵר לִשְׁלוּחוֹ צֵא וְקַדֵּשׁ לִי אִשָּׁה וּמֵת הַשָּׁלִיחַ וְאֵינוֹ יוֹדֵעַ אִם קִדֵּשׁ אִם לֹא קִדֵּשׁ לוֹ אִשָּׁה הֲרֵי זֶה בְּחֶזְקַת שֶׁקִּדֵּשׁ שֶׁחֶזְקַת שָׁלִיחַ לַעֲשׂוֹת שְׁלִיחוּתוֹ. וְהוֹאִיל וְאֵין יָדוּעַ אֵי זוֹ אִשָּׁה קִדֵּשׁ לוֹ הֲרֵי זֶה אָסוּר בְּכָל אִשָּׁה שֶׁיֵּשׁ לָהּ קְרוֹבוֹת שֶׁהֵן עֶרְוָה עִמָּהּ. כְּגוֹן אִשָּׁה שֶׁיֵּשׁ לָהּ בַּת אוֹ אֵם אוֹ אָחוֹת וְכַיּוֹצֵא בָּהֶן. שֶׁאִם תֹּאמַר יִשָּׂא זוֹ שֶׁמָּא אִמָּהּ קִדֵּשׁ לוֹ שְׁלוּחוֹ אוֹ אֲחוֹתָהּ אוֹ בִּתָּהּ. וּמֻתָּר בְּאִשָּׁה שֶׁאֵין לָהּ קְרוֹבוֹת כְּגוֹן אֵלּוּ. הָיְתָה לָהּ קְרוֹבָה כְּגוֹן אֵם אוֹ אָחוֹת וְכַיּוֹצֵא בָּהֶן וְהָיְתָה הַקְּרוֹבָה אֵשֶׁת אִישׁ בְּשָׁעָה שֶׁעָשָׂה הוּא שָׁלִיחַ אַף עַל פִּי שֶׁנִּתְגָּרְשָׁה קֹדֶם שֶׁיָּמוּת הַשָּׁלִיחַ הֲרֵי זֶה מֻתָּר בָּהּ. וְאֵין אוֹמְרִים שֶׁמָּא קִדֵּשׁ הַשָּׁלִיחַ אַתְּ קְרוֹבָתָהּ אַחַר שֶׁנִּתְגָּרְשָׁה. מִפְּנֵי שֶׁלֹּא הָיְתָה רְאוּיָה בְּשָׁעָה שֶׁעָשָׂה הַשָּׁלִיחַ וְאֵין אָדָם עוֹשֶׂה שָׁלִיחַ לְקַדֵּשׁ לוֹ אֶלָּא אִשָּׁה שֶׁיָּכוֹל הוּא לְקַדְּשָׁהּ בִּשְׁעַת הַשְּׁלִיחוּת:","מִי שֶׁהָיוּ לוֹ חֲמִשָּׁה בָּנִים וְעָשׂוּ כֻּלָּן שָׁלִיחַ אֶת אֲבִיהֶם לְקַדֵּשׁ לָהֶם אִשָּׁה. וְאָמַר אֲבִי הַבָּנִים לְאִישׁ שֶׁיֵּשׁ לוֹ חָמֵשׁ בָּנוֹת אַחַת מִבְּנוֹתֶיךָ מְקֻדֶּשֶׁת לְאֶחָד מִבָּנַי וְקִבֵּל הָאָב הַקִּדּוּשִׁין. כָּל אַחַת מֵהֶן צְרִיכָה חֲמִשָּׁה גִּטִּין מִכָּל הָאַחִין. הוֹאִיל וְכֻלָּן נָתְנוּ רְשׁוּת לָאָב לְקַדֵּשׁ לָהֶן אִשָּׁה. מֵת אֶחָד מֵהֶם כָּל אַחַת מֵהֶן צְרִיכָה אַרְבָּעָה גִּטִּין וַחֲלִיצָה מֵאֶחָד מֵהֶם:","הָאָב שֶׁהָיְתָה לוֹ בַּת קְטַנָּה אוֹ נַעֲרָה שֶׁהִיא בִּרְשׁוּתוֹ וּבַת בּוֹגֶרֶת וְנָתְנָה לוֹ הַבּוֹגֶרֶת רְשׁוּת לְקַדְּשָׁהּ וְקִדֵּשׁ בִּתּוֹ סְתָם לְאֶחָד. אֵין הַבּוֹגֶרֶת בִּכְלָל עַד שֶׁיְּפָרֵשׁ וְיֹאמַר בִּתִּי הַבּוֹגֶרֶת שֶׁעָשָׂת אוֹתִי שָׁלִיחַ. לְפִיכָךְ אֵין הַבּוֹגֶרֶת מְקֻדֶּשֶׁת (וַאֲחוֹתָהּ מְקֻדֶּשֶׁת):","מִי שֶׁיֵּשׁ לוֹ שְׁתֵּי כִּתֵּי בָּנוֹת מִשְּׁתֵּי נָשִׁים וְכֻלָּן בִּרְשׁוּתוֹ וְקִדֵּשׁ אַחַת מֵהֶן וּבִשְׁעַת הַקִּדּוּשִׁין אָמַר לַבַּעַל קִדַּשְׁתִּי לְךָ אֶת בִּתִּי הַגְּדוֹלָה. אַף עַל פִּי שֶׁיֵּשׁ לוֹמַר שֶׁמָּא גְּדוֹלָה שֶׁבַּגְּדוֹלוֹת קִדֵּשׁ לוֹ אוֹ גְּדוֹלָה שֶׁבַּקְּטַנּוֹת אוֹ קְטַנָּה שֶׁבַּגְּדוֹלוֹת שֶׁהִיא גְּדוֹלָה מִן הַגְּדוֹלָה שֶׁבַּקְּטַנּוֹת. הֲרֵי כֻּלָּן מֻתָּרוֹת חוּץ מִן הַגְּדוֹלָה שֶׁבַּגְּדוֹלוֹת שֶׁהִיא לְבַדָּהּ הַמְקֻדֶּשֶׁת. וְכֵן אִם קִדֵּשׁ בִּתּוֹ הַקְּטַנָּה אַף עַל פִּי שֶׁיֵּשׁ לוֹמַר שֶׁמָּא קְטַנָּה שֶׁבַּקְּטַנּוֹת אוֹ קְטַנָּה שֶׁבַּגְּדוֹלוֹת אוֹ גְּדוֹלָה שֶׁבַּקְּטַנּוֹת שֶׁהִיא קְטַנָּה מִן הַקְּטַנָּה שֶׁבַּגְּדוֹלוֹת הֲרֵי כֻּלָּן מֻתָּרוֹת חוּץ מִן הַקְּטַנָּה שֶׁבַּקְּטַנּוֹת וְהִיא לְבַדָּהּ הַמְקֻדֶּשֶׁת. שֶׁמַּשְׁמָע בִּתּוֹ הַגְּדוֹלָה שֶׁאֵין בִּבְנוֹתָיו גְּדוֹלָה מִמֶּנָּה וּמַשְׁמָע בִּתּוֹ הַקְּטַנָּה שֶׁאֵין בָּהֶן קְטַנָּה מִמֶּנָּה:","נֶאֱמָן הָאָב לוֹמַר עַל בִּתּוֹ קֹדֶם שֶׁתִּבְגֹּר שֶׁהִיא מְקֻדֶּשֶׁת וְאוֹסְרָהּ עַל הַכּל:","הָאָב שֶׁאָמַר קִדַּשְׁתִּי אֶת בִּתִּי וְאֵינִי יוֹדֵעַ לְמִי קִדַּשְׁתִּיהָ הֲרֵי זוֹ אֲסוּרָה לְעוֹלָם עַל כָּל אָדָם עַד שֶׁיֹּאמַר הָאָב נוֹדַע לִי שֶׁלִּפְלוֹנִי קִדַּשְׁתִּיהָ וְתִהְיֶה צְרִיכָה מִמֶּנּוּ גֵּט בִּלְבַד. וְאַף עַל פִּי שֶׁנּוֹדַע לוֹ אַחַר שֶׁבָּגְרָה:","אָמַר הָאָב אֵינִי יוֹדֵעַ לְמִי קִדַּשְׁתִּיהָ וּבָא אֶחָד וְאָמַר אֲנִי הוּא שֶׁקִּדַּשְׁתִּיהָ נֶאֱמָן אַף לִכְנֹס וְאֵינוֹ צָרִיךְ קִדּוּשִׁין אֲחֵרִים:","בָּאוּ שְׁנַיִם זֶה אוֹמֵר אֲנִי קִדַּשְׁתִּיהָ וְזֶה אוֹמֵר אֲנִי קִדַּשְׁתִּיהָ. שְׁנֵיהֶן נוֹתְנִין גֵּט וְאִם רָצוּ אֶחָד נוֹתֵן גֵּט וְאֶחָד כּוֹנֵס. כְּנָסָהּ וְאַחַר כָּךְ בָּא אַחֵר וְאָמַר אֲנִי הוּא שֶׁקִּדַּשְׁתִּיהָ אֵינוֹ נֶאֱמָן וְאֵינוֹ אוֹסְרָהּ עַל בַּעְלָהּ:","הָאִשָּׁה שֶׁאָמְרָה נִתְקַדַּשְׁתִּי וְאֵינִי יוֹדַעַת לְמִי נִתְקַדַּשְׁתִּי וּבָא אֶחָד וְאָמַר אֲנִי הוּא שֶׁקִּדַּשְׁתִּיךְ נֶאֱמָן לִתֵּן גֵּט וְתִהְיֶה מֻתֶּרֶת לְכָל אָדָם חוּץ מִמֶּנּוּ. אֲבָל אֵינוֹ נֶאֱמָן לִכְנֹס שֶׁמָּא יִצְרוֹ תּוֹקְפוֹ וְהִיא תַּרְגִּיל לוֹ כְּדֵי לְהַתִּירָהּ:","הָאוֹמֵר לְאִשָּׁה קִדַּשְׁתִּיךְ וְהִיא אוֹמֶרֶת לֹא קִדַּשְׁתַּנִי הוּא אָסוּר בִּקְרוֹבוֹתֶיהָ וְהִיא מֻתֶּרֶת בִּקְרוֹבָיו. קִדַּשְׁתַּנִי וְהוּא אוֹמֵר לֹא קִדַּשְׁתִּיךְ הוּא מֻתָּר בִּקְרוֹבוֹתֶיהָ וְהִיא אֲסוּרָה בִּקְרוֹבָיו. קִדַּשְׁתִּיךְ וְהִיא אוֹמֶרֶת לֹא קִדַּשְׁתָּ אֶלָּא בִּתִּי הוּא אָסוּר בִּקְרוֹבוֹת גְּדוֹלָה וּגְדוֹלָה מֻתֶּרֶת בִּקְרוֹבָיו. וּמֻתָּר בִּקְרוֹבוֹת הַבַּת וְהַבַּת מֻתֶּרֶת בִּקְרוֹבָיו. קִדַּשְׁתִּי אֶת בִּתֵּךְ וְהִיא אוֹמֶרֶת לֹא קִדַּשְׁתָּ אֶלָּא אוֹתִי הוּא אָסוּר בִּקְרוֹבוֹת הַבַּת וְהַבַּת מֻתֶּרֶת בִּקְרוֹבָיו. וּמֻתָּר בִּקְרוֹבוֹת הָאֵם וְהָאֵם אֲסוּרָה עַל קְרוֹבָיו:","וְכָל אֵלּוּ שֶׁטּוֹעֲנִין הַקִּדּוּשִׁין בְּשֶׁטָּעַן הַטּוֹעֵן שֶׁהָיוּ שָׁם קִדּוּשִׁין בִּפְנֵי עֵדִים וְהָלְכוּ לִמְדִינָה אַחֶרֶת אוֹ מֵתוּ. אֲבָל אִם הוֹדוּ שֶׁהָיוּ הַקִּדּוּשִׁין בְּלֹא עֵדִים אֵין כָּאן קִדּוּשִׁין כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל מָקוֹם שֶׁתֹּאמַר אִשָּׁה לְאִישׁ קִדַּשְׁתַּנִי וְהוּא אוֹמֵר לֹא קִדַּשְׁתִּיךְ מְבַקְּשִׁים מִמֶּנּוּ שֶׁיִּכְתֹּב לָהּ גֵּט לְהַתִּירָהּ לִשְׁאָר הָעָם שֶׁאֵין לוֹ בָּזֶה הֶפְסֵד. וְאִם נָתַן לָהּ גֵּט מֵעַצְמוֹ כּוֹפִין אוֹתוֹ לִתֵּן כְּתֻבָּה:","הָעוֹשֶׂה שָׁלִיחַ לְקַדֵּשׁ לוֹ אִשָּׁה וְהָלַךְ וְקִדְּשָׁהּ לְעַצְמוֹ הֲרֵי זוֹ מְקֻדֶּשֶׁת לַשָּׁלִיחַ. וְאָסוּר לַעֲשׂוֹת כֵּן. וְכָל הָעוֹשֶׂה דָּבָר זֶה וְכַיּוֹצֵא בּוֹ בִּשְׁאָר דִּבְרֵי מִקָּח וּמִמְכָּר נִקְרָא רָשָׁע:","הָעוֹשֶׂה שָׁלִיחַ לְקַדֵּשׁ לוֹ אִשָּׁה וְהָלַךְ וְקִדְּשָׁהּ הַשָּׁלִיחַ אוֹמֵר לְעַצְמִי קִדַּשְׁתִּיהָ וְהָאִשָּׁה אוֹמֶרֶת לָרִאשׁוֹן שֶׁשְּׁלָחוֹ נִתְקַדַּשְׁתִּי. אִם לֹא עָשָׂה הַשָּׁלִיחַ בְּעֵדִים הֲרֵי הַשָּׁלִיחַ אָסוּר בִּקְרוֹבוֹתֶיהָ וְהִיא מֻתֶּרֶת בִּקְרוֹבָיו. וְהָאִשָּׁה אֲסוּרָה בִּקְרוֹבֵי הַמְשַׁלֵּחַ וְהַמְשַׁלֵּחַ מֻתָּר בִּקְרוֹבוֹתֶיהָ. וְאִם הֻחְזַק הַשָּׁלִיחַ בְּעֵדִים הֲרֵי זוֹ מְקֻדֶּשֶׁת לָרִאשׁוֹן:","אָמְרָה אֵינִי יוֹדַעַת לְמִי נִתְקַדַּשְׁתִּי אִם לַשּׁוֹלֵחַ אוֹ לִשְׁלוּחוֹ. אִם לֹא הֻחְזַק הַשָּׁלִיחַ בְּעֵדִים הֲרֵי זוֹ מְקֻדֶּשֶׁת לַשֵּׁנִי. וְאִם הֻחְזַק שֶׁהוּא שְׁלוּחוֹ שְׁנֵיהֶן נוֹתְנִין גֵּט. וְאִם רָצוּ אֶחָד נוֹתֵן גֵּט וְאֶחָד כּוֹנֵס:","הָאִשָּׁה שֶׁעָשְׂתָה שָׁלִיחַ לְקַדְּשָׁהּ וְהָלַךְ וְקִדְּשָׁהּ וּבְעֵת הֲלִיכָתוֹ בִּטְּלָה הַשְּׁלִיחוּת וְחָזְרָה בָּהּ וְאֵין יָדוּעַ אִם קֹדֶם שֶׁקִּבֵּל לָהּ הַקִּדּוּשִׁין חָזְרָה אוֹ אַחַר הַקִּדּוּשִׁין הֲרֵי זוֹ מְקֻדֶּשֶׁת מִסָּפֵק. וְכֵן הָאִישׁ שֶׁעָשָׂה שָׁלִיחַ וְחָזַר בּוֹ:","הַמְקַדֵּשׁ אַחַת מֵחָמֵשׁ נָשִׁים וְאֵינוֹ יוֹדֵעַ אֵי זוֹ מֵהֶן קִדֵּשׁ וְכָל אַחַת וְאַחַת אוֹמֶרֶת אוֹתִי קִדֵּשׁ אָסוּר בִּקְרוֹבוֹת כֻּלָּן. וְנוֹתֵן גֵּט לְכָל אַחַת וְאַחַת וּמַנִּיחַ כְּתֻבָּה אַחַת בֵּינֵיהֶן וּמִסְתַּלֵּק. וְאִם קִדֵּשׁ בְּבִיאָה קָנְסוּ אוֹתוֹ חֲכָמִים שֶׁיִּתֵּן כְּתֻבָּה לְכָל אַחַת וְאַחַת. וְהַדָּבָר יָדוּעַ שֶׁהַכְּתֻבָּה שֶׁכָּתַב לְאַחַת מֵהֶן אָבְדָה וְכָל אַחַת וְאַחַת אוֹמֶרֶת אֲנִי הִיא שֶׁקִּדַּשְׁתַּנִי וְכָתַבְתָּ לִי כְּתֻבָּה וְאָבְדָה כְּתֻבָּתִי:","הָאִשָּׁה שֶׁיָּצָא עָלֶיהָ קוֹל שֶׁהִיא מְקֻדֶּשֶׁת לִפְלוֹנִי הֲרֵי זוֹ בְּחֶזְקַת מְקֻדֶּשֶׁת אַף עַל פִּי שֶׁאֵין שָׁם רְאָיָה בְּרוּרָה. וְכָל קוֹל שֶׁלֹּא הֻחְזַק בְּבֵית דִּין אֵין חוֹשְׁשִׁין לוֹ. וְכֵיצַד הוּא הַקּוֹל שֶׁתֻּחְזַק זוֹ בּוֹ שֶׁהִיא מְקֻדֶּשֶׁת. כְּגוֹן שֶׁבָּאוּ שְׁנַיִם וְהֵעִידוּ שֶׁרָאוּ הַנֵּרוֹת דּוֹלְקוֹת וּמִטּוֹת מוּצָעוֹת וּבְנֵי אָדָם נִכְנָסִין וְיוֹצְאִין וְנָשִׁים שְׂמֵחוֹת לָהּ וְאוֹמְרוֹת נִתְקַדְּשָׁה פְּלוֹנִית הַיּוֹם. שָׁמְעוּ אוֹתָן אוֹמְרוֹת פְּלוֹנִית תִּתְקַדֵּשׁ הַיּוֹם אֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא נִזְדַּמְּנוּ לְקַדֵּשׁ וְלֹא נִתְקַדְּשָׁה עַד שֶׁיִּשְׁמְעוּ שֶׁנִּתְקַדְּשָׁה. וְכֵן אִם בָּאוּ שְׁנַיִם וְאָמְרוּ רָאִינוּ כְּמוֹ שִׂמְחַת אֵרוּסִין וְשָׁמַעְנוּ קוֹל הֲבָרָה וְשָׁמַעְנוּ מִפְּלוֹנִי שֶׁשָּׁמַע מִפְּלוֹנִי שֶׁנִּתְקַדְּשָׁה פְּלוֹנִית בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וְהָלְכוּ לָהֶם הָעֵדִים לִמְדִינָה אַחֶרֶת אוֹ מֵתוּ הֲרֵי זֶה קוֹל שֶׁמַּחֲזִיק אוֹתָהּ מְקֻדֶּשֶׁת:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הָיְתָה שָׁם אֲמַתְלָא אֲבָל אִם הָיְתָה שָׁם אֲמַתְלָא וְשָׁמְעוּ הָאֲמַתְלָא כְּשֶׁשָּׁמְעוּ שֶׁנִּתְקַדְּשָׁה לֹא הֻחְזְקָה מְקֻדֶּשֶׁת. כֵּיצַד הִיא הָאֲמַתְלָא. פְּלוֹנִית נִתְקַדְּשָׁה עַל תְּנַאי אוֹ קִדּוּשֵׁי סָפֵק לֹא הֻחְזְקָה. אֶלָּא שׁוֹאֲלִין אוֹתָהּ וְסוֹמְכִין עַל דְּבָרֶיהָ הוֹאִיל וְאֵין שָׁם רְאָיָה בְּרוּרָה וְלֹא קוֹל חָזָק:","יָצָא עָלֶיהָ קוֹל שֶׁנִּתְקַדְּשָׁה לִפְלוֹנִי וּלְאַחַר יָמִים אָמְרוּ אֲמַתְלָא. אִם נִרְאִין הַדְּבָרִים לְבֵית דִּין שֶׁהוּא כֵּן סוֹמְכִין עַל הָאֲמַתְלָא וְלֹא תֻּחְזַק מְקֻדֶּשֶׁת. וְאִם לָאו הוֹאִיל וְלֹא נִשְׁמְעָה הָאֲמַתְלָא בְּעֵת שֶׁנִּשְׁמְעוּ הַקִּדּוּשִׁין אֵין חוֹשְׁשִׁין לַאֲמַתְלָא:","מַעֲשֶׂה בְּאַחַת שֶׁיָּצָא עָלֶיהָ קוֹל שֶׁנִּתְקַדְּשָׁה לִבְנוֹ שֶׁל פְּלוֹנִי וּלְאַחַר זְמַן שָׁאֲלוּ לְאָבִיו וְאָמַר עַל תְּנַאי כָּךְ נִתְקַדְּשָׁה לוֹ וְלֹא נִתְקַיֵּם הַתְּנַאי וְלֹא סָמְכוּ חֲכָמִים עַל דְּבָרָיו אֶלָּא אָמְרוּ הֲרֵי זוֹ סָפֵק מְקֻדֶּשֶׁת וּכְאִלּוּ אֵין שָׁם אֲמַתְלָא:","יָצָא עָלֶיהָ קוֹל שֶׁהִיא מְקֻדֶּשֶׁת לִפְלוֹנִי וּבָא שֵׁנִי וְקִדְּשָׁהּ בְּפָנֵינוּ בּוֹדְקִין עַל קִדּוּשֵׁי רִאשׁוֹן שֶׁהֵן בְּקוֹל. אִם בָּאוּ עֵדִים בִּרְאָיָה בְּרוּרָה שֶׁהִיא מְקֻדֶּשֶׁת לָרִאשׁוֹן אֵין קִדּוּשֵׁי שֵׁנִי כְּלוּם. וְאִם לָאו מְגָרֵשׁ רִאשׁוֹן שֶׁקִּדּוּשָׁיו בְּקוֹל וְנוֹשֵׂא הַשֵּׁנִי שֶׁקִּדּוּשָׁיו וַדַּאי. וְאִם גֵּרֵשׁ הַשֵּׁנִי לֹא יִכְנֹס הָרִאשׁוֹן שֶׁמָּא יֹאמְרוּ הֶחֱזִיר גְּרוּשָׁתוֹ מִן הָאֵרוּסִין אַחַר שֶׁנִּתְאָרְסָה לְאַחֵר:","יָצָא עָלֶיהָ קוֹל שֶׁהִיא מְקֻדֶּשֶׁת לִפְלוֹנִי וְיָצָא קוֹל אַחֵר כְּמוֹתוֹ שֶׁהִיא מְקֻדֶּשֶׁת לְאַחֵר. אֶחָד כּוֹתֵב גֵּט וְאֶחָד כּוֹנֵס בֵּין רִאשׁוֹן בֵּין אַחֲרוֹן:","מָקוֹם שֶׁנָּהֲגוּ לִשְׁלֹחַ סִבְלוֹנוֹת לַאֲרוּסָה אַחַר שֶׁתִּתְאָרֵס וּבָאוּ עֵדִים שֶׁרָאוּ סִבְלוֹנוֹת שֶׁהוּבְלוּ לָהּ חוֹשְׁשִׁין לָהּ שֶׁמָּא נִתְקַדְּשָׁה וּצְרִיכָה גֵּט מִסָּפֵק אַף עַל פִּי שֶׁרֹב אַנְשֵׁי הָעִיר אֵין מְשַׁלְּחִין סִבְלוֹנוֹת אֶלָּא קֹדֶם הָאֵרוּסִין. וּמָקוֹם שֶׁנָּהֲגוּ כֻּלָּן לִשְׁלֹחַ סִבְלוֹנוֹת בַּתְּחִלָּה וְאַחַר כָּךְ מְקַדְּשִׁין וְרָאוּ סִבְלוֹנוֹת אֵין חוֹשְׁשִׁין לָהּ:","הֻחְזַק שְׁטַר כְּתֻבָּתָהּ. אִם דֶּרֶךְ מִקְצָת אַנְשֵׁי הַמָּקוֹם שֶׁמְּקַדְּשִׁין וְאַחַר כָּךְ כּוֹתְבִין חוֹשְׁשִׁין לָהּ. וְאַף עַל פִּי שֶׁאֵין שָׁם סוֹפֵר אֵין אוֹמְרִין שֶׁמָּא מִפְּנֵי הַסּוֹפֵר שֶׁמָּצָא הִקְדִּים וְכָתַב. וְאִם דֶּרֶךְ כָּל אַנְשֵׁי הַמָּקוֹם שֶׁכּוֹתְבִין הַכְּתֻבָּה קֹדֶם הַקִּדּוּשִׁין אֵין חוֹשְׁשִׁין לָהּ:","שְׁנַיִם אוֹמְרִין רְאִינוּהָ שֶׁנִּתְקַדְּשָׁה בְּיוֹם פְּלוֹנִי וּשְׁנַיִם אוֹמְרִין לֹא רְאִינוּהָ אַף עַל פִּי שֶׁכֻּלָּם שְׁכֵנִים בֶּחָצֵר אַחַת הֲרֵי זוֹ מְקֻדֶּשֶׁת שֶׁאֵין [טַעֲנַת] לֹא רְאִינוּהָ רְאָיָה שֶׁדֶּרֶךְ הָעָם לְקַדֵּשׁ בְּצִנְעָה:","אָמַר עֵד אֶחָד מְקֻדֶּשֶׁת הִיא זוֹ וְהִיא אוֹמֶרֶת לֹא נִתְקַדַּשְׁתִּי הֲרֵי זוֹ מֻתֶּרֶת. אֶחָד אוֹמֵר מְקֻדֶּשֶׁת וְאֶחָד אוֹמֵר אֵינָהּ מְקֻדֶּשֶׁת לֹא תִּנָּשֵׂא וְאִם נִשֵּׂאת לֹא תֵּצֵא שֶׁהֲרֵי הִיא אוֹמֶרֶת לֹא נִתְקַדַּשְׁתִּי. אָמְרָה מְקֻדֶּשֶׁת אֲנִי וּלְאַחַר זְמַן עָמְדָה וְקִדְּשָׁה עַצְמָהּ אִם נָתְנָה אֲמַתְלָא לִדְבָרֶיהָ וְאָמְרָה מִפְּנֵי כָּךְ וְכָךְ אָמַרְתִּי בַּתְּחִלָּה שֶׁאֲנִי מְקֻדֶּשֶׁת וְרָאִינוּ בִּדְבָרֶיהָ מַמָּשׁ הֲרֵי זוֹ מֻתֶּרֶת לַשֵּׁנִי. וְאִם לֹא נָתְנָה אֲמַתְלָא אוֹ שֶׁנָּתְנָה וְאֵין בָּהֶן מַמָּשׁ הֲרֵי זוֹ אֲסוּרָה וְקִדּוּשֵׁי שֵׁנִי קִדּוּשֵׁי סָפֵק. לְפִיכָךְ נוֹתֵן לָהּ גֵּט וְתִהְיֶה אֲסוּרָה עָלָיו וְעַל הַכּל עַד שֶׁיָּבוֹא אֲרוּסָהּ. וְכֵן הָאִשָּׁה שֶׁבָּאת וְאָמְרָה אֵשֶׁת אִישׁ אֲנִי וְחָזְרָה וְאָמְרָה פְּנוּיָה אֲנִי אִם נָתְנָה אֲמַתְלָא לִדְבָרֶיהָ וְיֵשׁ בִּדְבָרֶיהָ מַמָּשׁ הֲרֵי זוֹ נֶאֱמֶנֶת:"],"Mishneh Torah, Mourning 7":["מִי שֶׁבָּאָה לוֹ שְׁמוּעָה שֶׁמֵּת לוֹ קָרוֹב. אִם בְּתוֹךְ שְׁלֹשִׁים יוֹם הִגִּיעָה הַשְּׁמוּעָה אֲפִלּוּ יוֹם שְׁלֹשִׁים עַצְמוֹ הֲרֵי זוֹ שְׁמוּעָה קְרוֹבָה. וְחַיָּב לִנְהֹג שִׁבְעָה יְמֵי אֲבֵלוּת מִיּוֹם שֶׁהִגִּיעָה הַשְּׁמוּעָה. וְקוֹרֵעַ וּמוֹנֶה שְׁלֹשִׁים לְאִסּוּר הַתִּסְפֹּרֶת עִם שְׁאָר הַדְּבָרִים. כְּלָלוֹ שֶׁל דָּבָר יוֹם שְׁמוּעָתוֹ הַקְּרוֹבָה כְּיוֹם הַקְּבוּרָה. אֲבָל אִם הִגִּיעָה לוֹ הַשְּׁמוּעָה אַחַר הַשְּׁלֹשִׁים יוֹם הֲרֵי זוֹ שְׁמוּעָה רְחוֹקָה וְאֵינָהּ נוֹהֶגֶת אֶלָּא יוֹם אֶחָד וְאֵינוֹ קוֹרֵעַ. וּכְאִלּוּ יוֹם הַשְּׁמוּעָה הוּא יוֹם שְׁבִיעִי וְיוֹם שְׁלֹשִׁים וּמִקְצָת הַיּוֹם כְּכֻלּוֹ:","כֵּיצַד מִקְצָת הַיּוֹם כְּכֻלּוֹ. כֵּיוָן שֶׁנָּהַג אֲבֵלוּת שָׁעָה אַחַת כְּאִלּוּ נָהַג כָּל הַיּוֹם כֻּלּוֹ. וּמֻתָּר לִנְעל וְלִרְחֹץ וְלָסוּךְ וּלְגַלֵּחַ בִּשְׁאָר הַיּוֹם. וְכֵן הוּא מֻתָּר בְּכָל הַדְּבָרִים:","מִי שֶׁבָּאָה לוֹ שְׁמוּעָה קְרוֹבָה בְּתוֹךְ הָרֶגֶל אוֹ בְּיוֹם שַׁבָּת וּלְאַחַר שַׁבָּת אוֹ אַחַר הָרֶגֶל נַעֲשֵׂית רְחוֹקָה. עוֹלֶה לוֹ וְאֵינוֹ נוֹהֵג לְאַחַר הָרֶגֶל אוֹ לְאַחַר הַשַּׁבָּת אֶלָּא יוֹם אֶחָד בִּלְבַד. וּמִקְצָת הַיּוֹם כְּכֻלּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁמֵּת לוֹ קָרוֹב וְלֹא יָדַע עַד שֶׁבָּא. אִם הָיָה בְּמָקוֹם קָרוֹב שֶׁהוּא מַהֲלַךְ עֲשָׂרָה פַּרְסָאוֹת שֶׁאֶפְשָׁר שֶׁיָּבוֹא בְּיוֹם אֶחָד. אֲפִלּוּ בָּא בַּיּוֹם הַשְּׁבִיעִי. אִם מָצָא מְנַחֲמִים אֵצֶל גְּדוֹל הַבַּיִת אַף עַל פִּי שֶׁנִּנְעֲרוּ לַעֲמֹד הוֹאִיל וּמָצָא מְנַחֲמִים עוֹלֶה לוֹ וּמוֹנֶה עִמָּהֶן תַּשְׁלוּם שְׁלֹשִׁים יוֹם. וְאִם לֹא מָצָא מְנַחֲמִים מוֹנֶה לְעַצְמוֹ. וְכֵן אִם הָיָה בְּמָקוֹם רָחוֹק אֲפִלּוּ בָּא בְּיוֹם שֵׁנִי מוֹנֶה לְעַצְמוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁבָּא:","אָבֵל בִּשְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים אֵינוֹ הוֹלֵךְ אֲפִלּוּ לְבֵית אָבֵל אַחֵר. מִכָּאן וְאֵילָךְ הוֹלֵךְ וְאֵינוֹ יוֹשֵׁב בִּמְקוֹם הַמְנַחֲמִין אֶלָּא בִּמְקוֹם הַמִּתְנַחֲמִין. וְלֹא יֵצֵא לְמָקוֹם אַחֵר מִפֶּתַח בֵּיתוֹ כָּל שַׁבָּת הָרִאשׁוֹנָה. שְׁנִיָּה יוֹצֵא וְאֵינוֹ יוֹשֵׁב בִּמְקוֹמוֹ. שְׁלִישִׁית יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר כְּדַרְכּוֹ. רְבִיעִית הֲרֵי הוּא כְּכָל אָדָם:","כֹּהֵן גָּדוֹל חַיָּב בְּכָל דִּבְרֵי אֲבֵלוּת. אֶלָּא שֶׁאָסוּר לוֹ לִקְרֹעַ בְּגָדָיו לְמַעְלָה וּלְגַדֵּל פֶּרַע וְלָצֵאת אַחַר הַמִּטָּה. וְכָל הָעָם בָּאִין לְנַחֲמוֹ לְבֵיתוֹ. וּכְשֶׁמַּבְרִין אוֹתוֹ כָּל הָעָם מְסֻבִּין עַל הָאָרֶץ וְהוּא מֵסֵב עַל הַסַּפְסָל. וְאוֹמְרִין לוֹ כְּשֶׁמְּנַחֲמִין אוֹתוֹ אָנוּ כַּפָּרָתְךָ וְהוּא אוֹמֵר לָהֶם תִּתְבָּרְכוּ מִן הַשָּׁמַיִם. וְאִם רָצָה לְנַחֵם אֲחֵרִים הַמְמֻנֶּה מְמַצְּעוֹ בְּתוֹךְ הָעָם וְאוֹמֵר לָהֶם תְּנֻחֲמוּ:","וְכֵן הַמֶּלֶךְ חַיָּב בְּכָל דִּבְרֵי אֲבֵלוּת אֶלָּא שֶׁאֵינוֹ יוֹצֵא מִפֶּתַח פַּלְטֵרִין שֶׁלּוֹ אַחַר מֵתוֹ. וְאֵין צָרִיךְ לוֹמַר אַחַר מֵתִים אֲחֵרִים. וְאֵינוֹ מְנַחֵם אֲבֵלִים. וְלֹא יָצָא דָּוִד אַחַר אַבְנֵר אֶלָּא לְהוֹדִיעַ לָעָם שֶׁלֹּא נֶהֱרַג בִּרְצוֹנוֹ:","אֵין אָדָם נִכְנָס לַמֶּלֶךְ לְנַחֲמוֹ אֶלָּא עֲבָדָיו וּמִי שֶׁנָּתַן לוֹ רְשׁוּת לְהִכָּנֵס. וְאֵין לָהֶן רְשׁוּת לְדַבֵּר לוֹ דִּבְרֵי תַּנְחוּמִין אֶלָּא כְּפִי מַה שֶּׁיַּרְשֶׁה אוֹתָם. וּכְשֶׁמַּבְרִין אוֹתוֹ כָּל הָעָם מְסֻבִּין עַל הָאָרֶץ וְהוּא מֵסֵב עַל הַדַּרְגָּשׁ:"],"Mishneh Torah, Murderer and the Preservation of Life 6":["שְׁלֹשָׁה הֵם הַהוֹרְגִים בְּלֹא כַּוָּנָה:","יֵשׁ הוֹרֵג בִּשְׁגָגָה וְהַעֲלָמָה גְּמוּרָה וְזֶהוּ שֶׁנֶּאֱמַר בּוֹ (שמות כא יג) \"וַאֲשֶׁר לֹא צָדָה\". וְדִינוֹ שֶׁיִּגְלֶה לְעָרֵי מִקְלָט וְיִנָּצֵל כְּמוֹ שֶׁבֵּאַרְנוּ:","וְיֵשׁ הוֹרֵג וְתִהְיֶה הַשְּׁגָגָה קָרוֹב לְאֹנֶס וְהוּא שֶׁיֶּאֱרַע בְּמִיתַת זֶה מְאֹרָע פֶּלֶא שֶׁאֵינוֹ מָצוּי בְּרֹב מְאֹרְעוֹת בְּנֵי אָדָם. וְדִינוֹ שֶׁהוּא פָּטוּר מִן הַגָּלוּת. וְאִם הֲרָגוֹ גּוֹאֵל הַדָּם נֶהֱרָג עָלָיו:","וְיֵשׁ הוֹרֵג בִּשְׁגָגָה וְתִהְיֶה הַשְּׁגָגָה קְרוֹבָה לְזָדוֹן וְהוּא שֶׁיִּהְיֶה בַּדָּבָר כְּמוֹ פְּשִׁיעָה. אוֹ שֶׁהָיָה לוֹ לְהִזָּהֵר וְלֹא נִזְהַר. וְדִינוֹ שֶׁאֵינוֹ גּוֹלֶה מִפְּנֵי שֶׁעֲוֹנוֹ חָמוּר אֵין גָּלוּת מְכַפֶּרֶת לוֹ וְאֵין עָרֵי מִקְלָט קוֹלְטוֹת אוֹתוֹ שֶׁאֵינָן קוֹלְטוֹת אֶלָּא הַמְחֻיָּב גָּלוּת בִּלְבַד. לְפִיכָךְ אִם מְצָאוֹ גּוֹאֵל הַדָּם בְּכָל מָקוֹם וַהֲרָגוֹ פָּטוּר:","וּמַה יַּעֲשֶׂה זֶה. יֵשֵׁב וְיִשְׁמֹר עַצְמוֹ מִגּוֹאֵל הַדָּם. וְכֵן כָּל הָרַצְחָנִים שֶׁהָרְגוּ בְּעֵד אֶחָד אוֹ בְּלֹא הַתְרָאָה וְכַיּוֹצֵא בָּהֶן אִם הֲרָגָן גּוֹאֵל הַדָּם אֵין לָהֶם דָּמִים. לֹא יִהְיוּ אֵלּוּ חֲמוּרִים מֵהַהוֹרֵג בְּלֹא כַּוָּנָה:","כֵּיצַד. הַזּוֹרֵק אֶבֶן לִרְשׁוּת הָרַבִּים וְהָרְגָה אוֹ הַסּוֹתֵר כָּתְלוֹ לִרְשׁוּת הָרַבִּים וְנָפְלָה אֶבֶן וְהֵמִיתָה. בֵּין שֶׁסְּתָרוֹ בַּיּוֹם בֵּין שֶׁסְּתָרוֹ בַּלַּיְלָה הֲרֵי זֶה קָרוֹב לְמֵזִיד וְאֵינוֹ נִקְלָט מִפְּנֵי שֶׁזּוֹ פְּשִׁיעוּת הִיא שֶׁהֲרֵי הָיָה לוֹ לְעַיֵּן וְאַחַר כָּךְ יִזְרֹק אוֹ יִסְתֹּר:","סְתָרוֹ לָאַשְׁפָּה בַּלַּיְלָה אִם הָרַבִּים מְצוּיִין בָּהּ הֲרֵי זֶה קָרוֹב לְמֵזִיד וְאֵינוֹ נִקְלָט וְאִם אֵין הָרַבִּים מְצוּיִין בָּהּ כְּלָל הֲרֵי זֶה קָרוֹב לְאֹנֶס וּפָטוּר מִן הַגָּלוּת:","הָיְתָה הָאַשְׁפָּה עֲשׂוּיָה לְהִפָּנוֹת בָּהּ בַּלַּיְלָה וְאֵינָהּ עֲשׂוּיָה לְהִפָּנוֹת בָּהּ בַּיּוֹם וְנִקְרָה אָדָם וְיָשַׁב שָׁם וְנָפְלָה עָלָיו אֶבֶן בִּשְׁעַת סְתִירָה וּמֵת הֲרֵי זֶה גּוֹלֶה. וְאִם אַחַר שֶׁנָּפְלָה הָאֶבֶן בָּא זֶה וְיָשַׁב וְנָפְלָה עָלָיו וּמֵת הֲרֵי זֶה פָּטוּר מִן הַגָּלוּת:","וְכֵן הַזּוֹרֵק אֶת הָאֶבֶן וְאַחַר שֶׁיָּצָאת מִיָּדוֹ הוֹצִיא הַלָּה אֶת רֹאשׁוֹ וְקִבְּלָהּ פָּטוּר מִגָּלוּת שֶׁנֶּאֱמַר (דברים יט ה) \"וּמָצָא אֶת רֵעֵהוּ\" פְּרָט לְמַמְצִיא עַצְמוֹ:","הַשּׂוֹנֵא שֶׁהָרַג בִּשְׁגָגָה אֵינוֹ נִקְלָט שֶׁנֶּאֱמַר (במדבר לה כג) \"וְהוּא לֹא אוֹיֵב לוֹ\" חֶזְקָתוֹ שֶׁהוּא קָרוֹב לְמֵזִיד. וְאֵי זֶהוּ שׂוֹנֵא זֶה שֶׁלֹּא דִּבֵּר עִמּוֹ שְׁלֹשָׁה יָמִים מִפְּנֵי הָאֵיבָה. וְכֵן אִם נִכְנַס לְקֶרֶן זָוִית וֶהֱמִיתוֹ שָׁם בִּשְׁגָגָה אוֹ שֶׁדְּחָפוֹ בְּגוּפוֹ אוֹ נִתְכַּוֵּן לִזְרֹק שְׁתַּיִם וְזָרַק אַרְבַּע. אוֹ שֶׁעָלָה עַל דַּעְתּוֹ שֶׁמֻּתָּר לַהֲרֹג. אוֹ שֶׁנִּתְכַּוֵּן לַהֲרֹג אֶת זֶה וְהָרַג אֶת זֶה אֲפִלּוּ נִתְכַּוֵּן לַהֲרֹג עַכּוּ\"ם אוֹ בְּהֵמָה וְנִמְצָא יִשְׂרָאֵל הֲרֵי כָּל אֵלּוּ קְרוֹבִין לְמֵזִיד וְאֵינָן נִקְלָטִין:","הַנִּכְנָס לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּת וַהֲרָגוֹ בַּעַל הַבַּיִת בִּשְׁגָגָה פָּטוּר מִן הַגָּלוּת שֶׁנֶּאֱמַר (דברים יט ה) \"וַאֲשֶׁר יָבֹא אֶת רֵעֵהוּ בַיַּעַר\" מָה יַעַר שֶׁיֵּשׁ רְשׁוּת לַנֶּהֱרָג לְהִכָּנֵס לְשָׁם אַף כָּל כַּיּוֹצֵא בּוֹ. לְפִיכָךְ הַנִּכְנָס לַחֲנוּת הַנַּגָּר שֶׁלֹּא בִּרְשׁוּת וְנִתְּזָה בְּקַעַת וְטָפְחָה לוֹ עַל פָּנָיו וּמֵת פָּטוּר מִגָּלוּת. וְאִם נִכְנַס בִּרְשׁוּת הֲרֵי זֶה גּוֹלֶה:","מִי שֶׁהָיָה דּוֹלֶה אֶת הֶחָבִית לְהַעֲלוֹתָהּ לַגַּג. וְנִפְסַק הַחֶבֶל וְנָפְלָה עַל חֲבֵרוֹ וַהֲרָגַתְהוּ. אוֹ שֶׁהָיָה עוֹלֶה בַּסֻּלָּם וְנָפַל עַל חֲבֵרוֹ וַהֲרָגוֹ. פָּטוּר מִן הַגָּלוּת. שֶׁזֶּה כְּמוֹ אָנוּס הוּא. שֶׁאֵין זֶה דָּבָר הַקָּרוֹב לִהְיוֹת בְּרֹב הָעִתִּים אֶלָּא כְּמוֹ פֶּלֶא הוּא. אֲבָל אִם הָיָה מְשַׁלְשֵׁל אֶת הֶחָבִית וְנָפְלָה עַל חֲבֵרוֹ וַהֲרָגַתְהוּ. הָיָה יוֹרֵד בַּסֻּלָּם וְנָפַל עַל חֲבֵרוֹ. הָיָה מְעַגֵּל בְּמַעְגֵּלָה וְנָפְלָה עַל חֲבֵרוֹ וַהֲרָגַתְהוּ. גּוֹלֶה. שֶׁנֶּאֱמַר (במדבר לה כג) \"וַיַּפֵּל עָלָיו וַיָּמֹת\" שֶׁיִּפּל דֶּרֶךְ נְפִילָה. שֶׁהֲרֵי דֶּרֶךְ נְפִילָה מָצוּי בְּרֹב הָעִתִּים לְהַזִּיק וְדָבָר קָרוֹב הוּא לִהְיוֹת. שֶׁהֲרֵי טֶבַע הַכָּבֵד לֵירֵד לְמַטָּה בִּמְהֵרָה. וְהוֹאִיל וְלֹא זֵרֵז עַצְמוֹ וְתִקֵּן מַעֲשָׂיו יָפֶה בִּשְׁעַת יְרִידָה יִגְלֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","קַצָּב שֶׁהָיָה מְקַצֵּב וְהִגְבִּיהַּ יָדוֹ בַּקּוֹפִיץ לַאֲחוֹרָיו וְהֶחֱזִירוֹ לִשְׁבֹּר הָעֶצֶם כְּדֶרֶךְ שֶׁעוֹשִׂין הַקַּצָּבִים. כָּל שֶׁיָּמוּת בַּהוֹלָכָה שֶׁהִיא הַהַגְבָּהָה מִלְּפָנָיו וִירִידָה מֵאַחֲרָיו אֵינוֹ גּוֹלֶה עָלָיו. וְכָל שֶׁיָּמוּת בַּחֲזָרָה שֶׁהִיא עֲלִיָּה מֵאַחֲרָיו וִירִידָה מִלְּפָנָיו גּוֹלֶה. זֶה הַכְּלָל כָּל שֶׁבְּדֶרֶךְ יְרִידָתוֹ גּוֹלֶה שֶׁלֹּא בְּדֶרֶךְ יְרִידָתוֹ אֵינוֹ גּוֹלֶה. וַאֲפִלּוּ בִּירִידָה שֶׁהִיא צֹרֶךְ עֲלִיָּה אֵינוֹ גּוֹלֶה:","כֵּיצַד. הָיָה עוֹלֶה בַּסֻּלָּם וְנִשְׁמְטָה שְׁלִיבָה מִתַּחַת רַגְלָיו וְנָפְלָה וְהֵמִיתָה פָּטוּר מִן הַגָּלוּת. וְכֵן הַמִּתְכַּוֵּן לִזְרֹק בְּצַד זֶה וְהָלְכָה לָהּ לְצַד אַחֵר אוֹ שֶׁהָיְתָה לוֹ אֶבֶן מֻנַּחַת בְּחֵיקוֹ וְלֹא הִכִּיר בָּהּ מֵעוֹלָם וְעָמַד וְנָפְלָה וְהֵמִיתָה. וְכֵן הַסּוּמָא שֶׁהָרַג בִּשְׁגָגָה. כָּל אֵלּוּ פְּטוּרִין מִן הַגָּלוּת מִפְּנֵי שֶׁהֵן קְרוֹבִין לְאֹנֶס:","הָיְתָה אֶבֶן בְּחֵיקוֹ וְהִכִּיר בָּהּ וּשְׁכָחָהּ וְעָמַד וְנָפְלָה וְהֵמִיתָה גּוֹלֶה שֶׁנֶּאֱמַר (במדבר לה יא) \"בִּשְׁגָגָה\" מִכְּלָל שֶׁהָיְתָה לוֹ יְדִיעָה. נִשְׁמַט הַבַּרְזֶל מִן הָעֵץ הַמִּתְבַּקֵּעַ אֵינוֹ גּוֹלֶה מִפְּנֵי שֶׁאֵין זֶה בָּא מִכֹּחוֹ אֶלָּא מִכֹּחַ כֹּחוֹ וְנִמְצָא כְּמוֹ אֹנֶס. וְכֵן הַזּוֹרֵק אֶבֶן לְתָמָר לְהַפִּיל תְּמָרִים וְנָפְלוּ מִן הַתְּמָרִים עַל תִּינוֹק וַהֲרָגוּהוּ פָּטוּר מִפְּנֵי שֶׁנָּפְלוּ מִכֹּחַ כֹּחוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִשְּׁאָר הַסִּבּוֹת:"],"Mishneh Torah, Nazariteship 8":["תִּגְלַחַת הַטָּהֳרָה כֵּיצַד הִיא. כְּשֶׁיִּגְמֹר הַנָּזִיר יְמֵי נְזִירוּתוֹ מֵבִיא שָׁלֹשׁ בְּהֵמוֹת כֶּבֶשׂ לְעוֹלָה וְכַבְשָׂה לְחַטָּאת וְאַיִל לִשְׁלָמִים. הֵבִיא שְׁלָשְׁתָּן וְלֹא פֵּרֵשׁ. הָרְאוּיָה לְחַטָּאת תִּקְרַב חַטָּאת וְהָרְאוּיָה לִשְׁלָמִים שְׁלָמִים וְהָרְאוּיָה לְעוֹלָה עוֹלָה. וּמֵבִיא עִם אֵיל הַשְּׁלָמִים שִׁשָּׁה עֶשְׂרוֹנוֹת וּשְׁנֵי שְׁלִישֵׁי עִשָּׂרוֹן סלֶת. אוֹפֶה מֵהֶן עֶשְׂרִים חַלָּה עֶשֶׂר חַלּוֹת מַצּוֹת וַעֲשָׂרָה רְקִיקֵי מַצּוֹת. וּמוֹשֵׁחַ הָעֶשְׂרִים בִּרְבִיעִית שֶׁמֶן. וְשִׁעוּר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי. וּמֵבִיא הָעֶשְׂרִים בִּכְלִי אֶחָד:","וְשׁוֹחֵט הַחַטָּאת תְּחִלָּה וְאַחַר כָּךְ הָעוֹלָה וְאַחַר כָּךְ שְׁלָמִים וְאַחַר כָּךְ מְגַלֵּחַ. וְאִם גִּלֵּחַ אַחַר שֶׁשָּׁחַט הַחַטָּאת אוֹ הָעוֹלָה יָצָא. וּמְבַשֵּׁל הַשְּׁלָמִים אוֹ שׁוֹלְקָן וְלוֹקֵחַ מִן הָרֹטֶב שֶׁל זִבְחֵי הַשְּׁלָמִים וְנוֹתֵן עַל הַשֵּׂעָר וְאַחַר כָּךְ מַשְׁלִיכוֹ לָאֵשׁ תַּחַת דּוּד הַשְּׁלָמִים. וְאִם הִשְׁלִיכוֹ תַּחַת הַחַטָּאת יָצָא:","וְהֵיכָן מְגַלֵּחַ שְׂעָרוֹ בְּעֶזְרַת הַנָּשִׁים בְּלִשְׁכַּת הַנְּזִירִים שֶׁהָיְתָה שָׁם בְּקֶרֶן מִזְרָחִית דְּרוֹמִית וְשֵׁם מְבַשְּׁלִין אֶת שְׁלָמֵיהֶן וּמַשְׁלִיכִין שְׂעָרָן לָאֵשׁ. וְאִם גִּלֵּחַ בַּמְּדִינָה יָצָא. וּבֵין שֶׁגִּלֵּחַ בַּמְּדִינָה וּבֵין שֶׁגִּלֵּחַ בַּמִּקְדָּשׁ תַּחַת הַדּוּד הוּא מַשְׁלִיךְ שְׂעָרוֹ. וְאֵינוֹ מְגַלֵּחַ עַד שֶׁיִּהְיֶה פֶּתַח הָעֲזָרָה פָּתוּחַ שֶׁנֶּאֱמַר (במדבר ו יח) \"פֶּתַח אֹהֶל מוֹעֵד\". לֹא שֶׁיְּגַלַּח כְּנֶגֶד הַפֶּתַח שֶׁזֶּה בִּזְיוֹן מִקְדָּשׁ הוּא:","וְאַחַר כָּךְ נוֹטֵל הַכֹּהֵן אֶת הַזְּרוֹעַ בְּשֵׁלָה מִן הָאַיִל וְחַלַּת מַצָּה אַחַת מִן הַסַּל וְרָקִיק אֶחָד וְנוֹתְנָן עַל כַּפֵּי הַנָּזִיר אוֹ הַנְּזִירָה וּמְנִיפָן וְאַחַר כָּךְ הֻתַּר הַנָּזִיר לִשְׁתּוֹת יַיִן וּלְהִטַּמֵּא לְמֵתִים:","נָזִיר מְמֹרָט אֵינוֹ צָרִיךְ לְהַעֲבִיר תַּעַר. וְאַף עַל פִּי שֶׁאֵין לוֹ שֵׂעָר אוֹ שֶׁאֵין לוֹ כַּפַּיִם הֲרֵי זֶה מַקְרִיב קָרְבְּנוֹתָיו וְיִשְׁתֶּה וְיִטַּמֵּא. וְאִם הֵבִיא קָרְבְּנוֹתָיו וְלֹא גִּלֵּחַ רֹאשׁוֹ אֵין הַתִּגְלַחַת מְעַכֶּבֶת אֶלָּא שׁוֹתֶה וּמִטַּמֵּא לָעֶרֶב. שֶׁמִּשֶּׁיִּזָּרֵק עָלָיו אֶחָד מִן הַדָּמִים הֻתַּר אַף עַל פִּי שֶׁלֹּא נָתַן עַל כַּפָּיו וְלֹא הֵנִיף שֶׁכָּל דְּבָרִים אֵלּוּ לְמִצְוָה וְלֹא לְעַכֵּב:","אַף עַל פִּי שֶׁאֵין הַתִּגְלַחַת מְעַכֵּב עָלָיו מִצְוָה לְגַלֵּחַ אֲפִלּוּ לְאַחַר זְמַן מְרֻבֶּה. וְנָזִיר שֶׁגִּלֵּחַ בְּלֹא תַּעַר אוֹ שֶׁגִּלֵּחַ וְשִׁיֵּר שְׁתֵּי שְׂעָרוֹת לֹא עָשָׂה כְּלוּם וְלֹא קִיֵּם מִצְוַת גִּלּוּחַ. בֵּין נָזִיר טָהוֹר בֵּין נָזִיר טָמֵא:","גִּלֵּחַ וְהִנִּיחַ שְׁתֵּי שְׂעָרוֹת וְצִמֵּחַ רֹאשׁוֹ כֻּלּוֹ וְחָזַר וְגִלְּחוֹ עִם אוֹתָן שְׁתֵּי הַשְּׂעָרוֹת אוֹ שֶׁגִּלֵּחַ אַחַת וְנָשְׁרָה אַחַת הֲרֵי זֶה קִיֵּם מִצְוַת גִּלּוּחַ. נָשְׁרָה אַחַת וְגִלֵּחַ אַחַת אֵין כָּאן מִצְוַת גִּלּוּחַ:","גִּלֵּחַ עַל הַשְּׁלָמִים וְנִמְצָא פָּסוּל תִּגְלַחְתּוֹ פְּסוּלָה וּזְבָחָיו לֹא עָלוּ לוֹ. גִּלֵּחַ עַל הַחַטָּאת וְנִמְצֵאת שֶׁלֹּא נִשְׁחֲטָה לְשֵׁם חַטָּאת וְאַחַר כָּךְ הֵבִיא הַשְּׁלָמִים וְהָעוֹלָה וְהִקְרִיבָן כְּמִצְוָתָן תִּגְלַחְתּוֹ פְּסוּלָה וּזְבָחָיו לֹא עָלוּ לוֹ:","גִּלֵּחַ עַל הָעוֹלָה וְעַל הַשְּׁלָמִים וְנִשְׁחֲטוּ שֶׁלֹּא לִשְׁמָן וְאַחַר כָּךְ הֵבִיא קָרְבָּנוֹת אֲחֵרוֹת לְהַקְרִיבָן לִשְׁמָן תִּגְלַחְתּוֹ פְּסוּלָה וּזְבָחָיו לֹא עָלוּ לוֹ:","גִּלֵּחַ עַל שְׁלָשְׁתָּן וְנִמְצָא אֶחָד מֵהֶם כָּשֵׁר תִּגְלַחְתּוֹ כְּשֵׁרָה וְיָבִיא שְׁאָר הַזְּבָחִים וְיִקָּרְבוּ כְּהִלְכָתָן:","כָּל מָקוֹם שֶׁאָמַרְנוּ תִּגְלַחְתּוֹ פְּסוּלָה הֲרֵי הוּא כְּמִי שֶׁנִּתְגַּלֵּחַ בְּתוֹךְ יְמֵי נְזִירוּתוֹ שֶׁהוּא סוֹתֵר שְׁלֹשִׁים יוֹם כְּמוֹ שֶׁבֵּאַרְנוּ. וְנִמְצָא מוֹנֶה שְׁלֹשִׁים יוֹם אַחַר הַתִּגְלַחַת הַפְּסוּלָה וְיָבִיא קָרְבְּנוֹתָיו:","שַׁלְמֵי נָזִיר שֶׁשְּׁחָטָן שֶׁלֹּא כְּמִצְוָתָן כְּשֵׁרִים וְאֵין עוֹלִים לַבְּעָלִים לְשֵׁם חוֹבָה. וְנֶאֱכָלִין לְיוֹם אֶחָד וְאֵין טְעוּנִין לֶחֶם וְלֹא מַתָּנוֹת וְלֹא זְרוֹעַ:","שָׁלֹשׁ בְּהֵמוֹת אֵלּוּ וְהַלֶּחֶם הַבָּא עִמָּהֶם הַכּל מִן הַחֻלִּין כִּשְׁאָר נִדְרֵי הֶקְדֵּשׁ כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","הָאוֹמֵר הֲרֵינִי נָזִיר עַל מְנָת שֶׁאֲגַלֵּחַ מִמְּעוֹת מַעֲשֵׂר שֵׁנִי הֲרֵי זֶה נָזִיר וְאֵינוֹ מֵבִיא קָרְבְּנוֹתָיו מִן הַמַּעֲשֵׂר אֶלָּא מִן הַחֻלִּין:","הָאִישׁ שֶׁנָּדַר בְּנָזִיר יֵשׁ לוֹ לְהָבִיא קָרְבְּנוֹת אָבִיו לְעַצְמוֹ וּמְגַלֵּחַ עֲלֵיהֶם. וְאֵין הָאִשָּׁה מְגַלַּחַת עַל קָרְבְּנוֹת אָבִיהָ וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה הוּא. כֵּיצַד. מִי שֶׁהָיָה אָבִיו נָזִיר וְהִפְרִישׁ מָעוֹת לִקְנוֹת בָּהֶן קָרְבְּנוֹתָיו וּמֵת וְהִנִּיחַ הַמָּעוֹת סְתוּמִין וְאָמַר אַחֲרֵי מוֹת אָבִיו הֲרֵינִי נָזִיר עַל מְנָת שֶׁאָבִיא קָרְבְּנוֹתַי מִמָּעוֹת שֶׁהִפְרִישׁ בָּהֶן אָבִי לְקָרְבְּנוֹתָיו הֲרֵי זֶה מֵבִיא מֵהֶן קָרְבְּנוֹתָיו. וְכֵן אִם הָיָה הוּא וְאָבִיו נְזִירִים וְהִפְרִישׁ אָבִיו מָעוֹת סְתוּמִין וּמֵת הָאָב וְאָמַר הַבֵּן אַחַר מוֹת אָבִיו הֲרֵינִי מְגַלֵּחַ עַל מְעוֹת אָבִי הֲרֵי זֶה מֵבִיא קָרְבְּנוֹתָיו מֵהֶן. אֲבָל אִם לֹא אָמַר יִפְּלוּ הַמָּעוֹת לִנְדָבָה. מֵת הָאָב וְהִנִּיחַ בָּנִים רַבִּים חוֹלְקִים הַמָּעוֹת הַסְּתוּמִים מִפְּנֵי שֶׁהִיא יְרֻשָּׁה לָהֶן וְיֵשׁ לְכָל אֶחָד מֵהֶן לְגַלֵּחַ עַל חֶלְקוֹ וְהַבְּכוֹר נוֹטֵל בָּהֶן פִּי שְׁנַיִם:","בֵּין שֶׁהָיָה הָאָב נְזִיר עוֹלָם וְהַבֵּן נָזִיר זְמַן קָצוּב בֵּין שֶׁהָיָה הָאָב נָזִיר זְמַן קָצוּב וְהַבֵּן נְזִיר עוֹלָם הֲרֵי זֶה מְגַלֵּחַ וּמֵבִיא קָרְבְּנוֹתָיו מִמְּעוֹת נְזִירוּת אָבִיו:","הִפְרִישׁ הָאָב מָעוֹת לְהָבִיא בָּהֶן קָרְבְּנוֹת טֻמְאָה וּמֵת אֵין הַבֵּן מֵבִיא בָּהֶן קָרְבְּנוֹת טָהֳרָה. וְכֵן אִם הִפְרִישָׁן הָאָב לְקָרְבַּן טָהֳרָה אֵין הַבֵּן מְגַלֵּחַ עֲלֵיהֶן תִּגְלַחַת טֻמְאָה. שֶׁדְּבָרִים אֵלּוּ הֵן סָפֵק וְאִם הֵבִיא זְבָחָיו לֹא עָלוּ לוֹ:","הָאוֹמֵר הֲרֵי עָלַי לְגַלֵּחַ נָזִיר חַיָּב לְהָבִיא קָרְבְּנוֹת תִּגְלַחַת טָהֳרָה וּמַקְרִיבָן עַל יַד אֵיזֶה נָזִיר שֶׁיִּרְצֶה. אָמַר הֲרֵי עָלַי חֲצִי קָרְבְּנוֹת נָזִיר. אוֹ אִם אָמַר הֲרֵי עָלַי לְגַלֵּחַ חֲצִי נָזִיר. הֲרֵי זֶה מֵבִיא חֲצִי הַקָּרְבָּנוֹת לְאֵיזֶה נָזִיר שֶׁיִּרְצֶה. וְאוֹתוֹ נָזִיר מַשְׁלִים קָרְבְּנוֹתָיו מִשֶּׁלּוֹ. אֲבָל אִם אָמַר הֲרֵי עָלַי קָרְבְּנוֹת חֲצִי נָזִיר הֲרֵי זֶה מֵבִיא קָרְבְּנוֹת נָזִיר שָׁלֵם שֶׁאֵין לָנוּ חֲצִי נְזִירוּת:","הָאוֹמֵר הֲרֵינִי נָזִיר וְעָלַי לְגַלֵּחַ נָזִיר וְשָׁמַע חֲבֵרוֹ וְאָמַר וַאֲנִי הֲרֵי חֲבֵרוֹ נָזִיר. וְאֵינוֹ חַיָּב לְגַלֵּחַ נָזִיר אַחֵר. שֶׁהֲרֵי לֹא הִתְפִּיס עַצְמוֹ אֶלָּא בִּנְזִירוּת. וְאִם אָמַר וַאֲנִי וְעָלַי לְגַלֵּחַ נָזִיר הֲרֵי זֶה חַיָּב. וְאִם הָיוּ פִּקְחִין מֵבִיא כָּל אֶחָד מֵהֶן קָרְבָּנוֹת עַל יְדֵי חֲבֵרוֹ וְאִם לֹא עָשׂוּ כֵן חַיָּבִים לְגַלֵּחַ נְזִירוּת אֲחֵרִים:","הָאוֹמֵר הֲרֵי עָלַי לְגַלֵּחַ חֲצִי נָזִיר וְשָׁמַע חֲבֵרוֹ וְאָמַר וַאֲנִי וְעָלַי לְגַלֵּחַ חֲצִי נָזִיר. זֶה מֵבִיא חֲצִי קָרְבְּנוֹתָיו שֶׁל זֶה וְזֶה מֵבִיא חֲצִי קָרְבְּנוֹתָיו שֶׁל זֶה וְכָל אֶחָד מֵהֶן מַשְׁלִים קָרְבְּנוֹתָיו אִם הָיוּ פִּקְחִין. וְאִם לָאו זֶה מֵבִיא חֲצִי קָרְבָּנוֹת מֵאֵיזֶה נָזִיר שֶׁיִּרְצֶה וְזֶה מֵבִיא חֲצִי קָרְבָּנוֹת מֵאֵיזֶה נָזִיר שֶׁיִּרְצֶה:"],"Mishneh Torah, Negative Mitzvot 108":["שלא לפדות בכור בהמה טהורה, שנאמר \"אך בכור שור . . . לא תפדה\" (במדבר יח,יז)."],"Mishneh Torah, Negative Mitzvot 119":["שלא להותיר מבשר פסח שני עד בוקר, שנאמר \"ולא ישאירו ממנו עד בוקר\" (ראה במדבר ט,יב)."],"Mishneh Torah, Negative Mitzvot 13":["שלא ליטע אילן במקדש, שנאמר \"לא תיטע לך אשרה, כל עץ\" (דברים טז,כא)."],"Mishneh Torah, Negative Mitzvot 140":["שלא לאכול פסולי המוקדשין שהוטל בהם מום בכוונה, שנאמר \"לא תאכל, כל תועבה\" (דברים יד,ג); מפי השמועה למדנו שבפסולי המוקדשין שהוטל בהם מום הכתוב מדבר."],"Mishneh Torah, Negative Mitzvot 151":["שלא לאכול מעשר שני באנינות, שנאמר \"לא אכלתי באוני ממנו\" (דברים כו,יד)."],"Mishneh Torah, Negative Mitzvot 162":["שלא יבעול כוהן גדול אלמנה, ואפילו בלא קידושים, מפני שמחללה, שנאמר \"לא יחלל זרעו, בעמיו\" (ויקרא כא,טו); הרי הוא מוזהר שלא לחלל כשרה."],"Mishneh Torah, Negative Mitzvot 173":["שלא לאכול דג טמא, שנאמר \"ושקץ, יהיו לכם; מבשרם לא תאכלו\" (ויקרא יא,יא)."],"Mishneh Torah, Negative Mitzvot 184":["שלא לאכול דם, שנאמר \"וכל דם, לא תאכלו\" (ויקרא ג,יז; ויקרא ז,כו)."],"Mishneh Torah, Negative Mitzvot 195":["שלא לאכול ולשתות דרך זולל וסובא, שנאמר \"בננו זה . . . זולל, וסובא\" (דברים כא,כ)."],"Mishneh Torah, Negative Mitzvot 205":["שלא יאכל חרצנים, שנאמר \"מחרצנים . . . לא יאכל\" (במדבר ו,ד)."],"Mishneh Torah, Negative Mitzvot 216":["שלא לזרוע תבואה או ירק בכרם, שנאמר \"לא תזרע כרמך, כלאיים\" (דברים כב,ט)."],"Mishneh Torah, Negative Mitzvot 227":["שלא למכור שדה בארץ ישראל לצמיתות, שנאמר \"והארץ, לא תימכר לצמיתות\" (ויקרא כה,כג)."],"Mishneh Torah, Negative Mitzvot 238":["שלא לאחר פעולת שכיר, שנאמר \"לא תלין פעולת שכיר, איתך\" (ויקרא יט,יג)."],"Mishneh Torah, Negative Mitzvot 249":["שלא לישבע על כפירת ממון חברו, שנאמר \"לא תשקרו\" (ויקרא יט,יא); כלומר, לא תישבע על שקר בממון שיש לחברך בידך."],"Mishneh Torah, Negative Mitzvot 26":["שלא להתנבא בשמה, שנאמר \"ואשר ידבר, בשם אלוהים אחרים\" (דברים יח,כ)."],"Mishneh Torah, Negative Mitzvot 270":["שלא להניח הבהמה רובצת תחת משאה בדרך, שנאמר \"לֹא תִרְאֶה חֲמוֹר אָחִיךָ\" (ראה דברים כב, ד)."],"Mishneh Torah, Negative Mitzvot 281":["שלא לשמוע מאחד מבעלי דינין ואין חברו עימו, שנאמר \"לֹא תִשָּׂא שֵׁמַע שָׁוְא\" (שמות כג, א)."],"Mishneh Torah, Negative Mitzvot 292":["שלא להרוג מחוייב הריגה קודם שיעמוד בדין, שנאמר \"וְלֹא יָמוּת הָרוֹצֵחַ עַד עָמְדוֹ לִפְנֵי הָעֵדָה\" (במדבר לה, יב)."],"Mishneh Torah, Negative Mitzvot 302":["שלא לשנוא בלב, שנאמר \"לֹא תִשְׂנָא אֶת אָחִיךָ בִּלְבָבֶךָ\" (ויקרא יט, יז)."],"Mishneh Torah, Negative Mitzvot 313":["שלא להוסיף על מצוות התורה, בין תורה שבכתב בין בפירושה שקיבלו על פה, שנאמר \"את כל הדבר, אשר אנוכי מצווה אתכם--אותו תשמרו, לעשות: .לא תוסף עליו\" (דברים יג,א)."],"Mishneh Torah, Negative Mitzvot 324":["שלא לעשות מלאכה בשביעי של פסח, שנאמר \"כל מלאכה, לא ייעשה בהם\" (שמות יב,טז)."],"Mishneh Torah, Negative Mitzvot 335":["שלא לגלות ערוות בת הבת, שנאמר \"או בת בתך, לא תגלה ערוותן\" (ויקרא יח,י)."],"Mishneh Torah, Negative Mitzvot 346":["שלא לגלות ערוות נידה, שנאמר \"ואל אישה, בנידת טומאתה--לא תקרב\" (ויקרא יח,יט)."],"Mishneh Torah, Negative Mitzvot 357":["שלא תינשא היבמה לאחר חוץ מיבמה, שנאמר \"לא תהיה אשת המת\" (דברים כה,ה)."],"Mishneh Torah, Negative Mitzvot 39":["שלא תעדה אישה עדי איש, שנאמר \"לא יהיה כלי גבר על אישה\" (דברים כב,ה)."],"Mishneh Torah, Negative Mitzvot 5":["שלא להשתחוות לעבודה זרה, ואף על פי שאין דרך עבודתה בהשתחוויה, שנאמר \"לא תשתחווה להם\" (שמות כ,ד; דברים ה,ח)."],"Mishneh Torah, Negative Mitzvot 60":["שאנו מוזהרין על ברכת השם, שנאמר \"אלוהים, לא תקלל\" (שמות כב,כז), ונאמר בעונש \"ונוקב שם ה' מות יומת\" (ויקרא כד,טז). .וזה הכלל: .כל שענש עליו הכתוב כרת או מיתת בית דין, הרי זו מצות לא תעשה--חוץ ממילה ופסח, שהן בכרת והן מצוות עשה."],"Mishneh Torah, Negative Mitzvot 71":["שלא יעבוד בעל מום עובר, שנאמר \"כָּל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרַב\" (ויקרא כא, יח)."],"Mishneh Torah, Negative Mitzvot 82":["שלא להקטיר ולהקריב במזבח הזהב, שנאמר \"לא תעלו עליו קטורת זרה\" (שמות ל,ט)."],"Mishneh Torah, Negative Mitzvot 93":["שלא לזרוק דם בעלי מומין לגבי המזבח, שנאמר בבעלי מומין \"לא תקריבו לה'\" (ויקרא כב,כד); וזה הוא איסור זריקת דמו."],"Mishneh Torah, Neighbors 14":["הָרוֹצֶה לִמְכֹּר שָׂדֵהוּ וְהֵבִיא בֶּן הַמֵּצר שֶׁלּוֹ וְזֶה שֶׁרוֹצֶה לִקַּח מִמֶּנּוּ לְבֵית דִּין וְאָמַר לְבֶן הַמֵּצַר אִם תִּרְצֶה לִקְנוֹת בְּכָךְ וְכָךְ עֲשֵׂה וְאִם לָאו סַלֵּק אֶת עַצְמְךָ וַהֲרֵי זֶה לוֹקֵחַ. הֲרֵי זֶה לֹא נִשְׁאֲרָה לוֹ טַעֲנָה אֶלָּא אוֹ מֵבִיא מָעוֹת מִיָּד וְיִקְנֶה אוֹ בָּטְלָה זְכוּתוֹ. אָמַר אֶטְרַח וְאָבִיא אֵין שׁוֹמְעִין לוֹ. אֵלֵךְ וָאָבִיא אִם הוּא אָמוּד שֶׁיֵּשׁ לוֹ מַמְתִּינִין לוֹ עַד שֶׁיֵּלֵךְ וְיָבִיא. וְאִם אֵינוֹ אָמוּד אֵין שׁוֹמְעִין לוֹ שֶׁאֵינוֹ רוֹצֶה אֶלָּא לְהִשָּׁמֵט. לְפִיכָךְ אוֹמְרִים לוֹ אוֹ תּוֹצִיא עַתָּה זוּזִים אוֹ בְּטֵלָה זְכוּתְךָ. שֶׁאֵין קוֹבְעִין זְמַן לְבַעַל הַמֵּצַר. הוֹצִיא בֶּן הַמֵּצַר הַמָּעוֹת וְהוֹצִיא הַלּוֹקֵחַ מָעוֹת אִם הָיוּ שֶׁל לוֹקֵחַ טוֹבִים מִזּוּזָיו אוֹ מְמַהֲרִים לָצֵאת יוֹתֵר מִזּוּזָיו בָּטְלָה זְכוּתוֹ וְאֵין לוֹ דִּין בֶּן הַמֵּצַר. הָיָה רוֹצֶה הַלּוֹקֵחַ לִקְנוֹתָהּ לִבְנוֹת בָּהּ בָּתִּים וּבֶן הַמֵּצַר רוֹצֶה לְזָרְעָהּ הַלּוֹקֵחַ זוֹכֶה מִשּׁוּם יִשּׁוּב הָאָרֶץ וְאֵין בָּהּ דִּין בֶּן הַמֵּצַר:","בָּא לוֹקֵחַ וְנִמְלָךְ בְּבֶן הַמֵּצַר וְאָמַר לוֹ הֲרֵי פְּלוֹנִי בֶּן הַמֵּצַר שֶׁלְּךָ רוֹצֶה לִמְכֹּר לִי שָׂדֶה זוֹ אֵלֵךְ וְאֶקַּח מִמֶּנּוּ וְאָמַר לוֹ לֵךְ וְקַח לֹא בִּטֵּל זְכוּתוֹ וְיֵשׁ לְסַלֵּק אוֹתוֹ אַחַר שֶׁיִּקְנֶה אֶלָּא אִם כֵּן קָנוּ מִיָּדוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁצָּרִיךְ קִנְיָן כְּשֶׁמָּחַל לוֹ קֹדֶם שֶׁיִּקְנֶה. אֲבָל אִם מָחַל לוֹ זְכוּתוֹ אַחַר שֶׁלָּקַח כְּגוֹן שֶׁבָּא בֶּן הַמֵּצַר וְסִיֵּעַ עִמּוֹ אוֹ שָׂכַר מִמֶּנּוּ אוֹ שֶׁרָאָה אוֹתוֹ בּוֹנֶה וְסוֹתֵר כָּל שֶׁהוּא וּמִשְׁתַּמֵּשׁ וְלֹא מִחָה בּוֹ וְלֹא עִרְעֵר הֲרֵי זֶה מָחַל וְשׁוּב אֵינוֹ יָכוֹל לְסַלְּקוֹ:","הָיָה בֶּן הַמֵּצַר בִּמְדִינָה אַחֶרֶת אוֹ חוֹלֶה אוֹ קָטָן וְאַחַר זְמַן הִבְרִיא הַחוֹלֶה וְהִגְדִּיל הַקָּטָן וּבָא הַהוֹלֵךְ אֵינוֹ יָכוֹל לְסַלְּקוֹ. שֶׁאִם אַתָּה אוֹמֵר כֵּן אֵין אָדָם יָכוֹל לִמְכֹּר קַרְקָעִיתוֹ שֶׁהֲרֵי הַלּוֹקֵחַ אוֹמֵר לְאַחַר כַּמָּה שָׁנִים תֵּצֵא מִיָּדִי וְכָזֶה הוֹרוּ הַגְּאוֹנִים:","הַמּוֹכֵר שְׁוֵה מָאתַיִם בְּמָנֶה אִם לְכָל הָעָם מוֹזִיל וּמוֹכֵר נוֹתֵן לוֹ בֶּן הַמֵּצַר מֵאָה וּמְסַלְּקוֹ וְאִם אֵינוֹ מוֹזִיל לְכָל הָעָם נוֹתֵן לוֹ מָאתַיִם שֶׁהוּא שָׁוֶה שֶׁהַמּוֹכֵר נָתַן לָזֶה מַתָּנָה. לָקַח שְׁוֵה מָנֶה בְּמָאתַיִם אֵינוֹ יָכוֹל לְסַלְּקוֹ עַד שֶׁיִּתֵּן הַמָּאתַיִם. טָעַן בֶּן הַמֵּצַר שֶׁעָשׂוּ קְנוּנְיָא בֵּינֵיהֶם נִשְׁבָּע הַלּוֹקֵחַ בִּנְקִיטַת חֵפֶץ וְנוֹטֵל מָאתַיִם זוּז. וְאִם הָיָה שָׁם עֵדִים שֶׁנָּתַן מָאתַיִם וּבֶן הַמֵּצַר טוֹעֵן שֶׁאֲמָנָה הָיְתָה בֵּינוֹ וּבֵין הַמּוֹכֵר וְאֵינוֹ יוֹדֵעַ [בְּוַדַּאי] שֶׁלֹּא לָקַח מִמֶּנּוּ אֶלָּא מֵאָה הֲרֵי זֶה נוֹתֵן דָּמִים כְּמוֹ שֶׁהֵעִידוּ הָעֵדִים וְאַחַר כָּךְ מְסַלְּקוֹ וּמַשְׁבִּיעוֹ הֶסֵּת שֶׁלָּקַח בְּמָאתַיִם וְנִפְטָר:","כָּל הָרוֹצֶה לִמְכֹּר קַרְקַע וּבָאוּ שְׁנַיִם כָּל אֶחָד מֵהֶן אוֹמֵר אֲנִי אֶקַּח בְּדָמִים אֵלּוּ וְאֵין אֶחָד מֵהֶן בַּעַל הַמֵּצַר. אִם הָיָה הָאֶחָד מִיּוֹשְׁבֵי הָעִיר וְהָאֶחָד מִשְּׁכֵנֵי הַשָּׂדֶה שָׁכֵן הָעִיר קֹדֶם. שָׁכֵן וְתַלְמִיד חָכָם תַּלְמִיד חָכָם קוֹדֵם. קָרוֹב וְתַלְמִיד חָכָם תַּלְמִיד חָכָם קוֹדֵם. שָׁכֵן וְקָרוֹב הַשָּׁכֵן קוֹדֵם שֶׁגַּם זֶה בִּכְלַל הַטּוֹב וְהַיָּשָׁר הוּא. קָדַם אֶחָד וְקָנָה זָכָה וְאֵין חֲבֵרוֹ שֶׁרָאוּי לִקְדֹּם לוֹ יָכוֹל לְסַלְּקוֹ הוֹאִיל וְאֵין אֶחָד מֵהֶן בַּעַל הַמֵּצַר שֶׁלֹּא צִוּוּ חֲכָמִים בַּדָּבָר הַזֶּה אֶלָּא דֶּרֶךְ חֲסִידוּת וְנֶפֶשׁ טוֹבָה הִיא שֶׁעוֹשָׂה כָּךְ: סְלִיקוּ לְהוּ הִלְכוֹת שְׁכֵנִים"],"Mishneh Torah, Oaths 12":["אַף עַל פִּי שֶׁלּוֹקֶה הַנִּשִׁבָּע לַשָּׁוְא אוֹ לַשֶּׁקֶר וְכֵן הַנִּשְׁבָּע שְׁבוּעַת הָעֵדוּת אוֹ שְׁבוּעַת הַפִּקָּדוֹן מֵבִיא קָרְבָּן. אֵין מִתְכַּפֵּר לָהֶן עֲוֹן הַשְּׁבוּעָה כֻּלּוֹ שֶׁנֶּאֱמַר (שמות כ ז) (דברים ה יא) \"לֹא יְנַקֶּה ה'\" אֵין לָזֶה נִקָּיוֹן מִדִּין שָׁמַיִם עַד שֶׁיִּתְפָּרַע מִמֶּנּוּ עַל הַשֵּׁם הַגָּדוֹל שֶׁחִלֵּל. שֶׁנֶּאֱמַר (ויקרא יט יב) \"וְחִלַּלְתָּ אֶת שֵׁם ה' אֱלֹהֶיךָ אֲנִי ה'\". לְפִיכָךְ צָרִיךְ אָדָם לְהִזָּהֵר מֵעָוֹן זֶה יוֹתֵר מִכָּל הָעֲבֵרוֹת:","עָוֹן זֶה מִן הַחֲמוּרוֹת הוּא כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּשׁוּבָה. אַף עַל פִּי שֶׁאֵין בּוֹ לֹא כָּרֵת וְלֹא מִיתַת בֵּית דִּין יֵשׁ בּוֹ חִלּוּל הַשֵּׁם הַמְקֻדָּשׁ שֶׁהוּא גָּדוֹל מִכָּל הָעֲוֹנוֹת:","מִי שֶׁנִּשְׁבַּע בַּשָּׁמַיִם וּבָאָרֶץ וּבַשֶּׁמֶשׁ וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁאֵין כַּוָּנָתוֹ אֶלָּא לְמִי שֶׁבְּרָאָם אֵין זוֹ שְׁבוּעָה. וְכֵן הַנִּשְׁבָּע בְּנָבִיא מִן הַנְּבִיאִים אוֹ בִּכְתָב מִכִּתְבֵי הַקֹּדֶשׁ אַף עַל פִּי שֶׁאֵין כַּוָּנָתוֹ אֶלָּא לְמִי שֶׁשָּׁלַח נָבִיא זֶה אוֹ לְמִי שֶׁצִּוָּה בִּכְתָב זֶה אֵין זוֹ שְׁבוּעָה. וְאַף עַל פִּי שֶׁאֵין אֵלּוּ שְׁבוּעוֹת מְאַיְּמִין עֲלֵיהֶן וּמְלַמְּדִין אֶת הָעָם שֶׁלֹּא יִנְהֲגוּ קַלּוּת רֹאשׁ בְּכָךְ וּמַרְאִין בְּעֵינֵיהֶם שֶׁזּוֹ שְׁבוּעָה. וּפוֹתְחִין לָהֶם פֶּתַח וּמַתִּירִין לָהֶם:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר כִּתְבֵי הַקֹּדֶשׁ. אֲבָל הַנִּשְׁבָּע בַּתּוֹרָה. אִם נִשְׁבָּע בְּמַה שֶּׁכָּתוּב בָּהּ דַּעְתּוֹ עַל הַהַזְכָּרוֹת. וְאִם נִשְׁבַּע בָּהּ סְתָם דַּעְתּוֹ עַל הַגְּוִיל וְאֵין כָּאן שְׁבוּעָה. נְטָלָהּ בְּיָדוֹ וְנִשְׁבַּע בָּהּ הֲרֵי זֶה כְּמִי שֶׁנִּשְׁבַּע בְּמַה שֶּׁכָּתוּב בָּהּ וְאָסוּר:","וְהַנִּשְׁבָּע בַּתּוֹרָה סְתָם אִם תַּלְמִיד חָכָם הוּא אֵינוֹ צָרִיךְ שְׁאֵלָה לְחָכָם. וְאִם עַם הָאָרֶץ הוּא צָרִיךְ שְׁאֵלָה לְחָכָם כְּדֵי שֶׁלֹּא יִנְהַג קַלּוּת רֹאשׁ בִּשְׁבוּעוֹת:","עֶבֶד שֶׁנִּשְׁבַּע אֵין רַבּוֹ צָרִיךְ לִכְפּוֹתוֹ. וַהֲרֵי הוּא אַחַר שֶׁנִּשְׁבַּע כְּקֹדֶם שֶׁנִּשְׁבַּע. לְפִי שֶׁאֵין גּוּפוֹ קָנוּי לוֹ כְּדֵי שֶׁתָּחוּל עָלָיו שְׁבוּעָתוֹ וְנֶאֱמַר בִּשְׁבוּעוֹת (במדבר ל ג) \"לֶאְסֹר אִסָּר עַל נַפְשׁוֹ\" מִי שֶׁנַּפְשׁוֹ בִּרְשׁוּתוֹ יָצָא עֶבֶד שֶׁהוּא בִּרְשׁוּת אֲחֵרִים. וְנִמְצָא זֶה כְּמוֹ שֶׁנִּשְׁבַּע עַל נִכְסֵי אַחֵר:","קְטַנִּים שֶׁנִּשְׁבְּעוּ וְהֵן יוֹדְעִין טַעַם הַשְּׁבוּעָה אַף עַל פִּי שֶׁאֵינָן חַיָּבִין. כּוֹפִין אוֹתָן לַעֲמֹד בְּדִבְרֵיהֶן. כְּדֵי לְחַנְּכָן וּלְאַיֵּם עֲלֵיהֶם כְּדֵי שֶׁלֹּא יִנְהֲגוּ קַלּוּת רֹאשׁ בִּשְׁבוּעוֹת. וְאִם הָיָה הַדָּבָר שֶׁנִּשְׁבְּעוּ עָלָיו דָּבָר שֶׁאֵין הַקָּטָן יָכוֹל לַעֲמֹד בּוֹ אֶלָּא אִם כֵּן נִזָּק. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁיָּצוּם אוֹ שֶׁלֹּא יֹאכַל בָּשָׂר זְמַן מְרֻבֶּה. מַכֶּה אוֹתוֹ אָבִיו אוֹ רַבּוֹ וְגוֹעֵר בּוֹ וּמַרְאִין לוֹ שֶׁהֻתְּרָה שְׁבוּעָתוֹ כְּדֵי שֶׁלֹּא יִהְיֶה רָגִיל לְהָקֵל רֹאשׁ בִּשְׁבוּעוֹת:","צָרִיךְ לְהִזָּהֵר בַּקְּטַנִּים הַרְבֵּה וּלְלַמֵּד לְשׁוֹנָם דִּבְרֵי אֱמֶת בְּלֹא שְׁבוּעָה כְּדֵי שֶׁלֹּא יִהְיוּ רְגִילִים לְהִשָּׁבַע תָּמִיד כְּעַכּוּ\"ם. וְזֶה הַדָּבָר כְּמוֹ חוֹבָה עַל אֲבוֹתֵיהֶם וְעַל מְלַמְּדֵי תִּינוֹקוֹת:","הַשּׁוֹמֵעַ הַזְכָּרַת הַשֵּׁם מִפִּי חֲבֵרוֹ לַשָּׁוְא אוֹ שֶׁנִּשְׁבַּע לְפָנָיו לַשֶּׁקֶר אוֹ שֶׁבֵּרֵךְ בְּרָכָה שֶׁאֵינָהּ צְרִיכָה שֶׁהוּא עוֹבֵר מִשּׁוּם נוֹשֵׂא שֵׁם ה' לַשָּׁוְא כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בְּרָכוֹת הֲרֵי זֶה חַיָּב לְנַדּוֹתוֹ. וְאִם לֹא נִדָּהוּ הוּא בְּעַצְמוֹ יְהֵא בְּנִדּוּי. וְצָרִיךְ לְהַתִּיר אוֹתוֹ מִיָּד כְּדֵי שֶׁלֹּא יְהֵא מִכְשׁוֹל לַאֲחֵרִים שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ שֶׁנִּדּוּהוּ. וְאִם תֹּאמַר יוֹדִיעוֹ נִמְצְאוּ כָּל הָעוֹלָם בְּנִדּוּי שֶׁהֲרֵי לִמְדוּ לְשׁוֹנָם הַעֲוֵה וּשְׁבוּעָה תָּמִיד:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הַנִּשְׁבָּע הַזֶּה אוֹ הַמְבָרֵךְ לְבַטָּלָה מֵזִיד. אֲבָל אִם הָיָה שׁוֹגֵג וְלֹא יָדַע שֶׁזֶּה אָסוּר אֵינוֹ חַיָּב לְנַדּוֹתוֹ. וַאֲנִי אוֹמֵר שֶׁאָסוּר לְנַדּוֹתוֹ שֶׁלֹּא עָנַשׁ הַכָּתוּב שׁוֹגֵג אֶלָּא מַזְהִירוֹ וּמַתְרֶה בּוֹ שֶׁלֹּא יַחְזֹר:","וְלֹא שְׁבוּעָה לַשָּׁוְא בִּלְבַד הִיא שֶׁאֲסוּרָה אֶלָּא אֲפִלּוּ לְהַזְכִּיר שֵׁם מִן הַשֵּׁמוֹת הַמְיֻחָדִין לְבַטָּלָה אָסוּר וְאַף עַל פִּי שֶׁלֹּא נִשְׁבָּע. שֶׁהֲרֵי הַכָּתוּב מְצַוֶּה וְאוֹמֵר (דברים כח נח) \"לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא\". וּבִכְלַל יִרְאָתוֹ שֶׁלֹּא יַזְכִּירוֹ לְבַטָּלָה. לְפִיכָךְ אִם טָעָה הַלָּשׁוֹן וְהוֹצִיא שֵׁם לְבַטָּלָה יְמַהֵר מִיָּד וִישַׁבֵּחַ וִיפָאֵר וִיהַדֵּר לוֹ כְּדֵי שֶׁלֹּא יִזָּכֵר לְבַטָּלָה. כֵּיצַד. אָמַר ה', אוֹמֵר בָּרוּךְ הוּא לְעוֹלָם וָעֶד אוֹ גָּדוֹל הוּא וּמְהֻלָּל מְאֹד וְכַיּוֹצֵא בָּזֶה, כְּדֵי שֶׁלֹּא יְהֵא לְבַטָּלָה:","אַף עַל פִּי שֶׁמֻּתָּר לְהִשָּׁאֵל עַל הַשְּׁבוּעָה כְּמוֹ שֶׁבֵּאַרְנוּ וְאֵין בָּזֶה דֹּפִי. וּמִי שֶׁלִּבּוֹ נוֹקְפוֹ בְּדָבָר זֶה אֵינוֹ אֶלָּא שֵׁמֶץ מִינוּת. אַף עַל פִּי כֵן רָאוּי לְהִזָּהֵר בְּדָבָר זֶה. וְאֵין נִזְקָקִין לְהַתִּיר אֶלָּא מִפְּנֵי דְּבַר מִצְוָה אוֹ מִפְּנֵי צֹרֶךְ גָּדוֹל. וְטוֹבָה גְּדוֹלָה הִיא לְאָדָם שֶׁלֹּא יִשָּׁבַע כְּלָל. וְאִם עָבַר וְנִשְׁבַּע שֶׁיִּצְטַעֵר וַיַּעֲמֹד בִּשְׁבוּעָתוֹ שֶׁנֶּאֱמַר (תהילים טו ד) \"נִשְׁבַּע לְהָרַע וְלֹא יָמִר\" וְכָתוּב אַחֲרָיו (תהילים טו ה) \"עשֵֹׁה אֵלֶּה לֹא יִמּוֹט לְעוֹלָם\": סְלִיקוּ לְהוּ הִלְכוֹת שְׁבוּעוֹת בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Offerings for Those with Incomplete Atonement 4":["כְּשֶׁיִּתְרַפֵּא הַצָּרוּעַ מִצָּרַעְתּוֹ אַחַר שֶׁמְּטַהֲרִין אוֹתוֹ בְּעֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תוֹלַעַת וּשְׁתֵּי צִפֳּרִים וּמְגַלְּחִין אֶת כָּל בְּשָׂרוֹ וּמַטְבִּילִין אוֹתוֹ אַחַר כָּל זֹאת יִכָּנֵס לִירוּשָׁלַיִם וּמוֹנֶה שִׁבְעַת יָמִים וּבַיּוֹם הַשְּׁבִיעִי מְגַלֵּחַ תִּגְלַחְתּוֹ שְׁנִיָּה כַּתִּגְלַחַת הָרִאשׁוֹנָה וְטוֹבֵל וַהֲרֵי הוּא טְבוּל יוֹם וּמַעֲרִיב שִׁמְשׁוֹ וּלְמָחָר בַּשְּׁמִינִי טוֹבֵל פַּעַם שְׁנִיָּה וְאַחַר כָּךְ מַקְרִיבִין קָרְבְּנוֹתָיו. וּמִפְּנֵי מָה טוֹבֵל בַּשְּׁמִינִי אַחַר שֶׁטּוֹבֵל מֵאֶמֶשׁ. מִפְּנֵי שֶׁהָיָה רָגִיל בְּטֻמְאָה בִּימֵי חִלּוּטוֹ וְאֵינוֹ נִזְהָר מִשּׁוּם טֻמְאָה וְשֶׁמָּא נִטְמָא אַחַר שֶׁטָּבַל. לְפִיכָךְ טוֹבֵל בַּשְּׁמִינִי בְּעֶזְרַת הַנָּשִׁים בְּלִשְׁכַּת הַמְצֹרָעִים שֶׁשָּׁם אַף עַל פִּי שֶׁלֹּא הִסִּיחַ דַּעְתּוֹ:","נִתְאַחֵר וְלֹא גִּלֵּחַ בַּשְּׁבִיעִי וְגִלֵּחַ בַּשְּׁמִינִי אוֹ אַחַר כַּמָּה יָמִים בַּיּוֹם שֶׁיְּגַלֵּחַ יִטְבּל וְיַעֲרִיב שִׁמְשׁוֹ וּלְמָחָר יָבִיא קָרְבְּנוֹתָיו אַחַר שֶׁיִּטְבּל פַּעַם שְׁנִיָּה כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד עוֹשִׂין לוֹ. הַמְצֹרָע עוֹמֵד חוּץ לְעֶזְרַת יִשְׂרָאֵל כְּנֶגֶד פֶּתַח מִזְרָחִית בְּאַסְקֻפַּת שַׁעַר נִיקָנוֹר וּפָנָיו לְמַעֲרָב וְשָׁם עוֹמְדִים כָּל מְחֻסְּרֵי כַּפָּרָה בְּעֵת שֶׁמְּטַהֲרִין אוֹתָן וְשָׁם מַשְׁקִין אֶת הַסּוֹטוֹת. וְהַכֹּהֵן לוֹקֵחַ אָשָׁם שֶׁל מְצֹרָע כְּשֶׁהוּא חַי וּמְנִיפוֹ עִם לוֹג הַשֶּׁמֶן בַּמִּזְרָח כְּדֶרֶךְ כָּל הַתְּנוּפוֹת. וְאִם הֵנִיף זֶה בִּפְנֵי עַצְמוֹ וְזֶה בִּפְנֵי עַצְמוֹ יָצָא. וְאַחַר כָּךְ מֵבִיא אֶת הָאָשָׁם שֶׁל מְצֹרָע עַד הַפֶּתַח וּמַכְנִיס שְׁתֵּי יָדָיו לָעֲזָרָה וְסוֹמֵךְ עָלָיו וְשׁוֹחֲטִין אוֹתוֹ מִיָּד. וּמְקַבְּלִין שְׁנֵי כֹּהֲנִים אֶת דָּמוֹ. אֶחָד מְקַבֵּל בִּכְלִי וְזוֹרְקוֹ עַל גַּבֵּי הַמִּזְבֵּחַ וְאֶחָד בְּיָדוֹ הַיְמָנִית וּמְעָרֶה לְיָדוֹ הַשְּׂמָאלִית וּמַזֶּה בְּאֶצְבָּעוֹ הַיְמָנִית. וְאִם שִׁנָּה וְקִבֵּל בִּשְׂמֹאל תְּחִלָּה פָּסַל. הַכֹּהֵן שֶׁקִּבֵּל מִקְצָת הַדָּם בִּכְלִי מוֹלִיכוֹ וְזוֹרְקוֹ עַל הַמִּזְבֵּחַ תְּחִלָּה. וְאַחַר כָּךְ יָבוֹא הַכֹּהֵן שֶׁקִּבֵּל הַדָּם בְּכַפּוֹ אֵצֶל הַמְצֹרָע. הַכֹּהֵן מִבִּפְנִים וְהַמְצֹרָע מִבַּחוּץ. וּמַכְנִיס הַמְצֹרָע רֹאשׁוֹ וְנוֹתֵן הַכֹּהֵן מִן הַדָּם שֶׁבְּכַפּוֹ עַל תְּנוּךְ אָזְנוֹ הַיְמָנִית. וְאַחַר כָּךְ יַכְנִיס יָדוֹ הַיְמָנִית וְיִתֵּן עַל בֹּהֶן יָדוֹ וְאַחַר כָּךְ יַכְנִיס רַגְלוֹ הַיְמָנִית וְיִתֵּן עַל בֹּהֶן רַגְלוֹ וְאִם נָתַן עַל הַשְּׂמֹאל לֹא יָצָא. וְאַחַר כָּךְ יַקְרִיב חַטָּאתוֹ וְעוֹלָתוֹ. וְאַחַר שֶׁיִּתֵּן הַדָּם עַל הַבְּהוֹנוֹת נוֹטֵל הַכֹּהֵן מִלּוֹג הַשֶּׁמֶן וְיוֹצֵק לְתוֹךְ כַפּוֹ שֶׁל חֲבֵרוֹ הַשְּׂמָאלִית וְאִם יָצַק לְתוֹךְ כַּף עַצְמוֹ יָצָא. וְטוֹבֵל אֶצְבָּעוֹ הַיְמָנִית בַּשֶּׁמֶן שֶׁבְּכַפּוֹ וּמַזֶּה שֶׁבַע פְּעָמִים כְּנֶגֶד בֵּית קֹדֶשׁ הַקֳדָשִׁים עַל כָּל הֲזָיָה טְבִילַת אֶצְבַּע בְּשֶׁמֶן. וְאִם הִזָּה וְלֹא כִּוֵּן כְּנֶגֶד בֵּית קֹדֶשׁ הַקֳדָשִׁים כְּשֵׁרוֹת. וְאַחַר כָּךְ יָבוֹא אֵצֶל הַמְצֹרָע וְיִתֵּן מִן הַשֶּׁמֶן עַל מְקוֹם דַּם הָאָשָׁם בִּתְנוּךְ אֹזֶן וּבֹהֶן יָדוֹ וּבֹהֶן רַגְלוֹ. וְהַנּוֹתָר מִן הַשֶּׁמֶן שֶׁבְּכַפּוֹ יִתְּנֶנּוּ עַל רֹאשׁ הַמִּתְטַהֵר וְאִם לֹא נָתַן לֹא כִּפֵּר. וּשְׁאָר הַלּוֹג מִתְחַלֵּק לַכֹּהֲנִים:","שְׁיָרֵי הַלּוֹג אֵינוֹ נֶאֱכָל אֶלָּא בָּעֲזָרָה לְזִכְרֵי כְּהֻנָּה כִּשְׁאָר קָדְשֵׁי קָדָשִׁים שֶׁהֲרֵי הֻקַּשׁ לְאָשָׁם. וְאָסוּר לֶאֱכל מִלּוֹג הַשֶּׁמֶן עַד שֶׁיִּתֵּן מִמֶּנּוּ מַתַּן שֶׁבַע וּמַתַּן בְּהוֹנוֹת וְאִם אָכַל לוֹקֶה כְּאוֹכֵל קָדָשִׁים קֹדֶם זְרִיקָה:"],"Mishneh Torah, Offerings for Unintentional Transgressions 5":["הַבָא עַל עֶרְוָה בִּיאוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת. אַף עַל פִּי שֶׁהָיָה בֵּין בְּעִילָה וּבְעִילָה יָמִים הַרְבֵּה. הוֹאִיל וְלֹא נוֹדַע לוֹ בֵּינְתַיִם וַהֲרֵי הִיא גּוּף אֶחָד. הֲרֵי הַכּל שְׁגָגָה אַחַת וְאֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. אֲבָל אִם שָׁגַג בָּהּ וְאַחַר כָּךְ נוֹדַע לוֹ וְחָזַר וְשָׁגַג בָּהּ עַצְמָהּ וּבְעָלָהּ. וְאַחַר כָּךְ נוֹדַע לוֹ וְחָזַר וְשָׁגַג בָּהּ עַצְמָהּ וּבְעָלָהּ. חַיָּב עַל כָּל בְּעִילָה וּבְעִילָה. שֶׁהַיְדִיעוֹת מְחַלְּקוֹת הַשְּׁגָגוֹת:","הַבָּא עַל הָעֶרְוָה בִּיאוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת. וְזוֹ הַנִּבְעֶלֶת הָיְתָה לָהּ יְדִיעָה בֵּין כָּל בִּיאָה וּבִיאָה. שֶׁנִּמְצְאוּ הַבִּיאוֹת אֶצְלָהּ בְּהַעֲלָמוֹת הַרְבֵּה. הוּא מֵבִיא חַטָּאת אַחַת. וְהִיא מְבִיאָה חַטָּאת עַל כָּל בִּיאָה וּבִיאָה. הוּא הָיוּ לוֹ יְדִיעוֹת בֵּינְתַיִם וְהִיא בְּהֶעְלֵם אַחַת. הוּא מֵבִיא חַטָּאוֹת הַרְבֵּה וְהִיא מְבִיאָה חַטָּאת אַחַת:","הַבָּא עַל עֲרָיוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת. אַף עַל פִּי שֶׁכֻּלָּן מִשֵּׁם אֶחָד הוֹאִיל וְהֵן גּוּפִים מֻחְלָקִים חַיָּב עַל כָּל אַחַת וְאַחַת. כֵּיצַד. הֲרֵי שֶׁבָּעַל חֲמֵשׁ נָשָׁיו נִדּוֹת. אוֹ שֶׁבָּא עַל חֲמֵשׁ אַחְיוֹתָיו אוֹ עַל חֲמֵשׁ בְּנוֹתָיו בְּהֶעְלֵם אַחַת. חַיָּב עַל כָּל גּוּף וְגוּף. מִכָּאן אַתָּה לָמֵד שֶׁזֶּה שֶׁאָמְרוּ חֲכָמִים הַבָּא עַל הַזָּכוּר וְהֵבִיא זָכוּר עָלָיו בְּהֶעְלֵם אַחַת חַיָּב חַטָּאת אַחַת. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה אוֹתוֹ הַזָּכוּר עַצְמוֹ. אֲבָל אִם הָיָה זָכוּר אַחֵר. בֵּין שֶׁבָּא עַל שְׁנַיִם בֵּין שֶׁבָּא עַל זֶה וְהֵבִיא זֶה עָלָיו חַיָּב עַל כָּל גּוּף וְגוּף. וְהוּא הַדִּין בְּבָא עַל הַבְּהֵמָה וְהֵבִיא בְּהֵמָה עָלָיו:","הָאִשָּׁה שֶׁהֵבִיאָה עָלֶיהָ בְּהֵמוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת חַיֶּבֶת חַטָּאת עַל כָּל בְּהֵמָה וּבְהֵמָה. שֶׁהֲרֵי גּוּפִין מֻחְלָקִין וַהֲרֵי זוֹ כְּמִי שֶׁנִּבְעֲלָה לַאֲנָשִׁים הַרְבֵּה בְּהֶעְלֵם אֶחָד שֶׁהִיא חַיֶּבֶת חַטָּאת עַל כָּל אִישׁ וְאִישׁ:","הָאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם וְשָׁמְעָה שֶׁמֵּת אוֹ שֶׁבָּאוּ עֵדִים שֶׁמֵּת וְנִשֵּׂאת בֵּין עַל פִּי עַצְמָהּ בֵּין עַל פִּי בֵּית דִּין. וְנוֹדַע שֶׁבַּעְלָהּ קַיָּם. חַיֶּבֶת קָרְבָּן אֶחָד. וְאִם נִשֵּׂאת לַאֲנָשִׁים הַרְבֵּה אוֹ שֶׁזִּנְּתָה עִם אֲנָשִׁים הַרְבֵּה. חַיֶּבֶת חַטָּאת עַל כָּל אִישׁ וְאִישׁ מִפְּנֵי שֶׁהֵן גּוּפִים מֻחְלָקִין וְאַף עַל פִּי שֶׁהַכּל בִּשְׁגָגָה אַחַת. הַבָּא עַל הַנִּדָּה בִּשְׁגָגָה וְטָהֲרָה מִנִּדָּתָהּ וְטָבְלָה וְחָזְרָה וְרָאֲתָה נִדָּה וּבָא עָלֶיהָ פַּעַם שְׁנִיָּה בְּאוֹתָהּ שְׁגָגָה עַצְמָהּ. חַיָּב עַל כָּל פַּעַם וּפַעַם. אַף עַל פִּי שֶׁהוּא בְּהֶעְלֵם אַחַת וְהוּא גּוּף אֶחָד. שֶׁזְּמַן נִדּוּת זֶה חוּץ מִזְּמַן נִדּוּת הַשֵּׁנִית. וַהֲרֵי הֵן כִּשְׁתֵּי נָשִׁים נִדּוֹת:","הַבָּא עַל אִשְׁתּוֹ שֶׁלֹּא בִּשְׁעַת וֶסְתָּהּ וְרָאֲתָה דָּם בִּשְׁעַת הַתַּשְׁמִישׁ. הֲרֵי אֵלּוּ פְּטוּרִין מִקָּרְבַּן חַטָּאת מִפְּנֵי שֶׁזֶּה כְּאָנוּס הוּא וְלֹא שׁוֹגֵג. שֶׁהַשּׁוֹגֵג הָיָה לוֹ לִבְדֹּק וּלְדַקְדֵּק וְאִלּוּ בָּדַק יָפֶה יָפֶה וְדִקְדֵּק בִּשְׁאֵלוֹת לֹא הָיָה בָּא לִידֵי שְׁגָגָה וּלְפִי שֶׁלֹּא טָרַח בִּדְרִישָׁה וּבַחֲקִירָה וְאַחַר כָּךְ יַעֲשֶׂה צָרִיךְ כַּפָּרָה. אֲבָל זֶה מַה לּוֹ לַעֲשׂוֹת הֲרֵי טְהוֹרָה הָיְתָה וְשֶׁלֹּא בִּשְׁעַת וֶסְתָּהּ בָּעַל אֵין זֶה אֶלָּא אֹנֶס. וּלְפִיכָךְ בֵּין שֶׁנִּמְצָא דָּם עַל עֵד שֶׁלָּהּ בֵּין שֶׁנִּמְצָא עַל עֵד שֶׁלּוֹ פְּטוּרִין. אֲבָל אִם עָבַר וּבָא עָלֶיהָ סָמוּךְ לַוֶּסֶת וְדִמָּה שֶׁיִּבְעל וְיִפְרשׁ קֹדֶם שֶׁתִּרְאֶה דָּם וְרָאֲתָה בִּשְׁעַת הַתַּשְׁמִישׁ. חַיָּבִין בְּקָרְבָּן. שֶׁזּוֹ הִיא שְׁגָגָה. לְפִיכָךְ אִם נִמְצָא דָּם עַל עֵד שֶׁלּוֹ שְׁנֵיהֶם טְמֵאִים וְחַיָּבִין בְּקָרְבָּן. נִמְצָא עַל עֵד שֶׁלָּהּ. אִם קִנְּחָה עַצְמָהּ מִיָּד כְּשֶׁפֵּרַשׁ הַבַּעַל וְלֹא שָׁהֲתָה שְׁנֵיהֶם טְמֵאִים וְחַיָּבִין בְּקָרְבָּן. ואִם שָׁהֲתָה כְּדֵי שֶׁתּוֹשִׁיט יָדָהּ לְתַחַת הַכַּר אוֹ לְתַחַת הַכֶּסֶת וְתִטּל עֵד לִבְדֹּק בּוֹ וְאַחַר כָּךְ קִנְּחָה עַצְמָהּ שְׁנֵיהֶן טְמֵאִים בְּסָפֵק וּפְטוּרִין מִקָּרְבָּן. וְאִם שָׁהֲתָה כְּדֵי שֶׁתֵּרֵד מִן הַמִּטָּה וְתָדִיחַ אֶת פָּנֶיהָ וְאַחַר כָּךְ קִנְּחָה עַצְמָהּ וְנִמְצָא דָּם. בַּעְלָהּ טָהוֹר:","מִי שֶׁעָבַר וּבָעַל סָמוּךְ לַוֶּסֶת עַל דַּעַת שֶׁתִּקְדֹּם בִּיאָתוֹ לִרְאִיַּת הַדָּם וְהִרְגִּישָׁה הָאִשָּׁה שֶׁנִּטְמֵאת בִּשְׁעַת תַּשְׁמִישׁ וְאָמְרָה לוֹ נִטְמֵאתִי. הֲרֵי זֶה לֹא יִפְרשׁ כְּשֶׁהוּא מִתְקַשֶּׁה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי בִּיאָה. וְאִם לֹא יָדַע שֶׁאָסוּר לִפְרשׁ מִיָּד וּפֵרַשׁ כְּשֶׁהוּא מִתְקַשֶּׁה חַיָּב שְׁתֵּי חַטָּאוֹת. אַחַת עַל כְּנִיסָתוֹ שֶׁהֲרֵי בָּעַל נִדָּה וְאַחַת עַל יְצִיאָתוֹ שֶׁיְּצִיאָתוֹ הֲנָאָה לוֹ כְּבִיאָתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיָּדַע שֶׁאָסוּר לִבְעל בִּשְׁעַת הַוֶּסֶת וְדִמָּה שֶׁתִּקְדֹּם בְּעִילָתוֹ לִרְאִיָּתָהּ וְלֹא יָדַע שֶׁאָסוּר לִפְרשׁ מִיָּד. שֶׁנִּמְצְאוּ לוֹ שְׁתֵּי הַעֲלָמוֹת בִּשְׁתֵּי הַבְּעִילוֹת. אֲבָל אִם לֹא יָדַע שֶׁאָסוּר לִבְעל בִּשְׁעַת הַוֶּסֶת וְלֹא יָדַע שֶׁאָסוּר לִפְרשׁ מִן הַטֻּמְאָה מִיָּד אַף עַל פִּי שֶׁפֵּרַשׁ מִיָּד וְהוּא מִתְקַשֶּׁה אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. מִפְּנֵי שֶׁכְּנִיסָתוֹ וִיצִיאָתוֹ שֶׁהֵן כִּשְׁתֵּי בְּעִילוֹת בִּשְׁגָגָה אַחַת הֵן וּבְהֶעְלֵם אַחַת עָשָׂה הַכּל. וְהוּא הַדִּין בִּשְׁאָר הָעֲרָיוֹת שֶׁאִם שָׁגַג וּבָא עַל הָעֶרְוָה עַל דַּעַת שֶׁהִיא מֻתֶּרֶת וְנוֹדַע לוֹ שֶׁהִיא עֶרְוָה וְהוּא בְּתוֹךְ הַתַּשְׁמִישׁ. לֹא יִפְרשׁ מִיָּד שֶׁיְּצִיאָתוֹ הֲנָאָה לוֹ כְּבִיאָתוֹ. וְאִם לֹא יָדַע שֶׁאָסוּר לִפְרשׁ מִיָּד וּפֵרַשׁ וְהוּא מִתְקַשֶּׁה אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. שֶׁהַכּל שְׁגָגָה אַחַת הִיא:"],"Mishneh Torah, One Who Injures a Person or Property 8":["הַמּוֹסֵר מָמוֹן חֲבֵרוֹ בִּידֵי אַנָּס חַיָּב לְשַׁלֵּם מִן הַיָּפֶה שֶׁבִּנְכָסָיו. וְאִם מֵת גּוֹבִין מִיּוֹרְשָׁיו כִּשְׁאָר כָּל הַמַּזִּיקִין. בֵּין שֶׁהָיָה הָאַנָּס עַכּוּ\"ם בֵּין שֶׁהָיָה יִשְׂרָאֵל הֲרֵי זֶה הַמּוֹסֵר חַיָּב לְשַׁלֵּם כָּל מַה שֶּׁלָּקַח הָאַנָּס. אַף עַל פִּי שֶׁלֹּא נָשָׂא הַמּוֹסֵר וְלֹא נָתַן בְּיָדוֹ אֶלָּא הִרְגִּיל בִּלְבַד:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֶרְאָה הַמּוֹסֵר מֵעַצְמוֹ. אֲבָל אִם אֲנָסוּהוּ עוֹבְדֵי כּוֹכָבִים אוֹ יִשְׂרָאֵל אַנָּס לְהַרְאוֹת וְהֶרְאָה הֲרֵי זֶה פָּטוּר מִן הַתַּשְׁלוּמִין. וְאִם נָשָׂא וְנָתַן בַּיָּד אַף עַל פִּי שֶׁהוּא אָנוּס חַיָּב לְשַׁלֵּם. שֶׁהַמַּצִּיל עַצְמוֹ בְּמָמוֹן חֲבֵרוֹ חַיָּב לְשַׁלֵּם:","כֵּיצַד. הֲרֵי שֶׁגָּזַר הַמֶּלֶךְ לְהָבִיא לוֹ יַיִן אוֹ תֶּבֶן וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. וְעָמַד מוֹסֵר וְאָמַר הֲרֵי יֵשׁ לִפְלוֹנִי אוֹצַר יַיִן אוֹ תֶּבֶן בְּמָקוֹם פְּלוֹנִי וְהָלְכוּ וּלְקָחוּהָ. חַיָּב לְשַׁלֵּם. אֲנָסוֹ הַמֶּלֶךְ לְמוֹסֵר זֶה עַד שֶׁיַּרְאֶה לוֹ אוֹצְרוֹת יַיִן אוֹ תֶּבֶן אוֹ עַד שֶׁיַּרְאֶה לוֹ מָמוֹן חֲבֵרוֹ שֶׁהוּא בּוֹרֵחַ מִלְּפָנָיו וְהֶרְאָה לוֹ מִפְּנֵי הָאוֹנֵס הֲרֵי זֶה פָּטוּר. שֶׁאִם לֹא יַרְאֶה לוֹ יַכֵּהוּ אוֹ יְמִיתֵהוּ:","נָשָׂא מָמוֹן חֲבֵרוֹ בְּיָדוֹ וּנְתָנוֹ לְאַנָּס חַיָּב לְשַׁלֵּם מִכָּל מָקוֹם. אַף עַל פִּי שֶׁהַמֶּלֶךְ אֲנָסוֹ לְהָבִיא. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאִם אֲנָסוֹ לְהָבִיא וְהֵבִיא חַיָּב בְּשֶׁלֹּא הִגִּיעַ הַמָּמוֹן לִרְשׁוּת הָאַנָּס. אֲבָל אַנָּס שֶׁאָנַס יִשְׂרָאֵל עַד שֶׁהֶרְאָהוּ וְעָמַד הָאַנָּס עַל הַמָּמוֹן וְנַעֲשָׂה בִּרְשׁוּתוֹ וְאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהוֹלִיכוֹ לוֹ לְמָקוֹם אַחֵר. וַאֲפִלּוּ הוֹלִיכוֹ זֶה הַמּוֹסֵר שֶׁהֶרְאָהוּ. הֲרֵי זֶה פָּטוּר מִלְּשַׁלֵּם. שֶׁכֵּיוָן שֶׁעָמַד הָאַנָּס בְּצַד הָאוֹצָר כְּבָר אָבַד כָּל מַה שֶּׁיֵּשׁ בּוֹ וּכְאִלּוּ נִשְׂרַף:","בַּעֲלֵי דִּין שֶׁהָיְתָה בֵּינֵיהֶם מְרִיבָה עַל הַקַּרְקַע אוֹ עַל מִטַּלְטְלִין. זֶה אוֹמֵר שֶׁלִּי וְזֶה אוֹמֵר שֶׁלִּי. וְעָמַד אֶחָד מֵהֶן וּמְסָרָהּ בְּיַד עוֹבֵד כּוֹכָבִים. מְנַדִּין אוֹתוֹ שֶׁיַּחְזִיר הַדָּבָר לִכְמוֹ שֶׁהָיָה וִיסַלֵּק יַד אַנָּס מִבֵּינֵיהֶם וְיַעֲשׂוּ דִּין בְּיִשְׂרָאֵל:","מִי שֶׁנִּתְפַּשׂ עַל חֲבֵרוֹ וְלָקְחוּ עוֹבְדֵי כּוֹכָבִים מָמוֹן מִמֶּנּוּ בִּגְלַל חֲבֵרוֹ. אֵין חֲבֵרוֹ חַיָּב לְשַׁלֵּם. אֵין לְךָ מִי שֶׁנִּתְפָּשׂ עַל חֲבֵרוֹ וְיִהְיֶה חֲבֵרוֹ חַיָּב לְשַׁלֵּם חוּץ מִן הַנִּתְפָּשׂ מִפְּנֵי הַמַּס הַקָּצוּב עַל כָּל אִישׁ וְאִישׁ בְּכָל שָׁנָה אוֹ הַנִּתְפַּשׂ עַל הַתְּשׁוּרָה שֶׁנּוֹתֵן כָּל אִישׁ וְאִישׁ לְמֶלֶךְ בְּעָבְרוֹ עֲלֵיהֶם הוּא אוֹ חֵילוֹתָיו הֲרֵי זֶה חַיָּב לְשַׁלֵּם לוֹ. וְהוּא שֶׁיִּקְחוּ מִמֶּנּוּ בְּפֵרוּשׁ בִּגְלַל פְּלוֹנִי בִּפְנֵי עֵדִים:","מִי שֶׁיֵּשׁ עָלָיו עֵדִים שֶׁמָּסַר מָמוֹן חֲבֵרוֹ. כְּגוֹן שֶׁהֶרְאָה מֵעַצְמוֹ אוֹ שֶׁנֶּאֱנַס וְנָשָׂא וְנָתַן. וְלֹא יָדְעוּ הָעֵדִים כַּמָּה הִפְסִידוֹ בִּמְסִירָתוֹ וְהַנִּמְסָר אוֹמֵר כָּךְ וְכָךְ הִפְסִידַנִי. וְהַמּוֹסֵר כּוֹפֵר בְּמַה שֶּׁטָּעֲנוֹ. אִם תָּפַשׂ הַנִּמְסָר אֵין מוֹצִיאִין מִיָּדוֹ אֶלָּא נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְזוֹכֶה בְּמַה שֶּׁתָּפַשׂ. וְאִם לֹא תָּפַשׂ אֵין מוֹצִיאִין מִן הַמּוֹסֵר אֶלָּא בִּרְאָיָה בְּרוּרָה:","אֵין מַשְׁבִּיעִין אֶת הַמּוֹסֵר שֶׁהֶרְאָה מֵעַצְמוֹ לֹא שְׁבוּעָה חֲמוּרָה וְלֹא שְׁבוּעַת הֶסֵּת. מִפְּנֵי שֶׁהוּא רָשָׁע וְאֵין לְךָ פָּסוּל יָתֵר מִזֶּה. אֲבָל הַמּוֹסֵר שֶׁאֲנָסוּהוּ לְהַרְאוֹת אוֹ לְהָבִיא וְנָשָׂא וְנָתַן בַּיָּד. אַף עַל פִּי שֶׁהוּא חַיָּב לְשַׁלֵּם אֵינוֹ רָשָׁע אֶלָּא בֶּן תַּשְׁלוּמִין הוּא בִּלְבַד וּמַשְׁבִּיעִין אוֹתוֹ כִּשְׁאָר הַכְּשֵׁרִין:","אָסוּר לִמְסֹר הָאָדָם בְּיַד עַכּוּ\"ם בֵּין בְּגוּפוֹ בֵּין בְּמָמוֹנוֹ. וַאֲפִלּוּ הָיָה רָשָׁע וּבַעַל עֲבֵרוֹת וַאֲפִלּוּ הָיָה מֵצֵר לוֹ וּמְצַעֲרוֹ. וְכָל הַמּוֹסְרוֹ בְּיַד עַכּוּ\"ם בֵּין בְּגוּפוֹ בֵּין בְּמָמוֹנוֹ אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא:","מֻתָּר לַהֲרֹג הַמּוֹסֵר בְּכָל מָקוֹם וַאֲפִלּוּ בַּזְּמַן הַזֶּה שֶׁאֵין דָּנִין דִּינֵי נְפָשׁוֹת. וּמֻתָּר לְהָרְגוֹ קֹדֶם שֶׁיִּמְסֹר אֶלָּא כְּשֶׁאָמַר הֲרֵינִי מוֹסֵר פְּלוֹנִי בְּגוּפוֹ אוֹ בְּמָמוֹנוֹ. וַאֲפִלּוּ מָמוֹן קַל הִתִּיר עַצְמוֹ לְמִיתָה. וּמַתְרִין לוֹ וְאוֹמְרִין לוֹ אַל תִּמְסֹר. אִם הֵעֵז פָּנָיו וְאָמַר לֹא כִּי אֶלָּא אֶמְסְרֶנּוּ מִצְוָה לְהָרְגוֹ וְכָל הַקּוֹדֵם לְהָרְגוֹ זָכָה:","עָשָׂה הַמּוֹסֵר אֲשֶׁר זָמַם וּמָסַר. יֵרָאֶה לִי שֶׁאָסוּר לְהָרְגוֹ אֶלָּא אִם כֵּן הֻחְזַק לִמְסֹר הֲרֵי זֶה יֵעָנֵשׁ שֶׁמָּא יִמְסֹר אֲחֵרִים. וּמַעֲשִׂים בְּכָל זְמַן בְּעָרֵי הַמַּעֲרָב לַעֲנשׁ הַמּוֹסְרִים שֶׁהֻחְזְקוּ לִמְסֹר מָמוֹן בְּנֵי אָדָם וְלִמְסֹר הַמּוֹסְרִים בְּיַד הָעַכּוּ\"ם לְעָנְשָׁם וּלְהַכּוֹתָם וּלְאָסְרָם כְּפִי רִשְׁעָם. וְכֵן כָּל הַמֵּצֵר לַצִּבּוּר וּמְצַעֲרָן מֻתָּר לְמָסְרוֹ בְּיַד עַכּוּ\"ם לְהַכּוֹתוֹ וּלְאָסְרוֹ וּלְקָנְסוֹ. אֲבָל מִפְּנֵי צַעַר יָחִיד אָסוּר לְאָסְרוֹ. וְאָסוּר לְאַבֵּד מָמוֹנוֹ שֶׁל מוֹסֵר וְאַף עַל פִּי שֶׁמֻּתָּר לְעָנְשׁוֹ שֶׁהֲרֵי מָמוֹנוֹ לְיוֹרְשָׁיו:","רוֹדֵף שֶׁהָיָה רוֹדֵף אַחַר חֲבֵרוֹ לְהָרְגוֹ אוֹ לִדְבַר עֲבֵרָה וְשָׁבַר אֶת הַכֵּלִים בֵּין שֶׁל נִרְדָּף בֵּין שֶׁל כָּל אָדָם. פָּטוּר מִן הַתַּשְׁלוּמִין מִפְּנֵי שֶׁהוּא מִתְחַיֵּב בְּנַפְשׁוֹ. שֶׁכֵּיוָן שֶׁרָדַף הִתִּיר עַצְמוֹ לְמִיתָה:","נִרְדָּף שֶׁשָּׁבַר כֵּלִים שֶׁל רוֹדֵף פָּטוּר. לֹא יְהֵא מָמוֹנוֹ חָבִיב מִגּוּפוֹ. וְאִם שָׁבַר כֵּלִים אֲחֵרִים חַיָּב. שֶׁהַמַּצִּיל עַצְמוֹ בְּמָמוֹן חֲבֵרוֹ חַיָּב:","מִי שֶׁרָדַף אַחַר הָרוֹדֵף לְהוֹשִׁיעַ הַנִּרְדָּף וְשָׁבַר אֶת הַכֵּלִים בֵּין שֶׁל רוֹדֵף בֵּין שֶׁל כָּל אָדָם פָּטוּר. וְלֹא מִן הַדִּין אֶלָּא תַּקָּנָה הִיא שֶׁלֹּא יִמָּנַע מִלְּהַצִּיל אוֹ יִתְמַהְמֵהַּ וִיעַיֵּן בְּעֵת שֶׁיִּרְדֹּף:","סְפִינָה שֶׁחִשְּׁבָה לְהִשָּׁבֵר מִכֹּבֶד הַמַּשּׂוֹי. וְעָמַד אֶחָד מֵהֶן וְהֵקֵל מִמַּשָּׂאָהּ וְהִשְׁלִיךְ בַּיָּם פָּטוּר. שֶׁהַמַּשָּׂא שֶׁבָּהּ כְּמוֹ רוֹדֵף אַחֲרֵיהֶם לְהָרְגָם וּמִצְוָה רַבָּה עָשָׂה שֶׁהִשְׁלִיךְ וְהוֹשִׁיעָם: סְלִיקוּ לְהוּ הִלְכוֹת חוֹבֵל וּמַזִּיק בְּסַ\"ד"],"Mishneh Torah, Other Sources of Defilement 2":["בְּהֵמָה אוֹ חַיָּה טְמֵאָה שֶׁנִּשְׁחֲטָה אֵינָהּ מְטַמְּאָה מִשּׁוּם נְבֵלָה כָּל זְמַן שֶׁהִיא מְפַרְכֶּסֶת עַד שֶׁיַּתִּיז אֶת רֹאשָׁהּ וַהֲרֵי הִיא כָּאֳכָלִין טְמֵאִין. נְחָרָהּ וַהֲרֵי הִיא מְפַרְכֶּסֶת אֵין בָּהּ אֲפִלּוּ טֻמְאַת אֳכָלִין כָּל זְמַן שֶׁהִיא מְפַרְכֶּסֶת. וְאֵיבָר הַפּוֹרֵשׁ מִן הַמְפַרְכֶּסֶת אָסוּר לִבְנֵי נֹחַ כְּפוֹרֵשׁ מִן הַחַי וּבָשָׂר הַפּוֹרֵשׁ מִמֶּנָּה כְּפוֹרֵשׁ מִן הַחַי. וְכֵן טְהוֹרָה שֶׁנִּפְסְלָה בִּשְׁחִיטָתָהּ וַעֲדַיִן הִיא מְפַרְכֶּסֶת אוֹ שָׁחַט בָּהּ אֶחָד אוֹ רֹב אֶחָד אֵין לָהּ טֻמְאָה כְּלָל עַד שֶׁתָּמוּת. חָלַק בְּהֵמָה לִשְׁנַיִם אוֹ שֶׁנִּטְּלָה יָרֵךְ וְחָלָל שֶׁלָּהּ הֲרֵי זוֹ נְבֵלָה וּמְטַמְּאָהּ בְּמַשָּׂא וּבְמַגָּע אַף עַל פִּי שֶׁהִיא עֲדַיִן בַּחַיִּים. וְכֵן אִם קְרָעָהּ מִגַּבָּהּ אוֹ שֶׁנִּשְׁבְּרָה מִפְרֶקֶת וְרֹב בָּשָׂר עַמָּהּ הֲרֵי זוֹ כִּנְבֵלָה לְכָל דָּבָר:","בְּהֵמָה שֶׁמֵּת עֻבָּרָהּ בְּתוֹךְ מֵעֶיהָ וְהוֹשִׁיט הָרוֹעֶה אֶת יָדוֹ וְנָגַע בּוֹ בֵּין בִּבְהֵמָה טְמֵאָה בֵּין בִּטְהוֹרָה הֲרֵי זֶה הַנּוֹגֵעַ טָהוֹר עַד שֶׁיֵּצֵא הַנֵּפֶל לַאֲוִיר הָעוֹלָם:","בָּשָׂר הַפּוֹרֵשׁ מִבְּהֵמָה וְחַיָּה כְּשֶׁהֵן חַיִּין בֵּין טְהוֹרִין בֵּין טְמֵאִין טָהוֹר וְאֵינוֹ מְטַמֵּא כִּנְבֵלָה. אֲבָל אֵיבָר מִן הַחַי הַפּוֹרֵשׁ מֵהֶן מְטַמֵּא כִּנְבֵלָה. אֶחָד אֵיבָר מִן הַחַי הַפּוֹרֵשׁ מִן הַבְּהֵמָה עַצְמָהּ אוֹ אֵיבָר הַפּוֹרֵשׁ מִן הַשָּׁלִיל שֶׁבְּבִטְנָהּ. וְהָאֵיבָרִים אֵין לָהֶן שִׁעוּר אֲפִלּוּ הָיָה כִּשְׂעוֹרָה אוֹ פָּחוֹת מְטַמֵּא וְהוּא שֶׁיִּהְיֶה הָאֵיבָר כִּבְרִיָּתוֹ בָּשָׂר וְגִידִין וַעֲצָמוֹת וְיִהְיֶה עָלָיו בָּשָׂר כְּדֵי לְהַעֲלוֹת אֲרוּכָה. הָיָה הַבָּשָׂר פָּחוֹת מֵהַעֲלוֹת אֲרוּכָה בְּחַי אוֹ חָסַר עַצְמוֹ טָהוֹר:","הַכֻּלְיָא וְהַלָּשׁוֹן וְהַשָּׂפָה וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהֵן אֵיבָרִים וְאֵין עוֹשִׂין חֲלִיפִין הוֹאִיל וְאֵין בָּהֶם עֶצֶם הֲרֵי הֵן כְּבָשָׂר:","הַבָּשָׂר אוֹ הָאֵיבָר הַמְדֻלְדָּלִין בִּבְהֵמָה אוֹ חַיָּה שֶׁאֵינָן יְכוֹלִין לִחְיוֹת וּלְהַדְבִּיק בִּשְׁאָר הַגּוּף אֵינָן מְטַמְּאִין כִּנְבֵלָה כָּל זְמַן שֶׁהַבְּהֵמָה בַּחַיִּים וַהֲרֵי הֵן כִּשְׁאָר אֳכָלִין אִם הֻכְשְׁרוּ מְקַבְּלִין טֻמְאָה בִּמְקוֹמָהּ. נִשְׁחֲטָה הַבְּהֵמָה הֻכְשְׁרוּ בִּשְׁחִיטָה וְאֵינָן מְטַמְּאִין כִּנְבֵלָה שֶׁאֵין הַשְּׁחִיטָה עוֹשָׂה אוֹתָן כְּמוֹ שֶׁפֵּרְשׁוּ מֵחַיִּים. אֲבָל אִם מֵתָה הַבְּהֵמָה הַבָּשָׂר שֶׁהָיָה מְדֻלְדָּל בָּהּ צָרִיךְ הֶכְשֵׁר. וְהָאֵיבָר מְטַמֵּא מִשּׁוּם אֵיבָר מִן הַחַי וְאֵינוֹ מְטַמֵּא מִשּׁוּם אֵיבָר מִן הַנְּבֵלָה. וּמַה בֵּין אֵיבָר מִן הַחַי לְאֵיבָר מִן הַנְּבֵלָה. שֶׁהַבָּשָׂר הַפּוֹרֵשׁ מֵאֵיבָר מִן הַחַי טָהוֹר. וְהַבָּשָׂר הַפּוֹרֵשׁ מֵאֵיבָר מִן הַנְּבֵלָה מְטַמֵּא בִּכְזַיִת בְּמַגָּע וּבְמַשָּׂא. וְזֶה וְזֶה שָׁוִין לְשִׁעוּר:","טְרֵפָה שֶׁנִּשְׁחֲטָה שְׁחִיטָה כְּשֵׁרָה אַף עַל פִּי שֶׁהִיא אֲסוּרָה בַּאֲכִילָה הֲרֵי הִיא טְהוֹרָה. וְכֵן הַשּׁוֹחֵט אֶת הַבְּהֵמָה וּמָצָא בָּהּ עֵבָּר מֵת שְׁחִיטַת אִמּוֹ מְטַהַרְתּוֹ מִידֵי נְבֵלָה. מָצָא בָּהּ בֶּן שְׁמוֹנָה חַי נִטְרַף. אַף עַל פִּי שֶׁנִּשְׁחַט אַחַר שֶׁנִּטְרַף אֵין שְׁחִיטָתוֹ מְטַהֲרַתּוּ מִיָּדִי נְבֵלָה לְפִי שֶׁאֵין לְמִינוֹ שְׁחִיטָה. לְפִיכָךְ וְלַד בְּהֵמָה שֶׁלֹּא שָׁהָה שִׁבְעָה יָמִים גְּמוּרִין אִם שְׁחָטוֹ בְּתוֹךְ שִׁבְעָה אֵין שְׁחִיטָתוֹ מְטַהֲרַתּוּ מִידֵי נְבֵלָה מִפְּנֵי שֶׁהוּא כְּנֵפֶל:","הַשּׁוֹחֵט אֶת הַבְּהֵמָה וּמָצָא בָּהּ בֶּן תִּשְׁעָה חַי קֹדֶם שֶׁיַּהֲלֹךְ עַל הַקַּרְקַע אַף עַל פִּי שֶׁאֵין צָרִיךְ שְׁחִיטָה כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁהֲרֵי שְׁחִיטַת אִמּוֹ מְטַהֲרַתּוּ אִם נִטְמֵאת אִמּוֹ לֹא נִטְמָא הוּא. וְאִם נִתְנַבְּלָה אִמּוֹ הֲרֵי הוּא טָהוֹר שֶׁאֵין הַחַי מִתְטַמֵּא לֹא טֻמְאַת אֳכָלִין וְלֹא טֻמְאַת נְבֵלוֹת וְאַף עַל פִּי שֶׁהוּא כְּאֵיבָר מֵאֵיבָרֶיהָ. וְאִם מֵת קֹדֶם שֶׁיַּפְרִיס עַל גַּבֵּי קַרְקַע הֲרֵי הוּא טָהוֹר שֶׁשְּׁחִיטַת אִמּוֹ טִהֲרַתּוּ:","טְרֵפָה שֶׁנִּשְׁחֲטָה אַף עַל פִּי שֶׁהִיא טְהוֹרָה מִן הַתּוֹרָה אִם נָגַע בָּהּ הֶקְדֵּשׁ נִטְמָא מִדִּבְרֵי סוֹפְרִים וְזוֹ מַעֲלָה יְתֵרָה שֶׁעָשׂוּ בְּקֹדֶשׁ:","בְּהֵמָה הַמַּקְשָׁה לֵילֵד וְהוֹצִיא הָעֻבָּר אֶת יָדוֹ וַחֲתָכָהּ וְאַחַר כָּךְ שָׁחַט אֶת אִמּוֹ הָאֵיבָר שֶׁנֶּחְתַּךְ נְבֵלָה וּשְׁאָר בְּשַׂר הָעֻבָּר טָהוֹר. שָׁחַט אֶת אִמּוֹ וְאַחַר כָּךְ חֲתָכָהּ הָאֵיבָר כִּטְרֵפָה שֶׁנִּשְׁחֲטָה וּשְׁאָר בְּשַׂר הָעֻבָּר מַגַּע טְרֵפָה שְׁחוּטָה שֶׁהִיא מְטַמְּאָה אֶת הַקֹּדֶשׁ אֲבָל לֹא אֶת הַתְּרוּמָה. הוֹצִיא הָעֻבָּר אֶת יָדוֹ בֵּין שְׁחִיטַת סִימָן לִשְׁחִיטַת סִימָן וַחֲתָכוֹ מִצְטָרֵף שְׁחִיטַת סִימָן לְסִימָן לְטַהֵר הָאֵיבָר מִידֵי נְבֵלָה:","שְׁחִיטַת עַכּוּ\"ם נְבֵלָה וּמְטַמְּאָה בְּמַשָּׂא וַאֲפִלּוּ יִשְׂרָאֵל עוֹמֵד עַל גַּבָּיו. וְאִם שָׁחַט בְּסַכִּין יָפָה שְׁחִיטָה כָּרָאוּי אֶחָד הָעַכּוּ\"ם וְאֶחָד הַכּוּתִי אוֹ גֵּר תּוֹשָׁב שְׁחִיטָתָן נְבֵלָה. וְקָרוֹב בְּעֵינַי שֶׁאַף זֶה מִדִּבְרֵי סוֹפְרִים שֶׁהֲרֵי טֻמְאַת עֲבוֹדָה זָרָה וְטֻמְאַת תִּקְרָבְתָּהּ מִדִּבְרֵיהֶם כְּמוֹ שֶׁיִּתְבָּאֵר. וּבִגְלַל עֲבוֹדָה זָרָה נִתְרַחֲקוּ הַכּוּתִים וְנֶאֶסְרָה שְׁחִיטָתָן. וְאִם תֹּאמַר וַהֲלֹא הִיא אֲסוּרָה בַּאֲכִילָה דִּין תּוֹרָה. לֹא כָּל הָאָסוּר בַּאֲכִילָה מְטַמֵּא שֶׁהֲרֵי הַטְּרֵפָה אֲסוּרָה וּטְהוֹרָה. וְאִי אֶפְשָׁר לְחַיֵּב כָּרֵת עַל טֻמְאָה זוֹ עַל בִּיאַת מִקְדָּשׁ וַאֲכִילַת קָדָשָׁיו אֶלָּא בִּרְאָיָה בְּרוּרָה:","קוּלְיַית הַנְּבֵלָה הַנּוֹגֵעַ בָּהּ אוֹ נוֹשְׂאָהּ טָהוֹר שֶׁכָּל דָּבָר מִן הַנְּבֵלָה שֶׁאֵינוֹ מְטַמֵּא בְּמַגָּע אֵינוֹ מְטַמֵּא בְּמַשָּׂא. נִקְּבָה כָּל שֶׁהוּא הַנּוֹגֵעַ בָּהּ אוֹ נוֹשְׂאָהּ טָמֵא. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַמֹּחַ שֶׁבָּהּ מִתְקַשְׁקֵשׁ שֶׁהֲרֵי אֵינָהּ מַעֲלָה אֲרוּכָה. אֲבָל אִם הָיָה עוֹמֵד בִּמְקוֹמוֹ אִם יֵשׁ בּוֹ כְּדֵי לְהַעֲלוֹת אֲרוּכָה לָעֶצֶם מִבַּחוּץ הֲרֵי זוֹ מְטַמְּאָה בְּמַגָּע וּבְמַשָּׂא כְּכָל הָאֵיבָרִים. וּכְבָר פֵּרַשְׁנוּ שֶׁהַקּוּלִית הִיא הָעֶצֶם הַסָּתוּם מִכָּל צְדָדָיו:","קוּלִית שֶׁחָשַׁב עָלֶיהָ לְנַקְּבָהּ וַעֲדַיִן לֹא נִקְּבָהּ הֲרֵי הַנּוֹגֵעַ בָּהּ סָפֵק טָמֵא. שֶׁהֲרֵי יֵשׁ בַּדָּבָר סָפֵק אִי מְחֻסַּר נְקִיבָה כִּמְחֻסַּר מַעֲשֶׂה אוֹ לֹא:"],"Mishneh Torah, Overview of Mishneh Torah Contents 12":["ספר קניין","הלכותיו חמש, וזה הוא סידורן: הלכות מכירה, הלכות זכייה ומתנה, הלכות שכנים, הלכות שלוחין ושותפין, הלכות עבדים.","הלכות מכירה. יש בכללן חמש מצוות – אחת מצות עשה, וארבע מצוות לא תעשה; וזה הוא פרטן: (א) דין מקח וממכר; (ב) שלא יונה במקח וממכר; (ג) שלא יונה בדברים; (ד) שלא יונה גר צדק בממונו; (ה) שלא יונהו בדברים.","הלכות זכייה ומתנה. עניין אלו ההלכות לידע דין זוכה מן ההפקר היאך יקנה ובמה יקנה, ודין נותן מתנה ומקבל ואיזו מתנה חוזרת ואיזו אינה חוזרת.","הלכות שכנים. עניין אלו ההלכות לידע דין חילוק הקרקעות בין השותפין, והרחקת נזקי כל אחד מהן משכנו ומבעל המצר שלו, ודין בעל המצר.","הלכות שלוחין ושותפין. עניין אלו ההלכות לידע דין שלוחו של אדם ושותפו, ומשפטיהן במקחן וממכרן ובהפסדן ושכרן.","הלכות עבדים. יש בכללן שלוש עשרה מצוות – חמש מצוות עשה, ושמונה מצוות לא תעשה; וזה הוא פרטן: (א) דין קניין עבד עברי; (ב) שלא יימכר ממכרת עבד; (ג) שלא יעבידנו בפרך; (ד) שלא נניח גר תושב לרדות בו בפרך; (ה) שלא נעבוד בו עבודת עבד; (ו) להעניק לו בצאתו חופשי; (ז) שלא ייצא ריקם; (ח) לפדות אמה עברייה; (ט) לייעדה; (י) שלא תימכר; (יא) לעבוד בעבד כנעני לעולם, אלא אם הפיל לו אדוניו אחד מראשי אבריו; (יב) שלא להסגיר עבד שברח מחוצה לארץ לארץ ישראל; (יג) שלא להונות עבד זה הניצול אלינו.","נמצאו כל המצוות הנכללות בספר זה, שמונה עשרה – שש מהן מצוות עשה, ושתים עשרה מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 10":["שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ מָנֶה לִפְלוֹנִי וּמֵת. יִתְּנוּ לְאַחַר מִיתָה. שֶׁדִּבְרֵי שְׁכִיב מֵרַע כִּכְתוּבִין וְכִמְסוּרִין דָּמוּ. וְאֵין חוֹשְׁשִׁין שֶׁמָּא עַל מָנֶה שֶׁיֵּשׁ לוֹ קָבוּר הוּא אוֹמֵר:","וְכֵן שְׁכִיב מֵרַע שֶׁאָמַר הַלְוָאָה אוֹ פִּקָּדוֹן שֶׁיֵּשׁ לִי בְּיַד פְּלוֹנִי תְּנוּ אוֹתָהּ לִפְלוֹנִי דְּבָרָיו קַיָּמִין וְאֵין צָרִיךְ לְמַעֲמַד שְׁלָשְׁתָּן. וְכֵן אִם אָמַר תְּנוּ שְׁטַר פְּלוֹנִי לִפְלוֹנִי זָכָה בְּמַה שֶּׁיֵּשׁ בַּשְּׁטָר. וּכְאִלּוּ כָּתַב וּמָסַר אַף עַל פִּי שֶׁלֹּא מָשַׁךְ הַשְּׁטָר. וְאֵין הַיּוֹרֵשׁ יָכוֹל לִמְחל שְׁטָר זֶה שֶׁנָּתַן בְּמַתְּנַת שְׁכִיב מֵרַע. וּמִפְּנֵי מָה הַמּוֹכֵר אוֹ נוֹתֵן שְׁטַר חוֹב לַחֲבֵרוֹ וְחָזַר וּמְחָלוֹ הַיּוֹרֵשׁ מָחוּל וּשְׁכִיב מֵרַע שֶׁנָּתַן שְׁטַר חוֹב אֵין הַיּוֹרֵשׁ יָכוֹל לִמְחל. מִפְּנֵי שֶׁקִּנְיַן הָרְאָיָה בִּשְׁטָר מִדִּבְרֵיהֶם לְפִיכָךְ הַיּוֹרֵשׁ עֲדַיִן זֶה הַשְּׁטָר שֶׁלּוֹ הוּא מִן הַתּוֹרָה וּמוֹחֲלוֹ. וּמַתְּנַת שְׁכִיב מֵרַע אַף עַל פִּי שֶׁהִיא מִדִּבְרֵיהֶם עָשׂוּ אוֹתָהּ כְּשֶׁל תּוֹרָה. וּכְאִלּוּ קָנָה מָמוֹן שֶׁבַּשְּׁטָר מִן הַתּוֹרָה וְהִגִּיעַ לְיָדוֹ וְלֹא נִשְׁאַר לַיּוֹרֵשׁ בּוֹ קִנְיָן. וּלְפִיכָךְ אֵינוֹ מוֹחֵל:","שְׁכִיב מֵרַע שֶׁאָמַר מָנֶה לִפְלוֹנִי בְּיָדִי. אִם אָמַר תְּנוּ נוֹתְנִין. לֹא אָמַר תְּנוּ אֵין נוֹתְנִין. שֶׁמָּא לֹא אָמַר מָנֶה יֵשׁ לִפְלוֹנִי בְּיָדִי אֶלָּא כְּדֵי שֶׁלֹּא יֹאמְרוּ עַל יוֹרְשָׁיו שֶׁיֵּשׁ לָהֶן מָמוֹן:","לְפִיכָךְ אִם אָמַר זֶה דֶּרֶךְ הוֹדָאָה וְלֹא הָיָה שָׁם חֲשַׁשׁ הַעֲרָמָה. נוֹתְנִין אַף עַל פִּי שֶׁלֹּא אָמַר תְּנוּ:","כַּיּוֹצֵא בּוֹ רָאוּ אֶת אֲבִיהֶם שֶׁהִטְמִין מָעוֹת בְּשִׁדָּה תֵּבָה וּמִגְדָּל וְאָמַר שֶׁל פְּלוֹנִי הֵן. שֶׁל מַעֲשֵׂר שֵׁנִי הֵן. אִם כְּמוֹסֵר דְּבָרָיו קַיָּמִין. אִם כְּמַעֲרִים לֹא אָמַר כְּלוּם:","וְכֵן אִם בָּא אֶחָד וְאָמַר לָהֶם אֲנִי רָאִיתִי אֶת אֲבִיכֶן שֶׁהִטְמִין מָעוֹת בְּשִׁדָּה תֵּבָה וּמִגְדָּל וְאָמַר שֶׁל פְּלוֹנִי הֵם. שֶׁל מַעֲשֵׂר הֵן. אִם הָיוּ טְמוּנִין בַּבַּיִת לֹא אָמַר כְּלוּם. בַּשָּׂדֶה דְּבָרָיו קַיָּמִין. כְּלָלוֹ שֶׁל דָּבָר כָּל שֶׁאִלּוּ יָכוֹל לִטּל דְּבָרָיו קַיָּמִין וְאִם לָאו לֹא אָמַר כְּלוּם:","הֲרֵי שֶׁהָיָה מִצְטַעֵר עַל מָעוֹת שֶׁהִנִּיחַ לוֹ אָבִיו וְלֹא יָדַע הֵיכָן הֶחְבִּיאָם וְאָמְרוּ לוֹ בַּחֲלוֹם כָּךְ וְכָךְ הֵם בְּמָקוֹם פְּלוֹנִי הֵן וְשֶׁל פְּלוֹנִי הֵן וְשֶׁל מַעֲשֵׂר שֵׁנִי הֵן. וּמְצָאָן בְּמָקוֹם פְּלוֹנִי שֶׁנֶּאֱמַר לוֹ וּבַמִּנְיָן שֶׁנֶּאֱמַר לוֹ. זֶה הָיָה מַעֲשֶׂה וְאָמְרוּ חֲכָמִים דִּבְרֵי חֲלוֹמוֹת לֹא מַעֲלִין וְלֹא מוֹרִידִין:","שְׁכִיב מֵרַע שֶׁהוֹדָה שֶׁיֵּשׁ לִפְלוֹנִי בְּיָדוֹ מָנֶה וְאָמְרוּ יְתוֹמִים חָזַר וְאָמַר לָנוּ אָבִינוּ פְּרַעְתִּיו נֶאֱמָנִין וְנִשְׁבָּעִין עַל זֶה שְׁבוּעַת הֶסֵּת:","אָמַר תְּנוּ וְאָמְרוּ יְתוֹמִים חָזַר וְאָמַר לָנוּ אָבִינוּ פְּרַעְתִּיו אֵין נֶאֱמָנִין:","אָמַר מָנֶה לִפְלוֹנִי (בְּיָדִי) וְאָמְרוּ יְתוֹמִין נָתַנְנוּ אֵין נֶאֱמָנִין. שֶׁהֲרֵי לֹא אָמַר תְּנוּ וּמִנַּיִן יָדְעוּ שֶׁחַיָּבִין לִתֵּן:","אָמַר תְּנוּ וְאָמְרוּ יְתוֹמִים נָתַנְנוּ נֶאֱמָנִין וְנִשְׁבָּעִין שְׁבוּעַת הֶסֵּת שֶׁנָּתְנוּ:","שְׁכִיב מֵרַע שֶׁנָּתַן מָנֶה לְאֶחָד וְאָמַר לוֹ הוֹלֵךְ מָנֶה זוֹ לִפְלוֹנִי וְהָלַךְ וּמְצָאוֹ שֶׁמֵּת. אִם קַיָּם הָיָה בְּשָׁעָה שֶׁנָּתַן לוֹ הַשְּׁכִיב מֵרַע. יִנָּתְנוּ לְיוֹרְשֵׁי מִי שֶּׁנִּשְׁתַּלְּחוּ לוֹ. שֶׁדִּבְרֵי שְׁכִיב מֵרַע כִּכְתוּבִין וְכִמְסוּרִין הֵן. וְאִם לֹא הָיָה קַיָּם יַחְזְרוּ לְיוֹרְשֵׁי מְשַׁלֵּחַ שֶׁאֵין קִנְיָן לְמֵת:","שְׁכִיב מֵרַע שֶׁאָמַר תְּנוּ מָאתַיִם זוּז לִפְלוֹנִי וּשְׁלֹשׁ מֵאוֹת זוּז לִפְלוֹנִי וְאַרְבַּע מֵאוֹת זוּז לִפְלוֹנִי. אֵין אוֹמְרִין הַקּוֹדֵם בַּשְּׁטָר זָכָה. לְפִיכָךְ אִם לֹא הִנִּיחַ תְּשַׁע מֵאוֹת חוֹלְקִין הַנִּמְצָא לְפִי מַה שֶּׁכָּתַב לָהֶן. וְאִם יָצָא עָלָיו שְׁטַר חוֹב גּוֹבֶה מִכֻּלָּן מִכָּל אֶחָד וְאֶחָד כְּפִי מַה שֶּׁכָּתוּב לָהֶן. כֵּיצַד. הָיָה הַחוֹב אַרְבַּע מֵאוֹת וַחֲמִשִּׁים בַּעַל הַמָּאתַיִם נוֹתֵן מֵאָה וּבַעַל הַשְּׁלֹשׁ מֵאוֹת מֵאָה וַחֲמִשִּׁים וּבַעַל הָאַרְבַּע מֵאוֹת נוֹתֵן מָאתַיִם:","אֲבָל אִם אָמַר תְּנוּ מָאתַיִם זוּז לִפְלוֹנִי וְאַחֲרָיו שְׁלֹשׁ מֵאוֹת לִפְלוֹנִי וְאַחֲרָיו אַרְבַּע מֵאוֹת לִפְלוֹנִי. כָּל הַקּוֹדֵם בַּשְּׁטָר זָכָה. לְפִיכָךְ אִם יָצָא עָלָיו שְׁטַר חוֹב גּוֹבֶה מִן הָאַחֲרוֹן. אֵין לוֹ גּוֹבֶה מִשֶּׁלְּפָנָיו. אֵין לוֹ גּוֹבֶה מִשֶּׁלִּפְנֵי פָנָיו:","שְׁכִיב מֵרַע שֶׁאָמַר יָדוּר פְּלוֹנִי בְּבַיִת זֶה. יֹאכַל פְּלוֹנִי פֵּרוֹת דֶּקֶל זֶה. לֹא אָמַר כְּלוּם שֶׁלֹּא הִקְנָה לָהֶם דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. שֶׁהַדִּירָה וְהָאֲכִילָה וְכַיּוֹצֵא בָּהֶן הֲרֵי הֵן כְּדִבּוּר וּכְשֵׁינָה שֶׁאֵין נִקְנִין. אֲבָל אִם אָמַר תְּנוּ בַּיִת זֶה לִפְלוֹנִי כְּדֵי שֶׁיָּדוּר בּוֹ עַד זְמַן פְּלוֹנִי. אוֹ תְּנוּ דֶּקֶל זֶה לִפְלוֹנִי כְּדֵי שֶׁיֹּאכַל פֵּרוֹתָיו. דְּבָרָיו קַיָּמִין. שֶׁהֲרֵי הִקְנָה לָהֶם הַגּוּף לְפֵרוֹת וְהַגּוּף דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Paschal Offering 10":["הַשׁוֹבֵר עֶצֶם בְּפֶסַח טָהוֹר הֲרֵי זֶה לוֹקֶה שֶׁנֶּאֱמַר (שמות יב מו) \"וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ\". וְכֵן נֶאֱמַר בְּפֶסַח שֵׁנִי וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ. אֲבָל פֶּסַח שֶׁבָּא בְּטֻמְאָה אִם שָׁבַר בּוֹ עֶצֶם אֵינוֹ לוֹקֶה. מִפִּי הַשְּׁמוּעָה לָמְדוּ לֹא תִשְׁבְּרוּ בוֹ בְּטָהוֹר וְלֹא בְּטָמֵא. אֶחָד הַשּׁוֹבֵר אֶת הָעֶצֶם בְּלֵילֵי חֲמִשָּׁה עָשָׂר אוֹ שֶׁשָּׁבַר בּוֹ עֶצֶם מִבְּעוֹד יוֹם אוֹ שֶׁשָּׁבַר אַחַר כַּמָּה יָמִים הֲרֵי זֶה לוֹקֶה:","לְפִיכָךְ שׂוֹרְפִין עַצְמוֹת הַפֶּסַח בִּכְלַל הַנּוֹתָר מִבְּשָׂרוֹ כְּדֵי שֶׁלֹּא יָבוֹאוּ בָּהֶן לִידֵי תַּקָּלָה:","אֵין חַיָּבִין אֶלָּא עַל שְׁבִירַת עֶצֶם שֶׁיֵּשׁ עָלָיו כְּזַיִת בָּשָׂר אוֹ שֶׁיֵּשׁ בּוֹ מוֹחַ. אֲבָל עֶצֶם שֶׁאֵין בּוֹ מוֹחַ וְשֶׁאֵין עָלָיו כְּזַיִת בָּשָׂר אֵינוֹ חַיָּב עַל שְׁבִירָתוֹ. הָיָה עָלָיו כְּזַיִת בָּשָׂר וְשָׁבַר הָעֶצֶם שֶׁלֹּא בִּמְקוֹם הַבָּשָׂר חַיָּב אַף עַל פִּי שֶׁהַמָּקוֹם שֶׁשָּׁבַר פָּנוּי מִבְּשָׂרוֹ:","הַשּׁוֹבֵר אַחַר הַשּׁוֹבֵר בְּעֶצֶם אֶחָד לוֹקֶה:","הַשּׂוֹרֵף עֲצָמוֹת וְהַמְחַתֵּךְ גִּידִים אֵינוֹ חַיָּב מִשּׁוּם שְׁבִירַת עֶצֶם:","פֶּסַח שֶׁהוּא נָא אוֹ מְבֻשָּׁל וְשָׁבַר בּוֹ אֶת הָעֶצֶם לוֹקֶה. אֲפִלּוּ נִפְסַל בְּטֻמְאָה וִיצִיאָה וְכַיּוֹצֵא בָּהֶם יֵשׁ בּוֹ אִסּוּר שְׁבִירַת הָעֶצֶם. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיְתָה לוֹ שְׁעַת הַכּשֶׁר וְנִפְסַל. אֲבָל אִם לֹא הָיְתָה לוֹ שְׁעַת הַכּשֶׁר כְּגוֹן שֶׁנִּתְפַּגֵּל אוֹ נַעֲשָׂה מַחֲשֶׁבֶת זְמַן אוֹ מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם. אֵין בּוֹ מִשּׁוּם שְׁבִירַת הָעֶצֶם:","שָׁבַר עֶצֶם הָאַלְיָה אֵינוֹ לוֹקֶה שֶׁהֲרֵי אֵינוֹ רָאוּי לַאֲכִילָה:","הַסְּחוּסִים שֶׁהֵם כְּמוֹ עֲצָמִים רַכִּים. הֲרֵי אֵלּוּ מֻתָּרִין לְאָכְלָן:","הָיָה גְּדִי קָטָן וְרַךְ שֶׁעַצְמוֹתָיו רַכִּים לֹא יֹאכַל אוֹתָן שֶׁזֶּה שׁוֹבֵר עֶצֶם וְאִם אָכַל לוֹקֶה. שֶׁאֶחָד הַשּׁוֹבֵר עֶצֶם קָשֶׁה אוֹ עֶצֶם רַךְ. זֶה הַכְּלָל כָּל שֶׁנֶּאֱכָל בְּשׁוֹר הַגָּדוֹל אַחַר שֶׁיִּתְבַּשֵּׁל הוּא שֶׁמֻּתָּר לֶאֱכל כְּנֶגְדּוֹ מִן הַגְּדִי הָרַךְ אַחַר צְלִיָּתוֹ כְּגוֹן רָאשֵׁי כְּנָפַיִם וְהַסְּחוּסִים:","גִּידִין הָרַכִּין שֶׁסּוֹפָן לְהִקָּשׁוֹת אַף עַל פִּי שֶׁהֵן רְאוּיִין לַאֲכִילָה עַתָּה וְנֶאֱכָלִין בְּפֶסַח אֵין נִמְנִין עֲלֵיהֶן. וְנִמְנִין עַל מוֹחַ שֶׁבָּרֹאשׁ מִפְּנֵי שֶׁיָּכוֹל לְהוֹצִיאוֹ בְּלֹא שְׁבִירַת עֶצֶם. וְאֵין נִמְנִין עַל מוֹחַ שֶׁבְּקוּלִית וְהוּא הָעֶצֶם הַסָּתוּם מִשְּׁנֵי רָאשָׁיו. שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהוֹצִיאוֹ אֶלָּא בִּשְׁבִירַת עֶצֶם:","כְּשֶׁאָדָם אוֹכֵל אֶת הַפֶּסַח חוֹתֵךְ הַבָּשָׂר וְאוֹכֵל וְחוֹתֵךְ הָעֲצָמוֹת מִן הַפֶּרֶק וּמְפָרְקָן אִם רָצָה. וּכְשֶׁיַּגִּיעַ לְגִיד הַנָּשֶׁה מוֹצִיאוֹ וּמַנִּיחוֹ עִם שְׁאָר הַגִּידִים וְהָעֲצָמוֹת וְהַקְּרוּמוֹת שֶׁיּוֹצְאִין בִּשְׁעַת אֲכִילָה. שֶׁאֵין מְנַקִּין אוֹתוֹ כִּשְׁאָר הַבָּשָׂר וְאֵין מְחַתְּכִין אוֹתוֹ אֶלָּא צוֹלִין אוֹתוֹ שָׁלֵם. וְאִם חֲתָכוֹ חֲתִיכוֹת חֲתִיכוֹת כָּשֵׁר וְהוּא שֶׁלֹּא יֶחְסַר אֵיבָר. צָרִיךְ אָדָם לְהִשְׁתַּדֵּל שֶׁלֹּא יַשְׁאִיר מִבְּשַׂר הַפֶּסַח עַד בֹּקֶר שֶׁנֶּאֱמַר (שמות יב י) \"לֹא תוֹתִירוּ מִמֶּנּוּ עַד בֹּקֶר\". וְכֵן בַּשֵּׁנִי שֶׁנֶּאֱמַר (במדבר ט יב) \"לֹא יַשְׁאִירוּ מִמֶּנּוּ עַד בֹּקֶר\". וְאִם הִשְׁאִיר מִמֶּנּוּ בֵּין בָּרִאשׁוֹן בֵּין בַּשֵּׁנִי עָבַר בְּלֹא תַּעֲשֶׂה. וְאֵינוֹ לוֹקֶה עַל לָאו זֶה שֶׁהֲרֵי נִתָּק לַעֲשֵׂה שֶׁנֶּאֱמַר (שמות יב י) \"וְהַנֹּתָר מִמֶּנּוּ בָּאֵשׁ תִּשְׂרֹפוּ\":","כְּשֶׁמַּקְרִיבִין אֶת הַפֶּסַח בָּרִאשׁוֹן מַקְרִיבִין עִמּוֹ שְׁלָמִים בְּיוֹם י\"ד מִן הַבָּקָר אוֹ מִן הַצֹּאן. גְּדוֹלִים אוֹ קְטַנִּים. זְכָרִים אוֹ נְקֵבוֹת כְּכָל זִבְחֵי הַשְּׁלָמִים. וְזוֹ הִיא הַנִּקְרֵאת חֲגִיגַת אַרְבָּעָה עָשָׂר וְעַל זֶה נֶאֱמַר בַּתּוֹרָה (דברים טז ב) \"וְזָבַחְתָּ פֶּסַח לַה' אֱלֹהֶיךָ צֹאן וּבָקָר\". אֵימָתַי מְבִיאִין עִמּוֹ חֲגִיגָה זוֹ בִּזְמַן שֶׁהוּא בָּא בְּחל וּבְטָהֳרָה וּבְמוּעָט. אֲבָל אִם חָל יוֹם אַרְבָּעָה עָשָׂר לִהְיוֹת בְּשַׁבָּת אוֹ שֶׁבָּא הַפֶּסַח בְּטֻמְאָה אוֹ שֶׁהָיוּ הַפְּסָחִים מְרֻבִּים אֵין מְבִיאִין עִמּוֹ חֲגִיגָה. וְאֵין מַקְרִיבִין אֶלָּא הַפְּסָחִים בִּלְבַד:","חֲגִיגַת אַרְבָּעָה עָשָׂר רְשׁוּת וְאֵינָהּ חוֹבָה. וְנֶאֱכֶלֶת לִשְׁנֵי יָמִים וְלַיְלָה אֶחָד כְּכָל זִבְחֵי שְׁלָמִים. וְאָסוּר לְהַנִּיחַ מִבְּשַׂר חֲגִיגַת אַרְבָּעָה עָשָׂר לַיּוֹם הַשְּׁלִישִׁי שֶׁנֶּאֱמַר (דברים טז ד) \"וְלֹא יָלִין מִן הַבָּשָׂר אֲשֶׁר תִּזְבַּח בָּעֶרֶב בַּיּוֹם הָרִאשׁוֹן לַבֹּקֶר\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה אַזְהָרָה לְמַנִּיחַ בְּשַׂר חֲגִיגַת אַרְבָּעָה עָשָׂר לְיוֹם שִׁשָּׁה עָשָׂר. שֶׁנֶּאֱמַר לַבֹּקֶר עַד בֹּקֶר שֶׁל יוֹם הַשֵּׁנִי. וְהַמּוֹתִיר אֵינוֹ לוֹקֶה אֶלָּא יִשְׂרֹף הַנּוֹתָר מִמֶּנָּה כִּשְׁאָר הַנּוֹתָרִים:","בְּשַׂר חֲגִיגָה שֶׁעָלָה עִם הַפֶּסַח עַל הַשֻּׁלְחָן וְכָל הַתַּבְשִׁילִין הָעוֹלִים עִמּוֹ עַל הַשֻּׁלְחָן מִתְבַּעֲרִין עִמּוֹ. וְאֵינָן נֶאֱכָלִים אֶלָּא עַד חֲצוֹת כַּפֶּסַח עַצְמוֹ גְּזֵרָה מִפְּנֵי הַתַּעֲרֹבֶת:","מַה בֵּין פֶּסַח רִאשׁוֹן לְפֶסַח שֵׁנִי. הָרִאשׁוֹן אָסוּר בְּחָמֵץ בְּבַל יֵרָאֶה וּבַל יִמָּצֵא. וְאֵינוֹ נִשְׁחָט עַל חָמֵץ. וְאֵין מוֹצִיאִין מִמֶּנּוּ חוּץ לַחֲבוּרָה. וְטָעוּן הַלֵּל בַּאֲכִילָתוֹ. וּמְבִיאִין עִמּוֹ חֲגִיגָה. וְאֶפְשָׁר שֶׁיָּבוֹא בְּטֻמְאָה אִם נִטְמָא רֹב הַקָּהָל טֻמְאַת מֵת כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל פֶּסַח שֵׁנִי חָמֵץ וּמַצָּה עִמּוֹ בַּבַּיִת. וְאֵינוֹ טָעוּן הַלֵּל בַּאֲכִילָתוֹ. וּמוֹצִיאִין אוֹתוֹ חוּץ לַחֲבוּרָתוֹ. וְאֵין מְבִיאִין עִמּוֹ חֲגִיגָה וְאֵינוֹ בָּא בְּטֻמְאָה. וּשְׁנֵיהֶם דּוֹחִין אֶת הַשַּׁבָּת. וּטְעוּנִין הַלֵּל בַּעֲשִׂיָּתָן וְנֶאֱכָלִין צָלִי בְּבַיִת אֶחָד עַל מַצָּה וּמָרוֹר. וְאֵין מוֹתִירִין מֵהֶן. וְאֵין שׁוֹבְרִין בָּהֶן אֶת הָעֶצֶם. וְלָמָּה לֹא יִשְׁוֶה הַשֵּׁנִי לָרִאשׁוֹן לְכָל הַדְּבָרִים מֵאַחַר שֶׁנֶּאֱמַר (במדבר ט יב) \"כְּכָל חֻקַּת הַפֶּסַח יַעֲשׂוּ\". לְפִי שֶׁפֵּרֵשׁ בּוֹ מִקְצָת חֻקַּת הַפֶּסַח. לְלַמֵּד שֶׁאֵינָהּ שָׁוָה לָרִאשׁוֹן אֶלָּא בִּדְבָרִים שֶׁנִּתְפָּרְשׁוּ בּוֹ. וְהֵן הַמִּצְוֹת שֶׁבְּגוּפוֹ וְהֵם חֻקַּת הַפֶּסַח. שֶׁכְּלָל זֶה שֶׁנֶּאֱמַר בְּמִצְרַיִם שֶׁיִּלָּקַח הַפֶּסַח מִבֶּעָשׂוֹר. וְשֶׁהוּא טָעוּן הַגָּעַת דָּם בַּאֲגוּדַת אֵזוֹב לַמַּשְׁקוֹף וְלִשְׁתֵּי הַמְּזוּזוֹת. וְשֶׁיֵּאָכֵל בְּחִפָּזוֹן. אֵין אוֹתָן הַדְּבָרִים נוֹהֲגִים לְדוֹרוֹת וְלֹא נַעֲשׂוּ אֶלָּא בְּפֶסַח מִצְרַיִם בִּלְבַד:"],"Mishneh Torah, Plaintiff and Defendant 12":["שָׁלֹשׁ שָׁנִים שֶׁאָמַרְנוּ מִיּוֹם לְיוֹם אֲפִלּוּ הָיוּ חֲסֵרִים יוֹם אֶחָד לֹא הֶחֱזִיק וּמְסַלְּקִין אוֹתוֹ מִמֶּנָּה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקַרְקָעוֹת שֶׁהֵן עוֹשִׂין פֵּרוֹת תָּמִיד כְּגוֹן הַבָּתִּים וְהַחֲצֵרוֹת וְהַבּוֹרוֹת וְהַשִּׁיחִין וְהַמְּעָרוֹת וְהַחֲנֻיּוֹת וְהַפֻּנְדָּקוֹת וְהַמֶּרְחֲצָאוֹת וְהַשׁוֹבָכוֹת וּבָתֵּי הַבַּדִּין וּשְׂדֵה בֵּית הַשְּׁלָחִין שֶׁמַּשְׁקִין אוֹתָה תָּמִיד וְזוֹרְעִין בָּהּ וְנוֹטְעִין וְהַגַּנּוֹת וְהַפַּרְדֵּסִין. וְכֵן עֲבָדִים הַמְהַלְּכִין כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל שְׂדֵה הַבַּעַל שֶׁהִיא שׁוֹתָה מִמֵּי גְּשָׁמִים בִּלְבַד וּשְׂדֵה אִילָן אֵינָהּ מִיּוֹם לְיוֹם אֶלָּא כֵּיוָן שֶׁאָכְלוּ שָׁלֹשׁ תְּבוּאוֹת מִמִּין אֶחָד הֲרֵי אֵלּוּ כְּשָׁלֹשׁ שָׁנִים. כֵּיצַד. הָיְתָה שְׂדֵה תְּמָרִים וְגָדַר שָׁלֹשׁ גְּדֵרוֹת אוֹ שְׂדֵה עֲנָבִים וּבָצַר שָׁלֹשׁ בְּצִירוֹת אוֹ שְׂדֵה זֵיתִים וּמָסַק שָׁלֹשׁ מְסִיקוֹת הֲרֵי אֵלּוּ כְּשָׁלֹשׁ שָׁנִים וְהֶחֱזִיק. וַאֲפִלּוּ הָיוּ הָאִילָנוֹת רְצוּפִין וְלֹא הָיָה בֵּינֵיהֶן הַרְחָקָה כָּרָאוּי שֶׁהֲרֵי סוֹפָן לִיבַשׁ הוֹאִיל וְאוֹכְלָן שָׁלֹשׁ תְּבוּאוֹת הֶחֱזִיק:","הֵבִיא עֵדִים שֶׁהָיָה דָּר בְּחָצֵר זוֹ שָׁלֹשׁ שָׁנִים אוֹ שֶׁשְּׂכָרָהּ שָׁלֹשׁ שָׁנִים הֲרֵי זוֹ חֲזָקָה. טָעַן בַּעַל הֶחָצֵר וְאָמַר שֶׁמָּא לֹא שָׁכַן בָּהּ בַּיּוֹם וּבַלַּיְלָה אוֹ שֶׁמָּא אֵלּוּ שֶׁהִשְׂכִּירוּ לָהֶם לֹא שָׁכְנוּ בָּהּ בַּיּוֹם וּבַלַּיְלָה הֲרֵי זוֹ טַעֲנָה. אוֹמְרִים לַמַּחֲזִיק אוֹ תָּבִיא עֵדִים שֶׁשָּׁנִים אֵלּוּ גְּמוּרוֹת בַּיּוֹם וּבַלַּיְלָה אוֹ הִסְתַּלֵּק. אֲפִלּוּ בָּאוּ עֵדִים וְאָמְרוּ לָנוּ הִשְׂכִּיר וְאָנוּ דַּרְנוּ בָּהּ בַּיּוֹם וּבַלַּיְלָה וְטָעַן בַּעַל הַשָּׂדֶה וְאָמַר יָבִיאוּ עֵדִים שֶׁדָּרוּ בָּהּ בַּיּוֹם וּבַלַּיְלָה. צְרִיכִין אֵלּוּ הַשּׂוֹכְרִין לְהָבִיא רְאָיָה שֶׁדָּרוּ בָּהּ תָּמִיד. שֶׁזֶּה הַדָּבָר תָּלוּי בָּהֶן וְאֵין תָּלוּי בְּטַעֲנַת הַמַּחֲזִיק כְּדֵי שֶׁיָּעִידוּ לוֹ:","הָיָה זֶה הַמַּחֲזִיק אוֹ הָעֵדִים שֶׁדָּרוּ בָּהּ מִן הָרוֹכְלִין הַמְחַזְּרִין בַּעֲיָרוֹת וְכַיּוֹצֵא בָּהֶן. טוֹעֲנִין אוֹתוֹ לְכַתְּחִלָּה וּכְשֶׁיָּבִיא עֵדֵי חֲזָקָה אוֹמֵר לוֹ הָבֵא עֵדִים שֶׁהָיִיתָ מַחֲזִיק בָּהּ בַּיּוֹם וּבַלַּיְלָה. בַּמֶּה דְּבָרִים אֲמוּרִים בַּחֲצֵרוֹת וּבָתִּים וְכַיּוֹצֵא בָּהֶן שֶׁהֵן עֲשׂוּיוֹת לָדוּר בְּתוֹכָן בַּיּוֹם וּבַלַּיְלָה. אֲבָל הַחֲנֻיּוֹת שֶׁל תַּגָּרִים וְכַיּוֹצֵא בָּהֶן שֶׁאֵין דָּרִין בָּהֶן אֶלָּא בַּיּוֹם כֵּיוָן שֶׁדָּר בָּהּ שָׁלֹשׁ שָׁנִים בַּיּוֹם הֲרֵי זֶה חֲזָקָה:","שָׁלֹשׁ שָׁנִים שֶׁאָמַרְנוּ צָרִיךְ שֶׁיִּהְיוּ רְצוּפוֹת זוֹ אַחַר זוֹ. הֲרֵי שֶׁהֶחְזִיק בְּשָׂדֶה וּזְרָעָהּ שָׁנָה וְהוֹבִירָהּ שָׁנָה וּזְרָעָהּ שָׁנָה וְהוֹבִירָהּ שָׁנָה. אֲפִלּוּ עָשָׂה כֵן כַּמָּה שָׁנִים לֹא הֶחֱזִיק. הָיָה דַּרְכָּן שֶׁל בְּנֵי אוֹתוֹ הַמָּקוֹם לְהוֹבִיר אַף עַל פִּי שֶׁמִּקְצָתָן זוֹרְעִין שָׁנָה אַחַר שָׁנָה וּמִקְצָתָן זוֹרְעִין שָׁנָה וּמוֹבִירִין שָׁנָה הֲרֵי זֶה הֶחֱזִיק שֶׁהֲרֵי הוּא אוֹמֵר לֹא הוֹבַרְתִּי אוֹתָהּ אֶלָּא כְּדֵי שֶׁתַּעֲשֶׂה הַרְבֵּה בִּשְׁנַת הַזְּרִיעָה:","שְׁנֵי שֻׁתָּפִין שֶׁהֶחְזִיקוּ בְּשָׂדֶה שֵׁשׁ שָׁנִים הָאֶחָד אֲכָלָהּ רִאשׁוֹנָה וּשְׁלִישִׁית וַחֲמִישִׁית. וְהַשֵּׁנִי אֲכָלָהּ שְׁנִיָּה וּרְבִיעִית וְשִׁשִּׁית לֹא עָלְתָה חֲזָקָה לְאֶחָד מֵהֶם. שֶׁהֲרֵי בַּעַל הַקַּרְקַע אוֹמֵר כֵּיוָן שֶׁלֹּא רָאִיתִי וְלֹא שָׁמַעְתִּי שֶׁהֶחְזִיק בָּהּ אָדָם אֶחָד שָׁנָה אַחַר שָׁנָה מִפְּנֵי זֶה לֹא מָחִיתִי. לְפִיכָךְ אִם כָּתְבוּ אֵלּוּ הַשֻּׁתָּפִין שְׁטָר בֵּינֵיהֶן שֶׁיִּשְׁתַּמְּשׁוּ בָּהּ שָׁנָה אַחַר שָׁנָה כֵּיוָן שֶׁעָבַר שָׁלֹשׁ שָׁנִים עָלְתָה לָהֶן חֲזָקָה. שֶׁהַשְּׁטָר יֵשׁ לוֹ קוֹל וְהוֹאִיל וְלֹא מִחָה אִבֵּד זְכוּתוֹ. וְהוּא הַדִּין לְעֶבֶד שֶׁהֶחְזִיקוּ בּוֹ שְׁנַיִם וְנִשְׁתַּמְּשׁוּ בּוֹ שָׁנָה אַחַר שָׁנָה אִם כָּתְבוּ שְׁטָר בֵּינֵיהֶן הֲרֵי הֶחֱזִיקוּ:","אֲכָלָהּ שָׁנָה זֶה הַמַּחֲזִיק וּמְכָרָהּ וַאֲכָלָהּ הַלּוֹקֵחַ שָׁנָה וּמָכַר לְלוֹקֵחַ שֵׁנִי וַאֲכָלָהּ שָׁנָה. אִם מָכְרוּ זֶה לָזֶה בִּשְׁטָר שְׁלָשְׁתָּן מִצְטָרְפִין וַהֲרֵי זוֹ חֲזָקָה מִפְּנֵי שֶׁלֹּא מִחָה. וְאִם מָכְרוּ שֶׁלֹּא בִּשְׁטָר אֵינָהּ חֲזָקָה שֶׁהַבְּעָלִים הָרִאשׁוֹנִים אוֹמְרִים כֵּיוָן שֶׁלֹּא עָמַד בָּהּ אִישׁ אֶחָד שָׁלֹשׁ שָׁנִים לֹא הֻצְרַכְתִּי לִמְחוֹת:","אֲכָלָהּ הָאָב שָׁנָה וְהַבֵּן שְׁתַּיִם הָאָב שְׁתַּיִם וְהַבֵּן שָׁנָה הָאָב שָׁנָה וְהַבֵּן שָׁנָה וְהַלּוֹקֵחַ מִן הַבֵּן שָׁנָה הֲרֵי זוֹ חֲזָקָה וְהוּא שֶׁלָּקַח בִּשְׁטָר:","אֲכָלָהּ בִּפְנֵי הָאָב שֶׁהָיָה בַּעַל הַשָּׂדֶה שָׁנָה וּבִפְנֵי בְּנוֹ שְׁתַּיִם. אוֹ בִּפְנֵי הָאָב שְׁתַּיִם וּבִפְנֵי הַבֵּן שָׁנָה. אוֹ בִּפְנֵי הָאָב שָׁנָה וּבִפְנֵי בְּנוֹ שָׁנָה וּבִפְנֵי לוֹקֵחַ מִן הַבֵּן שָׁנָה. הֲרֵי זוֹ חֲזָקָה. וְהוּא שֶׁמָּכַר הַבֵּן זוֹ הַשָּׂדֶה בִּכְלַל שְׂדוֹתָיו שֶׁהֲרֵי לֹא הִכִּיר הַמַּחֲזִיק שֶׁנִּמְכְּרָה וּלְפִיכָךְ לֹא נִזְהַר בִּשְׁטָרוֹ. אֲבָל אִם מָכַר הַבֵּן שָׂדֶה זוֹ בִּפְנֵי עַצְמָהּ אֵין לְךָ מְחָאָה גְּדוֹלָה מִזּוֹ:","נָרָהּ שָׁנָה אַחַר שָׁנָה אֲפִלּוּ כַּמָּה שָׁנִים הוֹאִיל וְלֹא נֶהֱנָה בָּהּ אֵינָהּ חֲזָקָה. וְכֵן אִם פָּתַח בָּהּ שְׁבִילֵי הַמַּיִם וּפָתַח וְשִׂדֵּד בִּלְבַד הוֹאִיל וְלֹא אָכַל פֵּרוֹת אֵינָהּ חֲזָקָה:","זְרָעָהּ וְלֹא הִרְוִיחַ כְּלוּם אֶלָּא זָרַע כּוֹר וְאָסַף כּוֹר לֹא הֶחֱזִיק שֶׁהֲרֵי לֹא נֶהֱנָה:","אֲכָלָהּ שַׁחַת לֹא הֶחֱזִיק. וְאִם הָיָה הַמָּקוֹם דַּרְכָּן לִזְרֹעַ לְשַׁחַת מִפְּנֵי שֶׁדָּמָיו יְקָרִין הֲרֵי זוֹ חֲזָקָה:","אֲכָלָהּ עָרְלָה שְׁבִיעִית וְכִלְאַיִם אַף עַל פִּי שֶׁנֶּהֱנָה בַּעֲבֵרָה הֲרֵי זוֹ חֲזָקָה:","הָיָה הַמָּקוֹם שֶׁהֶחְזִיק בּוֹ סֶלַע אוֹ חַלָּמִישׁ שֶׁאֵינוֹ רָאוּי לִזְרִיעָה צָרִיךְ לֵהָנוֹת בּוֹ בְּדָבָר הָרָאוּי לָהּ כְּגוֹן שֶׁיִּשְׁטַח בּוֹ הַפֵּרוֹת אוֹ יַעֲמִיד בּוֹ בְּהֵמָה וְכַיּוֹצֵא בָּזֶה. וְאִם לֹא נֶהֱנָה בּוֹ בְּכָל אוֹתָן הַשָּׁלֹשׁ שָׁנִים בַּדָּבָר הָרָאוּי לוֹ לֹא הֶחֱזִיק:","הָיָה מַעֲמִיד בְּהֵמָה בְּמָקוֹם מְסֻיָּם מֵחֲצַר חֲבֵרוֹ אוֹ שֶׁהָיָה מְגַדֵּל שָׁם תַּרְנְגוֹלִין אוֹ מַעֲמִיד שָׁם תַּנּוּר וְכִירַיִם וְרֵחַיִם. אוֹ שֶׁנָּתַן שָׁם זִבְלוֹ. בֵּין שֶׁהֶעֱמִיד שָׁם מְחִצָּה בֵּין שֶׁלֹּא הֶעֱמִיד. אִם נִשְׁתַּמֵּשׁ בִּדְבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן שָׁלֹשׁ שָׁנִים בַּיּוֹם וּבַלַּיְלָה וְטָעַן עַל בַּעַל הֶחָצֵר וְאָמַר אַתָּה נָתַתָּ לִי מָקוֹם זֶה אוֹ מְכַרְתּוֹ לִי הֲרֵי זוֹ חֲזָקָה:","שָׂדֶה שֶׁהִיא מֻקֶּפֶת גָּדֵר וּבָא זֶה שֶׁהֶחְזִיק בָּהּ וְזָרַע חוּץ לַגָּדֵר וְנֶהֱנָה בְּכָל מָקוֹם שֶׁאֵינוֹ שָׁמוּר. אַף עַל פִּי שֶׁאֲכָלוֹ שָׁנָה אַחַר שָׁנָה לֹא עָלְתָה לוֹ חֲזָקָה. שֶׁהַבְּעָלִים טוֹעֲנִין וְאוֹמְרִין כֵּיוָן שֶׁרָאִינוּ שֶׁזּוֹרֵעַ בְּמָקוֹם מֻפְקָר אָמַרְנוּ כָּל מַה שֶּׁזָּרַע חַיַּת הַשָּׂדֶה תֹּאכְלֶנּוּ וּלְפִיכָךְ לֹא מָחִיתִי. וְהוּא הַדִּין לְכָל הַזּוֹרֵעַ מָקוֹם שֶׁאֵינוֹ שָׁמוּר אֶלָּא רֶגֶל חַיָּה וְיַד כָּל אָדָם מְצוּיִין בּוֹ:","אֲכָלָהּ כֻּלָּהּ חוּץ מִבֵּית רֹבַע הֶחֱזִיק בְּכֻלָּהּ חוּץ מֵאוֹתוֹ בֵּית רֹבַע שֶׁלֹּא נֶהֱנָה בּוֹ. אֲפִלּוּ הָיָה חַלָּמִישׁ בְּתוֹךְ הַשָּׂדֶה הוֹאִיל וְלֹא נִשְׁתַּמֵּשׁ בּוֹ כָּרָאוּי לוֹ אֵין לָזֶה בּוֹ חֲזָקָה:","הֶחֱזִיק אֶחָד בָּאִילָנוֹת וְאָכַל פֵּרוֹתֵיהֶן וְאֶחָד הֶחֱזִיק בַּקַּרְקַע וּזְרָעָהּ וְאָכַל פֵּרוֹתֶיהָ וְכָל אֶחָד מִשְּׁנֵיהֶם טוֹעֵן שֶׁהַכּל שֶׁלִּי וַאֲנִי לְקַחְתִּיו. זֶה שֶׁהֶחְזִיק בָּאִילָנוֹת וַאֲכָלָן שָׁלֹשׁ שָׁנִים יֵשׁ לוֹ הָאִילָנוֹת וְקַרְקַע שֶׁצְּרִיכִין לוֹ וְהוּא כִּמְלֹא הָאוֹרֶה וְסַלּוֹ חוּצָה לְכָל אִילָן וְאִילָן. וְזֶה שֶׁהֶחְזִיק בַּקַּרְקַע יֵשׁ לוֹ שְׁאָר הַקַּרְקַע:","וְכֵן הָאוֹכֵל כָּל פֵּרוֹת אִילָן שָׁלֹשׁ שָׁנִים וְטָעַן עַל בַּעַל הָאִילָן אַתָּה מָכַרְתָּ לִי אִילָן זֶה וְקַרְקָעוֹ הֲרֵי זֶה יֵשׁ לוֹ קַרְקַע כָּעֳבִי הָאִילָן עַד הַתְּהוֹם:","שְׂדֵה אִילָן שֶׁהָיוּ בּוֹ שְׁלֹשִׁים אִילָנוֹת בְּתוֹךְ בֵּית שָׁלֹשׁ סְאִין וְאָכַל עֲשָׂרָה בְּשָׁנָה רִאשׁוֹנָה וַעֲשָׂרָה בְּשָׁנָה שְׁנִיָּה וַעֲשָׂרָה בְּשָׁנָה שְׁלִישִׁית הֻחְזַק בַּכּל. וְהוּא שֶׁהָיוּ עֲשָׂרָה שֶׁאָכַל מְפֻזָּרוֹת בְּכָל בֵּית הַשָּׁלֹשׁ סְאִין וְלֹא הוֹצִיאוּ שְׁאָר הָאִילָנוֹת פֵּרוֹת. אֲבָל אִם הוֹצִיאוּ שְׁאָר הָאִילָנוֹת פֵּרוֹת וְלֹא אֲכָלָן לֹא הֻחְזַק אֶלָּא בְּמַה שֶּׁאָכַל:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאָכַל הוּא מִקְצָת הַפֵּרוֹת וּבָזְזוּ הָעָם שְׁאָר הַפֵּרוֹת. אֲבָל אִם מֵנִיחַ פֵּרוֹתֵיהֶן עֲלֵיהֶן הוֹאִיל וְאָכַל אִילָן מִכָּאן וְאִילָן מִכָּאן מִכָּל הַשָּׂדֶה הֶחֱזִיק בְּכָל הַשָּׂדֶה אַף עַל פִּי שֶׁלֹּא אָסַף כָּל פֵּרוֹתֶיהָ:"],"Mishneh Torah, Plaintiff and Defendant 9":["הָאֻמָּן אֵין לוֹ חֲזָקָה בַּכֵּלִים שֶׁתַּחַת יָדוֹ. אֶחָד כֵּלִים הָעֲשׂוּיִים לְהַשְׁאִיל וּלְהַשְׂכִּיר וְאֶחָד שְׁאָר כֵּלִים. כֵּיצַד. רָאָה כֶּלְיוֹ בְּיַד הָאֻמָּן וְהֵבִיא עֵדִים שֶׁהֵן יוֹדְעִין שֶׁהַכְּלִי זֶה שֶׁלּוֹ וְהוּא טוֹעֵן וְאוֹמֵר לְתַקֵּן נְתַתִּיו לְךָ. וְהָאֻמָּן אוֹמֵר לֹא בָּא לְיָדִי אֶלָּא בִּמְכִירָה אוֹ מַתָּנָה. אוֹ שֶׁטָּעַן אַתָּה נְתַתּוֹ לִי אַתָּה מְכַרְתּוֹ לִי אַחַר שֶׁבָּא לְיָדִי לְתַקְּנוֹ. אַף עַל פִּי שֶׁמְּסָרוֹ לוֹ שֶׁלֹּא בְּעֵדִים בַּעַל הַכְּלִי נֶאֱמָן וּמוֹצִיאִין אוֹתוֹ מִיַּד הָאֻמָּן וְיִשָּׁבַע בַּעַל הַבַּיִת הֶסֵּת עַל טַעֲנָתוֹ. וְיֵשׁ גְּאוֹנִים שֶׁדָּנוּ אַף עַל פִּי שֶׁלֹּא הֵבִיא בַּעַל הַבַּיִת עֵדִים שֶׁזֶּה הַכְּלִי שֶׁלּוֹ הוֹאִיל וְרָאָה כֶּלְיוֹ בְּיַד הָאֻמָּן וַהֲרֵי הָאֻמָּן מוֹדֶה לוֹ שֶׁהָיָה שֶׁלּוֹ וּמְכָרוֹ לוֹ נֶאֱמָן. אֲבָל אִם אָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְשֶׁלִּי הוּא הַכְּלִי נֶאֱמָן הָאֻמָּן וְנִשְׁבָּע הֶסֵּת. וְאִם הֵבִיא בַּעַל הַבַּיִת עֵדִים שֶׁהַכְּלִי הַזֶּה יָדוּעַ לוֹ אֵין הָאֻמָּן נֶאֱמָן. וְדִין זֶה פֶּלֶא הוּא בְּעֵינַי:","לֹא רָאָה הַכְּלִי בְּיַד הָאֻמָּן אֶלָּא טָעַן וְאָמַר כְּלִי פְּלוֹנִי נְתַתִּיו לוֹ לְתַקֵּן וְהָאֻמָּן אוֹמֵר חָזַרְתָּ וּמְכַרְתּוֹ אוֹ נְתַתּוֹ לִי הָאֻמָּן נִשְׁבָּע הֶסֵּת וְנִפְטָר מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. וַאֲפִלּוּ מְסָרוֹ לְתַקֵּן בְּעֵדִים הָאֻמָּן נֶאֱמָן מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר הֶחְזַרְתִּי שֶׁהַמַּפְקִיד אֵצֶל חֲבֵרוֹ בְּעֵדִים אֵינוֹ צָרִיךְ לְהַחְזִיר לוֹ בְּעֵדִים. לְפִיכָךְ נִשְׁבָּע הָאֻמָּן הֶסֵּת וְנִפְטָר וְאֵין מְחַיְּבִין אוֹתוֹ לְהוֹצִיא הַכְּלִי. וְאִם הוֹצִיאוֹ הוֹאִיל וְנִרְאֶה הֲרֵי בַּעַל הַבַּיִת מֵבִיא עֵדִים שֶׁהוּא שֶׁלּוֹ וְנוֹטְלוֹ אַף עַל פִּי שֶׁמְּסָרוֹ לוֹ בְּלֹא עֵדִים כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ אִם טָעַן הָאֻמָּן וְאָמַר שְׁתַּיִם קָצַצְתָּ לִי בִּשְׂכָרִי וּבַעַל הַבַּיִת אוֹמֵר לֹא קָצַצְתִּי לְךָ אֶלָּא אַחַת אִם הָיָה הַכְּלִי נִרְאֶה בִּפְנֵיהֶם הוֹאִיל וְהָאֻמָּן אֵין לוֹ בּוֹ חֲזָקָה וְאֵינוֹ יָכוֹל לִטְעֹן שֶׁהוּא לָקוּחַ בְּיָדוֹ הֲרֵי בַּעַל הַבַּיִת נִשְׁבָּע בִּנְקִיטַת חֵפֶץ עַל הַקְּצִיצָה כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׂכִירוּת וְנוֹתֵן. וְאִם אֵין הַכְּלִי נִרְאֶה בִּפְנֵיהֶם הוֹאִיל וְהָאֻמָּן נֶאֱמָן לוֹמַר לָקוּחַ הוּא בְּיָדִי יָכוֹל לִטְעֹן עַד כְּדֵי דָּמָיו וְנִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל כְּדֶרֶךְ כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין כְּמוֹ שֶׁבֵּאַרְנוּ:","אֻמָּן שֶׁיָּרַד מֵאֻמָּנוּתוֹ וּבֶן הָאֻמָּן הֲרֵי הֵן כִּשְׁאָר כָּל אָדָם וְיֵשׁ לָהֶן חֲזָקָה בְּכָל הַמִּטַּלְטְלִין כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁנִּכְנַס לְבֵיתוֹ שֶׁל חֲבֵרוֹ בִּפְנֵי בַּעַל הַבַּיִת וְיָצָא וְכֵלִים טְמוּנִין תַּחַת כְּנָפָיו וְהָעֵדִים רוֹאִין אוֹתוֹ. וּלְאַחַר זְמַן תְּבָעוֹ בַּעַל הַבַּיִת וְאָמַר לוֹ הַחְזֵר לִי כֵּלִים שֶׁהִשְׁאַלְתִּיךָ וַהֲרֵי הָעֵדִים וְהוּא אוֹמֵר לְקוּחִין הֵן בְּיָדִי אֵינוֹ נֶאֱמָן. וְנִשְׁבָּע בַּעַל הַבַּיִת הֶסֵּת עַל טַעֲנָתוֹ שֶׁלֹּא מְכָרָן וְלֹא נְתָנָן וְיַחֲזִירוּ בֵּית דִּין הַכֵּלִים לְבַעַל הַבַּיִת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבַעַל הַבַּיִת שֶׁאֵינוֹ עָשׂוּי לִמְכֹּר אֶת כֵּלָיו. וְזֶה שֶׁהוֹצִיא הַכֵּלִים תַּחַת כְּנָפָיו אֵין דַּרְכּוֹ לְהַצְנִיעַ. וְאוֹתָן הַכֵּלִים אֵין דֶּרֶךְ בְּנֵי אָדָם לְהַצְנִיעָן. לְפִיכָךְ חַיָּב לְהַחְזִיר לְפִי שֶׁלֹּא הִצְנִיעָן אֶלָּא לִכְפֹּר בָּהֶן. אֲבָל בַּעַל הַבַּיִת הֶעָשׂוּי לִמְכֹּר אֶת כֵּלָיו אַף עַל פִּי שֶׁאֵין זֶה צָנוּעַ וְאֵין דֶּרֶךְ אוֹתָן הַכֵּלִים לְהַטְמִינָן תַּחַת הַכְּנָפַיִם הֲרֵי זֶה נִשְׁבָּע הֶסֵּת שֶׁהֵן לְקוּחִין בְּיָדוֹ. וְכֵן אִם יָצָא בָּהֶן מְגֻלִּין בִּפְנֵי עֵדִים אַף עַל פִּי שֶׁאֵין בַּעַל הַבַּיִת עָשׂוּי לִמְכֹּר אֶת כֵּלָיו הֲרֵי זֶה נֶאֱמָן לוֹמַר לְקוּחִין הֵן בְּיָדִי. שֶׁמָּא נִצְטָרְכוּ לוֹ מָעוֹת וּמָכַר. וּבִלְבַד שֶׁלֹּא יִהְיוּ מִדְּבָרִים הָעֲשׂוּיִים לְהַשְׁאִיל וּלְהַשְׂכִּיר. אֲבָל דְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר לְעוֹלָם הֵן בְּחֶזְקַת בַּעֲלֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ. וְאַף עַל פִּי שֶׁהוֹצִיאָן מְגֻלִּין וְאַף עַל פִּי שֶׁבַּעַל הַבַּיִת הַזֶּה עָשׂוּי לִמְכֹּר אֶת כֵּלָיו הוֹאִיל וְיֵשׁ לוֹ עֵדִים שֶׁזֶּה הַכְּלִי עָשׂוּי לְהַשְׁאִיל וּלְהַשְׂכִּיר בִּלְבַד יָדוּעַ הוּא לוֹ מוֹצִיאִין אוֹתָן מִיַּד זֶה עַל כָּל פָּנִים עַד שֶׁיָּבִיא רְאָיָה שֶׁמְּכָרוֹ לוֹ אוֹ נְתָנוֹ לוֹ בְּמַתָּנָה כְּדִין קַרְקָעוֹת:","אֲפִלּוּ מֵת זֶה שֶׁהַכְּלִי תַּחַת יָדוֹ מוֹצִיאִין אוֹתוֹ מִיַּד הַיּוֹרֵשׁ בְּלֹא שְׁבוּעָה שֶׁכֵּיוָן שֶׁאֵין לְאָבִיו לִטְעֹן שֶׁלְּקָחוֹ אוֹ שֶׁהוּא מַשְׁכּוֹן כָּךְ אֵין זֶה יָכוֹל לְהַשְׁבִּיעוֹ. וְאִם טָעַן הַיּוֹרֵשׁ טַעֲנַת וַדַּאי וְאָמַר בְּפָנַי נְתָנוֹ לְאָבִי אוֹ מְכָרוֹ לוֹ הֲרֵי בַּעַל הַבַּיִת נִשְׁבָּע הֶסֵּת כִּשְׁאָר כָּל הַנִּשְׁבָּעִין. וּכְבָר בֵּאַרְנוּ שֶׁיֵּשׁ מִי שֶׁהוֹרָה שֶׁיִּשָּׁבַע בַּעַל הַבַּיִת הֶסֵּת וְאַחַר כָּךְ יַחְזִיר כֶּלְיוֹ מִיַּד הַיּוֹרֵשׁ. וְאֵין דַּעְתִּי נוֹטָה לָזֶה:","מִי שֶׁלָּקַח קַרְדֹּם וְאָמַר הֲרֵינִי הוֹלֵךְ לִגְזֹר דִּקְלוֹ שֶׁל פְּלוֹנִי שֶׁמְּכָרוֹ לִי וְכָרַת הַדֶּקֶל הֲרֵי זֶה בְּחֶזְקָתוֹ. שֶׁאֵין אָדָם מֵעֵז פָּנָיו וְכוֹרֵת אִילָן שֶׁאֵינוֹ שֶׁלּוֹ. וְאִם טְעָנוֹ הַבְּעָלִים שֶׁלֹּא מְכָרוּהוּ נִשְׁבָּע זֶה הַכּוֹרֵת הֶסֵּת שֶׁהוּא שֶׁלּוֹ וְנִפְטָר. וְכֵיוָן שֶׁנִּכְרַת הֲרֵי הוּא כִּשְׁאָר כָּל הַמִּטַּלְטְלִין. וְכֵן הַיּוֹרֵד לִשְׂדֵה חֲבֵרוֹ וְאָכַל פֵּרוֹתֶיהָ שָׁנָה אוֹ שְׁנָתַיִם וְהַבְּעָלִים טוֹעֲנִין שֶׁזֶּה יָרַד שֶׁלֹּא בִּרְשׁוּת וּגְזָלָן הוּא וְאָכַל וַהֲרֵי הָעֵדִים שֶׁאָכַל וְהַיּוֹרֵד אוֹמֵר בִּרְשׁוּתְךָ יָרַדְתִּי לֶאֱכל פֵּרוֹתֶיהָ. הֲרֵי זֶה הָאוֹכֵל נֶאֱמָן וְנִשְׁבָּע הֶסֵּת עַל כָּךְ חֲזָקָה הִיא שֶׁאֵין אָדָם מֵעֵז פָּנָיו וְאוֹכֵל פֵּרוֹת שֶׁאֵינָן שֶׁלּוֹ. אַף עַל פִּי שֶׁהַקַּרְקַע בְּחֶזְקַת בַּעֲלֵיהֶן אֵין הַפֵּרוֹת בְּחֶזְקַת הַבְּעָלִים. שֶׁאֵין אָדָם מוֹכֵר פֵּרוֹת שָׂדֵהוּ בִּשְׁטָר כְּדֵי שֶׁנֹּאמַר לְזֶה שֶׁאָכַל הָבֵא שְׁטָרְךָ. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם אָכַל פֵּרוֹתֶיהָ שָׁנִים רַבּוֹת שֶׁמִּתּוֹךְ שֶׁיָּכוֹל לוֹמַר לְקוּחָה הִיא בְּיָדִי נֶאֱמָן לוֹמַר לְפֵרוֹת יָרַדְתִּי וְיִשָּׁבַע הֶסֵּת:","שְׁנַיִם שֶׁהָיוּ אוֹחֲזִין בִּכְלִי אֶחָד אוֹ שֶׁהָיוּ רוֹכְבִין עַל גַּבֵּי בְּהֵמָה אַחַת. אוֹ שֶׁהָיָה אֶחָד רוֹכֵב וְאֶחָד מַנְהִיג. אוֹ יוֹשְׁבִין בְּצַד עֲרֵמָה שֶׁל חִטִּים וּמֻנָּחוֹת בְּסִמְטָא אוֹ בְּחָצֵר שֶׁל שְׁנֵיהֶם. זֶה אוֹמֵר הַכּל שֶׁלִּי וְזֶה אוֹמֵר הַכּל שֶׁלִּי. כָּל אֶחָד מִשְּׁנֵיהֶן נִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁאֵין לוֹ בְּזֶה הַדָּבָר פָּחוֹת מֵחֶצְיוֹ וְיַחְלֹקוּ. וּשְׁבוּעָה זוֹ תַּקָּנַת חֲכָמִים הִיא כְּדֵי שֶׁלֹּא יִהְיֶה כָּל אֶחָד תּוֹפֵס בְּטַלִּיתוֹ שֶׁל חֲבֵרוֹ וְנוֹטֵל בְּלֹא שְׁבוּעָה:","זֶה אוֹמֵר כֻּלָּהּ שֶׁלִּי וְזֶה אוֹמֵר חֶצְיָהּ שֶׁלִּי הָאוֹמֵר כֻּלָּהּ שֶׁלִּי יִשָּׁבַע שֶׁאֵין לוֹ בָּהּ פָּחוֹת מִשְּׁלֹשָׁה חֲלָקִים. וְהָאוֹמֵר חֶצְיָהּ שֶׁלִּי יִשָּׁבַע שֶׁאֵין לוֹ בָּהּ פָּחוֹת מֵרְבִיעַ. וְזֶה נוֹטֵל שְׁלֹשָׁה חֲלָקִים וְזֶה נוֹטֵל רְבִיעַ. מִכָּאן אַתָּה לָמֵד לְכָל הַנִּשְׁבָּעִין לִטּל בֵּין שְׁבוּעָה קַלָּה בֵּין שְׁבוּעָה חֲמוּרָה שֶׁאֵינוֹ נִשְׁבָּע עַל מַה שֶּׁטּוֹעֵן אֶלָּא עַל מַה שֶּׁנּוֹטֵל אַף עַל פִּי שֶׁטּוֹעֵן יוֹתֵר:","הָיוּ שְׁנַיִם אֲדוּקִין בְּטַלִּית זֶה אוֹמֵר כֻּלָּהּ שֶׁלִּי וְזֶה אוֹמֵר כֻּלָּהּ שֶׁלִּי. זֶה נוֹטֵל עַד מָקוֹם שֶׁיָּדוֹ מַגַּעַת וְזֶה נוֹטֵל עַד מָקוֹם שֶׁיָּדוֹ מַגַּעַת וְהַשְּׁאָר חוֹלְקִין בְּשָׁוֶה אַחַר שֶׁנִּשְׁבָּעִין. וְיֵשׁ לְכָל אֶחָד לְגַלְגֵּל עַל חֲבֵרוֹ שֶׁכָּל מַה שֶּׁנָּטַל כַּדִּין נָטַל:","הָיָה זֶה אוֹחֵז בַּחוּטִין שֶׁבִּשְׂפַת הַטַּלִּית וְזֶה בַּחוּטִין שֶׁבִּשְׂפַת הָאַחֶרֶת חוֹלְקִין כֻּלָּהּ בְּשָׁוֶה אַחַר שֶׁנִּשְׁבָּעִין. וְכָל חֲלוּקָה הָאֲמוּרָה כָּאן בְּדָמִים לֹא שֶׁיַּפְסִידוּ עַצְמוֹ שֶׁל כְּלִי אוֹ שֶׁל טַלִּית אוֹ שֶׁיָּמִיתוּ הַבְּהֵמָה:","הָיָה אוֹחֵז הָאֶחָד אֶת כֻּלָּהּ וְזֶה מִתְאַבֵּק עִמּוֹ וְנִתְלֶה בָּהּ הֲרֵי זוֹ בְּחֶזְקַת הָאוֹחֵז אֶת כֻּלָּהּ:","בָּאוּ שְׁנֵיהֶם אֲדוּקִין בָּהּ וּשְׁמָטָהּ הָאֶחָד מִיַּד חֲבֵרוֹ בְּפָנֵינוּ וְשָׁתַק הַשֵּׁנִי אַף עַל פִּי שֶׁחָזַר וְצָוַח אֵין מוֹצִיאִין אוֹתָהּ מִיָּדוֹ כֵּיוָן שֶׁשָּׁתַק בַּתְּחִלָּה הֲרֵי זֶה כְּמוֹדֶה לוֹ. חָזַר הַשֵּׁנִי וּתְקָפָהּ מֵרִאשׁוֹן אַף עַל פִּי שֶׁהָרִאשׁוֹן (לֹא) צָוַח מִתְּחִלָּה וְעַד סוֹף חוֹלְקִין:","בָּאוּ שְׁנֵיהֶם אֲדוּקִין בְּטַלִּית וְאָמַרְנוּ לָהֶם צְאוּ וְחַלְּקוּ אֶת דָּמֶיהָ יָצְאוּ וְחָזְרוּ וַהֲרֵי הִיא תַּחַת יַד אֶחָד מֵהֶן זֶה טוֹעֵן הוֹדָה וְנִסְתַּלֵּק מִמֶּנָּה וְזֶה טוֹעֵן שֶׁמְּכַרְתִּיו לוֹ אוֹ נִתְגַּבֵּר עָלַי וַחֲטָפָהּ הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְאִם לֹא הֵבִיא רְאָיָה יִשָּׁבַע זֶה שֶׁהִיא שֶׁלּוֹ וְיִפָּטֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Positive Mitzvot 109":["להיות הטהרה מכל הטמאות בטבילה במי מקוה, שנאמר: \"וְרָחַץ בַּמַּיִם אֶת כָּל בְּשָׂרוֹ\" (ויקרא טו, טז) למדו מפי השמועה שרחיצה זו במים שכל גופו עולה בהן בבת אחת."],"Mishneh Torah, Positive Mitzvot 12":["לִקְשֹׁר תְּפִלִּין בָּרֹאשׁ, שֶׁנֶּאֱמָר: \"וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ\" (דברים ו, ח)."],"Mishneh Torah, Positive Mitzvot 130":["להפריש מעשר עני תחת מעשר שני בשלישית ובשישית בשבוע, שנאמר: \"מִקְצֵה שָׁלֹשׁ שָׁנִים תּוֹצִיא אֶת כָּל מַעְשַׂר תְּבוּאָתְךָ\" (דברים יד, כח)."],"Mishneh Torah, Positive Mitzvot 141":["להשמיט כספים בשביעית, שנאמר: \"שמוט כל בעל משה ידו\" (דברים טו,ב)."],"Mishneh Torah, Positive Mitzvot 152":["לבדוק בסימני דגים, שנאמר: \"את זה, תאכלו, מכול, אשר במים\" (ויקרא יא,ט; דברים יד,ט)."],"Mishneh Torah, Positive Mitzvot 163":["לשבות בראשון של חודש השביעי, שנאמר: \"באחד לחודש, יהיה לכם שבתון\" (ויקרא כג,כד)."],"Mishneh Torah, Positive Mitzvot 174":["לשמוע מכל בית דין הגדול שיעמדו להם לישראל, שנאמר: \"ועל המשפט אשר יאמרו לך--תעשה\" (דברים יז,יא)."],"Mishneh Torah, Positive Mitzvot 185":["לאבד עבודה זרה וכל משמשיה, שנאמר: \"אבד תאבדון את כל המקומות\" (דברים יב,ב)."],"Mishneh Torah, Positive Mitzvot 196":["להעניק לעבד עברי, שנאמר: \"הענק תעניק, לו\" (דברים טו,יד); וכן אמה עברייה."],"Mishneh Torah, Positive Mitzvot 206":["לאהוב כל בני אדם מבני ברית, שנאמר: \"וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ\" (ויקרא יט, יח)."],"Mishneh Torah, Positive Mitzvot 217":["לחלוץ ליבם, שנאמר: \"וחלצה נעלו מעל רגלו\" (דברים כה,ט)."],"Mishneh Torah, Positive Mitzvot 228":["להיות בית דין שורפין באש, שנאמר: \"באש ישרפו אותו, ואתהן\" (ויקרא כ,יד)."],"Mishneh Torah, Positive Mitzvot 239":["לדון לגנב בתשלומין או במיתה, שנאמר: \"וכי יגנוב\" (ראה שמות כא,לז), \"אם במחתרת\" (שמות כב,א), \"וגונב איש ומכרו\" (שמות כא,טז)."],"Mishneh Torah, Positive Mitzvot 26":["לְבָרַךְ הַכּוֹהֲנִים אֶת יִשְׂרָאֵל, שֶׁנֶּאֱמָר: \"כֹּה תְבָרְכוּ אֶת בְּנֵי יִשְׂרָאֵל\" (במדבר ו, כג)."],"Mishneh Torah, Positive Mitzvot 37":["להיות הכהנים מיטמאין לקרוביהם, ומתאבלין עליהן כשאר ישראל שהן מצווין להתאבל, שנאמר: \"לָהּ יִטַּמָּא\" (ויקרא כא, ג)."],"Mishneh Torah, Positive Mitzvot 48":["להוסיף קרבן ביום הצום, שנאמר: \"וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי...\" (במדבר כט, ז)."],"Mishneh Torah, Positive Mitzvot 59":["לתקוע בחצוצרות על הקרבנות ובשעת הצרות, שנאמר: \"וּתְקַעְתֶּם בַּחֲצוֹצְרֹת\" (במדבר י, י)."],"Mishneh Torah, Positive Mitzvot 7":["לְהִשָּׁבַע בִּשְׁמוֹ, שֶׁנֶּאֱמָר: \"וּבִשְׁמוֹ, תִּשָּׁבֵעַ\" (דברים ו יג, י כ)."],"Mishneh Torah, Positive Mitzvot 80":["לפדות בכור אדם, שנאמר: \"אך פדה תפדה, את בכור האדם\" (במדבר יח,טו)."],"Mishneh Torah, Positive Mitzvot 91":["לשרוף הנותר, שנאמר: \"והנותר, מבשר הזבח--ביום, השלישי, באש, יישרף\" (ויקרא ז,יז)."],"Mishneh Torah, Prayer and the Priestly Blessing 12":["מֹשֶׁה רַבֵּנוּ תִּקֵּן לָהֶם לִישְׂרָאֵל שֶׁיְּהוּ קוֹרִין בַּתּוֹרָה בָּרַבִּים בְּשַׁבָּת וּבְשֵׁנִי וּבַחֲמִישִׁי בְּשַׁחֲרִית כְּדֵי שֶׁלֹּא יִשְׁהוּ שְׁלֹשָׁה יָמִים בְּלֹא שְׁמִיעַת תּוֹרָה. וְעֶזְרָא תִּקֵּן שֶׁיְּהוּ קוֹרִין כֵּן בְּמִנְחָה בְּכָל שַׁבָּת מִשּׁוּם יוֹשְׁבֵי קְרָנוֹת. וְגַם הוּא תִּקֵּן שֶׁיְּהוּ קוֹרִין בְּשֵׁנִי וּבַחֲמִישִׁי שְׁלֹשָׁה בְּנֵי אָדָם וְלֹא יִקְרְאוּ פָּחוֹת מֵעֲשָׂרָה פְּסוּקִים:","וְאֵלּוּ הֵן הַיָּמִים שֶׁקּוֹרִין בָּהֶם בַּתּוֹרָה בְּצִבּוּר. בְּשַׁבָּתוֹת וּבְמוֹעֲדִים וּבְרָאשֵׁי חֳדָשִׁים וּבְתַעֲנִיּוֹת וּבַחֲנֻכָּה וּבְפוּרִים וּבְשֵׁנִי וַחֲמִישִׁי שֶׁבְּכָל שָׁבוּעַ וְשָׁבוּעַ. וְאֵין מַפְטִירִין בַּנְּבִיאִים אֶלָּא בְּשַׁבָּתוֹת וְיָמִים טוֹבִים וְתִשְׁעָה בְּאָב בִּלְבַד:","אֵין קוֹרִין בַּתּוֹרָה בְּצִבּוּר בְּפָחוֹת מֵעֲשָׂרָה אֲנָשִׁים גְּדוֹלִים בְּנֵי חוֹרִין. וְאֵין קוֹרִין פָּחוֹת מֵעֲשָׂרָה פְּסוּקִים. וַיְדַבֵּר עוֹלֶה מִן הַמִּנְיָן. וְלֹא יִהְיוּ הַקּוֹרִין פָּחוֹת מִשְּׁלֹשָׁה אֲנָשִׁים. וְאֵין מַתְחִילִין בְּפָרָשָׁה פָּחוֹת מִשְּׁלֹשָׁה פְּסוּקִים. וְאֵין מְשַׁיְּרִין בְּפָרָשָׁה פָּחוֹת מִשְּׁלֹשָׁה פְּסוּקִים. וְלֹא יִקְרָא הַקּוֹרֵא פָּחוֹת מִשְּׁלֹשָׁה פְּסוּקִים:","שְׁלֹשָׁה שֶׁקָּרְאוּ עֲשָׂרָה פְּסוּקִים שְׁנַיִם קוֹרְאִין שְׁלֹשָׁה שְׁלֹשָׁה וְאֶחָד אַרְבָּעָה. וּבֵין שֶׁהָיָה הַקּוֹרֵא אַרְבָּעָה רִאשׁוֹן אוֹ אַחֲרוֹן אוֹ אֶמְצָעִי הֲרֵי זֶה מְשֻׁבָּח:","כָּל אֶחָד וְאֶחָד מִן הַקּוֹרִין פּוֹתֵחַ סֵפֶר תּוֹרָה וּמַבִּיט לַמָּקוֹם שֶׁהוּא קוֹרֵא בּוֹ. וְאַחַר כָּךְ אוֹמֵר בָּרְכוּ אֶת יְיָ׳‎ הַמְבֹרָךְ וְכָל הָעָם עוֹנִין בָּרוּךְ ה׳‎ הַמְבֹרָךְ לְעוֹלָם וָעֶד . וְחוֹזֵר וּמְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים וְנָתַן לָנוּ אֶת תּוֹרָתוֹ בָּרוּךְ אַתָּה יְיָ׳‎ נוֹתֵן הַתּוֹרָה. וְכָל הָעָם עוֹנִין אָמֵן. וְאַחַר כָּךְ קוֹרֵא עַד שֶׁיַּשְׁלִים לִקְרוֹת וְגוֹלֵל הַסֵּפֶר וּמְבָרֵךְ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר נָתַן לָנוּ תּוֹרָתוֹ תּוֹרַת אֱמֶת וְחַיֵּי עוֹלָם נָטַע בְּתוֹכֵנוּ בָּרוּךְ אַתָּה יְיָ׳‎ נוֹתֵן הַתּוֹרָה:","אֵין הַקּוֹרֵא בַּתּוֹרָה רַשַּׁאי לִקְרוֹת בַּתּוֹרָה עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַצִּבּוּר. קָרָא וְטָעָה אֲפִלּוּ בְּדִקְדּוּק אוֹת אַחַת מַחְזִירִין אוֹתוֹ עַד שֶׁיִּקְרָאֶנָּה בְּדִקְדּוּק. וְלֹא יִקְרְאוּ שְׁנַיִם בַּתּוֹרָה אֶלָּא הָאֶחָד לְבַדּוֹ. קָרָא וְנִשְׁתַּתֵּק יַעֲמֹד אַחֵר תַּחְתָּיו וְיַתְחִיל מִמָּקוֹם שֶׁהִתְחִיל הָרִאשׁוֹן שֶׁנִּשְׁתַּתֵּק וּמְבָרֵךְ בַּסּוֹף:","אֵין הַקּוֹרֵא רַשַּׁאי לִקְרוֹת עַד שֶׁיֹּאמַר לוֹ גָּדוֹל שֶׁבַּצִּבּוּר לִקְרוֹת. וַאֲפִלּוּ חַזַּן הַכְּנֶסֶת אוֹ רֹאשׁ הַכְּנֶסֶת אֵינוֹ קוֹרֵא מֵעַצְמוֹ עַד שֶׁיֹּאמְרוּ לוֹ הַצִּבּוּר אוֹ גָּדוֹל שֶׁבָּהֶם לִקְרוֹת. וְצָרִיךְ אֶחָד לַעֲמֹד עִמּוֹ בִּשְׁעַת קְרִיאָה כְּדֶרֶךְ חַזָּן הָעוֹמֵד עִם הַקּוֹרְאִין:","הַקּוֹרֵא יֵשׁ לוֹ לְדַלֵּג מִמָּקוֹם לְמָקוֹם בְּעִנְיָן אֶחָד כְּגוֹן (ויקרא טז א) ״אַחֲרֵי מוֹת״ וְ(ויקרא כג כז) ״אַךְ בֶּעָשׂוֹר״ שֶׁבְּפָרָשַׁת (ויקרא כא א) ״אֱמֹר אֶל הַכֹּהֲנִים״. וְהוּא שֶׁלֹּא יִקְרָא עַל פֶּה שֶׁאָסוּר לִקְרוֹת שֶׁלֹּא מִן הַכְּתָב אֲפִלּוּ תֵּבָה אַחַת. וְלֹא יִשְׁהֶה בְּדִלּוּג אֶלָּא כְּדֵי שֶׁיַּשְׁלִים הַתֻּרְגְּמָן תַּרְגּוּם הַפָּסוּק:","כֵּיוָן שֶׁהִתְחִיל הַקּוֹרֵא לִקְרוֹת בַּתּוֹרָה אָסוּר לְסַפֵּר אֲפִלּוּ בִּדְבַר הֲלָכָה אֶלָּא הַכּל שׁוֹמְעִין וְשׁוֹתְקִין וּמְשִׂימִין לִבָּם לְמַה שֶּׁהוּא קוֹרֵא שֶׁנֶּאֱמַר (נחמיה ח ג) ״וְאָזְנֵי כָל הָעָם אֶל סֵפֶר הַתּוֹרָה״. וְאָסוּר לָצֵאת מִן הַכְּנֶסֶת בְּשָׁעָה שֶׁהַקּוֹרֵא קוֹרֵא. וּמֻתָּר לָצֵאת בֵּין אִישׁ לְאִישׁ. וּמִי שֶׁהוּא עוֹסֵק בַּתּוֹרָה תָּמִיד וְתוֹרָתוֹ אֻמְנוּתוֹ מֻתָּר לוֹ לַעֲסֹק בְּתַלְמוּד תּוֹרָה בְּשָׁעָה שֶׁהַקּוֹרֵא קוֹרֵא בַּתּוֹרָה:","מִימוֹת עֶזְרָא נָהֲגוּ שֶׁיְּהֵא שָׁם תֻּרְגְּמָן מְתַרְגֵּם לָעָם מַה שֶּׁהַקּוֹרֵא קוֹרֵא בַּתּוֹרָה כְּדֵי שֶׁיָּבִינוּ עִנְיַן הַדְּבָרִים. וְהַקּוֹרֵא קוֹרֵא פָּסוּק אֶחָד בִּלְבַד וְשׁוֹתֵק עַד שֶׁיְּתַרְגֵּם אוֹתוֹ הַתֻּרְגְּמָן וְחוֹזֵר וְקוֹרֵא פָּסוּק שֵׁנִי. וְאֵין הַקּוֹרֵא רַשַּׁאי לִקְרוֹת לַמְתֻרְגְּמָן יוֹתֵר מִפָּסוּק אֶחָד:","אֵין הַקּוֹרֵא רַשַּׁאי לְהַגְבִּיהַּ קוֹלוֹ יוֹתֵר מִן הַמְתַרְגֵּם. וְהַמְתַרְגֵּם לֹא יַגְבִּיהַּ קוֹלוֹ יוֹתֵר מִן הַקּוֹרֵא. וְאֵין הַמְתַרְגֵּם רַשַּׁאי לְתַרְגֵּם עַד שֶׁיִּכְלֶה הַפָּסוּק מִפִּי הַקּוֹרֵא. וְאֵין הַקּוֹרֵא רַשַּׁאי לִקְרוֹת פָּסוּק אַחֵר עַד שֶׁיִּכְלֶה הַתַּרְגּוּם מִפִּי הַתֻּרְגְּמָן. וְאֵין הַתֻּרְגְּמָן נִשְׁעָן לֹא לְעַמּוּד וְלֹא לְקוֹרָה אֶלָּא עוֹמֵד בְּאֵימָה וּבְיִרְאָה. וְלֹא יְתַרְגֵּם מִתּוֹךְ הַכְּתָב אֶלָּא עַל פֶּה. וְאֵין הַקּוֹרֵא רַשַּׁאי לְסַיֵּעַ לַתֻּרְגְּמָן שֶׁלֹּא יֹאמְרוּ תַּרְגּוּם כָּתוּב בַּתּוֹרָה. וְהַקָּטָן מְתַרְגֵּם עַל יְדֵי גָּדוֹל וְאֵין כָּבוֹד לַגָּדוֹל שֶׁיְּתַרְגֵּם עַל יְדֵי קָטָן. וְלֹא יִהְיוּ הַמְתַרְגְּמִין שְׁנַיִם כְּאֶחָד אֶלָּא אֶחָד קוֹרֵא וְאֶחָד מְתַרְגֵּם:","וְלֹא כָּל הַמִּקְרָאוֹת מְתַרְגְּמִינַן בְּצִבּוּר. (בראשית לה כב) ״מַעֲשֵׂה רְאוּבֵן״ וּ(במדבר ו כב כז) ״בִרְכַּת כֹּהֲנִים״ וּמַעֲשֵׂה הָעֵגֶל מִן (שמות לב כא) ״וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן״ עַד (שמות לב כה) ״וַיַּרְא משֶׁה אֶת הָעָם״ וְגוֹ׳‎ וְעוֹד פָּסוּק אֶחָד (שמות לב לה) ״וַיִּגֹּף ה׳‎ אֶת הָעָם״ כֻּלָּם נִקְרָאִין וְלֹא מִתַּרְגְּמִין. וּבְמַעֲשֵׂה אַמְנוֹן בַּמָּקוֹם שֶׁנֶּאֱמַר (שמואל ב יג א) ״אַמְנוֹן בֶּן דָּוִד״ נִקְרָא וְלֹא מִתַּרְגֵּם:","הַמַּפְטִיר בַּנָּבִיא צָרִיךְ לִקְרוֹת בַּתּוֹרָה תְּחִלָּה אֲפִלּוּ שְׁלֹשָׁה פְּסוּקִים. חוֹזֵר וְקוֹרֵא מַה שֶּׁקָּרָא לְפָנָיו. וְלֹא יַפְטִיר בַּנָּבִיא עַד שֶׁיִּגְלל סֵפֶר תּוֹרָה. וְלֹא יִפְחֹת מֵעֶשְׂרִים וְאֶחָד פְּסוּקִים. וְאִם שָׁלֵם הָעִנְיָן בְּפָחוֹת מֵאֵלּוּ אֵינוֹ צָרִיךְ לְהוֹסִיף. וְאִם קָרָא עֲשָׂרָה פְּסוּקִים וְתִרְגְּמָן הַמְתַרְגֵּם דַּיּוֹ וַאֲפִלּוּ לֹא שָׁלֵם הָעִנְיָן. וּבַנָּבִיא אֶחָד קוֹרֵא וַאֲפִלּוּ שְׁנַיִם מְתַרְגְּמִין. וּמְדַלֵּג מֵעִנְיָן לְעִנְיָן אַחֵר. וְאֵינוֹ מְדַלֵּג מִנָּבִיא לְנָבִיא אֶלָּא בִּנְבִיאִים שֶׁל שְׁנֵים עָשָׂר בִּלְבַד. וּבִלְבַד שֶׁלֹּא יְדַלֵּג מִסּוֹף הַסֵּפֶר לִתְחִלָּתוֹ. וְכָל הַמְדַלֵּג לֹא יִשְׁהֶה בְּדִלּוּג אֶלָּא כְּדֵי שֶׁיַּשְׁלִים הַמְתַרְגֵּם תַּרְגּוּמוֹ:","הַקּוֹרֵא בַּנָּבִיא יֵשׁ לוֹ לִקְרוֹת לַתֻּרְגְּמָן שְׁלֹשָׁה פְּסוּקִים וְהַמְתַרְגֵּם מְתַרְגֵּם שְׁלָשְׁתָּן זֶה אַחַר זֶה. וְאִם הָיוּ שְׁלֹשָׁה הַפְּסוּקִים שָׁלֹשׁ פָּרָשִׁיּוֹת לֹא יִקְרָא לַתֻּרְגְּמָן אֶלָּא אֶחָד אֶחָד בִּלְבַד:","הַמַּפְטִיר בַּנָּבִיא מְבָרֵךְ לְפָנָיו בְּרָכָה אַחַת. בָּרוּךְ אַתָּה ה׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בִּנְבִיאִים וְכוּ׳‎. וּמְבָרֵךְ לְאַחֲרָיו אַרְבַּע בְּרָכוֹת. בְּרָכָה רִאשׁוֹנָה חוֹתֵם בָּהּ הָאֵל הַנֶּאֱמָן בְּכָל דְּבָרָיו. שְׁנִיָּה חוֹתֵם בָּהּ בּוֹנֶה יְרוּשָׁלַיִם. שְׁלִישִׁית חוֹתֵם בָּהּ מָגֵן דָּוִד. רְבִיעִית חוֹתֵם בָּהּ עִנְיַן קְדֻשַּׁת הַיּוֹם כְּמוֹ שֶׁחוֹתֵם בַּתְּפִלָּה. וְכֵן אִם חָל רֹאשׁ חֹדֶשׁ לִהְיוֹת בְּשַׁבָּת הַמַּפְטִיר בַּנָּבִיא מַזְכִּיר רֹאשׁ חֹדֶשׁ בִּבְרָכָה זוֹ כְּמוֹ שֶׁמַּזְכִּיר בַּתְּפִלָּה:","כַּמָּה הֵן הַקּוֹרְאִין. בְּשַׁבָּת בְּשַׁחֲרִית קוֹרְאִין שִׁבְעָה. וּבְיוֹם הַכִּפּוּרִים שִׁשָּׁה. וּבְיָמִים טוֹבִים חֲמִשָּׁה. אֵין פּוֹחֲתִין מֵהֶן אֲבָל מוֹסִיפִין עֲלֵיהֶם. בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד קוֹרִין אַרְבָּעָה. בְּשַׁבָּת וּבְיוֹם הַכִּפּוּרִים בְּמִנְחָה וּבְשֵׁנִי וּבַחֲמִישִׁי שֶׁל כָּל הַשָּׁנָה וּבַחֲנֻכָּה וּבְפוּרִים בְּשַׁחֲרִית וּבִימֵי הַתַּעֲנִית בְּשַׁחֲרִית וּבְמִנְחָה קוֹרִין שְׁלֹשָׁה. אֵין פּוֹחֲתִין מִמִּנְיַן זֶה וְאֵין מוֹסִיפִין עֲלֵיהֶן:","אִשָּׁה לֹא תִּקְרָא בְּצִבּוּר מִפְּנֵי כְּבוֹד הַצִּבּוּר. קָטָן הַיּוֹדֵעַ לִקְרוֹת וְיוֹדֵעַ לְמִי מְבָרְכִין עוֹלֶה מִמִּנְיַן הַקּוֹרְאִים. וְכֵן מַפְטִיר עוֹלֶה מֵהַמִּנְיָן שֶׁהֲרֵי הוּא קוֹרֵא בַּתּוֹרָה. וְאִם הִפְסִיק שְׁלִיחַ צִבּוּר בְּקַדִּישׁ בֵּין מַשְׁלִים וּבֵין הַמַּפְטִיר אֵינוֹ עוֹלֶה מִן הַמִּנְיָן. צִבּוּר שֶׁלֹּא הָיָה בָּהֶם יוֹדֵעַ לִקְרוֹת אֶלָּא אֶחָד עוֹלֶה וְקוֹרֵא וְיוֹרֵד וְחוֹזֵר וְקוֹרֵא שְׁנִיָּה וּשְׁלִישִׁית עַד שֶׁיִּגְמֹר מִנְיַן הַקּוֹרְאִים שֶׁל אוֹתוֹ הַיּוֹם:","בְּכָל קְרִיאָה וּקְרִיאָה מֵאֵלּוּ כֹּהֵן קוֹרֵא רִאשׁוֹן וְאַחֲרָיו לֵוִי וְאַחֲרָיו מִיִּשְׂרָאֵל. וּמִנְהָג פָּשׁוּט הוּא הַיּוֹם שֶׁאֲפִלּוּ כֹּהֵן עַם הָאָרֶץ קוֹדֵם לִקְרוֹת לִפְנֵי חָכָם גָּדוֹל יִשְׂרָאֵל. וְכָל מִי שֶׁהוּא גָּדוֹל מֵחֲבֵרוֹ בְּחָכְמָה קֹדֶם לִקְרוֹת. וְהָאַחֲרוֹן שֶׁגּוֹלֵל סֵפֶר תּוֹרָה נוֹטֵל שָׂכָר כְּנֶגֶד הַכּל. לְפִיכָךְ עוֹלֶה וּמַשְׁלִים אֲפִלּוּ גָּדוֹל שֶׁבַּצִּבּוּר:","אֵין שָׁם כֹּהֵן עוֹלֶה יִשְׂרָאֵל. וְלֹא יַעֲלֶה אַחֲרָיו לֵוִי כְּלָל. אֵין שָׁם לֵוִי כֹּהֵן שֶׁקָּרָא רִאשׁוֹן חוֹזֵר וְקוֹרֵא הוּא עַצְמוֹ פַּעַם שְׁנִיָּה בִּמְקוֹם לֵוִי. אֲבָל לֹא יִקְרָא אַחֲרָיו כֹּהֵן אַחֵר שֶׁמָּא יֹאמְרוּ הָרִאשׁוֹן פָּסוּל וּלְפִיכָךְ עוֹלֶה כֹּהֵן אַחֵר. וְכֵן לֹא יִקְרָא לֵוִי אַחַר לֵוִי שֶׁמָּא יֹאמְרוּ אֶחָד מִשְּׁנֵיהֶם פָּסוּל:","כֵּיצַד סֵדֶר הַקְּרִיאָה בַּתּוֹרָה. אַחַר הַתְּפִלָּה כָּל יוֹם שֶׁיֵּשׁ בּוֹ תְּפִלַּת מוּסָף אַחַר שֶׁיִּגְמֹר שְׁלִיחַ צִבּוּר תְּפִלַּת שַׁחֲרִית אוֹמֵר קַדִּישׁ וּמוֹצִיא סֵפֶר תּוֹרָה וְקוֹרֵא לְאֶחָד אֶחָד מִן הַצִּבּוּר וְעוֹלִין וְקוֹרִין בַּתּוֹרָה. וּכְשֶׁגּוֹמְרִין מַחֲזִיר סֵפֶר תּוֹרָה לִמְקוֹמָהּ וְאוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין תְּפִלַּת מוּסָף. וְיָמִים שֶׁיֵּשׁ בָּהֶן מַפְטִיר וּמוּסָף נָהֲגוּ לוֹמַר קַדִּישׁ קֹדֶם שֶׁיַּעֲלֶה הַמַּפְטִיר. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לוֹמַר קַדִּישׁ אַחַר הַמַּפְטִיר:","וּבְמִנְחָה שֶׁל שַׁבָּת וְשֶׁל יוֹם הַכִּפּוּרִים אַחַר שֶׁיִּגְמֹר שְׁלִיחַ צִבּוּר (תהילים קמה א) ״תְּהִלָּה לְדָוִד״ וְסֵדֶר הַיּוֹם אוֹמֵר קַדִּישׁ וּמוֹצִיא סֵפֶר תּוֹרָה וְעוֹלִין וְקוֹרִין בּוֹ וּמַחֲזִירוֹ וְאוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין מִנְחָה. וְכֵן בְּתַעֲנִית קוֹרְאִין בְּמִנְחָה וְאַחַר כָּךְ אוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין תְּפִלַּת מִנְחָה. אֲבָל בְּיוֹם טוֹב לֹא נָהֲגוּ לִקְרוֹת בְּמִנְחָה:","וְיוֹם שֶׁאֵין בּוֹ מוּסָף כְּשֶׁגּוֹמֵר תְּפִלַּת שַׁחֲרִית אוֹמֵר קַדִּישׁ וּמוֹצִיא סֵפֶר תּוֹרָה וְקוֹרְאִין בּוֹ וּמַחֲזִירוֹ וְאוֹמֵר קַדִּישׁ וְאַחַר כָּךְ אוֹמֵר (תהילים קמה א) ״תְּהִלָּה לְדָוִד״ וְסֵדֶר הַיּוֹם כְּדֶרֶךְ שֶׁאוֹמְרִים בְּכָל יוֹם וְאוֹמֵר קַדִּישׁ וְכָל הָעָם נִפְטָרִין:","אֵין קוֹרְאִין בְּחֻמָּשִׁין בְּבָתֵּי כְּנֵסִיּוֹת מִשּׁוּם כְּבוֹד צִבּוּר. וְאֵין גּוֹלְלִין סֵפֶר תּוֹרָה בְּצִבּוּר מִפְּנֵי טֹרַח הַצִּבּוּר שֶׁלֹּא יַטְרִיחַ עֲלֵיהֶם לִהְיוֹתָן עוֹמְדִין עַד שֶׁיִּגְלל סֵפֶר תּוֹרָה. לְפִיכָךְ אִם יִצְטָרְכוּ לִקְרוֹת שְׁנֵי עִנְיָנִים מוֹצִיאִין שְׁנֵי סִפְרֵי תּוֹרָה. וְלֹא יִקְרָא אִישׁ אֶחָד עִנְיָן אֶחָד בִּשְׁתֵּי תּוֹרוֹת שֶׁמָּא יֹאמְרוּ סֵפֶר רִאשׁוֹן פָּגוּם הָיָה וּלְפִיכָךְ קוֹרֵא בַּשֵּׁנִי:","כָּל הַגּוֹלֵל סֵפֶר תּוֹרָה גּוֹלְלוּ מִבַּחוּץ וּכְשֶׁהוּא מְהַדְּקוֹ מְהַדְּקוֹ מִבִּפְנִים. וְצָרִיךְ לְהַעֲמִידוֹ עַל הַתֶּפֶר כְּדֵי שֶׁלֹּא יִקָּרַע. מָקוֹם שֶׁמּוֹצִיאִין סֵפֶר תּוֹרָה אַחַר שֶׁקּוֹרְאִין בּוֹ וּמוֹלִיכִין אוֹתוֹ לְבֵית אַחֵר לְהַצְנִיעוֹ אֵין הַצִּבּוּר רַשָּׁאִין לָצֵאת עַד שֶׁיֵּצֵא סֵפֶר תּוֹרָה וִילַוּוּ אוֹתוֹ וְהֵם אַחֲרָיו עַד הַמָּקוֹם שֶׁמַּצְנִיעִין אוֹתוֹ בּוֹ:"],"Mishneh Torah, Reading the Shema 1":["פַּעֲמַיִם בְּכָל יוֹם קוֹרְאִין קְרִיאַת שְׁמַע, בָּעֶרֶב וּבַבֹּקֶר. שֶׁנֶּאֱמַר (דברים ו ז) ״וּבְשָׁכְבְּךָ וּבְקוּמֶךָ״ בְּשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם שׁוֹכְבִין וְזֶה הוּא לַיְלָה. וּבְשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם עוֹמְדִין וְזֶה הוּא יוֹם:","וּמַה הוּא קוֹרֵא, שְׁלֹשָׁה פָּרָשִׁיּוֹת. אֵלּוּ הֵן (דברים ו ד) ״שְׁמַע״ (דברים יא יג) ״וְהָיָה אִם שָׁמֹעַ״ (במדבר טו לז) ״וַיֹּאמֶר״. וּמַקְדִּימִין לִקְרוֹת פָּרָשַׁת שְׁמַע מִפְּנֵי שֶׁיֵּשׁ בָּהּ יִחוּד הַשֵּׁם וְאַהֲבָתוֹ וְתַלְמוּדוֹ שֶׁהוּא הָעִקָּר הַגָּדוֹל שֶׁהַכּל תָּלוּי בּוֹ. וְאַחֲרֶיהָ וְהָיָה אִם שָׁמֹעַ שֶׁיֵּשׁ בָּהּ צִוּוּי עַל (זְכִירַת) שְׁאָר כָּל הַמִּצְוֹת. וְאַחַר כָּךְ פָּרָשַׁת (במדבר טו לח) ״צִיצִית״ שֶׁגַּם הִיא יֵשׁ בָּהּ צִוּוּי זְכִירַת כָּל הַמִּצְוֹת:","אַף עַל פִּי שֶׁאֵין מִצְוַת צִיצִית נוֹהֶגֶת בַּלַּיְלָה קוֹרְאִין אוֹתָהּ בַּלַּיְלָה מִפְּנֵי שֶׁיֵּשׁ בָּהּ זִכְרוֹן יְצִיאַת מִצְרַיִם וּמִצְוָה לְהַזְכִּיר יְצִיאַת מִצְרַיִם בַּיּוֹם וּבַלַּיְלָה שֶׁנֶּאֱמַר (דברים טז ג) ״לְמַעַן תִּזְכֹּר אֶת יוֹם צֵאתְךָ מֵאֶרֶץ מִצְרַיִם כּל יְמֵי חַיֶּיךָ״. וּקְרִיאַת שָׁלֹשׁ פָּרָשִׁיּוֹת אֵלּוּ עַל סֵדֶר זֶה הִיא הַנִּקְרֵאת קְרִיאַת שְׁמַע:","הַקּוֹרֵא קְרִיאַת שְׁמַע כְּשֶׁהוּא גּוֹמֵר פָּסוּק רִאשׁוֹן אוֹמֵר בְּלַחַשׁ בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד וְחוֹזֵר וְקוֹרֵא כְּדַרְכּוֹ (דברים ו ה) ״וְאָהַבְתָּ אֵת יְיָ׳‎ אֱלֹהֶיךָ״ עַד סוֹפָהּ. וְלָמָּה קוֹרִין כֵּן. מָסֹרֶת הִיא בְּיָדֵינוּ שֶׁבְּשָׁעָה שֶׁקִּבֵּץ יַעֲקֹב אָבִינוּ אֶת בָּנָיו בְּמִצְרַיִם בִּשְׁעַת מִיתָתוֹ צִוָּם וְזֵרְזָם עַל יִחוּד הַשֵּׁם וְעַל דֶּרֶךְ ה׳‎ שֶׁהָלַךְ בָּהּ אַבְרָהָם וְיִצְחָק אָבִיו וְשָׁאַל אוֹתָם וְאָמַר לָהֶם בָּנַי שֶׁמָּא יֵשׁ בָּכֶם פַּסְלוּת מִי שֶׁאֵינוֹ עוֹמֵד עִמִּי בְּיִחוּד הַשֵּׁם כָּעִנְיָן שֶׁאָמַר לָנוּ משֶׁה רַבֵּנוּ (דברים כט יז) ״פֶּן יֵשׁ בָּכֶם אִישׁ אוֹ אִשָּׁה״ וְגוֹ׳‎. עָנוּ כֻּלָּם וְאָמְרוּ (דברים ו ד) ״שְׁמַע יִשְׂרָאֵל יְיָ׳‎ אֱלֹהֵינוּ יְיָ׳‎ אֶחָד״. כְּלוֹמַר שְׁמַע מִמֶּנּוּ אָבִינוּ יִשְׂרָאֵל יְיָ׳‎ אֱלֹהֵינוּ יְיָ׳‎ אֶחָד. פָּתַח הַזָּקֵן וְאָמַר בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. לְפִיכָךְ נָהֲגוּ כָּל יִשְׂרָאֵל לוֹמַר שֶׁבַח שֶׁשִּׁבֵּחַ בּוֹ יִשְׂרָאֵל הַזָּקֵן אַחַר פָּסוּק זֶה:","הַקּוֹרֵא קְרִיאַת שְׁמַע מְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ. בַּיּוֹם מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ. וּבַלַּיְלָה מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ:","בְּרָכָה רִאשׁוֹנָה שֶׁלְּפָנֶיהָ בַּיּוֹם יוֹצֵר אוֹר וּבוֹרֵא חשֶׁךְ וְכוּ׳‎ וּבְרָכָה שְׁנִיָּה אַהֲבַת עוֹלָם אֲהַבְתָּנוּ. וְשֶׁל אַחֲרֶיהָ אֱמֶת וְיַצִּיב. וּבְרָכָה רִאשׁוֹנָה שֶׁלְּפָנֶיהָ בַּלַּיְלָה מַעֲרִיב עֲרָבִים וְכוּ׳‎ שְׁנִיָּה לָהּ אַהֲבַת עוֹלָם בֵּית יִשְׂרָאֵל עַמְּךָ אָהַבְתָּ כוּ׳‎. וּבְרָכָה רִאשׁוֹנָה שֶׁל אַחֲרֶיהָ אֱמֶת וֶאֱמוּנָה. שְׁנִיָּה לָהּ הַשְׁכִּיבֵנוּ:","בְּרָכָה רִאשׁוֹנָה שֶׁלְּפָנֶיהָ בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה פּוֹתֵחַ בָּהּ בְּבָרוּךְ וְחוֹתֵם בָּהּ בְּבָרוּךְ. וּשְׁאָר בִּרְכוֹתֶיהָ חוֹתֵם בְּכָל אַחַת מֵהֶן בְּבָרוּךְ וְאֵין לָהֶם פְּתִיחָה בְּבָרוּךְ. בְּרָכוֹת אֵלּוּ עִם שְׁאָר כָּל הַבְּרָכוֹת הָעֲרוּכוֹת בְּפִי כָּל יִשְׂרָאֵל עֶזְרָא הַסּוֹפֵר וּבֵית דִּינוֹ תִּקְּנוּם וְאֵין אָדָם רַשַּׁאי לִפְחֹת מֵהֶם וְלֹא לְהוֹסִיף עֲלֵיהֶם. מָקוֹם שֶׁהִתְקִינוּ לַחְתֹּם בְּבָרוּךְ אֵינוֹ רַשַּׁאי שֶׁלֹּא לַחְתֹּם. וּמָקוֹם שֶׁהִתְקִינוּ שֶׁלֹּא לַחְתֹּם אֵינוֹ רַשַּׁאי לַחְתֹּם. מָקוֹם שֶׁהִתְקִינוּ שֶׁלֹּא לִפְתֹּחַ בְּבָרוּךְ אֵינוֹ רַשַּׁאי לִפְתֹּחַ. מָקוֹם שֶׁהִתְקִינוּ לִפְתֹּחַ אֵינוֹ רַשַּׁאי שֶׁלֹּא לִפְתֹּחַ. כְּלָלוֹ שֶׁל דָּבָר כָּל הַמְשַׁנֶּה מִמַּטְבֵּעַ שֶׁטָּבְעוּ חֲכָמִים בַּבְּרָכוֹת הֲרֵי זֶה טוֹעֶה וְחוֹזֵר וּמְבָרֵךְ כַּמַּטְבֵּעַ. וְכָל שֶׁאֵינוֹ אוֹמֵר אֱמֶת וְיַצִּיב בְּשַׁחֲרִית וֶאֱמֶת וֶאֱמוּנָה בְּעַרְבִית לֹא יָצָא יְדֵי חוֹבָתוֹ:","הִקְדִּים בְּרָכָה שְׁנִיָּה לִבְרָכָה רִאשׁוֹנָה בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה בֵּין לְפָנֶיהָ בֵּין לְאַחֲרֶיהָ יָצָא לְפִי שֶׁאֵין סֵדֶר בַּבְּרָכוֹת. בְּשַׁחֲרִית פָּתַח יוֹצֵר אוֹר וְסִיֵּם מַעֲרִיב עֲרָבִים לֹא יָצָא. פָּתַח בְּמַעֲרִיב עֲרָבִים וְסִיֵּם בְּיוֹצֵר אוֹר יָצָא. וּבָעֶרֶב פָּתַח בְּמַעֲרִיב עֲרָבִים וְסִיֵּם בְּיוֹצֵר אוֹר לֹא יָצָא. פָּתַח בְּיוֹצֵר אוֹר וְסִיֵּם בְּמַעֲרִיב עֲרָבִים יָצָא. שֶׁכָּל הַבְּרָכוֹת הוֹלְכוֹת אַחַר חֲתִימָתָן:","אֵיזֶה הוּא זְמַן קְרִיאַת שְׁמַע בַּלַּיְלָה. מִצְוָתָהּ מִשְּׁעַת יְצִיאַת הַכּוֹכָבִים עַד חֲצִי הַלַּיְלָה. וְאִם עָבַר וְאִחֵר וְקָרָא עַד שֶׁלֹּא עָלָה עַמּוּד הַשַּׁחַר יָצָא יְדֵי חוֹבָתוֹ שֶׁלֹּא אָמְרוּ עַד חֲצוֹת אֶלָּא כְּדֵי לְהַרְחִיק אָדָם מִן הַפְּשִׁיעָה:","הַקּוֹרֵא קְרִיאַת שְׁמַע שֶׁל עַרְבִית אַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר קֹדֶם הָנֵץ הַחַמָּה לֹא יָצָא יְדֵי חוֹבָתוֹ אֶלָּא אִם כֵּן הָיָה אָנוּס כְּגוֹן שִׁכּוֹר אוֹ חוֹלֶה וְכַיּוֹצֵא בָּהֶן. וְאָנוּס שֶׁקָּרָא בְּעֵת זֶה אֵינוֹ אוֹמֵר הַשְׁכִּיבֵנוּ:","וְאֵי זֶה הוּא זְמַנָּה בַּיּוֹם. מִצְוָתָהּ שֶׁיַּתְחִיל לִקְרוֹת קֹדֶם הָנֵץ הַחַמָּה כְּדֵי שֶׁיִּגְמֹר לִקְרוֹת וּלְבָרֵךְ בְּרָכָה אַחֲרוֹנָה עִם הָנֵץ הַחַמָּה. וְשִׁעוּר זֶה כְּמוֹ [עִשּׂוּר] שָׁעָה קֹדֶם שֶׁתַּעֲלֶה הַשֶּׁמֶשׁ. וְאִם אִחֵר וְקָרָא קְרִיאַת שְׁמַע אַחַר שֶׁתַּעֲלֶה הַשֶּׁמֶשׁ יָצָא יְדֵי חוֹבָתוֹ שֶׁעוֹנָתָהּ עַד סוֹף שָׁלֹשׁ שָׁעוֹת בַּיּוֹם לְמִי שֶׁעָבַר וְאִחֵר:","מִי שֶׁהִקְדִּים וְקָרָא קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית אַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר אַף עַל פִּי שֶׁהִשְׁלִים קֹדֶם שֶׁתָּנֵץ הַחַמָּה יָצָא יְדֵי חוֹבָתוֹ. וּבִשְׁעַת הַדְּחָק כְּגוֹן שֶׁהָיָה מַשְׁכִּים לָצֵאת לַדֶּרֶךְ קוֹרֵא לְכַתְּחִלָּה מִשֶּׁעָלָה עַמּוּד הַשַּׁחַר:","הַקּוֹרֵא אַחַר שָׁלֹשׁ שָׁעוֹת בַּיּוֹם אֲפִלּוּ הָיָה אָנוּס לֹא יָצָא יְדֵי חוֹבַת קְרִיאַת שְׁמַע בְּעוֹנָתוֹ. אֶלָּא הֲרֵי הוּא כְּקוֹרֵא בַּתּוֹרָה. וּמְבָרֵךְ לְפָנֶיהָ וּלְאַחֲרֶיהָ כָּל הַיּוֹם אֲפִלּוּ אִחֵר וְקָרָא אַחַר שָׁלֹשׁ שָׁעוֹת:"],"Mishneh Torah, Red Heifer 10":["הַמְמַלֵא מַיִם לְקִדּוּשׁ אֵינוֹ צָרִיךְ שֶׁיִּהְיֶה הוּא עַצְמוֹ הַמְקַדֵּשׁ וְהַמַּזֶּה אֶלָּא מְקַדֵּשׁ אֶחָד וּמַזֶּה אֶחָד. וְכֵן מְמַלֵּא אָדָם בִּכְלִי וּמְעָרֶה מִכְּלִי לִכְלִי וּמְקַדֵּשׁ בִּכְלִי אַחֵר וּמְעָרֶה הַמַּיִם הַמְקֻדָּשִׁין מִכְּלִי לִכְלִי וּמַזֶּה מִכְּלִי אַחֵר:","מְמַלֵּא אָדָם מַיִם וּמַנִּיחָן אֶצְלוֹ בְּלֹא קִדּוּשׁ כָּל זְמַן שֶׁיִּרְצֶה וְאֵין בְּכָךְ כְּלוּם. וּמוֹלִיכָן מִמָּקוֹם לְמָקוֹם וּמֵעִיר לְעִיר וְנוֹתֵן עֲלֵיהֶן אֵפֶר וּמְקַדְּשָׁן בְּכָל עֵת שֶׁיִּרְצֶה. וְכֵן הַמַּיִם הַמְקֻדָּשִׁין מַנִּיחָן אָדָם אֶצְלוֹ יָמִים וְשָׁנִים וּמַזֶּה מֵהֶן בְּכָל יוֹם שֶׁהוּא צָרִיךְ עַד שֶׁיִּתַּמּוּ וּמוֹלִיכָן מִמָּקוֹם לְמָקוֹם וּמֵעִיר לְעִיר. וּמְשַׁמֵּר אָדָם אֵפֶר פָּרָה אֶצְלוֹ וּמוֹלִיכָהּ מִמָּקוֹם לְמָקוֹם וּמֵעִיר לְעִיר. פַּעַם אַחַת הוֹלִיכוּ כְּלִי שֶׁהָיָה בּוֹ מֵי חַטָּאת בִּסְפִינָה בַּיַּרְדֵּן וְנִמְצָא כְּזַיִת מִן הַמֵּת בְּקַרְקַע הַסְּפִינָה וְנִטְמְאוּ הַמַּיִם. בְּאוֹתָהּ שָׁעָה גָּזְרוּ בֵּית דִּין הַגָּדוֹל שֶׁאֵין מַעֲבִירִין מֵי חַטָּאת וְלֹא אֵפֶר חַטָּאת בְּנָהָר וּבִסְפִינָה וְלֹא יְשִׁיטֵם עַל פְּנֵי הַמַּיִם. וְלֹא יַעֲמֹד בְּצַד הַנָּהָר מִכָּאן וְיִזְרְקֵם לַצַּד הַשֵּׁנִי. אֲבָל עוֹבֵר הוּא אָדָם בְּמַיִם עַד צַוָּארוֹ וּבְיָדוֹ אֵפֶר פָּרָה אוֹ מַיִם מְקֻדָּשִׁין. וְכֵן אָדָם וְכֵלִים הָרֵיקָנִים שֶׁהֵן טְהוֹרִין לְחַטָּאת וּמַיִם שֶׁנִּתְמַלְּאוּ לְחַטָּאת וַעֲדַיִן לֹא נִתְקַדְּשׁוּ מַעֲבִירִין אוֹתָם בְּנָהָר בִּסְפִינָה:","מַעֲבִירִין מַיִם מְקֻדָּשִׁין בִּסְפִינָה בַּיָּם הַגָּדוֹל וְשָׁטִין [בָּהֶם] עַל פְּנֵי הַמַּיִם. שֶׁלֹּא גָּזְרוּ אֶלָּא עַל הַמַּיִם הַמְקֻדָּשִׁין וְעַל הָאֵפֶר בְּנָהָר:","הַמּוֹלִיךְ מַיִם לְקַדְּשָׁן וְאֵין צָרִיךְ לוֹמַר מַיִם שֶׁנִּתְקַדְּשׁוּ לֹא יַפְשִׁיל הַכְּלִי לַאֲחוֹרָיו אֶלָּא לְפָנָיו שֶׁנֶּאֱמַר (במדבר יט ט) \"לְמִשְׁמֶרֶת לְמֵי נִדָּה\" בִּזְמַן שֶׁהֵן שְׁמוּרִין הֵן מֵי נִדָּה וְאִם לָאו פְּסוּלִין. מִלֵּא שְׁתֵּי חָבִיּוֹת נוֹתֵן אַחַת לְפָנָיו וְאַחַת לַאֲחוֹרָיו מִפְּנֵי שֶׁאִי אֶפְשָׁר:","מֵי חַטָּאת שֶׁשְּׁקָלָן בְּמִשְׁקָל אִם הִסִּיחַ דַּעְתּוֹ פְּסוּלִין וְאִם לָאו כְּשֵׁרִין. אֲבָל אִם שָׁקַל דְּבָרִים אֲחֵרִים בְּמֵי חַטָּאת הוֹאִיל וַעֲשָׂאָן מִשְׁקלֶת פְּסָלָן שֶׁאֵין זוֹ מִשְׁמֶרֶת. כָּל אֵלּוּ הַטְּהוֹרִים שֶׁמְּמַלְּאִין אוֹ שֶׁמְּקַדְּשִׁין אוֹ שֶׁמַּזִּין וְכֵן כָּל הַכֵּלִים שֶׁמְּמַלְּאִין וּמְקַדְּשִׁין מֵהֶם וְשֶׁמַּזִּין מֵהֶן אִם הָיוּ טְבוּלֵי יוֹם אַף עַל פִּי שֶׁלֹּא הֶעֱרִיב שִׁמְשָׁן הֲרֵי אֵלּוּ כְּשֵׁרִים. שֶׁכָּל מַעֲשֵׂה הַפָּרָה וְהַמִּלּוּי וְהַקִּדּוּשׁ וְהַהַזָּיָה כָּשֵׁר בִּטְבוּל יוֹם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִפְּנֵי הַצְּדוֹקִין מְטַמְּאִין אֶת כָּל כְּלֵי שֶׁטֶף וּמַטְבִּילִין אוֹתָן וְאַחַר כָּךְ מִשְׁתַּמְּשִׁין בָּהֶן בְּמֵי חַטָּאת:","הַכּל כְּשֵׁרִין לְהַזּוֹת חוּץ מֵאִשָּׁה וְטֻמְטוּם וְאַנְדְּרוֹגִינוּס [וְחֵרֵשׁ שׁוֹטֶה] וְקָטָן שֶׁאֵין בּוֹ דַּעַת. אֲבָל קָטָן שֶׁיֵּשׁ בּוֹ דַּעַת כָּשֵׁר לְהַזּוֹת וְהֶעָרֵל כָּשֵׁר לְהַזּוֹת שֶׁאֵין הֶעָרֵל טָמֵא. קָטָן שֶׁיֵּשׁ בּוֹ דַּעַת שֶׁהִזָּה וְהָאִשָּׁה מְסַעֲדָּתוֹ כְּגוֹן שֶׁאָחֲזָה לוֹ הַמַּיִם בְּיָדוֹ הַזָּאָתוֹ כְּשֵׁרָה וּבִלְבַד שֶׁלֹּא תֶּאֱחֹז בְּיָדוֹ בִּשְׁעַת הַזָּאָה. וְאִם אָחֲזָה בְּיָדוֹ בִּשְׁעַת הַזָּיָתוֹ פְּסוּלָה:","הַמַּזֶּה צָרִיךְ לְכַוֵּן וּלְהַזּוֹת עַל הַטָּמֵא לְטַהֲרוֹ וְאִם הִזָּה שֶׁלֹּא בְּכַוָּנָה הַזָּאָתוֹ פְּסוּלָה. אֲבָל זֶה שֶׁמַּזִּין עָלָיו אֵינוֹ צָרִיךְ כַּוָּנָה אֶלָּא מַזִּין עַל הָאָדָם לְדַעְתּוֹ וְשֶׁלֹּא לְדַעְתּוֹ. הַמִּתְכַּוֵּן לְהַזּוֹת לְפָנָיו וְהִזָּה לַאֲחוֹרָיו לַאֲחוֹרָיו וְהִזָּה לְפָנָיו הַזָּיָתוֹ פְּסוּלָה. נִתְכַּוֵּן לְהַזּוֹת לְפָנָיו וְהִזָּה לַצְּדָדִין שֶׁל פָּנָיו הַזָּיָתוֹ כְּשֵׁרָה:","הַמַּזֶּה אֵינוֹ צָרִיךְ טְבִילָה לְכָל הַזָּיָה אֶלָּא טוֹבֵל אֶת הָאֵזוֹב וּמַזֶּה הַזָּיָה אַחַר הַזָּיָה עַד שֶׁיִּגָּמְרוּ הַמַּיִם. וּמַזֶּה הַזָּיָה אַחַת עַל כַּמָּה בְּנֵי אָדָם אוֹ עַל כַּמָּה כֵּלִים כְּאַחַת אֲפִלּוּ מֵאָה. כָּל שֶּׁנָּגַע בּוֹ מִן הַמַּיִם כָּל שֶׁהוּא טָהוֹר וְהוּא שֶׁיִּתְכַּוֵּן הַמַּזֶּה לְהַזּוֹת עָלָיו. טָבַל אֶת הָאֵזוֹב וְנִתְכַּוֵּן לְהַזּוֹת עַל דָּבָר שֶׁמְּקַבֵּל טֻמְאָה אוֹ עַל הָאָדָם וְהִזָּה מֵאוֹתָהּ טְבִילָה עַל דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה אוֹ עַל הַבְּהֵמָה. אִם נִשְׁאֲרוּ מַיִם בָּאֵזוֹב אֵינוֹ צָרִיךְ לַחְזֹר וּלְהַטְבִּיל אֶלָּא מַזֶּה מִן הַשְּׁאָר עַל הָאָדָם אוֹ עַל הַכֵּלִים הַטְּמֵאִים שֶׁהֲרֵי תְּחִלַּת טְבִילָתוֹ כְּשֵׁרָה הָיְתָה. אֲבָל אִם טָבַל אֶת הָאֵזוֹב לְהַזּוֹת עַל דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה אוֹ עַל הַבְּהֵמָה וְהִזָּה עַל הָאָדָם אוֹ עַל הַכְּלִי הַטָּמֵא הַזָּיָתוֹ פְּסוּלָה עַד שֶׁיַּחְזֹר וְיִטְבּל פַּעַם שְׁנִיָּה וְיִתְכַּוֵּן לְהַזּוֹת עַל הָאָדָם אוֹ עַל דָּבָר הַמְקַבֵּל טֻמְאָה:","הִטְבִּיל אֶת הָאֵזוֹב וְנִתְכַּוֵּן לְהַזּוֹת עַל דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה הַמַּיִם הַמְנַטְּפִים כְּשֵׁרִין לְפִיכָךְ אִם נָטְפוּ בִּכְלִי וְחָזַר וְהִטְבִּיל בָּהֶן אֶת הָאֵזוֹב בְּכַוָּנָה לְהַזּוֹת עַל דָּבָר הַמְקַבֵּל טֻמְאָה הַזָּיָתוֹ כְּשֵׁרָה:","מֵי חַטָּאת שֶׁנִּתְמַעֲטוּ טוֹבֵל בָּהֶן אֲפִלּוּ רָאשֵׁי גִּבְעוֹלִין וּמַזֶּה וּבִלְבַד שֶׁלֹּא יְסַפֵּג. צְלוֹחִית שֶׁפִּיהָ צַר טוֹבֵל וּמַעֲלֶה כְּדַרְכּוֹ וּמַזֶּה וְאֵינוֹ צָרִיךְ לְהִזָּהֵר שֶׁמָּא יִגַּע בְּצִדֵּי הַכְּלִי בְּפַעַם שְׁנִיָּה:"],"Mishneh Torah, Red Heifer 8":["מִי שֶׁהָיוּ מֵימָיו עַל כְּתֵפוֹ וְעָמַד וְהוֹרָה הוֹרָאָה לַאֲחֵרִים אוֹ שֶׁדָּן דִּין אוֹ שֶׁחָלְצָה בְּפָנָיו אוֹ מֵאֲנָה אוֹ שֶׁהֶרְאָה לַאֲחֵרִים אֶת הַדֶּרֶךְ אוֹ שֶׁהָרַג אֶת נָחָשׁ אוֹ עַקְרָב אוֹ נָטַל אֳכָלִין מִן הַשּׁוּק לְהַצְנִיעָם הֲרֵי הַמַּיִם פְּסוּלִין שֶׁהֲרֵי נִתְעַסֵּק בְּדָבָר אַחֵר קֹדֶם שֶׁיִּתֵּן הָאֵפֶר עַל הַמַּיִם. אֲבָל אִם נָטַל הָאֳכָלִין לְאָכְלָן וַאֲכָלָן כְּשֶׁהוּא מְהַלֵּךְ אוֹ שֶׁהָרַג נָחָשׁ אוֹ עַקְרָב הַמְעַכְּבִין אוֹתוֹ הֲרֵי הַמַּיִם כְּשֵׁרִים שֶׁזֶּה מִצֹּרֶךְ הוֹלָכַת הַמַּיִם. זֶה הַכְּלָל כָּל דָּבָר שֶׁהוּא מִשּׁוּם מְלָאכָה שֶׁעָשָׂהוּ קֹדֶם מַתַּן הָאֵפֶר בֵּין עָמַד בֵּין לֹא עָמַד פָּסַל וְדָבָר שֶׁאֵינוֹ מִשּׁוּם מְלָאכָה אִם לֹא עָמַד כְּשֵׁרִים וְאִם עָמַד פָּסַל. הָיָה מְהַלֵּךְ בְּמַיִם וּפָרַץ בִּשְׁעַת הִלּוּכוֹ מָקוֹם שֶׁיֵּלֵךְ בּוֹ אַף עַל פִּי שֶׁפָּרַץ עַל מְנָת לִגְדֹּר כְּשֵׁרִים. וְאִם גָּדַר קֹדֶם שֶׁיִּתֵּן הָאֵפֶר פְּסוּלִין. וְכֵן אִם קָצָה פֵּרוֹת לֶאֱכל אַף עַל פִּי שֶׁכַּוָּנָתוֹ לְהַקְצוֹת אֶת הַשְּׁאָר כְּשֵׁרִין. וְאִם הִקְצָה קֹדֶם מַתַּן הָאֵפֶר פָּסוּל:","הָיָה אוֹכֵל בִּשְׁעַת הוֹלָכַת הַמַּיִם וְהוֹתִיר וְזָרַק מַה שֶּׁהוֹתִיר לְתַחַת הַתְּאֵנָה אוֹ לְתַחַת הַמֻּקְצֶה אִם נִתְכַּוֵּן שֶׁלֹּא יֹאבְדוּ הַפֵּרוֹת הֲרֵי הַמַּיִם פְּסוּלִין שֶׁהֲרֵי עָשָׂה מְלָאכָה. וְאִם זְרָקָן לְפִי שֶּׁאֵין לוֹ צֹרֶךְ בָּהֶן הֲרֵי הַמַּיִם כְּשֵׁרִין. הַמְמַלֵּא מַיִם לְקַדְּשָׁן וּמְסָרָן לְאַחֵר לְשָׁמְרָן וְעָשׂוּ הַבְּעָלִים מְלָאכָה לֹא נִפְסְלוּ הַמַּיִם שֶׁהֲרֵי מְסָרָן לְשׁוֹמֵר. וְאִם עָשָׂה הַשּׁוֹמֵר מְלָאכָה פְּסָלָן שֶׁהֲרֵי הֵן בִּרְשׁוּתוֹ וְהוּא נִכְנַס תַּחַת הַבְּעָלִים. הָיוּ שְׁנַיִם שׁוֹמְרִין אֶת הַמַּיִם וְעָשָׂה אֶחָד מֵהֶן מְלָאכָה הַמַּיִם כְּשֵׁרִים שֶׁהֲרֵי הַשֵּׁנִי מְשַׁמֵּר. חָזַר הָרִאשׁוֹן לִשְׁמֹר וְעָמַד הַשֵּׁנִי וְעָשָׂה מְלָאכָה הַמַּיִם כְּשֵׁרִים עַד שֶׁיַּעֲשׂוּ כָּל הַשּׁוֹמְרִין מְלָאכָה כְּאַחַת:","הַמְקַדֵּשׁ בְּאַחַת יָדוֹ וְעָשָׂה מְלָאכָה בַּשְּׁנִיָּה. אִם לְעַצְמוֹ קִדֵּשׁ פָּסַל שֶׁהֲרֵי עָשָׂה מְלָאכָה קֹדֶם מַתַּן אֵפֶר בְּמַיִם. וְאִם לַחֲבֵרוֹ קִדֵּשׁ הַמַּיִם כְּשֵׁרִים שֶׁאֵין זֶה פּוֹסֵל מֵימָיו שֶׁל חֲבֵרוֹ בַּמְּלָאכָה שֶׁעָשָׂה. שֶׁאֵין הַמְּלָאכָה פּוֹסֶלֶת בְּקִדּוּשׁ אֶלָּא בְּמַיִם. וְהוּא שֶׁיִּהְיֶה הָעוֹשֶׂה הַשּׁוֹמֵר אוֹ הַבְּעָלִים:","הַמְקַדֵּשׁ לְעַצְמוֹ וּלְאַחֵר כְּאַחַת. שֶׁלּוֹ פָּסוּל שֶׁהֲרֵי נִפְסְלוּ הַמַּיִם שֶׁל עַצְמוֹ בְּעֵסֶק שֶׁנִּתְעַסֵּק בְּקִדּוּשׁ חֲבֵרוֹ. אֲבָל אִם קִדֵּשׁ לִשְׁנַיִם כְּאַחַת שְׁנֵיהֶם כְּשֵׁרִין שֶׁאֵין מְלַאכְתּוֹ פּוֹסֶלֶת מֵי אֲחֵרִים:","הַמְמַלֵּא לְעַצְמוֹ בִּשְׁתֵּי יָדָיו כְּאַחַת בְּקִדּוּשׁ אֶחָד פָּסוּל. בִּשְׁנֵי קִדּוּשִׁים כָּשֵׁר. קִדֵּשׁ לְעַצְמוֹ בִּשְׁתֵּי יָדָיו כְּאַחַת בְּקִדּוּשׁ אֶחָד כְּשֵׁרִים בִּשְׁנֵי קִדּוּשִׁין פְּסוּלִין. מִלֵּא וְקִדֵּשׁ בִּשְׁתֵּי יָדָיו כְּאַחַת לְעַצְמוֹ שְׁנֵיהֶן פְּסוּלִין. מִלֵּא לְאַחֵר בִּשְׁתֵּי יָדָיו כְּאַחַת בְּקִדּוּשׁ אֶחָד כָּשֵׁר בִּשְׁנֵי קִדּוּשִׁין פְּסוּלִין. קִדֵּשׁ לְאַחֵר בִּשְׁתֵּי יָדָיו כְּאַחַת בֵּין בְּקִדּוּשׁ אֶחָד בֵּין בִּשְׁנֵי קִדּוּשִׁין שְׁנֵיהֶן כְּשֵׁרִים. מִלֵּא וְקִדֵּשׁ בִּשְׁתֵּי יָדָיו כְּאַחַת לְאַחֵר הַמִּלּוּי פָּסוּל וְהַקִּדּוּשׁ כָּשֵׁר. זֶה הַכְּלָל כָּל מִלּוּי שֶׁעָשָׂה עִמּוֹ מְלָאכָה בֵּין שֶׁמִּלֵּא לְעַצְמוֹ בֵּין שֶׁמִּלֵּא לְאַחֵר פָּסוּל. וְכָל מַיִם שֶׁנִּתְמַלְּאוּ כְּהִלְכָתָן וְעָשָׂה מְלָאכָה קֹדֶם שֶׁיִּתֵּן אֶת הָאֵפֶר אִם הָיוּ הַמַּיִם שֶׁלּוֹ הֲרֵי הֵן פְּסוּלִין. וְאִם הָיוּ שֶׁל אַחֵר כְּשֵׁרִין. וְכָל דָּבָר שֶׁבְּיָדוֹ וְעָשָׂה מְלָאכָה בֵּין שֶׁיֵּשׁ שָׁם שׁוֹמֵר שֶׁאֵינוֹ עוֹשֶׂה מְלָאכָה בֵּין שֶׁאֵין [שָׁם] שׁוֹמֵר פָּסוּל. וְדָבָר שֶׁאֵינוֹ בְּיָדוֹ וְעָשָׂה מְלָאכָה אִם יֵשׁ [שָׁם] שׁוֹמֵר לֹא פָּסַל. אִם אֵין שָׁם שׁוֹמֵר פָּסַל:","הָאוֹמֵר לַחֲבֵרוֹ קַדֵּשׁ לִי וַאֲקַדֵּשׁ לְךָ וְקִדְּשׁוּ זֶה לָזֶה הָרִאשׁוֹן כָּשֵׁר וְהַשֵּׁנִי פָּסוּל שֶׁהֲרֵי קִדֵּשׁ בְּשָׂכָר. אָמַר לוֹ מַלֵּא לִי וַאֲמַלֵּא לְךָ וּמִלְּאוּ זֶה לָזֶה הָרִאשׁוֹן פָּסוּל הוֹאִיל וְכַוָּנָתוֹ שֶׁיְּמַלֵּא לוֹ חֲבֵרוֹ. חֵלֶף מִלּוּי זֶה הֲרֵי זֶה כִּמְמַלֵּא לוֹ וּלְאַחֵר שֶׁהֵן פְּסוּלִין. וְהַשֵּׁנִי כָּשֵׁר שֶׁהַמִּלּוּי בְּשָׂכָר מֻתָּר וַהֲרֵי לֹא עָשָׂה מְלָאכָה אַחַר שֶׁמִּלֵּא וְאֵין בְּכַוָּנָתוֹ מִלּוּי אַחֵר:","הָאוֹמֵר לַחֲבֵרוֹ קַדֵּשׁ לִי וַאֲמַלֵּא לְךָ שְׁנֵיהֶן כְּשֵׁרִין שֶׁהַמְּלָאכָה אֵינָהּ פּוֹסֶלֶת הַקִּדּוּשׁ וְהַמִּלּוּי בְּשָׂכָר מֻתָּר. מַלֵּא לִי וַאֲקַדֵּשׁ לְךָ שְׁנֵיהֶן פְּסוּלִין. זֶה שֶׁמִּלֵּא בַּתְּחִלָּה פָּסוּל שֶׁהֲרֵי הוּא כִּמְמַלֵּא וּמְקַדֵּשׁ כְּאַחַת וּפָסַל הַמַּיִם בַּמְּלָאכָה. וְזֶה שֶׁקִּדֵּשׁ בָּאַחֲרוֹנָה פָּסוּל שֶׁהֲרֵי קִדֵּשׁ בְּשָׂכָר וּכְאִלּוּ הֶחְזִיר חוֹב שֶׁעָלָיו:","הַהוֹלֵךְ לְקַדֵּשׁ הֲרֵי זֶה נוֹטֵל אֶת הַמַּפְתֵּחַ וּפוֹתֵחַ לְהוֹצִיא הָאֵפֶר. וְנוֹטֵל קַרְדֹּם אִם צָרִיךְ לַחְפֹּר בּוֹ אֵפֶר הַפָּרָה. וְנוֹטֵל סֻלָּם וּמוֹלִיךְ מִמָּקוֹם לְמָקוֹם לְהָבִיא הָאֵפֶר וְכָשֵׁר. וְאִם מִשֶּׁנָּטַל הָאֵפֶר לְקַדֵּשׁ בּוֹ כִּסָּה הַכְּלִי שֶׁהָיָה בּוֹ הָאֵפֶר. אוֹ שֶׁהֵגִיף אֶת הַדָּלֶת אוֹ שֶׁזָּקַף אֶת הַכְּלִי בָּאָרֶץ קֹדֶם שֶׁיַּשְׁלִיךְ הָאֵפֶר לַמַּיִם פָּסַל הַמַּיִם. אֲבָל הָאֵפֶר כָּשֵׁר לְקַדֵּשׁ בּוֹ מַיִם אֲחֵרִים. זָקַף אֶת הַכְּלִי שֶׁיֵּשׁ בּוֹ הָאֵפֶר בְּיָדוֹ כְּדֵי שֶׁלֹּא יִתְפַּזֵּר כְּשֵׁרִים מִפְּנֵי שֶׁאִי אֶפְשָׁר שֶׁהֲרֵי אִם הִנִּיחוֹ בָּאָרֶץ פָּסַל. וְאִם כִּסָּהוּ פָּסַל. נָטַל אֶת הָאֵפֶר וְרָאָה שֶׁהוּא מְרֻבֶּה וְהֶחְזִיר מִמֶּנּוּ כָּשֵׁר. נָתַן הָאֵפֶר עַל הַמַּיִם וְרָאָה שֶׁהוּא מְרֻבֶּה וְנָטַל מִמֶּנּוּ לְקַדֵּשׁ מַיִם אֲחֵרִים כָּשֵׁר. קִרְסֵם עֲלֵה זַיִת לַחְתּוֹת בּוֹ הָאֵפֶר אִם בִּשְׁבִיל שֶׁלֹּא יַחֲזִיק אֵפֶר הַרְבֵּה פָּסַל וְאִם בִּשְׁבִיל שֶׁיִּכָּנֵס הָאֵפֶר בַּכְּלִי כָּשֵׁר:"],"Mishneh Torah, Rest on a Holiday 1":["שֵׁשֶׁת יָמִים הָאֵלּוּ שֶׁאֲסָרָן הַכָּתוּב בַּעֲשִׂיַּת מְלָאכָה שֶׁהֵן רִאשׁוֹן וּשְׁבִיעִי שֶׁל פֶּסַח וְרִאשׁוֹן וּשְׁמִינִי שֶׁל חַג הַסֻּכּוֹת וּבְיוֹם חַג הַשָּׁבוּעוֹת וּבְאֶחָד לַחֹדֶשׁ הַשְּׁבִיעִי הֵן הַנִּקְרָאִין יָמִים טוֹבִים. וּשְׁבִיתַת כֻּלָּן שָׁוָה שֶׁהֵן אֲסוּרִין בְּכָל מְלֶאכֶת עֲבוֹדָה חוּץ מִמְּלָאכָה שֶׁהִיא לְצֹרֶךְ אֲכִילָה שֶׁנֶּאֱמַר (שמות יב טז) \"אַךְ אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ\" וְגוֹ':","כָּל הַשּׁוֹבֵת מִמְּלֶאכֶת עֲבוֹדָה בְּאֶחָד מֵהֶן הֲרֵי קִיֵּם מִצְוַת עֲשֵׂה שֶׁהֲרֵי נֶאֱמַר בָּהֶן (ויקרא כג כד) (ויקרא כג לט) \"שַׁבָּתוֹן\" כְּלוֹמַר שְׁבֹת. וְכָל הָעוֹשֶׂה בְּאֶחָד מֵהֶן מְלָאכָה שֶׁאֵינָהּ לְצֹרֶךְ אֲכִילָה כְּגוֹן שֶׁבָּנָה אוֹ הָרַס אוֹ אָרַג וְכַיּוֹצֵא בָּאֵלּוּ הֲרֵי בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה. שֶׁנֶּאֱמַר כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ. (שמות יב טז) \"כָּל מְלָאכָה לֹא יֵעָשֶׂה בָהֶם\". וְאִם עָשָׂה בְּעֵדִים וְהַתְרָאָה לוֹקֶה מִן הַתּוֹרָה:","הָעוֹשֶׂה אֲבוֹת מְלָאכוֹת הַרְבֵּה בְּיוֹם טוֹב בְּהַתְרָאָה אַחַת כְּגוֹן שֶׁזָּרַע וּבָנָה וְסָתַר וְאָרַג בְּהַתְרָאָה אַחַת אֵינוֹ לוֹקֶה אֶלָּא אַחַת. חִלּוּק מְלָאכוֹת לְשַׁבָּת וְאֵין חִלּוּק מְלָאכוֹת לְיוֹם טוֹב:","כָּל מְלָאכָה שֶׁחַיָּבִין עָלֶיהָ בְּשַׁבָּת אִם עָשָׂה אוֹתָהּ בְּיוֹם טוֹב שֶׁלֹּא לְצֹרֶךְ אֲכִילָה לוֹקֶה חוּץ מִן הַהוֹצָאָה מֵרְשׁוּת לִרְשׁוּת וְהַהַבְעָרָה שֶׁמִּתּוֹךְ שֶׁהֻתְּרָה הוֹצָאָה בְּיוֹם טוֹב לְצֹרֶךְ אֲכִילָה הֻתְּרָה שֶׁלֹּא לְצֹרֶךְ אֲכִילָה. לְפִיכָךְ מֻתָּר בְּיוֹם טוֹב לְהוֹצִיא קָטָן אוֹ סֵפֶר תּוֹרָה אוֹ מַפְתֵּחַ וְכַיּוֹצֵא בְּאֵלּוּ מֵרְשׁוּת לִרְשׁוּת. וְכֵן מֻתָּר לְהַבְעִיר אַף עַל פִּי שֶׁאֵינוֹ לְצֹרֶךְ אֲכִילָה. וּשְׁאָר מְלָאכוֹת כָּל שֶׁיֵּשׁ בּוֹ צֹרֶךְ אֲכִילָה מֻתָּר כְּגוֹן שְׁחִיטָה וַאֲפִיָּה וְלִישָׁה וְכַיּוֹצֵא בָּהֶן. וְכָל שֶׁאֵין בָּהֶן צֹרֶךְ אֲכִילָה אָסוּר כְּגוֹן כְּתִיבָה וַאֲרִיגָה וּבִנְיָן וְכַיּוֹצֵא בָּהֶן:","כָּל מְלָאכָה שֶׁאֶפְשָׁר לְהֵעָשׂוֹת מֵעֶרֶב יוֹם טוֹב וְלֹא יִהְיֶה בָּהּ הֶפְסֵד וְלֹא חֶסְרוֹן אִם נַעֲשֵׂית מִבָּעֶרֶב אָסְרוּ חֲכָמִים לַעֲשׂוֹת אוֹתָהּ בְּיוֹם טוֹב אַף עַל פִּי שֶׁהִיא לְצֹרֶךְ אֲכִילָה. וְלָמָּה אָסְרוּ דָּבָר זֶה גְּזֵרָה שֶׁמָּא יָנִיחַ אָדָם מְלָאכוֹת שֶׁאֶפְשָׁר לַעֲשׂוֹתָן מֵעֶרֶב יוֹם טוֹב לְיוֹם טוֹב וְנִמְצָא יוֹם טוֹב כֻּלּוֹ הוֹלֵךְ בַּעֲשִׂיַּת אוֹתָן מְלָאכוֹת וְיִמָּנַע מִשִּׂמְחַת יוֹם טוֹב וְלֹא יִהְיֶה לוֹ פְּנַאי לֶאֱכל:","וּמִזֶּה הַטַּעַם עַצְמוֹ לֹא אָסְרוּ הַהוֹצָאָה בְּיוֹם טוֹב וְאַף עַל פִּי שֶׁכָּל הַהוֹצָאָה הִיא מְלָאכָה שֶׁאֶפְשָׁר לַעֲשׂוֹתָהּ מֵעֶרֶב יוֹם טוֹב וְלָמָּה לֹא אֲסָרוּהָ כְּדֵי לְהַרְבּוֹת בְּשִׂמְחַת יוֹם טוֹב וְיוֹלִיךְ וְיָבִיא כָּל מַה שֶּׁיִּרְצֶה וְיַשְׁלִים חֲפָצָיו וְלֹא יִהְיֶה כְּמִי שֶׁיָּדָיו אֲסוּרוֹת. אֲבָל שְׁאָר מְלָאכוֹת שֶׁאֶפְשָׁר לַעֲשׂוֹתָן מֵעֶרֶב יוֹם טוֹב הוֹאִיל וְיֵשׁ בָּהֶן עֵסֶק אֵין עוֹשִׂין אוֹתָן בְּיוֹם טוֹב:","כֵּיצַד. אֵין קוֹצְרִין וְלֹא דָּשִׁין וְלֹא זוֹרִין וְלֹא בּוֹרְרִין וְלֹא טוֹחֲנִין אֶת הַחִטִּים וְלֹא מְרַקְּדִין בְּיוֹם טוֹב שֶׁכָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶם אֶפְשָׁר לַעֲשׂוֹתָן מֵעֶרֶב יוֹם טוֹב וְאֵין בְּכָךְ הֶפְסֵד וְלֹא חֶסְרוֹן:","אֲבָל לָשִׁין וְאוֹפִין וְשׁוֹחֲטִין וּמְבַשְּׁלִין בְּיוֹם טוֹב. שֶׁאִם עָשָׂה אֵלּוּ מִבָּעֶרֶב יֵשׁ בְּכָךְ הֶפְסֵד אוֹ חֶסְרוֹן טַעַם. שֶׁאֵין לֶחֶם חַם אוֹ תַּבְשִׁיל שֶׁבִּשֵּׁל הַיּוֹם כְּלֶחֶם שֶׁנֶּאֱפָה מֵאֶמֶשׁ וּכְתַבְשִׁיל שֶׁנִתְבַּשֵּׁל מֵאֶמֶשׁ. וְלֹא בָּשָׂר שֶׁנִּשְׁחַט הַיּוֹם כְּבָשָׂר שֶׁנִּשְׁחַט מֵאֶמֶשׁ. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ. וְכֵן מַכְשִׁירֵי אֹכֶל נֶפֶשׁ שֶׁיֵּשׁ בָּהֶן חֶסְרוֹן אִם נַעֲשׂוּ מִבָּעֶרֶב עוֹשִׂין אוֹתָן בְּיוֹם טוֹב. כְּגוֹן שְׁחִיקַת תַּבְלִין וְכַיּוֹצֵא בָּהֶן:","אֵין אוֹפִין וּמְבַשְּׁלִין בְּיוֹם טוֹב מַה שֶּׁיֵּאָכֵל בְּחל. וְלֹא הֻתְּרָה מְלָאכָה שֶׁהִיא לְצֹרֶךְ אֲכִילָה אֶלָּא כְּדֵי לֵהָנוֹת בָּהּ בְּיוֹם טוֹב. עָשָׂה כְּדֵי לֶאֱכל בְּיוֹם טוֹב וְהוֹתִיר מֻתָּר לֶאֱכל הַמּוֹתָר בְּחל:","מְמַלְּאָה אִשָּׁה קְדֵרָה בָּשָׂר אַף עַל פִּי שֶׁאֵינָהּ צְרִיכָה אֶלָּא לַחֲתִיכָה אַחַת. מְמַלֵּא נַחְתּוֹם חָבִית שֶׁל מַיִם אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ אֶלָּא לְקִיתוֹן אֶחָד. וּמְמַלְּאָה אִשָּׁה תַּנּוּר פַּת אַף עַל פִּי שֶׁאֵינָהּ צְרִיכָה אֶלָּא לְכִכָּר אֶחָד. שֶׁבִּזְמַן שֶׁהַפַּת מְרֻבָּה בַּתַּנּוּר הִיא נֶאֱפֵית יָפֶה. וּמוֹלֵחַ אָדָם כַּמָּה חֲתִיכוֹת בָּשָׂר בְּבַת אַחַת אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ אֶלָּא לַחֲתִיכָה אַחַת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמְבַשֵּׁל אוֹ הָאוֹפֶה בְּיוֹם טוֹב כְּדֵי לֶאֱכל בּוֹ בַּיּוֹם אוֹ שֶׁזִּמֵּן אוֹרְחִים וְלֹא בָּאוּ וְנִשְׁאַר הַתַּבְשִׁיל וְהַפַּת הֲרֵי זֶה מֻתָּר לֶאֱכל לְמָחָר בֵּין בְּחל בֵּין בְּשַׁבָּת. וּבִלְבַד שֶׁלֹּא יַעֲרִים. וְאִם הֶעֱרִים אָסוּר וַאֲפִלּוּ בְּשַׁבָּת שֶׁאַחַר יוֹם טוֹב מִפְּנֵי שֶׁהֶחְמִירוּ בְּמַעֲרִים יוֹתֵר מִן הַמֵּזִיד:","מִי שֶׁהָיְתָה לוֹ בְּהֵמָה מְסֻכֶּנֶת לֹא יִשְׁחֹט אוֹתָהּ בְּיוֹם טוֹב אֶלָּא אִם כֵּן יוֹדֵעַ שֶׁיָּכוֹל לֶאֱכל מִמֶּנָּה כְּזַיִת צָלִי מִבְּעוֹד יוֹם. כְּדֵי שֶׁלֹּא יִשְׁחֹט בְּיוֹם טוֹב מַה שֶּׁיֹּאכַל בְּחל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין אוֹפִין וּמְבַשְּׁלִין בְּיוֹם טוֹב כְּדֵי לְהַאֲכִיל כּוּתִים אוֹ כְּלָבִים שֶׁנֶּאֱמַר (שמות יב טז) \"הוּא לְבַדּוֹ יֵעָשֶׂה לָכֶם\" לָכֶם וְלֹא לְכוּתִים לָכֶם וְלֹא לִכְלָבִים. לְפִיכָךְ מְזַמְּנִין אֶת הַכּוּתִי בְּשַׁבָּת וְאֵין מְזַמְּנִין אוֹתוֹ בְּיוֹם טוֹב גְּזֵרָה שֶׁמָּא יַרְבֶּה בִּשְׁבִילוֹ. אֲבָל אִם בָּא הַכּוּתִי מֵאֵלָיו אוֹכֵל עִמָּהֶן מַה שֶּׁהֵן אוֹכְלִין שֶׁכְּבָר הֱכִינוּהָ:","בְּהֵמָה שֶׁחֶצְיָהּ שֶׁל כּוּתִי וְחֶצְיָהּ שֶׁל יִשְׂרָאֵל מֻתָּר לְשָׁחֳטָהּ בְּיוֹם טוֹב שֶׁאִי אֶפְשָׁר לֶאֱכל מִמֶּנָּה כְּזַיִת בָּשָׂר בְּלֹא שְׁחִיטָה. אֲבָל עִסָּה שֶׁחֶצְיָהּ לְכוּתִים וְחֶצְיָהּ לְיִשְׂרָאֵל אָסוּר לֶאֱפוֹת אוֹתָהּ מִפְּנֵי שֶׁיָּכוֹל לְחַלֵּק הַבָּצֵק. בְּנֵי הַחַיִל שֶׁנָּתְנוּ קֶמַח לְיִשְׂרָאֵל לַעֲשׂוֹת לָהֶם פַּת בְּיוֹם טוֹב. אִם כְּשֶׁנּוֹתְנִין פַּת מִמֶּנָּה לְתִינוֹק אֵין מַקְפִּידִין מֻתָּר לֶאֱפוֹתוֹ לָהֶן בְּיוֹם טוֹב שֶׁכָּל פַּת וּפַת רָאוּי לַתִּינוֹק. עִסַּת הַכְּלָבִים בִּזְמַן שֶׁהָרוֹעִים אוֹכְלִין מִמֶּנָּה נֶאֱפֵית בְּיוֹם טוֹב:","הַמְבַשֵּׁל בְּיוֹם טוֹב לְכוּתִים אוֹ לִבְהֵמָה אוֹ לְהַנִּיחַ לְחל אֵינוֹ לוֹקֶה שֶׁאִלּוּ בָּאוּ לוֹ אוֹרְחִים הָיָה אוֹתוֹ תַּבְשִׁיל רָאוּי לָהֶן. עָשָׂה לְנַפְשׁוֹ וְהוֹתִיר מֻתָּר לְהַאֲכִיל מִמֶּנּוּ לְכוּתִים וְלִבְהֵמָה:","רְחִיצָה וְסִיכָה הֲרֵי הֵן בִּכְלַל אֲכִילָה וּשְׁתִיָּה וְעוֹשִׂין אוֹתָן בְּיוֹם טוֹב שֶׁנֶּאֱמַר (שמות יב טז) \"אַךְ אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ\" לְכָל שֶׁצָּרִיךְ הַגּוּף. לְפִיכָךְ מְחִמִּין חַמִּין בְּיוֹם טוֹב וְרוֹחֵץ בָּהֶן פָּנָיו יָדָיו וְרַגְלָיו. אֲבָל כָּל גּוּפוֹ אָסוּר מִשּׁוּם גְּזֵרַת מֶרְחָץ. וְחַמִּין שֶׁהוּחַמּוּ מֵעֶרֶב יוֹם טוֹב רוֹחֵץ בָּהֶן כָּל גּוּפוֹ בְּיוֹם טוֹב שֶׁלֹּא גָּזְרוּ עַל דָּבָר זֶה אֶלָּא בְּשַׁבָּת בִּלְבַד:","כָּל שֶׁאָסוּר בְּשַׁבָּת בֵּין מִשּׁוּם שֶׁהוּא דּוֹמֶה לִמְלָאכָה אוֹ מֵבִיא לִידֵי מְלָאכָה בֵּין שֶׁהוּא מִשּׁוּם שְׁבוּת הֲרֵי הוּא אָסוּר בְּיוֹם טוֹב אֶלָּא אִם כֵּן הָיָה בּוֹ צֹרֶךְ אֲכִילָה וְכַיּוֹצֵא בָּהּ. אוֹ דְּבָרִים שֶׁהֵם מֻתָּרִים בְּיוֹם טוֹב כְּמוֹ שֶׁיִּתְבָּאֵר בַּהֲלָכוֹת אֵלּוּ. וְכָל שֶׁאָסוּר לְטַלְטְלוֹ בְּשַׁבָּת אָסוּר לְטַלְטְלוֹ בְּיוֹם טוֹב אֶלָּא לְצֹרֶךְ אֲכִילָה וְכַיּוֹצֵא בָּהּ. וְכָל שֶׁמֻּתָּר בְּשַׁבָּת מֻתָּר בְּיוֹם טוֹב. וְיֵשׁ בְּיוֹם טוֹב מַה שֶּׁאֵין בְּשַׁבָּת אִסּוּר מֻקְצֶה שֶׁהַמֻּקְצֶה אָסוּר בְּיוֹם טוֹב וּמֻתָּר בְּשַׁבָּת מִפְּנֵי שֶׁיּוֹם טוֹב קַל מִשַּׁבָּת אָסְרוּ בּוֹ הַמֻּקְצֶה שֶׁמָּא יָבוֹא לְזַלְזֵל בּוֹ:","כֵּיצַד. תַּרְנְגלֶת הָעוֹמֶדֶת לְגַדֵּל בֵּיצִים וְשׁוֹר הָעוֹמֵד לַחֲרִישָׁה וְיוֹנֵי שׁוֹבָךְ וּפֵרוֹת הָעוֹמְדִין לִסְחוֹרָה כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן מֻקְצֶה הֵן וְאָסוּר לֶאֱכל מֵהֶן בְּיוֹם טוֹב עַד שֶׁיָּכִין אוֹתָם מִבָּעֶרֶב וְיַחֲשֹׁב עֲלֵיהֶם לַאֲכִילָה. אֲבָל בְּשַׁבָּת הַכּל מוּכָן אֵצֶל שַׁבָּת וְאֵינוֹ צָרִיךְ הֲכָנָה. וּכְשֵׁם שֶׁהַמֻּקְצֶה אָסוּר בְּיוֹם טוֹב כָּךְ הַנּוֹלָד אָסוּר:","חֹל מֵכִין לְשַׁבָּת וְחל מֵכִין לְיוֹם טוֹב אֲבָל אֵין יוֹם טוֹב מֵכִין לְשַׁבָּת וְלֹא שַׁבָּת מְכִינָה לְיוֹם טוֹב. לְפִיכָךְ בֵּיצָה שֶׁנּוֹלְדָה בְּיוֹם טוֹב אַחַר הַשַּׁבָּת אֲסוּרָה. וְאַף עַל פִּי שֶׁהַתַּרְנְגלֶת עוֹמֶדֶת לַאֲכִילָה. הוֹאִיל וּמֵאֶמֶשׁ נִגְמְרָה הַבֵּיצָה נִמְצָא שַׁבָּת מֵכִין אוֹתָהּ לְיוֹם טוֹב. וַאֲסָרוּהָ בְּכָל יוֹם טוֹב גְּזֵרָה מִשּׁוּם יוֹם טוֹב שֶׁאַחַר שַׁבָּת. וְכֵן בֵּיצָה שֶׁנּוֹלְדָה בְּכָל שַׁבָּת אֲסוּרָה גְּזֵרָה מִשּׁוּם שַׁבָּת שֶׁאַחַר יוֹם טוֹב:","וּכְשֵׁם שֶׁאָסוּר לְאָכְלָהּ כָּךְ אָסוּר לְטַלְטְלָהּ וַאֲפִלּוּ נִתְעָרְבָה בְּאֶלֶף כֻּלָּן אֲסוּרוֹת שֶׁהֲרֵי לְמָחָר יֻתְּרוּ הַכּל וְכָל דָּבָר שֶׁיֵּשׁ לוֹ מַתִּירִין אֲפִלּוּ בְּאֶלֶף אֲלָפִים אֵינוֹ בָּטֵל. הַשּׁוֹחֵט תַּרְנְגלֶת בְּיוֹם טוֹב וּמָצָא בָּהּ בֵּיצִים גְּמוּרוֹת הֲרֵי אֵלּוּ מֻתָּרוֹת. שֶׁאֵין זֶה דָּבָר מָצוּי תָּמִיד וְדָבָר שֶׁאֵינוֹ מָצוּי אֶלָּא אַקְרַאי בְּעָלְמָא לֹא גָּזְרוּ בּוֹ:","זֶה שֶׁאָנוּ עוֹשִׂין בְּחוּצָה לָאָרֶץ כָּל יוֹם טוֹב מֵאֵלּוּ שְׁנֵי יָמִים מִנְהָג הוּא. וְיוֹם טוֹב שֵׁנִי מִדִּבְרֵי סוֹפְרִים הוּא וּמִדְּבָרִים שֶׁנִּתְחַדְּשׁוּ בַּגָּלוּת. וְאֵין עוֹשִׂין בְּנֵי אֶרֶץ יִשְׂרָאֵל שְׁנֵי יָמִים טוֹבִים אֶלָּא בְּרֹאשׁ הַשָּׁנָה בִּלְבַד. וּבְהִלְכוֹת קִדּוּשׁ הַחֹדֶשׁ מִסֵּפֶר זֶה נְבָאֵר עִקַּר מִנְהָג זֶה וּמֵאֵי זֶה טַעַם עוֹשִׂין רֹאשׁ הַשָּׁנָה שְׁנֵי יָמִים בְּכָל מָקוֹם:","יוֹם טוֹב שֵׁנִי אַף עַל פִּי שֶׁהוּא מִדִּבְרֵי סוֹפְרִים כָּל דָּבָר שֶׁאָסוּר בָּרִאשׁוֹן אָסוּר בַּשֵּׁנִי. וְכָל הַמְחַלֵּל יוֹם טוֹב שֵׁנִי וַאֲפִלּוּ שֶׁל רֹאשׁ הַשָּׁנָה בֵּין בְּדָבָר שֶׁהוּא מִשּׁוּם שְׁבוּת בֵּין בִּמְלָאכָה בֵּין שֶׁיָּצָא חוּץ לַתְּחוּם מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת אוֹ מְנַדִּין אוֹתוֹ אִם לֹא יִהְיֶה מִן הַתַּלְמִידִים. וּכְשֵׁם שֶׁהָרִאשׁוֹן אָסוּר בַּהֶסְפֵּד וְתַעֲנִית וְחַיָּב בְּשִׂמְחָה כָּךְ הַשֵּׁנִי וְאֵין בֵּינֵיהֶן הֶפְרֵשׁ אֶלָּא לְעִנְיַן מֵת בִּלְבַד:","כֵּיצַד. הַמֵּת בְּיוֹם טוֹב רִאשׁוֹן יִתְעַסְּקוּ בִּקְבוּרָתוֹ הַכּוּתִים וּבְיוֹם טוֹב שֵׁנִי יִתְעַסְּקוּ בּוֹ יִשְׂרָאֵל. וְעוֹשִׂין לוֹ כָּל צְרָכָיו כְּגוֹן עֲשִׂיַּת הַמִּטָּה וּתְפִירַת הַתַּכְרִיכִין וּקְצִיצַת הַבְּשָׂמִים וְכָל כַּיּוֹצֵא בָּזֶה. שֶׁיּוֹם טוֹב שֵׁנִי לְגַבֵּי הַמֵּת כְּחל הוּא חָשׁוּב וַאֲפִלּוּ בִּשְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה:","שְׁנֵי יָמִים טוֹבִים אֵלּוּ שֶׁל גָּלֻיּוֹת שְׁתֵּי קְדֻשּׁוֹת הֵן וְאֵינָן כְּיוֹם אֶחָד לְפִיכָךְ דָּבָר שֶׁהָיָה מֻקְצֶה בְּיוֹם טוֹב רִאשׁוֹן אוֹ שֶׁנּוֹלַד בָּרִאשׁוֹן אִם הֵכִין אוֹתוֹ לַשֵּׁנִי הֲרֵי זֶה מֻתָּר. כֵּיצַד. בֵּיצָה שֶׁנּוֹלְדָה בָּרִאשׁוֹן תֵּאָכֵל בַּשֵּׁנִי. חַיָּה וְעוֹף שֶׁנִּצּוֹדוּ בָּרִאשׁוֹן יֵאָכְלוּ בַּשֵּׁנִי. דָּבָר הַמְחֻבָּר לַקַּרְקַע שֶׁנֶּעֱקַר בָּרִאשׁוֹן יֵאָכֵל בַּשֵּׁנִי. וְכֵן מֻתָּר לִכְחל אֶת הָעַיִן בְּיוֹם טוֹב שֵׁנִי וְאַף עַל פִּי שֶׁאֵין שָׁם חלִי. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת אֲבָל שְׁנֵי יָמִים שֶׁל רֹאשׁ הַשָּׁנָה קְדֻשָּׁה אַחַת הֵן וּכְיוֹם אֶחָד הֵן חֲשׁוּבִים לְכָל אֵלּוּ הַדְּבָרִים אֶלָּא לְעִנְיַן הַמֵּת בִּלְבַד. אֲבָל בֵּיצָה שֶׁנּוֹלְדָה בָּרִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה אֲסוּרָה בַּשֵּׁנִי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. שַׁבָּת הַסְּמוּכָה לְיוֹם טוֹב וְנוֹלְדָה בֵּיצָה בְּאֶחָד מֵהֶן אֲסוּרָה בַּשֵּׁנִי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה וַאֲפִלּוּ נוֹלְדָה בְּיוֹם שֵׁנִי לֹא תֵּאָכֵל בְּשַׁבָּת הַסְּמוּכָה לוֹ:"],"Mishneh Torah, Ritual Slaughter 10":["שְׁבוּרָה כֵּיצַד הוּא שֶׁנִּשְׁתַּבְּרוּ רֹב צַלְעוֹתֶיהָ. וְצַלְעוֹת הַבְּהֵמָה הֵן אַחַת עֶשְׂרֵה מִיכָּן וְאַחַת עֶשְׂרֵה מִיכָּן. נִשְׁתַּבְּרוּ שֵׁשׁ מִיכָּן וְשֵׁשׁ מִכָּאן אוֹ אַחַת עֶשְׂרֵה מִכָּאן וְאַחַת מִכָּאן טְרֵפָה. וְהוּא שֶׁנִּשְׁבְּרוּ מֵחֶצְיָן שֶׁל מוּל הַשִּׁדְרָה:","נִשְׁבְּרוּ שֵׁשׁ מִכָּאן וְשֵׁשׁ מִכָּאן אִם הָיוּ צְלָעוֹת גְּדוֹלוֹת שֶׁיֵּשׁ בָּהֶן מֹחַ טְרֵפָה. וְאִם לָאו אַף עַל פִּי שֶׁהֵן רֹב וְאַף עַל פִּי שֶׁנִּשְׁבְּרוּ כְּלַפֵּי הַשִּׁדְרָה מֻתֶּרֶת. וְכֵן אִם נֶעֶקְרוּ רֹב צַלְעוֹתֶיהָ טְרֵפָה. וְאִם נֶעֶקְרָה אֲפִלּוּ צֶלַע אַחַת וַחֲצִי חֻלְיָתָהּ עִמָּהּ שֶׁהַצֶּלַע תְּקוּעָה בָּהּ הֲרֵי זוֹ טְרֵפָה. וְכֵן אִם נֶעֶקְרָה מִן הַשִּׁדְרָה חֻלְיָא אַחַת אֲפִלּוּ הָיְתָה מִן הַחֻלְיוֹת שֶׁלְּמַטָּה מִן הַכְּסָלִים שֶׁאֵין בָּהֶן צְלָעוֹת הֲרֵי זוֹ טְרֵפָה:","בְּהֵמָה שֶׁנִּשְׁמַט הַיָּרֵךְ שֶׁלָּהּ מֵעִקָּרוֹ וְיָצָא מִן הַכַּף שֶׁלּוֹ אִם נִתְאַכְּלוּ נִיבָיו וְהֵן הַיְתֵדוֹת שֶׁבְּעֶצֶם הַכַּף שֶׁיּוֹצֵאת עַל הָעֶצֶם הַזָּכָר וְאוֹחֶזֶת אוֹתוֹ הֲרֵי זוֹ טְרֵפָה. וְאִם לֹא נִתְאַכְּלוּ מֻתֶּרֶת:","וְכֵן בָּעוֹף אִם נִשְׁמַט יְרֵכוֹ טְרֵפָה. נִשְׁמַט כְּנָפוֹ מֵעִקָּרוֹ חוֹשְׁשִׁין שֶׁמָּא נִקְּבָה הָרֵאָה שֶׁלּוֹ וּלְפִיכָךְ בּוֹדְקִין אוֹתָהּ וְאַחַר כָּךְ יֵאָכֵל. וּבְהֵמָה שֶׁנִּשְׁמְטָה יָדָהּ מֵעִקָּרָהּ מֻתֶּרֶת וְאֵין חוֹשְׁשִׁין לָהּ:","גֻּלְגֹּלֶת בְּהֵמָה אוֹ חַיָּה שֶׁנִּטַּל מִמֶּנָּה כְּסֶלַע אַף עַל פִּי שֶׁלֹּא נִקַּב הַקְּרוּם טְרֵפָה. וְאִם נִקְּבוּ נְקָבִים שֶׁיֵּשׁ בָּהֶן חֶסְרוֹן כֻּלָּן מִצְטָרְפִין לִכְסֶלַע:","וְכֵן גֻּלְגֹּלֶת שֶׁנֶּחְבַּס רֹב גָּבְהָהּ וְרֹב הֶקֵּפָהּ טְרֵפָה. אַף עַל פִּי שֶׁהַקְּרוּם שָׁלֵם וְלֹא חָסֵר מִמֶּנָּה כְּלוּם. נֶחְבַּס רֹב גָּבְהָהּ וַהֲרֵי רֹב הֶקֵּפָהּ קַיָּם אוֹ שֶׁנֶּחְבַּס רֹב הֶקֵּפָהּ וַהֲרֵי רֹב גָּבְהָהּ קַיָּם הֲרֵי זוֹ סְפֵק טְרֵפָה. וְיֵרָאֶה לִי שֶׁאוֹסְרִין אוֹתָהּ:","עוֹף שֶׁל מַיִם כְּגוֹן אֲוָזִים אִם נִקַּב עֶצֶם גֻּלְגָּלְתּוֹ אַף עַל פִּי שֶׁלֹּא נִקַּב קְרוּם שֶׁל מֹחַ טְרֵפָה מִפְּנֵי שֶׁקְּרוּמוֹ רַךְ. עוֹף הַיַּבָּשָׁה שֶׁהִכַּתּוּ חֻלְדָּה עַל רֹאשׁוֹ אוֹ שֶׁנִּגַּף בְּאֶבֶן אוֹ בְּעֵץ מַנִּיחַ יָדוֹ בְּצַד הַנֶּקֶב וְנוֹעֵץ אוֹ מַכְנִיס יָדוֹ לְתוֹךְ פִּיו וְדוֹחֵק לְמַעְלָה. אִם יָצָא הַמֹּחַ מִן הַנֶּקֶב בְּיָדוּעַ שֶׁנִּקַּב הַקְּרוּם וּטְרֵפָה. וְאִם לָאו מֻתָּר:","בְּהֵמָה שֶׁאָחֲזָהּ דָּם אוֹ שֶׁהָיְתָה מְעֻשֶּׁנֶת אוֹ מְצֻנֶּנֶת אוֹ שֶׁאָכְלָה סַם שֶׁהוֹרֵג הַבְּהֵמָה אוֹ שָׁתְתָה מַיִם הָרָעִים הֲרֵי זוֹ מֻתֶּרֶת. אָכְלָה סַם שֶׁהוֹרֵג אֶת הָאָדָם אוֹ שֶׁנְּשָׁכָהּ נָחָשׁ וְכַיּוֹצֵא בּוֹ מֻתֶּרֶת מִשּׁוּם טְרֵפָה וַאֲסוּרָה מִפְּנֵי סַכָּנַת נְפָשׁוֹת:","נִמְצְאוּ כָּל הַטְּרֵפוֹת הַמְּנוּיוֹת כְּשֶׁיִּפָּרְטוּ וְאֶפְשָׁר שֶׁיִּמָּצְאוּ בִּבְהֵמָה וְחַיָּה שִׁבְעִים. וְאֵלּוּ הֵן עַל הַסֵּדֶר שֶׁנִּתְבָּאֲרוּ בְּחִבּוּר זֶה. א) דְּרוּסָה. ב) נִקַּב תַּרְבַּץ הַוֵּשֶׁט. ג) נִקַּב קְרוּם שֶׁל מֹחַ. ד) נִתְמַסְמֵס הַמֹּחַ עַצְמוֹ. ה) נִקַּב הַלֵּב עַצְמוֹ לְבֵית חֲלָלוֹ. ו) נִקַּב קְנֵה הַלֵּב. ז) נִקְּבָה הַמָּרָה. ח) נִקְּבוּ קְנֵי הַכָּבֵד. ט) נִקְּבָה הַקֵּבָה. י) נִקַּב הַכֶּרֶס. יא) נִקַּב הֶמְסֵס. יב) נִקַּב בֵּית הַכּוֹסוֹת. יג) נִקְּבוּ מֵעֶיהָ. יד) יָצְאוּ הַמֵּעַיִם לַחוּץ וְנֶהֶפְכוּ. טו) נִקַּב הַטְּחוֹל בְּעָבְיוֹ. טז) חֲסֵרָה הַמָּרָה. יז) נִמְצְאוּ שְׁתֵּי מְרָרוֹת. יח) חֲסֵרָה הַקֵּבָה. יט) נִמְצְאוּ שְׁתֵּי קֵבוֹת. כ) חָסֵר הַכֶּרֶס. כא) נִמְצְאוּ שְׁנֵי כְּרֵסִים. כב) חָסֵר הֶמְסֵס. כג) נִמְצְאוּ שְׁנֵי מְסָסִים. כד) חָסֵר בֵּית הַכּוֹסוֹת. כה) נִמְצְאוּ שְׁנֵי בָּתֵּי הַכּוֹסוֹת. כו) חָסֵר אֶחָד מִן הַמֵּעַיִם. כז) נִמְצְאוּ שְׁנֵי מֵעַיִם. כח) נִקְּבָה הָרֵאָה. כט) נִקַּב הַקָּנֶה לְמַטָּה בְּמָקוֹם שֶׁאֵינוֹ רָאוּי לִשְׁחִיטָה. ל) נִקַּב סִמְפּוֹן מִסִּמְפּוֹנֵי רֵאָה אֲפִלּוּ לַחֲבֵרוֹ. לא) נֶאֱטַם מָקוֹם מִן הָרֵאָה. לב) נִמֹּק סִמְפּוֹן מִסִּמְפּוֹנֵי הָרֵאָה. לג) נִמְצְאָה לֵחָה סְרוּחָה בָּרֵאָה. לד) נִמְצְאוּ בָּהּ מַיִם סְרוּחִים. לה) נִמְצְאוּ בָּהּ מַיִם עֲכוּרִין אַף עַל פִּי שֶׁלֹּא הִסְרִיחוּ. לו) נִתְמַסְמְסָה הָרֵאָה. לז) נִשְׁתַּנּוּ מַרְאֶיהָ. לח) נֶהֱפַךְ הַוֵּשֶׁט בְּמַרְאָיו. לט) חֲסֵרָה הָרֵאָה מִמִּנְיַן הָאֻנּוֹת. מ) נִתְחַלְּפוּ הָאֻנּוֹת. מא) הוֹתִירוּ הָאֻנּוֹת מִגַּבָּהּ. מב) נִסְרְכָה אֻנָּה לְאֻנָּה שֶׁלֹּא כְּסִדְרָן. מג) נִמְצְאָה הָרֵאָה בְּלֹא חִתּוּךְ אָזְנַיִם. מד) חָסֵר מִקְצָת הָרֵאָה. מה) יָבֵשׁ מִקְצָת גּוּפָהּ. מו) נִמְצְאָה הָרֵאָה נְפוּחָה וְעוֹמֶדֶת. מז) צָמְקָה הָרֵאָה מִפַּחַד אָדָם. מח) חָסֵר הָרֶגֶל בֵּין מִתְּחִלַּת בְּרִיָּתוֹ בֵּין שֶׁנֶּחְתַּךְ. מט) אוֹ שֶׁהָיְתָה יְתֵרָה רֶגֶל. נ) נִטְּלָה צֹמֶת הַגִּידִים. נא) נִטְּלָה הַכָּבֵד. נב) נִטַּל לֶחִי הָעֶלְיוֹן. נג) כּוּלְיָא שֶׁהִקְטִינָה בְּיוֹתֵר. נד) כּוּלְיָא שֶׁלָּקְתָה. נה) כּוּלְיָא שֶׁנִּמְצֵאת בָּהּ לֵחָה. נו) כּוּלְיָא שֶׁנִּמְצְאוּ בָּהּ מַיִם עֲכוּרִין אַף עַל פִּי שֶׁאֵינָן סְרוּחִין. נז) כּוּלְיָא שֶׁנִּמְצְאוּ בָּהּ מַיִם סְרוּחִין. נח) נִפְסַק חוּט הַשִּׁדְרָה. נט) נִמְרַךְ מֹחַ חוּט הַשִּׁדְרָה וְנִתְמַסְמֵס. ס) נִקְרַע רֹב הַבָּשָׂר הַחוֹפֶה אֶת הַכֶּרֶס. סא) נִגְלַד הָעוֹר שֶׁעָלֶיהָ. סב) נִתְרַסְּקוּ אֵיבָרֶיהָ מִנְּפִילָה. סג) נִדַּלְדְּלוּ הַסִּימָנִין. סד) נִשְׁתַּבְּרוּ רֹב צַלְעוֹתֶיהָ. סה) נֶעֶקְרוּ רֹב צַלְעוֹתֶיהָ. סו) נֶעֶקְרָה צֶלַע אַחַת בְּחֻלְיָתָהּ. סז) נֶעֶקְרָה חֻלְיָה אַחַת. סח) נִשְׁמַט הַיָּרֵךְ מֵעִקָּרוֹ. סט) חֲסֵרָה הַגֻּלְגֹּלֶת כְּסֶלַע. ע) נֶחְבַּס רֹב הַגֻּלְגֹּלֶת וְנִתְרוֹצֵץ:","אֵלּוּ הַשִּׁבְעִים חֳלָיִים שֶׁאוֹסְרִין אֶת הַבְּהֵמָה וְאֶת הַחַיָּה מִשּׁוּם טְרֵפָה כְּבָר נִתְבָּאֵר כָּל אֶחָד מֵהֶן וּמִשְׁפָּטָיו. וְכָל שֶׁאֶפְשָׁר מֵהֶן שֶׁיִּמָּצֵא בָּעוֹף בָּאֵיבָרִין הַמְּצוּיִין לָעוֹף וְלַבְּהֵמָה דִּינוֹ בִּבְהֵמָה וּבְעוֹף אֶחָד הוּא. חוּץ מִטְּרֵפוֹת שֶׁבְּכוּלְיָא וְשֶׁבַּטְּחוֹל וְשֶׁבְּאֻנּוֹת הָרֵאָה. מִפְּנֵי שֶׁהָעוֹף אֵין לוֹ חִתּוּךְ אֻנּוֹת כִּבְהֵמָה. וְאִם יִמָּצֵא אֵין לוֹ מִנְיָן יָדוּעַ. וּטְחוֹל הָעוֹף עָגל כְּמוֹ עֵנָב וְאֵינוֹ כִּטְחוֹל בְּהֵמָה. וּטְרֵפוֹת שֶׁבַּכּוּלְיָא וְשֶׁבַּטְּחוֹל לֹא מָנוּ אוֹתָן בִּבְהֵמָה כְּדֵי שֶׁיִּהְיֶה כְּנֶגְדָּן בָּעוֹף וּלְפִיכָךְ לֹא נָתְנוּ לְכוּלְיָא שֶׁהִקְטִינָה שִׁעוּר בָּעוֹף. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וּשְׁתֵּי טְרֵפוֹת יֵשׁ בָּעוֹף יֶתֶר עַל הַבְּהֵמָה וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ אוֹתָן הָאֵיבָרִים. וְאֵלּוּ הֵן. עוֹף שֶׁנִּשְׁתַּנּוּ מַרְאֵה בְּנֵי מֵעָיו מֵחֲמַת הָאוּר. וְעוֹף הַמַּיִם שֶׁנִּקַּב עֶצֶם רֹאשׁוֹ:","וְאֵין לְהוֹסִיף עַל טְרֵפוֹת אֵלּוּ כְּלָל. שֶׁכָּל שֶׁאֵרַע לִבְהֵמָה אוֹ לְחַיָּה אוֹ לְעוֹף חוּץ מֵאֵלּוּ שֶׁמָּנוּ חַכְמֵי דּוֹרוֹת הָרִאשׁוֹנִים וְהִסְכִּימוּ עֲלֵיהֶן בְּבָתֵּי דִּינֵי יִשְׂרָאֵל אֶפְשָׁר שֶׁתִּחְיֶה. וַאֲפִלּוּ נוֹדַע לָנוּ מִדֶּרֶךְ הָרְפוּאָה שֶׁאֵין סוֹפָהּ לִחְיוֹת:","וְכֵן אֵלּוּ שֶׁמָּנוּ וְאָמְרוּ שֶׁהֵן טְרֵפָה אַף עַל פִּי שֶׁיֵּרָאֶה בְּדַרְכֵי הָרְפוּאָה שֶׁבְּיָדֵינוּ שֶׁמִּקְצָתָן אֵינָן מְמִיתִין וְאֶפְשָׁר שֶׁתִּחְיֶה מֵהֶן אֵין לְךָ אֶלָּא מַה שֶּׁמָּנוּ חֲכָמִים שֶׁנֶּאֱמַר (דברים יז יא) \"עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ\":","כָּל טַבָּח שֶׁהוּא יוֹדֵעַ הַטְּרֵפוֹת הָאֵלּוּ וַהֲרֵי הוּא בְּחֶזְקַת כַּשְׁרוּת מֻתָּר לוֹ לִשְׁחֹט וְלִבְדֹּק לְעַצְמוֹ וְלִמְכֹּר וְאֵין בָּזֶה חֲשָׁשׁ. שֶׁעֵד אֶחָד נֶאֱמָן בְּאִסּוּרִין בֵּין יֵשׁ לוֹ הֲנָיָה בְּעֵדוּתוֹ בֵּין אֵין לוֹ הֲנָיָה בְּעֵדוּתוֹ. וּכְבָר בֵּאַרְנוּ שֶׁאֵין לוֹקְחִין בָּשָׂר מִטַּבָּח שֶׁשּׁוֹחֵט וּבוֹדֵק לְעַצְמוֹ בְּחוּצָה לָאָרֶץ אוֹ בְּאֶרֶץ יִשְׂרָאֵל בַּזְּמַן הַזֶּה. אֶלָּא אִם כֵּן הָיָה מֻמְחֶה. וְאִם יָצָאת טְרֵפָה מִתַּחַת יָדוֹ מְנַדִּין אוֹתוֹ וּמַעֲבִירִין אוֹתוֹ וְאֵינוֹ חוֹזֵר לְכַשְׁרוּתוֹ עַד שֶׁיֵּלֵךְ לְמָקוֹם שֶׁאֵין מַכִּירִים אוֹתוֹ וְיַחֲזִיר אֲבֵדָה בְּדָבָר חָשׁוּב אוֹ יוֹצִיא טְרֵפָה לְעַצְמוֹ בְּדָבָר חָשׁוּב:"],"Mishneh Torah, Ritual Slaughter 9":["פְּסוּקָה כֵּיצַד. חוּט הַשִּׁדְרָה שֶׁנִּפְסַק הָעוֹר הַחוֹפֶה אֶת הַמֹּחַ טְרֵפָה. וּבִלְבַד שֶׁיִּפָּסֵק רֹב הֶקֵּפוֹ. אֲבָל אִם נִסְדַּק הָעוֹר לְאָרְכּוֹ אוֹ נִקַּב מֻתֶּרֶת. וְכֵן אִם נִשְׁבְּרָה הַשִּׁדְרָה וְלֹא נִפְסַק הַחוּט שֶׁלָּהּ אוֹ שֶׁנִּתְמַעֵךְ הַמֹּחַ שֶׁבְּתוֹךְ הַחוּט וְנִתְנַדְנֵד הוֹאִיל וְעוֹרוֹ קַיָּם הֲרֵי זוֹ מֻתֶּרֶת:","הֻמְרַךְ הַמֹּחַ וְנִשְׁפַּךְ כַּמַּיִם אוֹ כְּדוֹנַג שֶׁנָּמֵס עַד שֶׁיִּמָּצֵא הַחוּט כְּשֶׁמַּעֲמִידוֹ אֵינוֹ עוֹמֵד הֲרֵי זוֹ טְרֵפָה. וְאִם אֵינוֹ יָכוֹל לַעֲמֹד מִפְּנֵי כָּבְדּוֹ הֲרֵי זוֹ סָפֵק:","עַד הֵיכָן חוּט הַשִּׁדְרָה. תְּחִלָּתוֹ מִבַּחוּץ לַפּוֹלִין שֶׁבִּתְחִלַּת הָעֹרֶף עַד סוֹף פָּרָשָׁה שְׁנִיָּה שֶׁלֹּא יִשָּׁאֵר אַחֲרֶיהָ אֶלָּא פָּרָשָׁה שְׁלִישִׁית הַסְּמוּכָה לִתְחִלַּת הָאַלְיָה:","וְשָׁלֹשׁ פָּרָשִׁיּוֹת הֵן וְאֵלּוּ הֵן. שְׁלֹשָׁה עֲצָמוֹת דְּבוּקִין זֶה בָּזֶה לְמַטָּה מֵחֻלְיוֹת שֶׁל שִׁדְרָה. וְחוּט הַשִּׁדְרָה בָּעוֹף עַד בֵּין אֲגַפַּיִים. אֲבָל לְמַטָּה מִמְּקוֹמוֹת אֵלּוּ אֵין מַשְׁגִּיחִין עַל הַחוּט הַנִּמְשָׁךְ לְשָׁם בֵּין שֶׁנִּפְסַק עוֹרוֹ בֵּין שֶׁנִּמְרַךְ הַמֹּחַ:","קְרוּעָה כֵּיצַד. בָּשָׂר הַחוֹפֶה אֶת רֹב הַכֶּרֶס וְהוּא הַמָּקוֹם מִן הַבֶּטֶן שֶׁאִם יִקָּרַע יֵצֵא הַכֶּרֶס אִם נִקְרַע בָּשָׂר זֶה טְרֵפָה. אַף עַל פִּי שֶׁלֹּא הִגִּיעַ הַקֶּרַע לַכֶּרֶס עַד שֶׁנִּרְאֵית. אֶלָּא כֵּיוָן שֶׁנִּקְרַע רֹב עֳבִי הַבָּשָׂר הַזֶּה אוֹ נִטַּל טְרֵפָה. וְכַמָּה שִׁעוּר הַקֶּרַע בְּאָרְכּוֹ אֹרֶךְ טֶפַח. וְאִם הָיְתָה בְּהֵמָה קְטַנָּה וְנִקְרַע רֹב אֹרֶךְ הַבָּשָׂר הַחוֹפֶה אֶת הַכֶּרֶס אַף עַל פִּי שֶׁאֵין בְּאֹרֶךְ הַקֶּרַע טֶפַח טְרֵפָה הוֹאִיל וְנִקְרַע רֻבָּהּ:","נִקְדַּר הַבָּשָׂר הַזֶּה בְּעִגּוּל אוֹ בְּאֹרֶךְ אִם הָיָה יָתֵר מִכְּסֶלַע וְהוּא כְּדֵי שֶׁיִּכָּנֵס בּוֹ שָׁלֹשׁ גַּרְעִינֵי תְּמָרָה זוֹ בְּצַד זוֹ בְּדֹחַק הֲרֵי זוֹ טְרֵפָה. שֶׁאִם יִמָּתַח קֶרַע זֶה יַעֲמֹד עַל טֶפַח:","בְּהֵמָה שֶׁנִּפְשַׁט הָעוֹר שֶׁעָלֶיהָ כֻּלּוֹ בֵּין שֶׁנִּקְרַע בַּיָּד אוֹ בְּחלִי וְנִמְצָא בָּשָׂר בְּלֹא עוֹר הֲרֵי זוֹ טְרֵפָה. וְזוֹ הִיא שֶׁנִּקְרֵאת גְּלוּדָה. וְאִם נִשְׁאַר מִן הָעוֹר רֹחַב סֶלַע עַל פְּנֵי כָּל הַשִּׁדְרָה וְרֹחַב סֶלַע עַל הַטַּבּוּר וְרֹחַב סֶלַע עַל רָאשֵׁי אֵיבָרֶיהָ הֲרֵי זוֹ מֻתֶּרֶת. וְאִם נִטַּל כְּרֹחַב סֶלַע מֵעַל כָּל פְּנֵי הַשִּׁדְרָה אוֹ מֵעַל הַטַּבּוּר אוֹ מֵעַל רָאשֵׁי אֵיבָרֶיהָ וּשְׁאָר כָּל הָעוֹר קַיָּם הֲרֵי זוֹ סָפֵק. וְיֵרָאֶה לִי שֶׁמַּתִּירִין אוֹתָהּ:","נְפוּלָה כֵּיצַד. הֲרֵי שֶׁנָּפְלָה הַבְּהֵמָה מִמָּקוֹם גָּבוֹהַּ שֶׁגָּבְהוֹ עֲשָׂרָה טְפָחִים אוֹ יֶתֶר וְנִתְרַסֵּק אֵיבָר מֵאֵיבָרֶיהָ הֲרֵי זוֹ טְרֵפָה. וְכֵיצַד הוּא הָרִסּוּק. שֶׁיִּתְרוֹצֵץ הָאֵיבָר וְיֶחֱלֶה מֵחֲמַת הַנְּפִילָה עַד שֶׁתִּפָּסֵד צוּרָתוֹ וְתָאֳרוֹ. אַף עַל פִּי שֶׁלֹּא נִקַּב וְלֹא נִסְדַּק וְלֹא נִשְׁבַּר הֲרֵי זוֹ טְרֵפָה. וְכֵן אִם הִכָּה אוֹתָהּ בְּאֶבֶן אוֹ בְּמַטֶּה וְרִצֵּץ אֵיבָר מֵאֵיבָרֶיהָ טְרֵפָה. בְּאֵי זֶה אֵיבָרִים אָמְרוּ בְּאֵיבָרִים שֶׁבַּחֲלַל הַגּוּף:","בְּהֵמָה שֶׁנָּפְלָה מִן הַגַּג אִם הָלְכָה אֵין חוֹשְׁשִׁין לָהּ. וְאִם עָמְדָה וְלֹא הָלְכָה חוֹשְׁשִׁין לָהּ. קָפְצָה מֵחֲמַת עַצְמָהּ אֵין חוֹשְׁשִׁין לָהּ. הִנִּיחָהּ לְמַעְלָה וּמְצָאָהּ לְמַטָּה אֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא נָפְלָה:","זְכָרִים הַמְנַגְּחִין זֶה אֶת זֶה אֵין חוֹשְׁשִׁין לָהֶן. נָפְלוּ לָאָרֶץ חוֹשְׁשִׁין לָהֶן. וְכֵן בְּהֵמָה שֶׁהָיְתָה מְגָרֶרֶת רַגְלֶיהָ אֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא נִתְרַסְּקוּ אֵיבָרֶיהָ אוֹ שֶׁמָּא נִפְסַק הַחוּט שֶׁל שִׁדְרָה:","גַּנָּבִים שֶׁגּוֹנְבִין הַטְּלָאִים וּמַשְׁלִיכִין אוֹתָן לַאֲחוֹרֵי הַדִּיר אֵין חוֹשְׁשִׁין לָהֶן מִשּׁוּם רִסּוּק אֵיבָרִים. מִפְּנֵי שֶׁאֵין מַשְׁלִיכִין אוֹתָן אֶלָּא בְּכַוָּנָה שֶׁלֹּא יִשְׁתַּבְּרוּ. וְאִם הֶחֱזִירוּם וְהִשְׁלִיכוּם לַדִּיר מֵחֲמַת יִרְאָה חוֹשְׁשִׁין לָהֶן. מֵחֲמַת תְּשׁוּבָה אֵין חוֹשְׁשִׁין לָהֶן. מִפְּנֵי שֶׁמִּתְכַּוֵּן לְהַחֲזִירָם שְׁלֵמִים וְיִזָּהֲרוּ בְּהַשְׁלָכָתָן:","שׁוֹר שֶׁהִרְבִּיצוּהוּ לִשְׁחִיטָה אַף עַל פִּי שֶׁנָּפַל נְפִילָה גְּדוֹלָה שֶׁיֵּשׁ לָהּ קוֹל בְּעֵת שֶׁמַּפִּילִין אוֹתוֹ אֵין חוֹשְׁשִׁין לוֹ מִפְּנֵי שֶׁנּוֹעֵץ צִפָּרְנָיו וּמִתְחַזֵּק עַד שֶׁמַּגִּיעַ לָאָרֶץ:","הִכָּה הַבְּהֵמָה עַל רֹאשָׁהּ וְהָלְכָה לָהּ הַמַּכָּה כְּלַפֵּי זְנָבָהּ אוֹ עַל זְנָבָהּ וְהָלְכָה לָהּ כְּלַפֵּי רֹאשָׁהּ וַאֲפִלּוּ הִכָּה אוֹתָהּ בַּמַּטֶּה עַל כָּל הַשִּׁדְרָה אֵין חוֹשְׁשִׁין לָהּ. וְאִם יֵשׁ בַּמַּטֶּה חֻלְיוֹת חֻלְיוֹת חוֹשְׁשִׁין לָהּ. וְאִם הִגִּיעַ רֹאשׁ הַמַּטֶּה לְמִקְצָת הַשִּׁדְרָה חוֹשְׁשִׁין לָהּ. וְכֵן אִם הִכָּה לְרֹחַב הַשִּׁדְרָה חוֹשְׁשִׁין לָהּ:","עוֹף שֶׁנֶּחְבַּט עַל דָּבָר קָשֶׁה כְּגוֹן כְּרִי שֶׁל חִטִּים אוֹ קֻפָּה שֶׁל שְׁקֵדִים וְכַיּוֹצֵא בָּהֶן חוֹשְׁשִׁין לְרִסּוּק אֵיבָרִים. וְאִם נֶחְבַּט עַל דָּבָר רַךְ כְּגוֹן כְּסוּת כְּפוּלָה וְהַתֶּבֶן וְהָאֵפֶר וְכַיּוֹצֵא בָּהֶן אֵין חוֹשְׁשִׁין לוֹ:","נִדְבְּקוּ כְּנָפָיו בְּדֶבֶק בִּשְׁעַת צִידָה וְנִתְחַבֵּט. אִם בְּכָנָף אַחַת נֶאֱחַז אֵין חוֹשְׁשִׁין לוֹ. וְאִם נֶאֱחַז בִּשְׁתֵּי כְּנָפָיו וְנִתְחַבֵּט בְּגוּפוֹ חוֹשְׁשִׁין לוֹ:","נֶחְבַּט עַל פְּנֵי הַמַּיִם אִם שָׁט מְלֹא קוֹמָתוֹ מִמַּטָּה לְמַעְלָה לְעֵמַּת הַמַּיִם אֵין חוֹשְׁשִׁין לוֹ. אֲבָל אִם שָׁט מִמַּעְלָה לְמַטָּה עִם הִלּוּךְ הַמַּיִם חוֹשְׁשִׁין לוֹ שֶׁמָּא הַמַּיִם הֵם הַמּוֹלִיכִין אוֹתוֹ. וְאִם קָדַם לְתֶבֶן אוֹ קַשׁ שֶׁמְּהַלְּכִין עַל גַּבֵּי הַמַּיִם הֲרֵי זוֹ שָׁט מֵחֲמַת עַצְמוֹ וְאֵין חוֹשְׁשִׁין לוֹ:","כָּל מָקוֹם שֶׁאָמַרְנוּ אֵין חוֹשְׁשִׁין לָהּ מֻתָּר לִשְׁחֹט מִיָּד. וְאֵינוֹ צָרִיךְ לִבְדֹּק שֶׁמָּא נִתְרַסֵּק אֵיבָר. וְכָל מָקוֹם שֶׁאָמַרְנוּ חוֹשְׁשִׁין לָהּ אִם שְׁחָטָהּ צָרִיךְ לִבְדֹּק כְּנֶגֶד כָּל הֶחָלָל כֻּלּוֹ מִקָּדְקֹד הָרֹאשׁ עַד הַיָּרֵךְ. אִם מָצָא בָּהּ טְרֵפָה מִן הַטְּרֵפוֹת שֶׁמָּנִינוּ אוֹ שֶׁנִּתְרַסֵּק אֵיבָר מִן הָאֵיבָרִים שֶׁבִּפְנִים וְנִפְסְדָה צוּרָתוֹ הֲרֵי זוֹ טְרֵפָה. אֲפִלּוּ נִתְרַסֵּק אֵיבָר מִן הָאֵיבָרִים שֶׁאִם נִטְּלוּ כְּשֵׁרָה כְּגוֹן טְחוֹל וּכְלָיוֹת הֲרֵי זוֹ טְרֵפָה חוּץ מִבֵּית הָרֶחֶם שֶׁאִם נִתְרַסֵּק הֲרֵי זוֹ מֻתֶּרֶת:","וְהַסִּימָנִין אֵינָן צְרִיכִין בְּדִיקָה בְּכָאן שֶׁאֵין הַנְּפִילָה מְמַעֶכֶת אוֹתָן:","נָפְלָה מִן הַגַּג וְלֹא עָמְדָה אָסוּר לִשְׁחֹט אוֹתָהּ עַד שֶׁתִּשְׁהֵא מֵעֵת לְעֵת. וְאִם שָׁחַט בְּתוֹךְ זְמַן זֶה הֲרֵי זוֹ טְרֵפָה. וּכְשֶׁשּׁוֹחֵט אוֹתָהּ אַחַר מֵעֵת לְעֵת צְרִיכָה בְּדִיקָה כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן מִי שֶׁדָּרַס בְּרַגְלוֹ עַל הָעוֹף אוֹ שֶׁדְּרָסַתּוּ בְּהֵמָה אוֹ שֶׁטְּרָפוֹ לַכֹּתֶל וַהֲרֵי הוּא מְפַרְכֵּס מַשְׁהִין אוֹתוֹ מֵעֵת לְעֵת וְאַחַר כָּךְ שׁוֹחֲטִין אוֹתוֹ וּבוֹדְקִין אוֹתוֹ כְּדֶרֶךְ שֶׁבֵּאַרְנוּ:","סִימָנִים שֶׁנִּדַּלְדְּלוּ רֻבָּן טְרֵפָה וַאֲפִלּוּ שֶׁלֹּא מֵחֲמַת נְפִילָה. וְכֵן אִם נִתְקַפְּלוּ שֶׁהֲרֵי אֵינָן רְאוּיִין לִשְׁחִיטָה. אֲבָל אִם נִתְפָּרֵק רֹב תַּרְבַּץ הַוֵּשֶׁט מִן הַלֶּחִי הֲרֵי זוֹ מֻתֶּרֶת שֶׁאֵין הַתַּרְבַּץ רָאוּי לִשְׁחִיטָה כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Robbery and Lost Property 3":["הַגּוֹזֵל חָבִית שֶׁל יַיִן מֵחֲבֵרוֹ וַהֲרֵי הִיא שָׁוָה דִּינָר בִּשְׁעַת הַגְּזֵלָה וְהוּקְרָה אֶצְלוֹ וְעָמְדָה בְּאַרְבָּעָה. אִם שָׁבַר הֶחָבִית אוֹ שָׁתָה אוֹתָהּ אוֹ מְכָרָהּ אוֹ נְתָנָהּ בְּמַתָּנָה אַחַר שֶׁהוּקְרָה מְשַׁלֵּם אַרְבָּעָה כִּשְׁעַת הוֹצָאָה מִן הָעוֹלָם שֶׁאִלּוּ הִנִּיחָהּ הָיְתָה חוֹזֶרֶת בְּעַצְמָהּ. נִשְׁבְּרָה מֵאֵלֶיהָ אוֹ אָבְדָה מְשַׁלֵּם דִּינָר כִּשְׁעַת הַגְּזֵלָה:","הָיְתָה שָׁוָה בִּשְׁעַת הַגְּזֵלָה אַרְבָּעָה וּבִשְׁעַת הוֹצָאָה מִן הָעוֹלָם דִּינָר. מְשַׁלֵּם אַרְבָּעָה כִּשְׁעַת הַגְּזֵלָה. בֵּין שֶׁשְּׁבָרָהּ אוֹ שְׁתָאָהּ בֵּין שֶׁנִּשְׁבְּרָה אוֹ אָבְדָה מֵאֵלֶיהָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַגּוֹזֵל חֹתֶל שֶׁיֵּשׁ בּוֹ חֲמִשִּׁים תְּמָרִים וּכְשֶׁיִּמְכֹּר הַחֹתֶל כֻּלּוֹ כְּאַחַת יִמְכֹּר בְּתִשְׁעָה וּכְשֶׁיִּמְכֹּר אַחַת אַחַת יִמְכֹּר בַּעֲשָׂרָה. אֵינוֹ מְשַׁלֵּם אֶלָּא תִּשְׁעָה. וְאֵין הַנִּגְזָל יָכוֹל לוֹמַר לוֹ אֲנִי אַחַת אַחַת הָיִיתִי מוֹכֵר. וְכֵן הַדִּין בְּמַזִּיק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בְּנִכְסֵי הֶדְיוֹט. אֲבָל בְּהֶקְדֵּשׁ אֵינוֹ כֵּן אֶלָּא מְשַׁלֵּם עֲשָׂרָה:","גָּזַל בְּהֵמָה וְהִזְקִינָה אוֹ כָּחֲשָׁה כַּחַשׁ שֶׁאֵינוֹ יָכוֹל לַחְזֹר כְּגוֹן חֳלָאִים שֶׁאֵין לָהֶם רְפוּאַת תְּעָלָה. אוֹ שֶׁגָּזַל מַטְבֵּעַ וְנִסְדַּק אוֹ פְּסָלוֹ הַמֶּלֶךְ. אוֹ שֶׁגָּזַל פֵּרוֹת וְהִרְקִיבוּ כֻּלָּן. אוֹ שֶׁגָּזַל יַיִן וְהֶחְמִיץ. הֲרֵי זֶה כְּמִי שֶׁגָּזַל כְּלִי וּשְׁבָרוֹ וּמְשַׁלֵּם כִּשְׁעַת הַגְּזֵלָה. אֲבָל אִם גָּזַל בְּהֵמוֹת וְכָחֲשׁוּ כַּחַשׁ שֶׁאֶפְשָׁר לַחְזֹר. אוֹ שֶׁגָּזַל עֲבָדִים וְהִזְקִינוּ. אוֹ שֶׁגָּזַל מַטְבֵּעַ וְנִפְסַל בִּמְדִינָה זוֹ וַהֲרֵי הִיא יוֹצֵא בִּמְדִינָה אַחֶרֶת. אוֹ שֶׁגָּזַל פֵּרוֹת וְהִרְקִיבוּ מִקְצָתָם. אוֹ תְּרוּמָה וְנִטְמֵאת. אוֹ שֶׁגָּזַל חָמֵץ וְעָבַר עָלָיו הַפֶּסַח. אוֹ בְּהֵמָה וְנֶעֶבְדָה בָּהּ עֲבֵרָה. אוֹ נִפְסְלָה מִלִּקָּרֵב. אוֹ שֶׁהָיְתָה יוֹצְאָה לְהִסָּקֵל. אוֹמֵר לוֹ הֲרֵי שֶׁלְּךָ לְפָנֶיךָ וּמַחֲזִיר אוֹתָהּ בְּעַצְמָהּ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֶחֱזִיר הַגְּזֵלָה. אֲבָל אִם נִשְׂרְפָה הַגְּזֵלָה אוֹ אָבְדָה אַחַר שֶׁנֶּאֶסְרָה בַּהֲנָאָה חַיָּב לְהַחְזִיר לוֹ דָּמֶיהָ כִּשְׁעַת הַגְּזֵלָה. לְפִיכָךְ אִם כָּפַר בּוֹ אַחַר שֶׁנֶּאֶסְרָה בַּהֲנָאָה וְנִשְׁבַּע חַיָּב לְשַׁלֵּם קֶרֶן וְחֹמֶשׁ וְאָשָׁם:","הַגּוֹזֵל בְּהֵמָה וְנָשָׂא עָלֶיהָ מַשָּׂא אוֹ רָכַב עָלֶיהָ אוֹ חָרַשׁ אוֹ דָּשׁ בָּהּ וְכַיּוֹצֵא בָּזֶה וְהֶחְזִיר לִבְעָלֶיהָ אַף עַל פִּי שֶׁעָבַר בְּלֹא תַּעֲשֶׂה אֵינוֹ חַיָּב לְשַׁלֵּם כְּלוּם שֶׁהֲרֵי לֹא הִפְסִידָהּ וְלֹא הִכְחִישָׁהּ. וְאִם הֻחְזַק אָדָם זֶה לִגְזל אוֹ לַעֲשֹׁק אוֹ לַעֲשׂוֹת מַעֲשִׂים אֵלּוּ פַּעַם אַחַר פַּעַם קוֹנְסִין אוֹתוֹ וַאֲפִלּוּ בְּחוּצָה לָאָרֶץ. וְשָׁמִין הַשָּׂכָר אוֹ הַשֶּׁבַח שֶׁהִשְׁבִּיחַ בַּבְּהֵמָה וּמְשַׁלֵּם לַנִּגְזָל:","הַתּוֹקֵף עַבְדּוֹ שֶׁל חֲבֵרוֹ וְעָשָׂה בּוֹ מְלָאכָה וְלֹא בִּטְּלוֹ מִמְּלָאכָה אַחֶרֶת פָּטוּר שֶׁנּוֹחַ לוֹ לָאָדָם שֶׁלֹּא יִבָּטֵל עַבְדּוֹ. וְאִם בִּטְּלוֹ מִמְּלָאכָה אַחֶרֶת מְשַׁלֵּם לוֹ כְּפוֹעֵל:","הַתּוֹקֵף סְפִינָתוֹ שֶׁל חֲבֵרוֹ וְעָשָׂה בָּהּ מְלָאכָה אִם אֵינָהּ עֲשׂוּיָה לְשָׂכָר שָׁמִין כַּמָּה פָּחֲתָה וּמְשַׁלֵּם. וְאִם הִיא עֲשׂוּיָה לְשָׂכָר אִם יָרַד לָהּ בְּתוֹרַת שְׂכִירוּת הוֹאִיל וְיָרַד שֶׁלֹּא בִּרְשׁוּת אִם רָצָה הַבַּעַל לִטּל שְׂכָרָהּ נוֹטֵל רָצָה לִטּל פְּחָתָהּ נוֹטֵל. וְאִם יָרַד לָהּ בְּתוֹרַת גֵּזֶל נוֹתֵן הַפְּחָת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַדָּר בַּחֲצַר חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ. אִם אוֹתָהּ חָצֵר אֵינָהּ עֲשׂוּיָה לְשָׂכָר אֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר. אַף עַל פִּי שֶׁדֶּרֶךְ זֶה הַדָּר לִשְׂכֹּר מָקוֹם לְעַצְמוֹ. שֶׁזֶּה נֶהֱנֶה וְזֶה אֵינוֹ חָסֵר. וְאִם הֶחָצֵר עֲשׂוּיָה לְשָׂכָר אַף עַל פִּי שֶׁאֵין דֶּרֶךְ זֶה לִשְׂכֹּר צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר שֶׁהֲרֵי חִסְּרוֹ מָמוֹן:","מִי שֶׁהָיָה לוֹ צֶמֶר וְסַמָּנִים שְׁרוּיִין וּבָא אֶחָד וְצָבַע הַצֶּמֶר בַּסַּמָּנִין שֶׁלֹּא מִדַּעַת חֲבֵרוֹ. מְשַׁלֵּם לוֹ דְּמֵי מַה שֶּׁהִפְסִיד בַּצֶּמֶר וְאֵינוֹ מְחַשֵּׁב לוֹ שֶׁבַח סַמָּנִין שֶׁעַל גַּבֵּי הַצֶּמֶר. וְאִם תָּפַשׂ הַנִּזָּק דְּמֵי מַה שֶּׁחָסְרוּ מִן הַסַּמָּנִין אֵין מוֹצִיאִין מִיָּדוֹ:","הַשּׁוֹלֵחַ יָד בְּפִקָּדוֹן בֵּין שֶׁשָּׁלַח יָד בְּעַצְמוֹ אוֹ עַל יַד בְּנוֹ וְעַבְדּוֹ וּשְׁלוּחוֹ הֲרֵי זֶה גַּזְלָן וְנִתְחַיֵּב בְּאֳנָסָיו. וְנַעֲשֵׂית הַגְּזֵלָה בִּרְשׁוּתוֹ כְּדִין כָּל הַגַּזְלָנִים. חָשַׁב לִשְׁלֹחַ יָד בְּפִקָּדוֹן אֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיִּשְׁלַח יָד. וּמִשֶּׁשָׁלַח יָד נִתְחַיֵּב בּוֹ. אַף עַל פִּי שֶׁלֹּא חָסַר מִמֶּנּוּ כְּלוּם אֶלָּא נָטַל הַפִּקָּדוֹן מִמָּקוֹם לְמָקוֹם בִּרְשׁוּתוֹ כְּדֵי לִשְׁלֹחַ בּוֹ יָד הֲרֵי זֶה חַיָּב שֶׁשְּׁלִיחוּת יָד אֵינָהּ צְרִיכָה חִסָּרוֹן:","הִגְבִּיהַּ אֶת הֶחָבִית לִטּל מִמֶּנָּה רְבִיעִית נִתְחַיֵּב בָּאֳנָסֶיהָ אַף עַל פִּי שֶׁלֹּא נָטַל. אֲבָל אִם הִגְבִּיהַּ אֶת הַכִּיס לִטּל מִמֶּנּוּ דִּינָר וְכַיּוֹצֵא בַּכִּיס מִדְּבָרִים שֶׁאֵינָן גּוּף אֶחָד הֲרֵי זֶה סָפֵק אִם נִתְחַיֵּב בְּכָל הַכִּיס אוֹ לֹא נִתְחַיֵּב אֶלָּא בְּדִינָר בִּלְבַד:","הָיוּ פֵּרוֹת מֻפְקָדִין אֶצְלוֹ וְנָטַל מִקְצָתָן אֵינוֹ חַיָּב אֶלָּא בְּאַחֲרָיוּת הַפֵּרוֹת שֶׁנָּטַל וּשְׁאָר הַפִּקָּדוֹן הַמֻּנָּח בִּמְקוֹמוֹ בִּרְשׁוּת בְּעָלָיו הוּא. וְאִם נִפְסַד הַשְּׁאָר מֵחֲמַת זֶה שֶׁנָּטַל חַיָּב בַּכּל. כֵּיצַד. הִטָּה אֶת הֶחָבִית בִּמְקוֹמָהּ וְנָטַל מִמֶּנָּה רְבִיעִית אוֹ יֶתֶר אִם נִשְׁבְּרָה אַחַר שֶׁנָּטַל וְהִיא בִּמְקוֹמָהּ אֵינוֹ חַיָּב אֶלָּא כַּמָּה שֶׁנָּטַל שֶׁהֲרֵי לֹא הִגְבִּיהַּ הֶחָבִית. וְאִם הֶחְמִיצָה מְשַׁלֵּם אֶת דְּמֵי כֻּלָּהּ כִּשְׁעַת הַגְּזֵלָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַכּוֹפֵר בְּפִקָּדוֹן בְּבֵית דִּין. אִם הָיָה בִּרְשׁוּתוֹ בִּשְׁעַת שֶׁכָּפַר נַעֲשָׂה עָלָיו גַּזְלָן וְחַיָּב בְּאָנְסוֹ:","הַשּׁוֹאֵל שֶׁלֹּא מִדַּעַת הַבְּעָלִים הֲרֵי זֶה גַּזְלָן. הָיָה כְּלִי בְּיַד בְּנוֹ שֶׁל בַּעַל הַבַּיִת אוֹ בְּיַד עַבְדּוֹ וּלְקָחוֹ אֶחָד מֵהֶן וְנִשְׁתַּמֵּשׁ בּוֹ הֲרֵי זֶה שׁוֹאֵל שֶׁלֹּא מִדַּעַת וְנַעֲשָׂה בִּרְשׁוּתוֹ וְנִתְחַיֵּב בָּאֳנָסָיו עַד שֶׁיַּחְזִירֶנוּ לַבְּעָלִים. לְפִיכָךְ אִם הֶחֱזִירוֹ לְקָטָן שֶׁהָיָה בְּיָדוֹ אוֹ לְעֶבֶד וְאָבַד מֵהֶן אוֹ נִשְׁבַּר חַיָּב לְשַׁלֵּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַחוֹטֵף מַשְׁכּוֹן מִיַּד הַלּוֶֹה שֶׁלֹּא בִּרְשׁוּת בֵּית דִּין הֲרֵי זֶה גַּזְלָן אַף עַל פִּי שֶׁהוּא חַיָּב לוֹ. וְאֵין צָרִיךְ לוֹמַר אִם נִכְנַס לְתוֹךְ בֵּית חֲבֵרוֹ וּמִשְׁכְּנוֹ שֶׁהוּא גַּזְלָן שֶׁנֶּאֱמַר (דברים כד יא) \"בַּחוּץ תַּעֲמֹד\":"],"Mishneh Torah, Sabbath 14":["אַרְבַע רְשׁוּיוֹת לְשַׁבָּת. רְשׁוּת הַיָּחִיד וּרְשׁוּת הָרַבִּים וְכַרְמְלִית וּמְקוֹם פְּטוֹר. אֵי זוֹ הִיא רְשׁוּת הָרַבִּים מִדְבָּרוֹת וַעֲיָרוֹת וּשְׁוָקִים וּדְרָכִים הַמְפֻלָּשִׁין לָהֶן. וּבִלְבַד שֶׁיִּהְיֶה רֹחַב הַדֶּרֶךְ שֵׁשׁ עֶשְׂרֵה אַמָּה וְלֹא יִהְיֶה עָלָיו תִּקְרָה. וְאֵי זוֹ רְשׁוּת הַיָּחִיד תֵּל שֶׁגָּבוֹהַּ עֲשָׂרָה טְפָחִים וְרָחָב אַרְבָּעָה טְפָחִים עַל אַרְבָּעָה טְפָחִים אוֹ יֶתֶר עַל כֵּן. וְכֵן חָרִיץ שֶׁהוּא עָמֹק עֲשָׂרָה וְרָחָב אַרְבָּעָה עַל אַרְבָּעָה אוֹ יֶתֶר עַל כֵּן. וְכֵן מָקוֹם שֶׁהוּא מֻקָּף אַרְבַּע מְחִצּוֹת גָּבְהָן עֲשָׂרָה וּבֵינֵיהֶן אַרְבָּעָה עַל אַרְבָּעָה אוֹ יֶתֶר עַל כֵּן אֲפִלּוּ יֵשׁ בּוֹ כַּמָּה מִילִין אִם הֻקַּף לְדִירָה כְּגוֹן מְדִינָה הַמֻּקֶּפֶת חוֹמָה שֶׁדַּלְתוֹתֶיהָ נִנְעָלוֹת בַּלַּיְלָה וּמְבוֹאוֹת שֶׁיֵּשׁ לָהֶן שְׁלֹשָׁה כְּתָלִים וְלֶחִי בְּרוּחַ רְבִיעִית. וְכֵן חָצֵר וְדִיר וְסַהַר שֶׁהֻקְּפוּ לְדִירָה כֻּלָּן רְשׁוּת הַיָּחִיד גְּמוּרָה הֵן:","אֲפִלּוּ כֵּלִים כְּגוֹן סְפִינָה אוֹ מִגְדָּל שֶׁל עֵץ וְכַוֶּרֶת וְכַיּוֹצֵא בָּהֶן אִם יֵשׁ בָּהֶן אַרְבָּעָה עַל אַרְבָּעָה בְּגֹבַהּ עֲשָׂרָה אוֹ יֶתֶר עַל זֶה הֲרֵי הֵן רְשׁוּת הַיָּחִיד גְּמוּרָה:","עֳבִי הַכְּתָלִים שֶׁל רְשׁוּת הַיָּחִיד כִּרְשׁוּת הַיָּחִיד. לַאֲחֵרִים עוֹשֶׂה מְחִצָּה לְעַצְמוֹ לֹא כָּל שֶׁכֵּן. אֲוִיר רְשׁוּת הַיָּחִיד כִּרְשׁוּת הַיָּחִיד עַד לָרָקִיעַ. אֲבָל אֲוִיר רְשׁוּת הָרַבִּים אֵינוֹ כִּרְשׁוּת הָרַבִּים אֶלָּא עַד עֲשָׂרָה טְפָחִים. וּלְמַעְלָה מֵעֲשָׂרָה בַּאֲוִיר רְשׁוּת הָרַבִּים מְקוֹם פְּטוֹר הוּא:","אֵי זוֹ הִיא כַּרְמְלִית תֵּל שֶׁיֵּשׁ בּוֹ אַרְבָּעָה עַל אַרְבָּעָה אוֹ יֶתֶר עַל כֵּן וְגָבְהוֹ מִשְּׁלֹשָׁה וְעַד עֲשָׂרָה. שֶׁהַכַּרְמְלִית אֵינָהּ תּוֹפֶשֶׂת אֶלָּא עַד עֲשָׂרָה וְאֵינָהּ רְחָבָה פָּחוֹת מֵאַרְבָּעָה עַל אַרְבָּעָה. וְכֵן חָרִיץ שֶׁיֵּשׁ בּוֹ אַרְבָּעָה עַל אַרְבָּעָה אוֹ יֶתֶר עַל כֵּן וְעָמֹק מִשְּׁלֹשָׁה עַד עֲשָׂרָה. וְכֵן מָקוֹם שֶׁהֻקַּף בְּאַרְבַּע מְחִצּוֹת גָּבְהָן מִשְּׁלֹשָׁה וְעַד עֲשָׂרָה וּבֵינֵיהֶן אַרְבָּעָה עַל אַרְבָּעָה אוֹ יֶתֶר עַל כֵּן. וְכֵן קֶרֶן זָוִית הַסְּמוּכָה לִרְשׁוּת הָרַבִּים וְהוּא הַמָּקוֹם שֶׁמֻּקָּף שָׁלֹשׁ מְחִצּוֹת וְהָרוּחַ הָרְבִיעִית רְשׁוּת הָרַבִּים כְּגוֹן מָבוֹי שֶׁאֵין לוֹ לֶחִי אוֹ קוֹרָה בְּרוּחַ רְבִיעִית וְכֵן הַיַּמִּים וְהַבִּקְעָה בֵּין בִּימוֹת הַחַמָּה בֵּין בִּימוֹת הַגְּשָׁמִים כָּל אֵלּוּ כַּרְמְלִית הֵן:","אֲוִיר הַכַּרְמְלִית הֲרֵי הוּא כְּכַרְמְלִית עַד עֲשָׂרָה טְפָחִים. וּלְמַעְלָה מֵעֲשָׂרָה טְפָחִים בַּאֲוִיר הַכַּרְמְלִית הֲרֵי הוּא מְקוֹם פְּטוֹר. לְפִיכָךְ מֵעַל פְּנֵי הַמַּיִם שֶׁבַּיַּמִּים וְשֶׁבַּנְּהָרוֹת עַד עֲשָׂרָה טְפָחִים כַּאֲוִיר כַּרְמְלִית. וּלְמַעְלָה מֵעֲשָׂרָה מְקוֹם פְּטוֹר. אֲבָל כָּל הָעֹמֶק הַמְּלֵאָה מַיִם הֲרֵי הוּא כְּקַרְקַע עָבָה:","בּוֹר שֶׁבְּכַרְמְלִית הֲרֵי הוּא כְּכַרְמְלִית אֲפִלּוּ עָמֹק מֵאָה אַמָּה אִם אֵין בּוֹ אַרְבָּעָה. רְשׁוּת הָרַבִּים שֶׁהָיְתָה עָלֶיהָ תִּקְרָה אוֹ שֶׁאֵין בְּרָחְבָּהּ ט\"ז אַמָּה הֲרֵי הִיא כְּכַרְמְלִית. אִצְטַבָּא שֶׁבֵּין הָעַמּוּדִים הָעוֹמְדִים בִּרְשׁוּת הָרַבִּים הֲרֵי הִיא כְּכַרְמְלִית. וְצִדֵּי רְשׁוּת הָרַבִּים כְּכַרְמְלִית. אֲבָל בֵּין הָעַמּוּדִים הוֹאִיל וְרַבִּים דּוֹרְסִין בֵּינֵיהֶן הֲרֵי הֵן רְשׁוּת הָרַבִּים:","אֵי זֶהוּ מְקוֹם פְּטוֹר. מָקוֹם שֶׁיֵּשׁ בּוֹ פָּחוֹת מֵאַרְבָּעָה עַל אַרְבָּעָה וְגָבְהוֹ שְׁלֹשָׁה עַד לָרָקִיעַ שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה הֲרֵי הוּא כָּאָרֶץ. אֲפִלּוּ קוֹצִים וּבַרְקָנִים אוֹ גְּלָלִים בִּרְשׁוּת הָרַבִּים גָּבְהָן שְׁלֹשָׁה וְאֵין רָחְבָּן אַרְבָּעָה עַל אַרְבָּעָה הֲרֵי הֵן מְקוֹם פְּטוֹר. וְכֵן חָרִיץ שֶׁאֵין בּוֹ אַרְבָּעָה עַל אַרְבָּעָה וְעָמְקוֹ מִשְּׁלֹשָׁה עַד הַתְּהוֹם. וְכֵן מָקוֹם הַמֻּקָּף שֶׁאֵין בּוֹ אַרְבָּעָה עַל אַרְבָּעָה אֲפִלּוּ הָיָה אָרְכּוֹ אֶלֶף מִיל וְרָחְבּוֹ אַרְבָּעָה פָּחוֹת שְׂעוֹרָה וְגָבְהוֹ מִשְּׁלֹשָׁה וּלְמַעְלָה הֲרֵי זֶה מְקוֹם פְּטוֹר. וְכֵן אֲוִיר רְשׁוּת הָרַבִּים אוֹ אֲוִיר כַּרְמְלִית לְמַעְלָה מֵעֲשָׂרָה הֲרֵי הוּא מְקוֹם פְּטוֹר:","מָקוֹם שֶׁיֵּשׁ בְּגָבְהוֹ תִּשְׁעָה טְפָחִים מְצֻמְצָמִים לֹא פָּחוֹת וְלֹא יֶתֶר בִּרְשׁוּת הָרַבִּים הֲרֵי הוּא כִּרְשׁוּת הָרַבִּים. וְאֵין מַשְׁגִּיחִין עַל מִדַּת אָרְכּוֹ וּמִדַּת רָחְבּוֹ בֵּין רָחָב בֵּין קָצָר מִפְּנֵי שֶׁרַבִּים מְכַתְּפִין עָלָיו. אֲבָל אִם הָיָה יֶתֶר עַל תִּשְׁעָה אוֹ פָּחוֹת אִם הָיָה בּוֹ אַרְבָּעָה עַל אַרְבָּעָה אוֹ יֶתֶר הֲרֵי הוּא כַּרְמְלִית. וְאִם אֵין בּוֹ אַרְבָּעָה עַל אַרְבָּעָה הֲרֵי הוּא מְקוֹם פְּטוֹר:","גַּג הַסָּמוּךְ לִרְשׁוּת הָרַבִּים בְּתוֹךְ עֲשָׂרָה טְפָחִים הוֹאִיל וְרַבִּים מְכַתְּפִין עָלָיו אָסוּר לְטַלְטֵל בַּגַּג עַד שֶׁיַּעֲשֶׂה לוֹ סֻלָּם קָבוּעַ לְהַתִּירוֹ. עַמּוּד בִּרְשׁוּת הָרַבִּים גָּבוֹהַּ עֲשָׂרָה וְרָחָב אַרְבָּעָה הֲרֵי זֶה רְשׁוּת הַיָּחִיד. נָעַץ בְּגָבְהוֹ יָתֵד כָּל שֶׁהוּא אֲפִלּוּ אֵינָהּ גְּבוֹהָה שְׁלֹשָׁה הוֹאִיל וְרָאוּי לִתְלוֹת בַּיָּתֵד וּלְהִשְׁתַּמֵּשׁ בּוֹ הֲרֵי זֶה מְמַעֲטוֹ וְנַעֲשָׂה כַּרְמְלִית. וְאֵין מוֹדְדִין לוֹ אֶלָּא מִן הַיָּתֵד וּלְמַעְלָה. וַאֲפִלּוּ מִלְּאָהוּ כֻּלּוֹ יְתֵדוֹת הֲרֵי זֶה מְמַעֵט גָּבְהוֹ. שֶׁהֲרֵי תּוֹלִין בְּאוֹתָן הַיְתֵדוֹת וּמִשְׁתַּמְּשִׁים בָּהֶן:","חוֹרֵי רְשׁוּת הַיָּחִיד הֲרֵי הֵן כִּרְשׁוּת הַיָּחִיד. אֲבָל חוֹרֵי רְשׁוּת הָרַבִּים אֵינָם כִּרְשׁוּת הָרַבִּים אֶלָּא הֲרֵי הֵן כְּפִי מִדָּתָן. כֵּיצַד. חוֹר בְּצַד רְשׁוּת הָרַבִּים אִם יֵשׁ בּוֹ אַרְבָּעָה עַל אַרְבָּעָה וְגָבוֹהַּ עֲשָׂרָה הֲרֵי הוּא רְשׁוּת הַיָּחִיד. וְאִם אֵין גָּבוֹהַּ עֲשָׂרָה הֲרֵי זֶה כַּרְמְלִית. וְאִם אֵין בּוֹ אַרְבָּעָה עַל אַרְבָּעָה הֲרֵי זֶה מְקוֹם פְּטוֹר. וְהוּא שֶׁגָּבוֹהַּ שְׁלֹשָׁה. שֶׁכָּל הַפָּחוּת מִשְּׁלֹשָׁה הֲרֵי הוּא כָּאָרֶץ:","רְשׁוּת הַיָּחִיד וּמְקוֹם פְּטוֹר מֻתָּר לְטַלְטֵל בְּכֻלָּן אֲפִלּוּ הָיָה אֹרֶךְ כָּל אַחַת מִשְּׁתֵּיהֶן כַּמָּה מִילִין מְטַלְטֵל בְּכֻלָּהּ. אֲבָל רְשׁוּת הָרַבִּים וְהַכַּרְמְלִית אֵין מְטַלְטְלִין בָּהֶן אֶלָּא בְּאַרְבַּע אַמּוֹת. וְאִם הֶעֱבִיר אוֹ הוֹשִׁיט אוֹ זָרַק חוּץ לְאַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים חַיָּב וּבְכַרְמְלִית פָּטוּר. שֶׁאִסּוּר הַכַּרְמְלִית מִדִּבְרֵיהֶם מִפְּנֵי שֶׁהִיא דּוֹמָה לִרְשׁוּת הָרַבִּים שֶׁמָּא תִּתְחַלֵּף בִּרְשׁוּת הָרַבִּים. לְפִיכָךְ אִם לֹא הָיָה צָרִיךְ לְגוּף הַהוֹצָאָה כְּגוֹן שֶׁהֶעֱבִיר קוֹץ בְּכַרְמְלִית כְּדֵי שֶׁלֹּא יִזּוֹקוּ בּוֹ רַבִּים הֲרֵי זֶה מֻתָּר. וַאֲפִלּוּ הֶעֱבִירוֹ כַּמָּה אַמּוֹת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כְּשֵׁם שֶׁמֻּתָּר לְטַלְטֵל בְּכָל מְקוֹם פְּטוֹר כָּךְ מֻתָּר לְהַכְנִיס מִמֶּנּוּ לִרְשׁוּת הַיָּחִיד אוֹ לִרְשׁוּת הָרַבִּים וְאֵין צָרִיךְ לוֹמַר לְכַרְמְלִית. וּמוֹצִיאִין לוֹ מֵרְשׁוּת הַיָּחִיד וּמֵרְשׁוּת הָרַבִּים וְאֵין צָרִיךְ לוֹמַר מִן הַכַּרְמְלִית:","כְּשֵׁם שֶׁאָסוּר לְטַלְטֵל בְּכָל הַכַּרְמְלִית כָּךְ אָסוּר לְהוֹצִיא מִמֶּנָּה לִרְשׁוּת הַיָּחִיד אוֹ לִרְשׁוּת הָרַבִּים אוֹ לְהַכְנִיס לְכַרְמְלִית מֵרְשׁוּת הַיָּחִיד אוֹ מֵרְשׁוּת הָרַבִּים. וְאִם הוֹצִיא אוֹ הִכְנִיס פָּטוּר:","הַמּוֹצִיא מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הַיָּחִיד אוֹ מֵרְשׁוּת הָרַבִּים לִרְשׁוּת הָרַבִּים וְכַרְמְלִית בָּאֶמְצַע פָּטוּר. וְכֵן הַמּוֹשִׁיט אוֹ הַזּוֹרֵק מִזּוֹ לְזוֹ וְכַרְמְלִית בָּאֶמְצַע פָּטוּר. הַמּוֹצִיא חֵפֶץ מֵרְשׁוּת הָרַבִּים לְכַרְמְלִית וְהִנִּיחוֹ שָׁם וְחָזַר וַעֲקָרוֹ מִכַּרְמְלִית וְהִכְנִיסוֹ לִרְשׁוּת הַיָּחִיד. אוֹ שֶׁהוֹצִיאוֹ מֵרְשׁוּת הַיָּחִיד לְכַרְמְלִית וְהִנִּיחוֹ שָׁם וְחָזַר וַעֲקָרוֹ מִכַּרְמְלִית וְהוֹצִיאוֹ לִרְשׁוּת הָרַבִּים הֲרֵי זֶה פָּטוּר:","הַמּוֹצִיא מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים וְעָבַר עַל מְקוֹם פְּטוֹר שֶׁהָיָה בֵּינֵיהֶן בַּהֲלִיכָתוֹ חַיָּב. שֶׁמְּהַלֵּךְ אֵינוֹ כְּעוֹמֵד. וְאֵין צָרִיךְ לוֹמַר בְּזוֹרֵק שֶׁעָבַר הַחֵפֶץ בִּמְקוֹם פְּטוֹר שֶׁאֵינוֹ חָשׁוּב כְּמִי שֶׁנָּח שָׁם. הָיָה עוֹמֵד בִּמְקוֹם פְּטוֹר וְנָטַל חֵפֶץ מֵרְשׁוּת הַיָּחִיד אוֹ מֵאָדָם הָעוֹמֵד שָׁם וְהִנִּיחוֹ בִּרְשׁוּת הָרַבִּים אוֹ בְּיַד אָדָם הָעוֹמֵד שָׁם פָּטוּר. וְכֵן אִם הִכְנִיס מֵרְשׁוּת הָרַבִּים לִרְשׁוּת הַיָּחִיד וְעָמַד בִּמְקוֹם פְּטוֹר, פָּטוּר:","עַמּוּד בִּרְשׁוּת הָרַבִּים גָּבוֹהַּ עֲשָׂרָה וְרָחָב אַרְבָּעָה וְאֵין בְּעִקָּרוֹ אַרְבָּעָה וְיֵשׁ בַּגֹּבַהּ הַקָּצָר שֶׁלּוֹ שְׁלֹשָׁה הֲרֵי הוּא רְשׁוּת הַיָּחִיד וְאִם זָרַק מֵרְשׁוּת הָרַבִּים וְנָח עַל גַּבָּיו חַיָּב. תֵּל הַמִּתְלַקֵּט גּוֹבֶה עֲשָׂרָה טְפָחִים מִתּוֹךְ אֹרֶךְ אַרְבַּע אַמּוֹת הֲרֵי הוּא רְשׁוּת הַיָּחִיד וְאִם זָרַק מֵרְשׁוּת הָרַבִּים וְנָח עַל גַּבָּיו חַיָּב:","נָעַץ קָנֶה בִּרְשׁוּת הַיָּחִיד אֲפִלּוּ גָּבוֹהַּ מֵאָה אַמָּה וְזָרַק מֵרְשׁוּת הָרַבִּים וְנָח עַל גַּבָּיו חַיָּב. שֶׁרְשׁוּת הַיָּחִיד עוֹלָה עַד לָרָקִיעַ. אִילָן שֶׁהוּא עוֹמֵד בִּרְשׁוּת הַיָּחִיד וְנוֹפוֹ נוֹטֶה לִרְשׁוּת הָרַבִּים וְזָרַק וְנָח עַל נוֹפוֹ פָּטוּר. שֶׁאֵין הַנּוֹף הוֹלֵךְ אַחַר הָעִקָּר:","נָעַץ קָנֶה בִּרְשׁוּת הָרַבִּים וּבְרֹאשׁוֹ טְרַסְקַל וְזָרַק וְנָח עַל גַּבָּיו פָּטוּר שֶׁאֵין רְשׁוּת הָרַבִּים אֶלָּא עַד עֲשָׂרָה. הַזּוֹרֵק אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים וְנָח הַחֵפֶץ בַּכֹּתֶל. כְּגוֹן שֶׁזָּרַק חֵלֶב אוֹ בָּצֵק וְנִדְבַּק בַּכֹּתֶל. אִם נִדְבַּק לְמַעְלָה מֵעֲשָׂרָה טְפָחִים כְּזוֹרֵק בַּאֲוִיר. שֶׁלְּמַעְלָה מֵעֲשָׂרָה בִּרְשׁוּת הָרַבִּים מְקוֹם פְּטוֹר הוּא. נִדְבַּק לְמַטָּה מֵעֲשָׂרָה טְפָחִים כְּזוֹרֵק בָּאָרֶץ וְחַיָּב. זָרַק לְמַעְלָה מֵעֲשָׂרָה וְנָח בְּחוֹר כָּל שֶׁהוּא פָּטוּר:","זָרַק קָנֶה אוֹ רֹמַח מֵרְשׁוּת הַיָּחִיד וְנִתְקַע בִּרְשׁוּת הָרַבִּים כְּשֶׁהוּא עוֹמֵד פָּטוּר. שֶׁהֲרֵי מִקְצָתוֹ בִּמְקוֹם פְּטוֹר. זָרַק כְּלִי מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים וְהָיָה אוֹתוֹ כְּלִי גָּדוֹל וְיֵשׁ בּוֹ אַרְבָּעָה עַל אַרְבָּעָה בְּגֹבַהּ עֲשָׂרָה פָּטוּר. מִפְּנֵי שֶׁכְּלִי זֶה רְשׁוּת הַיָּחִיד גְּמוּרָה וְנִמְצָא כְּמוֹצִיא מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הַיָּחִיד:","בּוֹר תִּשְׁעָה בִּרְשׁוּת הָרַבִּים וְעָקַר חֻלְיָא מִקַּרְקָעִיתוֹ וְהִשְׁלִימוֹ לַעֲשָׂרָה. אַף עַל פִּי שֶׁעֲקִירַת הַחֵפֶץ וַעֲשִׂיַּת הַמְּחִצָּה בָּאִין כְּאַחַת פָּטוּר. מִפְּנֵי שֶׁלֹּא הָיְתָה הַמְּחִצָּה עֲשָׂרָה בַּתְּחִלָּה. הָיָה הַבּוֹר עֲשָׂרָה וְהִשְׁלִיךְ בּוֹ חֻלְיָה וּמִעֲטוֹ מֵעֲשָׂרָה פָּטוּר. שֶׁהֲרֵי הַנָּחַת הַחֵפֶץ וְסִלּוּק הַמְּחִצָּה בָּאִין כְּאַחַת:","הַזּוֹרֵק דַּף וְנָח עַל גַּבֵּי יְתֵדוֹת בִּרְשׁוּת הָרַבִּים וְנַעֲשָׂה רְשׁוּת הַיָּחִיד אֲפִלּוּ הָיָה כְּלִי עַל גַּבֵּי הַדַּף פָּטוּר. שֶׁהֲרֵי עֲשִׂיַּת הַמְּחִצָּה עִם נוּחַת הַכְּלִי בָּאִין כְּאַחַת:","בּוֹר שֶׁהוּא עָמֹק עֲשָׂרָה וְרָחָב שְׁמוֹנָה בִּרְשׁוּת הָרַבִּים וְזָרַק מַחְצֶלֶת מֵרְשׁוּת הָרַבִּים וְחִלְּקָה הַבּוֹר בְּרָחְבּוֹ לִשְׁנַיִם פָּטוּר. שֶׁהֲרֵי עִם הַנָּחַת הַכְּלִי בָּטְלוּ הַמְּחִצּוֹת וְנַעֲשָׂה כָּל מָקוֹם מֵהֶן פָּחוֹת מֵאַרְבָּעָה עַל אַרְבָּעָה:","בּוֹר בִּרְשׁוּת הָרַבִּים עָמֹק עֲשָׂרָה וְרָחָב אַרְבָּעָה מָלֵא מַיִם וְזָרַק לְתוֹכוֹ חֵפֶץ וְנָח עַל גַּבֵּי הַמַּיִם חַיָּב. שֶׁאֵין הַמַּיִם מְבַטְּלִין הַמְּחִצּוֹת. הָיָה מָלֵא פֵּרוֹת וְזָרַק לְתוֹכוֹ פָּטוּר. שֶׁהֲרֵי מִעֲטוּ הַפֵּרוֹת אֶת שִׁעוּרוֹ:","רְקַק מַיִם שֶׁהוּא עוֹבֵר בִּרְשׁוּת הָרַבִּים וְרַבִּים מְהַלְּכִין בּוֹ. אִם אֵין בְּעָמְקוֹ עֲשָׂרָה טְפָחִים הֲרֵי הוּא כִּרְשׁוּת הָרַבִּים. בֵּין שֶׁהָיָה רָחָב אֲפִלּוּ אַרְבַּע אַמּוֹת בֵּין שֶׁלֹּא הָיָה בְּרָחְבּוֹ אַרְבָּעָה טְפָחִים. שֶׁהֲרֵי רֹב הָעָם מְדַלְּגִין עָלָיו וְאֵין מְהַלְּכִין בְּתוֹכוֹ. הוֹאִיל וְאֵין בְּעָמְקוֹ עֲשָׂרָה הֲרֵי הוּא רְשׁוּת הָרַבִּים. וְאִם יֵשׁ בְּעָמְקוֹ עֲשָׂרָה אוֹ יֶתֶר הֲרֵי הוּא כְּכַרְמְלִית כִּשְׁאָר הַיַּמִים. וְהוּא שֶׁיֵּשׁ בְּרָחְבּוֹ אַרְבָּעָה טְפָחִים אוֹ יֶתֶר עַל כֵּן. שֶׁאֵין כַּרְמְלִית פְּחוּתָה מֵאַרְבָּעָה:"],"Mishneh Torah, Sabbath 25":["יֵשׁ כְּלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר וְהוּא הַכְּלִי שֶׁמֻּתָּר לַעֲשׂוֹת בּוֹ בְּשַׁבָּת דָּבָר שֶׁנַּעֲשָׂה לוֹ בְּחל. כְּגוֹן כּוֹס לִשְׁתּוֹת בּוֹ וּקְעָרָה לֶאֱכל בָּהּ וְסַכִּין לַחְתוֹך בּוֹ בָּשָׂר וּפַת וְקֻרְנָס לִפְצֹעַ בּוֹ אֱגוֹזִים וְכַיּוֹצֵא בָּהֶן:","וְיֵשׁ כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר וְהוּא הַכְּלִי שֶׁאָסוּר לַעֲשׂוֹת בּוֹ בְּשַׁבָּת דָּבָר שֶׁנַּעֲשָׂה בּוֹ. כְּגוֹן מַכְתֶּשֶׁת וְרֵיחַיִם וְכַיּוֹצֵא בָּהֶן שֶׁאָסוּר לִכְתּשׁ וְלִטְחֹן בְּשַׁבָּת:","כָּל כְּלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר בֵּין הָיָה שֶׁל עֵץ אוֹ שֶׁל חֶרֶס אוֹ שֶׁל אֶבֶן אוֹ שֶׁל מַתֶּכֶת מֻתָּר לְטַלְטְלוֹ בְּשַׁבָּת. בֵּין בִּשְׁבִיל עַצְמוֹ שֶׁל כְּלִי בֵּין לְצֹרֶךְ מְקוֹמוֹ בֵּין לְצֹרֶךְ גּוּפוֹ. וְכָל כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר בֵּין הָיָה שֶׁל עֵץ אוֹ שֶׁל חֶרֶס אוֹ שֶׁל אֲבָנִים אוֹ שֶׁל מַתֶּכֶת מֻתָּר לְטַלְטְלוֹ בְּשַׁבָּת בֵּין לְצֹרֶךְ גּוּפוֹ בֵּין לְצֹרֶךְ מְקוֹמוֹ אֲבָל בִּשְׁבִיל עַצְמוֹ שֶׁל כְּלִי אָסוּר:","כֵּיצַד. מְטַלְטֵל הוּא אֶת הַקְּעָרָה שֶׁל עֵץ לֶאֱכל בָּהּ אוֹ לֵישֵׁב בִּמְקוֹמָהּ. אוֹ כְּדֵי שֶׁלֹּא תִּגָּנֵב. וְזֶה הוּא בִּשְׁבִיל עַצְמָהּ. וְכֵן אִם טִלְטֵל אוֹתָהּ מִן הַחַמָּה כְּדֵי שֶׁלֹּא תִּתְיַבֵּשׁ וְתִשָּׁבֵר אוֹ מִן הַגְּשָׁמִים כְּדֵי שֶׁלֹּא תִּתְפַּח וְתִפָּסֵד הֲרֵי זֶה מְטַלְטֵל בִּשְׁבִיל עַצְמָהּ וּמֻתָּר מִפְּנֵי שֶׁמְּלַאכְתָּהּ לְהֶתֵּר:","וְכֵן מְטַלְטֵל הוּא הָרֵחַיִם אוֹ הַמַּכְתֶּשֶׁת לְשַׁבֵּר עָלֶיהָ אֱגוֹזִים אוֹ לַעֲלוֹת עָלֶיהָ לַמִּטָּה וְזֶה הוּא לְצֹרֶךְ גּוּפוֹ אוֹ לֵישֵׁב בִּמְקוֹמוֹ. אֲבָל אֵינוֹ מְטַלְטְלָהּ כְּדֵי שֶׁלֹּא תִּשָּׁבֵר וְלֹא כְּדֵי שֶׁלֹּא תִּגָּנֵב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וְכָל שֶׁאֵינוֹ כְּלִי כְּגוֹן אֲבָנִים וּמָעוֹת וְקָנִים וְקוֹרוֹת וְכַיּוֹצֵא בָּהֶן אָסוּר לְטַלְטְלָן. אֶבֶן גְּדוֹלָה אוֹ קוֹרָה גְּדוֹלָה אַף עַל פִּי שֶׁהִיא נִטֶּלֶת בַּעֲשָׂרָה בְּנֵי אָדָם אִם יֵשׁ תּוֹרַת כְּלִי עָלֶיהָ מְטַלְטְלִים אוֹתָהּ. דַּלְתוֹת הַבַּיִת אַף עַל פִּי שֶׁהֵן כֵּלִים לֹא הוּכְנוּ לְטַלְטֵל לְפִיכָךְ אִם נִתְפָּרְקוּ אֲפִלּוּ בְּשַׁבָּת אֵין מְטַלְטְלִין אוֹתָן. וְכֵן הֶעָפָר וְהַחוֹל וְהַמֵּת אֵין מְזִיזִין אוֹתָן מִמְּקוֹמָן. וּבֶן שְׁמוֹנָה חַי הֲרֵי הוּא כְּאֶבֶן וְאָסוּר לְטַלְטְלוֹ:","מֻתָּר לְטַלְטֵל הַכְּלִי אֲפִלּוּ שֶׁלֹּא לְצֹרֶךְ תַּשְׁמִישׁוֹ אֶלָּא לַעֲשׂוֹת בּוֹ מְלָאכָה שֶׁלֹּא נַעֲשָׂה לְתַשְׁמִישָׁהּ. כֵּיצַד. נוֹטֵל אָדָם קֻרְנָס לִפְצֹעַ בּוֹ אֱגוֹזִים. קוֹרְדוֹם לַחְתֹּךְ בּוֹ דְּבֵלָה. מְגֵרָה לְגָרֵר בָּהּ אֶת הַגְּבִינָה. מַגְרֵפָה לִגְרֹף בָּהּ אֶת הַגְּרוֹגָרוֹת. אֶת הָרַחַת וְאֶת הַמַּזְלֵג לָתֵת עָלָיו אֹכֶל לְקָטָן. אֶת הַכּוֹשׁ וְאֶת הַכַּרְכָּר לִתְחֹב בּוֹ. מַחַט שֶׁל סַקָּאִין לִפְתֹּחַ בּוֹ אֶת הַדֶּלֶת. אֶת הַמַּכְתֶּשֶׁת לֵישֵׁב עָלֶיהָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וּמְטַלְטֵל אָדָם מַחַט שֶׁל יָד הַשְּׁלֵמָה לִטּל בָּהּ אֶת הַקּוֹץ. אֲבָל אִם נִטַּל הַקָּצֶה הַנָּקוּב שֶׁלָּהּ אוֹ הַקָּצֶה הַחַד שֶׁלָּהּ אֵין מְטַלְטְלִין אוֹתָהּ. וְאִם הָיְתָה גּלֶם וַעֲדַיִן לֹא נִקְּבָה מֻתָּר לְטַלְטְלָהּ:","כָּל כְּלִי שֶׁמַּקְפִּיד עָלָיו שֶׁמָּא יִפְחֲתוּ דָּמָיו כְּגוֹן כֵּלִים הַמֻּקְצִים לִסְחוֹרָה וְכֵלִים הַיְקָרִים בְּיוֹתֵר שֶׁמַּקְפִּיד עֲלֵיהֶן שֶׁמָּא יִפָּסְדוּ אָסוּר לְטַלְטְלָן בְּשַׁבָּת וְזֶה הוּא הַנִּקְרָא מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס. כְּגוֹן הַמַּסָּר הַגָּדוֹל וְיָתֵד שֶׁל מַחְרֵשָׁה וְסַכִּין שֶׁל טַבָּחִים וְחֶרֶב שֶׁל אוּשְׁכָּפִים וְחִצִּין הַחֲרָשִׁים וְקֻרְנָס שֶׁל בַּשָּׂמִים וְכַיּוֹצֵא בָּהֶן:","כָּל כְּלִי שֶׁהֻקְצָה מֵחֲמַת הָאִסּוּר אָסוּר לְטַלְטְלוֹ. כְּגוֹן נֵר שֶׁהִדְלִיקוּ בּוֹ בְּשַׁבָּת וְהַמְּנוֹרָה שֶׁהָיָה הַנֵּר עָלֶיהָ וְשֻׁלְחָן שֶׁהָיוּ עָלָיו מָעוֹת אַף עַל פִּי שֶׁכָּבָה הַנֵּר אוֹ שֶׁנָּפְלוּ הַמָּעוֹת אָסוּר לְטַלְטְלָן. שֶׁכָּל כְּלִי שֶׁהָיָה אָסוּר לְטַלְטְלוֹ בֵּין הַשְּׁמָשׁוֹת נֶאֱסַר לְטַלְטְלוֹ כָּל הַשַּׁבָּת כֻּלָּהּ אַף עַל פִּי שֶׁהָלַךְ הַדָּבָר שֶׁגָּרַם לוֹ הָאִסּוּר:","אֲבָל כְּלִי הַמֻּקְצֶה מֵחֲמַת מֵאוּסוֹ כְּגוֹן נֵר יָשָׁן שֶׁל נֵפְט וּכְלִי הַצּוֹאָה וְכַיּוֹצֵא בָּהֶן מֻתָּר לְטַלְטְלָן בְּשַׁבָּת אִם הֻצְרַךְ לָהֶן:","כָּל הַכֵּלִים הַנִּטָּלִין בְּשַׁבָּת שֶׁנִּתְפָּרְקוּ דַּלְתוֹתֵיהֶן כְּגוֹן דַּלְתוֹת שִׁדָּה תֵּבָה וּמִגְדָּל בֵּין שֶׁנִּתְפָּרְקוּ בְּשַׁבָּת בֵּין שֶׁנִּתְפָּרְקוּ קֹדֶם הַשַּׁבָּת מֻתָּר לְטַלְטֵל אוֹתָן דְּלָתוֹת. וְכֵן כָּל הַכֵּלִים הַנִּטָּלִין בְּשַׁבָּת שֶׁנִּשְׁבְּרוּ בֵּין קֹדֶם הַשַּׁבָּת בֵּין בְּשַׁבָּת שִׁבְרֵיהֶן נִטָּלִין וְהוּא שֶׁיִּהְיוּ שִׁבְרֵיהֶן עוֹשִׂין מֵעֵין מְלַאכְתָּן. כֵּיצַד. שִׁבְרֵי עֲרֵבָה לְכַסּוֹת בָּהֶן אֶת פִּי הֶחָבִית. שִׁבְרֵי זְכוּכִית לְכַסּוֹת בָּהֶן אֶת פִּי הַפַּךְ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אִם אֵין הַשְּׁבָרִים רְאוּיִין לִמְלָאכָה כְּלָל אָסוּר לְטַלְטְלָן:","כָּל כִּסּוּיֵי הַכֵּלִים נִטָּלִים בְּשַׁבָּת וְהוּא שֶׁיֵּשׁ תּוֹרַת כְּלִי עֲלֵיהֶן. הָיָה כְּלִי מְחֻבָּר בַּקַּרְקַע כְּגוֹן חָבִית הַטְּמוּנָה בָּאָרֶץ. אִם יֵשׁ בַּכִּסּוּי שֶׁלָּהּ בֵּית אֲחִיזָה מְטַלְטְלִין אוֹתוֹ וְאִם לָאו אֵין מְטַלְטְלִין אוֹתוֹ. וְכֵן כִּסּוּיֵי הַקַּרְקָעוֹת כְּגוֹן בּוֹרוֹת וַחֲרִיצִין אֵין מְטַלְטְלִין כִּסּוּי שֶׁלָּהֶן אֶלָּא אִם כֵּן יֵשׁ לוֹ בֵּית אֲחִיזָה. כִּסּוּי הַתַּנּוּר אַף עַל פִּי שֶׁאֵין לוֹ בֵּית אֲחִיזָה מֻתָּר לְטַלְטְלוֹ:","שְׁנֵי דְּבָרִים אֶחָד אָסוּר לְטַלְטְלוֹ וְאֶחָד מֻתָּר לְטַלְטְלוֹ וְהֵן סְמוּכִים זֶה לָזֶה אוֹ זֶה עַל זֶה אוֹ זֶה בָּזֶה וּבִזְמַן שֶׁמְּטַלְטְלִין אֶחָד מֵהֶן יְטַלְטֵל הַשֵּׁנִי. אִם הָיָה צָרִיךְ לַדָּבָר שֶׁמֻּתָּר לְטַלְטְלוֹ מְטַלְטְלוֹ וְאַף עַל פִּי שֶׁדָּבָר הָאָסוּר מִטַּלְטֵל עִמּוֹ. וְאִם צָרִיךְ לְטַלְטֵל דָּבָר הָאָסוּר לֹא יְטַלְטְלֶנּוּ בְּאוֹתוֹ דָּבָר הַמֻּתָּר:","כֵּיצַד. פַּגָּה שֶׁהָיְתָה טְמוּנָה בְּתֶבֶן וַחֲרָרָה שֶׁהָיְתָה עַל גַּבֵּי גֶּחָלִים תּוֹחֲבָן בְּכוֹשׁ אוֹ בְּכַרְכָּר וְנוֹטְלָן וְאַף עַל פִּי שֶׁהַתֶּבֶן וְהַגֶּחָלִים נִנְעָרִים בְּשַׁבָּת בִּשְׁעַת נְטִילָה. וְכֵן לֶפֶת אוֹ צְנוֹנוֹת שֶׁהָיוּ טְמוּנִים בְּעָפָר וּמִקְצָת הֶעָלִים מְגֻלִּים שׁוֹמְטָן בְּשַׁבָּת בֶּעָלֶה שֶׁלָּהֶן וְאַף עַל פִּי שֶׁהֶעָפָר נִנְעָר. אֲבָל אִם הָיָה כִּכָּר אוֹ תִּינוֹק עַל גַּבֵּי הָאֶבֶן אוֹ עַל גַּבֵּי הַקּוֹרָה לֹא יְטַלְטֵל הָאֶבֶן אוֹ הַקּוֹרָה בַּכִּכָּר אוֹ בַּתִּינוֹק שֶׁיֵּשׁ עָלֶיהָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נוֹטֵל אָדָם אֶת בְּנוֹ שֶׁיֵּשׁ לוֹ גַּעְגּוּעִין עָלָיו וְהָאֶבֶן בְּיָדוֹ אֲבָל לֹא דִּינָר שֶׁאִם יִפּל הַדִּינָר יִטְּלֶנּוּ הָאָב בְּיָדוֹ. כַּלְכָּלָה שֶׁהָיְתָה נְקוּבָה וְסָתַם נֶקֶב שֶׁלָּהּ בְּאֶבֶן מֻתָּר לְטַלְטְלָהּ שֶׁהֲרֵי הָאֶבֶן נַעֲשֵׂית כְּדֹפֶן. הָיְתָה הַכַּלְכָּלָה מְלֵאָה פֵּרוֹת וְהָאֶבֶן בְּתוֹךְ הַפֵּרוֹת אִם הָיוּ הַפֵּרוֹת רְטֻבִּים כְּגוֹן עֲנָבִים וְתוּתִים נוֹטֵל אוֹתָהּ כְּמוֹת שֶׁהִיא שֶׁאִם יְנַעֵר הַפֵּרוֹת יִטָּנְפוּ בֶּעָפָר וּבִמְקוֹם הֶפְסֵד לֹא גָּזְרוּ:","חָבִית שֶׁשָּׁכַח אֶבֶן עַל פִּיהָ מַטָּהּ עַל צִדָּהּ וְהִיא נוֹפֶלֶת. הָיְתָה בֵּין הֶחָבִיּוֹת וְהָאֶבֶן עָלֶיהָ מַגְבִּיהָהּ לְמָקוֹם אַחֵר וּמַטֶּה עַל צִדָּהּ שָׁם וְהָאֶבֶן נוֹפֶלֶת. וְכֵן הַשּׁוֹכֵחַ מָעוֹת עַל הַכַּר וְצָרַךְ לַכַּר נוֹעֵר אֶת הַכַּר וְהֵן נוֹפְלוֹת. וְאִם צָרִיךְ לִמְקוֹם הַכַּר נוֹטֵל אֶת הַכַּר וְהַמָּעוֹת עָלָיו. אֲבָל אִם הִנִּיחַ הַמָּעוֹת מֵעֶרֶב שַׁבָּת עַל הַכַּר אוֹ הִנִּיחַ הָאֶבֶן עַל פִּי הֶחָבִית הֲרֵי אֵלּוּ אֲסוּרִין לְטַלְטְלָן וַאֲפִלּוּ נִטְּלוּ הַמָּעוֹת וְהָאֶבֶן שֶׁהֲרֵי נַעֲשׂוּ בָּסִיס לְדָבָר הָאָסוּר:","הָאֶבֶן שֶׁבַּקֵּרוּיָה אִם מְמַלְּאִין בָּהּ וְאֵינָהּ נוֹפֶלֶת הֲרֵי הִיא כְּמִקְצַת הַקֵּרוּיָה וּמֻתָּר לְמַלְּאוֹת בָּהּ וְאִם לָאו אֵין מְמַלְּאִין בָּהּ. בֶּגֶד שֶׁעַל הַקָּנֶה שׁוֹמְטוֹ מֵעַל הַקָּנֶה:","פֵּרוֹת שֶׁאָסוּר לֶאֱכל כְּגוֹן פֵּרוֹת שֶׁאֵינָם מְעֵשָּׂרִין אֲפִלּוּ הֵן חַיָּבִין בְּמַעֲשֵׂר מִדִּבְרֵיהֶם אוֹ מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ אוֹ תְּרוּמָה טְמֵאָה אוֹ מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ כְּהִלְכָתָן אָסוּר לְטַלְטְלָן. אֲבָל הַדְּמַאי הוֹאִיל וְרָאוּי לָעֲנִיִּים וְכֵן מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁפְּדָאָן אַף עַל פִּי שֶׁלֹּא נָתַן הַחֹמֶשׁ מֻתָּר לְטַלְטְלָן:","מְטַלְטֵל יִשְׂרָאֵל הַתְּרוּמָה אַף עַל פִּי שֶׁאֵינָהּ רְאוּיָה לוֹ. וּמְטַלְטְלִין תְּרוּמָה טְמֵאָה עִם הַטְּהוֹרָה אוֹ עִם הַחֻלִּין אִם הָיוּ שְׁנֵיהֶם בִּכְלִי אֶחָד. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיְתָה הַטְּהוֹרָה לְמַטָּה וְהָיוּ פֵּרוֹת הַמִּתְטַנְּפִין בַּקַּרְקַע שֶׁאִם יְנַעֵר אוֹתָן יִפָּסְדוּ. אֲבָל אִם הָיוּ אֱגוֹזִים וּשְׁקֵדִים וְכַיּוֹצֵא בָּהֶן נוֹעֵר הַכְּלִי וְנוֹטֵל הַטְּהוֹרָה אוֹ הַחֻלִּין וּמַנִּיחַ הַטֻּמְאָה. וְאִם הָיָה צָרִיךְ לִמְקוֹם הַכְּלִי בֵּין שֶׁהַטְּהוֹרָה לְמַעְלָה בֵּין שֶׁהָיְתָה לְמַטָּה מְטַלְטֵל הַכּל כְּאֶחָד:","נִדְבָּךְ שֶׁל אֲבָנִים שֶׁחָשַׁב עָלָיו מִבְּעוֹד יוֹם אִם לִמְדּוּם מֻתָּר לֵישֵׁב עֲלֵיהֶן לְמָחָר וְאִם לָאו אָסוּר. חֲרָיוֹת שֶׁל דֶּקֶל שֶׁגְּדָרָן לְעֵצִים וְנִמְלַךְ עֲלֵיהֶן מֵעֶרֶב שַׁבָּת לִישִׁיבָה מֻתָּר לְטַלְטְלָן. וְכֵן אִם יָשַׁב עֲלֵיהֶן מִבְּעוֹד יוֹם מֻתָּר לְטַלְטְלָן:","הַקַּשׁ שֶׁעַל הַמִּטָּה לֹא יְנַעְנְעֶנּוּ בְּיָדוֹ אֲבָל מְנַעְנְעוֹ בְּגוּפוֹ. וְאִם הוּא מַאֲכַל בְּהֵמָה מֻתָּר לְטַלְטְלוֹ. וְכֵן אִם הָיָה עָלָיו כַּר אוֹ סָדִין וְכַיּוֹצֵא בָּהֶן מְנַעְנְעוֹ בְּיָדוֹ שֶׁהֲרֵי נַעֲשָׂה כְּמִי שֶׁיָּשַׁב עָלָיו מִבְּעוֹד יוֹם. הַמַּכְנִיס קֻפָּה שֶׁל עָפָר בְּבֵיתוֹ אִם יִחֵד לָהּ קֶרֶן זָוִית מֵעֶרֶב שַׁבָּת מְטַלְטְלוֹ בְּשַׁבָּת וְעוֹשֶׂה בּוֹ כָּל צְרָכָיו:","אָסוּר לְבַטֵּל כְּלִי מֵהֵיכָנוֹ מִפְּנֵי שֶׁהוּא כְּסוֹתֵר. כֵּיצַד. לֹא יִתֵּן כְּלִי תַּחַת הַנֵּר בְּשַׁבָּת לְקַבֵּל אֶת הַשֶּׁמֶן הַנּוֹטֵף. שֶׁהַשֶּׁמֶן שֶׁבַּנֵּר אָסוּר לְטַלְטְלוֹ וּכְשֶׁיִּפּוֹל לַכְּלִי יֵאָסֵר טִלְטוּל הַכְּלִי שֶׁהָיָה מֻתָּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ אֵין נוֹתְנִין כְּלִי תַּחַת הַתַּרְנְגלֶת לְקַבֵּל בֵּיצָתָהּ. אֲבָל כּוֹפֶה הוּא הַכְּלִי עָלֶיהָ. וְכֵן כּוֹפֶה הַכְּלִי עַל כָּל דָּבָר שֶׁאָסוּר לְטַלְטְלוֹ שֶׁהֲרֵי לֹא בִּטְּלוֹ שֶׁאִם יַחְפֹּץ יִטְּלֶנּוּ:","נוֹתְנִין כְּלִי תַּחַת הַדֶּלֶף וְאִם נִתְמַלֵּא הַכְּלִי שׁוֹפֵךְ וְשׁוֹנֶה וְאֵינוֹ נִמְנָע. וְהוּא שֶׁיִּהְיֶה הַדֶּלֶף רָאוּי לִרְחִיצָה אֲבָל אִם אֵינוֹ רָאוּי אֵין נוֹתְנִין וְאִם נָתַן מֻתָּר לְטַלְטְלוֹ בַּמַּיִם הַמְּאוּסִין שֶׁבּוֹ. שֶׁאֵין עוֹשִׂין גְּרָף שֶׁל רְעִי לְכַתְּחִלָּה:","חָבִית שֶׁל טֶבֶל שֶׁנִּשְׁבְּרָה מֵבִיא כְּלִי וּמַנִּיחַ תַּחְתֶּיהָ הוֹאִיל וְאִם עָבַר וְתִקְּנוֹ מְתֻקָּן הֲרֵי הוּא כִּמְתֻקָּן. וְנוֹתְנִין כְּלִי תַּחַת הַנֵּר לְקַבֵּל נִיצוֹצוֹת מִפְּנֵי שֶׁאֵין בָּהֶן מַמָּשׁ וּמֻתָּר לְטַלְטֵל הַכְּלִי. קוֹרָה שֶׁנִּשְׁבְּרָה אֵין סוֹמְכִין אוֹתָהּ בְּסַפְסָל אוֹ בַּאֲרוּכּוֹת הַמִּטָּה אֶלָּא אִם כֵּן הָיוּ רְוָחִים וְכָל זְמַן שֶׁיַּחְפֹּץ יִטְלֵם כְּדֵי שֶׁלֹּא יְבַטֵּל כְּלִי מֵהֵיכָנוֹ. פּוֹרְסִין מַחְצֶלֶת עַל גַּבֵּי אֲבָנִים בְּשַׁבָּת אוֹ עַל גַּבֵּי כַּוֶּרֶת דְּבוֹרִים בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לָצוּד שֶׁהֲרֵי נוֹטְלָהּ בְּכָל עֵת שֶׁיִּרְצֶה. וְכוֹפִין אֶת הַסַּל בְּשַׁבָּת לִפְנֵי הָאֶפְרוֹחִים בִּשְׁבִיל שֶׁיַּעֲלוּ עָלָיו וְיֵרְדוּ שֶׁהֲרֵי מֻתָּר לְטַלְטְלוֹ כְּשֶׁיֵּרְדוּ מֵעָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בְּהֵמָה שֶׁנָּפְלָה לְבוֹר אוֹ לְאַמַּת הַמַּיִם אִם יָכוֹל לִתֵּן לָהּ פַּרְנָסָה בִּמְקוֹמָהּ מְפַרְנְסִין אוֹתָהּ עַד מוֹצָאֵי שַׁבָּת וְאִם לָאו מֵבִיא כָּרִים וּכְסָתוֹת וּמַנִּיחַ תַּחְתֶּיהָ וְאִם עָלְתָה עָלְתָה. וְאַף עַל פִּי שֶׁמְּבַטֵּל כְּלִי מֵהֵיכָנוֹ שֶׁהֲרֵי מַשְׁלִיכוֹ לַבּוֹר לְתוֹךְ הַמַּיִם מִפְּנֵי צַעַר בַּעֲלֵי חַיִּים לֹא גָּזְרוּ. וְאָסוּר לְהַעֲלוֹתָהּ בְּיָדוֹ. וְכֵן אֵין עוֹקְרִין בְּהֵמָה וְחַיָּה וְעוֹף בְּחָצֵר אֲבָל דּוֹחִין אוֹתָן עַד שֶׁיִּכָּנְסוּ. וּמְדַדִּין עֲגָלִים וּסְיָחִים. תַּרְנְגלֶת שֶׁבָּרְחָה אֵין מְדַדִּין אוֹתָן מִפְּנֵי שֶׁהִיא נִשְׁמֶטֶת מִן הַיָּד וְנִמְצְאוּ אֲגַפֶּיהָ נִתְלָשִׁין אֲבָל דּוֹחִין אוֹתָהּ עַד שֶׁתִּכָּנֵס:"],"Mishneh Torah, Sabbath 9":["הָאוֹפֶה כִּגְרוֹגֶרֶת חַיָּב. אֶחָד הָאוֹפֶה אֶת הַפַּת אוֹ הַמְבַשֵּׁל אֶת הַמַּאֲכָל אוֹ אֶת הַסַּמְמָנִין אוֹ הַמְחַמֵּם אֶת הַמַּיִם הַכּל עִנְיָן אֶחָד הוּא. שִׁעוּר הַמְחַמֵּם אֶת הַמַּיִם כְּדֵי לִרְחֹץ בָּהֶן אֵיבָר קָטָן. וְשִׁעוּר מְבַשֵּׁל סַמְמָנִין כְּדֵי שֶׁיִּהְיוּ רְאוּיִין לְדָבָר שֶׁמְּבַשְּׁלִין אוֹתָן לוֹ:","הַנּוֹתֵן בֵּיצָה בְּצַד הַמֵּיחַם בִּשְׁבִיל שֶׁתִּתְגַּלְגֵּל וְנִתְגַּלְגְּלָה חַיָּב. שֶׁהַמְבַשֵּׁל בְּתוֹלֶדֶת הָאוּר כִּמְבַשֵּׁל בָּאוּר עַצְמָהּ. וְכֵן הַמֵּדִיחַ בְּחַמִּין דָּג מָלִיחַ הַיָּשָׁן אוֹ קוּלְיָיס הָאִסְפָּנִין וְהוּא דָּג דַּק וְרַךְ בְּיוֹתֵר הֲרֵי זֶה חַיָּב. שֶׁהֲדָחָתָן בְּחַמִּין זֶה הוּא גְּמַר בִּשּׁוּלָן. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","הַמַּפְקִיעַ אֶת הַבֵּיצָה בְּבֶגֶד חַם אוֹ בְּחוֹל וּבַאֲבַק דְּרָכִים שֶׁהֵן חַמִּים מִפְּנֵי הַשֶּׁמֶשׁ אַף עַל פִּי שֶׁנִּצְלֵית פָּטוּר. שֶׁתּוֹלְדוֹת חַמָּה אֵינָם כְּתוֹלְדוֹת הָאֵשׁ. אֲבָל גָּזְרוּ עֲלֵיהֶן מִפְּנֵי תּוֹלְדוֹת הָאוּר. וְכֵן הַמְבַשֵּׁל בְּחַמֵּי טְבֶרְיָה וְכַיּוֹצֵא בָּהֶם פָּטוּר. הַמְבַשֵּׁל עַל הָאוּר דָּבָר שֶׁהָיָה מְבֻשָּׁל כָּל צָרְכּוֹ אוֹ דָּבָר שֶׁאֵינוֹ צָרִיךְ בִּשּׁוּל כְּלָל פָּטוּר:","אֶחָד נָתַן אֶת הָאוּר וְאֶחָד נָתַן אֶת הָעֵצִים וְאֶחָד נָתַן אֶת הַקְּדֵרָה וְאֶחָד נָתַן אֶת הַמַּיִם וְאֶחָד נָתַן אֶת הַבָּשָׂר וְאֶחָד נָתַן אֶת הַתַּבְלִין וּבָא אַחֵר וְהֵגִיס כֻּלָּם חַיָּבִים מִשּׁוּם מְבַשֵּׁל. שֶׁכָּל הָעוֹשֶׂה דָּבָר מִצָּרְכֵי הַבִּשּׁוּל הֲרֵי זֶה מְבַשֵּׁל. אֲבָל אִם שָׁפַת אֶחָד אֶת הַקְּדֵרָה תְּחִלָּה וּבָא אַחֵר וְנָתַן אֶת הַמַּיִם וּבָא אַחֵר וְנָתַן אֶת הַבָּשָׂר וּבָא אַחֵר וְנָתַן אֶת הַתַּבְלִין וּבָא אַחֵר וְנָתַן אֶת הָאוּר וּבָא אַחֵר וְנָתַן עֵצִים עַל הָאוּר וּבָא אַחֵר וְהֵגִיס. שְׁנַיִם הָאַחֲרוֹנִים בִּלְבַד חַיָּבִין מִשּׁוּם מְבַשֵּׁל:","הִנִּיחַ בָּשָׂר עַל גַּבֵּי גֶּחָלִים אִם נִצְלָה בּוֹ כִּגְרוֹגֶרֶת אֲפִלּוּ בִּשְׁנַיִם וּשְׁלֹשָׁה מְקוֹמוֹת חַיָּב. לֹא נִצְלָה בּוֹ כִּגְרוֹגֶרֶת אֲבָל נִתְבַּשֵּׁל כֻּלּוֹ חֲצִי בִּשּׁוּל חַיָּב. נִתְבַּשֵּׁל חֲצִי בִּשּׁוּל מִצַּד אֶחָד פָּטוּר. עַד שֶׁיַּהֲפֹךְ בּוֹ וְיִתְבַּשֵּׁל חֲצִי בִּשּׁוּל מִשְּׁנֵי צְדָדִין. שָׁכַח וְהִדְבִּיק פַּת בַּתַּנּוּר בְּשַׁבָּת וְנִזְכַּר מֻתָּר לוֹ לִרְדוֹתָה קֹדֶם שֶׁתֵּאָפֶה וְיָבוֹא לִידֵי מְלָאכָה:","הַמַּתִּיךְ אֶחָד מִמִּינֵי מַתָּכוֹת כָּל שֶׁהוּא אוֹ הַמְחַמֵּם אֶת הַמַּתָּכוֹת עַד שֶׁתֵּעָשֶׂה גַּחֶלֶת הֲרֵי זֶה תּוֹלֶדֶת מְבַשֵּׁל. וְכֵן הַמְמַסֵּס אֶת הַדּוֹנַג אוֹ אֶת הַחֵלֶב אוֹ אֶת הַזֶּפֶת וְהַכֹּפֶר וְהַגָּפְרִית וְכַיּוֹצֵא בָּהֶם הֲרֵי זֶה תּוֹלֶדֶת מְבַשֵּׁל וְחַיָּב. וְכֵן הַמְבַשֵּׁל כְּלֵי אֲדָמָה עַד שֶׁיֵּעָשׂוּ חֶרֶס חַיָּב מִשּׁוּם מְבַשֵּׁל. כְּלָלוֹ שֶׁל דָּבָר בֵּין שֶׁרִפָּה גּוּף קָשֶׁה בָּאֵשׁ אוֹ שֶׁהִקְשָׁה גּוּף רַךְ הֲרֵי זֶה חַיָּב מִשּׁוּם מְבַשֵּׁל:","הַגּוֹזֵז צֶמֶר אוֹ שֵׂעָר בֵּין מִן הַבְּהֵמָה בֵּין מִן הַחַיָּה בֵּין מִן הַחַי בֵּין מִן הַמֵּת אֲפִלּוּ מִן הַשֶּׁלַח שֶׁלָּהֶן חַיָּב. כַּמָּה שִׁעוּרוֹ כְּדֵי לִטְווֹת מִמֶּנּוּ חוּט שֶׁאָרְכּוֹ כְּרֹחַב הַסִּיט כָּפוּל. וְכַמָּה רֹחַב הַסִּיט כְּדֵי לִמְתֹּחַ מִן בֹּהֶן שֶׁל יָד עַד הָאֶצְבַּע הָרִאשׁוֹנָה כְּשֶׁיִּפְתַּח בֵּינֵיהֶן בְּכָל כֹּחוֹ וְהוּא קָרוֹב לִשְׁנֵי שְׁלִישֵׁי זֶרֶת. הַתּוֹלֵשׁ כָּנָף מִן הָעוֹף הֲרֵי זֶה תּוֹלֶדֶת גּוֹזֵז. הַטּוֹוֶה אֶת הַצֶּמֶר מִן הַחַי פָּטוּר שֶׁאֵין דֶּרֶךְ גְּזִיזָה בְּכָךְ וְאֵין דֶּרֶךְ נִפּוּץ בְּכָךְ וְאֵין דֶּרֶךְ טְוִיָּה בְּכָךְ:","הַנּוֹטֵל צִפָּרְנָיו אוֹ שְׂעָרוֹ אוֹ שְׂפָמוֹ אוֹ זְקָנוֹ הֲרֵי זֶה תּוֹלֶדֶת גּוֹזֵז וְחַיָּב. וְהוּא שֶׁיִּטּל בִּכְלִי. אֲבָל אִם נְטָלָן בְּיָדוֹ בֵּין לוֹ בֵּין לְאַחֵר פָּטוּר. וְכֵן הַחוֹתֵךְ יַבֶּלֶת מִגּוּפוֹ בֵּין בְּיָד בֵּין בִּכְלִי פָּטוּר בֵּין לוֹ בֵּין לְאַחֵר. וּמֻתָּר לַחְתֹּךְ יַבֶּלֶת בַּמִּקְדָּשׁ בְּיָד אֲבָל לֹא בִּכְלִי. וְאִם הָיְתָה יְבֵשָׁה חוֹתְכָהּ אַף בִּכְלִי וְעוֹבֵד עֲבוֹדָה:","הַנּוֹטֵל שְׂעָרוֹ בִּכְלִי כַּמָּה יִטּל וְיִהְיֶה חַיָּב. שְׁתֵּי שְׂעָרוֹת. וְאִם לִקֵּט לְבָנוֹת מִתּוֹךְ שְׁחוֹרוֹת אֲפִלּוּ אַחַת חַיָּב. צִפֹּרֶן שֶׁפֵּרְשָׁה רֻבָּהּ וְצִיצִין שֶׁל עוֹר שֶׁפֵּרְשׁוּ רֻבָּן אִם פֵּרְשׁוּ כְּלַפֵּי מַעְלָה וּמְצַעֲרוֹת אוֹתוֹ מֻתָּר לִטּל אוֹתָן בְּיָדוֹ אֲבָל לֹא בִּכְלִי. וְאִם נְטָלָן בִּכְלִי פָּטוּר. וְאִם אֵינָן מְצַעֲרוֹת אוֹתוֹ אֲפִלּוּ בַּיָּד אָסוּר. וְאִם לֹא פֵּרְשׁוּ רֻבָּן אֲפִלּוּ מְצַעֲרוֹת אוֹתוֹ אָסוּר לְנָטְלָן בְּיָדוֹ וְאִם נְטָלָן בִּכְלִי חַיָּב:","הַמְלַבֵּן אֶת הַצֶּמֶר אוֹ אֶת הַפִּשְׁתָּן אוֹ אֶת הַשָּׁנִי. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן מִמַּה שֶּׁדַּרְכָּן לְהִתְלַבֵּן חַיָּב. וְכַמָּה שִׁעוּרוֹ כְּדֵי לִטְווֹת מִמֶּנּוּ חוּט אֶחָד אָרְכּוֹ כִּמְלֹא רֹחַב הַסִּיט כָּפוּל שֶׁהוּא אֹרֶךְ אַרְבָּעָה טְפָחִים:","הַמְכַבֵּס בְּגָדִים הֲרֵי הוּא תּוֹלֶדֶת מְלַבֵּן וְחַיָּב. והַסּוֹחֵט אֶת הַבֶּגֶד עַד שֶׁיּוֹצִיא הַמַּיִם שֶׁבּוֹ הֲרֵי זֶה מְכַבֵּס וְחַיָּב. שֶׁהַסְּחִיטָה מִצָּרְכֵי כִּבּוּס הִיא כְּמוֹ שֶׁהַהֲגָסָה מִצָּרְכֵי הַבִּשּׁוּל. וְאֵין סְחִיטָה בְּשֵׂעָר וְהוּא הַדִּין לְעוֹר שֶׁאֵין חַיָּבִין עַל סְחִיטָתוֹ:","הַמְנַפֵּץ אֶת הַצֶּמֶר אוֹ אֶת הַפִּשְׁתָּן אוֹ אֶת הַשָּׁנִי וְכַיּוֹצֵא בָּהֶן חַיָּב. וְכַמָּה שִׁעוּרוֹ כְּדֵי לִטְווֹת מִמֶּנּוּ חוּט אֶחָד אָרְכּוֹ אַרְבָּעָה טְפָחִים. וְהַמְנַפֵּץ אֶת הַגִּידִים עַד שֶׁיֵּעָשׂוּ כְּצֶמֶר כְּדֵי לִטְווֹת אוֹתָן הֲרֵי זֶה תּוֹלֶדֶת מְנַפֵּץ וְחַיָּב:","הַצּוֹבֵעַ חוּט שֶׁאָרְכּוֹ אַרְבָּעָה טְפָחִים אוֹ דָּבָר שֶׁאֶפְשָׁר לִטְווֹת מִמֶּנּוּ חוּט כָּזֶה חַיָּב. וְאֵין הַצּוֹבֵעַ חַיָּב עַד שֶׁיְּהֵא צֶבַע הַמִּתְקַיֵּם. אֲבָל צֶבַע שֶׁאֵינוֹ מִתְקַיֵּם כְּלָל כְּגוֹן שֶׁהֶעֱבִיר סָרָק אוֹ שָׁשַׁר עַל גַּבֵּי בַּרְזֶל אוֹ נְחשֶׁת וּצְבָעוֹ פָּטוּר. שֶׁהֲרֵי אַתָּה מַעֲבִירוֹ לִשְׁעָתוֹ וְאֵינוֹ צוֹבֵעַ כְּלוּם. וְכָל שֶׁאֵין מְלַאכְתּוֹ מִתְקַיֶּמֶת בְּשַׁבָּת פָּטוּר:","הָעוֹשֶׂה עֵין הַצֶּבַע הֲרֵי זֶה תּוֹלֶדֶת צוֹבֵעַ וְחַיָּב. כֵּיצַד. כְּגוֹן שֶׁנָּתַן קַנְקַנְתּוֹם לְתוֹךְ מֵי עַפְּצָא שֶׁנַּעֲשָׂה הַכּל שָׁחוֹר. אוֹ שֶׁנָּתַן אִיסְטִיס לְתוֹךְ מֵי כַּרְכֹּם שֶׁנַּעֲשָׂה הַכּל יָרֹק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכַמָּה שִׁעוּרוֹ כְּדֵי לִצְבֹּעַ בּוֹ חוּט שֶׁאָרְכּוֹ אַרְבָּעָה טְפָחִים:","הַטּוֹוֶה אֹרֶךְ אַרְבָּעָה טְפָחִים מִכָּל דָּבָר הַנִּטְוֶה חַיָּב. אֶחָד הַטּוֹוֶה אֶת הַצֶּמֶר אוֹ אֶת הַפִּשְׁתָּן אוֹ אֶת הַנּוֹצָה אוֹ אֶת הַשֵּׂעָר אוֹ אֶת הַגִּידִין. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. הָעוֹשֶׂה אֶת הַלֶּבֶד הֲרֵי זֶה תּוֹלֶדֶת טוֹוֶה וְחַיָּב. וְהוּא שֶׁיְּלַבֵּד דָּבָר שֶׁאֶפְשָׁר לִטְווֹת מִמֶּנּוּ חוּט אֹרֶךְ אַרְבָּעָה טְפָחִים בְּעֹבִי בֵּינוֹנִי:","הָעוֹשֶׂה שְׁנֵי בָּתֵּי נִירִין חַיָּב. הָעוֹשֶׂה נָפָה אוֹ כְּבָרָה אוֹ סַל אוֹ סְבָכָה אוֹ שֶׁסָּרַג מִטָּה בַּחֲבָלִים הֲרֵי זֶה תּוֹלֶדֶת עוֹשֶׂה נִירִין וּמִשֶּׁיַּעֲשֶׂה שְׁנֵי בָּתִּים בְּאֶחָד מִכָּל אֵלּוּ חַיָּב. וְכֵן כָּל הָעוֹשֶׂה שְׁנֵי בָּתֵּי נִירִין בְּדָבָר שֶׁעוֹשִׂין אוֹתוֹ בָּתִּים בָּתִּים כְּגוֹן אֵלּוּ חַיָּב:","דֶּרֶךְ הָאוֹרְגִין שֶׁמּוֹתְחִין הַחוּטִין תְּחִלָּה בְּאֹרֶךְ הַיְרִיעָה וּבְרָחְבָּהּ וּשְׁנַיִם אוֹחֲזִין זֶה מִכָּאן וְזֶה מִכָּאן וְאֶחָד שׁוֹבֵט בְּשֵׁבֶט עַל הַחוּטִין וּמְתַקֵּן אוֹתָן זֶה בְּצַד זֶה עַד שֶׁתֵּעָשֶׂה כֻּלָּהּ שְׁתִי בְּלֹא עֵרֶב. וּמְתִיחַת הַחוּטִין כְּדֶרֶךְ הָאוֹרְגִין הִיא הַנְסָכַת הַמַּסֶּכֶת וְזֶה הַמּוֹתֵחַ נִקְרָא מֵסֵךְ. וּכְשֶׁכּוֹפְלִין אוֹתָהּ וּמַתְחִיל לְהַכְנִיס הַשְּׁתִי בָּעֵרֶב נִקְרָא אוֹרֵג:","הַמֵּסֵךְ חַיָּב וְהִיא מְלָאכָה מֵאֲבוֹת מְלָאכוֹת. וְהַשּׁוֹבֵט עַל הַחוּטִין עַד שֶׁיִּפָּרְקוּ וִיתַקְּנֵם הֲרֵי זֶה תּוֹלֶדֶת מֵסֵךְ. וְכַמָּה שִׁעוּרוֹ מִשֶּׁיְּתַקֵּן רֹחַב שְׁתֵּי אֶצְבָּעוֹת. וְכֵן הָאוֹרֵג שְׁנֵי חוּטִין בְּרֹחַב שְׁתֵּי אֶצְבָּעוֹת חַיָּב. בֵּין שֶׁאֲרָגָן בַּתְּחִלָּה בֵּין שֶׁהָיָה מִקְצָת הַבֶּגֶד אָרוּג וְאָרַג עַל הָאָרוּג שִׁעוּרוֹ שְׁנֵי חוּטִין. וְאִם אָרַג חוּט אֶחָד וְהִשְׁלִים בּוֹ הַבֶּגֶד חַיָּב. אָרַג בִּשְׂפַת הַיְרִיעָה שְׁנֵי חוּטִין בְּרֹחַב שְׁלֹשָׁה בָּתֵּי נִירִין חַיָּב. הָא לְמָה זֶה דּוֹמֶה לְאוֹרֵג צִלְצוּל קָטָן בְּרֹחַב שְׁלֹשָׁה בָּתֵּי נִירִין:","הַמְדַקְדֵּק אֶת הַחוּטִין וּמַפְרִידָן בְּעֵת הָאֲרִיגָה הֲרֵי זֶה תּוֹלֶדֶת אוֹרֵג. וְכֵן הַקּוֹלֵעַ אֶת הַנִּימִין הֲרֵי זֶה תּוֹלֶדֶת אוֹרֵג וְשִׁעוּרוֹ מִשֶּׁיַּעֲשֶׂה קְלִיעָה בְּאֹרֶךְ שְׁתֵּי אֶצְבָּעוֹת:","הַבּוֹצֵעַ שְׁנֵי חוּטִין חַיָּב. וּבוֹצֵעַ הוּא הַמַּפְרִישׁ אֶת הָאָרוּג. בֵּין שֶׁהוֹצִיא הָעֵרֶב מִן הַשְּׁתִי אוֹ שֶׁהֶעֱבִיר הַשְּׁתִי מֵעַל הָעֵרֶב הֲרֵי זֶה בּוֹצֵעַ וְחַיָּב. וְהוּא שֶׁלֹּא יְהֵא מְקַלְקֵל אֶלָּא יִתְכַּוֵּן לְתַקֵּן כְּדֶרֶךְ שֶׁעוֹשִׂין אֵלּוּ שֶׁמְּאַחִין אֶת הַבְּגָדִים הַקַּלִּים בְּיוֹתֵר שֶׁבּוֹצְעִין וְאַחַר כָּךְ מְאַחִין וְחוֹזְרִין וְאוֹרְגִין חוּטִין שֶׁבָּצְעוּ עַד שֶׁיֵּעָשׂוּ שְׁנֵי הַבְּגָדִים אוֹ שְׁנֵי הַקְּרָעִים אֶחָד. וְהַסּוֹתֵר אֶת הַקְּלִיעָה לְתַקֵּן הֲרֵי זֶה תּוֹלֶדֶת בּוֹצֵעַ וְשִׁעוּרוֹ כְּשִׁעוּר הַבּוֹצֵעַ:"],"Mishneh Torah, Sabbatical Year and the Jubilee 8":["כְּדֶרֶךְ שֶׁאָסוּר לַעֲבֹד הָאָרֶץ בַּשְּׁבִיעִית כָּךְ אָסוּר לְחַזֵּק יְדֵי יִשְׂרָאֵל שֶׁעוֹבְדִין אוֹתָהּ. אוֹ לִמְכֹּר לָהֶן כְּלֵי עֲבוֹדָה. לְפִי שֶׁאָסוּר לְחַזֵּק יְדֵי עוֹבְרֵי עֲבֵרָה:","וְאֵלּוּ כֵּלִים שֶׁאֵין הָאֻמָּן רַשַּׁאי לְמָכְרָן בַּשְּׁבִיעִית לְמִי שֶׁחָשׁוּד עַל הַשְּׁבִיעִית. מַחְרֵשָׁה וְכָל כֵּלֶיהָ הָעל וְהַמַּזְּרֶה וְהַדֶּקֶר. זֶה הַכְּלָל כָּל שֶׁמְּלַאכְתּוֹ מְיֻחֶדֶת לִמְלָאכָה שֶׁאֲסוּרָה בַּשְּׁבִיעִית אָסוּר לְמָכְרוֹ לְחָשׁוּד. וְלִמְלָאכָה שֶׁאֶפְשָׁר שֶׁתִּהְיֶה אֲסוּרָה וְתִהְיֶה מֻתֶּרֶת מֻתָּר לְמָכְרוֹ לְחָשׁוּד:","כֵּיצַד. מוֹכֵר הוּא לוֹ הַמַּגָּל וְהָעֲגָלָה וְכָל כֵּלֶיהָ. שֶׁאִם יִקְצֹר בּוֹ מְעַט וְיָבִיא עַל הָעֲגָלָה מְעַט הֲרֵי זֶה מֻתָּר. וְאִם יִקְצֹר כְּדֶרֶךְ הַקּוֹצְרִין אוֹ יָבִיא כָּל פֵּרוֹת שָׂדֵהוּ אָסוּר:","וּמֻתָּר לִמְכֹּר סְתָם לְמִי שֶׁאֵינוֹ חָשׁוּד אֲפִלּוּ דָּבָר שֶׁמְּלַאכְתּוֹ מְיֻחֶדֶת לִמְלָאכָה הָאֲסוּרָה בַּשְּׁבִיעִית. שֶׁהֲרֵי אֶפְשָׁר שֶׁקָּנָה בַּשְּׁבִיעִית לַעֲשׂוֹת לוֹ מְלָאכָה לְאַחַר שְׁבִיעִית:","הַיּוֹצֵר מוֹכֵר חָמֵשׁ כַּדֵי שֶׁמֶן וַחֲמִשָּׁה עָשָׂר כַּדֵּי יַיִן. וּמֻתָּר לִמְכֹּר לְעַכּוּ\"ם יֶתֶר מִזֶּה וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יִמְכֹּר לְיִשְׂרָאֵל. וּמוֹכֵר כַּדִּים רַבִּים לְיִשְׂרָאֵל בְּחוּצָה לָאָרֶץ וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יְבִיאֵם לָאָרֶץ:","וּמוֹכֵר לְחָשׁוּד פָּרָה חוֹרֶשֶׁת בַּשְּׁבִיעִית שֶׁהֲרֵי אֶפְשָׁר לְשָׁחֳטָהּ. וּמוֹכֵר לוֹ שָׂדֵהוּ שֶׁהֲרֵי אֶפְשָׁר שֶׁיּוֹבִירָהּ. אֲבָל לֹא יִמְכֹּר לוֹ שְׂדֵה הָאִילָן אֶלָּא אִם כֵּן פָּסַק עִמּוֹ עַל מְנָת שֶׁאֵין לוֹ בָּאִילָן. וּמַשְׁאִילוֹ סְאָה לִמְדֹּד בָּהּ אַף עַל פִּי שֶׁהוּא יוֹדֵעַ שֶׁיֵּשׁ לוֹ גֹּרֶן שֶׁהֲרֵי אֶפְשָׁר שֶׁיִּמְדֹּד בָּהּ בְּתוֹךְ בֵּיתוֹ. וּפוֹרֵט לוֹ מָעוֹת אַף עַל פִּי שֶׁהוּא יוֹדֵעַ שֶׁיֵּשׁ לוֹ פּוֹעֲלִים. וְכֻלָּן בְּפֵרוּשׁ אֲסוּרִים:","וְכֵן מַשְׁאֶלֶת אִשָּׁה לַחֲבֶרְתָּהּ הַחֲשׁוּדָה עַל הַשְּׁבִיעִית נָפָה וּכְבָרָה רֵחַיִם וְתַנּוּר. אֲבָל לֹא תָּבֹר וְלֹא תִּטְחֹן עִמָּהּ:","מַחֲזִיקִין יְדֵי עַכּוּ\"ם בַּשְּׁבִיעִית בִּדְבָרִים בִּלְבַד. כְּגוֹן שֶׁרָאָהוּ חוֹרֵשׁ אוֹ זוֹרֵעַ אוֹמֵר לוֹ תִּתְחַזֵּק אוֹ תַּצְלִיחַ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. מִפְּנֵי שֶׁאֵינָם מְצֻוִּין עַל שְׁבִיתַת הָאָרֶץ. אֲבָל לֹא יְסַעֲדֶּנוּ בַּיָּד. וּמֻתָּר לִרְדּוֹת עִמָּהֶן הַכַּוֶּרֶת וְחוֹכְרִין מֵהֶן נִירִין לְפִי שֶׁאֵינָן בְּנֵי חִיּוּב כְּדֵי לִקְנֹס אוֹתָן:","מֻתָּר לַעֲשׂוֹת בְּסוּרְיָא בְּתָלוּשׁ אֲבָל לֹא בַּמְחֻבָּר. כֵּיצַד. דָּשִׁין וְזוֹרִין וְדוֹרְכִין וּמְעַמְּרִין. אֲבָל לֹא קוֹצְרִין וְלֹא בּוֹצְרִין וְלֹא מוֹסְקִין. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ:","כְּשֵׁם שֶׁאָסוּר לַעֲשׂוֹת סְחוֹרָה בְּפֵרוֹת שְׁבִיעִית אוֹ לְשָׁמְרָן כָּךְ אָסוּר לִקַּח מֵעַם הָאָרֶץ. לְפִי שֶׁאֵין מוֹסְרִין דְּמֵי שְׁבִיעִית לְעַם הָאָרֶץ. וַאֲפִלּוּ כָּל שֶׁהוּא. שֶׁמָּא לֹא יֹאכַל אוֹתָן בִּקְדֻשַּׁת שְׁבִיעִית:","הַלּוֹקֵחַ לוּלָב מֵעַם הָאָרֶץ בַּשְּׁבִיעִית נוֹתֵן לוֹ אֶתְרוֹג מַתָּנָה. וְאִם לֹא נָתַן לוֹ מַבְלִיעַ לוֹ דְּמֵי אֶתְרוֹג בִּדְמֵי לוּלָב:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהָיָה מוֹכֵר פֵּרוֹת שֶׁכְּמוֹתָן בְּשָׁמוּר כְּגוֹן תְּאֵנִים וְרִמּוֹנִים וְכַיּוֹצֵא בָּהֶן. אֲבָל הָיָה מוֹכֵר פֵּרוֹת שֶׁחֶזְקָתָן מִן הַהֶפְקֵר כְּגוֹן הַפֵּיגָם וְהַיַּרְבּוּזִין וְהַשּׁוֹטִים וְהַחֲלַגְלוֹגוֹת וְהַכֻּסְבַּר שֶׁל הָרִים וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה מֻתָּר לִקַּח מִמֶּנּוּ מְעַט כִּדְמֵי שָׁלֹשׁ סְעֻדּוֹת בִּלְבַד מִשּׁוּם כְּדֵי חַיָּיו שֶׁל מוֹכֵר:","וְכָל דָּבָר שֶׁאֵינוֹ חַיָּב בְּמַעַשְׂרוֹת כְּגוֹן שׁוּם בַּעַל בְּכִי וּבָצָל שֶׁל רִכְפָּה וּגְרִיסִין הַקִּלְקִיּוֹת וַעֲדָשִׁים הַמִּצְרִיּוֹת וְכֵן זֵרְעוֹנֵי גִּנָּה שֶׁאֵינָן נֶאֱכָלוֹת כְּגוֹן זֶרַע לֶפֶת וּצְנוֹן וְכַיּוֹצֵא בָּהֶן הֲרֵי אֵלּוּ נִלְקָחִין מִכָּל אָדָם בַּשְּׁבִיעִית:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּעַם הָאָרֶץ סְתָם. אֲבָל מִי שֶׁהוּא חָשׁוּד לַעֲשׂוֹת סְחוֹרָה בְּפֵרוֹת שְׁבִיעִית אוֹ לִשְׁמֹר פֵּרוֹתָיו וְלִמְכֹּר מֵהֶן אֵין לוֹקְחִין מִמֶּנּוּ דָּבָר שֶׁיֵּשׁ עָלָיו זִקַּת שְׁבִיעִית כְּלָל. וְאֵין לוֹקְחִין מִמֶּנּוּ פִּשְׁתָּן אֲפִלּוּ סָרוּק. אֲבָל לוֹקְחִין מִמֶּנּוּ טָווּי וְשָׁזוּר:","הֶחָשׁוּד עַל הַשְּׁבִיעִית אֵינוֹ חָשׁוּד עַל הַמַּעַשְׂרוֹת. וְהֶחָשׁוּד עַל הַמַּעַשְׂרוֹת אֵינוֹ חָשׁוּד עַל הַשְּׁבִיעִית. שֶׁאַף עַל פִּי שֶׁזֶּה וְזֶה מִן הַתּוֹרָה. מַעֲשֵׂר טָעוּן הֲבָאַת מָקוֹם מַה שֶּׁאֵין כֵּן בַּשְּׁבִיעִית. וּשְׁבִיעִית אֵין לָהּ פִּדְיוֹן מַה שֶּׁאֵין כֵּן בְּמַעֲשֵׂר:","הֶחָשׁוּד עַל הַטָּהֳרוֹת אֵינוֹ חָשׁוּד לֹא עַל הַמַּעֲשֵׂר וְלֹא עַל הַשְּׁבִיעִית. שֶׁהָאֹכֶל הַטָּמֵא הַזֶּה שֶׁמְּכָרוֹ בְּחֶזְקַת טָהוֹר אֵינוֹ מְטַמֵּא אֲחֵרִים אֶלָּא מִדִּבְרֵי סוֹפְרִים. וְהֶחָשׁוּד לְדִבְרֵי סוֹפְרִים אֵינוֹ חָשׁוּד לְדִבְרֵי תּוֹרָה:","כָּל הֶחָשׁוּד עַל דָּבָר אַף עַל פִּי שֶׁאֵינוֹ נֶאֱמָן עַל שֶׁל עַצְמוֹ נֶאֱמָן הוּא עַל שֶׁל אֲחֵרִים חֲזָקָה אֵין אָדָם חוֹטֵא לַאֲחֵרִים. לְפִיכָךְ הֶחָשׁוּד עַל הַדָּבָר דָּנוֹ וּמְעִידוֹ:","הַכֹּהֲנִים חֲשׁוּדִין עַל הַשְּׁבִיעִית לְפִי שֶׁהֵם אוֹמְרִים הוֹאִיל וְהַתְּרוּמוֹת מֻתָּרוֹת לָנוּ אַף עַל פִּי שֶׁהֵן אֲסוּרִין עַל הַזָּרִים בְּמִיתָה קַל וָחֹמֶר פֵּרוֹת שְׁבִיעִית. לְפִיכָךְ סְאָה תְּרוּמָה שֶׁנָּפְלָה לְמֵאָה סְאָה שֶׁל פֵּרוֹת שְׁבִיעִית תַּעֲלֶה. נָפְלָה לְפָחוֹת מִמֵּאָה יֵרָקְבוּ הַכּל וְלֹא יִמָּכְרוּ לַכֹּהֲנִים כְּכָל מְדֻמָּע לְפִי שֶׁהֵם חֲשׁוּדִין עַל הַשְּׁבִיעִית:","הַצַּבְעָנִין וְהַפַּטָּמִין לוֹקְחִין מֻרְסָן מִכָּל מָקוֹם. וְאֵינָן חוֹשְׁשִׁין שֶׁמָּא מִסְּפִיחֵי שְׁבִיעִית הוּא:","גַּבָּאֵי קֻפָּה בַּשְּׁבִיעִית לֹא יִהְיוּ מְדַקְדְּקִין בַּחֲצֵרוֹת שֶׁל אוֹכְלִין שְׁבִיעִית. וְאִם נָתְנוּ לָהֶן פַּת מֻתֶּרֶת וְאֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא מִסְּפִיחֵי שְׁבִיעִית הוּא. שֶׁלֹּא נֶחְשְׁדוּ יִשְׂרָאֵל לִהְיוֹת נוֹתְנִין אֶלָּא אוֹ מְעוֹת שְׁבִיעִית אוֹ בֵּיצִים הַנִּלְקָחוֹת בִּדְמֵי שְׁבִיעִית. וּמֻתָּר לִלְווֹת מִן הָעֲנִיִּים פֵּרוֹת שְׁבִיעִית וּמַחְזִירִין לָהֶן פֵּרוֹת בְּשָׁנָה שְׁמִינִית:"],"Mishneh Torah, Sacrifices Rendered Unfit 19":["מִצְוַת עֲשֵׂה לִשְׂרֹף כָּל הקָּדָשִׁים שֶׁנִּטְמְאוּ שֶׁנֶּאֱמַר (ויקרא ז יט) \"וְהַבָּשָׂר אֲשֶׁר יִגַּע בְּכָל טָמֵא לֹא יֵאָכֵל בָּאֵשׁ יִשָּׂרֵף\". וְכֵן הַנּוֹתָר מִצְוַת עֲשֵׂה לְשָׂרְפוֹ שֶׁנֶּאֱמַר (ויקרא ז יז) \"וְהַנּוֹתָר מִבְּשַׂר הַזָּבַח בַּיּוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף\". וּבִכְלַל הַנּוֹתָר הַפִּגּוּל וְכָל פְּסוּלֵי הַמֻּקְדָּשִׁין הַכּל נִשְׂרָפִין:","קָרְבָּן שֶׁנִּתְפַּגֵּל אוֹ נִפְסַל יִשָּׂרֵף בַּמִּקְדָּשׁ מִיָּד. וְכָל שֶׁפִּסּוּלוֹ מִסָּפֵק תְּעֻבַּר צוּרָתוֹ וְאַחַר כָּךְ יִשָּׂרֵף בַּמִּקְדָּשׁ:","פָּרִים וּשְׂעִירִים הַנִּשְׂרָפִים יֵשׁ בָּהֶם סָפֵק אִם הַלִּינָה וְהַיְצִיאָה קֹדֶם שֶׁיַּגִּיעַ זְמַנָּם לָצֵאת פּוֹסֶלֶת בְּשָׂרָם כְּאֵימוּרֵיהֶן אוֹ אֵינָהּ פּוֹסֶלֶת בְּשָׂרָן. לְפִיכָךְ פּוֹסְלִין אוֹתָן לְהַחְמִיר וְיִשָּׂרְפוּ בָּעֲזָרָה. וְכֵן אִם יָצָא חֲצִי הַבְּהֵמָה בְּרֹב הָאֵיבָר אִם מַחֲזִיקִין אוֹתָן כַּיּוֹצֵא הוֹאִיל וְיָצָא רֹב הָאֵיבָר אוֹ עֲדַיִן אֵינָן יוֹצְאִין שֶׁהֲרֵי לֹא יָצָא רֹב הַבְּהֵמָה. לְפִיכָךְ נִפְסְלוּ מִסָּפֵק וְיִשָּׂרְפוּ בָּעֲזָרָה. וְכֵן אִם נְשָׂאוּם חֲמִשָּׁה לְהוֹצִיאָן וְיָצְאוּ שְׁלֹשָׁה וְנִשְׁאֲרוּ שְׁנַיִם. וְהוֹצִיאוּ הַשְּׁלֹשָׁה חֲצִי הַבְּהֵמָה הֲרֵי אֵלּוּ נִפְסְלוּ מִסָּפֵק וְיִשָּׂרְפוּ בַּעֲזָרָה. וְיֵרָאֶה לִי שֶׁאֵין אֵלּוּ צְרִיכִין לְהַמְתִּין עַד שֶׁתְּעֵבַּר צוּרָתָן הוֹאִיל וְהֵן עוֹמְדִין לִשְׂרֵפָה לְעוֹלָם אֲפִלּוּ לֹא נִפְסְלוּ:","בָּשָׂר הַנִּמְצָא בָּעֲזָרָה. אֵיבָרִים עוֹלוֹת וַחֲתִיכוֹת חַטָּאוֹת. וְהַנִּמְצָא בִּירוּשָׁלַיִם שְׁלָמִים. הַכּל תְּעֵבַּר צוּרָתָן וְיֵצְאוּ לְבֵית הַשְּׂרֵפָה שֶׁמָּא נוֹתָר הוּא. אִם כֵּן מַה הוֹעִיל שֶׁתִּהְיֶה חֶזְקָתוֹ עוֹלָה אוֹ חַטָּאת אוֹ שְׁלָמִים. לְמִי שֶׁעָבַר וְאָכַל. אֵין שׂוֹרְפִין אֶת הַנּוֹתָר אֶלָּא בַּיּוֹם שֶׁנֶּאֱמַר (ויקרא ז יז) \"בַּיּוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף\":","אַף עַל פִּי שֶׁהַשְּׁלָמִים אֲסוּרִין בַּאֲכִילָה מִתְּחִלַּת לֵיל שְׁלִישִׁי. אֵין שׂוֹרְפִין אוֹתָן אֶלָּא בַּיּוֹם. בֵּין בִּזְמַנּוֹ בֵּין שֶׁלֹּא בִּזְמַנּוֹ. וְכֵן הַפִּגּוּל אֵינוֹ נִשְׂרָף אֶלָּא בַּיּוֹם. וְאֵין שְׂרֵפַת טָמֵא וְנוֹתָר וּפִגּוּל דּוֹחָה אֶת יוֹם טוֹב וְאֵין צָרִיךְ לוֹמַר אֶת הַשַּׁבָּת. וּמֻתָּר לִשְׂרֹף טָמֵא וְנוֹתָר וּפִגּוּל כְּאֶחָד:","בְּשַׂר קָדְשֵׁי קָדָשִׁים שֶׁנִּטְמָא בִּפְנִים. שׂוֹרְפִין אוֹתוֹ בִּפְנִים. וְאִם נִטְמָא בַּחוּץ שׂוֹרְפִין אוֹתוֹ בַּחוּץ. בֵּין שֶׁנִּטְמָא בְּאַב הַטֻּמְאָה בֵּין שֶׁנִּטְמָא בִּוְלַד הַטֻּמְאָה. וּמִימֵיהֶם שֶׁל כֹּהֲנִים לֹא נִמְנְעוּ מִלִּשְׂרֹף אֶת הַבָּשָׂר שֶׁנִּטְמָא בְּאַב הַטֻּמְאָה שֶׁהֲרֵי הוּא רִאשׁוֹן לְטֻמְאָה עִם הַבָּשָׂר שֶׁנִּטְמָא בִּוְלַד הַטֻּמְאָה שֶׁהֲרֵי הוּא שְׁלִישִׁי אַף עַל פִּי שֶׁמּוֹסִיפִין לוֹ טֻמְאָה עַל טֻמְאָתוֹ. שֶׁהַשְּׁלִישִׁי שֶׁנָּגַע בְּרִאשׁוֹן יַחְזֹר שֵׁנִי כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. וְלֹא עוֹד אֶלָּא אֲפִלּוּ שֶׁמֶן שֶׁנִּפְסַל בִּטְבוּל יוֹם שֶׁהוּא שְׁלִישִׁי מֻתָּר לְהַדְלִיקוֹ בְּנֵר שֶׁל מַתֶּכֶת שֶׁנָּגַע בָּהּ טְמֵא מֵת שֶׁהַנֵּר אַב הַטֻּמְאָה. אַף עַל פִּי שֶׁזֶּה הַשֶּׁמֶן נַעֲשֶׂה רִאשׁוֹן כְּשֶׁיִּגַּע בְּנֵר הוֹאִיל וְיֵשׁ שָׁם שׁוּם טֻמְאָה אֵין מַקְפִּידִין עַל תּוֹסֶפְתָּה וְאֵין נִזְהָרִין אֶלָּא מִן הַטָּהוֹר שֶׁלֹּא יִפָּסֵל:","נוֹתָר שֶׁל קָדָשִׁים קַלִּים שׂוֹרְפִין אוֹתוֹ בְּעָלָיו בְּבָתֵּיהֶן:","מִי שֶׁיָּצָא מִירוּשָׁלַיִם וְנִזְכַּר שֶׁיֵּשׁ בְּיָדוֹ בְּשַׂר קֹדֶשׁ. אִם עָבַר הַצּוֹפִין שׂוֹרְפוֹ בִּמְקוֹמוֹ. וְאִם לָאו אִם יֵשׁ בּוֹ כְּזַיִת אוֹ יֶתֶר חוֹזֵר וְשׂוֹרְפוֹ בִּירוּשָׁלַיִם. וְאִם הוּא אוֹרֵחַ שֶׁאֵין לוֹ בַּיִת שׂוֹרְפוֹ לִפְנֵי הַבִּירָה מֵעֲצֵי הַמַּעֲרָכָה:","כָּל עַצְמוֹת הַקָּדָשִׁים שֶׁאֵין בָּהֶן מוֹחַ אֵינָן טְעוּנִין שְׂרֵפָה חוּץ מֵעַצְמוֹת הַפֶּסַח. כְּבָר בֵּאַרְנוּ שֶׁהַקָּרְבָּן שֶׁנִּפְסַל אַחַר שֶׁהֻפְשַׁט הָעוֹר לַכֹּהֲנִים אוֹ לִבְעָלָיו בְּקָדָשִׁים קַלִּים. אֲבָל אִם נִפְסַל קֹדֶם הֶפְשֵׁט. הֲרֵי הָעוֹר כְּבָשָׂר וְיִשָּׂרֵף הַכּל. וְכֵן זֶבַח שֶׁהֻפְשַׁט וְנִמְצָא טְרֵפָה אוֹ שֶׁנִּפְסַל בְּמַחְשֶׁבֶת הַזְּמַן אוֹ בְּמַחְשֶׁבֶת הַמָּקוֹם. הוֹאִיל וְלֹא נִרְצָה הַזֶּבַח יִשָּׂרֵף הָעוֹר בֵּין בְּקָדְשֵׁי קָדָשִׁים בֵּין בְּקָדָשִׁים קַלִּים. אֲבָל אִם נַעֲשָׂה בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם. אַף עַל פִּי שֶׁלֹּא עָלָה לַבְּעָלִים הוֹאִיל וְנִרְצָה הֲרֵי הָעוֹר לַכֹּהֲנִים אוֹ לִבְעָלָיו כְּמוֹ שֶׁבֵּאַרְנוּ. וְזֶבַח שֶׁהֻפְשַׁט קֹדֶם זְרִיקָה אֵינוֹ פּוֹסֵל:","אֵלּוּ הֵן הַנִּשְׂרָפִים. בְּשַׂר קֹדֶשׁ שֶׁנִּטְמָא אוֹ נוֹתַר אוֹ נִפְסַל. וְכֵן הַמִּנְחָה שֶׁנִּטְמְאָה אוֹ נִפְסְלָה אוֹ נוֹתְרָה. וְאָשָׁם תָּלוּי שֶׁנּוֹדַע לוֹ שֶׁלֹּא חָטָא קֹדֶם שֶׁנִּזְרַק דָּמוֹ וְחַטַּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק. וּשְׂעַר נָזִיר טָהוֹר. וְהָעָרְלָה וְכִלְאֵי הַכֶּרֶם. וְדָבָר שֶׁאֵין דַּרְכּוֹ לְהִשָּׂרֵף כְּגוֹן מַשְׁקִין שֶׁל עָרְלָה וְשֶׁל כִּלְאֵי הַכֶּרֶם הֲרֵי אֵלּוּ יִקָּבֵרוּ:","וְאֵלּוּ הֵם הַנִּקְבָּרִים. קָדָשִׁים שֶׁמֵּתוּ בֵּין קָדְשֵׁי מִזְבֵּחַ בֵּין קָדְשֵׁי בֶּדֶק הַבַּיִת. וְקָדָשִׁים שֶׁהִפִּילוּ נֵפֶל. הִפִּילוּ שִׁלְיָא תִּקָּבֵר. וְשׁוֹר הַנִּסְקָל. וְעֶגְלָה עֲרוּפָה. וְצִפֳּרֵי מְצֹרָע. וּשְׂעַר נָזִיר טָמֵא. וּפֶטֶר חֲמוֹר. וּבָשָׂר בְּחָלָב. וְחֻלִּין שֶׁנִּשְׁחֲטוּ בָּעֲזָרָה:","הָאוֹרֵג מְלֹא הַסִּיט מִשְּׂעַר נָזִיר וּמִפֶּטֶר חֲמוֹר בְּשַׂק יִדָּלֵק:","כָּל הַנִּקְבָּרִין אֶפְרָן אָסוּר. וְכָל הַנִּשְׂרָפִין שֶׁל הֶקְדֵּשׁ אֶפְרָם מֻתָּר חוּץ מִדֶּשֶׁן הַמִּזְבֵּחַ הַחִיצוֹן וְהַפְּנִימִי וְדִשׁוּן הַמְּנוֹרָה:","כָּל הַנִּשְׂרָפִין לֹא יִקָּבְרוּ. וְכֵן כָּל הַנִּקְבָּרִים לֹא יִשָּׂרְפוּ. שֶׁאַף עַל פִּי שֶׁהוּא מַחְמִיר בִּשְׂרֵפָתוֹ הֲרֵי הֵקֵל בְּאֶפְרָן. שֶׁאֵפֶר הַנִּקְבָּרִים אָסוּר:","הָיָה מַקְרִיב עִמּוֹ בִּזְבָחִים וְאָמַר לוֹ נִתְפַּגְּלוּ. עוֹשֶׂה עִמּוֹ בְּטָהֳרוֹת וְאָמַר לוֹ נִטְמְאוּ. נֶאֱמָן. לֹא נֶחְשְׁדוּ יִשְׂרָאֵל עַל כָּךְ. אֲבָל אִם אָמַר לוֹ זְבָחִים שֶׁהִקְרַבְתִּי לְךָ בְּאוֹתוֹ הַיּוֹם נִתְפַּגְּלוּ. וְאוֹתָן הַטָּהֳרוֹת נִטְמְאוּ. אִם הָיָה נֶאֱמָן לוֹ סוֹמֵךְ עַל דְּבָרָיו. וְאִם לָאו שׁוּרַת הַדִּין שֶׁאֵינוֹ נֶאֱמָן. וְהָרוֹצֶה לְהַחְמִיר עַל עַצְמוֹ הֲרֵי זֶה מְשֻׁבָּח:"],"Mishneh Torah, Sacrificial Procedure 12":["הַמְּנָּחוֹת הֵם מִן הַקָּרְבָּנוֹת. וְהַמְּנָחוֹת הַבָּאוֹת בִּפְנֵי עַצְמָן וִאֵינָן בָּאוֹת מִשּׁוּם נְסָכִים. מֵהֶם מִנְחַת צִבּוּר. וּמֵהֶם מִנְחַת יָחִיד:","וְכָל הַמְּנָחוֹת סלֶת חִטִּין חוּץ מִמִּנְחַת סוֹטָה וְעֹמֶר הַתְּנוּפָה שֶׁהֵם מִן הַשְּׂעוֹרִים:","שָׁלֹשׁ מְנָחוֹת לַצִּבּוּר. עֹמֶר הַתְּנוּפָה וְהוּא קָרֵב לַמִּזְבֵּחַ כְּמוֹ שֶׁיִּתְבָּאֵר. וּשְׁתֵּי הַלֶּחֶם שֶׁמְּבִיאִין בְּיוֹם עֲצֶרֶת. וְאֵלּוּ נִקְרְאוּ מִנְחָה וְאֵינָן קְרֵבִין לְגַבֵּי הַמִּזְבֵּחַ וְהֵן חָמֵץ. וַעֲלֵיהֶם נֶאֱמַר (ויקרא ב יב) \"קָרְבַּן רֵאשִׁית תַּקְרִיבוּ אֹתָם לַה' וְאֶל הַמִּזְבֵּחַ לֹא יַעֲלוּ\". וְהַמִּנְחָה הַשְּׁלִישִׁית הוּא לֶחֶם הַפָּנִים שֶׁעוֹשִׂין בְּכָל שַׁבָּת וְאֵינוֹ קָרֵב לְגַבֵּי הַמִּזְבֵּחַ אֶלָּא כֻּלּוֹ נֶאֱכָל לַכֹּהֲנִים כְּמוֹ שֶׁיִּתְבָּאֵר:","וְתֵשַׁע מִנְחוֹת הַיָּחִיד וְכֻלָּן קְרֵבִין לַמִּזְבֵּחַ וְאֵלּוּ הֵן. מִנְחַת חוֹטֵא וְהוּא הַמִּנְחָה שֶׁמַּקְרִיב הֶעָנִי כְּשֶׁיִּתְחַיֵּב חַטָּאת וְלֹא תַּגִּיעַ יָדוֹ. מִנְחַת סוֹטָה וְהִיא מִנְחַת הַקְּנָאוֹת שֶׁכְּבָר נִתְפָּרְשׁוּ מַעֲשֶׂיהָ. הַמִּנְחָה שֶׁמַּקְרִיב כָּל כֹּהֵן תְּחִלָּה כְּשֶׁיִּכָּנֵס לַעֲבוֹדָה שֶׁמַּקְרִיב אוֹתָהּ בְּיָדוֹ וְהִיא הַנִּקְרֵאת מִנְחַת חִנּוּךְ. הַמִּנְחָה שֶׁמַּקְרִיב כֹּהֵן גָּדוֹל בְּכָל יוֹם וְהִיא הַנִּקְרֵאת חֲבִיתִין. מִנְחַת הַסּלֶת וְהִיא בָּאָה בְּנֵדֶר וּנְדָבָה. מִנְחַת הַמַּחֲבַת וְהִיא בָּאָה בְּנֵדֶר וּנְדָבָה. מִנְחַת הַמַּרְחֶשֶׁת וְהִיא בָּאָה בְּנֵדֶר וּנְדָבָה. מִנְחַת מַאֲפֵה תַּנּוּר וְהִיא בָּאָה בְּנֵדֶר וּנְדָבָה. מִנְחַת רְקִיקִין וְהִיא בָּאָה בְּנֵדֶר וּנְדָבָה:","כָּל הַמְּנָחוֹת הַקְּרֵבוֹת לְגַבֵּי הַמִּזְבֵּחַ אֵין כָּל אַחַת מֵהֶן פְּחוּתָה מֵעִשָּׂרוֹן. וּמִעוּטוֹ מְעַכֵּב אֶת כֻּלּוֹ. וְחָמֵשׁ מְנָחוֹת הַבָּאוֹת בְּנֵדֶר וּנְדָבָה יֵשׁ לוֹ לְהִתְנַדֵּב וְלִנְדֹּר מֵהֶן כָּל מַה שֶּׁיִּרְצֶה אֲפִלּוּ אֶלֶף עִשָּׂרוֹן. אֲבָל מִנְחַת הָעֹמֶר וּמִנְחַת חוֹטֵא וּמִנְחַת קְנָאוֹת וּמִנְחַת חִנּוּךְ וְהַחֲבִיתִין כָּל אַחַת מֵהֶן עִשָּׂרוֹן אֶחָד לֹא פָּחוֹת וְלֹא יֶתֶר:","כָּל הַמְּנָחוֹת הַקְּרֵבוֹת לְגַבֵּי הַמִּזְבֵּחַ טְעוּנוֹת הַגָּשָׁה בַּמַעֲרָב כְּנֶגֶד חֻדָּהּ שֶׁל קֶרֶן דְּרוֹמִית מַעֲרָבִית. וְאֵינָן טְעוּנוֹת תְּנוּפָה. חוּץ מִמִּנְחַת סוֹטָה וְעֹמֶר הַתְּנוּפָה שֶׁשְּׁנֵיהֶן טְעוּנוֹת תְּנוּפָה וְהַגָּשָׁה:","כָּל הַמְּנָחוֹת הַקְּרֵבוֹת לְגַבֵּי הַמִּזְבֵּחַ טְעוּנוֹת שֶׁמֶן וּלְבוֹנָה. לוֹג שֶׁמֶן לְכָל עִשָּׂרוֹן. וְקֹמֶץ לְבוֹנָה לְכָל מִנְחָה. בֵּין שֶׁהָיְתָה עִשָּׂרוֹן אֶחָד בֵּין שֶׁהָיְתָה שִׁשִּׁים עֶשְׂרוֹנִים. שֶׁאֵין מְבִיאִין בִּכְלִי אֶחָד יֶתֶר עַל שִׁשִּׁים עִשָּׂרוֹן כְּמוֹ שֶׁיִּתְבָּאֵר. חוּץ מִמִּנְחַת קְנָאוֹת וּמִנְחַת חוֹטֵא שֶׁנֶּאֱמַר (ויקרא ה יא) \"לֹא יָשִׂים עָלֶיהָ שֶׁמֶן וְלֹא יִתֵּן עָלֶיהָ לְבֹנָה\":","נָתַן וְהִקְרִיב לוֹקֶה עַל הַשֶּׁמֶן בִּפְנֵי עַצְמוֹ וְעַל הַלְּבוֹנָה בִּפְנֵי עַצְמָהּ. נָתַן כְּלִי שֶׁיֵּשׁ בּוֹ שֶׁמֶן אוֹ לְבוֹנָה עַל גַּבֶּיהָ אֵינוֹ עוֹבֵר וְלֹא פָּסַל. מִנְחַת חִנּוּךְ וְהַחֲבִיתִין מוֹסִיף לְכָל אַחַת מֵהֶן שֶׁמֶן כְּמוֹ שֶׁיִּתְבָּאֵר:","כָּל הַמְּנָחוֹת הַקְּרֵבוֹת לְגַבֵּי הַמִּזְבֵּחַ נִקְמָצוֹת וּמַקְטִיר הַקֹּמֶץ כֻּלּוֹ עַל גַּבֵּי הַמִּזְבֵּחַ וְהַשְּׁאָר נֶאֱכָל לַכֹּהֲנִים חוּץ מִמִּנְחַת זִכְרֵי כְּהֻנָּה שֶׁאֵינָהּ נִקְמֶצֶת אֶלָּא מַקְטִירִין אוֹתָהּ כֻּלָּהּ שֶׁנֶּאֱמַר (ויקרא ו טז) \"וְכָל מִנְחַת כֹּהֵן\" וְגוֹ'. הָא לָמַדְתָּ שֶׁמִּנְחַת חִנּוּךְ וְהַחֲבִיתִין וְכֹהֵן שֶׁהֵבִיא מִנְחַת חוֹטֵא אוֹ מִנְחַת נְדָבָה כֻּלָּן נִשְׂרָפוֹת עַל גַּבֵּי הַמִּזְבֵּחַ וְאֵינָן נִקְמָצוֹת:","הַכֹּהֶנֶת מִנְחָתָהּ נִקְמֶצֶת כְּמִנְחַת יִשְׂרָאֵל וּשְׁיָרֶיהָ נֶאֱכָלִין:","וְלָדוֹת שֶׁנִּתְעָרְבוּ וַהֲרֵי כָּל אֶחָד מֵהֶן סָפֵק מִנְחָתָם נִקְמֶצֶת כְּמִנְחַת יִשְׂרָאֵל וְאֵינָהּ נֶאֱכֶלֶת כְּמִנְחַת כֹּהֲנִים. כֵּיצַד עוֹשִׂים. הַקֹּמֶץ קָרֵב בִּפְנֵי עַצְמוֹ וְהַשְּׁיָרִים מִתְפַּזְּרִין עַל בֵּית הַדֶּשֶׁן:","כָּל הַנְּשׂוּאוֹת לַכֹּהֲנִים בֵּין כֹּהֶנֶת בֵּין יִשְׂרְאֵלִית אֵין שְׁיָרֵי מִנְחוֹתֵיהֶן נֶאֱכָלִים מִפְּנֵי חֵלֶק הַבַּעַל שֶׁאֵינוֹ אוֹכֵל. וְאֵינָהּ כֻּלָּהּ לָאִשִּׁים מִפְּנֵי חֵלֶק הָאִשָּׁה. אֶלָּא הַקֹּמֶץ קָרֵב לְעַצְמוֹ וְהַשְּׁיָרִים מִתְפַּזְּרִין עַל בֵּית הַדֶּשֶׁן. הַקְּמִיצָה בְּכָל מָקוֹם בָּעֲזָרָה וְאִם קָמַץ בַּהֵיכָל כְּשֵׁרָה:","וּמְקַדְּשִׁין מִנְחָה בִּכְלִי שֶׁעַל גַּבֵּי קַרְקַע וְקוֹמְצִין מִכְּלִי שֶׁעַל גַּבֵּי קַרְקַע. וְאֵין מַקְדִּישִׁין הַקֹּמֶץ בִּכְלִי שֶׁעַל גַּבֵּי קַרְקַע. וּמֵאֵימָתַי יֻתְּרוּ הַשְּׁיָרִים בַּאֲכִילָה מִשֶּׁיַּצִּית הָאוּר בְּרֹב הַקֹּמֶץ:","כָּל הַמְּנָחוֹת הַקְּרֵבוֹת לְגַבֵּי הַמִּזְבֵּחַ מַצָּה. וְכֵן שְׁיָרֵי הַמְּנָחוֹת שֶׁאוֹכְלִין הַכֹּהֲנִים אַף עַל פִּי שֶׁהֵן מֻתָּרִין לְאָכְלָן בְּכָל מַאֲכָל וּבִדְבַשׁ אֵין אוֹכְלִין אוֹתָן חָמֵץ שֶׁנֶּאֱמַר (ויקרא ו י) \"לֹא תֵאָפֶה חָמֵץ חֶלְקָם\". אֲפִלּוּ חֶלְקָם לֹא יַחְמִיצוּ. וְאִם הֶחְמִיץ שְׁיָרֶיהָ לוֹקֶה. וְהַמְחַמֵּץ אַחַר הַמְחַמֵּץ חַיָּב. וְלוֹקִין עַל כָּל עֲשִׂיָּה וַעֲשִׂיָּה שֶׁבָּהּ:","כֵּיצַד. לָשָׁהּ חָמֵץ אוֹ עֲרָכָהּ חָמֵץ אוֹ קְטָפָהּ חָמֵץ אוֹ אֲפָאָהּ חָמֵץ לוֹקֶה. שֶׁנֶּאֱמַר (ויקרא ב יא) \"לֹא תֵעָשֶׂה חָמֵץ\" וְנֶאֱמַר (ויקרא ו י) \"לֹא תֵאָפֶה חָמֵץ\" לְחַיֵּב עַל כָּל מַעֲשֶׂה יְחִידִי שֶׁבָּהּ. עָשָׂה חָמֵץ מִתְּחִלָּה וְעַד סוֹף לוֹקֶה עַל כָּל מַעֲשֶׂה מֵהֶן:","הִנִּיחַ שְׂאוֹר עַל גַּבֵּי הָעִסָּה וְהָלַךְ וְיָשַׁב לוֹ וְנִתְחַמְּצָה מֵאֵלֶיהָ לוֹקֶה. שֶׁהַנָּחַת הַשְּׂאוֹר הוּא הַמַּעֲשֶׂה:","תִּבֵּל הַשְּׁיָרִים בְּקֶצַח אוֹ בְּשֻׁמְשְׁמִין אוֹ בְּכָל מִינֵי תַּבְלִין וּשְׁמָנִים כְּשֵׁרָה. מַצָּה הִיא אֶלָּא שֶׁנִּקְרֵאת מַצָּה מְתֻבֶּלֶת:","הַמְחַמֵּץ מִנְחָה פְּסוּלָה פָּטוּר. שֶׁנֶּאֱמַר (ויקרא ב יא) \"אֲשֶׁר תַּקְרִיבוּ לַה' לֹא תֵעָשֶׂה חָמֵץ\". הַכְּשֵׁרָהּ לְהַשֵּׁם לֹא הַפְּסוּלָה. חִמְּצָהּ כְּשֶׁהִיא כְּשֵׁרָה וְיָצָאת לַחוּץ וְחָזַר וְחִמְּצָהּ אַחַר שֶׁנִּפְסְלָה בִּיצִיאָתָהּ אֵינוֹ לוֹקֶה. חִמְּצָהּ בְּרֹאשׁוֹ שֶׁל מִזְבֵּחַ אֵינוֹ לוֹקֶה שֶׁנֶּאֱמַר אֲשֶׁר תַּקְרִיבוּ וּכְבָר קָרְבָה זוֹ וְהִיא כְּשֵׁרָה:","הַמְחַמֵּץ לֶחֶם הַפָּנִים לוֹקֶה. שֶׁנֶּאֱמַר (ויקרא ב יא) \"כָּל הַמִּנְחָה\". אֲבָל מִנְחַת נְסָכִים אֵין בָּהּ מַלְקוֹת שֶׁאִם גִּבְּלָהּ בְּמַיִם הֲרֵי נִפְסְלָה קֹדֶם שֶׁתִּתְחַמֵּץ. וְאִם גִּבְּלָהּ בְּיַיִן שֶׁל נְסָכִים מֵי פֵּרוֹת הֵן וְאֵין מַחְמִיצִין:","הַחִטִּים שֶׁל מְנָחוֹת אֵין לוֹתְתִין אוֹתָן שֶׁמָּא יַחְמִיצוּ שֶׁהֲרֵי בַּחוּץ לוֹתְתִין אוֹתָן וְאֵין הַכּל זְרִיזִין לְשָׁמְרָן. אֲבָל מִנְחַת הָעֹמֶר הוֹאִיל וְהִיא שֶׁל צִבּוּר לוֹתְתִין אוֹתָהּ. שֶׁהֲרֵי הַצִּבּוּר זְרִיזִין הֵן וּמְשַׁמְּרִין אוֹתָהּ:","כָּל הַמְּנָחוֹת הַנֶּאֱפוֹת נִלּוֹשׁוֹת בְּפוֹשְׁרִין וּמְשַׁמְּרָן שֶׁלֹּא יַחְמִיצוּ. הוֹאִיל וְלִישָׁתָן וַאֲפִיָּתָן בִּפְנִים בָּעֲזָרָה אַנְשֵׁי פְּנִים זְרִיזִין הֵן:","וּבְמָקוֹם שֶׁמְּבַשְּׁלִין קָדְשֵׁי קָדָשִׁים שָׁם אוֹפִין אֶת הַמְּנָחוֹת שֶׁנֶּאֱמַר (יחזקאל מו כ) \"זֶה הַמָּקוֹם אֲשֶׁר יְבַשְּׁלוּ שָׁם הַכֹּהֲנִים אֶת הָאָשָׁם וְאֶת הַחַטָּאת אֲשֶׁר יֹאפוּ אֶת הַמִּנְחָה\" וְגוֹ':","כָּל הַמְּנָחוֹת טְחִינָתָן וְהַרְקָדָתָן בַּחוּץ. וְלִישָׁתָן וַעֲרִיכָתָן וַאֲפִיָּתָן בִּפְנִים. וְכָל מַעֲשֵׂיהֶן כְּשֵׁרִים בְּזָר עַד שֶׁיָּבוֹאוּ לְבֵית הַקְּמִיצָה. וּמַחֲבַת וּמַרְחֶשֶׁת הָיוּ בָּעֲזָרָה. וּשְׁתֵּיהֶם מִכְּלֵי הַשָּׁרֵת וּמְקַדְּשִׁין. וְתַנּוּר שֶׁל מִקְדָּשׁ שֶׁל מַתֶּכֶת הָיָה:"],"Mishneh Torah, Sacrificial Procedure 6":["מִצְוַת עֲשֵׂה לַעֲשׂוֹת הָעוֹלָה כְּמִשְׁפָּטָהּ הַכְּתוּבָה בַּתּוֹרָה. וְכֵיצַד מַעֲשֵׂה הָעוֹלָה. שׁוֹחֵט וְזוֹרֵק הַדָּם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַפְשִׁיט וּמְנַתֵּחַ וּמַקְטִיר כָּל הַנְּתָחִים עַל גַּבֵּי הַמִּזְבֵּחַ שֶׁנֶּאֱמַר (ויקרא א ט) \"וְהִקְטִיר הַכֹּהֵן אֶת הַכּל הַמִּזְבֵּחָה\":","צֶמֶר שֶׁבְּרָאשֵׁי כְּבָשִׂים וְשֵׂעָר שֶׁבִּזְקַן הַתְּיָשִׁים וְהָעֲצָמוֹת וְהַגִּידִים וְהַקַּרְנַיִם וְהַטְּלָפַיִם בִּזְמַן שֶׁהֵן מְחֻבָּרִין מַקְטִירִין אֶת הַכּל. וְאִם פָּרְשׁוּ לֹא יַעֲלוּ שֶׁנֶּאֱמַר (דברים יב כז) \"עלֹתֶיךָ הַבָּשָׂר וְהַדָּם\". וְכֻלָּן שֶׁפָּקְעוּ מֵעַל הַמִּזְבֵּחַ לֹא יַחְזִיר. וְכֵן גַּחֶלֶת שֶׁפָּקְעָה מֵעַל הַמִּזְבֵּחַ לֹא יַחְזִיר:","אֵיבָרִים שֶׁפָּקְעוּ מֵעַל הַמִּזְבֵּחַ אִם יֵשׁ בָּהֶן מַמָּשׁ אֲפִלּוּ פָּקְעוּ אַחַר חֲצוֹת הַלַּיְלָה יַחְזִיר. שֶׁנֶּאֱמַר (ויקרא ו ב) \"עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה\". וְאִם אֵין בָּהֶם מַמָּשׁ אֲפִלּוּ פָּקְעוּ קֹדֶם חֲצוֹת לֹא יַחְזִיר. נִתְחָרֵךְ הַבָּשָׂר וְיָבַשׁ עֲלֵיהֶן כְּעֵץ וּפָקְעוּ קֹדֶם חֲצוֹת יַחְזִיר אַחַר חֲצוֹת לֹא יַחְזִיר:","כְּשֶׁמְּנַתֵּחַ אֵיבְרֵי הָעוֹלָה מוֹלִיכִין אֶת כָּל הַנְּתָחִים לַכֶּבֶשׁ וּמוֹלְחִין אוֹתָם שָׁם. וְאַחַר כָּךְ מַעֲלִין כָּל הָאֵיבָרִים לְרֹאשׁ הַמִּזְבֵּחַ. וּמֵסִיר גִּיד הַנָּשֶׁה בְּרֹאשׁ הַמִּזְבֵּחַ וּמַשְׁלִיכוֹ עַל גַּבֵּי הַדֶּשֶׁן שֶׁבְּאֶמְצַע הַמִּזְבֵּחַ. וְזוֹרֵק כָּל הָאֵיבָרִים עַל הָאֵשׁ שֶׁנֶּאֱמַר (דברים יב כז) \"הַבָּשָׂר וְהַדָּם\". כְּשֵׁם שֶׁהַדָּם בִּזְרִיקָה כָּךְ כָּל הַבָּשָׂר בִּזְרִיקָה. וְאַחַר שֶׁזּוֹרְקָן חוֹזֵר וְעוֹרֵךְ אוֹתָן עַל הָאֵשׁ שֶׁנֶּאֱמַר (ויקרא א יב) \"וְעָרַךְ הַכֹּהֵן אֹתָם\". וְאֵיבָרִים שֶׁצְּלָאָן וְאַחַר כָּךְ הֶעֱלָן לַמִּזְבֵּחַ אֵין בָּהֶם מִשּׁוּם רֵיחַ נִיחוֹחַ:","כֵּיצַד מְנַתְּחִין אֶת הָעוֹלָה. לֹא הָיָה שׁוֹבֵר אֶת הָרֶגֶל אֶלָּא נוֹקְבוֹ וְתוֹלֶה בּוֹ וּמַפְשִׁיט. וְאִם הָיָה שׁוֹר מַפְשִׁיטוֹ בְּלִי תְּלִיָּה. וּמַפְשִׁיט עַד שֶׁהוּא מַגִּיעַ לֶחָזֶה. הִגִּיעַ לֶחָזֶה חוֹתֵךְ אֶת הָרֹאשׁ וְנוֹתְנוֹ לַכֹּהֵן. וְחוֹתֵךְ אֶת הַכְּרָעַיִם וְנוֹתְנָן לְאַחֵר וּמַשְׁלִים אֶת הַהֶפְשֵׁט. וְקוֹרֵעַ אֶת הַלֵּב וּמוֹצִיא אֶת דָּמוֹ. וְחוֹתֵךְ אֶת הַיָּדָיִם וְנוֹתְנָן לְאַחֵר. עָלָה לְרֶגֶל יְמִינִי חוֹתְכוֹ וְנוֹתְנוֹ לְמִי שֶׁזָּכָה בָּרֹאשׁ וּשְׁתֵּי בֵּיצִים עִמָּהּ. וְאַחַר כָּךְ קוֹרֵעַ אֶת הַבְּהֵמָה עַד שֶׁיִּגָּלוּ (אֶת) הַמֵּעַיִם. וְנוֹטֵל אֶת הַפֶּדֶר וְנוֹתְנוֹ עַל הָרֹאשׁ מִלְּמַעְלָה עַל בֵּית הַשְּׁחִיטָה. וְנוֹטֵל אֶת הַקְּרָבַיִם וְנוֹתְנָן לְאַחֵר:","הוֹלֵךְ וּמְדִיחָן בַּמַּיִם שֶׁנֶּאֱמַר (ויקרא א יג) \"וְהַקֶּרֶב וְהַכְּרָעַיִם יִרְחַץ בַּמָּיִם\". לֹא בְּיַיִן וְלֹא בְּמֶזֶג וְלֹא בִּשְׁאָר מַשְׁקִין. וְכָל הַמֵּימוֹת כְּשֵׁרִין. כַּמָּה מְדִיחָן. הַכָּרֵס מְדִיחִין אוֹתָהּ בְּבֵית [הַמְּדִיחִין] כָּל צָרְכָּהּ. הַקְּרָבַיִם אֵין פּוֹחֲתִין מִשָּׁלֹשׁ פְּעָמִים. וּמְדִיחִין אוֹתָן עַל שֻׁלְחָנוֹת שֶׁל שַׁיִשׁ שֶׁבֵּין הָעַמּוּדִים:","נָטַל אֶת הַסַּכִּין וְהִפְרִישׁ אֶת הָרֵאָה מִן הַכָּבֵד וְאֶצְבַּע הַכָּבֵד מִן הַכָּבֵד וְאֵינוֹ מֵזִיז הַכָּבֵד מִמְּקוֹמוֹ. וְנוֹקֵב אֶת הֶחָזֶה וְנוֹתְנוֹ לְאַחֵר. וְעוֹלֶה לַדֹּפֶן הַיְמָנִית וְחוֹתֵךְ וְיוֹרֵד עַד הַשִּׁדְרָה וְלֹא יִגַּע בַּשִּׁדְרָה. עַד שֶׁהוּא מַגִּיעַ לִשְׁתֵּי צְלָעוֹת רַכּוֹת חוֹתְכָהּ וְנוֹתְנָהּ לְאַחֵר וְהַכָּבֵד תְּלוּיָה בָּהּ:","בָּא לוֹ לַגֵּרָה מַנִּיחַ בָּהּ שְׁתֵּי צְלָעוֹת מִכָּאן וּשְׁתֵּי צְלָעוֹת מִכָּאן. חוֹתְכָהּ וְנוֹתְנָהּ לְאַחֵר וְהַקָּנֶה וְהַלֵּב וְהַרֵאָה תְּלוּיִין בָּהּ. בָּא לוֹ לַדֹּפֶן הַשְּׂמָאלִית וּמַנִּיחַ בָּהּ שְׁתֵּי צְלָעוֹת רַכּוֹת מִלְּמַעְלָה וּשְׁתֵּי צְלָעוֹת רַכּוֹת מִלְּמַטָּה וְכָךְ הָיָה מַנִּיחַ בַּחֲבֶרְתָּהּ. נִמְצָא מַנִּיחַ בִּשְׁתֵּי הַדְּפָנוֹת אַרְבַּע צְלָעוֹת בְּזוֹ וְאַרְבַּע צְלָעוֹת בְּזוֹ. חוֹתְכָהּ וְנוֹתְנָהּ לְאַחֵר וְהַשִּׁדְרָה עִמָּהּ וְהַטְּחוֹל תָּלוּי בָּהּ:","בָּא לוֹ לָעֹקֶץ חוֹתְכוֹ וְנוֹתְנוֹ לְאַחֵר. וְהָאַלְיָה וְאֶצְבַּע הַכָּבֵד וּשְׁתֵּי כְּלָיוֹת עִמָּהּ. נוֹטֵל אֶת הָרֶגֶל הַשְּׂמָאלִית וְנוֹתְנָהּ לְאַחֵר. וּכְסֵדֶר זֶה מַפְשִׁיטִין וּמְנַתְּחִין עוֹלַת בְּהֵמָה. וְאֵלּוּ הֵן הַנְּתָחִין הָאֲמוּרִין בַּתּוֹרָה (ויקרא א ו) \"וְנִתַּח אֹתָהּ לִנְתָחֶיהָ\":","בְּכַמָּה מוֹלִיכִין אֶת הָאֵיבָרִים לַכֶּבֶשׁ. אִם מִן הַצֹּאן הִיא הָעוֹלָה מוֹלִיכִין אוֹתָהּ שִׁשָּׁה:","הָרִאשׁוֹן בָּרֹאשׁ וּבָרֶגֶל. הָרֹאשׁ בִּימִינוֹ וְחָטְמוֹ כְּלַפֵּי זְרוֹעוֹ. וְקַרְנָיו בֵּין אֶצְבְּעוֹתָיו. וּבֵית שְׁחִיטָה לְמַעְלָה וְהַפֶּדֶר עָלֶיהָ וְהָרֶגֶל שֶׁל יָמִין בִּשְׂמֹאלוֹ וּבֵית עוֹרָהּ לַחוּץ:","הַשֵּׁנִי בִּשְׁתֵּי הַיָּדָיִם שֶׁל יָמִין בִּימִינוֹ וְשֶׁל שְׂמֹאל בִּשְׂמֹאלוֹ וּבֵית עוֹרָן לַחוּץ:","הַשְּׁלִישִׁי בָּעֹקֶץ וּבָרֶגֶל. הָעֹקֶץ בִּימִינוֹ וְהָאַלְיָה מְדֵלְדֶּלֶת בֵּין אֶצְבְּעוֹתָיו וְאֶצְבַּע הַכָּבֵד וּשְׁתֵּי הַכְּלָיוֹת עִמּוֹ וְהָרֶגֶל שֶׁל שְׂמֹאלוֹ בִּשְׂמֹאלוֹ וּבֵית עוֹרָן לַחוּץ:","הָרְבִיעִי בֶּחָזֶה וּבַגֵּרָה. הֶחָזֶה בִּימִינוֹ וְהַגֵּרָה בִּשְׂמֹאלוֹ וְצַלְעוֹתֶיהָ בֵּין אֶצְבְּעוֹתָיו:","הַחֲמִישִׁי בִּשְׁתֵּי דְּפָנוֹת שֶׁל יָמִין בִּימִינוֹ וְשֶׁל שְׂמֹאל בִּשְׂמֹאלוֹ וּבֵית עוֹרָן לַחוּץ:","הַשִּׁשִּׁי בַּקְּרָבַיִם נְתוּנִין בְּבָזָךְ וּכְרָעַיִם עַל גַּבֵּיהֶן מִלְּמַעְלָה. אִם הָיְתָה הָעוֹלָה כֶּבֶשׂ אוֹ עֵז. אֲבָל אִם הָיְתָה אַיִל מוֹלִיכִין הַקְּרָבַיִם שְׁנַיִם. וְכֵן הַסּלֶת שֶׁל נְסָכֶיהָ בְּיַד אֶחָד וְהַיַּיִן בְּיַד אַחֵר. וְאִם הָיָה אַיִל הַסּלֶת בִּשְׁנַיִם וְהַיַּיִן בִּשְׁנַיִם:","נִמְצֵאתָ לָמֵד שֶׁהַכֶּבֶשׂ אוֹ הָעֵז מוֹלִיכִין אוֹתוֹ שְׁמוֹנָה לַמִּזְבֵּחַ. וְהָאַיִל מוֹלִיכִין אוֹתוֹ אַחַד עָשָׂר:","הַשּׁוֹר מוֹלִיכִין אוֹתוֹ אַרְבָּעָה וְעֶשְׂרִים. הָרִאשׁוֹן מוֹלִיךְ אֶת הָרֹאשׁ. וְהַשֵּׁנִי וְהַשְּׁלִישִׁי מוֹלִיכִין הָרֶגֶל שֶׁל יָמִין. וְהָרְבִיעִי וְהַחֲמִישִׁי מוֹלִיכִין אֶת הָעֹקֶץ. וְהַשִּׁשִּׁי וְהַשְּׁבִיעִי מוֹלִיכִין אֶת הָרֶגֶל שֶׁל שְׂמֹאל. וְהַשְּׁמִינִי מוֹלִיךְ אֶת הֶחָזֶה. וְהַגֵּרָה מוֹלִיכִין אוֹתָהּ שְׁלֹשָׁה. תְּשִׁיעִי וַעֲשִׂירִי וְאַחַד עָשָׂר. וּמוֹלִיכִין שְׁתֵּי הַיָּדָיִם בִּשְׁנַיִם. וּשְׁתֵּי הַדְּפָנוֹת בִּשְׁנַיִם. וְהַקְּרָבַיִם וְהַסּלֶת וְהַיַּיִן בִּשְׁלֹשָׁה שְׁלֹשָׁה הֲרֵי אַרְבָּעָה וְעֶשְׂרִים:","וְלָמָּה לֹא יְחַלְּקוּ הָאֵיבָר הַגָּדוֹל שֶׁל שׁוֹר לַחֲלָקִים. שֶׁנֶּאֱמַר (ויקרא א ו) \"וְנִתַּח אֹתָהּ לִנְתָחֶיהָ\" וְלֹא נְתָחֶיהָ לִנְתָחִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעוֹלוֹת הַצִּבּוּר. אֲבָל עוֹלוֹת הַיָּחִיד אִם רָצוּ לְהוֹלִיךְ נְתָחֶיהָ בְּפָחוֹת מֵאֵלּוּ אוֹ בְּיוֹתֵר מוֹלִיכִין:","עוֹלַת הָעוֹף כֵּיצַד הָיְתָה נַעֲשֵׂית. עוֹלֶה לַכֶּבֶשׁ וּפָנָה לַסּוֹבֵב וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית וְהָיָה מוֹלֵק שָׁם אֶת רֹאשָׁהּ מִמּוּל עָרְפָּהּ וּמַבְדִּיל. וְאִם לֹא הִבְדִּיל פְּסוּלָה. וּמְמַצֶּה דַּם הָרֹאשׁ וְדַם הַגּוּף עַל קִיר הַמִּזְבֵּחַ לְמַעְלָה מִן הַחוּט שֶׁבְּאֶמְצַע הַמִּזְבֵּחַ. וְאִם מִצָּה דַּם הָרֹאשׁ וְלֹא מִצָּה דַּם הַגּוּף פְּסוּלָה. מִצָּה דַּם הַגּוּף וְלֹא מִצָּה דַּם הָרֹאשׁ כְּשֵׁרָה:","וְנוֹטֵל אֶת הָרֹאשׁ וּמַקִּיף בֵּית מְלִיקָתוֹ לַמִּזְבֵּחַ וְסוֹפְגוֹ בְּמֶלַח וְזוֹרְקוֹ עַל גַּבֵּי הָאִשִּׁים. וּבָא לוֹ לַגּוּף וְהֵסִיר אֶת הַמֻּרְאָה וְהָעוֹר שֶׁעָלֶיהָ בְּיָדוֹ עִם הַנּוֹצָה וְאֶת בְּנֵי מֵעַיִם הַיּוֹצְאִין עִמָּהּ וּמַשְׁלִיכָן לְבֵית הַדֶּשֶׁן:","(ויקרא א יז) \"וְשִׁסַּע אֹתוֹ בִכְנָפָיו\". בְּיָדוֹ בְּלֹא סַכִּין. וְאֵינוֹ צָרִיךְ לְהַבְדִּיל שֶׁנֶּאֱמַר (ויקרא א יז) \"לֹא יַבְדִּיל\" וְאִם הִבְדִּיל כָּשֵׁר. וְסוֹפְגוֹ בְּמֶלַח וְזוֹרְקוֹ עַל גַּבֵּי הָאִשִּׁים. לֹא הֵסִיר אֶת הַמֻּרְאָה וְלֹא אֶת הַנּוֹצָה וְלֹא אֶת בְּנֵי מֵעַיִם וְלֹא סְפָגָהּ בְּמֶלַח כָּל שֶׁשִּׁנָּה בָּהּ מֵאַחַר תַּמְצִית הַדָּם כְּשֵׁרָה:","כֵּיצַד מוֹלְקִין. קוֹצֵץ וְיוֹרֵד בַּצִּפֹּרֶן מִמּוּל עֹרֶף. אִם רָצָה לְהוֹלִיךְ וּלְהָבִיא מוֹלִיךְ וּמֵבִיא. וְאִם רָצָה לִהְיוֹת דּוֹרֵס וְיוֹרֵד בַּצִּפֹּרֶן דּוֹרֵס. וְאִם נֶעֶקְרוּ הַסִּימָנִים אֵינוֹ חוֹשֵׁשׁ. וְחוֹתֵךְ שִׁדְרָה וּמִפְרֶקֶת בְּלֹא רֹב בָּשָׂר. שֶׁאִם חָתַךְ רֹב בָּשָׂר הֲרֵי זוֹ כְּמֵתָה קֹדֶם שֶׁיַּגִּיעַ לַסִּימָנִין. וְצָרִיךְ לַחְתֹּךְ שְׁנֵי הַסִּימָנִים בָּעוֹלָה כְּשֶׁהוּא יוֹרֵד. וְהַמּוֹלֵק בְּסַכִּין אוֹ מִן הַצְּדָדִין אֵינָהּ מְלִיקָה אֶלָּא כְּמִי שֶׁחָנַק אוֹ נָחַר. וְכָל הָעֹרֶף כָּשֵׁר לִמְלִיקָה:"],"Mishneh Torah, Sales 17":["אַרְבַּע מִדּוֹת בְּמוֹכְרין. מָכַר לוֹ חִטִּים יָפוֹת וְנִמְצְאוּ רָעוֹת הַלּוֹקֵחַ יָכוֹל לַחְזֹר בּוֹ וְלֹא הַמּוֹכֵר. רָעוֹת וְנִמְצְאוּ יָפוֹת הַמּוֹכֵר יָכוֹל לַחְזֹר בּוֹ וְלֹא הַלּוֹקֵחַ. רָעוֹת וְנִמְצְאוּ רָעוֹת יָפוֹת וְנִמְצְאוּ יָפוֹת אַף עַל פִּי שֶׁאֵינָן יָפוֹת שֶׁאֵין לְמַעְלָה מֵהֶן וְלֹא רָעוֹת שֶׁאֵין לְמַטָּה מֵהֶן וַהֲרֵי יֵשׁ שָׁם הוֹנָיָה שְׁתוּת אֵין אֶחָד מֵהֶם יָכוֹל לַחְזֹר בּוֹ אֶלָּא קָנָה וּמַחֲזִיר אוֹנָאָה:","אֲבָל הַמּוֹכֵר חִטִּים שַׁחְמָתִית וְנִמְצֵאת לְבָנָה. לְבָנָה וְנִמְצָא שַׁחְמָתִית. עֵצִים שֶׁל זַיִת וְנִמְצְאוּ שֶׁל שִׁקְמָה. שֶׁל שִׁקְמָה וְנִמְצְאוּ שֶׁל זַיִת. יַיִן וְנִמְצָא חֹמֶץ. חֹמֶץ וְנִמְצָא יַיִן. כָּל אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ. שֶׁאֵין זֶה הַמִּין שֶׁאָמַר שֶׁיִּמְכֹּר לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר יַיִן לַחֲבֵרוֹ וּנְתָנוֹ הַלּוֹקֵחַ בְּקַנְקַנָּיו וְהֶחְמִיץ מִיָּד אֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ. וְאַף עַל פִּי שֶׁאָמַר לוֹ לְתַבְשִׁיל אֲנִי צָרִיךְ לוֹ. וְאִם יָדַע שֶׁיֵּינוֹ מַחְמִיץ הֲרֵי זֶה מִקַּח טָעוּת. מָכַר לוֹ יַיִן וַהֲרֵי הוּא בְּקַנְקַנָּיו שֶׁל מוֹכֵר וְהֶחְמִיץ. אִם אָמַר לוֹ לְמִקְפָּה אֲנִי צָרִיךְ וְהֶחְמִיץ מַחְזִיר וְאוֹמֵר לוֹ הֲרֵי יֵינְךָ וְקַנְקַנְּךָ שֶׁאֲנִי לֹא קָנִיתִי לִשְׁתּוֹתוֹ אֶלָּא לְבַשֵּׁל מְעַט מְעַט. וְאִם לֹא אָמַר לְמִקְפָּה הוּא אֵינוֹ יָכוֹל לְהַחְזִיר. שֶׁהֲרֵי אוֹמֵר לוֹ לָמָּה לֹא שָׁתִיתָ אוֹתוֹ. וְלֹא הָיָה לְךָ לַשְׁהוֹתוֹ עַד שֶׁיַּחְמִיץ:","הַמּוֹכֵר חָבִית שֶׁל שֵׁכָר לַחֲבֵרוֹ וְהֶחָבִית שֶׁל מוֹכֵר וְהֶחְמִיצָה בְּתוֹךְ שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים. הֲרֵי זֶה בִּרְשׁוּת הַמּוֹכֵר וּמַחֲזִיר אֶת הַדָּמִים. מִכָּאן וְאֵילָךְ בִּרְשׁוּת הַלּוֹקֵחַ:","הַמּוֹכֵר חָבִית שֶׁל יַיִן לַחֲבֵרוֹ כְּדֵי לְמָכְרָהּ מְעַט מְעַט וְהֶחְמִיצָה בְּמַחֲצִיתָהּ אוֹ בִּשְׁלִישָׁהּ חוֹזֶרֶת לַמּוֹכֵר. וְאִם שִׁנָּה הַלּוֹקֵחַ הַנֶּקֶב שֶׁלָּהּ אוֹ שֶׁהִגִּיעַ יוֹם הַשּׁוּק וְשָׁהָה וְלֹא מָכַר הֲרֵי הִיא בִּרְשׁוּת הַלּוֹקֵחַ. וְכֵן הַמְקַבֵּל חָבִית שֶׁל יַיִן מֵחֲבֵרוֹ כְּדֵי לְהוֹלִיכָהּ לְמָקוֹם פְּלוֹנִי לְמָכְרָהּ שָׁם וְקֹדֶם שֶׁהִגִּיעַ שָׁם הוּזַל הַיַּיִן אוֹ הֶחְמִיצָה הֲרֵי זֶה בִּרְשׁוּת הַמּוֹכֵר. מִפְּנֵי שֶׁהֶחָבִית וְהַיַּיִן שֶׁלּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר לַחֲבֵרוֹ יַיִן מְבֻשָּׂם אֲנִי מוֹכֵר לְךָ חַיָּב לְהַעֲמִיד לוֹ עַד עֲצֶרֶת. אָמַר לוֹ יַיִן יָשָׁן אֲנִי מוֹכֵר לְךָ נוֹתֵן לוֹ מִשֶּׁל שָׁנָה שֶׁעָבְרָה. מְיֻשָּׁן מִשֶּׁל שָׁלֹשׁ שָׁנִים. וְצָרִיךְ שֶׁיַּעֲמֹד וְלֹא יַחְמִיץ עַד הֶחָג. וּבְמָקוֹם שֶׁיֵּשׁ מִנְהָג יָדוּעַ הַכּל כְּמִנְהַג הַמְּדִינָה:","הָאוֹמֵר לַחֲבֵרוֹ מַרְתֵּף זֶה שֶׁל יַיִן אֲנִי מוֹכֵר לְךָ לְמִקְפָּה. אוֹ שֶׁמָּכַר לוֹ מַרְתֵּף שֶׁל יַיִן סְתָם. הֲרֵי הַלּוֹקֵחַ מְקַבֵּל עָלָיו עֲשָׂרָה קַנְקַנִּים בְּכָל מֵאָה שֶׁלֹּא יִהְיֶה יֵינָם טוֹב אֶלָּא כְּבָר הִתְחִיל לְהִשְׁתַּנּוֹת. יֶתֶר עַל זֶה לֹא יְקַבֵּל:","אָמַר לוֹ מַרְתֵּף שֶׁל יַיִן אֲנִי מוֹכֵר לְךָ לְמִקְפָּה. אוֹ שֶׁאָמַר לוֹ חָבִית שֶׁל יַיִן אֲנִי מוֹכֵר לְךָ. נוֹתֵן לוֹ יַיִן שֶׁכֻּלּוֹ יָפֶה וְרָאוּי לְתַבְשִׁיל. אָמַר לוֹ מַרְתֵּף זֶה שֶׁל יַיִן נוֹתֵן לוֹ יַיִן הַנִּמְכָּר בַּחֲנוּת שֶׁהֲרֵי הוּא בֵּינוֹנִי לֹא רַע וְלֹא יָפֶה. אָמַר לוֹ מַרְתֵּף זֶה אֲנִי מוֹכֵר לְךָ וְלֹא הִזְכִּיר יַיִן אֲפִלּוּ כֻּלּוֹ חֹמֶץ הִגִּיעוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר לַחֲבֵרוֹ עֲרֵבָה שֶׁל עֵץ אֲנִי מוֹכֵר לְךָ. אוֹ קוֹרַת בֵּית הַבַּד אֲנִי מוֹכֵר לְךָ. אֵינוֹ נוֹתֵן לוֹ עֵץ שֶׁרָאוּי לַחְפֹּר בּוֹ עֲרֵבָה. אוֹ קוֹרָה שֶׁרָאוּי לִקְרוֹת בֵּית הַבַּד. אֶלָּא עֲרֵבָה בְּצוּרָתָהּ אוֹ קוֹרוֹת בֵּית הַבַּד בְּצוּרָתָם. שֶׁכָּל הָרוֹאֶה אוֹמֵר זוֹ עֲרֵבָה אוֹ זוֹ קוֹרַת בֵּית הַבַּד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Sales 28":["הָאוֹמֵר לַחֲבֵרוֹ בֵּית כּוֹר עָפָר אֲנִי מוֹכֵר לְךָ וְהָיוּ בְּתוֹךְ הַשָּׂדוֹת גֵּאָיוֹת קְטַנִּים עֲמֻקִּים עֲשָׂרָה טְפָחִים אַף עַל פִּי שֶׁאֵין בָּהֶן מַיִם אוֹ סְלָעִים גְּבוֹהִים עֲשָׂרָה טְפָחִים אֵין נִמְדָּדִין בִּכְלַל הַבֵּית כּוֹר. שֶׁאֵין אָדָם רוֹצֶה לִתֵּן מְעוֹתָיו בְּמָקוֹם אֶחָד וְנִרְאִין כִּשְׁנַיִם אוֹ שְׁלֹשָׁה מְקוֹמוֹת. וְלוֹקֵחַ אֵלּוּ הַגֵּאָיוֹת וְהַסְּלָעִים בִּכְלַל הַבֵּית כּוֹר בְּלֹא דָּמִים. הָיוּ פָּחוֹת מִכָּאן נִמְדָּדִין עִמָּהּ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלֹּא הָיָה בָּהֶן אֶלָּא בֵּית אַרְבָּעָה קַבִּין וְהָיוּ הָאַרְבָּעָה קַבִּין מֻבְלָעִין בְּתוֹךְ חֲמֵשֶׁת קַבִּין וּמֻבְלָעִין בְּתוֹךְ רֻבָּהּ שֶׁל שָׂדֶה. אֲבָל הָיְתָה יֶתֶר עַל אַרְבָּעָה קַבִּין אוֹ שֶׁהָיוּ מְפֻזָּרִין הַרְבֵּה אוֹ אֵינָן מֻבְלָעִין. אַף עַל פִּי שֶׁאֵין בָּהֶן עֲשָׂרָה אֵינָן נִמְדָּדִין עִמָּהּ. הָיוּ נִבְלָעִין רֻבָּן בְּמִעוּטָהּ אוֹ מִעוּטָן בְּרֻבָּהּ. אוֹ שֶׁהָיוּ מֻחְלָקִין כְּמוֹ חוּט שָׁוֶה אוֹ כְּמוֹ עִגּוּל אוֹ כְּמוֹ מְשֻׁלָּשׁ אוֹ שֶׁהָיוּ בַּצְּדָדִין אוֹ שֶׁהָיוּ דֶּרֶךְ עֲקַלָּתוֹן. כָּל אֵלּוּ סָפֵק וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְכֵן אִם הָיוּ עָפָר מִלְּמַעְלָה וְסֶלַע מִלְּמַטָּה אוֹ סֶלַע מִלְּמַעְלָה וְעָפָר מִלְּמַטָּה הֲרֵי זֶה סָפֵק:","הָיָה בָּהּ סֶלַע יְחִידִי אֲפִלּוּ בֵּית רֹבַע לְכוֹר אֵין נִמְדָּד עִמָּהּ. וְאִם הָיָה סָמוּךְ לַמֵּצַר אֲפִלּוּ כָּל שֶׁהוּא אֵין זֶה נִמְדָּד עִמָּהּ. הִפְסִיק עָפָר בֵּין סֶלַע לַמֵּצַר הֲרֵי זֶה סָפֵק:","אָמַר לוֹ כְּבֵית כּוֹר עָפָר אֲנִי מוֹכֵר לְךָ. אֲפִלּוּ הָיוּ בָּהּ גֵּאָיוֹת עֲמֻקוֹת עֲשָׂרָה טְפָחִים אוֹ יוֹתֵר אוֹ סְלָעִים גְּבוֹהִים עֲשָׂרָה טְפָחִים אוֹ יוֹתֵר הֲרֵי אֵלּוּ נִמְדָּדִין עִמָּהּ:","הָאוֹמֵר לַחֲבֵרוֹ בֵּית כּוֹר עָפָר אֲנִי מוֹכֵר לְךָ מִדָּה בְּחֶבֶל. אִם פִּחֵת כָּל שֶׁהוּא מְנַכֶּה לוֹ מִן הַדָּמִים וְאִם הוֹתִיר כָּל שֶׁהוּא יַחְזִיר לוֹ:","אָמַר בֵּית כּוֹר עָפָר אֲנִי מוֹכֵר לְךָ. הֲרֵי זֶה כְּמִי שֶׁפֵּרֵשׁ וְאָמַר בֵּית כּוֹר עָפָר בֵּין חָסֵר בֵּין יָתֵר. וְאִם פִּחֵת מִן הַמִּדָּה אֶחָד מֵאַרְבָּעָה וְעֶשְׂרִים שֶׁהוּא רֹבַע לְכָל סְאָה אוֹ הוֹתִיר כָּךְ רֹבַע לְכָל סְאָה הִגִּיעוֹ. יֶתֶר עַל כֵּן יַחְשֹׁב עִמּוֹ עַל כָּל הָרְבָעִים כֻּלָּן שֶׁחָסְרוּ אוֹ הוֹסִיפוּ. וְכָל שֶׁפִּחֵת מִבֵּית כּוֹר יְנַכֶּה לוֹ מִן הַדָּמִים וְכָל שֶׁהוֹסִיף עַל בֵּית כּוֹר יַחְזִיר לוֹ:","וּמַה הוּא מַחְזִיר לוֹ. אִם הָיְתָה הַתּוֹסֶפֶת פְּחוּתָה מִתִּשְׁעָה קַבִּין מַחְזִיר לוֹ דָּמִים כִּשְׁעַת הַמְּכִירָה לְיַפּוֹת כֹּחַ הַמּוֹכֵר. וְאִם הָיְתָה הַתּוֹסֶפֶת סְמוּכָה לְשָׂדֶה אַחֶרֶת שֶׁל מוֹכֵר מַחְזִיר לוֹ אוֹתָהּ הַתּוֹסֶפֶת קַרְקַע שֶׁהֲרֵי סוֹמֵךְ אוֹתָהּ לִשְׁאָר שְׂדוֹתָיו וְאֵינוֹ מַפְסִיד כְּלוּם. הָיְתָה הַתּוֹסֶפֶת יְתֵרָה עַל תִּשְׁעָה קַבִּין נוֹתְנִין רֹבַע לְכָל סְאָה וּסְאָה. וְהַנִּשְׁאָר יֶתֶר עַל הָרְבָעִים אִם יֵשׁ בּוֹ תִּשְׁעָה קַבִּין נוֹתֵן לוֹ כָּל הָרְבָעִים כֻּלָּן עִם הַיֶּתֶר מִן הַקַּרְקַע וְנוֹתְנוֹ לוֹ כְּשָׁעָה שֶׁלְּקָחָהּ מִמֶּנּוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהִיא בְּזוֹל בִּשְׁעַת מִמְכָּר וְהוֹקִירָה בִּשְׁעַת הַחְזָרַת הַיֶּתֶר. אֲבָל אִם הָיְתָה בְּיֹקֶר וְהוּזְלָה. אוֹמְרִין לַלּוֹקֵחַ אִם רָצִיתָ לִתֵּן לוֹ דְּמֵי הַתּוֹסֶפֶת כֻּלָּהּ תֵּן לוֹ דָּמִים כְּפִי הַמִּמְכָּר וְאִם רָצִיתָ לִתֵּן לוֹ קַרְקַע תֵּן לוֹ כְּמוֹ שֶׁשָּׁוֶה עַכְשָׁו:","וְדִין חֲצִי קַב בְּגִנָּה כְּדִין תִּשְׁעָה קַבִּין בְּשָׂדֶה. שֶׁאִם הוֹתִירָה בְּגִנָּה פָּחוֹת מֵחֲצִי קַב עַל הָרְבָעִים אֵינוֹ מַחְזִיר לוֹ אֶלָּא דָּמִים. הוֹתִיר חֲצִי קַב מַחְזִיר לוֹ אֶת כָּל הָרְבָעִים עִם הַיֶּתֶר בְּדָמִים אוֹ קַרְקַע כִּשְׁעַת הַזּוֹל שֶׁל עֵת הַחֲזָרָה:","מָכַר שָׂדֶה וְנַעֲשֵׂית גִּנָּה בְּיַד לוֹקֵחַ. אוֹ גִּנָּה וְנַעֲשֵׂית שָׂדֶה. הֲרֵי זֶה סָפֵק אִם מְחַשֵּׁב לוֹ כְּדִין שֶׁהָיְתָה בְּעֵת הַמֶּכֶר אוֹ כְּדִין שֶׁהִיא עַתָּה:","הָאוֹמֵר לַחֲבֵרוֹ בֵּית כּוֹר עָפָר אֲנִי מוֹכֵר לְךָ מִדָּה בְּחֶבֶל בֵּין חָסֵר בֵּין יָתֵר. אוֹ שֶׁאָמַר בֵּית כּוֹר אֲנִי מוֹכֵר לְךָ בֵּין חָסֵר בֵּין יָתֵר מִדָּה בְּחֶבֶל. הַלֵּךְ אַחַר הַפָּחוּת שֶׁבַּלְּשׁוֹנוֹת וְאֵין לוֹ אֶלָּא כַּדִּין אִם חָסֵר אִם יָתֵר:","מָכַר לוֹ בֵּית כּוֹר וְאָמַר לוֹ בַּסִּימָנִין וּבַמְּצָרִים. פִּחֵת שְׁתוּת אוֹ הוֹתִיר שְׁתוּת הִגִּיעוֹ. פִּחֵת יֶתֶר עַל שְׁתוּת יְנַכֶּה לוֹ מִן הַדָּמִים. הוֹסִיף לוֹ יֶתֶר עַל שְׁתוּת יִתֵּן לוֹ דָּמִים אוֹ קַרְקַע הַכּל לְפִי הַשִּׁיּוּר. אִם הַנִּשְׁאָר בַּשָּׂדֶה פָּחוֹת מִתִּשְׁעָה קַבִּין וּבַגִּנָּה פָּחוֹת מֵחֲצִי קַב וְלֹא הָיָה סָמוּךְ לַשָּׂדֶה הַמּוֹכֵר מַחְזִיר לוֹ הַדָּמִים:","הַמּוֹכֵר לַחֲבֵרוֹ שָׂדֶה שֶׁהַלּוֹקֵחַ יוֹדֵעַ אוֹתָהּ וְאֶת מְצָרֶיהָ וּכְבָר הֻרְגַּל בָּהּ. אֲפִלּוּ אָמַר לוֹ יֵשׁ בִּמְשִׁיחָתָהּ מָאתַיִם וְנִמְצֵאת בָּהּ מֵאָה וַחֲמִשִּׁים הִגִּיעָתוֹ שֶׁהֲרֵי יְדָעָהּ וְקִבֵּל עָלָיו. וְזֶה שֶׁהִזְכִּיר לוֹ הַחֲשִׁיבוּת, כְּלוֹמַר שֶׁהִיא יָפָה כְּמוֹ שָׂדֶה אַחֶרֶת שֶׁיֵּשׁ בִּמְשִׁיחָתָהּ מָאתַיִם:","הָאוֹמֵר לַחֲבֵרוֹ בֵּית כּוֹר פְּלוֹנִי אֲנִי מוֹכֵר לְךָ אַף עַל פִּי שֶׁאֵין בִּמְשִׁיחָתוֹ אֶלָּא לֶתֶךְ הִגִּיעוֹ. שֶׁלֹּא מָכַר לוֹ אֶלָּא מָקוֹם הַנִּקְרָא בֵּית כּוֹר. לְפִיכָךְ צָרִיךְ הַמּוֹכֵר לְהָבִיא רְאָיָה שֶׁהוּא נִקְרָא בֵּית כּוֹר. וְכֵן הָאוֹמֵר לַחֲבֵרוֹ כֶּרֶם שֶׁלִּי בְּמָקוֹם פְּלוֹנִי אֲנִי מוֹכֵר לְךָ אַף עַל פִּי שֶׁאֵין בּוֹ גְּפָנִים הִגִּיעוֹ וְהוּא שֶׁיִּהְיוּ קוֹרִין אוֹתוֹ כֶּרֶם. וְכֵן הָאוֹמֵר לַחֲבֵרוֹ פַּרְדֵּס זֶה אֲנִי מוֹכֵר לְךָ. אֲפִלּוּ אֵין בּוֹ רִמּוֹנִים הִגִּיעוֹ וְהוּא שֶׁיִּקָּרֵא פַּרְדֵּס. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","וְכֵן כָּל הַדְּבָרִים הָאֵלּוּ בְּמָקוֹם שֶׁאֵין שָׁם מִנְהָג כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל בְּמָקוֹם שֶׁיֵּשׁ מִנְהָג הַלֵּךְ אַחַר הַמִּנְהָג וְאַחַר לְשׁוֹן רֹב אַנְשֵׁי הַמָּקוֹם הַיְדוּעִים לָהֶן:"],"Mishneh Torah, Sanctification of the New Month 11":["לְפִי שֶׁאָמַרְנוּ בַּהֲלָכוֹת אלּוּ שֶׁבֵּית דִּין הָיוּ מְחַשְּׁבִין בְּדִקְדּוּק וְיוֹדְעִים אִם יֵרָאֶה הַיָּרֵחַ אוֹ לֹא יֵרָאֶה. יָדַעְנוּ שֶׁכָּל מִי שֶׁרוּחוֹ נְכוֹנָה וְלִבּוֹ תָּאֵב לְדִבְרֵי הַחָכְמוֹת וְלַעֲמֹד עַל הַסּוֹדוֹת יִתְאַוֶּה לֵידַע אוֹתָן הַדְּרָכִים שֶׁמְּחַשְּׁבִין בָּהֶם עַד שֶׁיֵּדַע אָדָם אִם יֵרָאֶה הַיָּרֵחַ בְּלַיִל זֶה אוֹ לֹא יֵרָאֶה:","וְדַרְכֵי הַחֶשְׁבּוֹן יֵשׁ בָּהֶן מַחֲלוֹקוֹת גְּדוֹלוֹת בֵּין חַכְמֵי הַגּוֹיִם הַקַּדְמוֹנִים שֶׁחָקְרוּ עַל חֶשְׁבּוֹן הַתְּקוּפוֹת וְהַגִּימַטְרִיָּאוֹת. וַאֲנָשִׁים חֲכָמִים גְּדוֹלִים נִשְׁתַּבְּשׁוּ בָּהֶן וְנִתְעַלְּמוּ מֵהֶן דְּבָרִים וְנוֹלְדוּ לָהֶן סְפֵקוֹת. וְיֵשׁ מִי שֶׁדִּקְדֵּק הַרְבֵּה וְלֹא פָּגַע בַּדֶּרֶךְ הַנְּכוֹנָה בְּחֶשְׁבּוֹן רְאִיַּת הַיָּרֵחַ אֶלָּא צָלַל בְּמַיִם אַדִּירִים וְהֶעֱלָה חֶרֶס בְּיָדוֹ:","וּלְפִי אֹרֶךְ הַיָּמִים וְרֹב הַבְּדִיקוֹת וְהַחֲקִירוֹת נוֹדְעוּ לְמִקְצָת הַחֲכָמִים דַּרְכֵי חֶשְׁבּוֹן זֶה. וְעוֹד שֶׁיֵּשׁ לָנוּ בְּעִקָּרִים אֵלּוּ קַבָּלוֹת מִפִּי הַחֲכָמִים וּרְאָיוֹת שֶׁלֹּא נִכְתְּבוּ בַּסְּפָרִים הַיְדוּעִים לַכּל. וּמִפְּנֵי כָּל אֵלּוּ הַדְּבָרִים כָּשֵׁר בְּעֵינַי לְבָאֵר דַּרְכֵי חֶשְׁבּוֹן זֶה כְּדֵי שֶׁיִּהְיֶה נָכוֹן לְמִי שֶׁמְּלָאוֹ לִבּוֹ לְקָרְבָה אֶל הַמְּלָאכָה לַעֲשׂוֹת אוֹתָהּ:","וְאַל יִהְיוּ דְּרָכִים אֵלּוּ קַלִּים בְּעֵינֶיךָ מִפְּנֵי שֶׁאֵין אָנוּ צְרִיכִין לָהֶם בַּזְּמַן הַזֶּה. שֶׁאֵלּוּ הַדְּרָכִים דְּרָכִים רְחוֹקִים וַעֲמֻקִּים הֵן. וְהוּא סוֹד הָעִבּוּר שֶׁהָיוּ הַחֲכָמִים הַגְּדוֹלִים יוֹדְעִים אוֹתוֹ וְאֵין מוֹסְרִין אוֹתוֹ לְכָל אָדָם אֶלָּא לִסְמוּכִים נְבוֹנִים. אֲבָל זֶה הַחֶשְׁבּוֹן בַּזְּמַן הַזֶּה שֶׁאֵין בֵּית דִּין לִקְבֹּעַ עַל פִּי הָרְאִיָּה שֶׁאָנוּ מְחַשְּׁבִין בּוֹ הַיּוֹם אֲפִלּוּ תִּינוֹקוֹת שֶׁל בֵּית רַבָּן מַגִּיעִין עַד סוֹפוֹ בִּשְׁלֹשָׁה וְאַרְבָּעָה יָמִים:","שֶׁמָּא יִתְבּוֹנֵן חָכָם מֵחַכְמֵי הָאֻמּוֹת אוֹ מֵחַכְמֵי יִשְׂרָאֵל שֶׁלָּמְדוּ חָכְמַת יָוָן בִּדְרָכִים אֵלּוּ שֶׁאֲנִי מְחַשֵּׁב בָּהֶן לִרְאִיַּת הַיָּרֵחַ וְיִרְאֶה קֵרוּב מְעַט בְּמִקְצָת הַדְּרָכִים. וְיַעֲלֶה עַל דַּעְתּוֹ שֶׁנִּתְעַלֵּם מִמֶּנּוּ דָּבָר זֶה וְלֹא יָדַעְנוּ שֶׁיֵּשׁ בְּאוֹתוֹ הַדֶּרֶךְ קֵרוּב. אַל יַעֲלֶה זֶה עַל דַּעְתּוֹ אֶלָּא כָּל דָּבָר שֶׁלֹּא דִּקְדַּקְנוּ בּוֹ מִפְּנֵי שֶׁיָּדַעְנוּ בְּעִקְּרֵי הַגִּימַטְרִיָּאוֹת בִּרְאָיוֹת בְּרוּרוֹת שֶׁאֵין דָּבָר זֶה מַפְסִיד בִּידִיעַת הָרְאִיָּה וְאֵין חוֹשְׁשִׁין לוֹ. לְפִיכָךְ לֹא דִּקְדַּקְנוּ בּוֹ:","וְכֵן כְּשֶׁיִּרְאֶה בְּדֶרֶךְ מִן הַדְּרָכִים חֶסְרוֹן מְעַט מֵחֶשְׁבּוֹן הָרָאוּי לְאוֹתָהּ הַדֶּרֶךְ. בְּכַוָּנָה עָשִׂינוּ זֶה לְפִי שֶׁיֵּשׁ כְּנֶגְדּוֹ יִתְרוֹן בְּדֶרֶךְ אַחֶרֶת עַד שֶׁיֵּצֵא הַדָּבָר לַאֲמִתּוֹ בִּדְרָכִים קְרוֹבִים בְּלֹא חֶשְׁבּוֹן אָרֹךְ. כְּדֵי שֶׁלֹּא יִבָּהֵל הָאָדָם שֶׁאֵינוֹ רָגִיל בִּדְבָרִים אֵלּוּ בְּרֹב הַחֶשְׁבּוֹנוֹת שֶׁאֵין מוֹעִילִין בִּרְאִיַּת הַיָּרֵחַ:","הָעִקָּרִים שֶׁצָּרִיךְ אָדָם לֵידַע תְּחִלָּה לְכָל חֶשְׁבּוֹנוֹת הָאִצְטַגְנִינוּת. בֵּין לְדַרְכֵי חֶשְׁבּוֹן הָרְאִיָּה בֵּין לִשְׁאָר דְּבָרִים. אֵלּוּ הֵן. הַגַּלְגַּל מוחלק בְּש\"ס מַעֲלוֹת. כָּל מַזָּל וּמַזָּל שְׁלֹשִׁים מַעֲלוֹת. וּמַתְחִיל מִתְּחִלַּת מַזַּל טָלֶה וְכָל מַעֲלָה וּמַעֲלָה ס' חֲלָקִים. וְכָל חֵלֶק וְחֵלֶק ס' שְׁנִיּוֹת. וְכָל שְׁנִיָּה וּשְׁנִיָּה שִׁשִּׁים שְׁלִישִׁיּוֹת. וְכֵן תְּדַקְדֵּק הַחֶשְׁבּוֹן וּתְחַלֵּק כָּל זְמַן שֶׁתִּרְצֶה:","לְפִיכָךְ אִם יָצָא לְךָ בַּחֶשְׁבּוֹן שֶׁכּוֹכָב פְּלוֹנִי מְקוֹמוֹ בַּגַּלְגַּל בְּע' מַעֲלוֹת וְל' חֲלָקִים וּמ' שְׁנִיּוֹת. תֵּדַע שֶׁכּוֹכָב זֶה הוּא בְּמַזַּל תְּאוֹמִים בַּחֲצִי מַעֲלָה אַחַת עֶשְׂרֵה מִמַּזָּל זֶה. לְפִי שֶׁמַּזַּל טָלֶה ל' מַעֲלוֹת וּמַזַּל שׁוֹר ל' מַעֲלוֹת נִשְׁאַר עֶשֶׂר מַעֲלוֹת וּמֶחֱצָה מִמַּזַּל תְּאוֹמִים וּמ' שְׁנִיּוֹת מֵחֲצִי הַמַּעֲלָה הָאַחֲרוֹן:","וְכֵן אִם יָצָא מְקוֹמוֹ בַּגַּלְגַּל בְּש\"כ מַעֲלוֹת. תֵּדַע שֶׁכּוֹכָב זֶה בְּמַזַּל דְּלִי בְּכ' מַעֲלָה בּוֹ. וְעַל דֶּרֶךְ זוֹ בְּכָל הַמִּנְיָנוֹת. וְסֵדֶר הַמַּזָּלוֹת כָּךְ הוּא. טָלֶה שׁוֹר תְּאוֹמִים סַרְטָן אַרְיֵה בְּתוּלָה מֹאזְנַיִם עַקְרָב קֶשֶׁת גְּדִי דְּלִי דָּגִים:","הַחֶשְׁבּוֹנוֹת כֻּלָּם כְּשֶׁתְּקַבֵּץ שְׁאֵרִית לִשְׁאֵרִית אוֹ כְּשֶׁתּוֹסִיף מִנְיָן עַל מִנְיָן. תְּקַבֵּץ כָּל מִין עִם מִינוֹ. הַשְּׁנִיּוֹת עִם הַשְּׁנִיּוֹת וְהַחֲלָקִים עִם הַחֲלָקִים וְהַמַּעֲלוֹת עִם הַמַּעֲלוֹת. וְכָל זְמַן שֶׁיִּתְקַבֵּץ מִן הַשְּׁנִיּוֹת ס' תָּשִׂים חֵלֶק אֶחָד וְתוֹסִיף עַל הַחֲלָקִים. וְכָל שֶׁיִּתְקַבֵּץ מִן הַחֲלָקִים ס' תָּשִׂים אוֹתוֹ מַעֲלָה וְתוֹסִיף אוֹתָהּ עַל הַמַּעֲלוֹת. וּכְשֶׁתְּקַבֵּץ הַמַּעֲלוֹת תַּשְׁלִיךְ אוֹתָן ש\"ס וְהַנִּשְׁאָר מִש\"ס וּלְמַטָּה הוּא שֶׁתּוֹפְסִין אוֹתוֹ לְחֶשְׁבּוֹן:","בְּכָל הַחֶשְׁבּוֹנוֹת כֻּלָּן כְּשֶׁתִּרְצֶה לִגְרֹעַ מִנְיָן מִמִּנְיָן. אִם יִהְיֶה זֶה שֶׁגּוֹרְעִין אוֹתוֹ יֶתֶר עַל זֶה שֶׁגּוֹרְעִין מִמֶּנּוּ אֲפִלּוּ בְּחֵלֶק אֶחָד תּוֹסִיף עַל זֶה שֶׁגּוֹרְעִין מִמֶּנּוּ ש\"ס מַעֲלוֹת כְּדֵי שֶׁיְּהֵא אֶפְשָׁר לִגְרֹעַ זֶה הַמִּנְיָן מִמֶּנּוּ:","כֵּיצַד. הֲרֵי שֶׁהִצְרִיכְךָ הַחֶשְׁבּוֹן לִגְרֹעַ מָאתַיִם מַעֲלוֹת וְנ' חֲלָקִים וּמ' שְׁנִיּוֹת. סִימָן רנ\"ם. מִק' מַעֲלוֹת וְכ' חֲלָקִים וְל' שְׁנִיּוֹת. סִימָנָן קכ\"ל. תּוֹסִיף עַל הַק' ש\"ס יִהְיוּ הַמַּעֲלוֹת ת\"ס וְתַתְחִיל לִגְרֹעַ הַשְּׁנִיּוֹת מִן הַשְּׁנִיּוֹת תָּבוֹא לִגְרֹעַ אַרְבָּעִים מִשְּׁלֹשִׁים אִי אֶפְשָׁר. תָּרִים חֵלֶק אֶחָד מִן הָעֶשְׂרִים חֲלָקִים וְתַעֲשֶׂה אוֹתוֹ שִׁשִּׁים שְׁנִיּוֹת וְתוֹסִיף עַל הַשְּׁלֹשִׁים וְנִמְצְאוּ הַשְּׁנִיּוֹת תִּשְׁעִים. תִּגְרַע מֵהֶם הַמ' יִשָּׁאֵר חֲמִשִּׁים שְׁנִיּוֹת. וְתַחֲזֹר לִגְרֹעַ חֲמִשִּׁים חֲלָקִים מִי\"ט חֲלָקִים שֶׁכְּבָר הֲרִימוֹתָ מֵהֶם חֵלֶק אֶחָד וַעֲשִׂיתוֹ שְׁנִיּוֹת. וְאִי אֶפְשָׁר לִגְרֹעַ חֲמִשִּׁים מִתִּשְׁעָה עָשָׂר. לְפִיכָךְ תָּרִים מַעֲלָה אַחַת מִן הַמַּעֲלוֹת וְתַעֲשֶׂה אוֹתָהּ שִׁשִּׁים חֲלָקִים וְתוֹסִיף עַל הַתִּשְׁעָה עָשָׂר וְנִמְצְאוּ הַחֲלָקִים ע\"ט. תִּגְרַע מֵהֶן הַחֲמִשִּׁים יִשָּׁאֵר תִּשְׁעָה וְעֶשְׂרִים חֲלָקִים. וְתַחֲזֹר לִגְרֹעַ הַמָּאתַיִם מַעֲלוֹת מִן אַרְבַּע מֵאוֹת וְנ\"ט מַעֲלוֹת שֶׁכְּבָר הֲרִימוֹתָ מַעֲלָה אַחַת וְעָשִׂיתָ חֲלָקִים. יִשָּׁאֵר מָאתַיִם וְתֵשַׁע וַחֲמִשִּׁים מַעֲלוֹת וְנִמְצָא הַשְּׁאָר סִימָנוֹ רנ\"ט כ\"ט נ'. וְעַל דֶּרֶךְ זוֹ בְּכָל גֵּרָעוֹן וְגֵרָעוֹן:","הַשֶּׁמֶשׁ וְהַיָּרֵחַ וְכֵן שְׁאָר הַשִּׁבְעָה כּוֹכָבִים מַהֲלַךְ כָּל אֶחָד וְאֶחָד מֵהֶן בַּגַּלְגַּל שֶׁלּוֹ מַהֲלָךְ שָׁוֶה. אֵין בּוֹ לֹא קַלּוּת וְלֹא כְּבֵדוּת אֶלָּא כְּמוֹ מַהֲלָכוֹ הַיּוֹם כְּמוֹ מַהֲלָכוֹ אֶמֶשׁ כְּמוֹ מַהֲלָכוֹ לְמָחָר כְּמוֹ מַהֲלָכוֹ בְּכָל יוֹם וָיוֹם. וְגַלְגַּל שֶׁל כָּל אֶחָד מֵהֶם אַף עַל פִּי שֶׁהוּא מַקִּיף אֶת הָעוֹלָם אֵין הָאָרֶץ בְּאֶמְצָעוֹ:","לְפִיכָךְ אִם תַּעֲרֹךְ מַהֲלַךְ כָּל אֶחָד מֵהֶן לַגַּלְגַּל הַמַּקִּיף אֶת הָעוֹלָם שֶׁהָאָרֶץ בְּאֶמְצָעוֹ שֶׁהוּא גַּלְגַּל הַמַּזָּלוֹת. יִשְׁתַּנֶּה הִלּוּכוֹ וְנִמְצָא מַהֲלָכוֹ בְּיוֹם זֶה בְּגַלְגַּל הַמַּזָּלוֹת פָּחוֹת אוֹ יוֹתֵר עַל מַהֲלָכוֹ אֶמֶשׁ אוֹ עַל מַהֲלָכוֹ לְמָחָר:","הַמַּהֲלָךְ הַשָּׁוֶה שֶׁמְּהַלֵּךְ הַכּוֹכָב אוֹ הַשֶּׁמֶשׁ אוֹ הַיָּרֵחַ בְּגַלְגַּלּוֹ הוּא הַנִּקְרָא אֶמְצַע הַמַּהֲלָךְ. וְהַמַּהֲלָךְ שֶׁיִּהְיֶה בְּגַלְגַּל הַמַּזָּלוֹת שֶׁהוּא פְּעָמִים יוֹתֵר וּפְעָמִים חָסֵר הוּא הַמַּהֲלָךְ הָאֲמִתִּי. וּבוֹ יִהְיֶה מְקוֹם הַשֶּׁמֶשׁ אוֹ מְקוֹם הַיָּרֵחַ הָאֲמִתִּי:","כְּבָר אָמַרְנוּ שֶׁאֵלּוּ הַדְּרָכִים שֶׁאָנוּ מְבָאֲרִים בַּהֲלָכוֹת אֵלּוּ אֵינָן אֶלָּא לְחֶשְׁבּוֹן רְאִיַּת הַיָּרֵחַ בִּלְבַד. לְפִיכָךְ עָשִׂינוּ הָעִקָּר שֶׁמִּמֶּנּוּ מַתְחִילִין לְעוֹלָם לְחֶשְׁבּוֹן זֶה מִתְּחִלַּת לֵיל חֲמִישִׁי שֶׁיּוֹמוֹ יוֹם שְׁלִישִׁי לְחֹדֶשׁ נִיסָן מִשָּׁנָה זוֹ שֶׁהִיא שְׁנַת י\"ז מִמַּחֲזוֹר ר\"ס. שֶׁהִיא שְׁנַת תתקל\"ח וְאַרְבַּעַת אַלְפַּיִם לַיְצִירָה. שֶׁהִיא שְׁנַת תפ\"ט וְאֶלֶף לַשְּׁטָרוֹת. שֶׁהִיא שְׁנַת ק\"ט וְאֶלֶף לְחֻרְבַּן בַּיִת שֵׁנִי. וְזוֹ הִיא שֶׁאָנוּ קוֹרְאִים אוֹתָהּ שְׁנַת הָעִקָּר בְּחֶשְׁבּוֹן זֶה:","וּלְפִי שֶׁהָרְאִיָּה לֹא תִּהְיֶה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ. עָשִׂינוּ כָּל דַּרְכֵי חֶשְׁבּוֹן הַזֶּה בְּנוּיִים עַל עִיר יְרוּשָׁלַיִם וְלִשְׁאָר הַמְּקוֹמוֹת הַסּוֹבְבִין אוֹתָהּ בִּכְמוֹ שִׁשָּׁה אוֹ שִׁבְעָה יָמִים שֶׁבָּהֶן רוֹאִין אֶת הַיָּרֵחַ תָּמִיד וּבָאִים וּמְעִידִים בְּבֵית דִּין. וּמָקוֹם זֶה הוּא נוֹטֶה מִתַּחַת הַקַּו הַשָּׁוֶה הַמְסַבֵּב בְּאֶמְצַע הָעוֹלָם כְּנֶגֶד רוּחַ צְפוֹנִית בִּכְמוֹ ל\"ב מַעֲלוֹת עַד ל\"ה וְעַד כ\"ט. וְכֵן הוּא נוֹטֶה מֵאֶמְצַע הַיִּשּׁוּב כְּנֶגֶד רוּחַ מַעֲרָב בִּכְמוֹ כ\"ד מַעֲלוֹת עַד כ\"ז וְעַד כ\"א:"],"Mishneh Torah, Sanctification of the New Month 5":["כָּל מַה שֶּׁאָמַרְנוּ מִקְּבִיעוֹת רֹאשׁ חֹדֶשׁ עַל הָרְאִיָּה וְעִבּוּר הַשָּׁנָה מִפְּנֵי הַזְּמַן אוֹ מִפְּנֵי הַצֹּרֶךְ. אֵין עוֹשִׂין אוֹתוֹ אֶלָּא סַנְהֶדְרִין שֶׁבְּאֶרֶץ יִשְׂרָאֵל אוֹ בֵּית דִּין הַסְּמוּכִים בְּאֶרֶץ יִשְׂרָאֵל שֶׁנָּתְנוּ לָהֶן הַסַּנְהֶדְרִין רְשׁוּת. שֶׁכָּךְ נֶאֱמַר לְמשֶׁה וּלְאַהֲרֹן (שמות יב ב) \"הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים\" וּמִפִּי הַשְּׁמוּעָה לָמְדוּ אִישׁ מֵאִישׁ מִמּשֶׁה רַבֵּנוּ שֶׁכָּךְ הוּא פֵּרוּשׁ הַדָּבָר עֵדוּת זוֹ תִּהְיֶה מְסוּרָה לָכֶם וּלְכָל הָעוֹמֵד אַחֲרֵיכֶם בִּמְקוֹמְכֶם. אֲבָל בִּזְמַן שֶׁאֵין שָׁם סַנְהֶדְרִין בְּאֶרֶץ יִשְׂרָאֵל אֵין קוֹבְעִין חֳדָשִׁים וְאֵין מְעַבְּרִין שָׁנִים אֶלָּא בְּחֶשְׁבּוֹן זֶה שֶׁאָנוּ מְחַשְּׁבִין בּוֹ הַיּוֹם:","וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי הוּא. שֶׁבִּזְמַן שֶׁיֵּשׁ סַנְהֶדְרִין קוֹבְעִין עַל פִּי הָרְאִיָּה וּבִזְמַן שֶׁאֵין שָׁם סַנְהֶדְרִין קוֹבְעִין עַל פִּי הַחֶשְׁבּוֹן הַזֶּה שֶׁאָנוּ מְחַשְּׁבִין בּוֹ הַיּוֹם וְאֵין נִזְקָקִין לִרְאִיָּה. אֶלָּא פְּעָמִים שֶׁיִּהְיֶה יוֹם שֶׁקּוֹבְעִין בּוֹ בְּחֶשְׁבּוֹן זֶה הוּא יוֹם הָרְאִיָּה אוֹ קוֹדֵם לוֹ בַּיּוֹם אוֹ אַחֲרָיו בַּיּוֹם. וְזֶה שֶׁיִּהְיֶה אַחַר הָרְאִיָּה בְּיוֹם פֶּלֶא הוּא וּבַאֲרָצוֹת שֶׁהֵן לְמַעֲרַב אֶרֶץ יִשְׂרָאֵל:","וּמֵאֵימָתַי הִתְחִילוּ כָּל יִשְׂרָאֵל לְחַשֵּׁב בְּחֶשְׁבּוֹן זֶה. מִסּוֹף חַכְמֵי הַגְּמָרָא בְּעֵת שֶׁחָרְבָה אֶרֶץ יִשְׂרָאֵל וְלֹא נִשְׁאַר שָׁם בֵּית דִּין קָבוּעַ. אֲבָל בִּימֵי חַכְמֵי מִשְׁנָה וְכֵן בִּימֵי חַכְמֵי הַגְּמָרָא עַד יְמֵי אַבַּיֵּי וְרָבָא עַל קְבִיעַת אֶרֶץ יִשְׂרָאֵל הָיוּ סוֹמְכִין:","כְּשֶׁהָיְתָה סַנְהֶדְרִין קַיֶּמֶת וְהֵן קוֹבְעִין עַל הָרְאִיָּה. הָיוּ בְּנֵי אֶרֶץ יִשְׂרָאֵל וְכָל הַמְּקוֹמוֹת שֶׁמַּגִּיעִין אֲלֵיהֶן שְׁלוּחֵי תִּשְׁרֵי עוֹשִׂין יָמִים טוֹבִים יוֹם אֶחָד בִּלְבַד. וּשְׁאָר הַמְּקוֹמוֹת הָרְחוֹקוֹת שֶׁאֵין שְׁלוּחֵי תִּשְׁרֵי מַגִּיעִין אֲלֵיהֶם הָיוּ עוֹשִׂים שְׁנֵי יָמִים מִסָּפֵק לְפִי שֶׁלֹּא הָיוּ יוֹדְעִין יוֹם שֶׁקָּבְעוּ בּוֹ בְּנֵי אֶרֶץ יִשְׂרָאֵל אֶת הַחֹדֶשׁ:","בַּזְּמַן הַזֶּה שֶׁאֵין שָׁם סַנְהֶדְרִין וּבֵית דִּין שֶׁל אֶרֶץ יִשְׂרָאֵל קוֹבְעִין עַל חֶשְׁבּוֹן זֶה. הָיָה מִן הַדִּין שֶׁיִּהְיוּ בְּכָל הַמְּקוֹמוֹת עוֹשִׂין יוֹם טוֹב אֶחָד בִּלְבַד אֲפִלּוּ הַמְּקוֹמוֹת הָרְחוֹקוֹת שֶׁבְּחוּצָה לָאָרֶץ כְּמוֹ בְּנֵי אֶרֶץ יִשְׂרָאֵל. שֶׁהַכּל עַל חֶשְׁבּוֹן אֶחָד סוֹמְכִין וְקוֹבְעִין. אֲבָל תַּקָּנַת חֲכָמִים הוּא שֶׁיִּזָּהֲרוּ בְּמִנְהַג אֲבוֹתֵיהֶם שֶׁבִּידֵיהֶם:","לְפִיכָךְ כָּל מָקוֹם שֶׁלֹּא הָיוּ שְׁלוּחֵי תִּשְׁרֵי מַגִּיעִין אֵלָיו כְּשֶׁהָיוּ הַשְּׁלוּחִין יוֹצְאִין. יַעֲשׂוּ שְׁנֵי יָמִים וַאֲפִלּוּ בַּזְּמַן הַזֶּה כְּמוֹ שֶׁהָיוּ עוֹשִׂין בִּזְמַן שֶׁבְּנֵי אֶרֶץ יִשְׂרָאֵל קוֹבְעִין עַל הָרְאִיָּה. וּבְנֵי אֶרֶץ יִשְׂרָאֵל בַּזְּמַן הַזֶּה עוֹשִׂין יוֹם אֶחָד כְּמִנְהָגָן שֶׁמֵּעוֹלָם לֹא עָשׂוּ שְׁנֵי יָמִים. נִמְצָא יוֹם טוֹב שֵׁנִי שֶׁאָנוּ עוֹשִׂין בְּגָלֻיּוֹת בַּזְּמַן הַזֶּה מִדִּבְרֵי סוֹפְרִים שֶׁתִּקְּנוּ דָּבָר זֶה:","יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה בִּזְמַן שֶׁהָיוּ קוֹבְעִין עַל הָרְאִיָּה הָיוּ רֹב בְּנֵי אֶרֶץ יִשְׂרָאֵל עוֹשִׂין אוֹתוֹ שְׁנֵי יָמִים מִסָּפֵק. לְפִי שֶׁלֹּא הָיוּ יוֹדְעִין יוֹם שֶׁקָּבְעוּ בּוֹ בֵּית דִּין אֶת הַחֹדֶשׁ שֶׁאֵין הַשְּׁלוּחִין יוֹצְאִין בְּיוֹם טוֹב:","וְלֹא עוֹד אֶלָּא אֲפִלּוּ בִּירוּשָׁלַיִם עַצְמָהּ שֶׁהוּא מְקוֹם בֵּית דִּין פְּעָמִים רַבּוֹת הָיוּ עוֹשִׂין יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה שְׁנֵי יָמִים. שֶׁאִם לֹא בָּאוּ הָעֵדִים כָּל יוֹם שְׁלֹשִׁים נוֹהֲגִין הָיוּ בְּאוֹתוֹ הַיּוֹם שֶׁמְּצַפִּין לְעֵדִים קֹדֶשׁ וּלְמָחָר קֹדֶשׁ. וְהוֹאִיל וְהָיוּ עוֹשִׂין אוֹתוֹ שְׁנֵי יָמִים וַאֲפִלּוּ בִּזְמַן הָרְאִיָּה הִתְקִינוּ שֶׁיִּהְיוּ עוֹשִׂין אֲפִלּוּ בְּנֵי אֶרֶץ יִשְׂרָאֵל אוֹתוֹ תָּמִיד שְׁנֵי יָמִים בַּזְּמַן הַזֶּה שֶׁקּוֹבְעִין עַל הַחֶשְׁבּוֹן. הִנֵּה לָמַדְתָּ שֶׁאֲפִלּוּ יוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה בַּזְּמַן הַזֶּה מִדִּבְרֵי סוֹפְרִים:","אֵין עֲשִׂיַּת יוֹם טוֹב אֶחָד תְּלוּיָה בִּקְרִיבַת הַמָּקוֹם. כֵּיצַד. אִם יִהְיֶה מָקוֹם בֵּינוֹ וּבֵין יְרוּשָׁלַיִם מַהֲלַךְ חֲמִשָּׁה יָמִים אוֹ פָּחוֹת שֶׁבְּוַדַּאי אֶפְשָׁר שֶׁיַּגִּיעוּ לָהֶן שְׁלוּחִין. אֵין אוֹמְרִין שֶׁאַנְשֵׁי מָקוֹם זֶה עוֹשִׂין יוֹם טוֹב אֶחָד. שֶׁמִּי יֹאמַר לָנוּ שֶׁהָיוּ הַשְּׁלוּחִים יוֹצְאִין לְמָקוֹם זֶה. שֶׁמָּא לֹא הָיוּ הַשְּׁלוּחִים יוֹצְאִין לְמָקוֹם זֶה מִפְּנֵי שֶׁלֹּא הָיוּ שָׁם יִשְׂרָאֵל וְאַחַר שֶׁחָזְרוּ לִקְבֹּעַ עַל הַחֶשְׁבּוֹן יָשְׁבוּ שָׁם יִשְׂרְאֵלִים שֶׁהֵן חַיָּבִין לַעֲשׂוֹת שְׁנֵי יָמִים. אוֹ מִפְּנֵי שֶׁהָיָה חֵרוּם בַּדֶּרֶךְ כְּדֶרֶךְ שֶׁהָיָה בֵּין יְהוּדָה וְגָלִיל בִּימֵי חַכְמֵי הַמִּשְׁנָה. אוֹ מִפְּנֵי שֶׁהָיוּ הַכּוּתִים מוֹנְעִין אֶת הַשְּׁלוּחִין לַעֲבֹר בֵּינֵיהֶן:","וְאִלּוּ הָיָה הַדָּבָר תָּלוּי בִּקְרִיבַת הַמָּקוֹם הָיוּ כָּל בְּנֵי מִצְרַיִם עוֹשִׂין יוֹם אֶחָד. שֶׁהֲרֵי אֶפְשָׁר שֶׁיַּגִּיעוּ לָהֶם שְׁלוּחֵי תִּשְׁרֵי. שֶׁאֵין בֵּין יְרוּשָׁלַיִם וּמִצְרַיִם עַל דֶּרֶךְ אַשְׁקְלוֹן אֶלָּא מַהֲלַךְ שְׁמוֹנָה יָמִים אוֹ פָּחוֹת וְכֵן רֹב סוּרְיָא. הָא לָמַדְתָּ שֶׁאֵין הַדָּבָר תָּלוּי בִּהְיוֹת הַמָּקוֹם קָרוֹב:","נִמְצָא עִקַּר דָּבָר זֶה עַל דֶּרֶךְ זוֹ כָּךְ הוּא. כָּל מָקוֹם שֶׁיֵּשׁ בֵּינוֹ וּבֵין יְרוּשָׁלַיִם מַהֲלָךְ יֶתֶר עַל עֲשָׂרָה יָמִים גְּמוּרִים עוֹשִׂין שְׁנֵי יָמִים לְעוֹלָם כְּמִנְהָגָם מִקֹּדֶם. שֶׁאֵין שְׁלוּחֵי כָּל תִּשְׁרֵי וְתִשְׁרֵי מַגִּיעִין אֶלָּא לְמָקוֹם שֶׁבֵּינוֹ וּבֵין יְרוּשָׁלַיִם מַהֲלַךְ עֲשָׂרָה יָמִים אוֹ פָּחוֹת. וְכָל מָקוֹם שֶׁבֵּינוֹ לְבֵין יְרוּשָׁלַיִם מַהֲלַךְ עֲשָׂרָה יָמִים בְּשָׁוֶה אוֹ פָּחוֹת שֶׁאֶפְשָׁר שֶׁיִּהְיוּ שְׁלוּחִין מַגִּיעִין אֵלָיו. רוֹאִים אִם אוֹתוֹ הַמָּקוֹם מֵאֶרֶץ יִשְׂרָאֵל שֶׁהָיוּ בָּהּ יִשְׂרָאֵל בִּשְׁעַת הָרְאִיָּה בְּכִבּוּשׁ שֵׁנִי כְּגוֹן אוּשָׁא וּשְׁפַרְעָם וְלוּז וְיַבְנֵה וְנֹב וּטְבֶרְיָה וְכַיּוֹצֵא בָּהֶן עוֹשִׂין יוֹם אֶחָד בִּלְבַד. וְאִם אוֹתוֹ הַמָּקוֹם מִסּוּרְיָא כְּגוֹן צוֹר וְדַמֶּשֶׂק וְאַשְׁקְלוֹן וְכַיּוֹצֵא בָּהֶן. אוֹ מִחוּצָה לָאָרֶץ כְּגוֹן מִצְרַיִם וְעַמּוֹן וּמוֹאָב וְכַיּוֹצֵא בָּהֶן. עוֹשִׂין כְּמִנְהַג אֲבוֹתֵיהֶן שֶׁבִּידֵיהֶן אִם יוֹם אֶחָד יוֹם אֶחָד וְאִם שְׁנֵי יָמִים שְׁנֵי יָמִים:","מָקוֹם שֶׁבֵּינוֹ וּבֵין יְרוּשָׁלַיִם עֲשָׂרָה יָמִים אוֹ פָּחוֹת מֵעֲשָׂרָה וְהוּא סוּרְיָא אוֹ חוּצָה לָאָרֶץ וְאֵין לָהֶם מִנְהָג. אוֹ שֶׁהִיא עִיר שֶׁנִּתְחַדְּשָׁה בְּמִדְבַּר אֶרֶץ יִשְׂרָאֵל. אוֹ מָקוֹם שֶׁשָּׁכְנוּ בּוֹ יִשְׂרָאֵל עַתָּה. עוֹשִׂין שְׁנֵי יָמִים כְּמִנְהַג רֹב הָעוֹלָם. וְכָל יוֹם טוֹב שֵׁנִי מִדִּבְרֵי סוֹפְרִים וַאֲפִלּוּ יוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה שֶׁהַכּל עוֹשִׂין אוֹתוֹ בַּזְּמַן הַזֶּה:","זֶה שֶׁאָנוּ מְחַשְּׁבִין בַּזְּמַן הַזֶּה כָּל אֶחָד וְאֶחָד בְּעִירוֹ וְאוֹמְרִין שֶׁרֹאשׁ חֹדֶשׁ יוֹם פְּלוֹנִי וְיוֹם טוֹב בְּיוֹם פְּלוֹנִי. לֹא בַּחֶשְׁבּוֹן שֶׁלָּנוּ אָנוּ קוֹבְעִין וְלֹא עָלָיו אָנוּ סוֹמְכִין. שֶׁאֵין מְעַבְּרִין שָׁנִים וְקוֹבְעִין חֳדָשִׁים בְּחוּצָה לָאָרֶץ. וְאֵין אָנוּ סוֹמְכִין אֶלָּא עַל חֶשְׁבּוֹן בְּנֵי אֶרֶץ יִשְׂרָאֵל וּקְבִיעָתָם. וְזֶה שֶׁאָנוּ מְחַשְּׁבִין לְגַלּוֹת הַדָּבָר בִּלְבַד הוּא. כֵּיוָן שֶׁאָנוּ יוֹדְעִין שֶׁעַל חֶשְׁבּוֹן זֶה הֵן סוֹמְכִין אָנוּ מְחַשְּׁבִין לֵידַע יוֹם שֶׁקָּבְעוּ בּוֹ בְּנֵי אֶרֶץ יִשְׂרָאֵל אֵי זֶה יוֹם הוּא. וּקְבִיעַת בְּנֵי אֶרֶץ יִשְׂרָאֵל אוֹתוֹ הוּא שֶׁיִּהְיֶה רֹאשׁ חֹדֶשׁ אוֹ יוֹם טוֹב. לֹא מִפְּנֵי חֶשְׁבּוֹן שֶׁאָנוּ מְחַשְּׁבִין:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 2":["מַעֲשֵׂר שֵׁנִי נֶאֱכָל לִבְעָלָיו לְפָנִים מֵחוֹמַת יְרוּשָׁלַיִם שֶׁנֶּאֱמַר (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ בַּמָּקוֹם אֲשֶׁר יִבְחַר לְשַׁכֵּן שְׁמוֹ שָׁם\" וְגוֹ'. וְנוֹהֵג בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת אֲבָל אֵינוֹ נֶאֱכָל בִּירוּשָׁלַיִם אֶלָּא בִּפְנֵי הַבַּיִת שֶׁנֶּאֱמַר (דברים יד כג) \"מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנְךָ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ מָה בְּכוֹר אֵינוֹ נֶאֱכָל אֶלָּא בִּפְנֵי הַבַּיִת אַף מַעֲשֵׂר שֵׁנִי לֹא יֵאָכֵל אֶלָּא בִּפְנֵי הַבַּיִת:","מִדַּת חֲסִידוּת שֶׁפּוֹדִין מַעֲשֵׂר שֵׁנִי בַּזְּמַן הַזֶּה בְּשָׁוְיוֹ כְּדֶרֶךְ שֶׁפּוֹדִין אוֹתוֹ בִּפְנֵי הַבַּיִת. וְהוֹרוּ הַגְּאוֹנִים שֶׁאִם רָצָה לִפְדּוֹת שְׁוֵה מָנֶה בִּפְרוּטָה לְכַתְּחִלָּה בַּזְּמַן הַזֶּה פּוֹדֶה. לֹא יִהְיֶה זֶה חָמוּר מִן הַקֹּדֶשׁ. וּמַשְׁלִיךְ הַפְּרוּטָה לַיָּם הַגָּדוֹל:","וְכֵן אִם חִלֵּל מַעֲשֵׂר שְׁוֵה מָנֶה עַל שְׁוֵה פְּרוּטָה מִפֵּרוֹת אֲחֵרוֹת הֲרֵי זֶה מְחֻלָּל. וְשׂוֹרֵף אֶת הַפֵּרוֹת שֶׁחִלֵּל עֲלֵיהֶם כְּדֵי שֶׁלֹּא יִהְיוּ תַּקָּלָה לַאֲחֵרִים. כְּפִדְיוֹן נֶטַע רְבָעִי בַּזְּמַן הַזֶּה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מַאֲכָלוֹת:","כְּשֵׁם שֶׁאֵין אוֹכְלִין מַעֲשֵׂר שֵׁנִי בַּזְּמַן הַזֶּה בִּירוּשָׁלַיִם כָּךְ אֵין פּוֹדִין אוֹתוֹ שָׁם. וְאֵין מְחַלְּלִין אוֹתוֹ וְאֵין מוֹכְרִין אוֹתוֹ. וְאִם נִכְנַס בִּירוּשָׁלַיִם אַף בַּזְּמַן הַזֶּה אֵין מוֹצִיאִין אוֹתוֹ מִשָּׁם וּמַנִּיחִים אוֹתוֹ שָׁם עַד שֶׁיֵּרָקֵב וְכֵן אִם עָבַר וְהוֹצִיאוֹ מִשָּׁם מַנִּיחִין אוֹתוֹ עַד שֶׁיֵּרָקֵב. לְפִיכָךְ אֵין מַפְרִישִׁים מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם בַּזְּמַן הַזֶּה אֶלָּא מוֹצִיאִין אֶת הַפֵּרוֹת בְּטִבְלָן חוּץ לָעִיר וּמַפְרִישִׁין אוֹתוֹ שָׁם וּפוֹדֵהוּ. וְאִם הִפְרִישׁוּ שָׁם בַּזְּמַן הַזֶּה יֵרָקֵב:","כָּל הָאוֹכֵל כְּזַיִת מַעֲשֵׂר שֵׁנִי אוֹ שֶׁשָּׁתָה מִמֶּנּוּ רְבִיעִית יַיִן חוּץ לְחוֹמַת יְרוּשָׁלַיִם לוֹקֶה שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\" וְגוֹ'. וְלוֹקֶה עַל כָּל אֶחָד וְאֶחָד בִּפְנֵי עַצְמוֹ. לְפִיכָךְ אִם אָכַל שְׁלָשְׁתָּן חוּץ לַחוֹמָה לוֹקֶה שָׁלֹשׁ מַלְקִיּוֹת שֶׁנֶּאֱמַר (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\" מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וְנֶאֱמַר לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ וְגוֹ' לָמָּה פְּרָטָן וְלֹא אָמַר לֹא תֹאכְלֵם בִּשְׁעָרֶיךָ לְחַיֵּב עַל כָּל אֶחָד וְאֶחָד בִּפְנֵי עַצְמוֹ:","אֵינוֹ לוֹקֶה מִן הַתּוֹרָה עַד שֶׁיֹּאכְלֶנּוּ אַחַר שֶׁנִּכְנַס לְחוֹמַת יְרוּשָׁלַיִם שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ\" וְגוֹ' (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\". כֵּיוָן שֶׁנִּכְנַס לִמְקוֹם אֲכִילָתוֹ וַאֲכָלוֹ בַּחוּץ לוֹקֶה. אֲבָל אִם אֲכָלוֹ קֹדֶם שֶׁיִּכָּנְסוּ לִירוּשָׁלַיִם מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵיהֶם:","מִקְצָת מַעֲשֵׂר בִּפְנִים וּמִקְצָתוֹ מִבַּחוּץ הָאוֹכֵל מִזֶּה שֶׁעֲדַיִן לֹא נִכְנַס מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְהָאוֹכֵל בַּחוּץ מִזֶּה שֶׁנִּכְנַס לוֹקֶה:","אֵין פּוֹדִין מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם אֶלָּא אִם כֵּן נִטְמָא שֶׁנֶּאֱמַר (דברים יד כד) \"כִּי יִרְחַק מִמְּךָ הַמָּקוֹם\" בְּרִחוּק מָקוֹם הוּא נִפְדֶּה וְאֵינוֹ נִפְדֶּה בְּקֵרוּב מָקוֹם. הָיָה הוּא בִּפְנִים וּמַשָּׂאוֹ בַּחוּץ אֲפִלּוּ הָיָה אוֹחֵז אוֹתוֹ בְּקָנֶה הוֹאִיל וְלֹא נִכְנַס הַמַּעֲשֵׂר הֲרֵי זֶה מֻתָּר לִפְדּוֹתוֹ שָׁם בְּצַד הַחוֹמָה:","מַעֲשֵׂר שֵׁנִי שֶׁנִּכְנַס לִירוּשָׁלַיִם אֲפִלּוּ שֶׁל דְּמַאי אָסוּר לְהוֹצִיאוֹ מִשָּׁם שֶׁכְּבָר קְלָטוּהוּ מְחִצּוֹת. וְכֵן פֵּרוֹת הַנִּלְקָחִין בְּכֶסֶף מַעֲשֵׂר שֶׁנֶּאֱמַר (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\". עָבַר וְהוֹצִיאָן אוֹ שֶׁיָּצְאוּ בִּשְׁגָגָה יַחְזְרוּ וְיֵאָכְלוּ בִּירוּשָׁלַיִם. וּקְלִיטַת מְחִצּוֹת מִדִּבְרֵיהֶם אֲפִלּוּ מַעֲשֵׂר שֶׁאֵין בְּחֻמְשׁוֹ שְׁוֵה פְּרוּטָה שֶׁהוּא מִדִּבְרֵיהֶם מְחִצּוֹת קוֹלְטוֹת אוֹתוֹ וְאָסוּר לְהוֹצִיאוֹ. אֲבָל מְעוֹת מַעֲשֵׂר שֵׁנִי נִכְנָסִין לִירוּשָׁלַיִם וְיוֹצְאִין:","פֵּרוֹת שֶׁנִּגְמְרָה מְלַאכְתָּן וְעָבְרוּ בְּתוֹךְ יְרוּשָׁלַיִם וְיָצְאוּ אֵינוֹ יָכוֹל לְהוֹצִיא עֲלֵיהֶן מַעֲשֵׂר שֵׁנִי מִפֵּרוֹת אֲחֵרוֹת שֶׁלֹּא נִכְנְסוּ לִירוּשָׁלַיִם. אֶלָּא יַחֲזֹר מַעֲשֵׂר שֵׁנִי שֶׁלָּהֶן וְיֵאָכֵל בִּירוּשָׁלַיִם וְאֵינוֹ נִפְדֶּה בַּחוּץ. אֲפִלּוּ עָשָׂה כָּל הַפֵּרוֹת הָאֵלּוּ מַעֲשֵׂר שֵׁנִי אַחַר שֶׁיָּצְאוּ עַל פֵּרוֹת אֲחֵרוֹת שֶׁלֹּא נִכְנְסוּ יַחְזְרוּ וְיֵאָכְלוּ בִּירוּשָׁלַיִם. חֹמֶר הוּא בִּמְחִצּוֹת יְרוּשָׁלַיִם הוֹאִיל וְקָלְטוּ קָלְטוּ:","פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן שֶׁעָבְרוּ בִּירוּשָׁלַיִם וְיָצְאוּ. כְּגוֹן סַלֵּי עֲנָבִים לְגַת וְסַלֵּי תְּאֵנִים בְּמֻקְצֶה. מֻתָּר לִפְדּוֹת מַעֲשֵׂר שֵׁנִי שֶׁלָּהֶם בַּחוּץ. וְכֵן פֵּרוֹת דְּמַאי אַף עַל פִּי שֶׁנִּגְמְרָה מְלַאכְתָּן וְעָבְרוּ בִּירוּשָׁלַיִם וְיָצְאוּ פּוֹדִין מַעֲשֵׂר שֵׁנִי שֶׁלָּהֶן בַּחוּץ:","פֵּרוֹת מַעֲשֵׂר שֵׁנִי שֶׁנִּטְמְאוּ בִּירוּשָׁלַיִם וּפְדָאָן אִם נִטְמְאוּ בִּוְלַד הַטֻּמְאָה אָסוּר לְהוֹצִיאָן. אֶלָּא יֵאָכְלוּ בִּפְנִים מִפְּנֵי שֶׁוְּלַד הַטֻּמְאָה מִדִּבְרֵיהֶם. וְאִם נִטְמְאוּ בְּאַב הַטֻּמְאָה אוֹ שֶׁנִּטְמְאוּ בַּחוּץ וַאֲפִלּוּ בִּוְלַד הַטֻּמְאָה אַף עַל פִּי שֶׁנִּכְנְסוּ לִירוּשָׁלַיִם הֲרֵי אֵלּוּ נִפְדִּין וְנֶאֱכָלִין בְּכָל מָקוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהִכְנִיסָן עַל מְנָת שֶׁלֹּא תִּתְפְּשֵׂם הַמְּחִצּוֹת. אֲבָל אִם לֹא הִתְנָה הוֹאִיל וְנִכְנַס הֲרֵי הוּא טָהוֹר מִן הַתּוֹרָה [שֶׁאֵין וָלָד מְטַמֵּא שֵׁנִי מִן הַתּוֹרָה] וּכְבָר קְלָטוּהוּ מְחִצּוֹת וְאֵינוֹ יוֹצֵא:","תִּלְתָּן שֶׁל מַעֲשֵׂר שֵׁנִי מֻתָּר לְאָכְלָהּ צִמְחוֹנִין שֶׁכָּךְ הִיא רְאוּיָה לַאֲכִילָה. וְכֵן כַּרְשִׁינֵי מַעֲשֵׂר שֵׁנִי יֵאָכְלוּ צִמְחוֹנִין. וְאִם עָשָׂה מֵהֶם עִסָּה הֲרֵי זוֹ מֻתֶּרֶת לְהִכָּנֵס לִירוּשָׁלַיִם וּלְהוֹצִיאָהּ שֶׁאֵינָן בִּכְלַל הַפֵּרוֹת. וְאִם נִטְמְאוּ בִּירוּשָׁלַיִם יִפָּדוּ וְיֵאָכְלוּ בַּחוּץ:","אִילָן שֶׁעוֹמֵד לְפָנִים מִן הַחוֹמָה וְנוֹפוֹ נוֹטֶה חוּץ לַחוֹמָה אֵין אוֹכְלִין תַּחַת נוֹפוֹ מַעֲשֵׂר שֵׁנִי. וּמַעֲשֵׂר שֵׁנִי שֶׁנִּכְנַס תַּחַת נוֹפוֹ אֵין פּוֹדִין אוֹתוֹ שֶׁהֲרֵי הוּא כְּמִי שֶׁנִּכְנַס לִירוּשָׁלַיִם:","בָּתִּים שֶׁבְּצַד הַחוֹמָה שֶׁפִּתְחֵיהֶם לְפָנִים מִן הַחוֹמָה וַחֲלָלָן לְחוּץ. מִכְּנֶגֶד הַחוֹמָה וּלְפָנִים כִּלְפָנִים לְכָל דָּבָר וּמִכְּנֶגֶד הַחוֹמָה וְלַחוּץ אֵין אוֹכְלִים שָׁם וְאֵין פּוֹדִין שָׁם לְהַחֲמִיר. הָיָה חֲלָלָן לְפָנִים וּפִתְחֵיהֶם לַחוּץ. מִכְּנֶגֶד הַחוֹמָה וְלַחוּץ כְּלַחוּץ פּוֹדִין בּוֹ וְאֵין אוֹכְלִין. וּמִכְּנֶגֶד הַחוֹמָה וְלִפְנִים אֵין אוֹכְלִין שָׁם וְאֵין פּוֹדִין לְהַחֲמִיר. וְהַחַלּוֹנוֹת וָעֳבִי הַחוֹמָה כִּלְפָנִים:"],"Mishneh Torah, Service on the Day of Atonement 5":["כָּל עֲבוֹדוֹת שֶׁעוֹבֵד בְּבִגְדֵי לָבָן בִּפְנִים בַּהֵיכָל צָרִיךְ לַעֲשׂוֹתָן עַל הַסֵּדֶר שֶׁבֵּאַרְנוּ. וְאִם הִקְדִּים בָּהֶן מַעֲשֶׂה לַחֲבֵרוֹ לֹא עָשָׂה כְּלוּם:","קְטֹרֶת שֶׁחֲפָנָהּ קֹדֶם שְׁחִיטַת הַפָּר לֹא עָשָׂה כְּלוּם. אַף עַל פִּי שֶׁהַחֲפִינָה בָּעֲזָרָה צֹרֶךְ פְּנִים כַּעֲבוֹדַת פְּנִים הִיא. וְכֵן שָׂעִיר שֶׁשְּׁחָטוֹ קֹדֶם מַתַּן דָּמוֹ שֶׁל פַּר לֹא עָשָׂה כְּלוּם. אַף עַל פִּי שֶׁהַשְּׁחִיטָה בָּעֲזָרָה הֲרֵי דָּמוֹ נִכְנָס לְפָנִים:","אֵיל וּשְׂעִיר הַמּוּסָפִין שֶׁעָשָׂה אוֹתָן קֹדֶם עֲבוֹדַת הַיּוֹם אֵינָן כְּלוּם:","הִקְדִּים דַּם הַשָּׂעִיר לְדַם הַפָּר בְּקֹדֶשׁ הַקָּדָשִׁים קֹדֶם שֶׁיִּגְמֹר עֲבוֹדָתוֹ. יַזֶּה מִדַּם הַפָּר כְּמִצְוָתוֹ וְאַחַר כָּךְ יָבִיא שָׂעִיר אַחֵר וְיִשְׁחֹט אוֹתוֹ וְיַזֶּה מִדָּמוֹ בְּקֹדֶשׁ הַקָּדָשִׁים כְּמִצְוָתוֹ וְיִפָּסֵל הָרִאשׁוֹן. הִקְדִּים דַּם הַשָּׂעִיר לְדַם הַפָּר בְּמַתָּנוֹת שֶׁבַּהֵיכָל עַל הַפָּרֹכֶת יַחְזֹר וְיַזֶּה מִדַּם הַשָּׂעִיר פַּעַם שְׁנִיָּה לְאַחַר דַּם הַפָּר:","נִשְׁפַּךְ הַדָּם עַד שֶׁלֹּא גָּמַר מַתָּנוֹת שֶׁבְּקֹדֶשׁ הַקָּדָשִׁים. יָבִיא דָּם אַחֵר וְיַחְזֹר וְיַזֶּה בַּתְּחִלָּה בְּקֹדֶשׁ הַקָּדָשִׁים:","גָּמַר מַתָּנוֹת שֶׁבְּקֹדֶשׁ הַקָּדָשִׁים וְהִתְחִיל בְּמַתָּנוֹת שֶׁבַּהֵיכָל וְנִשְׁפַּךְ הַדָּם עַד שֶׁלֹּא גָּמַר יָבִיא דָּם אַחֵר וְיַתְחִיל מִתְּחִלַּת הַזָּיוֹת שֶׁבַּהֵיכָל:","גָּמַר מַתָּנוֹת שֶׁבַּהֵיכָל וְהִתְחִיל לִתֵּן עַל מִזְבַּח הַזָּהָב וְנִשְׁפַּךְ הַדָּם עַד שֶׁלֹּא גָּמַר. יָבִיא דָּם אַחֵר וּמַתְחִיל מִתְּחִלַּת מַתְּנוֹת הַמִּזְבֵּחַ שֶׁכֻּלָּן כַּפָּרָה בִּפְנֵי עַצְמָן הֵן:","גָּמַר מַתְּנוֹת הַמִּזְבֵּחַ וְאַחַר כָּךְ נִשְׁפַּךְ הַדָּם אֵינוֹ צָרִיךְ לְהָבִיא דָּם אַחֵר. שֶׁשְּׁפִיכַת הַשְּׁיָרִים עַל מִזְבֵּחַ הַחִיצוֹן אֵינָהּ מְעַכֶּבֶת. וְאִם דָּם הַפָּר הוּא שֶׁנִּשְׁפַּךְ קֹדֶם שֶׁיִּגְמֹר כָּל הַמַּתָּנוֹת הֲרֵי זֶה מֵבִיא פַּר אַחֵר. וְיַחֲפֹן קְטֹרֶת פַּעַם שְׁנִיָּה קֹדֶם שְׁחִיטַת הַפָּר. וְיַקְטִיר הַקְּטֹרֶת וְאַחַר כָּךְ יָבִיא דָּמוֹ וְיַזֶּה מִמֶּנּוּ:","וְאֵין מְטַמֵּא בְּגָדִים וְאֵין נִשְׂרָף בְּבֵית הַדֶּשֶׁן אֶלָּא הַפָּר הַזֶּה הָאַחֲרוֹן שֶׁבּוֹ נִגְמְרָה הַכַּפָּרָה:","נִתְעָרֵב לוֹ דַּם הַפָּר בְּדַם הַשָּׂעִיר קֹדֶם שֶׁיִּגְמֹר הַהַזָּיוֹת. נוֹתֵן אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה לְשֵׁם פַּר. וְחוֹזֵר וְנוֹתֵן אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה לְשֵׁם שָׂעִיר. נִתְעָרְבוּ בְּמַתָּנָה אַחֲרוֹנָה. נוֹתֵן אַחַת לְמַטָּה לְשֵׁם פַּר וְחוֹזֵר וְנוֹתֵן אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה לְשֵׁם שָׂעִיר:","נִתְחַלְּפוּ הַכּוֹסוֹת וְלֹא יָדַע אֵי זֶה הוּא כּוֹס דַּם הַפָּר וְאֵי זֶה הוּא כּוֹס דַּם הַשָּׂעִיר נוֹתֵן מֵאֶחָד מֵהֶן אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה. וְנוֹתֵן מִן הַשֵּׁנִי אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה. (וְחוֹזֵר וְנוֹתֵן מִן הָרִאשׁוֹן אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה). נִמְצָא מִכָּל מָקוֹם שֶׁנָּתַן מִדַּם הַפָּר וְאַחֲרָיו מִדַּם הַשָּׂעִיר:","קִבֵּל דַּם הַפָּר בִּשְׁתֵּי כּוֹסוֹת. וְקִבֵּל דַּם הַשָּׂעִיר בִּשְׁתֵּי כּוֹסוֹת. וְנִתְעָרְבוּ מִקְצָת הַכּוֹסוֹת. וְלֹא נוֹדַע כּוֹס דַּם הַפָּר מִכּוֹס דַּם הַשָּׂעִיר. הֲרֵי זֶה מַזֶּה כָּל הַהַזָּיוֹת כְּמִצְוָתָן מִן הַכּוֹסוֹת שֶׁלֹּא נִתְעָרְבוּ. וְשׁוֹפַךְ שְׁיָרֵי אֵלּוּ שֶׁהִזָּה מֵהֶן עַל הַיְסוֹד כַּמִּצְוָה. וְאוֹתָן הַכּוֹסוֹת שֶׁנִּתְעָרְבוּ יִשָּׁפְכוּ לָאַמָּה:","פַּר יוֹם הַכִּפּוּרִים אַף עַל פִּי שֶׁכֹּהֵן גָּדוֹל קוֹנֶה מִשֶּׁלּוֹ שֶׁנֶּאֱמַר (ויקרא טז ו) (ויקרא טז יא) \"פַּר הַחַטָּאת אֲשֶׁר לוֹ\". הַמָּקוֹם הִפְקִיר מָמוֹנוֹ בּוֹ לְכָל אֶחָיו הַכֹּהֲנִים. שֶׁאִלּוּ לֹא הָיָה לָהֶן בּוֹ שֻׁתָּפוּת לֹא הָיוּ מִתְכַּפְּרִין בּוֹ. לְפִיכָךְ אִם מֵת כֹּהֵן גָּדוֹל קֹדֶם שֶׁיִּשָּׁחֵט הַפָּר. הַכֹּהֵן שֶׁעוֹמֵד תַּחְתָּיו אֵינוֹ מֵבִיא פַּר אַחֵר אֶלָּא שׁוֹחֵט אֶת שֶׁל רִאשׁוֹן. וְאֵינוֹ חַטָּאת שֶׁמֵּתוּ בְּעָלֶיהָ שֶׁתָּמוּת שֶׁאֵין חַטַּאת הָרַבִּים מֵתָה. שָׁחַט אֶת הַפָּר וּמֵת קֹדֶם שֶׁיְּכַפֵּר בְּדָמוֹ. הַכֹּהֵן הָאַחֵר נִכְנָס בְּדָם זֶה וּמְכַפֵּר בּוֹ:","שְׁנֵי שְׂעִירֵי יוֹם הַכִּפּוּרִים מִצְוָתָן שֶׁיִּהְיוּ שָׁוִין בְּמַרְאֶה וּבְקוֹמָה וּבְדָמִים. וּלְקִיחָתָן כְּאַחַת. אַף עַל פִּי שֶׁאֵינָן שָׁוִין כְּשֵׁרִין. לָקַח אֶחָד מֵהֶן הַיּוֹם וְאֶחָד לְמָחָר כְּשֵׁרִים:","מֵת אֶחָד מֵהֶן. אִם עַד שֶׁלֹּא הִגְרִיל מֵת יִקַּח זוּג לְשֵׁנִי. וְאִם מִשֶּׁהִגְרִיל מֵת יָבִיא שְׁנַיִם וְיַגְרִיל עֲלֵיהֶן בַּתְּחִלָּה וְרוֹאֶה אֵי זֶהוּ שֶׁמֵּת. אִם הָיָה שֶׁל שֵׁם אוֹמֵר זֶה שֶׁעָלָה עָלָיו הַגּוֹרָל לַשֵּׁם יִתְקַיֵּם תַּחְתָּיו. וְאִם הָיָה הַמֵּת שֶׁל עֲזָאזֵל יֹאמַר זֶה שֶׁעָלָה עָלָיו הַגּוֹרָל לַעֲזָאזֵל יִתְקַיֵּם תַּחְתָּיו. וְהַשֵּׁנִי מִן הַשְּׁנַיִם שֶׁהִגְרִיל עֲלֵיהֶן בַּסּוֹף יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִמָּכֵר וְיִפְּלוּ דָּמָיו לִנְדָבָה. שֶׁאֵין חַטַּאת הַצִּבּוּר מֵתָה:","פַּר וְשָׂעִיר שֶׁל יוֹם הַכִּפּוּרִים שֶׁאָבְדוּ וְהִפְרִישׁ אֲחֵרִים תַּחְתֵּיהֶן וְקָרְבוּ וְנִמְצְאוּ הָרִאשׁוֹנִים. יִרְעוּ עַד שֶׁיִּסְתָּאֲבוּ וְיִמָּכְרוּ וְיִפְּלוּ דְּמֵיהֶן לִנְדָבָה. וְכֵן אִם נִמְצְאוּ הָרִאשׁוֹנִים קֹדֶם שֶׁיִּקָּרְבוּ אֵלּוּ יִקָּרְבוּ הָרִאשׁוֹנִים וְיִרְעוּ הַשְּׁנִיִּים עַד שֶׁיִּפּל בָּהֶן מוּם וְיִפְּלוּ דְּמֵיהֶן לִנְדָבָה. שֶׁאֵין חַטַּאת הַצִּבּוּר מֵתָה:","הַמּוּם פּוֹסֵל בְּשָׂעִיר הַמִּשְׁתַּלֵּחַ אֲפִלּוּ מוּם עוֹבֵר. וְכֵן אִם נַעֲשָׂה מְחֻסַּר זְמַן נִפְסָל. כְּגוֹן שֶׁנִּשְׁחֲטָה אִמּוֹ לְחוֹלֶה בְּיוֹם הַכִּפּוּרִים. שֶׁדְּחִיָּתוֹ לַעֲזָאזֵל הִיא שְׁחִיטָתוֹ:","הָיָה טְרֵפָה פָּסוּל שֶׁנֶּאֱמַר (ויקרא טז י) \"יָעֳמַד חַי\":","חָלָה הַשָּׂעִיר וְאֵין יָכוֹל לְהַלֵּךְ מַרְכִּיבוֹ עַל כְּתֵפוֹ וַאֲפִלּוּ בְּשַׁבָּת:","חָלָה הַמְשַׁלֵּחַ הֲרֵי זֶה מְשַׁלְּחוֹ בְּיַד אַחֵר:","נִטְמָא הַמְשַׁלֵּחַ הֲרֵי זֶה נִכְנָס לַמִּקְדָּשׁ וְנוֹטְלוֹ וְיוֹצֵא. שֶׁנֶּאֱמַר (ויקרא טז כא) \"בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה\". בְּיַד זֶה שֶׁהוּכַן אֲפִלּוּ נִטְמָא:","דְּחָפוֹ וְנָפַל הַשָּׂעִיר וְלֹא מֵת. יֵרֵד אַחֲרָיו וִימִיתֶנּוּ בְּכָל דָּבָר שֶׁמְּמִיתוֹ. וְאֵיבְרֵי שָׂעִיר זֶה מֻתָּרִין בַּהֲנָיָה:","נִפְחֲתָה תִּקְרָה שֶׁל הֵיכָל לֹא הָיָה מַזֶּה. שֶׁנֶּאֱמַר (ויקרא טז יז) \"בְּאֹהֶל מוֹעֵד\":","מִזְבֵּחַ שֶׁלֹּא נִתְחַנֵּךְ בַּקְּטֹרֶת לֹא יַזֶּה עָלָיו. שֶׁנֶּאֱמַר (ויקרא ד ז) \"מִזְבַּח קְטֹרֶת הַסַּמִּים\":","חִסֵּר מִן הַקְּטֹרֶת אֶחָד מִסַּמָּנֶיהָ אוֹ מַעֲלֶה עָשָׁן חַיָּב מִיתָה עָלֶיהָ שֶׁנֶּאֱמַר (ויקרא טז ב) \"וְלֹא יָמוּת כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת\". וְכֵן חַיָּב מִיתָה עַל בִּיאָתוֹ בְּלֹא מִצְוָה. לְפִיכָךְ אִם שָׁגַג בְּבִיאָה וְהֵזִיד בִּקְטֹרֶת. אוֹ שֶׁנִּכְנַס בִּקְטֹרֶת שְׁלֵמָה עִם הַחֲסֵרָה חַיָּב מִיתָה:","הִקְטִיר מִן הַקְּטֹרֶת שֶׁל קֹדֶשׁ הַקָּדָשִׁים כְּזַיִת בַּהֵיכָל חַיָּב מִיתָה:","חֲפִינַת הַקְּטֹרֶת עֲבוֹדָה. וְהַמַּחְשָׁבָה פּוֹסֶלֶת בָּהּ. וְכֵן חֲתִיַּת הַגֶּחָלִים לַקְּטֹרֶת נִפְסֶלֶת בְּמַחְשָׁבָה. שֶׁמַּכְשִׁירֵי קָרְבָּן כְּקָרְבָּן:","חָפַן בְּרָאשֵׁי אֶצְבְּעוֹתָיו אוֹ מִן הַצְּדָדִין אוֹ מִמַּטָּה לְמַעְלָה אוֹ שֶׁחָפַן בְּיָדוֹ זוֹ וּבְיָדוֹ זוֹ וְקָרַב זוֹ לָזוֹ. אוֹ שֶׁנִּתְפַּזְּרָה קְטֹרֶת מִיָּדוֹ עַל הָאָרֶץ וַאֲסָפָהּ. אוֹ שֶׁחָפַן חֲבֵרוֹ וְנָתַן לְחָפְנָיו. אוֹ שֶׁחָפַן וּמֵת וְנִכְנַס שֵׁנִי בְּמַה שֶּׁחָפַן רִאשׁוֹן. כָּל אֵלּוּ סָפֵק וְלֹא יַקְטִיר וְאִם הִקְטִיר הֻרְצָה:"],"Mishneh Torah, Shofar, Sukkah and Lulav 8":["אַרְבַעַת מִינִין הָאֵלּוּ שֶׁהֵן לוּלָב וַהֲדַס וַעֲרָבָה וְאֶתְרוֹג שֶׁהָיָה אֶחָד מֵהֶן יָבֵשׁ אוֹ גָּזוּל אוֹ גָּנוּב אֲפִלּוּ לְאַחַר יֵאוּשׁ אוֹ שֶׁיִּהְיֶה מֵאֲשֵׁרָה הַנֶּעֱבֶדֶת אַף עַל פִּי שֶׁבִּטְּלוּ הָאֲשֵׁרָה מִלְּעָבְדָהּ. אוֹ שֶׁהָיָה שֶׁל עִיר הַנִּדַּחַת. הֲרֵי זֶה פָּסוּל. הָיָה אֶחָד מֵהֶן שֶׁל עֲבוֹדַת כּוֹכָבִים לֹא יִטּל לְכַתְּחִלָּה וְאִם נָטַל יָצָא. הָיָה כָּמוּשׁ וְלֹא גָּמַר לִיבַשׁ כָּשֵׁר. וּבִשְׁעַת הַדְּחָק אוֹ בִּשְׁעַת הַסַּכָּנָה לוּלָב הַיָּבֵשׁ כָּשֵׁר אֲבָל לֹא שְׁאָר הַמִּינִין:","אֶתְרוֹג שֶׁל עָרְלָה וְשֶׁל תְּרוּמָה טְמֵאָה וְשֶׁל טֶבֶל פָּסוּל. שֶׁל דְּמַאי כָּשֵׁר שֶׁאֶפְשָׁר שֶׁיַּפְקִיר נְכָסָיו וְיִהְיֶה עָנִי שֶׁמֻּתָּר לוֹ לֶאֱכל דְּמַאי. אֶתְרוֹג שֶׁל תְּרוּמָה טְהוֹרָה וְשֶׁל מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם לֹא יִטּל שֶׁמָּא יַכְשִׁירוֹ לְטֻמְאָה. וְאִם נָטַל כָּשֵׁר:","לוּלָב שֶׁנִּקְטַם רֹאשׁוֹ פָּסוּל. נִסְדַּק אִם נִתְרַחֲקוּ שְׁנֵי סְדָקָיו זֶה מִזֶּה עַד שֶׁיֵּרָאוּ כִּשְׁנַיִם פָּסוּל. הָיָה עָקוּם לְפָנָיו שֶׁהֲרֵי שְׁדֵרוֹ כְּגַב בַּעַל חֲטוֹטֶרֶת פָּסוּל. הָיָה עָקוּם לַאֲחוֹרָיו כָּשֵׁר שֶׁזּוֹ הִיא בְּרִיָּתוֹ. נֶעֱקַם לְאֶחָד מִצְּדָדָיו פָּסוּל. נִפְרְדוּ עָלָיו זֶה מֵעַל זֶה וְלֹא נִדַּלְדְּלוּ כַּעֲלֵי הַחֲרָיוֹת כָּשֵׁר. נִפְרְצוּ עָלָיו וְהוּא שֶׁיִּדַּלְדְּלוּ מִשְּׁדֵרוֹ שֶׁל לוּלָב כַּעֲלֵי הַחֲרָיוֹת פָּסוּל:","בְּרִיַּת עָלִין שֶׁל לוּלָב כָּךְ הִיא. כְּשֶׁהֵם גְּדֵלִין גְּדֵלִין שְׁנַיִם שְׁנַיִם וּדְבוּקִין מִגַּבָּן וְגַב כָּל שְׁנֵי עָלִין הַדְּבוּקִין הוּא הַנִּקְרָא תְּיֹמֶת. נֶחְלְקָה הַתְּיֹמֶת פָּסוּל. הָיוּ עָלָיו אַחַת אַחַת מִתְּחִלַּת בְּרִיָּתוֹ ולֹא הָיָה לָהֶם תְּיֹמֶת פָּסוּל. לֹא הָיוּ עָלָיו זֶה עַל גַּב זֶה כְּדֶרֶךְ כָּל הַלּוּלָבִין אֶלָּא זֶה תַּחַת זֶה אִם רֹאשׁ זֶה מַגִּיעַ לָעִקָּר שֶׁלְּמַעְלָה מִמֶּנּוּ עַד שֶׁנִּמְצָא כָּל שְׁדֵרוֹ שֶׁל לוּלָב מְכֻסֶּה בְּעָלִין כָּשֵׁר. וְאִם אֵין רֹאשׁוֹ שֶׁל זֶה מַגִּיעַ לְצַד עִקָּרוֹ שֶׁל זֶה פָּסוּל:","הֲדַס שֶׁנִּקְטַם רֹאשׁוֹ כָּשֵׁר. נָשְׁרוּ רֹב עָלָיו אִם נִשְׁתַּיְּרוּ שְׁלֹשָׁה עָלִין בְּקֵן אֶחָד כָּשֵׁר. הָיוּ עֲנָבָיו מְרֻבּוֹת מֵעָלָיו אִם יְרֻקּוֹת כָּשֵׁר וְאִם אֲדֻמּוֹת אוֹ שְׁחוֹרוֹת פָּסוּל. וְאִם מִעֲטָן כָּשֵׁר. וְאֵין מְמַעֲטִין אוֹתָן בְּיוֹם טוֹב לְפִי שֶׁהוּא כִּמְתַקֵּן. עָבַר וְלִקְּטָן אוֹ שֶׁלִּקְּטָן אֶחָד אֶחָד לַאֲכִילָה הֲרֵי זֶה כָּשֵׁר:","עֲרָבָה שֶׁנִּקְטַם רֹאשָׁהּ כְּשֵׁרָה. נִפְרְצוּ עָלֶיהָ פְּסוּלָה:","אֶתְרוֹג שֶׁנִּקַּב נֶקֶב מְפֻלָּשׁ כָּל שֶׁהוּא פָּסוּל. וְשֶׁאֵינוֹ מְפֻלָּשׁ אִם הָיָה כְּאִיסָר אוֹ יֶתֶר פָּסוּל. חָסֵר כָּל שֶׁהוּא פָּסוּל. נִטַּל דָּדוֹ וְהוּא הָרֹאשׁ הַקָּטָן שֶׁשּׁוֹשַׁנְתּוֹ בּוֹ פָּסוּל. נִטַּל הָעֵץ שֶׁהוּא תָּלוּי בּוֹ בָּאִילָן מֵעִקַּר הָאֶתְרוֹג וְנִשְׁאַר מְקוֹמוֹ גּוּמָא פָּסוּל. עָלְתָה חֲזָזִית עָלָיו אִם בִּשְׁנַיִם וּשְׁלֹשָׁה מְקוֹמוֹת פָּסוּל. וְאִם בְּמָקוֹם אֶחָד אִם עָלְתָה עַל רֻבּוֹ פָּסוּל. וְאִם עַל דָּדוֹ וַאֲפִלּוּ כָּל שֶׁהוּא פָּסוּל. נִקְלַף הַקְּרוּם הַחִיצוֹנָה שֶׁלּוֹ שֶׁאֵינוֹ מְחַסְּרוֹ אֶלָּא נִשְׁאָר יָרֹק כְּמוֹת שֶׁהִיא בְּרִיָּתוֹ אִם נִקְלַף כֻּלּוֹ פָּסוּל וְאִם נִשְׁאַר מִמֶּנּוּ כָּל שֶׁהוּא כָּשֵׁר:","אֶתְרוֹג שֶׁהוּא תָּפוּחַ סָרוּחַ כָּבוּשׁ שָׁלוּק שָׁחֹר לָבָן מְנֻמָּר יָרֹק כְּכַרְתִּי פָּסוּל. גִּדְּלוֹ בִּדְפוּס וְעָשָׂהוּ כְּמִין בְּרִיָּה אַחֶרֶת פָּסוּל. עָשָׂהוּ כְּמִין בְּרִיָּתוֹ אַף עַל פִּי שֶׁעָשָׂהוּ דַּפִּין דַּפִּין כָּשֵׁר. הַתִּיוֹם וְהַבֹּסֶר כָּשֵׁר. מָקוֹם שֶׁהָאֶתְרוֹגִין שֶׁלָּהֶם כְּעֵין שַׁחֲרוּת מְעוּטָה כְּשֵׁרִין. וְאִם הָיוּ שְׁחוֹרִים בְּיוֹתֵר כְּאָדָם כּוּשִׁי הֲרֵי זֶה פָּסוּל בְּכָל מָקוֹם:","כָּל אֵלּוּ שֶׁאָמַרְנוּ שֶׁהֵם פְּסוּלִין מִפְּנֵי מוּמִין שֶׁבֵּאַרְנוּ אוֹ מִפְּנֵי גֵּזֶל וּגְנֵבָה בְּיוֹם טוֹב רִאשׁוֹן בִּלְבַד אֲבָל בְּיוֹם טוֹב שֵׁנִי עִם שְׁאָר הַיָּמִים הַכּל כָּשֵׁר. וְהַפַּסְלָנוּת שֶׁהוּא מִשּׁוּם עֲבוֹדַת כּוֹכָבִים אוֹ מִפְּנֵי שֶׁאוֹתוֹ אֶתְרוֹג אָסוּר בַּאֲכִילָה בֵּין בְּיוֹם טוֹב רִאשׁוֹן בֵּין בִּשְׁאָר יָמִים פָּסוּל:","אֵין אָדָם יוֹצֵא בְּיוֹם טוֹב רִאשׁוֹן שֶׁל חַג בְּלוּלָבוֹ שֶׁל חֲבֵרוֹ שֶׁיִּשְׁאָלֶנּוּ מִמֶּנּוּ עַד שֶׁיִּתְּנֶנּוּ לוֹ בְּמַתָּנָה. נְתָנוֹ לוֹ עַל מְנָת לְהַחֲזִירוֹ הֲרֵי זֶה יוֹצֵא בּוֹ יְדֵי חוֹבָתוֹ וּמַחֲזִירוֹ. שֶׁמַּתָּנָה עַל מְנָת לְהַחֲזִיר שְׁמָהּ מַתָּנָה. וְאִם לֹא הֶחְזִירוֹ לֹא יָצָא שֶׁנִּמְצָא כְּגָזוּל. וְאֵין נוֹתְנִין אוֹתוֹ לְקָטָן שֶׁהַקָּטָן קוֹנֶה וְאֵינוֹ מַקְנֶה לַאֲחֵרִים מִן הַתּוֹרָה וְנִמְצָא שֶׁאִם הֶחְזִירוֹ לוֹ אֵינוֹ חוֹזֵר. וְאֶחָד הַלּוּלָב וְאֶחָד כָּל מִין וָמִין מֵאַרְבַּע מִינִין שֶׁבּוֹ אִם הָיָה אֶחָד מֵהֶן שָׁאוּל אֵין יוֹצְאִין בּוֹ בְּיוֹם טוֹב רִאשׁוֹן:","שֻׁתָּפִין שֶׁקָּנוּ לוּלָב אוֹ אֶתְרוֹג בְּשֻׁתָּפוּת אֵין אֶחָד מֵהֶן יוֹצֵא בּוֹ יְדֵי חוֹבָתוֹ בָּרִאשׁוֹן עַד שֶׁיִּתֵּן לוֹ חֶלְקוֹ בְּמַתָּנָה. הָאַחִין שֶׁקָּנוּ אֶתְרוֹגִין מִתְּפִיסַת הַבַּיִת וְנָטַל אֶחָד מֵהֶן אֶתְרוֹג וְיָצָא בּוֹ. אִם יָכוֹל לְאָכְלוֹ וְאֵין הָאַחִין מַקְפִּידִין בְּכָךְ יָצָא. וְאִם הָיוּ מַקְפִּידִין לֹא יָצָא עַד שֶׁיִּתְּנוּ לוֹ חֶלְקָם בְּמַתָּנָה. וְאִם קָנָה זֶה אֶתְרוֹג וְזֶה פָּרִישׁ אוֹ שֶׁקָּנוּ כְּאֶחָד אֶתְרוֹג וְרִמּוֹן וּפָרִישׁ מִתְּפִיסַת הַבַּיִת אֵינוֹ יוֹצֵא בָּאֶתְרוֹג עַד שֶׁיִּתֵּן לוֹ חֶלְקוֹ בְּמַתָּנָה וְאַף עַל פִּי שֶׁאִם אֲכָלוֹ אֵין מַקְפִּידִין עָלָיו:","אַף עַל פִּי שֶׁכָּל הַמּוֹעֲדוֹת מִצְוָה לִשְׂמֹחַ בָּהֶן. בְּחַג הַסֻּכּוֹת הָיְתָה בַּמִּקְדָּשׁ יוֹם שִׂמְחָה יְתֵרָה שֶׁנֶּאֱמַר (ויקרא כג מ) \"וּשְׂמַחְתֶּם לִפְנֵי ה' אֱלֹהֵיכֶם שִׁבְעַת יָמִים\". וְכֵיצַד הָיוּ עוֹשִׂין. עֶרֶב יוֹם טוֹב הָרִאשׁוֹן הָיוּ מְתַקְּנִין בַּמִּקְדָּשׁ מָקוֹם לַנָּשִׁים מִלְּמַעְלָה וְלָאֲנָשִׁים מִלְּמַטָּה כְּדֵי שֶׁלֹּא יִתְעָרְבוּ אֵלּוּ עִם אֵלּוּ. וּמַתְחִילִין לִשְׂמֹחַ מִמּוֹצָאֵי יוֹם טוֹב הָרִאשׁוֹן. וְכֵן בְּכָל יוֹם וְיוֹם מִימֵי חֻלּוֹ שֶׁל מוֹעֵד מַתְחִילִין מֵאַחַר שֶׁיַּקְרִיבוּ תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם לִשְׂמֹחַ לִשְׁאָר הַיּוֹם עִם כָּל הַלַּיְלָה:","וְהֵיאַךְ הָיְתָה שִׂמְחָה זוֹ. הֶחָלִיל מַכֶּה וּמְנַגְּנִין בְּכִנּוֹר וּבִנְבָלִים וּבִמְצִלְתַּיִם וְכָל אֶחָד וְאֶחָד בִּכְלֵי שִׁיר שֶׁהוּא יוֹדֵעַ לְנַגֵּן בּוֹ. וּמִי שֶׁיּוֹדֵעַ בַּפֶּה בַּפֶּה. וְרוֹקְדִין וּמְסַפְּקִין וּמְטַפְּחִין וּמְפַזְּזִין וּמְכַרְכְּרִין כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁיּוֹדֵעַ וְאוֹמְרִים דִּבְרֵי שִׁירוֹת וְתֻשְׁבָּחוֹת. וְשִׂמְחָה זוֹ אֵינָהּ דּוֹחָה לֹא אֶת הַשַּׁבָּת וְלֹא אֶת יוֹם טוֹב:","מִצְוָה לְהַרְבּוֹת בְּשִׂמְחָה זוֹ. וְלֹא הָיוּ עוֹשִׂין אוֹתָהּ עַמֵּי הָאָרֶץ וְכָל מִי שֶׁיִּרְצֶה. אֶלָּא גְּדוֹלֵי חַכְמֵי יִשְׂרָאֵל וְרָאשֵׁי הַיְשִׁיבוֹת וְהַסַּנְהֶדְרִין וְהַחֲסִידִים וְהַזְּקֵנִים וְאַנְשֵׁי מַעֲשֶׂה הֵם שֶׁהָיוּ מְרַקְּדִין וּמְסַפְּקִין וּמְנַגְּנִין וּמְשַׂמְּחִין בַּמִּקְדָּשׁ בִּימֵי חַג הַסֻּכּוֹת. אֲבָל כָּל הָעָם הָאֲנָשִׁים וְהַנָּשִׁים כֻּלָּן בָּאִין לִרְאוֹת וְלִשְׁמֹעַ:","הַשִּׂמְחָה שֶׁיִּשְׂמַח אָדָם בַּעֲשִׂיַּת הַמִּצְוָה וּבְאַהֲבַת הָאֵל שֶׁצִּוָּה בָּהֶן. עֲבוֹדָה גְּדוֹלָה הִיא. וְכָל הַמּוֹנֵעַ עַצְמוֹ מִשִּׂמְחָה זוֹ רָאוּי לְהִפָּרַע מִמֶּנּוּ שֶׁנֶּאֱמַר (דברים כח מז) \"תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה' אֱלֹהֶיךָ בְּשִׂמְחָה וּבְטוּב לֵבָב\". וְכָל הַמֵּגִיס דַּעְתּוֹ וְחוֹלֵק כָּבוֹד לְעַצְמוֹ וּמִתְכַּבֵּד בְּעֵינָיו בִּמְקוֹמוֹת אֵלּוּ חוֹטֵא וְשׁוֹטֶה. וְעַל זֶה הִזְהִיר שְׁלֹמֹה וְאָמַר (משלי כה ו) \"אַל תִּתְהַדַּר לִפְנֵי מֶלֶךְ\". וְכָל הַמַּשְׁפִּיל עַצְמוֹ וּמֵקֵל גּוּפוֹ בִּמְקוֹמוֹת אֵלּוּ הוּא הַגָּדוֹל הַמְכֻבָּד הָעוֹבֵד מֵאַהֲבָה. וְכֵן דָּוִד מֶלֶךְ יִשְׂרָאֵל אָמַר (שמואל ב ו כב) \"וּנְקַלֹּתִי עוֹד מִזֹּאת וְהָיִיתִי שָׁפָל בְּעֵינָי\". וְאֵין הַגְּדֻלָּה וְהַכָּבוֹד אֶלָּא לִשְׂמֹחַ לִפְנֵי ה' שֶׁנֶּאֱמַר (שמואל ב ו טז) \"וְהַמֶּלֶךְ דָּוִד מְפַזֵּז וּמְכַרְכֵּר לִפְנֵי ה'\": סָלִיק הִלְכוֹת שׁוֹפָּר סֻכָּה וְלוּלָב"],"Mishneh Torah, Substitution 3":["כֵּיצַד דִּין הַתְּמוּרוֹת לִקָּרֵב. תְּמוּרַת הָעוֹלָה תִּקָּרֵב עוֹלָה וְאִם הָיְתָה תְּמוּרָתָהּ נְקֵבָה אוֹ בַּעֲלַת מוּם תִּרְעֶה הַנְּקֵבָה עַד שֶׁיִּפּל בָּהּ מוּם וְתִמָּכֵר וְיָבִיא בְּדָמֶיהָ עוֹלָה. תְּמוּרַת הַחַטָּאת תָּמוּת כְּמוֹ שֶׁבֵּאַרְנוּ בִּפְסוּלֵי הַמֻּקְדָּשִׁין. תְּמוּרַת הָאָשָׁם תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְיִפְּלוּ דָּמֶיהָ לִנְדָבָה. תְּמוּרַת הַשְּׁלָמִים כִּשְׁלָמִים לְכָל דָּבָר טְעוּנָה סְמִיכָה וּנְסָכִים וּתְנוּפַת חָזֶה וְשׁוֹק. תְּמוּרַת הַתּוֹדָה כְּתוֹדָה אֶלָּא שֶׁאֵינָהּ טְעוּנָה לֶחֶם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין. תְּמוּרַת הַפֶּסַח אִם הֵמִיר בָּהּ קֹדֶם חֲצוֹת יוֹם אַרְבָּעָה עָשָׂר אֵין תְּמוּרָתוֹ קְרֵבָה אֶלָּא תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְיָבִיא בְּדָמֶיהָ שְׁלָמִים וְאִם הֵמִיר בָּהּ אַחַר חֲצוֹת הֲרֵי הַתְּמוּרָה עַצְמָהּ תִּקָּרֵב שְׁלָמִים. תְּמוּרַת הַבְּכוֹר וְהַמַּעֲשֵׂר אֵינָם קְרֵבִין לְעוֹלָם שֶׁנֶּאֱמַר בִּבְכוֹר (ויקרא כז כו) (ויקרא כז ל) \"לַה' הוּא\". מִפִּי הַשְּׁמוּעָה לָמְדוּ הוּא קָרֵב וְאֵין תְמוּרָתוֹ קְרֵבָה. וְדִין הַמַּעֲשֵׂר בִּבְכוֹר תְּמוּרָתָן תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְתֵאָכֵל:","תְּמוּרַת הַבְּכוֹר לַכֹּהֲנִים וּתְמוּרַת הַמַּעֲשֵׂר לַבְּעָלִים. וּכְשֵׁם שֶׁאֵין פּוֹדִין בְּכוֹר וּמַעֲשֵׂר שֶׁנָּפַל בָּהֶן מוּם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מִזְבֵּחַ כָּךְ אֵין פּוֹדִים תְּמוּרָתָן:","בְּהֵמָה שֶׁהִקְדִּישָׁהּ חֶצְיָהּ עוֹלָה וְחֶצְיָהּ שְׁלָמִים תְּמוּרָתָהּ כָּמוֹהָ. וְכֵן כָּל בֶּהֱמַת הֶקְדֵּשׁ שֶׁאֵינָהּ קְרֵבָה מִפְּנֵי תְּחִלַּת הֶקְדֵּשָׁהּ הֲרֵי תְּמוּרָתָהּ כָּמוֹהָ. אָמַר חֲצִי בְּהֵמָה זוֹ תְּמוּרָה וְחֶצְיָהּ עוֹלָה הֲרֵי זוֹ תִּקָּרֵב עוֹלָה. חֶצְיָהּ עוֹלָה וְחֶצְיָהּ מַעֲשֵׂר תִּקָּרֵב עוֹלָה. חֶצְיָהּ תְּמוּרָה וְחֶצְיָהּ מַעֲשֵׂר הֲרֵי זוֹ סָפֵק וְאֵינָהּ קְרֵבָה:","הַמַּקְדִּישׁ בַּעֲלַת מוּם עוֹבֵר וְאֵין צָרִיךְ לוֹמַר תְּמִימָה וְאַחַר כָּךְ נוֹלַד בָּהּ מוּם קָבוּעַ וְנִפְדֵּית וְהֵמִיר בָּהּ אַחַר שֶׁנִּפְדֵּית. הֲרֵי זוֹ תְּמוּרָה וְאֵינָהּ קְרֵבָה וְאֵינָהּ נִפְדֵּית אֶלָּא מַנִּיחָהּ עַד שֶׁתָּמוּת. אֵינָהּ קְרֵבָה מִפְּנֵי שֶׁבָּאָה מִכֹּחַ קְדֻשָּׁה דְּחוּיָה וְאֵינָהּ נִפְדֵּית שֶׁאֵין בְּכֹחַ קְדֻשָּׁתָהּ לִתְפּשֹׁ פִּדְיוֹנָהּ:","כָּל הַתְּמוּרוֹת שֶׁהָיוּ בַּעֲלֵי מוּמִין קְבוּעִין מִתְּחִלָּתָן הֲרֵי אֵלּוּ יִפָּדוּ וְאֵינָן יוֹצְאִין לְחֻלִּין לְכָל דָּבָר כְּדֵי שֶׁיִּהְיוּ מֻתָּרִין בְּגִזָּה וַעֲבוֹדָה אַחַר פִּדְיוֹנָן. שֶׁהַקְּדֻשָּׁה חָלָה בַּתְּמוּרָה עַל בַּעֲלַת מוּם קָבוּעַ שֶׁנֶּאֱמַר (ויקרא כז י) \"אוֹ רַע בְּטוֹב\" וְרַע הָאָמוּר כָּאן הוּא בַּעַל מוּם וְכַיּוֹצֵא בּוֹ שֶׁאֵינוֹ רָאוּי לְקָרְבָּן וְאַף עַל פִּי כֵן כָּתוּב בּוֹ (ויקרא כז י) \"יִהְיֶה קֹדֶשׁ\":","עוֹלָה שֶׁנִּתְעָרְבָה בִּזְבָחִים וְהֵמִיר בְּאַחַת מִן הַתַּעֲרוֹבוֹת הֲרֵי זֶה מֵבִיא בְּהֵמָה אַחֶרֶת וְאוֹמֵר אִם תְּמוּרַת עוֹלָה הִיא זוֹ הֲרֵי בְּהֵמָה זוֹ שְׁלָמִים וְאִם תְּמוּרַת שְׁלָמִים הִיא זוֹ הֲרֵי בְּהֵמָה זוֹ עוֹלָה. וְנִמְצָא הַבְּהֵמָה שֶׁהֵבִיא עִם הַתְּמוּרָה כְּעוֹלָה וּשְׁלָמִים שֶׁנִּתְעָרְבוּ זֶה בָּזֶה. חָזַר וְהֵמִיר בְּאַחַת מִשְּׁתֵּיהֶן וְאֵין יָדוּעַ בְּאֵי זוֹ מֵהֶן הֵמִיר. מֵבִיא זֶבַח אַחֵר מִתּוֹךְ בֵּיתוֹ. וְאוֹמֵר עַל הַתְּמוּרָה הַשְּׁנִיָּה. אִם תְּמוּרַת תְּמוּרָה הִיא זוֹ הֲרֵי זוֹ שֶׁהֵבִיא חֻלִּין. וְאִם תְּמוּרַת עוֹלָה אוֹ שְׁלָמִים הִיא הֲרֵי זֶה שֶׁהֵבִיא עוֹלָה אוֹ שְׁלָמִים. וַהֲרֵי זֶה שֶׁהֵבִיא עִם הַתְּמוּרָה הַשְּׁנִיָּה כְּזֶבַח וּתְמוּרָה שֶׁנִּתְעָרְבוּ זֶה בָּזֶה. וּכְבָר בֵּאַרְנוּ דִּין הַתַּעֲרוֹבוֹת בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין:","שְׁלָמִים שֶׁנִּתְעָרְבוּ בִּבְכוֹר אוֹ בְּמַעֲשֵׂר וְהֵמִיר בְּאֶחָד מֵהֶן הֲרֵי זֶה לֹא יִקְרַב אֶלָּא יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִפָּדֶה וְיֵאָכֵל כִּבְכוֹר אוֹ כְּמַעֲשֵׂר כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Testimony 1":["הָעֵד מְצֻוֶּה לְהָעִיד בְּבֵית דִּין בְּכָל עֵדוּת שֶׁיּוֹדֵעַ. בֵּין בְּעֵדוּת שֶׁיְּחַיֵּב בָּהּ אֶת חֲבֵרוֹ בֵּין בְּעֵדוּת שֶׁיְּזַכֵּהוּ בּוֹ. וְהוּא שֶׁיִּתְבָּעֶנּוּ לְהָעִיד בְּדִינֵי מָמוֹנוֹת שֶׁנֶּאֱמַר (ויקרא ה א) \"וְהוּא עֵד אוֹ רָאָה אוֹ יָדָע אִם לוֹא יַגִּיד וְנָשָׂא עֲוֹנוֹ\":","הָיָה הָעֵד חָכָם גָּדוֹל וְהָיָה בְּבֵית דִּין פָּחוּת מִמֶּנּוּ בְּחָכְמָה. הוֹאִיל וְאֵין כְּבוֹדוֹ שֶׁיֵּלֵךְ לִפְנֵיהֶם עֲשֵׂה שֶׁל כְּבוֹד תּוֹרָה עָדִיף וְיֵשׁ לוֹ לְהִמָּנַע. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעֵדוּת מָמוֹן. אֲבָל בְּעֵדוּת שֶׁמַּפְרִישׁ בָּהּ מִן הָאִסּוּר וְכֵן בְּעֵדוּת נְפָשׁוֹת אוֹ מַכּוֹת הוֹלֵךְ וּמֵעִיד שֶׁנֶּאֱמַר (גמרא ברכות יט ב) \"אֵין חָכְמָה וְאֵין תְּבוּנָה לְנֶגֶד ה'\". כָּל מָקוֹם שֶׁיֵּשׁ חִלּוּל הַשֵּׁם אֵין חוֹלְקִין כָּבוֹד לָרַב:","כֹּהֵן גָּדוֹל אֵינוֹ חַיָּב לְהָעִיד אֶלָּא עֵדוּת שֶׁהִיא לְמֶלֶךְ יִשְׂרָאֵל בִּלְבַד. הוֹלֵךְ לְבֵית דִּין הַגָּדוֹל וּמֵעִיד בָּהּ. אֲבָל בִּשְׁאָר הָעֵדֻיּוֹת פָּטוּר:","מִצְוַת עֲשֵׂה לִדְרשׁ אֶת הָעֵדִים וּלְחָקְרָן וּלְהַרְבּוֹת בִּשְׁאֵלָתָן וּמְדַקְדְּקִין עֲלֵיהֶן וּמַסִּיעִין אוֹתָן מֵעִנְיָן לְעִנְיָן בְּעֵת הַשְּׁאֵלָה כְּדֵי שֶׁיִּשְׁתְּקוּ אוֹ יַחְזְרוּ בָּהֶן אִם יֵשׁ בְּעֵדוּתָן דֹּפִי. שֶׁנֶּאֱמַר (דברים יג טו) \"וְדָרַשְׁתָּ וְחָקַרְתָּ וְשָׁאַלְתָּ הֵיטֵב\". וּצְרִיכִין הַדַּיָּנִים לְהִזָּהֵר בְּעֵת חֲקִירַת הָעֵדִים [שֶׁמָּא מִתּוֹכָהּ יִלְמְדוּ לְשַׁקֵּר. וּבְשֶׁבַע חֲקִירוֹת בּוֹדְקִין אוֹתָם]. בְּאֵי זוֹ שָׁבוּעַ. בְּאֵי זוֹ שָׁנָה. בְּאֵי זֶה חֹדֶשׁ. בְּכַמָּה בְּחֹדֶשׁ. בְּאֵי זֶה יוֹם מִימֵי הַשַּׁבָּת. וּבְכַמָּה שָׁעוֹת בַּיּוֹם. וּבְאֵי זֶה מָקוֹם. אֲפִלּוּ אָמַר הַיּוֹם הֲרָגוֹ אוֹ אֶמֶשׁ הֲרָגוֹ שׁוֹאֲלִין לָהֶן בְּאֵי זֶה שָׁבוּעַ בְּאֵי זוֹ שָׁנָה בְּאֵי זֶה חֹדֶשׁ בְּכַמָּה בַּחֹדֶשׁ בְּאֵי זֶה יוֹם בְּאֵי זוֹ שָׁעָה. וּמִכְּלַל הַחֲקִירוֹת יֶתֶר עַל הַשֶּׁבַע הַשָּׁווֹת בַּכּל שֶׁאִם הֵעִידוּ עָלָיו שֶׁעָבַד עֲבוֹדָה זָרָה שׁוֹאֲלִין לָהֶן אֶת מֶה עָבַד וּבְאֵי זוֹ עֲבוֹדָה עָבַד. הֵעִידוּ שֶׁחִלֵּל אֶת הַשַּׁבָּת שׁוֹאֲלִין אוֹתָן אֵי זוֹ מְלָאכָה עָשָׂה וְהֵיאַךְ עָשָׂה. הֵעִידוּ שֶׁאָכַל בְּיוֹם הַכִּפּוּרִים שׁוֹאֲלִין אוֹתָן אֵי זֶה מַאֲכָל אָכַל וְכַמָּה אָכַל. הֵעִידוּ שֶׁהָרַג אֶת הַנֶּפֶשׁ שׁוֹאֲלִין אוֹתָן בַּמֶּה הֲרָגוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה הֲרֵי הוּא מִכְּלַל הַחֲקִירוֹת:","הַחֲקִירוֹת וְהַדְּרִישׁוֹת הֵן הַדְּבָרִים שֶׁהֵן עִקַּר הָעֵדוּת וּבָהֶן יִתְחַיֵּב אוֹ יִפָּטֵר. וְהֵן כַּוָּנַת הַמַּעֲשֶׂה שֶׁעָשָׂה וְכִוּוּן הַזְּמַן וְכִוּוּן הַמָּקוֹם שֶׁבָּהֶן יָזֹמּוּ הָעֵדִים אוֹ לֹא יָזֹמּוּ. שֶׁאֵין אָנוּ יְכוֹלִים לְהָזִים הָעֵדִים עַד שֶׁיְּכַוְּנוּ הַזְּמַן וְהַמָּקוֹם:","וְעוֹד מַרְבִּין לִבְדֹּק הָעֵדִים בִּדְבָרִים שֶׁאֵינָן עִקָּר בָּעֵדוּת וְאֵינָהּ תְּלוּיָה בָּהֶם. וְהֵם הַנִּקְרָאִים בְּדִיקוֹת. וְכָל הַמַּרְבֶּה בִּבְדִיקוֹת הֲרֵי זֶה מְשֻׁבָּח. כֵּיצַד הֵן הַבְּדִיקוֹת. הֲרֵי שֶׁהֵעִידוּ עָלָיו שֶׁהָרַג וְנֶחְקְרוּ בְּשֶׁבַע חֲקִירוֹת שֶׁמָּנִינוּ. שֶׁהֵן בְּכַוָּנַת הַזְּמַן וְכַוָּנַת הַמָּקוֹם. וְנִדְרְשׁוּ בְּכַוָּנַת הַמַּעֲשֶׂה וְכִוְּנוּ הַמַּעֲשֶׂה וְכִוְּנוּ הַכְּלִי שֶׁהֲרָגוֹ בּוֹ. בּוֹדְקִין אוֹתָן עוֹד וְאוֹמְרִים לָהֶן מֶה הָיָה לְבוּשׁ הַנֶּהֱרָג אוֹ הַהוֹרֵג. בְּגָדִים לְבָנִים אוֹ שְׁחוֹרִים. עֲפַר הָאָרֶץ שֶׁנֶּהֱרַג עָלֶיהָ לָבָן אוֹ אָדֹם. אֵלּוּ וְכַיּוֹצֵא בָּהֶן הֵם הַבְּדִיקוֹת. מַעֲשֶׂה שֶׁאָמְרוּ הָעֵדִים הֲרָגוֹ בְּמָקוֹם פְּלוֹנִי תַּחַת הַתְּאֵנָה וּבָדְקוּ הָעֵדִים וְאָמְרוּ לָהֶם תְּאֵנִים שֶׁלָּהּ שְׁחוֹרוֹת הָיוּ אוֹ לְבָנוֹת עֻקְצִין שֶׁל אוֹתָם הַתְּאֵנִים אֲרֻכּוֹת הָיוּ אוֹ קְצָרוֹת. וְכָל הַמַּרְבֶּה בִּבְדִיקוֹת וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה מְשֻׁבָּח:"],"Mishneh Torah, Testimony 20":["אֵין עֵדִים זוֹמְמִין נֶהֱרָגִין וְלֹא לוֹקִין וְלֹא מְשַׁלְּמִין עַד שֶׁיִּהְיוּ שְׁנֵיהֶם רְאוּיִין לְעֵדוּת וְיִזּוֹמוּ שְׁנֵיהֶם אַחַר שֶׁנִּגְמַר הַדִּין. אֲבָל אִם הוּזַם אֶחָד מֵהֶן בִּלְבַד אוֹ שֶׁהוּזַמּוּ שְׁנֵיהֶם קֹדֶם גְּמַר דִּין אוֹ אַחַר גְּמַר דִּין וְנִמְצָא אֶחָד מֵהֶן קָרוֹב אוֹ פָּסוּל אֵין נֶעֱנָשִׁין אַף עַל פִּי שֶׁהוּזַמּוּ וְנִפְסְלוּ לְכָל עֵדוּת שֶׁבַּתּוֹרָה:","נֶהֱרַג זֶה שֶׁהֵעִידוּ עָלָיו וְאַחַר כָּךְ הוּזַמּוּ אֵינָן נֶהֱרָגִין מִן הַדִּין. שֶׁנֶּאֱמַר (דברים יט יט) \"כַּאֲשֶׁר זָמַם לַעֲשׂוֹת\" וַעֲדַיִן לֹא עָשָׂה. וְדָבָר זֶה מִפִּי הַקַּבָּלָה. אֲבָל אִם לָקָה זֶה שֶׁהֵעִידוּ עָלָיו לוֹקִין. וְכֵן אִם יָצָא הַמָּמוֹן מִיַּד זֶה לְיַד זֶה בְּעֵדוּתָן חוֹזֵר לִבְעָלָיו וּמְשַׁלְּמִין לוֹ:","הָיוּ הָעֵדִים שְׁלֹשָׁה אֲפִלּוּ מֵאָה אִם הֵעִידוּ בְּבֵית דִּין זֶה אַחַר זֶה וְהֵעִיד כָּל אֶחָד מֵהֶן אַחַר חֲבֵרוֹ בְּתוֹךְ כְּדֵי דִּבּוּר וְהוּזַמּוּ מִקְצָתָן אֵין נֶעֱנָשִׁין עַד שֶׁיּוּזַמּוּ כֻּלָּן. אֲבָל אִם הָיָה הֶפְסֵק בֵּין זֶה לָזֶה יֶתֶר מִכְּדֵי דִּבּוּר שֶׁהוּא כְּדֵי שְׁאֵלַת שָׁלוֹם תַּלְמִיד לְרַב. הֲרֵי נֶחְלְקָה הָעֵדוּת וְהַשְּׁנַיִם שֶׁהוּזַמּוּ נֶעֱנָשִׁין וְהַשְּׁנַיִם הָאֲחֵרִים שֶׁהָיָה בֵּין דִּבְרֵיהֶן וְדִבְרֵי הָרִאשׁוֹנִים הֶפְסֵק אֵין נֶעֱנָשִׁין. וְאַף עַל פִּי שֶׁבָּטְלָה הָעֵדוּת כֻּלָּהּ. מִפְּנֵי שֶׁהֵן כַּת אַחַת הוֹאִיל וְנִפְסְלָה מִקְּצָתָהּ נִפְסְלָה כֻּלָּהּ:","הֵעִיד הָאֶחָד וְנֶחְקְרָה עֵדוּתוֹ וְאָמַר הַשֵּׁנִי אַף אֲנִי כָּמוֹהוּ אוֹ שֶׁאָמַר הֵן כַּיּוֹצֵא בָּזֶה וְהוּזַמּוּ שְׁנֵיהֶן הֲרֵי שְׁנֵיהֶן נֶהֱרָגִין אוֹ לוֹקִין אוֹ מְשַׁלְּמִין. שֶׁכָּל עֵד שֶׁאָמַר אַחַר עֵדוּת חֲבֵרוֹ הֵן הֲרֵי זֶה כְּמִי שֶׁנֶּחְקַר וְהֵעִיד כְּמוֹ שֶׁהֵעִיד חֲבֵרוֹ. וְאֵין לְעֵדִים זוֹמְמִין שְׁגָגָה לְפִי שֶׁאֵין בָּהּ מַעֲשֶׂה. לְפִיכָךְ אֵין צְרִיכִים הַתְרָאָה כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּשֵׁם שֶׁהַשְּׁנַיִם מְזִימִין אֶת הַמֵּאָה אִם הֵעִידוּ הַמֵּאָה בְּבַת אַחַת. כָּךְ הֵן מְזִימִין אוֹתָן אֲפִלּוּ הָיוּ חֲמִשִּׁים כַּת וּבָאוּ שְׁנַיִם אַחַר שְׁנַיִם. כֵּיצַד. כַּת שֶׁהֵעִידָה עַל רְאוּבֵן שֶׁהָרַג אֶת שִׁמְעוֹן בִּירוּשָׁלַיִם וּבָאוּ שְׁנֵי עֵדִים וֶהֱזִימוּהָ. וּבָאת כַּת שְׁנִיָּה וְהֵעִידָה אוֹתָהּ עֵדוּת עַצְמָהּ שֶׁרְאוּבֵן הָרַג שִׁמְעוֹן בִּירוּשָׁלַיִם וְעָמְדוּ אוֹתָן הַשְּׁנַיִם וֶהֱזִימוּהָ גַּם זוֹ הַכַּת הַשְּׁנִיָּה וְכֵן הַשְּׁלִישִׁית וְכֵן הָרְבִיעִית אֲפִלּוּ מֵאָה כֻּלָּן הֵן נֶהֱרָגִין עַל פִּי אֵלּוּ הַשְּׁנַיִם:","כַּת שֶׁהֵעִידָה עַל רְאוּבֵן שֶׁהָרַג אֶת שִׁמְעוֹן בִּירוּשָׁלַיִם וּבָאָה כַּת שְׁנִיָּה וְהֵזִימָה אֶת הַכַּת רִאשׁוֹנָה יֵהָרְגוּ הָעֵדִים הַזּוֹמְמִין וְיִנָּצֵל רְאוּבֵן. בָּאָה כַּת שְׁלִישִׁית וְהֵזִימָה אֶת הַכַּת הַשְּׁנִיָּה תֵּהָרֵג הַכַּת הַשְּׁנִיָּה וּרְאוּבֵן וְתִנָּצֵל הַכַּת רִאשׁוֹנָה. בָּאָה כַּת רְבִיעִית וְהֵזִימָה אֶת הַכַּת שְׁלִישִׁית תֵּהָרֵג הַכַּת הַשְּׁלִישִׁית וְהָרִאשׁוֹנָה וְיִנָּצֵל רְאוּבֵן וְהַכַּת הַשְּׁנִיָּה. וְכֵן אֲפִלּוּ הֵן מֵאָה כַּת זוֹ מְזִמָּה אֶת זוֹ כַּת נִכְנֶסֶת וְכַת יוֹצֵאת:","עֵדִים שֶׁהֵעִידוּ עַל אִישׁ טְרֵפָה שֶׁהָרַג וְהוּזַמּוּ אֵין נֶהֱרָגִין. שֶׁאֲפִלּוּ הֲרָגוּהוּ בִּידֵיהֶן אֵין נֶהֱרָגִין לְפִי שֶׁהוּא טְרֵפָה. וְכֵן הָעֵדִים שֶׁהָיוּ טְרֵפָה וְהֵעִידוּ בְּדָבָר שֶׁחַיָּבִין עָלָיו מִיתַת בֵּית דִּין וְהוּזַמּוּ אֵין נֶהֱרָגִין. שֶׁאִם יוּזַמּוּ זוֹמְמֵיהֶן אֵין זוֹמְמֵיהֶן נֶהֱרָגִין שֶׁלֹּא הֵזִימוּ אֶלָּא טְרֵפָה:","עֵדִים שֶׁהֵעִידוּ עַל אֶחָד וְהִרְשִׁיעוּהוּ רֶשַׁע שֶׁאֵין בּוֹ לֹא מַלְקוֹת וְלֹא מִיתָה וְלֹא חִיּוּב מָמוֹן וְאַחַר כָּךְ הוּזַמּוּ. הֲרֵי אֵלּוּ לוֹקִין אַף עַל פִּי שֶׁלֹּא זָמְמוּ לְהַלְקוֹת זֶה וְלֹא לְחַיְּבוֹ מָמוֹן. כֵּיצַד. הֵעִידוּ עַל כֹּהֵן שֶׁהוּא חָלָל כְּגוֹן שֶׁהֵעִידוּ בְּפָנֵינוּ נִתְגָּרְשָׁה אִמּוֹ אוֹ נֶחְלְצָה בְּמָקוֹם פְּלוֹנִי בְּיוֹם פְּלוֹנִי וְהוּזַמּוּ הֲרֵי הֵן לוֹקִין. וְכֵן אִם הֵעִידוּ עַל אָדָם שֶׁהָרַג בִּשְׁגָגָה וְהוּזַמּוּ לוֹקִין וְאֵינָן גּוֹלִין. הֵעִידוּ עַל שׁוֹרוֹ שֶׁל זֶה שֶׁהָרַג הַנֶּפֶשׁ וְהוּזַמּוּ. הֲרֵי הֵן לוֹקִין וְאֵין מְשַׁלְּמִין אֶת הַכֹּפֶר. הֵעִידוּ עָלָיו שֶׁנִּמְכַּר בְּעֶבֶד עִבְרִי וְהוּזַמּוּ לוֹקִין. וְאַרְבָּעָה דְּבָרִים אֵלּוּ מִפִּי הַקַּבָּלָה הֵן:","כָּךְ קִבְּלוּ חֲכָמִים שֶׁשְּׁנַיִם שֶׁהִרְשִׁיעוּ אֶת הַצַּדִּיק וְהִצְדִּיקוּ אֶת הָרָשָׁע בְּעֵדוּתָן. וּבָאוּ עֵדִים אֲחֵרִים וֶהֱזִימוּם וְהִצְדִּיקוּ אֶת הַצַּדִּיק וְהִרְשִׁיעוּ אֶת הָרָשָׁע. הֲרֵי עֵדִים הָרִאשׁוֹנִים לוֹקִים אַף עַל פִּי שֶׁלֹּא הִרְשִׁיעוּ הַצַּדִּיק לְהַלְקוֹתוֹ. אֲבָל אִם הֵעִידוּ עָלָיו שֶׁאָכַל בָּשָׂר בְּחָלָב אוֹ שֶׁלָּבַשׁ שַׁעַטְנֵז הֲרֵי אֵלּוּ לוֹקִין. מִשּׁוּם שֶׁנֶּאֱמַר (דברים יט יט) \"וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם\":","שְׁנַיִם שֶׁהֵעִידוּ עַל רְאוּבֵן שֶׁנָּאַף עִם בַּת כֹּהֵן וְנִגְמַר דִּין רְאוּבֵן לֵיחָנֵק וְדִין הַנּוֹאֶפֶת לִשְׂרֵפָה וְאַחַר כָּךְ נִמְצְאוּ זוֹמְמִין הֲרֵי אֵלּוּ נֶחְנָקִין וְלֹא נִשְׂרָפִין. וְדָבָר זֶה מִפִּי הַקַּבָּלָה:"],"Mishneh Torah, The Chosen Temple 3":["הַמְּנּוֹרָה מְפֹרֶשֶׁת צוּרָתָהּ בַּתּוֹרָה. וְאַרְבָּעָה גְּבִיעִים וּשְׁנֵי כַּפְתּוֹרִים וּשְׁנֵי פְּרָחִים הָיוּ בִּקְנֵה הַמְּנוֹרָה שֶׁנֶּאֱמַר (שמות כה לד) (שמות לז כ) \"וּבַמְּנֹרָה אַרְבָּעָה גְבִעִים מְשֻׁקָּדִים כַּפְתֹּרֶיהָ וּפְרָחֶיהָ\". וְעוֹד פֶּרַח שְׁלִישִׁי הָיָה סָמוּךְ לִירֵכָהּ שֶׁל מְנוֹרָה שֶׁנֶּאֱמַר (במדבר ח ד) \"עַד יְרֵכָהּ עַד פִּרְחָהּ\":","וְשָׁלֹשׁ רַגְלַיִם הָיוּ לָהּ. וּשְׁלֹשָׁה כַּפְתּוֹרִים אֲחֵרִים הָיוּ בִּקְנֵה הַמְּנוֹרָה שֶׁמֵּהֶן יוֹצְאִים שֵׁשֶׁת הַקָּנִים. שְׁלֹשָׁה מִצַּד זֶה וּשְׁלֹשָׁה מִצַּד זֶה. וּבְכָל קָנֶה וְקָנֶה מֵהֶן שְׁלֹשָׁה גְּבִיעִים וְכַפְתּוֹר וָפֶרַח. וְהַכּל מְשֻׁקָּדִים כְּמוֹ שְׁקֵדִים בַּעֲשִׂיָּתָן:","נִמְצְאוּ כָּל הַגְּבִיעִים שְׁנַיִם וְעֶשְׂרִים. וְהַפְּרָחִים תִּשְׁעָה. וְהַכַּפְתּוֹרִים אַחַד עָשָׂר. וְכֻלָּן מְעַכְּבִין זֶה אֶת זֶה וַאֲפִלּוּ חָסֵר אֶחָד מִן הַשְּׁנַיִם וְאַרְבָּעִים מְעַכֵּב אֶת כֻּלָּן:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁעֲשָׂאוּהָ זָהָב. אֲבָל שְׁאָר מִינֵי מַתָּכוֹת אֵין עוֹשִׂין בָּהּ גְּבִיעִים כַּפְתּוֹרִים וּפְרָחִים. וְכֵן מְנוֹרָה הַבָּאָה זָהָב תִּהְיֶה כֻּלָּהּ כִּכָּר עִם נֵרוֹתֶיהָ וְתִהְיֶה כֻּלָּהּ מִקְשָׁה מִן הָעֲשָׁתוֹת. וְשֶׁל שְׁאָר מִינֵי מַתָּכוֹת אֵין מַקְפִּידִין עַל מִשְׁקָלָהּ. וְאִם הָיְתָה חֲלוּלָה כְּשֵׁרָה:","וְאֵין עוֹשִׂין אוֹתָהּ לְעוֹלָם מִן הַגְּרוּטָאוֹת בֵּין שֶׁהָיְתָה שֶׁל זָהָב בֵּין שֶׁהָיְתָה שֶׁל שְׁאָר מִינֵי מַתָּכוֹת:","הַמֶּלְקָחַיִם וְהַמַּחְתּוֹת וּכְלֵי הַשֶּׁמֶן אֵינָן מִכְּלַל הַכִּכָּר שֶׁהֲרֵי נֶאֱמַר בַּמְּנוֹרָה (שמות כה לא) (שמות לז יז) \"זָהָב טָהוֹר\" וְחָזַר וְאָמַר וּמַלְקָחֶיהָ וּמַחְתֹּתֶיהָ זָהָב טָהוֹר. וְלֹא נֶאֱמַר נֵרוֹתֶיהָ זָהָב טָהוֹר מִפְּנֵי שֶׁהַנֵּרוֹת קְבוּעִין בַּמְּנוֹרָה וְהֵם מִכְּלַל הַכִּכָּר:","שִׁבְעַת קְנֵי הַמְּנוֹרָה מְעַכְּבִין זֶה אֶת זֶה. וְשִׁבְעַת נֵרוֹתֶיהָ מְעַכְּבִין זֶה אֶת זֶה בֵּין שֶׁהָיְתָה שֶׁל זָהָב בֵּין שֶׁהָיְתָה שֶׁל שְׁאָר מִינֵי מַתָּכוֹת. וְכָל הַנֵּרוֹת קְבוּעִים בַּקָּנִים:","שֵׁשֶׁת הַנֵּרוֹת הַקְּבוּעִים בְּשֵׁשֶׁת הַקָּנִים הַיּוֹצְאִים מִן הַמְּנוֹרָה כֻּלָּן פְּנֵיהֶם לַנֵּר הָאֶמְצָעִי שֶׁעַל קְנֵי הַמְּנוֹרָה וְזֶה הַנֵּר הָאֶמְצָעִי פָּנָיו כְּנֶגֶד קֹדֶשׁ הַקָּדָשִׁים וְהוּא הַנִּקְרָא נֵר מַעֲרָבִי:","הַגְּבִיעִים דּוֹמִין לְכוֹסוֹת אֲלֶכְּסַנְדְּרִיאָה שֶׁפִּיהֶן רָחָב וְשׁוּלֵיהֶן קָצָר. וְהַכַּפְתּוֹרִים כְּמִין תַּפּוּחִים כְּרוּתִיִּים שֶׁהֵן אֲרֻכִּין מְעַט כְּבֵיצָה שֶׁשְּׁנֵי רָאשֶׁיהָ כַּדִּין. וְהַפְּרָחִים כְּמוֹ פִּרְחֵי הָעַמּוּדִים שֶׁהֵן כְּמִין קְעָרָה וּשְׂפָתָהּ כְּפוּלָה לַחוּץ:","גֹּבַהּ הַמְּנוֹרָה הָיָה שְׁמוֹנָה עָשָׂר טֶפַח. הָרַגְלַיִם וְהַפֶּרַח שְׁלֹשָׁה טְפָחִים. וּשְׁנֵי טְפָחִים חָלָק. וְטֶפַח שֶׁבּוֹ גָּבִיעַ כַּפְתּוֹר וָפֶרַח. וּטְפָחַיִם חָלָק. וְטֶפַח כַּפְתּוֹר וּשְׁנֵי קָנִים יוֹצְאִין מִמֶּנּוּ אֶחָד הֵילָךְ וְאֶחָד הֵילָךְ וְנִמְשָׁכִים וְעוֹלִין כְּנֶגֶד גֹּבַהּ הַמְּנוֹרָה. וְטֶפַח חָלָק. וְטֶפַח כַּפְתּוֹר וּשְׁנֵי קָנִים יוֹצְאִים מִמֶּנּוּ אֶחָד הֵילָךְ וְאֶחָד הֵילָךְ וְנִמְשָׁכִין וְעוֹלִין כְּנֶגֶד גֹּבַהּ הַמְּנוֹרָה. וְטֶפַח חָלָק. וְטֶפַח כַּפְתּוֹר וּשְׁנֵי קָנִים יוֹצְאִים מִמֶּנּוּ אֶחָד הֵילָךְ וְאֶחָד הֵילָךְ וְנִמְשָׁכִין וְעוֹלִין כְּנֶגֶד גֹּבַהּ הַמְּנוֹרָה. וּטְפָחַיִם חָלָק. נִשְׁתַּיְּרוּ שְׁלֹשָׁה טְפָחִים שֶׁבָּהֶן שְׁלֹשָׁה גְּבִיעִים כַּפְתּוֹר וָפֶרַח:","וְאֶבֶן הָיְתָה לִפְנֵי הַמְּנוֹרָה וּבָהּ שָׁלֹשׁ מַעֲלוֹת שֶׁעָלֶיהָ כֹּהֵן עוֹמֵד וּמֵיטִיב אֶת הַנֵּרוֹת וּמַנִּיחַ עָלֶיהָ כְּלֵי שַׁמְנָהּ וּמַלְקָחֶיהָ וּמַחְתּוֹתֶיהָ בִּשְׁעַת הֲטָבָה:","הַשֻּׁלְחָן הָיָה אָרְכּוֹ שְׁנֵים עָשָׂר טֶפַח וְרָחְבּוֹ שִׁשָּׁה טְפָחִים. וְהָיָה מֻנָּח אָרְכּוֹ לְאֹרֶךְ הַבַּיִת וְרָחְבּוֹ לְרֹחַב הַבַּיִת. וְכֵן שְׁאָר כָּל הַכֵּלִים שֶׁבַּמִּקְדָּשׁ אָרְכָּן לְאָרְכּוֹ שֶׁל בַּיִת וְרָחְבָּן לְרֹחַב הַבַּיִת חוּץ מִן הָאָרוֹן שֶׁהָיָה אָרְכּוֹ לְרֹחַב הַבַּיִת. וְכֵן נֵרוֹת הַמְּנוֹרָה כְּנֶגֶד רֹחַב הַבַּיִת בֵּין הַצָּפוֹן וּבֵין הַדָּרוֹם:","אַרְבָּעָה סְנִיפִין שֶׁל זָהָב הָיוּ לַשֻּׁלְחָן מְפֻצָּלִין בְּרָאשֵׁיהֶן שֶׁהָיוּ סוֹמְכִין בָּהֶן שְׁתֵּי הַמַּעֲרָכוֹת שֶׁל לֶחֶם הַפָּנִים. שְׁנַיִם מִסֵּדֶר זֶה. וּשְׁנַיִם מִסֵּדֶר זֶה. וְהֵם הַנֶּאֱמָרִים בַּתּוֹרָה (שמות כה כט) \"וּקְשׂוֹתָיו\":","וּשְׁמוֹנָה וְעֶשְׂרִים קָנִים שֶׁל זָהָב כָּל אֶחָד מֵהֶן כַּחֲצִי קָנֶה חָלוּל הָיוּ לוֹ. אַרְבָּעָה עָשָׂר לְסֵדֶר זֶה וְאַרְבָּעָה עָשָׂר לְסֵדֶר זֶה. וְהֵם הַנִּקְרָאִים (שמות כה כט) \"מְנַקִּיּוֹתָיו\". וּשְׁנֵי הַבְּזִיכִין שֶׁמַּנִּיחִין בָּהֶן הַלְּבוֹנָה עַל הַשֻּׁלְחָן בְּצַד הַמַּעֲרָכוֹת הֵן הַנִּקְרָאִין (שמות כה כט) \"כַּפּוֹתָיו\". וְהַדְּפוּסִין שֶׁעוֹשִׂין בָּהֶם לֶחֶם הַפָּנִים הֵם הַנִּקְרָאִים (שמות כה כט) \"קְעָרוֹתָיו\":","אֵלּוּ הָאַרְבָּעָה עָשָׂר קָנִים נוֹתֵן הַחַלָּה הָרִאשׁוֹנָה עַל עַצְמוֹ שֶׁל שֻׁלְחָן וְנוֹתֵן בֵּין רִאשׁוֹנָה וּשְׁנִיָּה שְׁלֹשָׁה קָנִים. וְכֵן בֵּין כָּל חַלָּה וְחַלָּה שְׁלֹשָׁה קָנִים. וּבֵין שִׁשִּׁית וַחֲמִישִׁית שְׁנֵי קָנִים בִּלְבַד לְפִי שֶׁאֵין עַל הַשִּׁשִּׁית אַחֶרֶת. נִמְצְאוּ אַרְבָּעָה עָשָׂר בְּכָל מַעֲרָכָה וּמַעֲרָכָה:","וּשְׁנֵי שֻׁלְחָנוֹת הָיוּ בָּאוּלָם מִבִּפְנִים עַל פֶּתַח הַבַּיִת. אֶחָד שֶׁל שַׁיִשׁ נוֹתְנִין עָלָיו לֶחֶם הַפָּנִים בִּכְנִיסָתוֹ. וְאֶחָד שֶׁל זָהָב נוֹתְנִין עָלָיו לֶחֶם בִּיצִיאָתוֹ. שֶׁמַּעֲלִין בַּקֹּדֶשׁ וְלֹא מוֹרִידִין:","מִזְבַּח הַקְּטֹרֶת הָיָה מְרֻבָּע אַמָּה עַל אַמָּה. וְהוּא נָתוּן בַּהֵיכָל מְכֻוָּן בֵּין הַצָּפוֹן לַדָּרוֹם מָשׁוּךְ בֵּין הַשֻּׁלְחָן וְהַמְּנוֹרָה לַחוּץ. וּשְׁלָשְׁתָּן הָיוּ מֻנָּחִין מִשְּׁלִישׁ הַהֵיכָל וְלִפְנִים כְּנֶגֶד הַפָּרֹכֶת הַמַּבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקָּדָשִׁים:","הַכִּיּוֹר הָיוּ לוֹ שְׁנֵים עָשָׂר דָּד כְּדֵי שֶׁיִּהְיוּ כָּל הַכֹּהֲנִים הָעוֹסְקִים בַּתָּמִיד מְקַדְּשִׁים מִמֶּנּוּ כְּאֶחָד. וּמוּכְנִי עָשׂוּ לוֹ שֶׁיִּהְיוּ בָּהּ הַמַּיִם תָּמִיד. וְהִיא חֹל כְּדֵי שֶׁלֹּא יִהְיוּ הַמַּיִם שֶׁבָּהּ נִפְסָלִין בְּלִינָה שֶׁהַכִּיּוֹר מִכְּלֵי הַקֹּדֶשׁ וּמְקַדֵּשׁ וְכָל דָּבָר שֶׁיִּתְקַדֵּשׁ בִּכְלִי קֹדֶשׁ אִם לָן נִפְסַל:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 10":["אֶחָד מִן הַדַּיָּנִים בְּדִינֵי נְפָשׁוֹת שֶׁהָיָה מִן הַמְזַכִּין אוֹ מִן הַמְחַיְּבִין לֹא מִפְּנֵי שֶׁאָמַר דָּבָר הַנִּרְאֶה לוֹ בְּדַעְתּוֹ אֶלָּא נָטָה אַחַר דִּבְרֵי חֲבֵרוֹ הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה. וְעַל זֶה נֶאֱמַר (שמות כג ב) \"וְלֹא תַעֲנֶה עַל רִב לִנְטֹת\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁלֹּא תֹּאמַר בִּשְׁעַת מִנְיָן דַּי שֶׁאֶהֱיֶה כְּאִישׁ פְּלוֹנִי אֶלָּא אֱמֹר מַה שֶּׁלְּפָנֶיךָ:","וּבִכְלַל לָאו זֶה שֶׁלֹּא יַחְזֹר הַמְלַמֵּד זְכוּת בְּדִינֵי נְפָשׁוֹת לְלַמֵּד חוֹבָה שֶׁנֶּאֱמַר (שמות כג ב) \"לֹא תַעֲנֶה עַל רִב לִנְטֹת\". בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁעַת מַשָּׂא וּמַתָּן. אֲבָל בִּשְׁעַת גְּמַר דִּין יֵשׁ לַמְלַמֵּד זְכוּת לַחְזֹר וּלְהִתְמַנּוֹת עִם הַמְחַיְּבִים:","תַּלְמִיד שֶׁהָיָה מְזַכֶּה וּמֵת רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא מְזַכֶּה בִּמְקוֹמוֹ:","אָמַר אֶחָד יֵשׁ לִי לְלַמֵּד עָלָיו זְכוּת וְנִשְׁתַּתֵּק אוֹ מֵת קֹדֶם שֶׁיְּלַמֵּד זְכוּת וְיֹאמַר מֵאֵי זֶה טַעַם מְזַכֶּה הֲרֵי הוּא כְּמִי שֶׁאֵינוֹ:","שְׁנַיִם שֶׁאָמְרוּ טַעַם אֶחָד אֲפִלּוּ מִשְּׁנֵי מִקְרָאוֹת אֵין נִמְנִין אֶלָּא כְּאֶחָד:","וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין מַתְחִילִין בְּדִינֵי נְפָשׁוֹת מִן הַגָּדוֹל שֶׁמָּא יִסְמְכוּ הַשְּׁאָר עַל דַּעְתּוֹ וְלֹא יִרְאוּ עַצְמָן כְּדָאִין לַחְלֹק עָלָיו. אֶלָּא יֹאמַר כָּל אֶחָד דָּבָר הַנִּרְאֶה לוֹ בְּדַעְתּוֹ:","וְכֵן אֵין פּוֹתְחִין בְּדִינֵי נְפָשׁוֹת לְחוֹבָה אֶלָּא לִזְכוּת. כֵּיצַד. אוֹמְרִים לָזֶה שֶׁחָטָא אִם לֹא עָשִׂיתָ דָּבָר זֶה שֶׁהֵעִידוּ בּוֹ עָלֶיךָ אַל תִּירָא מִדִּבְרֵיהֶם:","אָמַר אֶחָד מִן הַתַּלְמִידִים בְּדִינֵי נְפָשׁוֹת יֵשׁ לִי לְלַמֵּד עָלָיו חוֹבָה מְשַׁתְּקִין אוֹתוֹ. אָמַר יֵשׁ לִי לְלַמֵּד עָלָיו זְכוּת מַעֲלִין אוֹתוֹ עִמָּהֶן לַסַּנְהֶדְרִין. אִם יֵשׁ מַמָּשׁ בִּדְבָרָיו שׁוֹמְעִין לוֹ וְאֵינוֹ יוֹרֵד מִשָּׁם לְעוֹלָם. וְאִם אֵין מַמָּשׁ בִּדְבָרָיו אֵינוֹ יוֹרֵד מִשָּׁם כָּל הַיּוֹם כֻּלּוֹ. אֲפִלּוּ אָמַר הַנִּדּוֹן עַצְמוֹ יֵשׁ לִי לְלַמֵּד עַל עַצְמִי זְכוּת שׁוֹמְעִין לוֹ וְעוֹלֶה לְמִנְיָן. וְהוּא שֶׁיִּהְיֶה מַמָּשׁ בִּדְבָרָיו:","בֵּית דִּין שֶׁטָּעוּ בְּדִינֵי נְפָשׁוֹת וְחִיְּבוּ אֶת הַפָּטוּר וְגָמְרוּ דִּינוֹ לְחוֹבָה וְנִרְאֶה לָהֶם הַטַּעַם שֶׁיִּסְתְּרוּ בּוֹ אֶת דִּינוֹ כְּדֵי לְזַכּוֹתוֹ סוֹתְרִין וְחוֹזְרִין וְדָנִין אוֹתוֹ. אֲבָל אִם טָעוּ וּפָטְרוּ אֶת הַמְחֻיָּב הֲרִיגָה אֵין סוֹתְרִין אֶת דִּינוֹ וְאֵין מַחֲזִירִין אוֹתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁטָּעוּ בְּדָבָר שֶׁאֵין הַצְּדוֹקִין מוֹדִין בּוֹ. אֲבָל אִם טָעוּ בְּדָבָר שֶׁהַצְּדוֹקִין מוֹדִין בּוֹ מַחֲזִירִין אוֹתוֹ לְחוֹבָה. כֵּיצַד. אָמְרוּ הַבָּא עַל הָעֶרְוָה שֶׁלֹּא כְּדַרְכָּהּ פָּטוּר וּפְטָרוּהוּ מַחֲזִירִין אוֹתוֹ וּמְמִיתִין אוֹתוֹ. אֲבָל אִם אָמְרוּ הַמְעָרֶה שֶׁלֹּא כְּדַרְכָּהּ פָּטוּר וּפְטָרוּהוּ אֵין מַחֲזִירִין אוֹתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 21":["מִצְוַת עֲשֵׂה לִשְׁפֹּט הַשּׁוֹפֵט בְּצֶדֶק שֶׁנֶּאֱמַר (ויקרא יט טו) \"בְּצֶדֶק תִּשְׁפֹּט עֲמִיתֶךָ\". אֵי זֶהוּ צֶדֶק הַמִּשְׁפָּט זוֹ הַשְׁוָיַת שְׁנֵי בַּעֲלֵי דִּינִין בְּכָל דָּבָר. לֹא יְהֵא אֶחָד מְדַבֵּר כָּל צָרְכּוֹ וְאֶחָד אוֹמֵר לוֹ קַצֵּר דְּבָרֶיךָ. וְלֹא יַסְבִּיר פָּנִים לְאֶחָד וִידַבֵּר לוֹ רַכּוֹת וְיָרֵעַ פָּנָיו לְאַחֵר וִידַבֵּר לוֹ קָשׁוֹת:","שְׁנֵי בַּעֲלֵי דִּינִין שֶׁהָיָה אֶחָד מֵהֶם מְלֻבָּשׁ בְּגָדִים יְקָרִים וְהַשֵּׁנִי מְלֻבָּשׁ בְּגָדִים בְּזוּיִין אוֹמֵר לַמְכֻבָּד אוֹ הַלְבִּישֵׁהוּ כְּמוֹתְךָ עַד שֶׁתָּדוּן עִמּוֹ אוֹ לְבשׁ כְּמוֹתוֹ עַד שֶׁתִּהְיוּ שָׁוִין אַחַר כָּךְ תַּעַמְדוּ בַּדִּין:","לֹא יִהְיֶה אֶחָד יוֹשֵׁב וְאֶחָד עוֹמֵד אֶלָּא שְׁנֵיהֶם עוֹמְדִים. וְאִם רָצוּ בֵּית דִּין לְהוֹשִׁיב אֶת שְׁנֵיהֶם מוֹשִׁיבִין. וְלֹא יֵשֵׁב אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה אֶלָּא זֶה בְּצַד זֶה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁעַת מַשָּׂא וּמַתָּן. אֲבָל בִּשְׁעַת גְּמַר דִּין שְׁנֵיהֶם בַּעֲמִידָה שֶׁנֶּאֱמַר (שמות יח יג) \"וַיַּעֲמֹד הָעָם עַל משֶׁה\". וְאֵי זֶהוּ גְּמַר דִּין אִישׁ פְּלוֹנִי אַתָּה זַכַּאי אִישׁ פְּלוֹנִי אַתָּה חַיָּב. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבַעֲלֵי דִּינִין. אֲבָל הָעֵדִים לְעוֹלָם בַּעֲמִידָה שֶׁנֶּאֱמַר (דברים יט יז) \"וְעָמְדוּ שְׁנֵי הָאֲנָשִׁים\":","תַּלְמִיד חָכָם וְעַם הָאָרֶץ שֶׁבָּאוּ לְדִין מוֹשִׁיבִין אֶת הֶחָכָם וְאוֹמְרִים לְעַם הָאָרֶץ שֵׁב. אִם לֹא יָשַׁב אֵין מַקְפִּידִין עַל כָּךְ. וְלֹא יַקְדִּים הַתַּלְמִיד כְּשֶׁיָּבוֹא לְדִין וְיֵשֵׁב לִפְנֵי רַבּוֹ כְּרוֹצֶה לָדוּן לְפָנָיו. וְאִם הָיָה קוֹבֵעַ לוֹ זְמַן לִקְרוֹת וּבָא זְמַנּוֹ מֻתָּר:","כְּבָר נָהֲגוּ כָּל בָּתֵּי דִּינֵי יִשְׂרָאֵל מֵאַחַר הַגְּמָרָא בְּכָל הַיְשִׁיבוֹת שֶׁמּוֹשִׁיבִין בַּעֲלֵי דִּינִין וּמוֹשִׁיבִין הָעֵדִים כְּדֵי לְסַלֵּק הַמַּחֲלֹקֶת. שֶׁאֵין בָּנוּ כֹּחַ לְהַעֲמִיד מִשְׁפְּטֵי הַדָּת עַל תִּלָּם:","הָיוּ לִפְנֵי הַדַּיָּנִים בַּעֲלֵי דִּין הַרְבֵּה מַקְדִּימִין אֶת דִּין הַיָּתוֹם לְדִין הָאַלְמָנָה שֶׁנֶּאֱמַר (ישעיה א יז) \"שִׁפְטוּ יָתוֹם רִיבוּ אַלְמָנָה\". וְדִין אַלְמָנָה קוֹדֵם לְדִין תַּלְמִיד חָכָם. וְדִין תַּלְמִיד חָכָם קוֹדֵם לְדִין עַם הָאָרֶץ. וְדִין הָאִשָּׁה קוֹדֵם לְדִין הָאִישׁ שֶׁבּשֶׁת הָאִשָּׁה מְרֻבָּה:","אָסוּר לְדַיָּן לִשְׁמֹעַ דִּבְרֵי אֶחָד מִבַּעֲלֵי דִּינִין קֹדֶם שֶׁיָּבוֹא חֲבֵרוֹ אוֹ שֶׁלֹּא בִּפְנֵי חֲבֵרוֹ. וַאֲפִלּוּ דָּבָר אֶחָד אָסוּר שֶׁנֶּאֱמַר (דברים א טז) \"שָׁמֹעַ בֵּין אֲחֵיכֶם\". וְכָל הַשּׁוֹמֵעַ מֵאֶחָד עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כג א) \"לֹא תִשָּׂא שֵׁמַע שָׁוְא\". וּבִכְלַל לָאו זֶה אַזְהָרָה לִמְקַבֵּל לָשׁוֹן הָרַע וּמְסַפֵּר לָשׁוֹן הָרַע וּמֵעִיד עֵדוּת שֶׁקֶר. וְכֵן בַּעַל דִּין מֻזְהָר שֶׁלֹּא יַשְׁמִיעַ דְּבָרָיו לַדַּיָּן קֹדֶם שֶׁיָּבוֹא בַּעַל דִּין חֲבֵרוֹ. וְגַם עַל זֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\":","לֹא יִהְיֶה הַדַּיָּן שׁוֹמֵעַ מִפִּי הַתֻּרְגְּמָן אֶלָּא אִם כֵּן הָיָה מַכִּיר לְשׁוֹן בַּעֲלֵי דִּינִין וְשׁוֹמֵעַ טַעֲנוֹתֵיהֶם. וְאִם אֵינוֹ מָהִיר בִּלְשׁוֹנָם כְּדֵי לְהָשִׁיב לָהֶם יַעֲמֹד הַתֻּרְגְּמָן לְהוֹדִיעַ אוֹתָם פְּסַק הַדִּין וּמֵאֵי זֶה טַעַם חַיָּב זֶה וְזָכָה זֶה:","צָרִיךְ הַדַּיָּן לִשְׁמֹעַ טַעֲנוֹת בַּעֲלֵי דִּינִין וְלִשְׁנוֹת טַעֲנוֹתֵיהֶן שֶׁנֶּאֱמַר (מלכים א ג כג) \"וַיֹּאמֶר הַמֶּלֶךְ זֹאת אֹמֶרֶת זֶה בְּנִי הַחַי וּבְנֵךְ הַמֵּת\" וּמְצַדֵּק אֶת הַדִּין בְּלִבּוֹ וְאַחַר כָּךְ חוֹתְכוֹ:","מִנַּיִן לַדַּיָּן שֶׁלֹּא יֵעָשֶׂה מֵלִיץ לִדְבָרָיו שֶׁל בַּעַל דִּין שֶׁנֶּאֱמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\" אֶלָּא יֹאמַר מַה שֶּׁנִּרְאֶה לוֹ וְיִשְׁתֹּק. וְלֹא יְלַמֵּד אֶחָד מִבַּעֲלֵי דִּינִין טַעֲנָה כְּלָל. אֲפִלּוּ הֵבִיא עֵד אֶחָד לֹא יֹאמַר לוֹ אֵין מְקַבְּלִין עֵד אֶחָד אֶלָּא יֹאמַר לַנִּטְעָן הֲרֵי זֶה הֵעִיד עָלֶיךָ. הַלְוַאי שֶׁיּוֹדֶה וְיֹאמַר אֱמֶת הֵעִיד. עַד שֶׁיִּטְעֹן הוּא וְיֹאמַר עֵד אֶחָד הוּא וְאֵינוֹ נֶאֱמָן עָלַי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רָאָה הַדַּיָּן זְכוּת לְאֶחָד מֵהֶן וּבַעַל דִּין מְבַקֵּשׁ לְאָמְרָהּ וְאֵינוֹ יוֹדֵעַ לְחַבֵּר הַדְּבָרִים. אוֹ שֶׁרָאָהוּ מִצְטַעֵר לְהַצִּיל עַצְמוֹ בְּטַעֲנַת אֱמֶת וּמִפְּנֵי הַחֵמָה וְהַכַּעַס נִסְתַּלֵּק מִמֶּנּוּ אוֹ נִשְׁתַּבֵּשׁ מִפְּנֵי הַסִּכְלוּת. הֲרֵי זֶה מֻתָּר לְסַעֲדוֹ מְעַט לַהֲבִינוֹ תְּחִלַּת הַדָּבָר מִשּׁוּם (משלי לא ח) \"פְּתַח פִּיךָ לְאִלֵּם\". וְצָרִיךְ לְהִתְיַשֵּׁב בְּדָבָר זֶה הַרְבֵּה שֶׁלֹּא יִהְיֶה כְּעוֹרְכֵי הַדַּיָּנִין:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 9":["סַנְּהֶדְרִין שֶׁפָּתְחוּ כֻּלָּם בְּדִינֵי נְפָשׁוֹת תְּחִלָּה וְאָמְרוּ כֻּלָּן חַיָּב הֲרֵי זֶה פָּטוּר עַד שֶׁיִּהְיוּ שָׁם מִקְצָת מְזַכִּין שֶׁיְּהַפְּכוּ בִּזְכוּתוֹ וְיִרְבּוּ הַמְחַיְּבִין וְאַחַר כָּךְ יַהֲרֹג:","סַנְהֶדְרִי קְטַנָּה שֶׁנֶּחְלְקוּ בְּדִינֵי נְפָשׁוֹת שְׁנֵים עָשָׂר אוֹמְרִים זַכַּאי וְאַחַד עָשָׂר אוֹמְרִים חַיָּב הֲרֵי זֶה זַכַּאי. שְׁנֵים עָשָׂר אוֹמְרִים חַיָּב וְאַחַד עָשָׂר אוֹמְרִים זַכַּאי אוֹ שֶׁאָמְרוּ אַחַד עָשָׂר זַכַּאי וְאַחַד עָשָׂר חַיָּב וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ אֲפִלּוּ עֶשְׂרִים וּשְׁנַיִם מְזַכִּין אוֹ מְחַיְּבִין וְהָאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ יוֹסִיפוּ שְׁנַיִם. זֶה שֶׁאָמַר אֵינִי יוֹדֵעַ הֲרֵי הוּא כְּמִי שֶׁאֵינוֹ שֶׁהֲרֵי אֵינוֹ חוֹזֵר וּמְלַמֵּד חוֹבָה וְנִמְצְאוּ אַחַר הַתּוֹסֶפֶת עֶשְׂרִים וְאַרְבָּעָה חוּץ מִזֶּה הַמִּסְתַּפֵּק. אָמְרוּ שְׁנֵים עָשָׂר זַכַּאי וּשְׁנֵים עָשָׂר חַיָּב הֲרֵי זֶה זַכַּאי. אַחַד עָשָׂר אוֹמְרִים זַכַּאי וּשְׁלֹשָׁה עָשָׂר אוֹמְרִים חַיָּב אַף עַל פִּי שֶׁהָאֶחָד מִן הָרִאשׁוֹנִים אוֹמֵר אֵינִי יוֹדֵעַ הֲרֵי זֶה חַיָּב שֶׁהֲרֵי הַמְחַיְּבִין רַבּוּ בִּשְׁנַיִם. אָמְרוּ שְׁנֵים עָשָׂר זַכַּאי וּשְׁנֵים עָשָׂר חַיָּב וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ מוֹסִיפִין שְׁנַיִם אֲחֵרִים. וְכֵן מוֹסִיפִין וְהוֹלְכִין עַד שֶׁיִּרְבּוּ הַמְזַכִּין אֶחָד וִיהֵא זַכַּאי אוֹ יִרְבּוּ הַמְחַיְּבִין שְׁנַיִם אוֹ יוֹתֵר וִיהֵא חַיָּב. הָיוּ אֵלּוּ כְּנֶגֶד אֵלּוּ וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ אוֹ שֶׁהָיוּ הַמְחַיְּבִין יוֹתֵר אֶחָד בִּלְבַד מוֹסִיפִין וְהוֹלְכִין עַד שִׁבְעִים וְאֶחָד. הִגִּיעוּ לְשִׁבְעִים וְאֶחָד שְׁלֹשִׁים וְשִׁשָּׁה אוֹמְרִים זַכַּאי וּשְׁלֹשִׁים וַחֲמִשָּׁה אוֹמְרִים חַיָּב הֲרֵי זֶה זַכַּאי. שְׁלֹשִׁים וְשִׁשָּׁה אוֹמְרִים חַיָּב וּשְׁלֹשִׁים וַחֲמִשָּׁה אוֹמְרִים זַכַּאי דָּנִים אֵלּוּ כְּנֶגֶד אֵלּוּ עַד שֶׁיִּרְאֶה אֶחָד מֵהֶן דִּבְרֵי חֲבֵרוֹ וּמְזַכִּין אוֹתוֹ אוֹ מְחַיְּבִין אוֹתוֹ. וְאִם לֹא רָאָה גָּדוֹל שֶׁבַּדַּיָּנִים אוֹמֵר נִזְדַּקֵּן הַדִּין וּפוֹטְרִין אוֹתוֹ. שְׁלֹשִׁים וַחֲמִשָּׁה אוֹמְרִים חַיָּב וּשְׁלֹשִׁים וַחֲמִשָּׁה אוֹמְרִים זַכַּאי וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ פּוֹטְרִין אוֹתוֹ. אַרְבָּעָה וּשְׁלֹשִׁים אוֹמְרִים זַכַּאי וְשִׁשָּׁה וּשְׁלֹשִׁים אוֹמְרִים חַיָּב וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ חַיָּב שֶׁהֲרֵי רַבּוּ הַמְחַיְּבִין שְׁנַיִם:","בֵּית דִּין הַגָּדוֹל שֶׁבָּא לָהֶם מַחְלֹקֶת בֵּין בְּדִינֵי נְפָשׁוֹת בֵּין בְּדִינֵי מָמוֹנוֹת בֵּין בְּדִינֵי תּוֹרָה. אֵין מוֹסִיפִין עֲלֵיהֶן אֶלָּא דָּנִין אֵלּוּ כְּנֶגֶד אֵלּוּ וְהוֹלְכִין אַחַר הָרֹב שֶׁלָּהֶן. וְאִם בְּדִין אֶחָד מִן הַנֶּהֱרָגִין נֶחְלְקוּ דָּנִין אֵלּוּ כְּנֶגֶד אֵלּוּ עַד שֶׁיִּפְטְרוּהוּ אוֹ יִתְחַיֵּב:"],"Mishneh Torah, Things Forbidden on the Altar 3":["אֵין הַמּוּמִין פּוֹסְלִין בָּעוֹף וְכֵן אֶחָד הַזָּכָר וְאֶחָד הַנְּקֵבָה בָּעוֹף שֶׁלֹּא נֶאֱמַר (ויקרא כב-יט) \"תָמִים זָכָר\" אֶלָּא בִּבְהֵמָה בִּלְבַד. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמוּמִין קְטַנִּים. אֲבָל עוֹף שֶׁיָּבַשׁ גַּפּוֹ אוֹ נִסְמֵית עֵינוֹ אוֹ נִקְטְעָה רַגְלוֹ אָסוּר לְגַבֵּי הַמִּזְבֵּחַ שֶׁאֵין מַקְרִיבִין חָסֵר כְּלָל. וְכֵן אִם נוֹלַד בּוֹ אַחַת מִן הַטְּרֵפוֹת שֶׁאוֹסְרִין אוֹתָהּ בַּאֲכִילָה הֲרֵי זֶה נִפְסָל לְקָרְבָּן:","תּוֹרִים קְטַנִּים פְּסוּלִין וּבְנֵי יוֹנָה גְּדוֹלִים פְּסוּלִין שֶׁנֶּאֱמַר (ויקרא א׳:י״ד) \"מִן הַתֹּרִים אוֹ מִן בְּנֵי הַיּוֹנָה\". תְּחִלַּת הַצִּהוּב בָּזֶה וּבָזֶה פָּסוּל. וְעַד מָתַי יִהְיוּ בְּנֵי יוֹנָה כְּשֵׁרִים כָּל זְמַן שֶׁעוֹקֵר כָּנָף וּמִתְמַלֵּא מְקוֹם עִקָּרוֹ דָּם. וְהַתּוֹרִים כְּשֵׁרִים מִשֶּׁיִּזְהֲבוּ:","הַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס אַף עַל פִּי שֶׁאֵין לְךָ מוּם גָּדוֹל מֵהֶן הֲרֵי הֵן פְּסוּלִין לַמִּזְבֵּחַ מִדֶּרֶךְ אַחֶרֶת לְפִי שֶׁהֵן סָפֵק זָכָר סָפֵק נְקֵבָה הֲרֵי הֵן כְּמִין אַחֵר. וּבַקָּרְבָּנוֹת נֶאֱמַר (ויקרא א-ג) (ויקרא א-י) (ויקרא ד-כג) \"זָכָר תָּמִים\" וּ(ויקרא ד-לב) \"נְקֵבָה תְּמִימָה\" עַד שֶׁיִּהְיֶה זָכָר וַדַּאי אוֹ נְקֵבָה וַדָּאִית. לְפִיכָךְ אַף הָעוֹף שֶׁהוּא טֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס פָּסוּל לַמִּזְבֵּחַ:","וְכֵן הַכִּלְאַיִם וְיוֹצֵא דֹּפֶן וּמְחֻסַּר זְמַן פְּסוּלִין אַף עַל פִּי שֶׁאֵין בָּהֶם מוּם שֶׁנֶּאֱמַר (ויקרא כ״ב:כ״ז) \"שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז\" עַד שֶׁיִּהְיֶה כָּל מִין וּמִין בִּפְנֵי עַצְמוֹ לֹא שֶׁיִּהְיֶה מְעֹרָב מִכֶּבֶשׂ וְעֵז. (ויקרא כ״ב:כ״ז) \"כִּי יִוָּלֵד\" פְּרָט לְיוֹצֵא דֹּפֶן. (ויקרא כ״ב:כ״ז) \"וְהָיָה שִׁבְעַת יָמִים\" פְּרָט לִמְחֻסַּר זְמַן. (ויקרא כ״ב:כ״ז) \"תַּחַת אִמּוֹ\" פְּרָט לְיָתוֹם שֶׁנּוֹלַד אַחַר שֶׁנִּשְׁחֲטָה אִמּוֹ:","הַנִּדְמֶה אַף עַל פִּי שֶׁאֵינוֹ כִּלְאַיִם הֲרֵי הוּא פָּסוּל לַמִּזְבֵּחַ. כֵּיצַד. רָחֵל שֶׁיָּלְדָה כְּמִין עֵז וְעֵז שֶׁיָּלְדָה כְּמִין כֶּבֶשׂ. אַף עַל פִּי שֶׁיֵּשׁ בּוֹ מִקְצָת סִימָנִין הוֹאִיל וְהוּא דּוֹמֶה לְמִין אַחֵר פָּסוּל כְּבַעַל מוּם קָבוּעַ שֶׁאֵין לְךָ מוּם קָבוּעַ גָּדוֹל מִן הַשִּׁנּוּי:","וְכֵן הָרוֹבֵעַ וְהַנִּרְבָּע וְהַמֻּקְצֶה לַעֲבוֹדָה זָרָה וְהַנֶּעֱבָד אַף עַל פִּי שֶׁהֵן מֻתָּרִין בַּאֲכִילָה הֲרֵי הֵן פְּסוּלִין לְגַבֵּי הַמִּזְבֵּחַ שֶׁנֶּאֱמַר (ויקרא כ״ב:כ״ה) \"כִּי מָשְׁחָתָם בָּהֶם\" כָּל שֶׁיֵּשׁ בּוֹ הַשְׁחָתָה פָּסוּל. וּבַעֲבֵרָה הוּא אוֹמֵר (בראשית ו׳:י״ב) \"כִּי הִשְׁחִית כָּל בָּשָׂר\". וּבַעֲבוֹדָה זָרָה כְּתִיב (שמות לב-ז) (דברים ט׳:י״ב) \"כִּי שִׁחֵת עַמְּךָ\". וְכֵן בְּהֵמָה וְעוֹף שֶׁהָרְגוּ אֶת הָאָדָם הֲרֵי הֵן כְּרוֹבֵעַ אוֹ נִרְבָּע וּפְסוּלִין לַמִּזְבֵּחַ:","וְיֵרָאֶה לִי שֶׁאַף עַל פִּי שֶׁאֵין כָּל הַפְּסוּלִין הָאֵלּוּ רְאוּיִין לַמִּזְבֵּחַ לְקָרְבָּן אִם עָבַר וְהִקְרִיבָן אֵינוֹ לוֹקֶה מִן הַתּוֹרָה לְפִי שֶׁלֹּא נִתְפָּרְשָׁה אַזְהָרָתָן. (דברים כג-יט) \"אֲבָל אֶתְנַן זוֹנָה וּמְחִיר\" כֶּלֶב אֲסוּרִין לְגַבֵּי הַמִּזְבֵּחַ וְהַמַּקְרִיב אֶחָד מֵהֶן אוֹ שְׁנֵיהֶן כְּאֶחָד לוֹקֶה אַחַת שֶׁנֶּאֱמַר (דברים כג-יט) \"לֹא תָבִיא אֶתְנַן זוֹנָה וּמְחִיר כֶּלֶב\". וּמִפְּנֵי מָה לוֹקֶה אַחַת עַל שְׁנֵיהֶן מִפְּנֵי שֶׁנֶּאֶמְרוּ בְּלָאו אֶחָד:","מִצְוַת עֲשֵׂה לְהַקְרִיב כָּל הַקָּרְבָּנוֹת מִיּוֹם הַשְּׁמִינִי וָהָלְאָה שֶׁנֶּאֱמַר (ויקרא כ״ב:כ״ז) \"וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה\". וְכָל שִׁבְעַת הַיָּמִים נִקְרָא מְחֻסַּר זְמַן. וְאַף עַל פִּי שֶׁמְּחֻסַּר זְמַן פָּסוּל אִם עָבַר וְהִקְרִיבוֹ אֵינוֹ לוֹקֶה מִפְּנֵי שֶׁהוּא לָאו הַבָּא מִכְּלַל עֲשֵׂה וְלֹא נִרְצָה הַקָּרְבָּן:","תּוֹרִים שֶׁלֹּא הִגִּיעַ זְמַנָּן שֶׁהֵן כִּמְחֻסַּר זְמַן בִּבְהֵמָה וּבְנֵי יוֹנָה שֶׁעָבַר זְמַנָּן הַכּל כְּבַעַל מוּם וְהַמַּקְרִיבָן אֵינוֹ לוֹקֶה אַף עַל פִּי שֶׁהַקָּרְבָּן פָּסוּל וְלֹא נִרְצָה:","הַמַּקְדִּישׁ טֻמְטוּם וְאַנְדְּרוֹגִינוּס וּטְרֵפָה וְכִלְאַיִם וְיוֹצֵא דֹּפֶן לַמִּזְבֵּחַ הֲרֵי זֶה כְּמַקְדִּישׁ עֵצִים וַאֲבָנִים. לְפִי שֶׁאֵין קְדֻשָּׁה חָלָה עַל גּוּפָן וַהֲרֵי הֵן חֻלִּין לְכָל דָּבָר. וְיִמָּכְרוּ וְיָבִיא בִּדְמֵיהֶם כָּל קָרְבָּן שֶׁיִּרְצֶה. וְאֵינָן כְּבַעַל מוּם שֶׁבַּעַל מוּם יֵשׁ בְּמִינוֹ קָרְבָּן. אֲבָל הַמַּקְדִּישׁ רוֹבֵעַ וְנִרְבָּע וּמֻקְצֶה וְנֶעֱבָד וְאֶתְנָן וּמְחִיר הֲרֵי זֶה כְּמַקְדִּישׁ בַּעַל מוּם עוֹבֵר. וְיִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם קָבוּעַ וְיִפָּדוּ עָלָיו. וְכֵן הַמַּקְדִּישׁ מְחֻסַּר זְמַן הֲרֵי זֶה כְּמַקְדִּישׁ בַּעַל מוּם עוֹבֵר וְאֵינוֹ לוֹקֶה כְּמוֹ שֶׁבֵּאַרְנוּ:","נִמְצְאוּ כָּל הָאִסּוּרִין לַמִּזְבֵּחַ הֲרֵי הֵן י\"ד וְאֵלּוּ הֵן. בַּעַל מוּם. וְשֶׁאֵינוֹ מִן הַמֻּבְחָר. וּמְחֻסַּר אֵיבָר מִבִּפְנִים. וּטְרֵפָה. וְכִלְאַיִם. וְיוֹצֵא דֹּפֶן. וְרוֹבֵעַ. וְנִרְבָּע. וְשֶׁהֵמִית הָאָדָם. הַנֶּעֱבָד. הַמֻּקְצֶה. הָאֶתְנָן. הַמְּחִיר. מְחֻסַּר זְמַן:","כָּל הָאֲסוּרִין לְגַבֵּי הַמִּזְבֵּחַ אוֹסְרִין בְּכָל שֶׁהֵן אֲפִלּוּ נִתְעָרֵב אֶחָד בְּרִבּוֹא נִפְסַד הַכּל וְנִפְסַל לַמִּזְבֵּחַ. וְכֻלָּן וַלְדוֹתֵיהֶן מֻתָּרִין לַמִּזְבֵּחַ חוּץ מִוְּלַד נִרְבַּעַת וְנֶעֱבֶדֶת וּמֻקְצֵית וְשֶׁהֵמִיתָה אֶת הָאָדָם שֶׁוְּלָדָן אֲסוּרִין לַמִּזְבֵּחַ כְּמוֹתָן:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנֶּעֶבְדָה בָּהּ עֲבֵרָה אוֹ שֶׁהֵמִיתָה כְּשֶׁהָיְתָה מְעֵבֶּרֶת שֶׁהֲרֵי הַוָּלָד מָצוּי עִמָּהּ בְּעֵת שֶׁנִּפְסְלָה וְהָיָה כְּאֵיבָר מֵאֵיבָרֶיהָ. אֲבָל אִם נִתְעַבְּרָה אַחַר שֶׁנֶּעֶבְדָה בָּהּ עֲבֵרָה אוֹ אַחַר שֶׁהֵמִיתָה הֲרֵי וְלָדָהּ כָּשֵׁר לַמִּזְבֵּחַ אֲפִלּוּ נִרְבְּעָה כְּשֶׁהִיא מֻקְדֶּשֶׁת וְאַחַר כָּךְ נִתְעַבְּרָה. וְאֵין צָרִיךְ לוֹמַר אִם נִרְבְּעָה וְהִיא חֻלִּין וְאַחַר כָּךְ הִקְדִּישָׁהּ וְנִתְעַבְּרָה שֶׁוְּלָדָהּ מֻתָּר. וְכֵן אֶפְרוֹחַ בֵּיצַת טְרֵפָה מֻתָּר לַמִּזְבֵּחַ:","הַמִּשְׁתַּחֲוֶה לַקָּמָה חִטֶּיהָ מֻתָּרִין לִמְנָחוֹת שֶׁהֲרֵי נִשְׁתַּנּוּ וְנִדְמוּ לִוְלָדוֹת שֶׁל אִסּוּר מִזְבֵּחַ שֶׁהֵן מֻתָּרִין. וְכֵן בְּהֵמָה שֶׁפִּטְּמָהּ בְּכַרְשִׁינֵי עֲבוֹדָה זָרָה מֻתֶּרֶת לַמִּזְבֵּחַ שֶׁהֲרֵי נִשְׁתַּנּוּ:","לוֹקְחִין כָּל הַקָּרְבָּנוֹת מִן הָעַכּוּ\"ם וְאֵין חוֹשְׁשִׁין לָהֶם לֹא מִשּׁוּם רוֹבֵעַ וְנִרְבָּע וְלֹא מִשּׁוּם מֻקְצֶה וְנֶעֱבָד. עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁזֶּה נִפְסָל. הֲרֵי הוּא אוֹמֵר (שמואל א טו-טו) \"מֵעֲמָלֵקִי הֱבִיאוּם אֲשֶׁר חָמַל הָעָם עַל מֵיטַב הַצֹּאן וְהַבָּקָר לְמַעַן זְבֹחַ לַה' אֱלֹהֶיךָ\":"],"Mishneh Torah, Those Who Defile Bed or Seat 4":["אַרְבַּע נָשִׁים דַּיָּן שְׁעָתָן וְאֵינָן מִטַּמְּאוֹת לְמַפְרֵעַ. וְאֵלּוּ הֵן מְעֻבֶּרֶת וּמֵינִיקָה וּבְתוּלָה וּזְקֵנָה. אֵי זוֹ הִיא מְעֻבֶּרֶת מִשֶּׁיֻּכַּר עֻבָּרָהּ. הָיְתָה בְּחֶזְקַת מְעֻבֶּרֶת וְרָאֲתָה דָּם וְאַחַר כָּךְ הִפִּילָה רוּחַ אוֹ דָּבָר שֶׁאֵינוֹ וָלָד הֲרֵי זוֹ בְּחֶזְקָתָהּ וְדַיָּהּ שְׁעָתָהּ. רָאֲתָה דָּם וְאַחַר כָּךְ הֻכַּר עֻבָּרָהּ הֲרֵי זוֹ מִטַּמְּאָה לְמַפְרֵעַ כְּכָל הַנָּשִׁים. אֵי זוֹ הִיא מֵינִיקָה כָּל אַרְבָּעָה וְעֶשְׂרִים חֹדֶשׁ מִיּוֹם הַלֵּדָה אֲפִלּוּ מֵת בְּנָהּ בְּתוֹךְ זְמַן זֶה אוֹ שֶׁגְּמָלַתְהוּ אוֹ נְתָנַתְהוּ לְמֵינִיקָה דַּיָּהּ שְׁעָתָהּ. אֲבָל אַחַר אַרְבָּעָה וְעֶשְׂרִים חֹדֶשׁ אַף עַל פִּי שֶׁהִיא מֵינִיקָה וְהוֹלֶכֶת הֲרֵי זוֹ טְמֵאָה לְמַפְרֵעַ כְּכָל הַנָּשִׁים. אֵי זוֹ הִיא בְּתוּלָה כָּל שֶׁלֹּא רָאֲתָה דָּם מִיָּמֶיהָ. בְּתוּלַת דָּמִים אָמְרוּ לֹא בְּתוּלַת בְּתוּלִים. כֵּיצַד. אֲפִלּוּ נִשֵּׂאת וְרָאֲתָה דָּם מֵחֲמַת נִשּׂוּאִין אוֹ יָלְדָה וְרָאֲתָה דָּם מֵחֲמַת לֵדָה עֲדַיִן הִיא בְּתוּלָה לְעִנְיַן טֻמְאָה וְדַיָּה שְׁעָתָהּ. אֵי זוֹ הִיא זְקֵנָה כָּל שֶׁעָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים סָמוּךְ לְזִקְנוּתָהּ וְלֹא רָאֲתָה דָּם. וְאֵי זוֹ הִיא סָמוּךְ לְזִקְנוּתָהּ כָּל שֶׁחַבְרוֹתֶיהָ קוֹרְאוֹת לָהּ זְקֵנָה בְּפָנֶיהָ וְאֵינָהּ מַקְפֶּדֶת. עָבְרוּ עָלֶיהָ שָׁלֹשׁ עוֹנוֹת וְרָאֲתָה וְחָזְרוּ וְעָבְרוּ עָלֶיהָ שָׁלֹשׁ עוֹנוֹת אֲחֵרוֹת אוֹ פָּחוֹת אוֹ יֶתֶר וְרָאֲתָה הֲרֵי הִיא כְּכָל הַנָּשִׁים וּמִטַּמְּאָה לְמַפְרֵעַ:","בְּתוּלָה שֶׁרָאֲתָה דָּם אֲפִלּוּ שׁוֹפַעַת כָּל שִׁבְעָה אוֹ דּוֹלֶפֶת הֲרֵי זֶה פַּעַם אַחַת. רָאֲתָה דָּם וּפָסְקָה וְחָזְרָה וְרָאֲתָה הֲרֵי זֶה שְׁתֵּי פְּעָמִים:","תִּינֹקֶת שֶׁלֹּא הִגִּיעַ זְמַנָּהּ לִרְאוֹת וְרָאֲתָה דָּם פַּעַם רִאשׁוֹנָה וּשְׁנִיָּה דַּיָּהּ שְׁעָתָהּ. רָאֲתָה פַּעַם שְׁלִישִׁית מִטַּמְּאָה לְמַפְרֵעַ. [עָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים וְאַחַר כָּךְ רָאֲתָה דַּיָּהּ שְׁעָתָהּ]. עָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים אֲחֵרִים וְאַחַר כָּךְ רָאֲתָה דַּיָּהּ שְׁעָתָהּ. עָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים אֲחֵרִים וְרָאֲתָה מִטַּמְּאָה לְמַפְרֵעַ:","תִּינֹקֶת שֶׁהִגִּיעַ זְמַנָּהּ לִרְאוֹת וְרָאֲתָה פַּעַם רִאשׁוֹנָה דַּיָּהּ שְׁעָתָהּ שְׁנִיָּה מִטַּמְּאָה לְמַפְרֵעַ. עָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים וְאַחַר כָּךְ רָאֲתָה דַּיָּהּ שְׁעָתָהּ. עָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים אֲחֵרִים וְאַחַר כָּךְ רָאֲתָה מִטַּמְּאָה לְמַפְרֵעַ:","מְעֻבֶּרֶת וּמֵינִיקָה וּזְקֵנָה וּבְתוּלָה שֶׁהִגִּיעַ זְמַנָּם לִרְאוֹת שֶׁרָאוּ רְאִיָּה רִאשׁוֹנָה דַּיָּן שְׁעָתָן. רָאוּ פַּעַם שְׁנִיָּה מִטַּמְּאוֹת לְמַפְרֵעַ כְּכָל הַנָּשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם רָאוּ הָרִאשׁוֹנָה בְּאֹנֶס אַף בַּשְּׁנִיָּה דַּיָּן שְׁעָתָן:","מְעֻבֶּרֶת אוֹ מֵינִיקָה שֶׁרָאֲתָה הַדָּם וְעָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים וְאַחַר כָּךְ רָאֲתָה דַּיָּהּ שְׁעָתָהּ. עָבְרוּ עָלֶיהָ שְׁלֹשָׁה חֳדָשִׁים אֲחֵרִים וְרָאֲתָה פַּעַם שְׁנִיָּה שֶׁהִיא שְׁלִישִׁית לִרְאִיָּה רִאשׁוֹנָה מִטַּמְּאוֹת לְמַפְרֵעַ. הָרוֹאָה דָּם אַחַר דַּם טֹהַר בְּתוֹךְ כ\"ד שָׁעוֹת דַּיָּהּ שְׁעָתָהּ. וְכָל שֶׁדַּיָּהּ שְׁעָתָהּ אַף עַל פִּי שֶׁאֵינָהּ מִטַּמְּאָה לְמַפְרֵעַ צְרִיכָה שֶׁתִּבְדֹּק עַצְמָהּ תָּמִיד. וְכָל אִשָּׁה הַמַּרְבָּה לִבְדֹּק מְשֻׁבַּחַת חוּץ מִן הַנִּדָּה וְיוֹשֶׁבֶת עַל דַּם טֹהַר שֶׁאֵין הַבְּדִיקָה מוֹעֶלֶת לָהֶן כְּלוּם:","חֲכָמִים תִּקְּנוּ לָהֶן לִבְנוֹת יִשְׂרָאֵל לִהְיוֹת בּוֹדְקוֹת עַצְמָן בְּכָל יוֹם בְּשַׁחֲרִית מִפְּנֵי טָהֳרוֹת שֶׁל עַרְבִית וּבְעַרְבִית מִפְּנֵי טָהֳרוֹת שֶׁל שַׁחֲרִית. וְכָל אוֹכֶלֶת תְּרוּמָה בּוֹדֶקֶת בְּשָׁעָה שֶׁאוֹכֶלֶת בִּתְרוּמָה. וְכָל אִשָּׁה בּוֹדֶקֶת בְּשָׁעָה שֶׁעוֹבֶרֶת לְשַׁמֵּשׁ מִטָּתָהּ מִפְּנֵי הַטָּהֳרוֹת. אֲבָל אִם לֹא הָיְתָה עוֹסֶקֶת בְּטָהֳרוֹת אֵינָהּ צְרִיכָה בְּדִיקָה לְבַעֲלָהּ שֶׁכָּל הַנָּשִׁים שֶׁיֵּשׁ לָהֶן וֶסֶת בְּחֶזְקַת טָהֳרָה לְבַעְלֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן נִדָּה:","חֶזְקַת בְּנוֹת יִשְׂרָאֵל שֶׁלֹּא הִגִּיעוּ לְפִרְקָן בְּחֶזְקַת טָהֳרָה וְאֵין הַנָּשִׁים בּוֹדְקוֹת אוֹתָן. אֲבָל מִשֶּׁהִגִּיעוּ לְפִרְקָן צְרִיכוֹת בְּדִיקָה וְנָשִׁים בּוֹדְקוֹת אוֹתָן:","הַחֵרֶשֶׁת וְהַשּׁוֹטָה וּמִי שֶׁנִּטְרְפָה דַּעְתָּהּ בְּחלִי אִם יֵשׁ לָהֶן פִּקְחוֹת מְתַקְּנוֹת אוֹתָן הֲרֵי אֵלּוּ אוֹכְלוֹת בִּתְרוּמָה:","כָּל הַכְּתָמִים הַבָּאִים מִבֵּין יִשְׂרָאֵל בְּחֶזְקַת טֻמְאָה וְהַבָּאִים מִבֵּין הָעַכּוּ\"ם בְּחֶזְקַת טְהוֹרִין. וְהַנִּמְצָאִים בְּעָרֵי יִשְׂרָאֵל טְהוֹרִים שֶׁלֹּא נֶחְשְׁדוּ יִשְׂרָאֵל לְהַשְׁלִיךְ כִּתְמֵיהֶן אֶלָּא מַצְנִיעִין אוֹתָם. לְפִיכָךְ כָּל הַכְּתָמִין הַנִּמְצָאִים בְּכָל מָקוֹם טְהוֹרִין חוּץ מִן הַנִּמְצָאִים בַּחוֹרִים וּסְבִיבוֹת בֵּית הַטֻּמְאָה. וְכֻלָּן טֻמְאָתָן בְּסָפֵק כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל הַכְּתָמִים הַטְּמֵאִין מַעֲבִירִין עֲלֵיהֶן שִׁבְעָה סַמְמָנִין וְאַחַר כָּךְ בֵּין עָבַר הַכֶּתֶם בֵּין לֹא עָבַר מַטְבִּילוֹ וְטָהוֹר. שֶׁאִם לֹא עָבַר כְּלָל הֲרֵי הוּא צֶבַע. וְאִם עָבַר אוֹ כֵּהָה הֲרֵי זֶה כֶּתֶם וּמֵאַחַר שֶׁעָבְרוּ עָלָיו הַסַּמְמָנִין כְּבָר בָּטֵל אַף עַל פִּי שֶׁרִשּׁוּמוֹ נִכָּר. וַאֲפִלּוּ כֶּתֶם שֶׁל דַּם נִדּוּת וַדַּאי כֵּיוָן שֶׁהֶעֱבִיר עָלָיו שִׁבְעָה סַמְמָנִים בָּטֵל וּמַטְבִּילוֹ וְעוֹשֶׂה טָהֳרוֹת עַל גַּבָּיו:","בֶּגֶד שֶׁאָבַד בּוֹ כֶּתֶם מַעֲבִירִין עַל כָּל הַבֶּגֶד שִׁבְעָה סַמְמָנִים וּמַטְבִּילוֹ. אָבְדָה בּוֹ שִׁכְבַת זֶרַע אִם הָיָה חָדָשׁ בּוֹדְקוֹ בְּמַחַט וְאִם הָיָה שָׁחוּק בּוֹדְקוֹ בַּחַמָּה:","בֶּגֶד שֶׁהָיָה עָלָיו כֶּתֶם וְהִטְבִּילוֹ וְעָשָׂה עַל גַּבָּיו טָהֳרוֹת וְאַחַר כָּךְ הֶעֱבִיר עַל הַכֶּתֶם שִׁבְעָה הַסַּמְמָנִים וְלֹא עָבַר הֲרֵי זֶה צֶבַע וְהַטָּהֳרוֹת שֶׁעָשָׂה טְהוֹרוֹת וְאֵין צָרִיךְ לְהַטְבִּילוֹ פַּעַם אַחֶרֶת. וְאִם עָבַר הַכֶּתֶם אוֹ כֵּהָה עֵינוֹ הֲרֵי זֶה כֶּתֶם וְהַטָּהֳרוֹת טְמֵאוֹת. שֶׁהֲרֵי הִקְפִּיד עַל הַכֶּתֶם לַהֲסִירוֹ. וְצָרִיךְ לְהַטְבִּילוֹ פַּעַם שְׁנִיָּה לְטַהֲרוֹ:","כֶּתֶם שֶׁהֶעֱבִיר עָלָיו שִׁשָּׁה סַמְמָנִים וְלֹא עָבַר וְאַחַר כָּךְ הֶעֱבִיר עָלָיו צְפוֹן וְעָבַר הֲרֵי הַטָּהֳרוֹת שֶׁנַּעֲשׂוּ עַל גַּבָּיו טְמֵאוֹת. אַף עַל פִּי שֶׁהַצְּפוֹן מַעֲבִיר הַצֶּבַע הוֹאִיל וְלֹא הֶעֱבִיר עָלָיו שִׁבְעָה הַסַּמְמָנִין הֲרֵי זֶה בְּחֶזְקַת כֶּתֶם. וְשֶׁמָּא אִלּוּ הֶעֱבִיר הַשְּׁבִיעִי הָיָה עוֹבֵר. הֶעֱבִיר עָלָיו שִׁבְעַת הַסַּמְמָנִים וְלֹא עָבַר וְחָזַר וְהֶעֱבִירָן עָלָיו פַּעַם שְׁנִיָּה וְעָבַר כָּל הַטָּהֳרוֹת שֶׁנַּעֲשׂוּ עַל גַּבָּיו בֵּין תִּכְבֹּסֶת רִאשׁוֹנָה לַשְּׁנִיָּה טְהוֹרוֹת. וְכָל הַטָּהֳרוֹת שֶׁנַּעֲשׂוּ עַל גַּבָּיו אַחַר תִּכְבֹּסֶת שְׁנִיָּה טְמֵאוֹת. הוֹאִיל וְגִלָּה דַּעְתּוֹ שֶׁהוּא מַקְפִּיד עָלָיו וְרוֹצֶה לְהוֹצִיא רִשּׁוּמוֹ הֲרֵי זֶה טָמֵא עַד שֶׁיְּבַטְּלוֹ וְיַטְבִּילוֹ. כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי בִּיאָה שִׁבְעָה הַסַּמְמָנִין שֶׁמַּעֲבִירִין עַל הַכֶּתֶם מַה הֵן וְהֵיאַךְ מַעֲבִירִין אוֹתָן:","הָאִשָּׁה שֶׁמֵּתָה וְיָצְאָה מִמֶּנָּה דָּם מְטַמֵּא מִשּׁוּם כֶּתֶם שֶׁהַמָּקוֹר מְקוֹמוֹ טָמֵא. אַף עַל פִּי שֶׁיָּצָא הַדָּם אַחַר שֶׁמֵּתָה וְאֵין כָּאן נִדָּה הוֹאִיל וּמִמָּקוֹם טָמֵא יָצָא מְטַמֵּא טֻמְאַת כְּתָמִים. וְאִם הָיָה בּוֹ רְבִיעִית מְטַמֵּא בְּאֹהֶל וּמְטַמֵּא מִשּׁוּם כֶּתֶם:"],"Mishneh Torah, Tithes 2":["אֵינּוֹ חַיָּב לְהַפְרִישׁ מִן הַתּוֹרָה אֶלָּא הַגּוֹמֵר פֵּרוֹתָיו לְאָכְלָן לְעַצְמוֹ אֲבָל הַגּוֹמְרָן לְמָכְרָן פָּטוּר מִן הַתּוֹרָה וְחַיָּב מִדִּבְרֵיהֶם שֶׁנֶּאֱמַר (דברים יד כב) \"עַשֵּׂר תְּעַשֵּׂר\" וְגוֹ' (דברים יד כג) \"וְאָכַלְתָּ\" אֵינוֹ חַיָּב אֶלָּא הַגּוֹמֵר תְּבוּאָתוֹ לְאָכְלָהּ:","וְכֵן הַלּוֹקֵחַ פָּטוּר מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים יד כב) \"תְּבוּאַת זַרְעֶךָ\". וְחַיָּב מִדִּבְרֵיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלְּקָחָן אַחַר שֶׁנִּגְמְרוּ מְלַאכְתָּן בְּיַד מוֹכֵר. אֲבָל אִם נִגְמְרוּ בְּיַד לוֹקֵחַ חַיָּב לְעַשֵּׂר מִן הַתּוֹרָה:","פֵּרוֹת שֶׁאֵינָן רְאוּיִים לַאֲכִילָה מִקָּטְנָן כְּגוֹן הַבֹּסֶר וְכַיּוֹצֵא בּוֹ אֵינָן חַיָּבִין בְּמַעֲשֵׂר עַד שֶׁיִּגְדְּלוּ וְיֵעָשׂוּ אֹכֶל שֶׁנֶּאֱמַר (ויקרא כז ל) \"מִזֶּרַע הָאָרֶץ מִפְּרִי הָעֵץ\" עַד שֶׁיִּהְיֶה פְּרִי. וְכֵן הַתְּבוּאָה וְהַקִּטְנִיּוֹת שֶׁנֶּאֱמַר (דברים יד כב) \"אֵת כָּל תְּבוּאַת זַרְעֶךָ\" עַד שֶׁתֵּעָשֶׂה תְּבוּאָה וְזוֹ הִיא עוֹנַת הַמַּעַשְׂרוֹת. וְקֹדֶם שֶׁתַּגִּיעַ הַתְּבוּאָה וְהַפֵּרוֹת לְעוֹנָה זוֹ מֻתָּר לֶאֱכל מֵהֶן כָּל מַה שֶּׁיִּרְצֶה וּבְכָל דֶּרֶךְ שֶׁיִּרְצֶה:","פֵּרוֹת שֶׁהֵן רְאוּיִין לַאֲכִילָה בְּקָטְנָן כְּגוֹן הַקִּשּׁוּאִים וְהַמְּלָפְפוֹנוֹת שֶׁאֵין מַנִּיחִין אוֹתָן אֶלָּא כְּדֵי לְהוֹסִיף בְּגוּפָן בִּלְבַד אֲבָל רְאוּיִין הֵן מִתְּחִלָּה לַאֲכִילָה. הֲרֵי אֵלּוּ חַיָּבִין בְּמַעֲשֵׂר בְּקָטְנָן. שֶׁמִּתְּחִלַּת יְצִיאָתָן בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת:","אֵי זוֹ הִיא עוֹנַת הַמַּעַשְׂרוֹת. מִשֶּׁיַּגִּיעוּ הַפֵּרוֹת לְהַזְרִיעַ וְלִצְמֹחַ הַכּל לְפִי מַה שֶּׁהוּא הַפְּרִי. כֵּיצַד. הַתְּאֵנִים מִשֶּׁיֵּעָשׂוּ רַכִּים עַד שֶׁיְּהוּ רְאוּיִים לַאֲכִילָה אַחַר כ\"ד שָׁעוֹת מִשְּׁעַת אֲסִיפָתָן. הָעֲנָבִים וְהַבְּאוּשִׁים וְהֵם הָעֲנָבִים הַדַּקִּים הַמִּדְבָּרִיּוֹת מִשֶּׁיֵּרָאֶה הַחַרְצָן שֶׁלָּהֶם מִבַּחוּץ. הָרִמּוֹנִים מִשֶּׁיִּמַּס הַפֶּרַח שֶׁלָּהֶן בֵּין הָאֶצְבָּעוֹת וְיֵצֵא מִמֶּנּוּ מַיִם. הַתְּמָרִים מִשֶּׁיִּפָּתְחוּ כִּשְׂאוֹר. הָאֲפַרְסֵקִין מִשֶּׁיַּטִּילוּ גִּידִים אֲדֻמִּים. הָאֱגוֹזִים מִשֶּׁיִּתְפָּרֵשׁ הָאֹכֶל מֵהַקְּלִפָּה הַחִיצוֹנָה. הַשְּׁקֵדִים הַמְּתוּקִים מִשֶּׁתִּתְפָּרֵשׁ קְלִפָּתָן הַחִיצוֹנָה. הַמָּרִים פְּטוּרִין לְעוֹלָם. וּשְׁאָר כָּל בַּעֲלֵי קְלִפּוֹת כְּגוֹן הָאִצְטְרֻבּוֹלִין וְהַלּוֹט וְהַבָּטְנִים מִשֶּׁיַּעֲשׂוּ קְלִפָּה הַתַּחְתּוֹנָה הַסְּמוּכָה לָאֹכֶל. הַזֵּיתִים מִשֶּׁיַּעֲשׂוּ שֶׁמֶן אֶחָד מִתִּשְׁעָה מִמַּה שֶּׁהֵן רְאוּיִין לַעֲשׂוֹת כְּשֶׁיִּגָּמְרוּ. וְזֶה שְׁלִישׁ שֶׁלָּהֶן. הַתַּפּוּחִים וְהָאֶתְרוֹגִים מִשֶּׁיִּתְעַגְּלוּ מִפְּנֵי שֶׁהֵן רְאוּיִין לַאֲכִילָה כְּשֶׁהֵם קְטַנִּים. הַתּוּתִים וְהָאוֹג מִשֶּׁיַּאֲדִימוּ. וְכֵן כָּל שֶׁדַּרְכָּן לְהַאֲדִים מִשֶּׁיַּאֲדִימוּ. הֶחָרוּבִין מִשֶּׁיֵּעָשׂוּ נְקֻדּוֹת נְקֻדּוֹת שְׁחוֹרוֹת. וְכֵן כָּל שֶׁדַּרְכָּן לְהַשְׁחִיר מִשֶּׁיִּנָּקְדוּ. הָאֲגַסִּים וְהַקְרוּסְטְמָלִין וְהַפְּרִישִׁים וְהָעוֹזְרָדִין מִשֶּׁיֵּעָשׂוּ קַרָחוֹת קַרָחוֹת לְבָנוֹת. וְכֵן כָּל שֶׁדַּרְכָּן לְלַבֵּן מִשֶּׁיִּקְרְחוּ קַרָחוֹת. הַתְּבוּאָה מִשֶּׁתָּבִיא שְׁלִישׁ. הַתִּלְתָּן מִשֶּׁתִּהְיֶה זַרְעָהּ רָאוּי לִצְמִיחָה אִם נִזְרַע. וּבְיָרָק הַקִּשּׁוּאִין וְהַדְּלוּעִין וְהָאֲבַטִּיחִין וְהַמְּלָפְפוֹנוֹת וְכָל כַּיּוֹצֵא בָּהֶן חַיָּבִין בְּקָטְנָן כְּמוֹ שֶׁבֵּאַרְנוּ. וּשְׁאָר הַיָּרָק שֶׁאֵינוֹ רָאוּי לַאֲכִילָה עַד שֶׁיַּגְדִּיל אֵינוֹ חַיָּב עַד שֶׁיְּהֵא רָאוּי לַאֲכִילָה. אֶשְׁכּוֹל שֶׁהִגִּיעַ בּוֹ אֲפִלּוּ גַּרְגִּיר יְחִידִי כֻּלּוֹ חִבּוּר לְמַעַשְׂרוֹת וּכְאִלּוּ הִגִּיעַ כֻּלּוֹ. וְלֹא אוֹתוֹ אֶשְׁכּוֹל בִּלְבַד אֶלָּא כָּל הָרוּחַ שֶׁיֵּשׁ בָּהּ אוֹתָהּ הַגֶּפֶן שֶׁיֵּשׁ בָּהּ הָאֶשְׁכּוֹל. וְכֵן רִמּוֹן שֶׁהִגִּיעַ בָּהּ אֲפִלּוּ פְּרֵדָה אַחַת כֻּלָּהּ חִבּוּר:","לֹא יִמְכֹּר אָדָם פֵּרוֹתָיו מִשֶּׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת לְמִי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת. וְאִם בִּכְּרוּ נוֹטֵל אֶת הַבִּכּוּרוֹת וּמֻתָּר לִמְכֹּר הַשְּׁאָר שֶׁעֲדַיִן לֹא הִגִּיעַ לְעוֹנַת הַמַּעַשְׂרוֹת. וְכֵן לֹא יִמְכֹּר אָדָם אֶת גִּפְתּוֹ וְאֶת זַגָּיו לְמִי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת לְהוֹצִיא מֵהֶן מַשְׁקִין. שֶׁהַמַּשְׁקִין הַיּוֹצְאִין מֵהֶם חַיָּבִין בְּמַעַשְׂרוֹת. וְלֹא אֶת תִּבְנוֹ לִלְקֹט מִמֶּנּוּ תְּבוּאָה לְמִי שֶׁאֵינוֹ נֶאֱמָן שֶׁהַתְּבוּאָה שֶׁתִּלָּקֵט מִן הַתֶּבֶן חַיֶּבֶת בְּמַעֲשֵׂר:","שִׁמְרֵי יַיִן שֶׁנָּתַן עֲלֵיהֶם מַיִם וְסִנְּנָן אִם נָתַן שְׁלֹשָׁה וּמָצָא אַרְבָּעָה מוֹצִיא מַעֲשֵׂר מִזֶּה הַיֶּתֶר מִמָּקוֹם אַחֵר. וְאֵינוֹ מַפְרִישׁ עָלָיו תְּרוּמָה שֶׁהַתּוֹרֵם בַּתְּחִלָּה בְּלִבּוֹ עַל הַכּל כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְרוּמָה. מָצָא פָּחוֹת מֵאַרְבָּעָה אַף עַל פִּי שֶׁמָּצָא יֶתֶר עַל מִדָּתוֹ וְאַף עַל פִּי שֶׁיֵּשׁ בָּהֶן טַעַם יַיִן פָּטוּר:","הַמַּקְדִּישׁ פֵּרוֹתָיו כְּשֶׁהֵן מְחֻבָּרִין עַד שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעֲשֵׂר וּפְדָאָן וְאַחַר שֶׁפְּדָאָן הִגִּיעוּ חַיָּבִין בְּמַעֲשֵׂר. וְאִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת וְהֵם בְּיַד הַגִּזְבָּר וְאַחַר כָּךְ פְּדָאָן פְּטוּרִין:"],"Mishneh Torah, Torah Study 5":["כְּשֵׁם שֶׁאָדָם מְצֻוֶּה בִּכְבוֹד אָבִיו וְיִרְאָתוֹ כָּךְ הוּא חַיָּב בִּכְבוֹד רַבּוֹ וְיִרְאָתוֹ יֶתֶר מֵאָבִיו. שֶׁאָבִיו מְבִיאוֹ לְחַיֵּי הָעוֹלָם הַזֶּה וְרַבּוֹ שֶׁלִּמְּדוֹ חָכְמָה מְבִיאוֹ לְחַיֵּי הָעוֹלָם הַבָּא. רָאָה אֲבֵדַת אָבִיו וַאֲבֵדַת רַבּוֹ שֶׁל רַבּוֹ קוֹדֶמֶת לְשֶׁל אָבִיו. אָבִיו וְרַבּוֹ נוֹשְׂאִים בְּמַשָּׂא מֵנִיחַ אֶת שֶׁל רַבּוֹ וְאַחַר כָּךְ שֶׁל אָבִיו. אָבִיו וְרַבּוֹ שְׁבוּיִים בַּשִּׁבְיָה פּוֹדֶה אֶת רַבּוֹ וְאַחַר כָּךְ פּוֹדֶה אֶת אָבִיו. וְאִם הָיָה אָבִיו תַּלְמִיד חָכָם פּוֹדֶה אֶת אָבִיו תְּחִלָּה. וְכֵן אִם הָיָה אָבִיו תַּלְמִיד חָכָם אַף עַל פִּי שֶׁאֵינוֹ שָׁקוּל כְּנֶגֶד רַבּוֹ מֵשִׁיב אֲבֵדָתוֹ וְאַחַר כָּךְ מֵשִׁיב אֲבֵדַת רַבּוֹ. וְאֵין לְךָ כָּבוֹד גָּדוֹל מִכְּבוֹד הָרַב וְלֹא מוֹרָא מִמּוֹרָא הָרַב. אָמְרוּ חֲכָמִים (משנה אבות ד יב) \"מוֹרָא רַבָּךְ כְּמוֹרָא שָׁמַיִם\". לְפִיכָךְ אָמְרוּ כָּל הַחוֹלֵק עַל רַבּוֹ כְּחוֹלֵק עַל הַשְּׁכִינָה שֶׁנֶּאֱמַר (במדבר כו ט) \"בְּהַצֹּתָם עַל ה'\". וְכָל הָעוֹשֶׂה מְרִיבָה עִם רַבּוֹ כְּעוֹשֶׂה מְרִיבָה עִם הַשְּׁכִינָה שֶׁנֶּאֱמַר (במדבר כ יג) \"אֲשֶׁר רָבוּ בְנֵי יִשְׂרָאֵל אֶת ה' וַיִּקָּדֵשׁ בָּם\". וְכָל הַמִּתְרַעֵם עַל רַבּוֹ כְּמִתְרַעֵם עַל ה' שֶׁנֶּאֱמַר (שמות טז ח) \"לֹא עָלֵינוּ תְלֻנֹתֵיכֶם כִּי עַל ה'\". וְכָל הַמְהַרְהֵר אַחַר רַבּוֹ כְּאִלּוּ מְהַרְהֵר אַחַר שְׁכִינָה שֶׁנֶּאֱמַר (במדבר כא ה) \"וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמשֶׁה\":","אֵיזֶהוּ חוֹלֵק עַל רַבּוֹ. זֶה שֶׁקּוֹבֵעַ לוֹ מִדְרָשׁ וְיוֹשֵׁב וְדוֹרֵשׁ וּמְלַמֵּד שֶׁלֹּא בִּרְשׁוּת רַבּוֹ וְרַבּוֹ קַיָּם וְאַף עַל פִּי שֶׁרַבּוֹ בִּמְדִינָה אַחֶרֶת. וְאָסוּר לָאָדָם לְהוֹרוֹת בִּפְנֵי רַבּוֹ לְעוֹלָם. וְכָל הַמּוֹרֶה הֲלָכָה בִּפְנֵי רַבּוֹ חַיָּב מִיתָה:","הָיָה בֵּינוֹ וּבֵין רַבּוֹ שְׁנֵים עָשָׂר מִיל וְשָׁאַל לוֹ אָדָם דְּבַר הֲלָכָה מֻתָּר לְהָשִׁיב. וּלְהַפְרִישׁ מִן הָאִסּוּר אֲפִלּוּ בִּפְנֵי רַבּוֹ מֻתָּר לְהוֹרוֹת. כֵּיצַד. כְּגוֹן שֶׁרָאָה אָדָם עוֹשֶׂה דָּבָר הָאָסוּר מִפְּנֵי שֶׁלֹּא יָדַע בְּאִסּוּרוֹ אוֹ מִפְּנֵי רִשְׁעוֹ יֵשׁ לוֹ לְהַפְרִישׁוֹ וְלוֹמַר לוֹ דָּבָר זֶה אָסוּר וַאֲפִלּוּ בִּפְנֵי רַבּוֹ וְאַף עַל פִּי שֶׁלֹּא נָתַן לוֹ רַבּוֹ רְשׁוּת. שֶׁכָּל מָקוֹם שֶׁיֵּשׁ חִלּוּל הַשֵּׁם אֵין חוֹלְקִין כָּבוֹד לָרַב. בַּמֶּה דְּבָרִים אֲמוּרִים. בְּדָבָר שֶׁנִּקְרָה מִקְרֶה. אֲבָל לִקְבֹּעַ עַצְמוֹ לְהוֹרָאָה וְלֵישֵׁב וּלְהוֹרוֹת לְכָל שׁוֹאֵל אֲפִלּוּ הוּא בְּסוֹף הָעוֹלָם וְרַבּוֹ בְּסוֹף הָעוֹלָם אָסוּר לוֹ לְהוֹרוֹת עַד שֶׁיָּמוּת רַבּוֹ אֶלָּא אִם כֵּן נָטַל רְשׁוּת מֵרַבּוֹ. וְלֹא כָּל מִי שֶׁמֵּת רַבּוֹ מֻתָּר לוֹ לֵישֵׁב וּלְהוֹרוֹת בַּתּוֹרָה. אֶלָּא אִם כֵּן הָיָה תַּלְמִיד שֶׁהִגִּיעַ לְהוֹרָאָה:","וְכָל תַּלְמִיד שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה הֲרֵי זֶה רָשָׁע שׁוֹטֶה וְגַס הָרוּחַ. וְעָלָיו נֶאֱמַר (משלי ז כו) \"כִּי רַבִּים חֲלָלִים הִפִּילָה\" וְגוֹ'. וְכֵן חָכָם שֶׁהִגִּיעַ לְהוֹרָאָה וְאֵינוֹ מוֹרֶה הֲרֵי זֶה מוֹנֵעַ תּוֹרָה וְנוֹתֵן מִכְשׁוֹלוֹת לִפְנֵי הָעִוְּרִים וְעָלָיו נֶאֱמַר (משלי ז כו) \"וַעֲצֻמִים כָּל הֲרֻגֶיהָ\". אֵלּוּ הַתַּלְמִידִים הַקְּטַנִּים שֶׁלֹּא הִרְבּוּ תּוֹרָה כָּרָאוּי וְהֵם מְבַקְּשִׁים לְהִתְגַּדֵּל בִּפְנֵי עַמֵּי הָאָרֶץ וּבֵין אַנְשֵׁי עִירָם וְקוֹפְצִין וְיוֹשְׁבִין בָּרֹאשׁ לְדִין וּלְהוֹרוֹת בְּיִשְׂרָאֵל הֵם הַמַּרְבִּים הַמַּחֲלֹקֶת וְהֵם הַמַּחֲרִיבִים אֶת הָעוֹלָם וְהַמְכַבִּין נֵרָהּ שֶׁל תּוֹרָה וְהַמְחַבְּלִים כֶּרֶם ה' צְבָאוֹת. עֲלֵיהֶם אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (שיר השירים ב טו) \"אֶחֱזוּ לָנוּ שׁוּעָלִים שׁוּעָלִים קְטַנִּים מְחַבְּלִים כְּרָמִים\":","וְאָסוּר לוֹ לְתַלְמִיד לִקְרוֹת לְרַבּוֹ בִּשְׁמוֹ וַאֲפִלּוּ שֶׁלֹּא בְּפָנָיו. וְהוּא שֶׁיִּהְיֶה הַשֵּׁם פֶּלְאִי שֶׁכָּל הַשּׁוֹמֵעַ יֵדַע שֶׁהוּא פְּלוֹנִי. וְלֹא יַזְכִּיר שְׁמוֹ בְּפָנָיו וַאֲפִלּוּ לִקְרוֹת לַאֲחֵרִים שֶׁשְּׁמָם כְּשֵׁם רַבּוֹ כְּדֶרֶךְ שֶׁעוֹשֶׂה בְּשֵׁם אָבִיו. אֶלָּא יְשַׁנֶּה אֶת שְׁמָם אֲפִלּוּ לְאַחַר מוֹתָם. וְלֹא יִתֵּן שָׁלוֹם לְרַבּוֹ אוֹ יַחֲזִיר לוֹ שָׁלוֹם כְּדֶרֶךְ שֶׁנּוֹתְנִים לְרֵעִים וּמַחֲזִירִים זֶה לָזֶה. אֶלָּא שׁוֹחֶה לְפָנָיו וְאוֹמֵר לוֹ בְּיִרְאָה וְכָבוֹד שָׁלוֹם עָלֶיךָ רַבִּי. וְאִם נָתַן לוֹ רַבּוֹ שָׁלוֹם יַחֲזִיר לוֹ שָׁלוֹם עָלֶיךָ רַבִּי וּמוֹרִי:","וְכֵן לֹא יַחֲלֹץ תְּפִלָּיו לִפְנֵי רַבּוֹ. וְלֹא יָסֵב אֶלָּא יוֹשֵׁב כְּיוֹשֵׁב לִפְנֵי הַמֶּלֶךְ. וְלֹא יִתְפַּלֵּל לֹא לִפְנֵי רַבּוֹ וְלֹא לְאַחַר רַבּוֹ וְלֹא בְּצַד רַבּוֹ. וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לוֹ לְהַלֵּךְ בְּצִדּוֹ. אֶלָּא יִתְרַחֵק לְאַחַר רַבּוֹ וְלֹא יְהֵא מְכַוֵּן כְּנֶגֶד אֲחוֹרָיו וְאַחַר כָּךְ יִתְפַּלֵּל. וְלֹא יִכָּנֵס עִם רַבּוֹ בַּמֶּרְחָץ. וְלֹא יֵשֵׁב בִּמְקוֹם רַבּוֹ. וְלֹא יַכְרִיעַ דְּבָרָיו בְּפָנָיו. וְלֹא יִסְתֹּר אֶת דְּבָרָיו. וְלֹא יֵשֵׁב לְפָנָיו עַד שֶׁיֹּאמַר לוֹ שֵׁב. וְלֹא יַעֲמֹד מִלְּפָנָיו עַד שֶׁיֹּאמַר לוֹ עֲמֹד אוֹ עַד שֶׁיִּטּל רְשׁוּת לַעֲמֹד. וּכְשֶׁיִּפָּטֵר מֵרַבּוֹ לֹא יַחֲזֹר לוֹ לַאֲחוֹרָיו אֶלָּא נִרְתָּע לַאֲחוֹרָיו וּפָנָיו כְּנֶגֶד פָּנָיו:","וְחַיָּב לַעֲמֹד מִפְּנֵי רַבּוֹ מִשֶּׁיִּרְאֶנּוּ מֵרָחוֹק מְלֹא עֵינָיו עַד שֶׁיִּתְכַּסֶּה מִמֶּנּוּ וְלֹא יִרְאֶה קוֹמָתוֹ וְאַחַר כָּךְ יֵשֵׁב. וְחַיָּב אָדָם לְהַקְבִּיל פְּנֵי רַבּוֹ בָּרֶגֶל:","אֵין חוֹלְקִין כָּבוֹד לְתַלְמִיד בִּפְנֵי רַבּוֹ אֶלָּא אִם כֵּן דֶּרֶךְ רַבּוֹ לַחֲלֹק לוֹ כָּבוֹד. וְכָל הַמְּלָאכוֹת שֶׁהָעֶבֶד עוֹשֶׂה לְרַבּוֹ תַּלְמִיד עוֹשֶׂה לְרַבּוֹ. וְאִם הָיָה בְּמָקוֹם שֶׁאֵין מַכִּירִין אוֹתוֹ וְלֹא הָיוּ לוֹ תְּפִלִּין וְחָשׁ שֶׁמָּא יֹאמְרוּ עֶבֶד הוּא אֵינוֹ נוֹעֵל לוֹ מִנְעָלוֹ וְאֵינוֹ חוֹלְצוֹ. וְכָל הַמּוֹנֵעַ תַּלְמִידוֹ מִלְּשַׁמְּשׁוֹ מוֹנֵעַ מִמֶּנּוּ חֶסֶד וּפוֹרֵק מִמֶּנּוּ יִרְאַת שָׁמַיִם. וְכָל תַּלְמִיד שֶׁמְּזַלְזֵל דָּבָר מִכָּל כְּבוֹד רַבּוֹ גּוֹרֵם לַשְּׁכִינָה שֶׁתִּסְתַּלֵּק מִיִּשְׂרָאֵל:","רָאָה רַבּוֹ עוֹבֵר עַל דִּבְרֵי תּוֹרָה אוֹמֵר לוֹ לִמַּדְתָּנוּ רַבֵּנוּ כָּךְ וְכָךְ. וְכָל זְמַן שֶׁמַּזְכִּיר שְׁמוּעָה בְּפָנָיו אוֹמֵר לוֹ כָּךְ לִמַּדְתָּנוּ רַבֵּנוּ. וְאַל יֹאמַר דָּבָר שֶׁלֹּא שָׁמַע מֵרַבּוֹ עַד שֶׁיַּזְכִּיר שֵׁם אוֹמְרוֹ. וּכְשֶׁיָּמוּת רַבּוֹ קוֹרֵעַ כָּל בְּגָדָיו עַד שֶׁהוּא מְגַלֶּה אֶת לִבּוֹ וְאֵינוֹ מְאַחֶה לְעוֹלָם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּרַבּוֹ מֻבְהָק שֶׁלָּמַד מִמֶּנּוּ רֹב חָכְמָתוֹ. אֲבָל אִם לֹא לָמַד מִמֶּנּוּ רֹב חָכְמָתוֹ הֲרֵי זֶה תַּלְמִיד חָבֵר וְאֵינוֹ חַיָּב בִּכְבוֹדוֹ בְּכָל אֵלּוּ הַדְּבָרִים. אֲבָל עוֹמֵד מִלְּפָנָיו וְקוֹרֵעַ עָלָיו כְּשֵׁם שֶׁהוּא קוֹרֵעַ עַל כָּל הַמֵּתִים שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם. אֲפִלּוּ לֹא לָמַד מִמֶּנּוּ אֶלָּא דָּבָר אֶחָד בֵּין קָטָן בֵּין גָּדוֹל עוֹמֵד מִלְּפָנָיו וְקוֹרֵעַ עָלָיו:","וְכָל תַּלְמִיד חָכָם שֶׁדֵּעוֹתָיו מְכֻוָּנוֹת אֵינוֹ מְדַבֵּר בִּפְנֵי מִי שֶׁהוּא גָּדוֹל מִמֶּנּוּ בְּחָכְמָה אַף עַל פִּי שֶׁלֹּא לָמַד מִמֶּנּוּ כְּלוּם:","הָרַב הַמֻּבְהָק שֶׁרָצָה לִמְחל עַל כְּבוֹדוֹ בְּכָל הַדְּבָרִים הָאֵלּוּ אוֹ בְּאֶחָד מֵהֶן לְכָל תַּלְמִידָיו אוֹ לְאֶחָד מֵהֶן הָרְשׁוּת בְּיָדוֹ. וְאַף עַל פִּי שֶׁמָּחַל חַיָּב הַתַּלְמִיד לְהַדְּרוֹ וַאֲפִלּוּ בְּשָׁעָה שֶׁמָּחַל:","כְּשֵׁם שֶׁהַתַּלְמִידִים חַיָּבִין בִּכְבוֹד הָרַב כָּךְ הָרַב צָרִיךְ לְכַבֵּד אֶת תַּלְמִידָיו וּלְקָרְבָן. כָּךְ אָמְרוּ חֲכָמִים (משנה אבות ד יב) \"יְהִי כְּבוֹד תַּלְמִידְךָ חָבִיב עָלֶיךָ כְּשֶׁלְּךָ\". וְצָרִיךְ אָדָם לְהִזָּהֵר בְּתַלְמִידָיו וּלְאָהֳבָם שֶׁהֵם הַבָּנִים הַמְהַנִּים לָעוֹלָם הַזֶּה וְלָעוֹלָם הַבָּא:","הַתַּלְמִידִים מוֹסִיפִין חָכְמַת הָרַב וּמַרְחִיבִין לִבּוֹ. אָמְרוּ חֲכָמִים הַרְבֵּה חָכְמָה לָמַדְתִּי מֵרַבּוֹתַי וְיוֹתֵר מֵחֲבֵרַי וּמִתַּלְמִידַי יוֹתֵר מִכֻּלָּם. וּכְשֵׁם שֶׁעֵץ קָטָן מַדְלִיק אֶת הַגָּדוֹל כָּךְ תַּלְמִיד קָטָן מְחַדֵּד הָרַב עַד שֶׁיּוֹצִיא מִמֶּנּוּ בִּשְׁאֵלוֹתָיו חָכְמָה מְפֹאָרָה:"],"Mishneh Torah, Transmission of the Oral Law 18":["רָב חִבַּר סִפְרָא וְסִפְרֵי לְבָאַר וּלְהוֹדִיעַ עִיקְרֵי הַמִּשְׁנָה, וְרִבִּי חִיָּא חִבַּר הַתּוֹסֶפְתָּא לְבָאַר עִנְיְנֵי הַמִּשְׁנָה. וְכֵן רִבִּי הוֹשַׁעְיָה וּבַר קַפָּרָא חִבְּרוּ בַּרַּיְתּוֹת לְבָאַר דִּבְרֵי הַמִּשְׁנָה, וְרִבִּי יוֹחָנָן חִבַּר הַתַּלְמוּד הַיְּרוּשְׁלְמִי בְּאֶרֶץ יִשְׂרָאֵל אַחַר חָרְבַּן הַבַּיִת בְּקֵרוּב מִשְּׁלוֹשׁ מֵאוֹת שָׁנָה."],"Mishneh Torah, Transmission of the Oral Law 29":["נִמְצָא רַבִּינָא וְרָב אַשֵׁי וְחַבְרֵיהֶם, סוֹף גְּדוֹלֵי חַכְמֵי יִשְׂרָאֵל הַמַּעְתִּיקִים תּוֹרָה שֶׁבְּעַל פֶּה, וְשֶׁגָּזְרוּ גְּזֵרוֹת וְהִתְקִינוּ תַּקָּנוֹת וְהִנְהִיגוּ מִנְהָגוֹת וּפָשְׁטוּ גְּזֵרוֹתָם וְתַקָּנוֹתָם וּמִנְהֲגוֹתָם בְּכָל יִשְׂרָאֵל, בְּכָל מְקוֹמוֹת מוֹשְׁבוֹתֵיהֶם."],"Mishneh Torah, Transmission of the Oral Law 4":["אַף עַל פִּי שֶׁלֹּא נִכְתְּבָה תּוֹרָה שֶׁבְּעַל פֶּה, לִמְּדָהּ מֹשֶׁה רַבֵּנוּ כֻּלָּהּ בְּבֵית דִּינוֹ לְשִׁבְעִים זְקֵנִים; וְאֶלְעָזָר וּפִינְחָס וִיהוֹשׁוּעַ, שְׁלָשְׁתָּן קִבְּלוּ מִמֹּשֶׁה. וְלִיהוֹשׁוּעַ שְׁהוּא תַּלְמִידוֹ שֶׁלְּמֹשֶׁה רַבֵּנוּ, מָסַר תּוֹרָה שֶׁבְּעַל פֶּה וְצִוָּהוּ עָלֶיהָ; וְכֵן יְהוֹשׁוּעַ, כָּל יְמֵי חַיָּיו לִמַּד עַל פֶּה."],"Mishneh Torah, Trespass 1":["אָסוּר לְהֶדְיוֹט לֵהָנוֹת מִקָּדְשֵׁי הַשֵּׁם. בֵּין מִדְּבָרִים הַקְּרֵבִין עַל גַּבֵּי הַמִּזְבֵּחַ. בֵּין מִקָּדְשֵׁי בֶּדֶק הַבַּיִת. וְכָל הַנֶּהֱנֶה בִּשְׁוֵה פְּרוּטָה מִקָּדְשֵׁי הַשֵּׁם מָעַל:","דְּבָרִים שֶׁהֻתְּרוּ בַּאֲכִילָה מִן הַקָּרְבָּנוֹת. כְּגוֹן בְּשַׂר חַטָּאת וְאָשָׁם אַחַר זְרִיקַת דָּמָן אוֹ שְׁתֵּי הַלֶּחֶם אַחַר זְרִיקַת דַּם שְׁנֵי הַכְּבָשִׂים אֵין בָּהֶן מְעִילָה. אֲפִלּוּ אָכַל הַזָּר מֵאֵלּוּ וְכַיּוֹצֵא בָּהֶן. הוֹאִיל וְהֵן מֻתָּרִין לְמִקְצָת בְּנֵי אָדָם לֵהָנוֹת בָּהֶן כָּל הַנֶּהֱנֶה מֵהֶן לֹא מָעַל. וַאֲפִלּוּ נִפְסְלוּ וְנֶאֶסְרוּ בַּאֲכִילָה הוֹאִיל וְהָיְתָה לָהֶן שְׁעַת הֶתֵּר אֵין חַיָּבִין עֲלֵיהֶן מְעִילָה:","כָּל הַמּוֹעֵל בְּזָדוֹן לוֹקֶה וּמְשַׁלֵּם מַה שֶּׁפָּגַם מִן הַקֹּדֶשׁ בְּרֹאשׁוֹ. וְאַזְהָרָה שֶׁל מְעִילָה מִזֶּה שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ\" וְגוֹ' (דברים יב יז) \"וּנְדָרֶיךָ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לָאוֹכֵל מִבְּשַׂר עוֹלָה הוֹאִיל וְכֻלּוֹ לַשֵּׁם. וְהוּא הַדִּין לִשְׁאָר כָּל קֹדֶשׁ שֶׁהוּא לַהַשֵּׁם לְבַדּוֹ בֵּין מִקָּדְשֵׁי הַמִּזְבֵּחַ בֵּין מִקָּדְשֵׁי בֶּדֶק הַבַּיִת אִם נֶהֱנֶה בָּהֶן שְׁוֵה פְּרוּטָה לוֹקֶה. מָעַל בִּשְׁגָגָה מְשַׁלֵּם מַה שֶּׁנֶּהֱנָה וְתוֹסֶפֶת חֹמֶשׁ. וּמֵבִיא אַיִל בִּשְׁנֵי סְלָעִים וּמַקְרִיבוֹ אָשָׁם וּמִתְכַּפֵּר לוֹ וְזֶהוּ הַנִּקְרָא אֲשַׁם מְעִילוֹת. שֶׁנֶּאֱמַר (ויקרא ה טו) \"וְחָטְאָה בִּשְׁגָגָה מִקָּדְשֵׁי ה' וְהֵבִיא אֶת אֲשָׁמוֹ\" וְגוֹ' (ויקרא ה טז) \"וְאֵת אֲשֶׁר חָטָא מִן הַקֹּדֶשׁ יְשַׁלֵּם וְאֶת חֲמִישִׁתוֹ\" וְגוֹ'. וְשִׁלּוּם הַקֶּרֶן בְּתוֹסֶפֶת חֹמֶשׁ עִם הֲבָאַת הַקָּרְבָּן מִצְוַת עֲשֵׂה:","תַּשְׁלוּם הַקֶּרֶן וַהֲבָאַת הָאָשָׁם מְעַכְּבִין הַכַּפָּרָה. וְאֵין הַחֹמֶשׁ מְעַכֵּב. שֶׁנֶּאֱמַר (ויקרא ה טז) \"בְּאֵיל הָאָשָׁם\". אַיִל וְאָשָׁם מְעַכְּבִין וְאֵין הַחֹמֶשׁ מְעַכֵּב:","הֵבִיא מְעִילָתוֹ עַד שֶׁלֹּא הֵבִיא אֲשָׁמוֹ לֹא יָצָא. נִסְתַּפֵּק לוֹ אִם מָעַל אוֹ לֹא מָעַל פָּטוּר מִן הַתַּשְׁלוּמִין וּמִן הַקָּרְבָּן. וְהַחֹמֶשׁ הֲרֵי הוּא כִּתְחִלַּת הַהֶקְדֵּשׁ וְאִם נֶהֱנָה בּוֹ מוֹסִיף חֹמֶשׁ עַל הַחֹמֶשׁ. וּכְבָר בֵּאַרְנוּ כַּמָּה פְּעָמִים שֶׁהַחֹמֶשׁ אֶחָד מֵאַרְבָּעָה מִן הַקֶּרֶן עַד שֶׁיִּהְיֶה הוּא וְחֻמְשׁוֹ חֲמִשָּׁה:","יֵשׁ דְּבָרִים שֶׁאֵין חַיָּבִין עֲלֵיהֶן מְעִילָה מִדִּבְרֵי תּוֹרָה אֲבָל אָסוּר לֵהָנוֹת בָּהֶן מִדִּבְרֵי סוֹפְרִים וְהַנֶּהֱנֶה מֵהֶן מְשַׁלֵּם קֶרֶן בִּלְבַד וְאֵינוֹ מוֹסִיף חֹמֶשׁ וְאֵינוֹ מֵבִיא אָשָׁם:","כָּל קָדְשֵׁי מִזְבֵּחַ בֵּין קָדְשֵׁי קָדָשִׁים בֵּין קָדָשִׁים קַלִּים אֲסוּרִין בְּגִזָּה וַעֲבוֹדָה שֶׁנֶּאֱמַר (דברים טו יט) \"לֹא תַעֲבֹד בִּבְכֹר שׁוֹרֶךָ וְלֹא תָגֹז בְּכוֹר צֹאנֶךָ\". וְהוּא הַדִּין לִשְׁאָר קָדָשִׁים. וְהַגּוֹזֵז אֶת הַשּׁוֹר אוֹ הָעוֹבֵד בַּצֹּאן לוֹקֶה מִן הַתּוֹרָה. וְתוֹלֵשׁ אֵינוֹ כְּגוֹזֵז. וְיֵרָאֶה לִי שֶׁאֵינוֹ לוֹקֶה עַד שֶׁיִּגְזֹז כְּדֵי רֹחַב הַסִּיט כָּפוּל. לֹא יִהְיֶה זֶה חָמוּר מִשַּׁבָּת:","סְפֵק קָדָשִׁים כְּגוֹן בְּהֵמָה שֶׁהִיא סְפֵק בְּכוֹר וְכַיּוֹצֵא בָּהּ. הֲרֵי הֵן אֲסוּרִין בְּגִזָּה וַעֲבוֹדָה וְהַגּוֹזֵז אוֹ הָעוֹבֵד בָּהֶן אֵינוֹ לוֹקֶה:","בֶּהֱמַת הֶקְדֵּשׁ שֶׁנָּפַל בָּהּ מוּם וְנִפְדַּת כְּמוֹ שֶׁבֵּאַרְנוּ אֵינָהּ מֻתֶּרֶת בְּגִזָּה וַעֲבוֹדָה וַהֲרֵי הִיא בְּאִסּוּרָהּ עַד שֶׁתִּשָּׁחֵט. נִשְׁחֲטָה אַחַר פִּדְיוֹנָהּ הֻתְּרָה בַּאֲכִילָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁקָּדַם הֶקְדֵּשָׁן אֶת מוּמָן אוֹ קָדַם מוּם עוֹבֵר לְהֶקְדֵּשָׁן. אֲבָל הַמַּקְדִּישׁ בַּעֲלַת מוּם קָבוּעַ לַמִּזְבֵּחַ אֵינָהּ אֲסוּרָה בְּגִזָּה וַעֲבוֹדָה אֶלָּא מִדִּבְרֵיהֶם. נִפְדַּת הֲרֵי זוֹ כְּחֻלִּין לְכָל דָּבָר וְתֵצֵא לְחֻלִּין לְהִגָּזֵז וּלְהֵעָבֵד. חוּץ מִן הַבְּכוֹר וְהַמַּעֲשֵׂר שֶׁהַקְּדֻשָּׁה חָלָה עַל גּוּפָן אַף עַל פִּי שֶׁהֵן בַּעֲלֵי מוּמִין קְבוּעִין מִתְּחִלָּתָן. וְאֵינָן יוֹצְאִין לְחֻלִּין לְהִגָּזֵז וּלְהֵעָבֵד לְעוֹלָם. וְאָסוּר לְהַרְבִּיעַ בִּבְכוֹר אוֹ בִּפְסוּלֵי הַמֻּקְדָּשִׁין:","מֻתָּר לִתְלֹשׁ אֶת הַשֵּׂעָר לְכַתְּחִלָּה מִן הַקָּדָשִׁים כְּדֵי לְהַרְאוֹת הַמּוּם לְמֻמְחֶה. וְאוֹתוֹ הַשֵּׂעָר שֶׁתָּלַשׁ אוֹ שֶׁנָּשַׁר מִן הַבְּהֵמָה אוֹ מִן הַבְּכוֹר וְהַמַּעֲשֵׂר הֲרֵי זֶה אָסוּר בַּהֲנָיָה אֲפִלּוּ לְאַחַר שֶׁיִּשָּׁחֲטוּ מִפְּנֵי מוּמָן. גְּזֵרָה שֶׁמָּא יַשְׁהֶה אוֹתָן הוֹאִיל וְאֵינָן בָּאִין לְכַפָּרָה. אֲבָל צֶמֶר הַנּוֹשֵׁר מִן הַחַטָּאת וְהָאָשָׁם מֻתָּר בַּהֲנָיָה לְאַחַר שְׁחִיטָתָן מִפְּנֵי מוּמָן. הוֹאִיל וּלְכַפָּרָה הֵן בָּאִין אֵינוֹ מַשְׁהֶה אוֹתָן. וְאִם נִתְלַשׁ מִן הָעוֹלָה הֲרֵי זֶה סָפֵק. וְכָל שֶׁיִּתָּלֵשׁ מִכָּל הַקָּדָשִׁים אַחַר שֶׁנָּפַל בָּהֶן מוּם הֲרֵי הוּא מֻתָּר בַּהֲנָיָה שֶׁהֲרֵי לֹא תָּלַשׁ בְּיָדוֹ. חוּץ מִן הַבְּכוֹר וְהַמַּעֲשֵׂר שֶׁאַף הַנִּתְלָשׁ מִמֶּנּוּ אַחַר שֶׁנָּפַל בּוֹ מוּם אָסוּר בַּהֲנָיָה:","הַשּׁוֹחֵט בְּכוֹר אוֹ שְׁאָר מֻקְדָּשִׁין. תּוֹלֵשׁ אֶת הַשֵּׂעָר מִכָּאן וּמִכָּאן לַעֲשׂוֹת מָקוֹם לַסַּכִּין. וּבִלְבַד שֶׁלֹּא יְזִיזֶנּוּ מִמְּקוֹמוֹ:","קָדְשֵׁי בֶּדֶק הַבַּיִת אֲסוּרִין בְּגִזָּה וַעֲבוֹדָה מִדִּבְרֵי סוֹפְרִים אֲבָל מִן הַתּוֹרָה אֵינָן אֲסוּרִין. לְפִיכָךְ הַגּוֹזֵז אוֹתָן אוֹ הָעוֹבֵד בָּהֶן אֵינוֹ לוֹקֶה אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הַמַּקְדִּישׁ עֻבָּר לַמִּזְבֵּחַ אִמּוֹ אֲסוּרָה בַּעֲבוֹדָה מִדִּבְרֵי סוֹפְרִים. מִפְּנֵי שֶׁעֲבוֹדָתָהּ מַכְחֶשֶׁת אֶת הָעֻבָּר גָּזְרוּ בָּהּ. וַהֲרֵי הִיא מֻתֶּרֶת בְּגִזָּה שֶׁאֵין בָּזֶה הֶפְסֵד לַוָּלָד. הִקְדִּישׁ אֵיבָר אֶחָד מִן הַבְּהֵמָה בֵּין לְבֶדֶק הַבַּיִת בֵּין לַמִּזְבֵּחַ הֲרֵי הַדָּבָר סָפֵק אִם אֲסוּרָה כֻּלָּהּ בְּגִזָּה וַעֲבוֹדָה אוֹ אֵינָהּ אֲסוּרָה לְפִיכָךְ אֵין לוֹקִין עָלֶיהָ:"],"Mishneh Torah, Vessels 13":["כְּבָר בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת שֶׁאֵין כְּלִי חֶרֶס מִתְטַמֵּא אֶלָּא מֵאֲוִירוֹ אוֹ בְּהֶסֵּט הַזָּב. וּשְׁאָר כָּל הַכֵּלִים שֶׁנָּגְעָה בָּהֶן הַטֻּמְאָה נִטְמְאוּ וְאִם נִכְנְסָה טֻמְאָה לַאֲוִירוֹ וְלֹא נָגְעָה בָּהֶן הֲרֵי הֵם טְהוֹרִין. נִמְצָא הַטָּמֵא בִּכְלִי חֶרֶס טָהוֹר בְּכָל הַכֵּלִים וְהַטָּמֵא בְּכָל הַכֵּלִים טָהוֹר בִּכְלִי חֶרֶס. וּמִנַּיִן שֶׁאֵין כְּלִי חֶרֶס מִתְטַמֵּא אֶלָּא מֵאֲוִירוֹ שֶׁנֶּאֱמַר (ויקרא יא לג) \"וּכְלִי חֶרֶשׂ אֲשֶׁר יִפּל מֵהֶם אֶל תּוֹכוֹ\" וְגוֹ' מִתּוֹכוֹ הוּא מִתְטַמֵּא לֹא מֵאֲחוֹרָיו:","וּכְשֵׁם שֶׁמִּתְטַמֵּא מֵאֲוִירוֹ כָּךְ מְטַמֵּא אֳכָלִין וּמַשְׁקִין מֵאֲוִירוֹ. כֵּיצַד. כְּלִי חֶרֶס שֶׁנִּטְמָא וְנִכְנְסוּ אֳכָלִין וּמַשְׁקִין לַאֲוִירוֹ אַף עַל פִּי שֶׁלֹּא נָגְעוּ בּוֹ הֲרֵי אֵלּוּ טְמֵאִין שֶׁנֶּאֱמַר (ויקרא יא לג) \"כּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא\". אֲבָל שְׁאָר הַכֵּלִים הַטְּמֵאִין אֵינָן מְטַמְּאִין אֳכָלִין וּמַשְׁקִין עַד שֶׁיִּגְּעוּ בָּהֶן:","אֵין כְּלִי חֶרֶס מְטַמֵּא כֵּלִים מֵאֲוִירוֹ בֵּין כְּלֵי חֶרֶס בֵּין שְׁאָר כֵּלִים. כֵּיצַד. כְּלִי חֶרֶס גָּדוֹל שֶׁהָיוּ בְּתוֹכוֹ כֵּלִים וְנִכְנְסָה טֻמְאָה בַּאֲוִירוֹ הוּא טָמֵא וְכָל הַכֵּלִים שֶׁבְּתוֹכוֹ טְהוֹרִין. הָיוּ מַשְׁקִין בַּכֵּלִים שֶׁבְּתוֹכוֹ נִטְמְאוּ הַמַּשְׁקִין מֵאֲוִירוֹ וְחוֹזְרִין וּמְטַמְּאִין אֶת הַכֵּלִים. וַהֲרֵי זֶה אוֹמֵר מְטַמְּאֶיךָ לֹא טִמְּאוּנִי וְאַתָּה טִמֵּאתַנִי:","כְּלִי חֶרֶס שֶׁנָּגְעוּ מַשְׁקִין טְמֵאִין בַּאֲחוֹרָיו בִּלְבַד נִטְמְאוּ אֲחוֹרָיו כִּשְׁאָר כָּל הַכֵּלִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה לוֹ תּוֹךְ. אֲבָל אִם אֵין לוֹ תּוֹךְ וְנָגְעוּ בּוֹ מַשְׁקִין טְמֵאִין הֲרֵי זֶה טָהוֹר. שֶׁכָּל שֶׁאֵין לוֹ תּוֹךְ בִּכְלִי חֶרֶס אֵין אֲחוֹרָיו מִתְטַמְּאִין בְּמַשְׁקִין. נָגְעוּ אֳכָלִין אוֹ מַשְׁקִין בַּאֲחוֹרֵי כְּלִי חֶרֶס הַטָּמֵא הֲרֵי אֵלּוּ טְמֵאִין. וְאֶחָד כְּלִי חֶרֶס וְאֶחָד שְׁאָר כָּל הַכֵּלִים בְּדָבָר זֶה שֶׁכָּל הַכֵּלִים הַטְּמֵאִין שֶׁנָּגְעוּ אֳכָלִין אוֹ מַשְׁקִין בָּהֶן בֵּין מִתּוֹכָן בֵּין מֵאֲחוֹרֵיהֶן נִטְמְאוּ:","אֶחָד כְּלִי חֶרֶס שֶׁנִּכְנְסָה טֻמְאָה לַאֲוִירוֹ אוֹ שֶׁכָּפָהוּ עַל הַטֻּמְאָה הַמֻּנַּחַת עַל הָאָרֶץ וְנַעֲשָׂה אֹהֶל עָלֶיהָ שֶׁהֲרֵי הַטֻּמְאָה בְּתוֹכוֹ. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר (ויקרא יא לג) \"אֶל תּוֹכוֹ\" לְרַבּוֹת אֶת הָאֹהָלִים:","גּוּמָא שֶׁהָיָה הַשֶּׁרֶץ מֻנָּח בְּתוֹכָהּ וְכָפָה כְּלִי חֶרֶס עַל הַגּוּמָא לֹא נִטְמָא שֶׁנֶּאֱמַר (ויקרא יא לג) \"אֶל תּוֹכוֹ\" עַד שֶׁתִּכָּנֵס עַצְמָהּ שֶׁל טֻמְאָה בְּתוֹכוֹ. לְפִיכָךְ הַשֶּׁרֶץ שֶׁנִּמְצָא לְמַטָּה מִנְּחֻשְׁתּוֹ שֶׁל תַּנּוּר שֶׁהִיא קַרְקָעִית הַתַּנּוּר טָהוֹר שֶׁאֲנִי אוֹמֵר חַי נָפַל וְעַכְשָׁו מֵת בְּתוֹךְ גּוּמָא זוֹ. וְכֵן אִם נִמְצֵאת מַחַט אוֹ טַבַּעַת לְמַטָּה מִנְּחֻשְׁתּוֹ אַף עַל פִּי שֶׁכָּל הַכֵּלִים הַנִּמְצָאִים טְמֵאִים כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי הַתַּנּוּר טָהוֹר שֶׁאֲנִי אוֹמֵר שָׁם הָיוּ עַד שֶׁלֹּא בָּא הַתַּנּוּר וְהַתַּנּוּר נִבְנָה עֲלֵיהֶן וְלֹא נָפְלוּ בְּתוֹכוֹ. נִמְצְאוּ בַּדֶּשֶׁן הֲרֵי הַתַּנּוּר טָמֵא שֶׁאֵין לוֹ בְּמָה יִתְלֶה. נִמְצְאוּ בִּנְחֻשְׁתּוֹ שֶׁל תַּנּוּר נִרְאִין אֲבָל אֵינָן יוֹצְאִין לַאֲוִירוֹ. אִם אוֹפֶה אֶת הַבָּצֵק וְהוּא נוֹגֵעַ בָּהֶן נִטְמָא הַתַּנּוּר כְּאִלּוּ הָיוּ בְּתוֹךְ אֲוִירוֹ. וְאִם לָאו הַתַּנּוּר טָהוֹר כְּאִלּוּ הָיוּ לְמַטָּה מִנְּחֻשְׁתּוֹ. בְּאֵי זֶה בָּצֵק אָמְרוּ בְּבָצֵק הַבֵּינוֹנִי שֶׁאֵינוֹ רַךְ בְּיוֹתֵר וְלֹא קָשֶׁה:","הַשֶּׁרֶץ שֶׁנִּמְצָא בְּעַיִן שֶׁל תַּנּוּר בְּעַיִן שֶׁל כִּירָה בְּעַיִן שֶׁל כֻּפַּח אִם נִמְצָא מִן הַשָּׂפָה הַפְּנִימִית וְלַחוּץ טָהוֹר. וְכֵן אִם נִמְצָא בַּאֲוִיר הָעַיִן טָהוֹר שֶׁהֲרֵי לֹא נִכְנַס לַאֲוִיר הַתַּנּוּר אוֹ הַכִּירָה אוֹ הַכֻּפַּח אֶלָּא תַּחַת עֳבִי דָּפְנוֹתֵיהֶן הוּא תָּלוּי. וַאֲפִלּוּ הָיָה שָׁם כְּזַיִת מִן הַמֵּת טְהוֹרִין אֶלָּא אִם כֵּן הָיָה בָּעֳבִי הָעַיִן פּוֹתֵחַ טֶפַח שֶׁהֲרֵי מֵבִיא אֶת הַטֻּמְאָה לַאֲוִיר הַתַּנּוּר כְּמוֹ שֶׁנִּתְבָּאֵר בְּעִנְיַן טֻמְאַת מֵת:","נִמְצָא הַשֶּׁרֶץ בִּמְקוֹם הַנָּחַת הָעֵצִים מִן הַשָּׂפָה הַפְּנִימִית וְלַחוּץ טָהוֹר. נִמְצָא בִּמְקוֹם יְשִׁיבַת הַבַּלָּן בִּמְקוֹם יְשִׁיבַת הַצַּבָּע בִּמְקוֹם יְשִׁיבַת שׁוֹלְקֵי הַזֵּיתִים הַכּל טָהוֹר:","אֵין הַתַּנּוּר וְלֹא הַכִּירָה וְלֹא שְׁאָר מְקוֹמוֹת הַיְקוֹד מִתְטַמְּאִין אֶלָּא אִם כֵּן נִמְצֵאת הַטֻּמְאָה מִן הַסְּתִימָה וּלְפָנִים:","כְּלִי חֶרֶס שֶׁשּׁוֹתִין בּוֹ בַּעֲלֵי בָּתִּים הַמַּיִם שֶׁבְּאֶמְצָעוֹ כְּמוֹ רֶשֶׁת שֶׁל חֶרֶס וּשְׂפָתוֹ שֶׁלְּמַעְלָה מִן הָרֶשֶׁת כְּמוֹ מַסְרֵק וְזֶהוּ הַנִּקְרָא צַרְצוּר אִם נִכְנְסָה הַטֻּמְאָה לַאֲוִיר הַמַּסְרֵק לְמַעְלָה מִן הָרֶשֶׁת נִטְמָא כֻּלּוֹ שֶׁזֶּהוּ תּוֹכוֹ שֶׁל כְּלִי זֶה:","כְּלִי חֶרֶס שֶׁהָיָה לוֹ שָׁלֹשׁ שְׂפָיוֹת זוֹ לְפָנִים מִזּוֹ הָיְתָה הַפְּנִימִית עוֹדֶפֶת וְנִכְנְסָה טֻמְאָה לַאֲוִיר הַפְּנִימִית כָּל הָאֳכָלִין וְהַמַּשְׁקִין שֶׁבָּאֲוִיר שֶׁבֵּין הַשָּׂפָה הַפְּנִימִית וּבֵין הָאֶמְצָעִית וְהַחִיצוֹנָה טְהוֹרִין. הָיְתָה הָאֶמְצָעִית עוֹדֶפֶת וְנִטְמָא אֲוִירָהּ מִמֶּנָּה וְלִפְנִים טָמֵא מִמֶּנָּה וְלַחוּץ טָהוֹר. הָיְתָה הַחִיצוֹנָה עוֹדֶפֶת וְנִטְמָא אֲוִירָהּ הַכּל טָמֵא. הָיוּ שָׁווֹת כָּל שֶׁנִּטְמָא אֲוִירָהּ טְמֵאָה וְהַשְּׁאָר טָהוֹר:","אִלְפָּסִים זוֹ בְּתוֹךְ זוֹ וְשִׂפְתוֹתֵיהֶן שָׁווֹת וְהַשֶּׁרֶץ בָּעֶלְיוֹנָה אוֹ בַּתַּחְתּוֹנָה זוֹ שֶׁיֵּשׁ בָּהּ הַשֶּׁרֶץ טְמֵאָה וּשְׁאָר הָאִלְפָּסִין טְהוֹרִין הֵן וְכָל הָאֳכָלִין שֶׁבָּהֶן. הָיָה כָּל אִלְפָּס מֵהֶן נְקוּבָה בְּכוֹנֵס מַשְׁקֶה וְהַשֶּׁרֶץ בָּעֶלְיוֹנָה כָּל הָאֳכָלִין וְהַמַּשְׁקִין שֶׁבְּכָל הָאִלְפָּסִים טְמֵאִים שֶׁהַטֻּמְאָה בַּאֲוִיר כֻּלָּן כְּמוֹ שֶׁיִּתְבָּאֵר. הָיָה הַשֶּׁרֶץ בַּתַּחְתּוֹנָה הִיא טְמֵאָה וְכֻלָּן טְהוֹרוֹת שֶׁהֲרֵי לֹא נִכְנַס שֶׁרֶץ לַאֲוִיר הָעֶלְיוֹנָה וְאֵין שְׂפַת הַתַּחְתּוֹנָה עוֹדֶפֶת כְּדֵי לְטַמֵּא כָּל הָאֳכָלִין וְהַמַּשְׁקִין שֶׁבְּתוֹכָהּ. הָיָה הַשֶּׁרֶץ בָּעֶלְיוֹנָה וְהָיְתָה שְׂפַת הַתַּחְתּוֹנָה עוֹדֶפֶת הָעֶלְיוֹנָה טְמֵאָה שֶׁהַשֶּׁרֶץ בְּתוֹכָהּ וְכֵן הַתַּחְתּוֹנָה מִפְּנֵי שֶׁשְּׂפָתָהּ עוֹדֶפֶת הֲרֵי הַשֶּׁרֶץ בַּאֲוִירָהּ וּשְׁאָר הָאִלְפָּסִין שֶׁבְּתוֹךְ הַתַּחְתּוֹנָה טְהוֹרִין שֶׁאֵין כְּלִי חֶרֶס מְטַמֵּא כֵּלִים שֶׁבְּתוֹכוֹ. וְאִם הָיָה בֵּינֵיהֶן מַשְׁקֶה טוֹפֵחַ כָּל שֶׁיֵּשׁ בָּהּ מַשְׁקֶה טוֹפֵחַ טְמֵאָה שֶׁהַמַּשְׁקֶה מִתְטַמֵּא מֵאֲוִיר הַתַּחְתּוֹנָה הָעוֹדֶפֶת וְחוֹזֵר וּמְטַמֵּא אֶת הָאִלְפָּס:","טַבְלָא שֶׁל חֶרֶס שֶׁהָיוּ קְעָרוֹת דְּבוּקוֹת בָּהּ בִּתְחִלַּת מַעֲשֶׂיהָ וַהֲרֵי הַכּל כְּלִי אֶחָד וְנִטְמֵאת אַחַת מֵהֶן לֹא נִטְמְאוּ כֻּלָּן. וְאִם הָיָה לַטַּבְלָא דֹּפֶן עוֹדֵף שֶׁנִּמְצְאוּ כָּל הַקְּעָרוֹת בְּתוֹכוֹ וְנִטְמֵאת אַחַת מֵהֶן נִטְמְאוּ כֻּלָּן. וְכֵן הַדִּין בְּבֵית הַתַּבְלִין שֶׁל חֶרֶס וְקַלְמִירִין הַמַּתְאִימוֹת כַּיּוֹצֵא בּוֹ:","בֵּית הַתַּבְלִין שֶׁל עֵץ שֶׁנִּטְמָא אֶחָד מִבָּתָּיו בְּמַשְׁקִין לֹא נִטְמְאוּ שְׁאָר הַבָּתִּים. וְאִם יֵשׁ לוֹ דֹּפֶן עוֹדֵף שֶׁנִּמְצְאוּ כָּל הַבָּתִּים בְּתוֹכוֹ וְנִטְמָא אֶחָד מִבָּתָּיו בְּמַשְׁקִין נִטְמְאוּ כֻּלָּן שֶׁהַכּל כִּכְלִי אֶחָד וּכְלִי שֶׁנִּטְמָא תּוֹכוֹ בְּמַשְׁקִין נִטְמָא כֻּלּוֹ. הָיוּ בָּתָּיו קְבוּעִין בְּמַסְמֵר הֲרֵי אֵלּוּ חִבּוּר זֶה לָזֶה לְטֻמְאָה וּלְהַזָּיָה. הָיוּ תְּקוּעִין בִּלְבַד הֲרֵי אֵלּוּ חִבּוּר לְטֻמְאָה וְלֹא לְהַזָּיָה. וְאִם הָיוּ בָּתָּיו נִטָּלִין וְנִתָּנִין אֵינָן חִבּוּר לֹא לְטֻמְאָה וְלֹא לְהַזָּיָה:"],"Mishneh Torah, Vessels 24":["אֵלוּ עוֹרוֹת מִתְטַמְּאִין בְּמִדְרָס. עוֹר שֶׁחָשַׁב עָלָיו לִשְׁטִיחָה. וְעוֹר שֶׁמַּנִּיחִין עַל הַמִּטּוֹת מִלְּמַעְלָה לִישֹׁן עָלָיו. וְעוֹר שֶׁמַּנִּיחִין עַל הַחֲמוֹר תַּחַת הַמַּשּׂאוֹי. וְעוֹר שֶׁמַּנִּיחִין בָּעֶרֶס תַּחַת הַקָּטָן. וְעוֹר הַכַּר. וְעוֹר הַכֶּסֶת. וְעוֹר שֶׁמַּנִּיחִין תַּחַת הַשֻּׁלְחָן בְּעֵת הָאֲכִילָה כְּדֵי שֶׁיִּפְּלוּ עָלָיו הַפֵּרוּרִין מִפְּנֵי שֶׁהוּא נִשְׁעָן עָלָיו בְּרַגְלוֹ. וְעוֹר שֶׁחוֹגֵר נוֹפֵץ הַפִּשְׁתָּן עָלָיו בְּעֵת שֶׁנּוֹפֵץ. וְעוֹר שֶׁחוֹגֵר הַחַמָּר עָלָיו. וְעוֹר שֶׁמַּנִּיחַ הַסַּבָּל עַל כְּתֵפוֹ בְּעֵת שֶׁסּוֹבֵל. וְעוֹר שֶׁמַּנִּיחַ הָרוֹפֵא עַל בִּרְכָּיו בְּעֵת שֶׁמֵּפִיס הַשְּׁחִינִין מִפְּנֵי שֶׁכָּל הָעוֹרוֹת הָאֵלּוּ יוֹשֵׁב עֲלֵיהֶן. וְעוֹר הַלֵּב שֶׁל קָטָן שֶׁרִירוֹ יוֹרֵד עָלָיו כְּדֵי שֶׁלֹּא יִפָּסְדוּ בְּגָדָיו. וְעוֹר שֶׁעֲשָׂאָהוּ לְנוֹתְנוֹ עַל לִבּוֹ בִּשְׁעַת הַקָּצִיר מִפְּנֵי הַשָּׁרָב. וְעוֹר שֶׁלּוֹפְפִין הַכְּסוּת בּוֹ. וְעוֹר הַתָּפוּר בְּתֵבָה שֶׁמַּנִּיחִין בּוֹ הַבְּגָדִים שֶׁכָּל אֵלּוּ מִתְהַפְּכִין עֲלֵיהֶן וְנִשְׁעָנִין עֲלֵיהֶן:","כָּל הָעוֹרוֹת הַמִּתְטַמְּאוֹת בְּמִדְרָס אֵינָן מִתְטַמְּאִין עַד שֶׁיִּהְיֶה בָּהֶן כְּשִׁעוּר חֲמִשָּׁה טְפָחִים עַל חֲמִשָּׁה טְפָחִים. וְאֵלּוּ עוֹרוֹת שֶׁאֵין מִתְטַמְּאִין בְּמִדְרָס. עוֹר שֶׁחוֹגֵר סוֹרֵק הַצֶּמֶר בְּעֵת שֶׁסּוֹרֵק. וְעוֹר שֶׁלּוֹפֵף בּוֹ הַצֶּמֶר הַסָּרוּק. וְעוֹר שֶׁלּוֹפֵף בּוֹ הָאַרְגָּמָן. וְעוֹר הַתּוֹפֵר שֶׁמַּנִּיחִין בּוֹ הָאַרְגָּמָן. וְכֻלָּן מִתְטַמְּאִין בִּשְׁאָר טֻמְאוֹת:","עוֹר שֶׁעֲשָׂאוֹ חִפּוּי לְכֵלִים טָהוֹר מִכְּלוּם. עֲשָׂאוֹ חִפּוּי לְמִשְׁקלֶת מְקַבֵּל שְׁאָר טֻמְאוֹת שֶׁהֲרֵי נַעֲשָׂה לְקַבָּלָה וְאֵינוֹ מִתְטַמֵּא בְּמִדְרָס:","עוֹר שֶׁעֲשָׂאָהוּ לַעֲקֵבוֹ וּלְפַרְסָתוֹ אִם חוֹפֶה אֶת רֹב הָרֶגֶל מִתְטַמֵּא וְאִם לָאו טָהוֹר:","מִנְעָל שֶׁעַל הָאִמּוּם אַף עַל פִּי שֶׁעֲדַיִן לֹא לְבָשׁוֹ אָדָם הֲרֵי זֶה מִתְטַמֵּא בְּמִדְרָס שֶׁכְּבָר נִגְמְרָה מְלַאכְתּוֹ:","כָּל עוֹר הָרָאוּי לְהִתְטַמֵּא בְּמִדְרָס וְאֵינוֹ חָסֵר מְלָאכָה הַמַּחְשָׁבָה מְטַמֵּאתוֹ וְאִם חִשֵּׁב עָלָיו לִהְיוֹת עוֹר שֻׁלְחָן וְכַיּוֹצֵא בּוֹ הֲרֵי זֶה מִתְטַמֵּא בְּמִדְרָס. וְאִם חָסֵר מְלָאכָה אֵין הַמַּחְשָׁבָה מוֹעֶלֶת בּוֹ עַד שֶׁתִּגָּמֵר מְלַאכְתּוֹ. חוּץ מִן הָעוֹר שֶׁמְּחַפִּין בּוֹ הַמֶּרְכָּב מִפְּנֵי הָאָבָק שֶׁהַמַּחְשָׁבָה מוֹעֶלֶת בּוֹ אַף עַל פִּי שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעוֹרוֹת בַּעַל הַבַּיִת. אֲבָל עוֹרוֹת הָעַבְּדָן שֶׁסְּתָמָן לִמְכִירָה אֵין הַמַּחְשָׁבָה מְטַמֵּאתָן עַד שֶׁיַּעֲשֶׂה בָּהֶן מַעֲשֵׂה וִיכִינֵם לְמִדְרָס:","אֵין אָדָם מְטַמֵּא בְּמִדְרַס מִשְׁכָּב אוֹ מֶרְכָּב שֶׁאֵינָן שֶׁלּוֹ שֶׁנֶּאֱמַר (ויקרא טו כא) \"וְהַנּוֹגֵעַ בְּמִשְׁכָּבוֹ\". גָּזַל מִשְׁכָּב וְדָרַס עָלָיו בְּלֹא נְגִיעָה טָהוֹר וְאִם נִתְיָאֲשׁוּ הַבְּעָלִים טָמֵא. גָּנַב מִשְׁכָּב וְיָשַׁב עָלָיו טָמֵא שֶׁחֶזְקָתוֹ שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים שֶׁאֵינָן יוֹדְעִים מִי גְּנָבוֹ וְאִם נוֹדַע שֶׁעֲדַיִן לֹא נִתְיָאֲשׁוּ הַבְּעָלִים טָהוֹר. לְפִיכָךְ גַּנָּב שֶׁגָּנַב עוֹר וְחִשֵּׁב עָלָיו לִשְׁכִיבָה מַחֲשָׁבָה מוֹעֶלֶת לוֹ וּמִתְטַמֵּא בְּמִדְרָס אֲבָל הַגַּזְלָן אֵין מַחְשַׁבְתּוֹ מוֹעֶלֶת אֶלָּא אִם כֵּן נִתְיָאֲשׁוּ הַבְּעָלִים:","עוֹר שֶׁנִּטְמָא בְּמִדְרָס וְהִתְחִיל לְקָרְעוֹ רְצוּעוֹת הֲרֵי הוּא בְּטֻמְאָתוֹ עַד שֶׁיְּמַעֲטֶנּוּ פָּחוֹת פָּחוֹת מֵחֲמִשָּׁה טְפָחִים:","כָּל כְּלִי עוֹר שֶׁנִּטְמָא בְּמִדְרַס הַזָּב וְשִׁנָּהוּ לִכְלִי אַחֵר אִם שִׁנָּהוּ מִפָּשׁוּט לְפָשׁוּט הֲרֵי הוּא בְּטֻמְאָתוֹ. שִׁנָּהוּ מִפָּשׁוּט לִמְקַבֵּל וּמִמְּקַבֵּל לְפָשׁוּט טָהוֹר. וּבְבֶגֶד הַכּל טָמֵא. כֵּיצַד. חֵמֶת שֶׁעֲשָׂאָהּ שָׁטִיחַ וְשָׁטִיחַ שֶׁעֲשָׂאָהּ חֵמֶת טָהוֹר אֲבָל חֵמֶת שֶׁנִּטְמְאָה מִדְרָס וַעֲשָׂאָהּ תּוּרְמִיל אוֹ תּוּרְמִיל שֶׁעֲשָׂאָהוּ חֵמֶת הֲרֵי הֵן מִדְרָס כְּשֶׁהָיוּ:","כַּר שֶׁל בֶּגֶד שֶׁנִּטְמָא בְּמִדְרָס וַעֲשָׂאָהוּ סָדִין אוֹ סָדִין שֶׁעֲשָׂאָהוּ כַּר אוֹ כֶּסֶת. בֶּגֶד שֶׁעֲשָׂאָהוּ מִטְפַּחַת אוֹ מִטְפַּחַת שֶׁעֲשָׂאָהוּ כֶּסֶת הֲרֵי הֵן מִדְרָס כְּשֶׁהָיוּ:","כֵּלִים שֶׁעִקַּר עֲשִׂיָּתָן לְקַבָּלָה וּלְמִשְׁכָּב כְּאֶחָד כְּגוֹן הַכָּרִים וְהַכְּסָתוֹת וְהַשַּׂקִּין וְהַמַּרְצּוּפִין אִם נִפְחֲתוּ אַף עַל פִּי שֶׁטָּהֲרוּ מִלְּהִתְטַמֵּא בְּמֵת וּבִשְׁאָר טֻמְאוֹת מִפְּנֵי שֶׁאֵינָן יְכוֹלִין לְקַבֵּל הֲרֵי הֵן מִתְטַמְּאִין בְּמִדְרָס שֶׁעֲדַיִן הֵן רְאוּיִין לְמִדְרָס. אֲבָל כֵּלִים שֶׁעִקַּר עֲשִׂיָּתָן לְקַבָּלָה בִּלְבַד כְּגוֹן הַחֵמֶת וְהַתּוּרְמִיל אִם הָיוּ גְּדוֹלִים כְּדֵי שֶׁיִּהְיוּ רְאוּיִין לֵישֵׁב עֲלֵיהֶן הוֹאִיל וְיוֹשְׁבִין עֲלֵיהֶן מִפְּנֵי גָּדְלָן הֲרֵי הֵן מִתְטַמְּאִין בְּמִדְרָס כָּל זְמַן שֶׁהֵן שְׁלֵמִין נִפְחֲתוּ אַף עַל פִּי שֶׁאֶפְשָׁר עֲדַיִן לֵישֵׁב עֲלֵיהֶן אֵין מִתְטַמְּאִין בְּמִדְרָס שֶׁעִקַּר עֲשִׂיָּתָן לְקַבָּלָה בִּלְבַד הוֹאִיל וּבָטְלוּ מִלְּקַבֵּל טָהֲרוּ מִלְּהִתְטַמֵּא לֹא בְּמִדְרָס וְלֹא בִּשְׁאָר טֻמְאוֹת. וְכַמָּה הוּא שִׁעוּרָן וְיִהְיוּ רְאוּיִין לְמִדְרָס הַחֵמֶת שִׁבְעָה קַבִּין וְהַיַּלְקוּט חֲמִשָּׁה וְהַקְּלַסְתֵּר שֶׁתּוֹלִין בּוֹ הַשְּׂעוֹרִים בְּרֹאשׁ הַבְּהֵמָה אַרְבָּעָה וְהַכְּרִיתִית שֶׁמְּעָרִין בָּהּ הַמַּיִם סְאָה. פָּחוֹת מִשִּׁעוּרִין אֵלּוּ אֵינָן רְאוּיִין לְמִדְרָס וְאֵין דֶּרֶךְ הָעָם לֵישֵׁב עֲלֵיהֶן. נִפְחֲתוּ וְצָרַר מְקוֹם הַפְּחָת הֲרֵי הֵן טְהוֹרִין וּכְאִלּוּ לֹא קָשַׁר מְקוֹם הַפְּחָת. וְכָל הַחֲמָתוֹת שֶׁנִּפְחֲתוּ וּצְרָרָן טְהוֹרוֹת חוּץ מִשֶּׁל עַרְבִיִּים מִפְּנֵי שֶׁכָּךְ הוּא דַּרְכָּן תָּמִיד לְצָרְרָן. וְחֵמֶת חֲלִילִין אֵין מִתְטַמֵּא בְּמִדְרָס שֶׁהֲרֵי אֵינָהּ רְאוּיָה לְמִדְרָס:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 1":["מִצְוַת עֲשֵׂה לַעֲשׂוֹת שֶׁמֶן הַמִּשְׁחָה שֶׁיִּהְיֶה מוּכָן לִדְבָרִים שֶׁצְּרִיכִין מְשִׁיחָה בּוֹ שֶׁנֶּאֱמַר (שמות ל, כה) \"וְעָשִׂיתָ אֹתוֹ שֶׁמֶן מִשְׁחַת קֹדֶשׁ\":","וְכָכָה עָשָׂהוּ משֶׁה רַבֵּנוּ בַּמִּדְבָּר. לָקַח מִן הַמּוֹר וְהַקִּנָּמוֹן וְהַקִּדָּה מִכָּל אֶחָד מִשְּׁלָשְׁתָּן חֲמֵשׁ מֵאוֹת שֶׁקֶל בְּשֶׁקֶל הַקֹּדֶשׁ. וּמִקְּנֵה הַבּשֶֹׁם חֲמִשִּׁים וּמָאתַיִם. וְזֶהוּ שֶׁנֶּאֱמַר בַּתּוֹרָה (שמות ל כג) \"וְקִנְּמָן בֶּשֶׂם מַחֲצִיתוֹ חֲמִשִּׁים וּמָאתַיִם\" שֶׁשּׁוֹקְלִים אוֹתוֹ בִּשְׁתֵּי פְּעָמִים חֲמִשִּׁים וּמָאתָיִם בְּכָל פַּעַם. וְשׁוֹחֵק כָּל אֶחָד וְאֶחָד לְבַדּוֹ. וְעֵרֵב הַכּל וְשָׁרָה אוֹתָן בְּמַיִם זַכִּין וּמְתוּקִין עַד שֶׁיֵּצֵא כָּל כֹּחָן בַּמַּיִם וְנָתַן עַל הַמַּיִם שֶׁמֶן זַיִת הִין וְהוּא י\"ב לוֹג. כָּל לוֹג אַרְבַּע רְבִיעִיּוֹת. וּבִשֵּׁל הַכּל עַל הָאֵשׁ עַד שֶׁאָבְדוּ הַמַּיִם וְנִשְׁאַר הַשֶּׁמֶן וְהִנִּיחוֹ בִּכְלִי לְדוֹרוֹת:","הַמּוֹר הוּא הַדָּם הַצָּרוּר בְּחַיָּה שֶׁבְּהֹדּוּ הַיָּדוּעַ לַכּל שֶׁמִּתְבַּשְּׂמִין בָּהּ בְּנֵי אָדָם בְּכָל מָקוֹם. וְהַקִּנָּמוֹן הוּא הָעֵץ שֶׁבָּא מֵאִיֵּי הֹדּוּ שֶׁרֵיחוֹ טוֹב וּמִתְגַּמְּרִים בּוֹ בְּנֵי אָדָם. וְהַקִּדָּה הִיא הַקּוֹשְׁט. וּקְנֵה בּשֶֹׁם הֵם הַקָּנִים הַדַּקִּים כְּתֶבֶן הָאֲדֻמִּים הַבָּאִים מֵאִיֵּי הֹדּוּ וְרֵיחָן טוֹב וְהֵם מִמִּינֵי הַבְּשָׂמִים שֶׁנּוֹתְנִין אוֹתָם הָרוֹפְאִים בְּצֹרִי:","הָעוֹשֶׂה שֶׁמֶן הַמִּשְׁחָה כַּמַּעֲשֶׂה הַזֶּה וְכַמִּשְׁקָל הַזֶּה וְלֹא הוֹסִיף וְלֹא גָּרַע בְּמֵזִיד חַיָּב כָּרֵת. בְּשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה שֶׁנֶּאֱמַר (שמות ל לג) \"אֲשֶׁר יִרְקַח כָּמֹהוּ\" (שמות ל לג) \"וְנִכְרַת מֵעַמָּיו\". וְהוּא שֶׁיַּעֲשֶׂה אוֹתוֹ לְהִמָּשַׁח בּוֹ. אֲבָל אִם עָשָׂהוּ לְהִתְלַמֵּד אוֹ לִתְּנוֹ לַאֲחֵרִים פָּטוּר:","הַסָּךְ מִשֶּׁמֶן הַמִּשְׁחָה כְּזַיִת בְּמֵזִיד חַיָּב כָּרֵת. וּבְשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה שֶׁנֶּאֱמַר (שמות ל לג) \"וַאֲשֶׁר יִתֵּן מִמֶּנּוּ עַל זָר וְנִכְרַת מֵעַמָּיו\". וְאֵין חַיָּבִין אֶלָּא עַל סִיכַת שֶׁמֶן הַמִּשְׁחָה שֶׁעָשָׂה משֶׁה שֶׁנֶּאֱמַר מִמֶּנּוּ. מִזֶּה שֶׁנֶּאֱמַר בּוֹ (שמות ל לא) \"שֶׁמֶן מִשְׁחַת קֹדֶשׁ יִהְיֶה זֶה לִי\". וּמֵעוֹלָם לֹא נַעֲשָׂה שֶׁמֶן אַחֵר חוּץ מִמַּה שֶּׁעָשָׂה משֶׁה:","אֶחָד הַסָּךְ אֶת עַצְמוֹ וְאֶחָד הַסָּךְ אֶת אֲחֵרִים שֶׁנֶּאֱמַר (שמות ל לג) \"וַאֲשֶׁר יִתֵּן מִמֶּנּוּ עַל זָר\". הַסָּךְ כֵּלִים וּבְהֵמָה וְעַכּוּ\"ם שֶׁהֵם כְּמוֹתָהּ אוֹ שֶׁסָּךְ מֵתִים בּוֹ פָּטוּר שֶׁנֶּאֱמַר (שמות ל לב) \"עַל בְּשַׂר אָדָם לֹא יִיסָךְ\":","אֵין מוֹשְׁחִין מִמֶּנּוּ לְדוֹרוֹת אֶלָּא כֹּהֲנִים גְּדוֹלִים וּמְשׁוּחַ מִלְחָמָה וּמַלְכֵי בֵּית דָּוִד בִּלְבַד. אֲפִלּוּ כֹּהֵן בֶּן כֹּהֵן מוֹשְׁחִין אוֹתוֹ. שֶׁנֶּאֱמַר (ויקרא ו טו) \"וְהַכֹּהֵן הַמָּשִׁיחַ תַּחְתָּיו מִבָּנָיו\" וְגוֹ':","בְּבַיִת שֵׁנִי שֶׁלֹּא הָיָה שָׁם שֶׁמֶן הַמִּשְׁחָה הָיָה כֹּהֵן גָּדוֹל מִתְרַבֶּה בִּלְבִישַׁת בְּגָדִים בִּלְבַד שֶׁהָיָה לוֹבֵשׁ בִּגְדֵי כְּהֻנָּה גְּדוֹלָה:","כֵּיצַד מוֹשְׁחִין אֶת הַכֹּהֵן. צָק אֶת הַשֶּׁמֶן עַל רֹאשׁוֹ וְסָךְ מִמֶּנּוּ עַל גַּבֵּי עֵינָיו כְּמִין כִּי יְוָנִית כָּזֶה שֶׁנֶּאֱמַר (ויקרא ח יב) \"וַיִּצֹק מִשֶּׁמֶן הַמִּשְׁחָה עַל רֹאשׁ אַהֲרֹן וַיִּמְשַׁח אֹתוֹ לְקַדְּשׁוֹ\". וּמַלְכֵי בֵּית דָּוִד מוֹשְׁחִין אוֹתָן כְּמִין נֵזֶר עַל רֹאשׁוֹ. וְלֹא יִמְשַׁח בִּמְקוֹמוֹת אֲחֵרוֹת וְלֹא יַרְבֶּה בְּשֶׁמֶן:","הַנּוֹתֵן מִשֶּׁמֶן הַמִּשְׁחָה עַל גַּבֵּי מֶלֶךְ אוֹ כֹּהֵן גָּדוֹל שֶׁכְּבָר נִמְשְׁחוּ פָּטוּר שֶׁנֶּאֱמַר (שמות ל לג) \"וַאֲשֶׁר יִתֵּן מִמֶּנּוּ עַל זָר\" וְאֵין אֵלּוּ זָרִים אֶצְלוֹ. אֲבָל הַסָּךְ מִמֶּנּוּ אֲפִלּוּ לְמֶלֶךְ וְכֹהֵן גָּדוֹל חַיָּב שֶׁנֶּאֱמַר (שמות ל לב) \"עַל בְּשַׂר אָדָם לֹא יִיסָךְ\" כָּל אָדָם בְּמַשְׁמָע. וְכֹהֵן גָּדוֹל שֶׁנָּטַל שֶׁמֶן הַמִּשְׁחָה מֵרֹאשׁוֹ וְסָךְ בְּמֵעָיו חַיָּב כָּרֵת וְהוּא שֶׁיָּסוּךְ מִמֶּנּוּ בִּכְזַיִת:","אֵין מוֹשְׁחִין אֶת הַמֶּלֶךְ אֶלָּא עַל גַּבֵּי הַמַּעְיָן. וְאֵין מוֹשְׁחִין מֶלֶךְ בֶּן מֶלֶךְ שֶׁהַמַּלְכוּת יְרֻשָּׁה לַמֶּלֶךְ לְעוֹלָם שֶׁנֶּאֱמַר (דברים יז כ) \"הוּא וּבָנָיו בְּקֶרֶב יִשְׂרָאֵל\". וְאִם הָיְתָה שָׁם מַחְלֹקֶת מוֹשְׁחִין אוֹתוֹ כְּדֵי לְסַלֵּק הַמַּחֲלֹקֶת וּלְהוֹדִיעַ לַכּל שֶׁזֶּהוּ מֶלֶךְ לְבַדּוֹ. כְּמוֹ שֶׁמָּשְׁחוּ שְׁלֹמֹה מִפְּנֵי מַחְלֹקֶת אֲדוֹנִיָּהוּ. וְיוֹאָשׁ מִפְּנֵי עֲתַלְיָה. וִיהוֹאָחָז מִפְּנֵי יְהוֹיָקִים אָחִיו. וְזֶה שֶׁמָּשַׁח אֱלִישָׁע לְיֵהוּא לֹא בְּשֶׁמֶן הַמִּשְׁחָה מְשָׁחוֹ אֶלָּא בְּשֶׁמֶן אֲפַרְסְמוֹן. וְדָבָר זֶה מָסֹרֶת בְּיַד הַחֲכָמִים:","כָּל כְּלֵי הַמִּקְדָּשׁ שֶׁעָשָׂה משֶׁה בַּמִּדְבָּר לֹא נִתְקַדְּשׁוּ אֶלָּא בִּמְשִׁיחָתָן בְּשֶׁמֶן הַמִּשְׁחָה שֶׁנֶּאֱמַר (במדבר ז א) \"וַיִּמְשָׁחֵם וַיְקַדֵּשׁ אֹתָם\". וְדָבָר זֶה אֵינוֹ נוֹהֵג לְדוֹרוֹת. אֶלָּא הַכֵּלִים כֻּלָּן כֵּיוָן שֶׁנִּשְׁתַּמְּשׁוּ בָּהֶן בַּמִּקְדָּשׁ בִּמְלַאכְתָּן נִתְקַדְּשׁוּ שֶׁנֶּאֱמַר (במדבר ד יב) \"אֲשֶׁר יְשָׁרְתוּ בָם בַּקֹּדֶשׁ\" בְּשֵׁרוּת הֵם מִתְקַדְּשִׁין:","הַכַּפּוֹת וְהַקְּעָרוֹת שֶׁמְּקַבְּלִין בָּהֶם הַמְּנָחוֹת וְכֵן הַמִּזְרָקוֹת שֶׁמְּקַבְּלִין בָּהֶן הַדָּם וּשְׁאָר כְּלֵי הַשָּׁרֵת כֻּלָּן שֶׁל כֶּסֶף וְשֶׁל זָהָב הָיוּ וּמֻתָּר לַעֲשׂוֹתָן מִשְּׁאָר מִינֵי מַתָּכוֹת כְּמוֹ שֶׁבֵּאַרְנוּ וְכֻלָּן מִתְקַדְּשִׁין בִּמְלַאכְתָּן. וְאִם נִשְׁבְּרוּ מַתִּיךְ אוֹתָם וְעוֹשֶׂה אוֹתָן כְּלִי אַחֵר וְאֵין קְדֻשָּׁתָן מִסְתַּלֶּקֶת מֵהֶן לְעוֹלָם:","כְּלֵי הַקֹּדֶשׁ שֶׁנִּקְּבוּ אוֹ שֶׁנִּסְדְּקוּ אֵין סוֹתְמִין אוֹתָן אֶלָּא מַתִּיכִין אוֹתָן וְעוֹשִׂין אוֹתָן חֲדָשִׁים:","סַכִּין שֶׁנִּשְׁמַט מִן הַנִּצָּב אוֹ שֶׁנִּפְגַּם אֵין מַחֲזִירִין אוֹתוֹ וְאֵין מַשְׁחִיזִין אוֹתוֹ. אֶלָּא גּוֹנְזִין אוֹתוֹ בְּצַד הַהֵיכָל בֵּין הַקֹּדֶשׁ וְהָאוּלָם לַדָּרוֹם וְעוֹשִׂין אֲחֵרִים. שֶׁאֵין עֲנִיּוּת בִּמְקוֹם עֲשִׁירוּת:","שְׁתֵּי מִדּוֹת שֶׁל יָבֵשׁ הָיוּ בַּמִּקְדָּשׁ. עִשָּׂרוֹן. וַחֲצִי עִשָּׂרוֹן. הָעִשָּׂרוֹן לִמְנָחוֹת. וַחֲצִי הָעִשָּׂרוֹן לְחַלֵּק בּוֹ מִנְחַת כֹּהֵן גָּדוֹל שֶׁבְּכָל יוֹם:","וְשֶׁבַע מִדּוֹת שֶׁל לַח הָיוּ שָׁם. הִין. וַחֲצִי הַהִין. וּשְׁלִישִׁית הַהִין. וּרְבִיעִית הַהִין. וְלוֹג. וַחֲצִי לוֹג. וּרְבִיעִית. וְלָמָּה הָיוּ חֲצִי הַהִין וּשְׁלִישִׁית הַהִין וּרְבִיעִית הַהִין. לִמְדִידַת הַנְּסָכִים שֶׁל זְבָחִים. וְלוֹג לִמְדִידַת שֶׁמֶן הַמְּנָחוֹת. וַחֲצִי לוֹג לִמְדִידַת שֶׁמֶן לְכָל נֵר מִנֵּרוֹת הַמְּנוֹרָה. וּרְבִיעִית לְחַלֵּק בָּהּ הַשֶּׁמֶן לַחֲבִיתִין:","וְאֵין לָנוּ דָּבָר לִמְדֹּד בּוֹ הִין וְלָמָּה הָיָה שָׁם. הוֹאִיל וְהָיָה בַּמִּקְדָּשׁ מִימֵי משֶׁה שֶׁמָּדַד בּוֹ שֶׁמֶן לְשֶׁמֶן הַמִּשְׁחָה. וּבַחֲצִי לוֹג שֶׁיִּהְיֶה בַּמִּקְדָּשׁ הָיוּ מוֹדְדִין מַיִם לְמֵי סוֹטָה וְשֶׁמֶן לְתוֹדָה. וּבָרְבִיעִית שֶׁהָיְתָה שָׁם הָיוּ מוֹדְדִין שֶׁמֶן לֶחֶם הַנָּזִיר. וּמַיִם לְטָהֳרַת מְצֹרָע. וְלֹא מִפְּנֵי מַעֲשִׂים אֵלּוּ נִתְקַדְּשׁוּ אֶלָּא מִפְּנֵי הַמְּלָאכוֹת שֶׁל מִקְדָּשׁ שֶׁאָמַרְנוּ:","כָּל הַמִּדּוֹת הָאֵלּוּ קֹדֶשׁ וּמִכְּלֵי הַשָּׁרֵת. אֶלָּא שֶׁמִּדּוֹת הַלַּח נִמְשְׁחוּ מִבִּפְנִים וּמִבַּחוּץ. וּכְלֵי הַיָּבֵשׁ לֹא נִמְשְׁחוּ אֶלָּא בִּפְנִים. לְפִיכָךְ בֵּירוּצֵי מִדּוֹת הַלַּח קֹדֶשׁ. וּבֵירוּצֵי מִדּוֹת הַיָּבֵשׁ חל:"],"Mishneh Torah, Virgin Maiden 3":["הַמּוֹצִיא שֵׁם רַע עַל בַּת יִשְׂרָאֵל וְנִמְצָא הַדָּבָר שֶׁקֶר לוֹקֶה שֶׁנֶּאֱמַר (דברים כב יח) \"וְיִסְּרוּ אֹתוֹ\". וְאַזְהָרָה שֶׁלּוֹ מִ(ויקרא יט טז) \"לֹּא תֵלֵךְ רָכִיל בְּעַמֶּיךָ\". וְנוֹתֵן לְאָבִיהָ מִשְׁקַל מֵאָה סְלָעִים כֶּסֶף מְזֻקָּק. וְאִם הָיְתָה יְתוֹמָה הֲרֵי הֵם שֶׁל עַצְמָהּ:","וְהַמּוֹצִיא שֵׁם רַע עַל הַקְּטַנָּה אוֹ עַל הַבּוֹגֶרֶת פָּטוּר מִן הַקְּנָס וּמִן הַמַּלְקוֹת. וְאֵינוֹ חַיָּב עַד שֶׁיּוֹצִיא עַל הַנַּעֲרָה שֶׁנֶּאֱמַר (דברים כב טו) \"וְהוֹצִיאוּ אֶת בְּתוּלֵי הַנַּעֲרָה\" נַעֲרָה מָלֵא דִּבֵּר הַכָּתוּב:","אֵין דָּנִין דִּין זֶה אֶלָּא בִּפְנֵי הַבַּיִת וּבֵית דִּין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה. מִפְּנֵי שֶׁיֵּשׁ בְּדִין מוֹצִיא שֵׁם רַע דִּינֵי נְפָשׁוֹת. שֶׁאִם נִמְצָא הַדָּבָר כְּמוֹ שֶׁנֶּאֱמַר הֲרֵי זוֹ נֶהֱרֶגֶת. אֲבָל הָאוֹנֵס וְהַמְפַתֶּה דָּנִין בָּהֶן בְּכָל זְמַן בִּשְׁלֹשָׁה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת סַנְהֶדְרִין:","וּמִצְוַת עֲשֵׂה שֶׁל תּוֹרָה שֶׁתֵּשֵׁב אֵשֶׁת מוֹצִיא שֵׁם רַע תַּחְתָּיו לְעוֹלָם שֶׁנֶּאֱמַר (דברים כב יט) \"וְלוֹ תִהְיֶה לְאִשָּׁה\" אֲפִלּוּ עִוֶּרֶת אוֹ מֻכַּת שְׁחִין. וְאִם גֵּרְשָׁהּ עָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כב יט) \"לֹא יוּכַל לְשַׁלְּחָהּ כָּל יָמָיו\". וְכוֹפִין אוֹתוֹ וּמַחֲזִיר וְאֵינוֹ לוֹקֶה כְּמוֹ שֶׁבֵּאַרְנוּ בְּאוֹנֵס. וְאִם קִדֵּם אֶחָד וְקִדְּשָׁהּ אוֹ שֶׁמֵּתָה אוֹ שֶׁהָיָה כֹּהֵן שֶׁאָסוּר בִּגְרוּשָׁה הֲרֵי זֶה לוֹקֶה עַל גֵּרוּשֶׁיהָ:","נִמְצָא בָּהּ דְּבַר זִמָּה. אוֹ שֶׁנִּמְצֵאת אֲסוּרָה עָלָיו מֵחַיָּבֵי לָאוִין אוֹ מֵחַיָּבֵי עֲשֵׂה וַאֲפִלּוּ שְׁנִיָּה הֲרֵי זֶה יְגָרְשֶׁנָּה בְּגֵט שֶׁנֶּאֱמַר (דברים כב יט) \"וְלוֹ תִהְיֶה לְאִשָּׁה\" אִשָּׁה הָרְאוּיָה לוֹ. וְלָמָּה לֹא יָבֹא עֲשֵׂה וְיִדְחֶה אֶת לֹא תַּעֲשֶׂה בֵּין בְּמוֹצִיא שֵׁם רַע בֵּין בְּאוֹנֵס וְיִשָּׂא זוֹ הָאֲסוּרָה לוֹ. שֶׁהֲרֵי אֶפְשָׁר שֶׁלֹּא תִּרְצֶה הִיא לֵישֵׁב וְנִמְצָא עֲשֵׂה וְלֹא תַּעֲשֶׂה קַיָּמִין:","כֵּיצַד הוֹצָאַת שֵׁם רַע. הוּא שֶׁיָּבוֹא לְבֵית דִּין וְיֹאמַר נַעֲרָה זוֹ בָּעַלְתִּי וְלֹא מָצָאתִי לָהּ בְּתוּלִים וּכְשֶׁבִּקַּשְׁתִּי עַל הַדָּבָר נוֹדַע לִי שֶׁזִּנְּתָה תַּחְתַּי אַחַר שֶׁאֵרַסְתִּיהָ וְאֵלּוּ הֵם עֵדַי שֶׁזִּנְּתָה בִּפְנֵיהֶם. וּבֵית דִּין שׁוֹמְעִין דִּבְרֵי הָעֵדִים וְחוֹקְרִין עֵדוּתָן. אִם נִמְצָא הַדָּבָר אֱמֶת נִסְקֶלֶת. וְאִם הֵבִיא הָאָב עֵדִים וְהוּזְמוּ הָעֵדִים שֶׁהֵבִיא הַבַּעַל וְנִמְצָא שֶׁהֵעִידוּ שֶׁקֶר יִסָּקְלוּ וְיִלְקֶה הוּא וְנוֹתֵן מֵאָה סְלָעִים. וְעַל זֶה נֶאֱמַר (דברים כב יז) \"וְאֵלֶּה בְּתוּלֵי בִתִּי\", אֵלּוּ הָעֵדִים שֶׁיָּזִימוּ עֵדֵי הַבַּעַל. חָזַר הַבַּעַל וְהֵבִיא עֵדִים אֲחֵרִים וְהֵזִימוּ עֵדֵי הָאָב הֲרֵי הַנַּעֲרָה וְעֵדֵי אָבִיהָ נִסְקָלִין. עַל זֶה נֶאֱמַר (דברים כב כ) \"וְאִם אֱמֶת הָיָה הַדָּבָר הַזֶּה\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁפָּרָשָׁה זוֹ יֵשׁ בָּהּ עֵדִים וְזוֹמְמִין וְזוֹמְמֵי זוֹמְמִין:","הוֹצִיא עָלֶיהָ שֵׁם רַע וְהִיא בּוֹגֶרֶת אַף עַל פִּי שֶׁהֵבִיא עֵדִים שֶׁזִּנְּתָה תַּחְתָּיו כְּשֶׁהָיְתָה נַעֲרָה הֲרֵי זֶה פָּטוּר מִן הַמַּלְקוֹת וּמִן הַקְּנָס. וְאִם נִמְצָא הַדָּבָר אֱמֶת הֲרֵי זוֹ תִּסָּקֵל אַף עַל פִּי שֶׁהִיא בּוֹגֶרֶת הוֹאִיל וּבְעֵת שֶׁזִּנְּתָה נַעֲרָה הָיְתָה:","כָּל נַעֲרָה שֶׁאֵין לָהּ קְנָס אִם נֶאֶנְסָה אוֹ נִתְפַּתְּתָה כָּךְ הַמּוֹצִיא עָלֶיהָ שֵׁם רַע פָּטוּר מִן הַמַּלְקוֹת וּמִן הַתַּשְׁלוּמִין. וְכֵן הַכּוּתִית שֶׁנִּתְגַּיְּרָה וְהַשִּׁפְחָה שֶׁנִּשְׁתַּחְרְרָה פְּחוּתָה מִבַּת שָׁלֹשׁ שָׁנִים אֲפִלּוּ הָיְתָה הוֹרָתָהּ שֶׁלֹּא בִּקְדֻשָּׁה וְלֵדָתָהּ בִּקְדֻשָּׁה הַמּוֹצִיא עָלֶיהָ שֵׁם רַע פָּטוּר מִן הַקְּנָס וּמִן הַמַּלְקוֹת שֶׁנֶּאֱמַר (דברים כב יט) \"כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל\" עַד שֶׁתִּהְיֶה הוֹרָתָהּ וְלֵדָתָהּ בִּקְדֻשָּׁה:","קִדֵּשׁ נַעֲרָה וְגֵרְשָׁהּ וְחָזַר וְקִדְּשָׁהּ וְהוֹצִיא עָלֶיהָ שֵׁם רַע וְהֵבִיא עֵדִים שֶׁזִּנְּתָה תַּחְתָּיו בַּקִּדּוּשִׁין הָרִאשׁוֹנִים וְנִמְצְאוּ זוֹמְמִים הֲרֵי זֶה פָּטוּר. וְכֵן אִם הָיְתָה יְבִמְתּוֹ שֶׁכָּנְסָהּ וְהוֹצִיא עָלֶיהָ שֵׁם רַע וְהֵבִיא עֵדִים שֶׁזִּנְּתָה תַּחַת קִדּוּשֵׁי אָחִיו וְנִמְצְאוּ זוֹמְמִים הֲרֵי זֶה פָּטוּר מִן הַמַּלְקוֹת וּמִן הַתַּשְׁלוּמִין. וְכָל הַפָּטוּר אִם רָצָה לְגָרֵשׁ יְגָרֵשׁ:","אֵינוֹ חַיָּב עַד שֶׁיִּבְעל אוֹתָהּ כְּדַרְכָּהּ וְיוֹצִיא שֵׁם רַע (עַל הַבְּעִילָה) כְּדַרְכָּהּ. בְּעָלָהּ שֶׁלֹּא כְּדַרְכָּהּ וְאָמַר לֹא מְצָאתִיהָ בְּתוּלָה פָּטוּר וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וְכֵן אִם אָמַר לֹא מְצָאתִיהָ בְּתוּלָה וְלֹא אָמַר שֶׁזִּנְּתָה תַּחְתַּי אוֹ שֶׁאָמַר זִנְּתָה תַּחְתַּי וְלֹא הֵבִיא עֵדִים אֶלָּא בָּאוּ מֵאֲלֵיהֶם הֲרֵי זֶה פָּטוּר אַף עַל פִּי שֶׁהָעֵדִים נֶהֱרָגִים אִם הוּזַמּוּ:","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (דברים כב יז) \"וּפָרְשׂוּ הַשִּׂמְלָה\" לְשׁוֹן כָּבוֹד שֶׁנּוֹשְׂאִין וְנוֹתְנִין בְּסִתְרֵי הַדָּבָר. וְכֵן זֶה שֶׁיֹּאמַר הָאָב (דברים כב יז) \"אֵלֶּה בְּתוּלֵי בִתִּי\" הֵן זוֹמְמֵי עֵדֵי הַבַּעַל. וְזֶה שֶׁנֶּאֱמַר (דברים כב כ) \"וְאִם אֱמֶת הָיָה הַדָּבָר\" תֵּהָרֵג כְּשֶׁזִּנְּתָה אַחַר הָאֵרוּסִין בְּעֵדִים שֶׁנֶּאֱמַר (דברים כב כא) \"לִזְנוֹת בֵּית אָבִיהָ\". אֲבָל קדֶם הָאֵרוּסִין כְּבָר אָמְרָה תּוֹרָה בָּהּ שֶׁהִיא פְּטוּרָה מִכְּלוּם וּבוֹעֲלָהּ חַיָּב בְּתַשְׁלוּמֵי מָמוֹן בִּלְבַד בֵּין פִּתָּה בֵּין אָנַס:"],"Mishneh Torah, Vows 8":["מִי שֶׁנָּדַר אוֹ נִשְׁבַּע וּפֵרֵשׁ בִּשְׁעַת נִדְרוֹ דָּבָר שֶׁנָּדַר אוֹ נִשְׁבַּע בִּגְלָלוֹ. הֲרֵי זֶה כְּמִי שֶׁתָּלָה נִדְרוֹ אוֹ שְׁבוּעָתוֹ בְּאוֹתוֹ דָּבָר. וְאִם לֹא נִתְקַיֵּם אוֹתוֹ דָּבָר שֶׁנִּשְׁבַּע בִּגְלָלוֹ הֲרֵי זֶה מֻתָּר:","כֵּיצַד. נָדַר אוֹ נִשְׁבַּע שֶׁאֵינִי נוֹשֵׂא אִשָּׁה פְּלוֹנִית שֶׁאָבִיהָ רַע. שֶׁאֵינִי נִכְנָס לְבַיִת זֶה שֶׁכֶּלֶב רַע בְּתוֹכוֹ. מֵתוּ אוֹ שֶׁעָשָׂה הָאָב תְּשׁוּבָה הֲרֵי זֶה מֻתָּר. שֶׁזֶּה כְּמִי שֶׁנָּדַר אוֹ נִשְׁבַּע וְאָמַר שֶׁלֹּא אֶשָּׂא פְּלוֹנִית וְלֹא אֶכָּנֵס לְבַיִת זֶה אֶלָּא אִם נִסְתַּלֵּק הַהֵזֶּק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֲבָל הַנּוֹדֵר אוֹ הַנִּשְׁבָּע שֶׁאֵינִי נוֹשֵׂא פְּלוֹנִית הַכְּעוּרָה וְנִמְצֵאת נָאָה. שְׁחוֹרָה וְנִמְצֵאת לְבָנָה. קְצָרָה וְנִמְצֵאת אֲרֻכָּה. קוֹנָם שֶׁאֵין אִשְׁתִּי נֶהֱנֵית לִי שֶׁגָּנְבָה אֶת כִּיסִי וְשֶׁהִכְּתָה אֶת בְּנִי וְנוֹדַע שֶׁלֹּא גָּנְבָה וְשֶׁלֹּא הִכְּתָה. הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁהוּא נֵדֶר טָעוּת וְהוּא בִּכְלַל נִדְרֵי שְׁגָגוֹת שֶׁהֵן מֻתָּרִין. וְאֵין זֶה כְּתוֹלֶה נִדְרוֹ בְּדָבָר וְלֹא נִתְקַיֵּם הַדָּבָר. שֶׁהֲרֵי הַסִּבָּה שֶׁבִּגְלָלָהּ נָדַר לֹא הָיְתָה מְצוּיָה וְטָעוּת הָיָה:","וְלֹא עוֹד אֶלָּא מִי שֶׁרָאָה אֲנָשִׁים מֵרָחוֹק אוֹכְלִים תְּאֵנִים שֶׁלּוֹ. וְאָמַר לָהֶן הֲרֵי הֵן עֲלֵיכֶם קָרְבָּן. כֵּיוָן שֶׁקָּרַב אֲלֵיהֶם וְהִבִּיט וַהֲרֵי הֵן אָבִיו וְאָחִיו הֲרֵי אֵלּוּ מֻתָּרִין. אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ הַסִּבָּה שֶׁהִדִּירָן בִּגְלָלָהּ הֲרֵי זֶה כְּמוֹ שֶׁפֵּרֵשׁ. שֶׁהַדָּבָר מוֹכִיחַ שֶׁלֹּא אָסַר עֲלֵיהֶם אֶלָּא שֶׁהָיָה בְּדַעְתּוֹ שֶׁהֵן זָרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁנָּדַר אוֹ נִשְׁבַּע וְנוֹלַד לוֹ דָּבָר שֶׁלֹּא הָיָה בְּלִבּוֹ בִּשְׁעַת הַשְּׁבוּעָה אוֹ בִּשְׁעַת הַנֵּדֶר הֲרֵי זֶה אָסוּר עַד שֶׁיִּשְׁאַל לְחָכָם וְיַתִּיר אֶת נִדְרוֹ. כֵּיצַד. אָסַר אֶת עַצְמוֹ בַּהֲנָיַת פְּלוֹנִי אוֹ שֶׁלֹּא יִכָּנֵס לְמָקוֹם פְּלוֹנִי. וְנַעֲשָׂה אוֹתוֹ הָאִישׁ סוֹפֵר וְאוֹתוֹ מָקוֹם בֵּית הַכְּנֶסֶת. אַף עַל פִּי שֶׁהוּא אוֹמֵר אִלּוּ הָיִיתִי יוֹדֵעַ שֶׁזֶּה נַעֲשָׂה סוֹפֵר וּבְמָקוֹם זֶה יֵעָשֶׂה בֵּית הַכְּנֶסֶת לֹא הָיִיתִי נוֹדֵר אוֹ נִשְׁבַּע הֲרֵי זֶה אָסוּר לֵהָנוֹת וּלְהִכָּנֵס עַד שֶׁיַּתִּיר נִדְרוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל נֵדֶר שֶׁהֻתַּר מִקְצָתוֹ הֻתַּר כֻּלּוֹ וְהוּא הַדִּין בִּשְׁבוּעָה. כֵּיצַד. רָאָה אֲנָשִׁים מֵרָחוֹק אוֹכְלִין פֵּרוֹתָיו וְאָמַר הֲרֵי הֵן עֲלֵיכֶם קָרְבָּן. וּכְשֶׁהִגִּיעַ אֲלֵיהֶם וְהִנֵּה הֵם אָבִיו וַאֲנָשִׁים זָרִים הוֹאִיל וְאָבִיו מֻתָּר כֻּלָּן מֻתָּרִין. וַאֲפִלּוּ אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ כֵּן הָיִיתִי אוֹמֵר פְּלוֹנִי וּפְלוֹנִי אֲסוּרִין וְאָבִי מֻתָּר הֲרֵי כֻּלָּן מֻתָּרִין. אֲבָל אִם אוֹמֵר כְּשֶׁהִגִּיעַ אֲלֵיהֶן אִלּוּ הָיִיתִי יוֹדֵעַ שֶׁאָבִי בֵּינֵיכֶם הָיִיתִי אוֹמֵר כֻּלְּכֶם אֲסוּרִין חוּץ מֵאָבִי הֲרֵי כֻּלָּן אֲסוּרִין חוּץ מֵאָבִיו. שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁלֹּא הִתִּיר מִקְצָת הַנֵּדֶר אֶלָּא כְּמוֹ שֶׁנָּדַר הָיָה נוֹדֵר וּמַתְנֶה עַל אָבִיו:","וְכֵן הָאוֹמֵר הַיַּיִן קָרְבָּן עָלַי מִפְּנֵי שֶׁהַיַּיִן רַע לִבְנֵי מֵעַיִם. וְאָמְרוּ לוֹ הֲרֵי הַמְיֻשָּׁן יָפֶה לִבְנֵי מֵעַיִם. אִם אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ לֹא הָיִיתִי נוֹדֵר. וַאֲפִלּוּ אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ הָיִיתִי אוֹמֵר הֶחָדָשׁ אָסוּר וְהַיָּשָׁן מֻתָּר. מֻתָּר בַּיָּשָׁן וּבֶחָדָשׁ. אֲבָל אִם אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ הָיִיתִי אוֹמֵר כָּל הַיֵּינוֹת אֲסוּרִין עָלַי חוּץ מִן הַמְיֻשָּׁן הֲרֵי זֶה מֻתָּר בַּמְיֻשָּׁן בִּלְבַד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל הַנּוֹדֵר אוֹ נִשְׁבָּע רוֹאִין דְּבָרִים שֶׁבִּגְלָלָן נִשְׁבַּע אוֹ נָדַר וּלְמֵדִין מֵהֶן לְאֵי זֶה נִתְכַּוֵּן וְהוֹלְכִין אַחַר הָעִנְיָן לֹא אַחַר כָּל מַשְׁמַע הַדִּבּוּר. כֵּיצַד. הָיָה טָעוּן מַשָּׂא שֶׁל צֶמֶר אוֹ שֶׁל פִּשְׁתִּים וְהִזִּיעַ וְהָיָה רֵיחוֹ קָשֶׁה וְנִשְׁבַּע אוֹ נָדַר שֶׁלֹּא יַעֲלֶה עָלָיו צֶמֶר אוֹ פִּשְׁתִּים לְעוֹלָם. הֲרֵי זֶה מֻתָּר לִלְבּשׁ בִּגְדֵי צֶמֶר אוֹ פִּשְׁתִּים וּלְכַסּוֹתָן. וְאֵינוֹ אָסוּר אֶלָּא לְהַפְשִׁילָן לַאֲחוֹרָיו. הָיָה לָבוּשׁ בִּגְדֵי צֶמֶר וְנִצְטַעֵר בִּלְבִישָׁתָן וְנִשְׁבַּע אוֹ נָדַר שֶׁלֹּא יַעֲלֶה עָלָיו צֶמֶר לְעוֹלָם אָסוּר לִלְבּשׁ וּמֻתָּר לִטְעֹן עָלָיו וּמֻתָּר לְהִתְכַּסּוֹת בְּגִזֵּי צֶמֶר. שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא לְבֶגֶד צֶמֶר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָיוּ מְבַקְּשִׁין מִמֶּנּוּ שֶׁיִּשָּׂא קְרוֹבָתוֹ וְהוּא מְמָאֵן וּפָצְרוּ בּוֹ וְנָדַר אוֹ נִשְׁבַּע שֶׁלֹּא תֶּהֱנֶה בּוֹ לְעוֹלָם. וְכֵן הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְנִשְׁבַּע אוֹ נָדַר שֶׁלֹּא תֶּהֱנֶה בּוֹ לְעוֹלָם. הֲרֵי אֵלּוּ מֻתָּרוֹת לֵהָנוֹת לוֹ. שֶׁאֵין כַּוָּנָתוֹ אֶלָּא לְשֵׁם אִישׁוּת:","וְכֵן הַקּוֹרֵא לַחֲבֵרוֹ שֶׁיִּסְעֹד אֶצְלוֹ וּמֵאֵן וְנִשְׁבַּע אוֹ נָדַר שֶׁלֹּא יִכָּנֵס לְבֵיתוֹ וְלֹא יִשְׁתֶּה לוֹ טִפַּת צוֹנֵן הֲרֵי זֶה מֻתָּר לְהִכָּנֵס לְבֵיתוֹ וְלִשְׁתּוֹת לוֹ צוֹנֵן. שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא שֶׁלֹּא יֹאכַל וְיִשְׁתֶּה עִמּוֹ בִּסְעֻדָּה זוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר לַחֲבֵרוֹ קוֹנָם לְבֵיתְךָ אֲנִי נִכְנָס וְשָׂדְךָ אֲנִי לוֹקֵחַ בֵּין בְּנֵדֶר בֵּין בִּשְׁבוּעָה וּמֵת אוֹ מְכָרָן לְאַחֵר הֲרֵי זֶה מֻתָּר לְהִכָּנֵס לַבַּיִת וְלִקַּח הַשָּׂדֶה מִן הַיּוֹרֵשׁ אוֹ מִן הַלּוֹקֵחַ. שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא כָּל זְמַן שֶׁהֵן בִּרְשׁוּתוֹ. אֲבָל אִם אָמַר לַבַּיִת הַזֶּה אֵינִי נִכְנָס וְשָׂדֶה זֶה אֵינִי לוֹקֵחַ וּמֵת אוֹ מְכָרָן לְאַחֵר הֲרֵי זֶה אָסוּר:","הָאוֹמֵר לַחֲבֵרוֹ הַשְׁאִילֵנִי פָּרָתְךָ אָמַר לוֹ אֵינָהּ פְּנוּיָה נִשְׁבַּע אוֹ נָדַר וְאָמַר קוֹנָם שָׂדִי אֵינִי חוֹרֵשׁ בָּהּ לְעוֹלָם. אִם הָיָה דַּרְכּוֹ לַחְרשׁ בְּיָדוֹ הוּא אָסוּר וְכָל אָדָם מֻתָּרִין לַחְרשׁ לוֹ בָּהּ. וְאִם אֵין דַּרְכּוֹ לַחְרשׁ בְּיָדוֹ הוּא וְכָל אָדָם אֲסוּרִין. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ:","מִי שֶׁנִּשְׁבַּע אוֹ נָדַר שֶׁיִּשָּׂא אִשָּׁה אוֹ שֶׁיִּקְנֶה בַּיִת אוֹ שֶׁיֵּצֵא בְּשַׁיָּרָא אוֹ יִפְרשׁ בַּיָּם אֵין מְחַיְּבִין אוֹתוֹ לִשָּׂא אִשָּׁה אוֹ לִקְנוֹת אוֹ לְצֵאת מִיָּד אֶלָּא עַד שֶׁיִּמָּצֵא דָּבָר הֶהָגוּן לוֹ. מַעֲשֶׂה בְּאִשָּׁה שֶׁנָּדְרָה שֶׁכָּל מִי שֶׁיִּתְבַּע אוֹתָהּ תִּנָּשֵׂא לוֹ וְקָפְצוּ עָלֶיהָ בְּנֵי אָדָם שֶׁאֵינָן הֲגוּנִין לָהּ. וְאָמְרוּ חֲכָמִים לֹא נִתְכַּוְּנָה זוֹ אֶלָּא לְכָל מִי שֶׁיִּתְבַּע אוֹתָהּ מִן הַהֲגוּנִין לָהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמַּדִּיר אֶת חֲבֵרוֹ אוֹ שֶׁנִּשְׁבַּע וְאָמַר לוֹ שֶׁתָּבוֹא וְתִטּל לְבָנֶיךָ כּוֹר אֶחָד חִטִּים אוֹ שְׁתֵּי חָבִיּוֹת שֶׁל יַיִן הֲרֵי זֶה יָכוֹל לְהַתִּיר נִדְרוֹ בְּלֹא שְׁאֵלָה לְחָכָם. וְיֹאמַר לוֹ כְּלוּם נִתְכַּוַּנְתָּ אֶלָּא לְכַבְּדֵנִי כְּבוֹדִי שֶׁלֹּא אֶטּל וּכְבָר הִגִּיעַ אֵלַי כָּבוֹד שֶׁנָּדַרְתָּ בִּשְׁבִילִי. וְכֵן הַנּוֹדֵר אוֹ הַנִּשְׁבָּע שֶׁאֵין אַתָּה נֶהֱנֶה לִי אִם אֵין אַתָּה נוֹתֵן לִבְנִי כּוֹר שֶׁל חִטִּים וּשְׁתֵּי חָבִיּוֹת שֶׁל יַיִן. הֲרֵי זֶה יָכוֹל לְהַתִּיר נִדְרוֹ שֶׁלֹּא בִּשְׁאֵלַת חָכָם וְיֹאמַר הֲרֵינִי כְּאִלּוּ נִתְקַבַּלְתִּי וְהִגִּיעוּ לְיָדִי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"]} as Record<string, string[]>;
